\label{chap:Challenge}

Throughout, \(k\) is a field and \(C\) a \emph{smooth curve} over \(k\): a geometrically
irreducible, smooth \(k\)-scheme of relative dimension one, proper over \(k\). We write
\(C \to \Spec k\) for its structure morphism. This chapter states the goal of the project — the
genus, the Jacobian, the Abel--Jacobi map, and the universal property that characterizes the
Jacobian as the Albanese variety of \(C\). It is the mathematical counterpart of the statement file
\texttt{AlgebraicJacobian/Challenge.lean}.

\emph{Provenance.} Each node below should carry a \verb!\source{...}! anchor to the reference it is
read from once that reference has been consulted; anchors are added during the rebuild, never
guessed.

\section{Genus}

\begin{definition}[Genus]
  \label{def:genus}
  \lean{AlgebraicGeometry.genus}
  \leanok
  \uses{def:moduleKSheaf, def:HModule}
  The \emph{genus} of a smooth proper curve \(C\) over \(k\) is
  \[
    g(C) \;=\; \dim_k H^1\!\bigl(C, \struct C\bigr),
  \]
  the \(k\)-dimension of the first cohomology group of the structure sheaf, viewed as a sheaf
  of \(k\)-modules on the small Zariski site of \(C\) (Definition~\ref{def:moduleKSheaf}),
  with cohomology the \(\Ext\)-groups from the constant sheaf
  (Definition~\ref{def:HModule}).
\end{definition}

\section{The Jacobian as an abelian variety}

\begin{definition}[Jacobian]
  \label{def:jacobian}
  \lean{AlgebraicGeometry.Jacobian}
  The \emph{Jacobian} \(\Jac(C)\) of a smooth proper curve \(C\) over \(k\) is the identity
  component \(\Pic^0_{C/k}\) of the relative Picard scheme of \(C\) over \(k\): the \(k\)-scheme
  representing (the fppf-sheafification of) the functor of degree-zero line bundles on \(C\).
\end{definition}

\begin{proposition}[Group scheme structure]
  \label{prop:jacobian_grpobj}
  \uses{def:jacobian}
  \lean{AlgebraicGeometry.Jacobian.instGrpObj}
  \(\Jac(C)\) is a commutative group scheme over \(k\), with multiplication induced by the tensor
  product of line bundles.
\end{proposition}

\begin{theorem}[Smoothness of the Jacobian]
  \label{thm:jacobian_smooth}
  \uses{def:genus, def:jacobian}
  \lean{AlgebraicGeometry.Jacobian.smoothOfRelativeDimension_genus}
  \(\Jac(C)\) is smooth over \(k\) of relative dimension \(g(C)\).
\end{theorem}

\begin{theorem}[Properness of the Jacobian]
  \label{thm:jacobian_proper}
  \uses{def:jacobian}
  \lean{AlgebraicGeometry.Jacobian.instIsProper}
  \(\Jac(C)\) is proper over \(k\).
\end{theorem}

\begin{theorem}[Geometric irreducibility of the Jacobian]
  \label{thm:jacobian_geomirred}
  \uses{def:jacobian}
  \lean{AlgebraicGeometry.Jacobian.instGeometricallyIrreducible}
  \(\Jac(C)\) is geometrically irreducible over \(k\).
\end{theorem}

In particular \(\Jac(C)\) is an abelian variety over \(k\) of dimension \(g(C)\).

\section{The Abel--Jacobi map and the universal property}

\begin{definition}[Abel--Jacobi map]
  \label{def:ofCurve}
  \uses{def:jacobian}
  \lean{AlgebraicGeometry.Jacobian.ofCurve}
  For a \(k\)-rational point \(P : \Spec k \to C\), the \emph{Abel--Jacobi map}
  \(\varphi_P : C \to \Jac(C)\) sends a point \(Q\) to the class of the line bundle
  \(\struct C(Q - P)\).
\end{definition}

\begin{lemma}[Base point maps to the origin]
  \label{lem:comp_ofCurve}
  \uses{def:ofCurve, prop:jacobian_grpobj}
  \lean{AlgebraicGeometry.Jacobian.comp_ofCurve}
  The Abel--Jacobi map \(\varphi_P\) sends the base point \(P\) to the neutral element of
  \(\Jac(C)\): \(\varphi_P \circ P = 0\).
\end{lemma}

\begin{theorem}[Universal property of the Jacobian]
  \label{thm:exists_unique_ofCurve_comp}
  \uses{def:ofCurve, lem:comp_ofCurve, prop:jacobian_grpobj}
  \lean{AlgebraicGeometry.Jacobian.exists_unique_ofCurve_comp}
  \(\Jac(C)\) is the Albanese variety of \(C\): for every abelian variety \(A\) over \(k\) and every
  morphism \(f : C \to A\) with \(f \circ P = 0\), there is a unique homomorphism of group schemes
  \(g : \Jac(C) \to A\) such that \(f = g \circ \varphi_P\).
\end{theorem}

\label{chap:BaseChange}

Beyond existence and the universal property, the Jacobian is \emph{canonical}: it is functorial in
the curve and commutes with extension of the base field. This chapter states those properties. As
before, \(k\) is a field and curves are smooth, proper, geometrically irreducible of relative
dimension one.

\section{Functoriality}

\begin{definition}[Category of curves]
  \label{def:Curve}
  \lean{AlgebraicGeometry.Curve}
  Let \(\mathrm{Curve}(k)\) denote the category whose objects are smooth proper geometrically
  irreducible curves over \(k\) and whose morphisms are morphisms of \(k\)-schemes.
\end{definition}

\begin{definition}[Jacobian functor]
  \label{def:jacobian_functor}
  \uses{def:Curve, def:jacobian, prop:jacobian_grpobj}
  \lean{AlgebraicGeometry.Jacobian.functor}
  The Jacobian is a contravariant functor
  \[
    \Jac : \mathrm{Curve}(k)^{\op} \longrightarrow \mathrm{Grp}\bigl(\Over(\Spec k)\bigr),
  \]
  sending a curve to its Jacobian group scheme and a morphism of curves to the induced pullback of
  line bundles. In particular an isomorphism of curves induces an isomorphism of Jacobian group
  schemes.
\end{definition}

\section{Base change of fields}

Fix a field extension \(k \to L\). Base change along it is the functor
\(\,\cdot\,_L = (\,\cdot\,) \times_{\Spec k} \Spec L : \Over(\Spec k) \to \Over(\Spec L)\), which
preserves properness, geometric irreducibility, and smoothness of relative dimension one.

\begin{definition}[Base change of schemes]
  \label{def:baseChange}
  \lean{AlgebraicGeometry.baseChange}
  \leanok
  For a field extension \(k \to L\), base change is the functor
  \(X \mapsto X \times_{\Spec k} \Spec L\) from \(k\)-schemes to \(L\)-schemes.
\end{definition}

\begin{theorem}[Jacobians commute with base change]
  \label{thm:baseChangeIso}
  \uses{def:jacobian_functor, def:baseChange}
  \lean{AlgebraicGeometry.Jacobian.baseChangeIso}
  For every field extension \(k \to L\) and every curve \(C\) over \(k\) there is a canonical
  isomorphism of group schemes over \(L\)
  \[
    \Jac(C)_L \;\cong\; \Jac(C_L).
  \]
\end{theorem}

\begin{proposition}[Identity coherence]
  \label{thm:baseChangeIso_id}
  \uses{thm:baseChangeIso}
  \lean{AlgebraicGeometry.Jacobian.baseChangeIso_id}
  The base-change isomorphism for the trivial extension \(k \to k\) is the identity, compatibly with
  the identification \(C_k \cong C\).
\end{proposition}

\begin{proposition}[Cocycle coherence]
  \label{thm:baseChangeIso_comp}
  \uses{thm:baseChangeIso}
  \lean{AlgebraicGeometry.Jacobian.baseChangeIso_comp}
  For a tower \(k \to L \to M\) the base-change isomorphisms compose: the isomorphism for \(k \to M\)
  agrees with base-changing the isomorphism for \(k \to L\) along \(L \to M\) and then applying the
  isomorphism for \(L \to M\), compatibly with the identification \((C_L)_M \cong C_M\).
\end{proposition}

\begin{proposition}[Compatibility with the Abel--Jacobi map]
  \label{thm:baseChange_ofCurve}
  \uses{thm:baseChangeIso, def:ofCurve}
  \lean{AlgebraicGeometry.Jacobian.baseChange_ofCurve}
  Base change carries the Abel--Jacobi map of \((C, P)\) to the Abel--Jacobi map of \((C_L, P_L)\):
  under \(\Jac(C)_L \cong \Jac(C_L)\), the base change of \(\varphi_P\) is \(\varphi_{P_L}\).
\end{proposition}

\label{chap:Curves}

Throughout this chapter \(k\) is a field. As in Chapter~\ref{chap:Challenge}, a \emph{smooth
curve} over \(k\) is a \(k\)-scheme which is smooth of relative dimension one, proper, and
geometrically irreducible over \(k\). This chapter provides the geometric substrate for the
genus: smooth schemes over a field are reduced, so a smooth curve is geometrically integral;
a proper geometrically integral scheme over a field has no global functions besides the
constants; the projective line carries two affine charts with polynomial section rings and
Laurent-polynomial overlap; the section rings of the standard smooth charts of a curve are
Dedekind domains, so the local rings of the curve are valuation rings and its
specialization order has height one; a rational function transcendental over \(k\) therefore
spreads out to a locally quasi-finite morphism \(C \to \PP^1\); and Zariski's main theorem
upgrades it to a finite one.

\section{Smooth algebras over a domain are reduced}

\begin{lemma}[Unramified flat algebras over a domain are reduced]
  \label{lem:unramified_flat_reduced}
  \lean{Algebra.FormallyUnramified.isReduced_of_isDomain}
  \leanok
  Let \(B\) be an integral domain and let \(S\) be a commutative \(B\)-algebra which is
  formally unramified, essentially of finite type, and flat over \(B\). Then \(S\) is reduced.
\end{lemma}
\begin{proof}
  \leanok
  Let \(K = \Frac B\) be the fraction field. The \(K\)-algebra \(K \otimes_B S\) is again
  formally unramified and essentially of finite type, both properties being stable under base
  change, and a formally unramified, essentially of finite type algebra over a field is
  reduced. It therefore suffices to embed \(S\) into \(K \otimes_B S\). The canonical map
  \(s \mapsto 1 \otimes s\) is, up to the isomorphism \(S \cong B \otimes_B S\), obtained from
  the injection \(B \hookrightarrow K\) by tensoring with \(S\); since \(S\) is flat over
  \(B\), it is injective. A subring of a reduced ring is reduced.
\end{proof}

\begin{lemma}[\'Etale algebras over a domain are reduced]
  \label{lem:etale_reduced_domain}
  \lean{Algebra.Etale.isReduced_of_isDomain}
  \leanok
  An \'etale algebra over an integral domain is reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:unramified_flat_reduced}
  An \'etale algebra is formally unramified and of finite presentation, in particular
  essentially of finite type, and it is flat. Apply \ref{lem:unramified_flat_reduced}.
\end{proof}

\begin{lemma}[Standard smooth homomorphisms out of a domain]
  \label{lem:standard_smooth_reduced_ringhom}
  \lean{RingHom.IsStandardSmooth.isReduced_of_isDomain}
  \leanok
  Let \(B\) be an integral domain and let \(B \to S\) be a standard smooth ring homomorphism,
  that is, one admitting a presentation \(S = B[x_1,\dots,x_n]/(f_1,\dots,f_c)\) in which the
  Jacobian matrix \((\partial f_u/\partial x_v)_{u,v \le c}\) has invertible determinant in
  \(S\). Then \(S\) is reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:etale_reduced_domain}
  By the structure theorem for standard smooth algebras, \(S\) is \'etale over a polynomial
  ring over the base: there are \(m\) and a factorization
  \(B \to B[x_1,\dots,x_m] \to S\) with the second map \'etale. A polynomial ring over an
  integral domain is an integral domain, so \ref{lem:etale_reduced_domain} applies.
\end{proof}

\begin{lemma}[Standard smooth algebras over a domain]
  \label{lem:standard_smooth_reduced}
  \lean{Algebra.IsStandardSmooth.isReduced_of_isDomain}
  \leanok
  A standard smooth algebra over an integral domain is reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:standard_smooth_reduced_ringhom}
  The structure homomorphism is a standard smooth ring homomorphism out of a domain; apply
  \ref{lem:standard_smooth_reduced_ringhom}.
\end{proof}

\begin{theorem}[Smooth schemes over a field are reduced]
  \label{thm:smooth_reduced_field}
  \lean{AlgebraicGeometry.Smooth.isReduced_of_field}
  \leanok
  Let \(K\) be a field and let \(X\) be a scheme which is smooth over \(\Spec K\). Then \(X\)
  is reduced.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:standard_smooth_reduced_ringhom}
  A smooth morphism is, locally on the source and the target, standard smooth: every point
  \(x \in X\) has an affine open neighbourhood \(V\), mapping into an affine open \(U\) of the
  base, such that the induced ring homomorphism \(\Gamma(U) \to \Gamma(V)\) is standard
  smooth. Since \(\Spec K\) has a single point and \(U\) is a nonempty open subset containing
  the image of \(x\), we have \(U = \Spec K\), and \(\Gamma(U) \cong K\) is a field, in
  particular a domain. By \ref{lem:standard_smooth_reduced_ringhom} the ring \(\Gamma(V)\) is
  reduced, hence the affine scheme \(V\) is reduced. The opens \(V\) cover \(X\), and a scheme
  covered by reduced open subschemes is reduced.
\end{proof}

\begin{theorem}[Smooth morphisms are geometrically reduced]
  \label{thm:smooth_geometrically_reduced}
  \lean{AlgebraicGeometry.Smooth.geometricallyReduced}
  \leanok
  A smooth morphism of schemes \(f : X \to Y\) is geometrically reduced: for every field \(K\)
  and every morphism \(\Spec K \to Y\), the base change \(X \times_Y \Spec K\) is a reduced
  scheme.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:smooth_reduced_field}
  Smoothness is stable under base change, so the projection
  \(X \times_Y \Spec K \to \Spec K\) is smooth; apply \ref{thm:smooth_reduced_field}.
\end{proof}

\begin{lemma}[Smooth of relative dimension one implies smooth]
  \label{lem:smooth_of_relDim_one}
  \lean{AlgebraicGeometry.Smooth.of_smoothOfRelativeDimension_one}
  \leanok
  A morphism of schemes which is smooth of relative dimension one is smooth.
\end{lemma}
\begin{proof}
  \leanok
  A morphism smooth of some relative dimension is smooth.
\end{proof}

\begin{lemma}[Smooth of a relative dimension implies geometrically reduced]
  \label{lem:relDim_geometrically_reduced}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.geometricallyReduced}
  \leanok
  For every \(n\), a morphism of schemes which is smooth of relative dimension \(n\) is
  geometrically reduced.
\end{lemma}
\begin{proof}
  \leanok
  \uses{thm:smooth_geometrically_reduced}
  Such a morphism is smooth; apply \ref{thm:smooth_geometrically_reduced}.
\end{proof}

\begin{theorem}[Smooth and geometrically irreducible implies geometrically integral]
  \label{thm:smooth_geometrically_integral}
  \lean{AlgebraicGeometry.Smooth.geometricallyIntegral}
  \leanok
  A smooth, geometrically irreducible morphism of schemes is geometrically integral: every
  base change to the spectrum of a field is an integral scheme.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:smooth_geometrically_reduced}
  Every base change to the spectrum of a field is reduced
  (\ref{thm:smooth_geometrically_reduced}) and irreducible (geometric irreducibility), and a
  reduced scheme with irreducible --- in particular nonempty --- underlying space is integral.
\end{proof}

\begin{theorem}[Relative-dimension form]
  \label{thm:relDim_geometrically_integral}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.geometricallyIntegral}
  \leanok
  For every \(n\), a geometrically irreducible morphism of schemes which is smooth of relative
  dimension \(n\) is geometrically integral.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:smooth_geometrically_integral}
  Such a morphism is smooth; apply \ref{thm:smooth_geometrically_integral}.
\end{proof}

\section{Schemes over a field: the topological substrate}

In this section \(X\) is a scheme over \(k\), that is, a scheme equipped with a structure
morphism \(X \to \Spec k\).

\begin{lemma}[Irreducibility]
  \label{lem:irreducible_of_geomirred}
  \lean{AlgebraicGeometry.irreducibleSpace_left_of_geometricallyIrreducible}
  \leanok
  If \(X\) is geometrically irreducible over \(k\), then the underlying topological space of
  \(X\) is irreducible; in particular \(X\) is nonempty.
\end{lemma}
\begin{proof}
  \leanok
  Geometric irreducibility applied to the trivial extension \(k \to k\) says that
  \(X \times_{\Spec k} \Spec k \cong X\) is irreducible.
\end{proof}

\begin{lemma}[Quasi-compactness]
  \label{lem:curve_compact}
  \lean{AlgebraicGeometry.compactSpace_left_of_quasiCompact}
  \leanok
  If \(X\) is quasi-compact over \(\Spec k\) (for instance proper), then the underlying
  topological space of \(X\) is quasi-compact.
\end{lemma}
\begin{proof}
  \leanok
  \(\Spec k\) is a one-point space, hence quasi-compact, and \(X\) is the preimage of it
  under a quasi-compact morphism.
\end{proof}

\begin{lemma}[Quasi-separatedness]
  \label{lem:curve_quasiseparated}
  \lean{AlgebraicGeometry.quasiSeparatedSpace_left_of_quasiSeparated}
  \leanok
  If \(X\) is quasi-separated over \(\Spec k\) (for instance proper), then the underlying
  topological space of \(X\) is quasi-separated: the intersection of any two quasi-compact
  opens is quasi-compact.
\end{lemma}
\begin{proof}
  \leanok
  \(\Spec k\) is affine, hence a quasi-separated scheme, and a scheme quasi-separated over a
  quasi-separated scheme is quasi-separated.
\end{proof}

\begin{proposition}[Integrality]
  \label{prop:curve_integral}
  \lean{AlgebraicGeometry.isIntegral_left_of_geometricallyReduced}
  \leanok
  If \(X\) is geometrically reduced and geometrically irreducible over \(k\), then \(X\) is an
  integral scheme.
\end{proposition}
\begin{proof}
  \leanok
  \uses{lem:irreducible_of_geomirred}
  Applying geometric reducedness to the trivial extension \(k \to k\) shows that \(X\) is
  reduced, and \(X\) is irreducible by \ref{lem:irreducible_of_geomirred}. A reduced scheme
  with irreducible underlying space is integral.
\end{proof}

\section{Global sections of a proper geometrically integral scheme}

\begin{lemma}[Pushout of a field extension along itself]
  \label{lem:pushout_field_epi}
  \lean{CommRingCat.epi_of_isPushout_of_isField}
  \leanok
  Let \(\varphi : A \to B\) and \(\psi : A \to C\) be homomorphisms of commutative rings with
  \(B\) nontrivial, and let \(D\), with coprojections \(\iota_B : B \to D\) and
  \(\iota_C : C \to D\), be a pushout of \((\varphi, \psi)\) (for instance
  \(D = B \otimes_A C\)). Assume that \(D\) is a field and that there is a ring isomorphism
  \(e : C \cong B\) with \(e \circ \psi = \varphi\). Then \(\varphi\) is an epimorphism in the
  category of commutative rings.
\end{lemma}
\begin{proof}
  \leanok
  Let \(\mu : D \to B\) be the homomorphism with \(\mu \circ \iota_B = \id_B\) and
  \(\mu \circ \iota_C = e\), given by the universal property of the pushout (the two maps
  agree on \(A\) because \(e \circ \psi = \varphi\)). Since \(D\) is a field and \(B\) is
  nontrivial, \(\mu\) is injective; it is surjective because \(\mu \circ \iota_B = \id_B\).
  Hence \(\mu\) is an isomorphism, and from
  \(\mu \circ \iota_B = \id_B = \mu \circ (\iota_C \circ e^{-1})\) we conclude
  \(\iota_B = \iota_C \circ e^{-1}\).

  Now let \(u, v : B \to W\) satisfy \(u \circ \varphi = v \circ \varphi\). Then
  \(u \circ \varphi = (v \circ e) \circ \psi\), so there is
  \(w : D \to W\) with \(w \circ \iota_B = u\) and \(w \circ \iota_C = v \circ e\). Therefore
  \[
    u = w \circ \iota_B = w \circ \iota_C \circ e^{-1} = v \circ e \circ e^{-1} = v,
  \]
  which proves that \(\varphi\) is an epimorphism.
\end{proof}

\begin{lemma}[Global sections form a field]
  \label{lem:sections_field}
  \lean{AlgebraicGeometry.isField_of_universallyClosed_of_isField}
  \leanok
  Let \(R\) be a commutative ring which is a field, let \(X\) be an integral scheme, and let
  \(f : X \to \Spec R\) be universally closed. Then \(\Gamma(X, \struct X)\) is a field.
\end{lemma}
\begin{proof}
  \leanok
  \(\Gamma(X, \struct X)\) is an integral domain because \(X\) is integral. Since \(f\) is
  universally closed, the induced ring homomorphism
  \(R \cong \Gamma(\Spec R, \struct{\Spec R}) \to \Gamma(X, \struct X)\) is an integral
  extension. A domain which is integral over a field is a field.
\end{proof}

\begin{theorem}[Constant functions on a proper geometrically integral scheme]
  \label{thm:sections_k}
  \lean{AlgebraicGeometry.bijective_appTop_of_isProper_of_geometricallyIntegral}
  \leanok
  Let \(K\) be a field and let \(X\) be a scheme, proper and geometrically integral over
  \(K\). Then the ring homomorphism
  \(\Gamma(\Spec K, \struct{\Spec K}) \to \Gamma(X, \struct X)\) induced by the structure
  morphism is bijective; identifying \(\Gamma(\Spec K, \struct{\Spec K}) = K\), this says
  \(\Gamma(X, \struct X) = K\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:pushout_field_epi, lem:sections_field, lem:curve_compact, lem:curve_quasiseparated}
  Write \(A = \Gamma(X, \struct X)\) and let \(\varphi : K \to A\) be the map in question.
  Applying geometric integrality to the trivial extension \(K \to K\) shows that \(X\) is
  integral; in particular \(X\) is nonempty and \(A\) is a nontrivial domain, so \(\varphi\),
  a ring homomorphism out of a field into a nontrivial ring, is injective. By
  \ref{lem:sections_field} (properness includes universal closedness), \(A\) is a field, and
  since \(f\) is proper, \(A\) is moreover a finite \(K\)-module. As a finite ring
  homomorphism is surjective as soon as it is an epimorphism of commutative rings, it remains
  to prove that \(\varphi\) is an epimorphism.

  Let \(q : \Spec A \to \Spec K\) be the morphism induced by \(\varphi\) and form the base
  change \(Y = X \times_{\Spec K} \Spec A\). Since \(A\) is a field, geometric integrality of
  \(f\) makes \(Y\) integral, and the projection \(Y \to \Spec A\) is universally closed as a
  base change of \(f\); hence \(D := \Gamma(Y, \struct Y)\) is a field by
  \ref{lem:sections_field}. On the other hand, \(X\) is quasi-compact and quasi-separated as
  a topological space (\ref{lem:curve_compact}, \ref{lem:curve_quasiseparated}), and \(q\) is
  flat because every vector space over \(K\) is flat; flat base change for global sections
  therefore exhibits the square of section rings
  \[
    \begin{array}{ccc}
      K & \longrightarrow & A \\
      \downarrow & & \downarrow \\
      A & \longrightarrow & D
    \end{array}
  \]
  (left column \(\varphi\), top row \(\varphi\) transported through the canonical isomorphism
  \(\Gamma(\Spec A, \struct{\Spec A}) \cong A\)) as a pushout square of commutative rings,
  \(D \cong A \otimes_K A\). Its pushout \(D\) is a field and its two legs are isomorphic
  copies of \(\varphi\), so \(\varphi\) is an epimorphism by \ref{lem:pushout_field_epi}.
\end{proof}

\begin{corollary}[Isomorphism form]
  \label{cor:sections_iso}
  \lean{AlgebraicGeometry.isIso_appTop_of_isProper_of_geometricallyIntegral}
  \leanok
  In the situation of \ref{thm:sections_k}, the induced map
  \(\Gamma(\Spec K, \struct{\Spec K}) \to \Gamma(X, \struct X)\) is an isomorphism of rings.
\end{corollary}
\begin{proof}
  \leanok
  \uses{thm:sections_k}
  A bijective ring homomorphism is an isomorphism.
\end{proof}

\begin{corollary}[Global sections of the curve]
  \label{cor:curve_sections}
  \lean{AlgebraicGeometry.isIso_hom_appTop_of_geometricallyReduced}
  \leanok
  Let \(C\) be a scheme over \(k\) which is proper, geometrically irreducible and
  geometrically reduced over \(k\). Then the structure morphism induces an isomorphism
  \(\Gamma(\Spec k, \struct{\Spec k}) \cong \Gamma(C, \struct C)\); that is,
  \(\Gamma(C, \struct C) = k\).
\end{corollary}
\begin{proof}
  \leanok
  \uses{cor:sections_iso}
  Every base change of \(C\) to the spectrum of a field is reduced and irreducible, hence
  integral; so \(C\) is geometrically integral over \(k\) and \ref{cor:sections_iso} applies.
\end{proof}

\begin{remark}[The smooth curve]
  \label{rem:curve_bundle}
  \uses{lem:smooth_of_relDim_one, lem:relDim_geometrically_reduced,
    thm:relDim_geometrically_integral, lem:irreducible_of_geomirred, lem:curve_compact,
    lem:curve_quasiseparated, prop:curve_integral, cor:curve_sections}
  \leanok
  Let \(C\) be a smooth curve over \(k\), i.e.\ proper, smooth of relative dimension one and
  geometrically irreducible over \(k\), as in Chapter~\ref{chap:Challenge}. Combining the
  above: \(C\) is smooth over \(k\) (\ref{lem:smooth_of_relDim_one}), geometrically reduced
  (\ref{lem:relDim_geometrically_reduced}) and geometrically integral
  (\ref{thm:relDim_geometrically_integral}); its underlying space is irreducible
  (\ref{lem:irreducible_of_geomirred}), quasi-compact (\ref{lem:curve_compact}) and
  quasi-separated (\ref{lem:curve_quasiseparated}); \(C\) is an integral scheme
  (\ref{prop:curve_integral}); and \(\Gamma(C, \struct C) = k\) (\ref{cor:curve_sections}).
\end{remark}

\section{The projective line and its charts}

Let \(A = k[X_0, X_1]\) be the polynomial ring in two variables, graded by total degree. For a
homogeneous element \(f \in A\) we write \(A_{(f)}\) for the degree-zero part of the
localization \(A_f\); its elements are fractions \(a/f^n\) with \(a\) homogeneous of degree
\(n \deg f\).

\begin{definition}[The projective line]
  \label{def:P1}
  \lean{AlgebraicGeometry.P1}
  \leanok
  The projective line over \(k\) is \(\PP^1 = \Proj A\), the Proj of the graded ring
  \(A = k[X_0, X_1]\).
\end{definition}

\begin{definition}[Degree zero]
  \label{def:P1_gradeZero}
  \lean{AlgebraicGeometry.P1.gradeZeroAlgEquiv}
  \leanok
  The inclusion of constants \(k \to A_0\) into the degree-zero part of \(A\) is an
  isomorphism of \(k\)-algebras.
\end{definition}
\begin{proof}
  \leanok
  It is injective because a nonzero constant polynomial is nonzero, and surjective because a
  polynomial which is homogeneous of degree zero is constant.
\end{proof}

\begin{definition}[Structure morphism]
  \label{def:P1_structureMap}
  \lean{AlgebraicGeometry.P1.structureMap}
  \uses{def:P1, def:P1_gradeZero}
  \leanok
  The structure morphism \(\PP^1 \to \Spec k\) is the canonical morphism
  \(\Proj A \to \Spec A_0\) followed by the isomorphism \(\Spec A_0 \cong \Spec k\) induced by
  \ref{def:P1_gradeZero}.
\end{definition}

\begin{theorem}[Properness of the projective line]
  \label{thm:P1_proper}
  \lean{AlgebraicGeometry.P1.isProper_structureMap}
  \uses{def:P1_structureMap}
  \leanok
  \(\PP^1\) is proper over \(k\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{def:P1_gradeZero}
  \(A\) is a finitely generated algebra over its degree-zero part \(A_0 = k\) (generated by
  \(X_0\) and \(X_1\)), and the Proj of a graded ring which is finitely generated over its
  degree-zero part is proper over the spectrum of the degree-zero part. Composing with the
  isomorphism \(\Spec A_0 \cong \Spec k\) preserves properness.
\end{proof}

\begin{definition}[The projective line as a scheme over \(k\)]
  \label{def:P1_asOver}
  \lean{AlgebraicGeometry.P1.asOver}
  \uses{def:P1_structureMap}
  \leanok
  \(\PP^1\), regarded as a scheme over \(k\) via the structure morphism of
  \ref{def:P1_structureMap}.
\end{definition}

\begin{definition}[The standard charts]
  \label{def:P1_chartOpen}
  \lean{AlgebraicGeometry.P1.chartOpen}
  \uses{def:P1}
  \leanok
  For \(i \in \{0,1\}\), the chart \(U_i = D_+(X_i) \subseteq \PP^1\) is the basic open locus
  where the homogeneous coordinate \(X_i\) does not vanish.
\end{definition}

\begin{lemma}[The charts are affine]
  \label{lem:P1_chartOpen_affine}
  \lean{AlgebraicGeometry.P1.isAffineOpen_chartOpen}
  \uses{def:P1_chartOpen}
  \leanok
  Each chart \(U_i\) is an affine open of \(\PP^1\).
\end{lemma}
\begin{proof}
  \leanok
  \(X_i\) is homogeneous of degree \(1 > 0\), and the basic open of \(\Proj\) at a homogeneous
  element of positive degree is affine.
\end{proof}

\begin{lemma}[The charts cover]
  \label{lem:P1_chartOpen_sup}
  \lean{AlgebraicGeometry.P1.chartOpen_sup}
  \uses{def:P1_chartOpen}
  \leanok
  \(U_0 \cup U_1 = \PP^1\).
\end{lemma}
\begin{proof}
  \leanok
  A point of \(\Proj A\) is a homogeneous prime ideal \(\mathfrak p\) of \(A\) not containing
  the irrelevant ideal \(A_+\). Every monomial of positive degree is divisible by \(X_0\) or
  by \(X_1\), so if both \(X_0 \in \mathfrak p\) and \(X_1 \in \mathfrak p\) then
  \(A_+ \subseteq \mathfrak p\), a contradiction. Hence every point avoids some \(X_i\), i.e.\
  lies in \(U_0 \cup U_1\).
\end{proof}

\begin{lemma}[The chart overlap]
  \label{lem:P1_chartOpen_inf}
  \lean{AlgebraicGeometry.P1.chartOpen_inf}
  \uses{def:P1_chartOpen}
  \leanok
  \(U_0 \cap U_1 = D_+(X_0 X_1)\).
\end{lemma}
\begin{proof}
  \leanok
  A homogeneous prime avoids the product \(X_0 X_1\) if and only if it avoids both factors.
\end{proof}

\begin{definition}[Affine models of the charts]
  \label{def:P1_chartIota}
  \lean{AlgebraicGeometry.P1.chartι}
  \uses{def:P1, def:P1_chartOpen}
  \leanok
  For \(i \in \{0,1\}\), the canonical morphism \(\Spec A_{(X_i)} \to \PP^1\) associated with
  the basic open at the degree-one element \(X_i\); it is an open immersion.
\end{definition}

\begin{lemma}[Image of the affine model]
  \label{lem:P1_chartIota_range}
  \lean{AlgebraicGeometry.P1.opensRange_chartι}
  \uses{def:P1_chartIota, def:P1_chartOpen}
  \leanok
  The image of \(\Spec A_{(X_i)} \to \PP^1\) is the chart \(U_i\); thus
  \(U_i \cong \Spec A_{(X_i)}\).
\end{lemma}
\begin{proof}
  \leanok
  This is the standard description of the basic opens of \(\Proj\): the homogeneous primes
  avoiding \(X_i\) correspond to the primes of the degree-zero localization \(A_{(X_i)}\).
\end{proof}

\begin{lemma}[The affine models lie over \(k\)]
  \label{lem:P1_chartIota_structureMap}
  \lean{AlgebraicGeometry.P1.chartι_structureMap}
  \uses{def:P1_chartIota, def:P1_structureMap}
  \leanok
  The composite \(\Spec A_{(X_i)} \to \PP^1 \to \Spec k\) is the morphism induced by the
  \(k\)-algebra structure of \(A_{(X_i)}\); that is, the affine models are morphisms of
  schemes over \(k\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{def:P1_gradeZero}
  The canonical morphism \(\Proj A \to \Spec A_0\), restricted to the affine chart, is induced
  by the ring homomorphism \(A_0 \to A_{(X_i)}\); composing with the isomorphism
  \(k \cong A_0\) of \ref{def:P1_gradeZero} gives the claim.
\end{proof}

\begin{definition}[Chart coordinates]
  \label{def:P1_chartCoord}
  \lean{AlgebraicGeometry.P1.chartCoord}
  \uses{def:P1}
  \leanok
  For \(i, j \in \{0,1\}\), the chart coordinate is the degree-zero fraction
  \(t_{ij} = X_j / X_i \in A_{(X_i)}\).
\end{definition}

\begin{definition}[Dehomogenization]
  \label{def:P1_dehomogenize}
  \lean{AlgebraicGeometry.P1.dehomogenize}
  \leanok
  For \(i \in \{0,1\}\), the dehomogenization at \(X_i\) is the \(k\)-algebra homomorphism
  \(\delta_i : k[X_0, X_1] \to k[t]\) with \(\delta_i(X_i) = 1\) and \(\delta_i(X_j) = t\) for
  \(j \neq i\).
\end{definition}

\begin{definition}[From polynomials to the chart ring]
  \label{def:P1_polyToAway}
  \lean{AlgebraicGeometry.P1.polyToAway}
  \uses{def:P1_chartCoord}
  \leanok
  For \(i, j \in \{0,1\}\), the \(k\)-algebra homomorphism \(k[t] \to A_{(X_i)}\) given by
  evaluation at the chart coordinate, \(t \mapsto t_{ij}\).
\end{definition}

\begin{definition}[From the chart ring to polynomials]
  \label{def:P1_awayToPoly}
  \lean{AlgebraicGeometry.P1.awayToPoly}
  \uses{def:P1_dehomogenize}
  \leanok
  For \(i \in \{0,1\}\), the \(k\)-algebra homomorphism \(A_{(X_i)} \to k[t]\) sending a
  degree-zero fraction \(a / X_i^n\) (with \(a\) homogeneous of degree \(n\)) to
  \(\delta_i(a)\).
\end{definition}
\begin{proof}
  \leanok
  Well-definedness: \(\delta_i(X_i) = 1\) is a unit of \(k[t]\), so \(\delta_i\) extends to
  the localization \(A_{X_i} \to k[t]\) by the universal property of localization; on the
  degree-zero subring its value on \(a / X_i^n\) is
  \(\delta_i(a)\,\delta_i(X_i)^{-n} = \delta_i(a)\).
\end{proof}

\begin{lemma}[One composite is the identity]
  \label{lem:P1_awayToPoly_polyToAway}
  \lean{AlgebraicGeometry.P1.awayToPoly_comp_polyToAway}
  \uses{def:P1_polyToAway, def:P1_awayToPoly}
  \leanok
  For \(i \neq j\), the composite \(k[t] \to A_{(X_i)} \to k[t]\) of
  \ref{def:P1_polyToAway} followed by \ref{def:P1_awayToPoly} is the identity.
\end{lemma}
\begin{proof}
  \leanok
  Both sides are \(k\)-algebra homomorphisms on \(k[t]\), so it suffices to check the
  generator: \(t \mapsto t_{ij} = X_j / X_i \mapsto \delta_i(X_j) = t\).
\end{proof}

\begin{lemma}[Monomial fractions are powers of the coordinate]
  \label{lem:P1_away_monomial}
  \lean{AlgebraicGeometry.P1.away_mk_prod_eq}
  \uses{def:P1_chartCoord}
  \leanok
  Let \(i \neq j\) and let \(e_0, e_1 \ge 0\) with \(e_0 + e_1 = a\). Then in \(A_{(X_i)}\)
  \[
    \frac{X_0^{e_0} X_1^{e_1}}{X_i^{a}} \;=\; t_{ij}^{\,e_j}.
  \]
\end{lemma}
\begin{proof}
  \leanok
  Since \(X_0^{e_0} X_1^{e_1} = X_i^{e_i} X_j^{e_j}\) and \(a = e_i + e_j\), the left-hand
  side is \(X_i^{e_i} X_j^{e_j} / X_i^{e_i + e_j} = X_j^{e_j} / X_i^{e_j}\), which is
  \(t_{ij}^{\,e_j}\).
\end{proof}

\begin{lemma}[Surjectivity onto the chart ring]
  \label{lem:P1_polyToAway_surjective}
  \lean{AlgebraicGeometry.P1.polyToAway_surjective}
  \uses{def:P1_polyToAway}
  \leanok
  For \(i \neq j\), the homomorphism \(k[t] \to A_{(X_i)}\) of \ref{def:P1_polyToAway} is
  surjective.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_away_monomial, def:P1_gradeZero}
  Since \(A\) is generated over \(A_0\) by the degree-one elements \(X_0, X_1\), the
  degree-zero localization \(A_{(X_i)}\) is spanned, as a module over \(A_0 = k\)
  (\ref{def:P1_gradeZero}), by the fractions \(m / X_i^a\) where \(m\) ranges over the
  monomials \(X_0^{e_0} X_1^{e_1}\) of degree \(a\). By \ref{lem:P1_away_monomial} each such
  fraction equals \(t_{ij}^{\,e_j}\), which is the image of \(t^{e_j}\). The image of a ring
  homomorphism is closed under addition and under multiplication by scalars from \(k\), so it
  is all of \(A_{(X_i)}\).
\end{proof}

\begin{lemma}[The other composite is the identity]
  \label{lem:P1_polyToAway_awayToPoly}
  \lean{AlgebraicGeometry.P1.polyToAway_comp_awayToPoly}
  \uses{def:P1_polyToAway, def:P1_awayToPoly}
  \leanok
  For \(i \neq j\), the composite \(A_{(X_i)} \to k[t] \to A_{(X_i)}\) of
  \ref{def:P1_awayToPoly} followed by \ref{def:P1_polyToAway} is the identity.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_polyToAway_surjective, lem:P1_awayToPoly_polyToAway}
  By \ref{lem:P1_polyToAway_surjective} every element of \(A_{(X_i)}\) is of the form
  \(p(t_{ij})\) with \(p \in k[t]\), and on such elements the claim follows from
  \ref{lem:P1_awayToPoly_polyToAway}.
\end{proof}

\begin{definition}[The chart identification]
  \label{def:P1_awayAlgEquiv}
  \lean{AlgebraicGeometry.P1.awayAlgEquiv}
  \uses{def:P1_polyToAway, def:P1_awayToPoly}
  \leanok
  For \(i \neq j\), the isomorphism of \(k\)-algebras
  \(\alpha_i : A_{(X_i)} \cong k[t]\) given by the mutually inverse homomorphisms of
  \ref{def:P1_awayToPoly} and \ref{def:P1_polyToAway}; the chart coordinate \(t_{ij}\)
  corresponds to \(t\).
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:P1_awayToPoly_polyToAway, lem:P1_polyToAway_awayToPoly}
  The two composites are the identity by \ref{lem:P1_awayToPoly_polyToAway} and
  \ref{lem:P1_polyToAway_awayToPoly}.
\end{proof}

\section{The chart overlap and Laurent polynomials}

Write \(k[T, T^{-1}]\) for the ring of Laurent polynomials over \(k\).

\begin{lemma}[Laurent span]
  \label{lem:laurent_span}
  \lean{LaurentPolynomial.exists_toLaurent_add_aeval}
  \leanok
  Every Laurent polynomial \(f \in R[T, T^{-1}]\) over a commutative (semi)ring \(R\) can be
  written as \(f = p(T) + q(T^{-1})\) with \(p, q \in R[t]\) ordinary polynomials.
\end{lemma}
\begin{proof}
  \leanok
  Split \(f\) into its monomials and collect those with nonnegative exponent into \(p\) and
  those with negative exponent into \(q\).
\end{proof}

\begin{definition}[Restriction from the left chart]
  \label{def:P1_awayToOverlapLeft}
  \lean{AlgebraicGeometry.P1.awayToOverlapLeft}
  \uses{def:P1}
  \leanok
  The canonical ring homomorphism \(\lambda : A_{(X_0)} \to A_{(X_0 X_1)}\), sending
  \(a / X_0^{\,n}\) to \(a X_1^{\,n} / (X_0 X_1)^{n}\).
\end{definition}

\begin{definition}[Restriction from the right chart]
  \label{def:P1_awayToOverlapRight}
  \lean{AlgebraicGeometry.P1.awayToOverlapRight}
  \uses{def:P1}
  \leanok
  The canonical ring homomorphism \(\rho : A_{(X_1)} \to A_{(X_0 X_1)}\), sending
  \(a / X_1^{\,n}\) to \(a X_0^{\,n} / (X_0 X_1)^{n}\).
\end{definition}

\begin{lemma}[The two coordinates are mutually inverse on the overlap]
  \label{lem:P1_coord_mul}
  \lean{AlgebraicGeometry.P1.awayToOverlap_mul_eq_one}
  \uses{def:P1_awayToOverlapLeft, def:P1_awayToOverlapRight, def:P1_chartCoord}
  \leanok
  In \(A_{(X_0 X_1)}\) one has \(\lambda(t_{01}) \cdot \rho(t_{10}) = 1\).
\end{lemma}
\begin{proof}
  \leanok
  Computing with the formulas of \ref{def:P1_awayToOverlapLeft} and
  \ref{def:P1_awayToOverlapRight}:
  \(\lambda(t_{01}) = X_1^2 / (X_0 X_1)\) and \(\rho(t_{10}) = X_0^2 / (X_0 X_1)\), so
  \[
    \lambda(t_{01}) \cdot \rho(t_{10})
      = \frac{X_0^2 X_1^2}{(X_0 X_1)^2} = 1 .
  \]
\end{proof}

\begin{lemma}[The overlap ring is a localization of the chart ring]
  \label{lem:P1_overlap_isLocalization}
  \lean{AlgebraicGeometry.P1.instAwayAwayNatMvPolynomialFinOfNatSubmoduleHomogeneousSubmoduleXChartCoordHMul}
  \uses{def:P1_awayToOverlapLeft, def:P1_chartCoord}
  \leanok
  The homomorphism \(\lambda\) of \ref{def:P1_awayToOverlapLeft} identifies
  \(A_{(X_0 X_1)}\) with the localization of \(A_{(X_0)}\) at the powers of the chart
  coordinate \(t_{01}\).
\end{lemma}
\begin{proof}
  \leanok
  This is a general property of degree-zero localizations: for homogeneous elements \(f, g\)
  of degree one, \(A_{(fg)}\) is the localization of \(A_{(f)}\) away from the degree-zero
  fraction \(g/f\). Here \(f = X_0\), \(g = X_1\) and \(g/f = t_{01}\).
\end{proof}

\begin{definition}[The overlap identification]
  \label{def:P1_overlapAlgEquiv}
  \lean{AlgebraicGeometry.P1.overlapAlgEquiv}
  \uses{def:P1}
  \leanok
  The isomorphism of \(k\)-algebras \(\theta : A_{(X_0 X_1)} \cong k[T, T^{-1}]\), with
  \(T\) the image of the coordinate \(t_{01}\).
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:P1_overlap_isLocalization, def:P1_awayAlgEquiv}
  By \ref{lem:P1_overlap_isLocalization}, \(A_{(X_0X_1)}\) is the localization of
  \(A_{(X_0)}\) at the powers of \(t_{01}\). The isomorphism
  \(\alpha_0 : A_{(X_0)} \cong k[t]\) of \ref{def:P1_awayAlgEquiv} carries \(t_{01}\) to
  \(t\), hence induces an isomorphism of the two localizations
  \(A_{(X_0X_1)} \cong k[t]_{t} = k[T, T^{-1}]\) (localizations at corresponding
  multiplicative sets are canonically isomorphic). The map is \(k\)-linear because
  \(\alpha_0\) is.
\end{proof}

\begin{lemma}[Left restriction is \(t \mapsto T\)]
  \label{lem:P1_overlap_res_left}
  \lean{AlgebraicGeometry.P1.overlapAlgEquiv_awayToOverlapLeft}
  \uses{def:P1_overlapAlgEquiv, def:P1_awayAlgEquiv, def:P1_awayToOverlapLeft}
  \leanok
  For every \(z \in A_{(X_0)}\) one has \(\theta(\lambda(z)) = p(T)\), where
  \(p = \alpha_0(z) \in k[t]\). In other words, under the identifications
  \(\alpha_0\) and \(\theta\), the restriction \(\lambda\) is the canonical inclusion
  \(k[t] \to k[T, T^{-1}]\), \(t \mapsto T\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_overlap_isLocalization}
  By construction (\ref{def:P1_overlapAlgEquiv}), \(\theta\) is the comparison of
  localizations induced by \(\alpha_0\); under such a comparison the localization map
  \(\lambda\) of \ref{lem:P1_overlap_isLocalization} corresponds to the localization map
  \(k[t] \to k[T, T^{-1}]\).
\end{proof}

\begin{lemma}[Right restriction is \(t \mapsto T^{-1}\)]
  \label{lem:P1_overlap_res_right}
  \lean{AlgebraicGeometry.P1.overlapAlgEquiv_awayToOverlapRight}
  \uses{def:P1_overlapAlgEquiv, def:P1_awayAlgEquiv, def:P1_awayToOverlapRight}
  \leanok
  For every \(z \in A_{(X_1)}\) one has \(\theta(\rho(z)) = q(T^{-1})\), where
  \(q = \alpha_1(z) \in k[t]\). In other words, under the identifications \(\alpha_1\) and
  \(\theta\), the restriction \(\rho\) is the homomorphism \(k[t] \to k[T, T^{-1}]\),
  \(t \mapsto T^{-1}\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_coord_mul, lem:P1_overlap_res_left, lem:P1_polyToAway_surjective}
  By \ref{lem:P1_overlap_res_left} the image of \(\lambda(t_{01})\) under \(\theta\) is
  \(T\), and by \ref{lem:P1_coord_mul} \(\lambda(t_{01})\,\rho(t_{10}) = 1\); applying
  \(\theta\) gives \(\theta(\rho(t_{10})) = T^{-1}\). By
  \ref{lem:P1_polyToAway_surjective} (for the indices \((1,0)\)) every \(z \in A_{(X_1)}\)
  is a polynomial in \(t_{10}\) with coefficients in \(k\); both sides of the claim are
  \(k\)-algebra homomorphisms in \(z\), and they agree on \(t_{10}\).
\end{proof}

\begin{lemma}[Laurent span on the overlap ring]
  \label{lem:P1_overlap_span}
  \lean{AlgebraicGeometry.P1.exists_awayToOverlap_add}
  \uses{def:P1_awayToOverlapLeft, def:P1_awayToOverlapRight}
  \leanok
  Every \(w \in A_{(X_0 X_1)}\) can be written as \(w = \lambda(z_0) + \rho(z_1)\) with
  \(z_0 \in A_{(X_0)}\) and \(z_1 \in A_{(X_1)}\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:laurent_span, def:P1_overlapAlgEquiv, lem:P1_overlap_res_left,
    lem:P1_overlap_res_right, def:P1_awayAlgEquiv}
  Write \(\theta(w) = p(T) + q(T^{-1})\) by \ref{lem:laurent_span} and set
  \(z_0 = \alpha_0^{-1}(p)\), \(z_1 = \alpha_1^{-1}(q)\). By
  \ref{lem:P1_overlap_res_left} and \ref{lem:P1_overlap_res_right},
  \(\theta(\lambda(z_0) + \rho(z_1)) = p(T) + q(T^{-1}) = \theta(w)\), and \(\theta\) is
  injective.
\end{proof}

\section{Section rings and the Laurent chart pair}

\begin{lemma}[The overlap is affine]
  \label{lem:P1_overlap_affine}
  \lean{AlgebraicGeometry.P1.isAffineOpen_overlap}
  \uses{lem:P1_chartOpen_inf}
  \leanok
  The chart overlap \(U_0 \cap U_1 = D_+(X_0 X_1)\) is an affine open of \(\PP^1\).
\end{lemma}
\begin{proof}
  \leanok
  \(X_0 X_1\) is homogeneous of degree \(2 > 0\), and the basic open of \(\Proj\) at a
  homogeneous element of positive degree is affine.
\end{proof}

\begin{definition}[Sections on the left chart]
  \label{def:P1_chartSectionsEquiv0}
  \lean{AlgebraicGeometry.P1.chartSectionsEquiv₀}
  \uses{def:P1_chartOpen, def:P1_chartIota, def:P1_awayAlgEquiv}
  \leanok
  The ring isomorphism \(\gamma_0 : \Gamma(\PP^1, U_0) \cong k[t]\): the canonical
  identification \(\Gamma(\PP^1, D_+(X_0)) \cong A_{(X_0)}\) (sections of \(\Proj\) over a
  basic open; equivalently, \(U_0 = \Spec A_{(X_0)}\) via \ref{def:P1_chartIota}) followed by
  \(\alpha_0\) of \ref{def:P1_awayAlgEquiv}.
\end{definition}

\begin{definition}[Sections on the right chart]
  \label{def:P1_chartSectionsEquiv1}
  \lean{AlgebraicGeometry.P1.chartSectionsEquiv₁}
  \uses{def:P1_chartOpen, def:P1_chartIota, def:P1_awayAlgEquiv}
  \leanok
  The ring isomorphism \(\gamma_1 : \Gamma(\PP^1, U_1) \cong k[t]\), defined as in
  \ref{def:P1_chartSectionsEquiv0} with the identification
  \(\Gamma(\PP^1, D_+(X_1)) \cong A_{(X_1)}\) followed by \(\alpha_1\).
\end{definition}

\begin{definition}[Sections on the overlap]
  \label{def:P1_overlapSectionsEquiv}
  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv}
  \uses{lem:P1_chartOpen_inf, def:P1_overlapAlgEquiv}
  \leanok
  The ring isomorphism \(\gamma_{01} : \Gamma(\PP^1, U_0 \cap U_1) \cong k[T, T^{-1}]\): the
  canonical identification \(\Gamma(\PP^1, D_+(X_0X_1)) \cong A_{(X_0X_1)}\) followed by
  \(\theta\) of \ref{def:P1_overlapAlgEquiv}.
\end{definition}

\begin{lemma}[Restriction of sections from the left chart]
  \label{lem:P1_res_left}
  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv_res_left}
  \uses{def:P1_chartSectionsEquiv0, def:P1_overlapSectionsEquiv}
  \leanok
  For every section \(a \in \Gamma(\PP^1, U_0)\),
  \[
    \gamma_{01}\bigl(a|_{U_0 \cap U_1}\bigr) = p(T), \qquad p = \gamma_0(a);
  \]
  under the identifications, restriction from the left chart to the overlap is
  \(t \mapsto T\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_overlap_res_left}
  The identifications \(\Gamma(\PP^1, D_+(f)) \cong A_{(f)}\) are natural with respect to
  inclusions of basic opens: restriction of sections from \(D_+(X_0)\) to \(D_+(X_0X_1)\)
  corresponds to the ring homomorphism \(\lambda\). Conclude by
  \ref{lem:P1_overlap_res_left}.
\end{proof}

\begin{lemma}[Restriction of sections from the right chart]
  \label{lem:P1_res_right}
  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv_res_right}
  \uses{def:P1_chartSectionsEquiv1, def:P1_overlapSectionsEquiv}
  \leanok
  For every section \(b \in \Gamma(\PP^1, U_1)\),
  \[
    \gamma_{01}\bigl(b|_{U_0 \cap U_1}\bigr) = q(T^{-1}), \qquad q = \gamma_1(b);
  \]
  under the identifications, restriction from the right chart to the overlap is
  \(t \mapsto T^{-1}\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_overlap_res_right}
  As in \ref{lem:P1_res_left}, restriction of sections corresponds to \(\rho\); conclude by
  \ref{lem:P1_overlap_res_right}.
\end{proof}

\begin{definition}[Laurent chart pair]
  \label{def:LaurentChartPair}
  \lean{AlgebraicGeometry.LaurentChartPair}
  \uses{def:P1}
  \leanok
  A \emph{Laurent chart pair} on \(\PP^1\) consists of open subsets
  \(V_0, V_1, V_{01} \subseteq \PP^1\) with \(V_{01} \subseteq V_0\),
  \(V_{01} \subseteq V_1\) and \(V_0 \cap V_1 = V_{01}\), all three affine, covering the
  projective line (\(V_0 \cup V_1 = \PP^1\)), together with ring isomorphisms
  \[
    \Gamma_0 : \Gamma(\PP^1, V_0) \cong k[t], \quad
    \Gamma_1 : \Gamma(\PP^1, V_1) \cong k[t], \quad
    \Gamma_{01} : \Gamma(\PP^1, V_{01}) \cong k[T, T^{-1}],
  \]
  such that, under these identifications, restriction \(V_{01} \subseteq V_0\) is
  \(t \mapsto T\) and restriction \(V_{01} \subseteq V_1\) is \(t \mapsto T^{-1}\).
\end{definition}

\begin{theorem}[Laurent span for a chart pair]
  \label{thm:laurentChartPair_span}
  \lean{AlgebraicGeometry.LaurentChartPair.exists_res_add_res}
  \uses{def:LaurentChartPair}
  \leanok
  Let \((V_0, V_1, V_{01}, \Gamma_0, \Gamma_1, \Gamma_{01})\) be a Laurent chart pair on
  \(\PP^1\). Every section \(z \in \Gamma(\PP^1, V_{01})\) is the sum of a restriction from
  \(V_0\) and a restriction from \(V_1\): there are \(a \in \Gamma(\PP^1, V_0)\) and
  \(b \in \Gamma(\PP^1, V_1)\) with \(z = a|_{V_{01}} + b|_{V_{01}}\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:laurent_span}
  Write \(\Gamma_{01}(z) = p(T) + q(T^{-1})\) by \ref{lem:laurent_span} and set
  \(a = \Gamma_0^{-1}(p)\), \(b = \Gamma_1^{-1}(q)\). By the two restriction conditions,
  \(\Gamma_{01}(a|_{V_{01}} + b|_{V_{01}}) = p(T) + q(T^{-1}) = \Gamma_{01}(z)\), and
  \(\Gamma_{01}\) is injective.
\end{proof}

\begin{definition}[The canonical Laurent chart pair]
  \label{def:P1_laurentChartPair}
  \lean{AlgebraicGeometry.P1.laurentChartPair}
  \uses{def:LaurentChartPair, def:P1_chartOpen, def:P1_chartSectionsEquiv0,
    def:P1_chartSectionsEquiv1, def:P1_overlapSectionsEquiv}
  \leanok
  The Laurent chart pair on \(\PP^1\) given by the standard charts: \(V_0 = U_0\),
  \(V_1 = U_1\), \(V_{01} = D_+(X_0X_1)\), with the identifications \(\gamma_0, \gamma_1,
  \gamma_{01}\) of \ref{def:P1_chartSectionsEquiv0}--\ref{def:P1_overlapSectionsEquiv}.
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:P1_chartOpen_affine, lem:P1_chartOpen_sup, lem:P1_chartOpen_inf,
    lem:P1_overlap_affine, lem:P1_res_left, lem:P1_res_right}
  The overlap conditions and affineness are \ref{lem:P1_chartOpen_inf},
  \ref{lem:P1_chartOpen_affine} and \ref{lem:P1_overlap_affine}; the covering condition is
  \ref{lem:P1_chartOpen_sup}; the two restriction conditions are \ref{lem:P1_res_left} and
  \ref{lem:P1_res_right}.
\end{proof}

\section{Unramified finite-type algebras over Dedekind domains}

The results of this section are pure commutative algebra, stated in full generality. The
first theorem strengthens the classical statement that a domain which is unramified and
\emph{module-finite} over a Dedekind domain is Dedekind: module-finiteness is relaxed to
finite type. The point of the generalization is where incomparability of primes comes from
--- for module-finite algebras it follows from integrality (lying over/incomparability),
while here it follows from quasi-finiteness, which every unramified algebra essentially of
finite type enjoys.

\begin{theorem}[Unramified finite-type domains over a Dedekind domain, DVR form]
  \label{thm:unramified_finiteType_dedekind_dvr}
  \lean{IsDedekindDomainDvr.of_formallyUnramified_of_finiteType}
  \leanok
  Let \(A\) be a Dedekind domain and \(B\) an integral domain which is an \(A\)-algebra of
  finite type and formally unramified over \(A\). Then \(B\) is Noetherian, and the
  localization of \(B\) at every nonzero prime ideal is a discrete valuation ring.
\end{theorem}
\begin{proof}
  \leanok
  \(B\) is Noetherian as a finite-type algebra over the Noetherian ring \(A\) (Hilbert basis
  theorem). Let \(\mathfrak q\) be a nonzero prime of \(B\) and set
  \(\mathfrak p = \mathfrak q \cap A\). The localization \(B_{\mathfrak q}\) is a Noetherian
  local domain and not a field (its maximal ideal is nonzero because \(\mathfrak q\) is), so
  it suffices to show that its maximal ideal \(\mathfrak q B_{\mathfrak q}\) is principal.

  \emph{Step 1: \(\mathfrak p \neq 0\).} An algebra which is formally unramified and of
  finite type is quasi-finite, and over a quasi-finite algebra two comparable primes of
  \(B\) lying over the same prime of \(A\) coincide. If \(\mathfrak p\) were zero, the
  comparable primes \(0 \subseteq \mathfrak q\) of \(B\) would both contract to \(0\) in
  \(A\), forcing \(\mathfrak q = 0\), a contradiction. Since \(A\) is Dedekind, the nonzero
  prime \(\mathfrak p\) is maximal, and \(A_{\mathfrak p}\) is a discrete valuation ring; in
  particular \(\mathfrak p A_{\mathfrak p}\) is principal.

  \emph{Step 2: \(\mathfrak q\) is minimal over \(\mathfrak p B\).} The fiber ring
  \(B/\mathfrak p B\) is an algebra over the residue field \(A/\mathfrak p\) which is again
  formally unramified (base change); every module over a field is free, and an unramified
  algebra which is free as a module is module-finite. Hence \(B/\mathfrak p B\) is a finite
  module over the field \(A/\mathfrak p\), in particular an Artinian ring, so all of its
  primes are minimal; applying this to the image of \(\mathfrak q\) shows that
  \(\mathfrak q\) is a minimal prime over \(\mathfrak p B\).

  \emph{Step 3: \(\mathfrak q B_{\mathfrak q} = \mathfrak p B_{\mathfrak q}\).} Since
  \(\mathfrak p\) is maximal and \(B\) is unramified over \(A\), the extension
  \(\mathfrak p B\) is a radical ideal of \(B\) (the fiber ring \(B/\mathfrak p B\) is
  reduced, being unramified and essentially of finite type over a field). Localization
  commutes with radicals, so \(\mathfrak p B_{\mathfrak q}\) is a radical ideal of
  \(B_{\mathfrak q}\); and because \(\mathfrak q\) is minimal over \(\mathfrak p B\)
  (Step~2), the radical of \(\mathfrak p B_{\mathfrak q}\) is exactly the maximal ideal
  \(\mathfrak q B_{\mathfrak q}\). A radical ideal equals its own radical, so
  \(\mathfrak p B_{\mathfrak q} = \mathfrak q B_{\mathfrak q}\).

  \emph{Step 4: conclusion.} By Step~3 and Step~1, the maximal ideal
  \(\mathfrak q B_{\mathfrak q}\) is the extension of the principal ideal
  \(\mathfrak p A_{\mathfrak p} \subseteq A_{\mathfrak p}\) along
  \(A_{\mathfrak p} \to B_{\mathfrak q}\), hence principal. A Noetherian local domain which
  is not a field and whose maximal ideal is principal is a discrete valuation ring.
\end{proof}

\begin{corollary}[Unramified finite-type domains over a Dedekind domain]
  \label{cor:unramified_finiteType_dedekind}
  \lean{IsDedekindDomain.of_formallyUnramified_of_finiteType}
  \uses{thm:unramified_finiteType_dedekind_dvr}
  \leanok
  Let \(A\) be a Dedekind domain and \(B\) an integral domain which is an \(A\)-algebra of
  finite type and formally unramified over \(A\). Then \(B\) is a Dedekind domain.
\end{corollary}
\begin{proof}
  \leanok
  A Noetherian domain whose localizations at all nonzero primes are discrete valuation
  rings is a Dedekind domain; apply \ref{thm:unramified_finiteType_dedekind_dvr}.
\end{proof}

\begin{lemma}[The polynomial ring in one variable is a principal ideal ring]
  \label{lem:mvpoly_fin_one_pid}
  \lean{MvPolynomial.isPrincipalIdealRing_fin_one}
  \leanok
  Let \(k\) be a field. The polynomial ring over \(k\) on a one-element set of variables is
  a principal ideal ring.
\end{lemma}
\begin{proof}
  \leanok
  It is isomorphic as a ring to the ordinary one-variable polynomial ring \(k[t]\), which
  is a principal ideal domain (Euclidean division), and being a principal ideal ring
  transports along a surjective ring homomorphism.
\end{proof}

\begin{lemma}[The polynomial ring in one variable is Dedekind]
  \label{lem:mvpoly_fin_one_dedekind}
  \lean{MvPolynomial.isDedekindDomain_fin_one}
  \uses{lem:mvpoly_fin_one_pid}
  \leanok
  Let \(k\) be a field. The polynomial ring over \(k\) on a one-element set of variables is
  a Dedekind domain.
\end{lemma}
\begin{proof}
  \leanok
  A principal ideal domain is a Dedekind domain.
\end{proof}

\begin{theorem}[Structure theorem for standard smooth algebras]
  \label{thm:standard_smooth_etale_structure}
  \lean{Algebra.IsStandardSmoothOfRelativeDimension.exists_etale_mvPolynomial}
  \mathlibok
  \source{stacks-project}
  \textit{Provided by Mathlib.}
  Let \(R\) be a commutative ring and \(S\) an \(R\)-algebra which is standard smooth of
  relative dimension \(n\): it admits a presentation
  \(S = R[x_1,\dots,x_m]/(f_1,\dots,f_c)\) with \(m - c = n\) in which the Jacobian matrix
  \((\partial f_u/\partial x_v)_{u,v \le c}\) has invertible determinant in \(S\). Then the
  structure map factors as
  \[
    R \longrightarrow R[y_1, \dots, y_n] \longrightarrow S
  \]
  with the second homomorphism \'etale. (For such a presentation the module of K\"ahler
  differentials \(\Omega_{S/R}\) is free on the images of
  \(dx_{c+1}, \dots, dx_m\); consequently \(S\) is unramified, hence \'etale, over the
  polynomial subring on those last \(n\) coordinates.)
\end{theorem}

\begin{theorem}[Standard smooth domains of relative dimension one are Dedekind]
  \label{thm:standard_smooth_dim_one_dedekind}
  \lean{Algebra.IsStandardSmoothOfRelativeDimension.isDedekindDomain}
  \uses{cor:unramified_finiteType_dedekind, lem:mvpoly_fin_one_dedekind,
    thm:standard_smooth_etale_structure}
  \leanok
  Let \(k\) be a field and \(B\) an integral domain which is a standard smooth
  \(k\)-algebra of relative dimension \(1\). Then \(B\) is a Dedekind domain.
\end{theorem}
\begin{proof}
  \leanok
  By the structure theorem \ref{thm:standard_smooth_etale_structure}, \(B\) is \'etale over
  a polynomial ring over \(k\) in one variable, which is a Dedekind domain
  (\ref{lem:mvpoly_fin_one_dedekind}). An \'etale algebra is formally unramified and of
  finite type, so \ref{cor:unramified_finiteType_dedekind} applies.
\end{proof}

\begin{theorem}[Standard smooth algebras of relative dimension one contain a transcendental]
  \label{thm:standard_smooth_transcendental}
  \lean{Algebra.IsStandardSmoothOfRelativeDimension.exists_transcendental}
  \uses{thm:standard_smooth_etale_structure}
  \leanok
  Let \(k\) be a field and \(B\) a nontrivial standard smooth \(k\)-algebra of relative
  dimension \(1\). Then \(B\) contains an element transcendental over \(k\).
\end{theorem}
\begin{proof}
  \leanok
  By the structure theorem \ref{thm:standard_smooth_etale_structure}, there is an \'etale
  homomorphism \(g : k[y] \to B\) from a one-variable polynomial ring; we claim that the
  \'etale coordinate \(t = g(y)\) is transcendental over \(k\). Note that no dimension
  theory enters: the argument is pure torsion-freeness.

  First, \(g\) is injective. An \'etale algebra is flat, and a flat module over a domain is
  torsion-free; so \(B\) is a torsion-free \(k[y]\)-module. If \(g(P) = g(Q)\) for
  \(P \neq Q\), then the nonzero element \(P - Q\) of the domain \(k[y]\) would satisfy
  \((P - Q) \cdot 1_B = g(P - Q) = 0\) with \(1_B \neq 0\) (\(B\) is nontrivial),
  contradicting torsion-freeness.

  Now suppose \(P(t) = 0\) for some nonzero \(P \in k[T]\). Evaluating \(P\) at \(t = g(y)\)
  is the image under \(g\) of the evaluation of \(P\) at \(y\), so \(g(P(y)) = 0\); by
  injectivity \(P(y) = 0\) in \(k[y]\), contradicting the transcendence of the variable
  \(y\) over \(k\). Hence \(t\) is transcendental over \(k\).
\end{proof}

\section{Stalks, specializations and finiteness on curve-like schemes}

A scheme covered by affine opens whose section rings are Dedekind domains behaves like a
smooth curve: its stalks are valuation rings, and its specialization order has height one.
This section proves the pointwise statements from the single hypothesis ``the point lies in
an affine open with Dedekind section ring'', derives the finiteness of proper closed
subsets, and discharges the hypotheses for a scheme smooth of relative dimension one over a
field.

\begin{theorem}[Stalks over Dedekind section rings are valuation rings]
  \label{thm:affine_dedekind_stalk_valuation}
  \lean{AlgebraicGeometry.IsAffineOpen.valuationRing_stalk}
  \leanok
  Let \(X\) be an integral scheme, \(V \subseteq X\) an affine open whose ring of sections
  \(\Gamma(X, V)\) is a Dedekind domain, and \(x \in V\). Then the stalk
  \(\struct{X,x}\) is a valuation ring.
\end{theorem}
\begin{proof}
  \leanok
  The stalk at \(x\) is the localization of \(\Gamma(X, V)\) at the prime ideal
  \(\mathfrak q\) corresponding to \(x\) under \(V \cong \Spec \Gamma(X, V)\). If
  \(\mathfrak q = 0\), its complement is the set of nonzero elements of the domain
  \(\Gamma(X, V)\), so the stalk is the fraction field --- a field, and every field is a
  valuation ring. If \(\mathfrak q \neq 0\), the localization of a Dedekind domain at a
  nonzero prime is a discrete valuation ring, and every discrete valuation ring is a
  valuation ring.
\end{proof}

\begin{theorem}[Height-one specialization over Dedekind section rings]
  \label{thm:affine_dedekind_specializes}
  \lean{AlgebraicGeometry.IsAffineOpen.specializes_eq_genericPoint_or_eq}
  \leanok
  Let \(X\) be a scheme whose underlying space is irreducible, \(V \subseteq X\) an affine
  open with \(\Gamma(X, V)\) a Dedekind domain, and \(x \in V\). Then every generalization
  of \(x\) is the generic point of \(X\) or \(x\) itself.
\end{theorem}
\begin{proof}
  \leanok
  Let \(y\) be a generalization of \(x\). Open sets are stable under generalization, so
  \(y \in V\). Under the open immersion \(\Spec \Gamma(X, V) \cong V \subseteq X\) the
  points \(x, y\) correspond to primes \(\mathfrak q_x, \mathfrak q_y\) of
  \(\Gamma(X, V)\) with \(\mathfrak q_y \subseteq \mathfrak q_x\) (specialization order of
  the spectrum). If \(\mathfrak q_y = 0\), then \(y\) is the image of the generic point of
  \(\Spec \Gamma(X, V)\), and the generic point of a nonempty open subscheme of an
  irreducible scheme is the generic point of the whole scheme. If \(\mathfrak q_y \neq 0\),
  then \(\mathfrak q_y\) is maximal (nonzero primes of a Dedekind domain are maximal), so
  \(\mathfrak q_y = \mathfrak q_x\) and \(y = x\).
\end{proof}

\begin{lemma}[Non-generic points are closed]
  \label{lem:height_one_closed_points}
  \lean{AlgebraicGeometry.Scheme.isClosed_singleton_of_forall_specializes}
  \leanok
  Let \(X\) be a scheme whose underlying space is irreducible and whose specialization
  order has height one: every generalization of any point is the generic point or the
  point itself. Then every point other than the generic point is closed.
\end{lemma}
\begin{proof}
  \leanok
  Let \(x \neq \xi\) (\(\xi\) the generic point) and let \(y\) be a point of the closure of
  \(\{x\}\), i.e.\ \(x\) is a generalization of \(y\). By hypothesis \(x = \xi\) or
  \(x = y\); the first is excluded, so \(y = x\). Hence the closure of \(\{x\}\) is
  \(\{x\}\).
\end{proof}

\begin{theorem}[Finiteness of proper closed subsets]
  \label{thm:height_one_finite_closed}
  \lean{AlgebraicGeometry.Scheme.finite_of_isClosed_of_notMem_genericPoint}
  \uses{lem:height_one_closed_points}
  \leanok
  Let \(X\) be a scheme whose underlying space is irreducible and Noetherian and whose
  specialization order has height one. Then every closed subset \(Z \subseteq X\) not
  containing the generic point is finite.
\end{theorem}
\begin{proof}
  \leanok
  A closed subset of a Noetherian space is a finite union of irreducible closed subsets.
  Schemes are sober, so each irreducible closed subset \(T\) in such a decomposition of
  \(Z\) is the closure of a unique point \(z \in T \subseteq Z\). Since the generic point
  does not lie in \(Z\), \(z\) is not the generic point, so \(\{z\}\) is closed by
  \ref{lem:height_one_closed_points} and \(T = \overline{\{z\}} = \{z\}\). Hence \(Z\) is a
  finite union of singletons.
\end{proof}

\begin{theorem}[Dedekind charts on a curve]
  \label{thm:relDim1_dedekind_charts}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.exists_isDedekindDomain_section}
  \uses{thm:standard_smooth_dim_one_dedekind}
  \leanok
  Let \(k\) be a field and \(X\) an integral scheme, smooth of relative dimension one over
  \(\Spec k\). Then every point of \(X\) lies in an affine open \(V\) whose ring of
  sections \(\Gamma(X, V)\) is a Dedekind domain.
\end{theorem}
\begin{proof}
  \leanok
  By definition of smoothness of relative dimension one, a point \(x\) has an affine open
  neighbourhood \(V\), mapping into an affine open \(U\) of \(\Spec k\), such that
  \(\Gamma(U) \to \Gamma(X, V)\) is standard smooth of relative dimension \(1\). The base
  \(\Spec k\) has a single point, and \(U\) is nonempty (it receives the image of \(x\)),
  so \(U = \Spec k\) and \(\Gamma(U) \cong k\). The ring \(\Gamma(X, V)\) is an integral
  domain, since \(V\) is a nonempty open of the integral scheme \(X\). Apply
  \ref{thm:standard_smooth_dim_one_dedekind}.
\end{proof}

\begin{theorem}[The stalks of a curve are valuation rings]
  \label{thm:relDim1_stalks_valuation}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.valuationRing_stalk}
  \uses{thm:relDim1_dedekind_charts, thm:affine_dedekind_stalk_valuation}
  \leanok
  Let \(k\) be a field and \(X\) an integral scheme, smooth of relative dimension one over
  \(\Spec k\). Then every stalk of the structure sheaf of \(X\) is a valuation ring.
\end{theorem}
\begin{proof}
  \leanok
  Combine \ref{thm:relDim1_dedekind_charts} with
  \ref{thm:affine_dedekind_stalk_valuation}.
\end{proof}

\begin{theorem}[Height-one specialization on a curve]
  \label{thm:relDim1_specializes}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.specializes_eq_genericPoint_or_eq}
  \uses{thm:relDim1_dedekind_charts, thm:affine_dedekind_specializes}
  \leanok
  Let \(k\) be a field and \(X\) an integral scheme, smooth of relative dimension one over
  \(\Spec k\). Then every generalization of a point of \(X\) is the generic point or the
  point itself.
\end{theorem}
\begin{proof}
  \leanok
  Combine \ref{thm:relDim1_dedekind_charts} with \ref{thm:affine_dedekind_specializes};
  the underlying space of an integral scheme is irreducible.
\end{proof}

\begin{theorem}[Existence of a transcendental rational function]
  \label{thm:relDim1_transcendental}
  \lean{AlgebraicGeometry.SmoothOfRelativeDimension.exists_transcendental_functionField}
  \uses{thm:standard_smooth_transcendental}
  \leanok
  Let \(k\) be a field and \(X\) an integral scheme, smooth of relative dimension one over
  \(\Spec k\). Regard the function field \(K(X)\) --- the stalk of the structure sheaf at
  the generic point --- as a ring under \(k\) via the structure morphism (global sections
  followed by the germ at the generic point). Then \(K(X)\) contains an element \(f_0\)
  transcendental over \(k\): no nonzero polynomial with coefficients in \(k\) vanishes at
  \(f_0\).
\end{theorem}
\begin{proof}
  \leanok
  Apply the definition of smoothness of relative dimension one at the generic point
  \(\xi\): there is an affine open \(V \ni \xi\) such that \(k \to \Gamma(X, V)\) is
  standard smooth of relative dimension \(1\) (the base affine open is all of \(\Spec k\),
  as in the proof of \ref{thm:relDim1_dedekind_charts}). The ring \(\Gamma(X, V)\) is
  nontrivial (\(V\) is nonempty), so by \ref{thm:standard_smooth_transcendental} it
  contains an element \(t\) transcendental over \(k\); let \(f_0\) be the germ of \(t\) at
  \(\xi\).

  On an integral scheme, the germ map \(\Gamma(X, V) \to K(X)\) at the generic point is
  injective. Let \(P \in k[T]\) be nonzero. Evaluating \(P\) at \(f_0\) through the
  structure map \(k \to K(X)\) is the germ of the evaluation of \(P\) at \(t\) through
  \(k \to \Gamma(X, V)\) (the structure map factors through \(\Gamma(X, V)\), and germs
  commute with polynomial evaluation). The latter is nonzero by transcendence of \(t\)
  (with coefficients moved into \(\Gamma(X, V)\) along the injective map \(k \to
  \Gamma(X, V)\)), so by injectivity of the germ map \(P(f_0) \neq 0\).
\end{proof}

\section{The curve-morphism dichotomy}
\label{sec:curve_morphism_dichotomy}

A morphism from a complete nonsingular curve to a curve is either constant or a finite
surjection. This section proves the bundle form of that dichotomy for the proper smooth
geometrically irreducible curve bundles of the challenge, together with its two general
ingredients: a morphism between proper bundles is itself proper, and a morphism whose
set-range is a single closed point factors through the spectrum of the residue field of
that point.

\begin{theorem}[Morphisms of proper bundles are proper]
  \label{thm:overHom_isProper}
  \lean{AlgebraicGeometry.isProper_left, AlgebraicGeometry.locallyOfFiniteType_left,
    AlgebraicGeometry.quasiCompact_left}
  \leanok
  Let \(S\) be a scheme and \(D, E\) schemes over \(S\), with \(D \to S\) proper and
  \(E \to S\) separated. Then every morphism \(h : D \to E\) over \(S\) is proper; in
  particular \(h\) is locally of finite type and quasi-compact.
\end{theorem}
\begin{proof}
  \leanok
  The composite of \(h\) with the structure morphism \(E \to S\) is the structure
  morphism \(D \to S\), which is proper. Properness cancels along separated morphisms:
  if \(g \circ f\) is proper and \(g\) is separated, then \(f\) is proper --- \(f\)
  factors as its graph \((\mathrm{id}, f)\), a closed immersion because it is a base
  change of the diagonal of the separated \(g\), followed by a projection which is a
  base change of the proper \(g \circ f\); closed immersions are proper, and properness
  is stable under base change and composition. Apply this with \(f = h\) and \(g\) the
  structure morphism of \(E\). Properness comprises finite type, so \(h\) is locally of
  finite type; and \(h\) is universally closed, hence quasi-compact (the preimage of a
  quasi-compact open under a universally closed morphism is quasi-compact).
\end{proof}

\begin{lemma}[The kernel comparison at a one-point range]
  \label{lem:ker_fromSpecResidueField_le}
  \lean{AlgebraicGeometry.Scheme.Hom.ker_fromSpecResidueField_le}
  \leanok
  Let \(f : X \to Y\) be a quasi-compact morphism of schemes with \(X\) reduced whose
  set-range is a single point \(y\): \(f(X) = \{y\}\). Then the kernel ideal sheaf of
  the canonical morphism \(\Spec \kappa(y) \to Y\) is contained in the kernel ideal
  sheaf of \(f\): for every open \(U \subseteq Y\), every section \(s \in \Gamma(Y, U)\)
  pulling back to \(0\) on \(\Spec \kappa(y)\) pulls back to \(0\) in
  \(\Gamma(X, f^{-1}U)\).
\end{lemma}
\begin{proof}
  \leanok
  Let \(s \in \Gamma(Y, U)\) pull back to \(0\) on \(\Spec \kappa(y)\). First,
  \(y \notin D(s)\), the basic open of \(s\): the point \(y\) lies in the range of
  \(\Spec \kappa(y) \to Y\), and if its preimage point lay in the preimage of \(D(s)\),
  that preimage --- the basic open of the pulled-back section, i.e.\ of \(0\) --- would
  be nonempty, which is absurd. Since the range of \(f\) is \(\{y\}\) and \(y \notin
  D(s)\), the preimage \(f^{-1}D(s)\) is empty. But \(f^{-1}D(s)\) is the basic open of
  the pulled-back section \(f^{\sharp}s \in \Gamma(X, f^{-1}U)\), so \(f^{\sharp}s\)
  has empty basic open: its image in every stalk of \(X\) lies in the maximal ideal, so
  on each affine chart it lies in every prime ideal, i.e.\ it is nilpotent. On the
  reduced scheme \(X\) it is therefore \(0\).
\end{proof}

\begin{theorem}[Factorization through the residue field of a closed point]
  \label{thm:hom_factors_fromSpecResidueField}
  \lean{AlgebraicGeometry.Scheme.Hom.exists_comp_fromSpecResidueField_eq}
  \uses{lem:ker_fromSpecResidueField_le}
  \leanok
  Let \(f : X \to Y\) be a quasi-compact morphism of schemes with \(X\) reduced whose
  set-range is a single \emph{closed} point \(y\): \(\{y\}\) is closed and
  \(f(X) = \{y\}\). Then \(f\) factors through the canonical morphism from the spectrum
  of the residue field: there is a morphism \(q : X \to \Spec \kappa(y)\) with
  \[
    f \;=\; \bigl(\Spec \kappa(y) \to Y\bigr) \circ q .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Since \(\{y\}\) is closed, the canonical morphism \(\Spec \kappa(y) \to Y\) is a
  closed immersion (it presents the reduced induced structure on the closed set
  \(\{y\}\): a singleton is irreducible, its reduced subscheme is the spectrum of a
  field, namely the residue field of its point). A morphism factors through a closed
  immersion --- necessarily uniquely --- exactly when the kernel ideal sheaf of the
  immersion is contained in its own kernel ideal sheaf; this containment is
  \ref{lem:ker_fromSpecResidueField_le}.
\end{proof}

\begin{theorem}[Proper closed subsets of the curve bundle are finite]
  \label{thm:curve_finite_closed}
  \lean{AlgebraicGeometry.finite_of_isClosed_of_notMem_genericPoint_curve}
  \leanok
  Let \(K\) be a field and \(X\) an integral scheme, smooth of relative dimension one
  over \(\Spec K\), whose underlying space is quasi-compact. Then every closed subset
  \(Z \subseteq X\) not containing the generic point is finite.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:height_one_finite_closed, thm:relDim1_specializes}
  The underlying space of \(X\) is irreducible, and its specialization order has height
  one: every generalization of a point is the generic point or the point itself
  (\ref{thm:relDim1_specializes}). The space is moreover Noetherian: \(X\) is locally of
  finite type over the field \(K\) (smoothness of relative dimension one includes local
  finite presentation), so each affine chart is the spectrum of a finitely generated
  \(K\)-algebra --- a Noetherian ring by the Hilbert basis theorem --- and a
  quasi-compact space covered by finitely many Noetherian opens is Noetherian. Apply
  the finiteness of proper closed subsets (\ref{thm:height_one_finite_closed}).
\end{proof}

\begin{theorem}[The curve-morphism dichotomy]
  \label{thm:curveHom_isFinite_or_constant}
  \lean{AlgebraicGeometry.curveHom_isFinite_or_constant}
  \leanok
  \source{hartshorne-algebraic-geometry:page-0154}
  Let \(K\) be a field and let \(D, E\) be objects of \(\Over(\Spec K)\), both proper,
  smooth of relative dimension one and geometrically irreducible over \(K\). Then every
  morphism \(h : D \to E\) of \(\Over(\Spec K)\) satisfies at least one of the
  following: either (1) \(h\) is surjective and finite, or (2) there is a point \(x\)
  of \(E\) with \(\{x\}\) closed and \(h(D) = \{x\}\). The two cases may overlap: when
  the space of \(E\) is a single point, both hold.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:overHom_isProper, thm:curve_finite_closed, thm:closedpoint_isClosed,
    lem:genericPoint_eq_of_surjective, thm:smooth_geometrically_reduced,
    prop:curve_integral, lem:irreducible_of_geomirred}
  Both bundles are integral schemes: smoothness gives geometric reducedness
  (\ref{thm:smooth_geometrically_reduced}), which together with geometric
  irreducibility gives integrality (\ref{prop:curve_integral}); in particular the
  underlying spaces are irreducible (\ref{lem:irreducible_of_geomirred}) and sober,
  with generic points \(\eta_D\), \(\eta_E\).

  \emph{The image is the closure of a point.} By \ref{thm:overHom_isProper} the
  underlying morphism of \(h\) is proper, hence a closed map, so the set-range
  \(h(D)\) is closed in \(E\); and it is irreducible, being the continuous image of
  the irreducible space \(D\). A nonempty irreducible closed subset of a sober space is
  the closure of a unique point: \(h(D) = \overline{\{\zeta\}}\).

  \emph{Case \(\zeta \neq \eta_E\).} The singleton \(\{\zeta\}\) is closed
  (\ref{thm:closedpoint_isClosed}), so \(h(D) = \overline{\{\zeta\}} = \{\zeta\}\), and
  case (2) holds with \(x = \zeta\).

  \emph{Case \(\zeta = \eta_E\).} Then \(h(D) = \overline{\{\eta_E\}} = E\), so \(h\)
  is surjective; and a surjection matches the generic points, \(h(\eta_D) = \eta_E\)
  (\ref{lem:genericPoint_eq_of_surjective}).

  Suppose first that some point \(z \neq \eta_D\) also maps to \(\eta_E\). Then
  \(\{z\}\) is closed in \(D\) (\ref{thm:closedpoint_isClosed}), and \(h\), a closed
  map, carries it to the closed set \(\{\eta_E\}\). A closed subset containing the
  generic point of an irreducible space is the whole space, so \(E\) has the single
  point \(\eta_E\); since the range is all of \(E = \{\eta_E\}\), case (2) holds with
  \(x = \eta_E\) --- this is the overlap of the two cases.

  Otherwise the fiber of \(\eta_E\) is exactly \(\{\eta_D\}\), and every fiber of
  \(h\) is finite: the fiber over a point \(y \neq \eta_E\) is closed --- \(\{y\}\) is
  closed by \ref{thm:closedpoint_isClosed} --- and avoids \(\eta_D\), whose image is
  \(\eta_E\); so it is finite by \ref{thm:curve_finite_closed}. Since \(h\) is locally
  of finite type and quasi-compact (\ref{thm:overHom_isProper}), finiteness of all
  fibers makes it locally quasi-finite; and a proper, locally quasi-finite morphism is
  finite, by Zariski's main theorem. So case (1) holds.
\end{proof}

\section{The topology of the projective line and morphisms into it}

Two groups of results about \(\PP^1\) feed the construction of the finite morphism from
the curve: the topology of \(\PP^1\) (irreducibility, height-one specialization, closed
points, separatedness), and the construction of morphisms \(\Spec A \to \PP^1\) from a
single element of a ring \(A\) under \(k\), with the gluing identity
\([1 : u] = [u^{-1} : 1]\) for units.

\begin{lemma}[The chart models are domains]
  \label{lem:P1_away_domains}
  \lean{AlgebraicGeometry.P1.instIsDomainAwayNatMvPolynomialFinOfNatSubmoduleHomogeneousSubmoduleX,
    AlgebraicGeometry.P1.instIsDomainAwayNatMvPolynomialFinOfNatSubmoduleHomogeneousSubmoduleX_1,
    AlgebraicGeometry.P1.instNontrivialAwayNatMvPolynomialFinOfNatSubmoduleHomogeneousSubmoduleHMulX}
  \uses{def:P1_awayAlgEquiv, def:P1_overlapAlgEquiv}
  \leanok
  The chart rings \(A_{(X_0)}\) and \(A_{(X_1)}\) are integral domains, and the overlap
  ring \(A_{(X_0X_1)}\) is nontrivial.
\end{lemma}
\begin{proof}
  \leanok
  Transport along the isomorphisms \(\alpha_i : A_{(X_i)} \cong k[t]\) of
  \ref{def:P1_awayAlgEquiv} and \(\theta : A_{(X_0X_1)} \cong k[T,T^{-1}]\) of
  \ref{def:P1_overlapAlgEquiv}: polynomial rings over a field are domains, and the Laurent
  polynomial ring is nontrivial.
\end{proof}

\begin{lemma}[The chart section rings are principal ideal rings]
  \label{lem:P1_chartSections_pid}
  \lean{AlgebraicGeometry.P1.isPrincipalIdealRing_chartSections}
  \uses{def:P1_chartSectionsEquiv0, def:P1_chartSectionsEquiv1}
  \leanok
  For \(i \in \{0,1\}\), the ring \(\Gamma(\PP^1, U_i)\) is a principal ideal ring.
\end{lemma}
\begin{proof}
  \leanok
  Being a principal ideal ring transports along the surjective homomorphism
  \(\gamma_i^{-1} : k[t] \to \Gamma(\PP^1, U_i)\)
  (\ref{def:P1_chartSectionsEquiv0}--\ref{def:P1_chartSectionsEquiv1}), and \(k[t]\) is a
  principal ideal domain.
\end{proof}

\begin{lemma}[The chart section rings are domains]
  \label{lem:P1_chartSections_domain}
  \lean{AlgebraicGeometry.P1.isDomain_chartSections}
  \uses{def:P1_chartSectionsEquiv0, def:P1_chartSectionsEquiv1}
  \leanok
  For \(i \in \{0,1\}\), the ring \(\Gamma(\PP^1, U_i)\) is an integral domain.
\end{lemma}
\begin{proof}
  \leanok
  Transport along \(\gamma_i : \Gamma(\PP^1, U_i) \cong k[t]\).
\end{proof}

\begin{theorem}[The chart section rings are Dedekind]
  \label{thm:P1_chartSections_dedekind}
  \lean{AlgebraicGeometry.P1.isDedekindDomain_chartSections}
  \uses{lem:P1_chartSections_pid, lem:P1_chartSections_domain}
  \leanok
  For \(i \in \{0,1\}\), the ring \(\Gamma(\PP^1, U_i)\) is a Dedekind domain.
\end{theorem}
\begin{proof}
  \leanok
  A principal ideal domain is a Dedekind domain; combine
  \ref{lem:P1_chartSections_pid} and \ref{lem:P1_chartSections_domain}.
\end{proof}

\begin{lemma}[Every nonempty open meets the left chart]
  \label{lem:P1_dense_chart}
  \lean{AlgebraicGeometry.P1.exists_mem_chartOpen_zero_of_isOpen}
  \uses{lem:P1_chartOpen_sup, lem:P1_chartIota_range, lem:P1_away_domains}
  \leanok
  Every nonempty open subset \(W \subseteq \PP^1\) contains a point of the chart \(U_0\).
\end{lemma}
\begin{proof}
  \leanok
  Let \(w \in W\). The charts cover (\ref{lem:P1_chartOpen_sup}), so \(w \in U_0\) or
  \(w \in U_1\); in the first case we are done. In the second, work in the affine model
  \(U_1 \cong \Spec A_{(X_1)}\) (\ref{lem:P1_chartIota_range}), an irreducible space since
  \(A_{(X_1)}\) is a domain (\ref{lem:P1_away_domains}). The preimage of \(W\) there is a
  nonempty open (it contains the preimage of \(w\)). The preimage of \(U_0\) there is open
  and nonempty: the overlap \(D_+(X_0X_1)\) is contained in both charts and is nonempty,
  because its coordinate ring \(A_{(X_0X_1)}\) is nontrivial (\ref{lem:P1_away_domains}).
  Two nonempty opens of an irreducible space intersect; the image in \(\PP^1\) of a common
  point lies in \(W \cap U_0\).
\end{proof}

\begin{theorem}[Irreducibility of the projective line]
  \label{thm:P1_irreducible}
  \lean{AlgebraicGeometry.P1.instIrreducibleSpaceCarrierCarrierCommRingCat}
  \uses{lem:P1_dense_chart, lem:P1_chartIota_range, lem:P1_away_domains}
  \leanok
  The underlying topological space of \(\PP^1\) is irreducible (in particular nonempty).
\end{theorem}
\begin{proof}
  \leanok
  \(\PP^1\) is nonempty: the chart \(U_0 \cong \Spec A_{(X_0)}\) is the spectrum of a
  nontrivial ring. Let \(u, v\) be nonempty opens of \(\PP^1\). By
  \ref{lem:P1_dense_chart} both meet \(U_0\), so their preimages in the affine model
  \(\Spec A_{(X_0)}\) (\ref{lem:P1_chartIota_range}) are nonempty opens; the spectrum of
  the domain \(A_{(X_0)}\) (\ref{lem:P1_away_domains}) is irreducible, so the preimages
  intersect, and the image of a common point lies in \(u \cap v\).
\end{proof}

\begin{lemma}[The generic point through the chart]
  \label{lem:P1_generic_point_chart}
  \lean{AlgebraicGeometry.P1.chartι_base_genericPoint}
  \uses{def:P1_chartIota, thm:P1_irreducible}
  \leanok
  The affine model \(\Spec A_{(X_0)} \to \PP^1\) sends the generic point of
  \(\Spec A_{(X_0)}\) to the generic point of \(\PP^1\).
\end{lemma}
\begin{proof}
  \leanok
  An open immersion with nonempty source into an irreducible space has dense image, and
  the image of the generic point of the source is a generic point of the image, hence of
  the closure of the image, which is the whole space.
\end{proof}

\begin{lemma}[A second point of the projective line]
  \label{lem:P1_exists_ne_generic}
  \lean{AlgebraicGeometry.P1.exists_ne_genericPoint}
  \uses{def:P1_awayAlgEquiv, lem:P1_generic_point_chart}
  \leanok
  \(\PP^1\) has a point distinct from its generic point.
\end{lemma}
\begin{proof}
  \leanok
  \(A_{(X_0)} \cong k[t]\) (\ref{def:P1_awayAlgEquiv}) is not a field, so it has a nonzero
  prime ideal \(\mathfrak p\). The corresponding point of the chart differs from the
  generic point: the generic point corresponds to the zero ideal
  (\ref{lem:P1_generic_point_chart}), and the chart immersion is injective.
\end{proof}

\begin{theorem}[Height-one specialization on the projective line]
  \label{thm:P1_specializes}
  \lean{AlgebraicGeometry.P1.specializes_eq_genericPoint_or_eq}
  \uses{lem:P1_chartOpen_sup, lem:P1_chartOpen_affine, thm:P1_chartSections_dedekind,
    thm:affine_dedekind_specializes}
  \leanok
  Every generalization of a point of \(\PP^1\) is the generic point or the point itself.
\end{theorem}
\begin{proof}
  \leanok
  Every point lies in one of the two charts (\ref{lem:P1_chartOpen_sup}), which are affine
  (\ref{lem:P1_chartOpen_affine}) with Dedekind section rings
  (\ref{thm:P1_chartSections_dedekind}); apply \ref{thm:affine_dedekind_specializes}.
\end{proof}

\begin{lemma}[Non-generic points of the projective line are closed]
  \label{lem:P1_closed_points}
  \lean{AlgebraicGeometry.P1.isClosed_singleton_of_ne_genericPoint}
  \uses{lem:height_one_closed_points, thm:P1_specializes}
  \leanok
  Every point of \(\PP^1\) other than the generic point is closed.
\end{lemma}
\begin{proof}
  \leanok
  Immediate from \ref{lem:height_one_closed_points} and \ref{thm:P1_specializes}.
\end{proof}

\begin{theorem}[Separatedness of the projective line]
  \label{thm:P1_separated}
  \lean{AlgebraicGeometry.P1.instIsSeparated}
  \uses{thm:P1_proper}
  \leanok
  \(\PP^1\) is a separated scheme.
\end{theorem}
\begin{proof}
  \leanok
  The structure morphism \(\PP^1 \to \Spec k\) is proper (\ref{thm:P1_proper}), hence
  separated, and \(\Spec k\), being affine, is a separated scheme; a scheme separated over
  a separated scheme is separated.
\end{proof}

\begin{definition}[Evaluation of the chart ring]
  \label{def:P1_chartEval}
  \lean{AlgebraicGeometry.P1.chartEval}
  \uses{def:P1_awayToPoly}
  \leanok
  Let \(A\) be a commutative ring under \(k\), i.e.\ equipped with a ring homomorphism
  \(\sigma : k \to A\), let \(i \in \{0,1\}\) and \(a \in A\). The evaluation of the chart
  ring at \(a\) is the ring homomorphism
  \[
    A_{(X_i)} \longrightarrow A, \qquad
    z \longmapsto \bigl(\text{the polynomial } \alpha_i(z) \in k[t]\bigr)
      \text{ evaluated at } t = a \text{ with coefficients mapped by } \sigma
  \]
  (composite of \ref{def:P1_awayToPoly} with polynomial evaluation). It sends the chart
  coordinate \(t_{ij}\) (\(j \neq i\)) to \(a\) and a constant \(c \in k\) to \(\sigma(c)\).
\end{definition}

\begin{definition}[Morphisms to the projective line through a chart]
  \label{def:P1_fromSpecChart}
  \lean{AlgebraicGeometry.P1.fromSpecChart}
  \uses{def:P1_chartEval, def:P1_chartIota}
  \leanok
  With \(\sigma : k \to A\), \(i \in \{0,1\}\) and \(a \in A\) as in
  \ref{def:P1_chartEval}: the morphism \(\Spec A \to \PP^1\) obtained by applying
  \(\Spec\) to the evaluation \(A_{(X_i)} \to A\) at \(a\) and composing with the affine
  model \(\Spec A_{(X_i)} \to \PP^1\) of \ref{def:P1_chartIota}. For \(i = 0\) this is the
  ``point'' \([1 : a]\); for \(i = 1\) it is \([a : 1]\).
\end{definition}

\begin{lemma}[The chart morphisms lie over the base]
  \label{lem:P1_fromSpecChart_over}
  \lean{AlgebraicGeometry.P1.fromSpecChart_structureMap}
  \uses{def:P1_fromSpecChart, def:P1_structureMap, lem:P1_chartIota_structureMap}
  \leanok
  The composite of the morphism of \ref{def:P1_fromSpecChart} with the structure morphism
  \(\PP^1 \to \Spec k\) is \(\Spec \sigma : \Spec A \to \Spec k\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{def:P1_chartEval}
  The affine model lies over \(k\) (\ref{lem:P1_chartIota_structureMap}), and the
  evaluation homomorphism of \ref{def:P1_chartEval} restricts to \(\sigma\) on the constants
  \(k \to A_{(X_i)}\); apply \(\Spec\) to this equality of ring homomorphisms.
\end{proof}

\begin{lemma}[Naturality of the chart morphisms]
  \label{lem:P1_fromSpecChart_natural}
  \lean{AlgebraicGeometry.P1.SpecMap_fromSpecChart}
  \uses{def:P1_fromSpecChart}
  \leanok
  Let \(g : A \to A'\) be a homomorphism of rings under \(k\) (so \(A'\) is under \(k\)
  via \(g \circ \sigma\)), \(i \in \{0,1\}\) and \(a \in A\). Then the composite
  \(\Spec A' \xrightarrow{\Spec g} \Spec A \to \PP^1\) of \ref{def:P1_fromSpecChart} at
  \(a\) is the morphism of \ref{def:P1_fromSpecChart} at \(g(a) \in A'\).
\end{lemma}
\begin{proof}
  \leanok
  Polynomial evaluation commutes with \(g\): evaluating at \(a\) and applying \(g\) is
  evaluating at \(g(a)\) with coefficients mapped by \(g \circ \sigma\). Apply \(\Spec\).
\end{proof}

\begin{lemma}[The chart restrictions factor the overlap model]
  \label{lem:P1_SpecMap_overlap_chartIota}
  \lean{AlgebraicGeometry.P1.SpecMap_awayToOverlapLeft_chartι,
    AlgebraicGeometry.P1.SpecMap_awayToOverlapRight_chartι}
  \uses{def:P1_awayToOverlapLeft, def:P1_awayToOverlapRight, def:P1_chartIota}
  \leanok
  Applying \(\Spec\) to the restriction homomorphism \(\lambda : A_{(X_0)} \to
  A_{(X_0X_1)}\) (resp.\ \(\rho : A_{(X_1)} \to A_{(X_0X_1)}\)) of
  \ref{def:P1_awayToOverlapLeft} (resp.\ \ref{def:P1_awayToOverlapRight}) and composing
  with the affine model of the chart \(U_0\) (resp.\ \(U_1\)) yields the affine model
  \(\Spec A_{(X_0X_1)} \to \PP^1\) of the overlap \(D_+(X_0X_1)\).
\end{lemma}
\begin{proof}
  \leanok
  This is the compatibility of the basic-open affine models of \(\Proj\) with inclusions
  of basic opens: the inclusion \(D_+(fg) \subseteq D_+(f)\) of basic opens corresponds,
  on affine models, to \(\Spec\) of the canonical map \(A_{(f)} \to A_{(fg)}\).
\end{proof}

\begin{theorem}[The gluing identity]
  \label{thm:P1_gluing_identity}
  \lean{AlgebraicGeometry.P1.fromSpecChart_units}
  \uses{def:P1_fromSpecChart, lem:P1_SpecMap_overlap_chartIota,
    lem:P1_overlap_isLocalization, lem:P1_coord_mul, lem:P1_polyToAway_surjective}
  \leanok
  Let \(\sigma : k \to A\) and let \(u \in A\) be a unit. Then the morphism
  \([1 : u] : \Spec A \to \PP^1\) through the chart \(U_0\) equals the morphism
  \([u^{-1} : 1]\) through the chart \(U_1\) (both as in \ref{def:P1_fromSpecChart}).
\end{theorem}
\begin{proof}
  \leanok
  \uses{def:P1_chartEval}
  Both morphisms factor through the chart overlap, where they are induced by one and the
  same ring homomorphism.

  The evaluation \(e_0 : A_{(X_0)} \to A\) at \(u\) (\ref{def:P1_chartEval}) sends the
  coordinate \(t_{01}\) to the unit \(u\). Since \(A_{(X_0X_1)}\) is the localization of
  \(A_{(X_0)}\) at the powers of \(t_{01}\) (\ref{lem:P1_overlap_isLocalization}), the
  universal property of localization extends \(e_0\) to a ring homomorphism
  \(\psi : A_{(X_0X_1)} \to A\) with \(\psi \circ \lambda = e_0\).

  From \(\lambda(t_{01}) \cdot \rho(t_{10}) = 1\) in \(A_{(X_0X_1)}\)
  (\ref{lem:P1_coord_mul}) we get \(u \cdot \psi(\rho(t_{10})) = 1\), i.e.\
  \(\psi(\rho(t_{10})) = u^{-1}\). Moreover \(\psi \circ \rho\) agrees with the structure
  map on constants: the two restrictions \(\lambda\) and \(\rho\) restrict to the same map
  on the constants \(k \to A_{(X_0X_1)}\), and \(\psi \circ \lambda = e_0\) restricts to
  \(\sigma : k \to A\) on constants. Since \(A_{(X_1)}\) is generated as a \(k\)-algebra by
  \(t_{10}\) (\ref{lem:P1_polyToAway_surjective}), it follows that \(\psi \circ \rho\) is
  exactly the evaluation \(e_1 : A_{(X_1)} \to A\) at \(u^{-1}\).

  Now apply \(\Spec\) and compose with the chart models. Writing \(\iota_0, \iota_1,
  \iota_{01}\) for the affine models of \(U_0\), \(U_1\) and \(D_+(X_0X_1)\), the
  factorization \(e_0 = \psi \circ \lambda\) and \ref{lem:P1_SpecMap_overlap_chartIota}
  give
  \[
    [1 : u]
      = \iota_0 \circ \Spec e_0
      = \iota_0 \circ \Spec \lambda \circ \Spec \psi
      = \iota_{01} \circ \Spec \psi ,
  \]
  and the same computation for \(e_1 = \psi \circ \rho\) gives
  \([u^{-1} : 1] = \iota_1 \circ \Spec e_1 = \iota_{01} \circ \Spec \psi\). The two
  morphisms coincide.
\end{proof}

\begin{theorem}[Transcendental points land on the generic point]
  \label{thm:P1_fromSpecChart_generic}
  \lean{AlgebraicGeometry.P1.fromSpecChart_base_genericPoint}
  \uses{def:P1_fromSpecChart, lem:P1_polyToAway_surjective, lem:P1_generic_point_chart}
  \leanok
  Let \(A\) be an integral domain under \(\sigma : k \to A\) and let \(a \in A\) be
  transcendental in the sense that no nonzero polynomial over \(k\), evaluated at \(a\)
  with coefficients mapped by \(\sigma\), vanishes. Then the morphism
  \([1 : a] : \Spec A \to \PP^1\) of \ref{def:P1_fromSpecChart} sends the generic point of
  \(\Spec A\) to the generic point of \(\PP^1\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{def:P1_chartEval}
  The evaluation \(A_{(X_0)} \to A\) at \(a\) is injective: every \(z \in A_{(X_0)}\) is a
  polynomial in the coordinate \(t_{01}\) with coefficients in \(k\)
  (\ref{lem:P1_polyToAway_surjective}), its image is that polynomial evaluated at \(a\),
  and by hypothesis this vanishes only for the zero polynomial. The spectrum of an
  injective homomorphism between domains sends the zero ideal to the zero ideal, i.e.\ the
  generic point of \(\Spec A\) to the generic point of \(\Spec A_{(X_0)}\); conclude by
  \ref{lem:P1_generic_point_chart}.
\end{proof}

\section{Spreading out a rational function to the projective line}

On an integral scheme \(X\), proper and smooth of relative dimension one over \(k\), a
rational function \(f_0 \in K(X)\) transcendental over \(k\) spreads out to a
\(k\)-morphism \(\pi : X \to \PP^1\) with finite fibers. This section provides the
stalk-level bricks and the spreading-out argument. Classically, the corresponding morphism
is produced from the inclusion of function fields \(k(f_0) \subseteq K(X)\) together with
the finiteness of \(K(X)\) over \(k(f_0)\); the route taken here never uses that
finiteness --- quasi-finiteness of \(\pi\) is obtained purely topologically from the
height-one specialization order of both spaces.

\begin{lemma}[Stalk morphisms are compatible with specialization]
  \label{lem:fromSpecStalkOfMem_stalkSpecializes}
  \lean{AlgebraicGeometry.Scheme.Opens.fromSpecStalkOfMem_stalkSpecializes}
  \leanok
  Let \(X\) be a scheme, \(U \subseteq X\) open, \(x \in U\), and let \(y\) be a
  generalization of \(x\) (so \(y \in U\) as well). Write
  \(\struct{X,x} \to \struct{X,y}\) for the canonical map of stalks (restriction of
  germs). Then the composite
  \[
    \Spec \struct{X,y} \longrightarrow \Spec \struct{X,x} \longrightarrow U
  \]
  of the induced morphism of spectra with the canonical morphism
  \(\Spec \struct{X,x} \to U\) is the canonical morphism \(\Spec \struct{X,y} \to U\).
\end{lemma}
\begin{proof}
  \leanok
  The stalk of \(X\) at a point of \(U\) is canonically the stalk of the open subscheme
  \(U\) at that point, compatibly with the canonical maps of stalks along
  specializations (naturality of germs along the open immersion \(U \to X\)); and on
  \(X\) itself the analogous triangle of canonical morphisms
  \(\Spec \struct{X,y} \to \Spec \struct{X,x} \to X\) commutes, both composites being the
  morphism determined by the local ring \(\struct{X,y}\) and its ideal-theoretic image.
  Transport this triangle through the open immersion.
\end{proof}

\begin{definition}[Partial and rational maps]
  \label{def:rational_map_machinery}
  \lean{AlgebraicGeometry.Scheme.RationalMap.ofFunctionField,
    AlgebraicGeometry.Scheme.RationalMap.toPartialMap,
    AlgebraicGeometry.Scheme.PartialMap.ofFromSpecStalk,
    AlgebraicGeometry.Scheme.RationalMap.mem_domain,
    AlgebraicGeometry.Scheme.RationalMap.eq_of_fromFunctionField_eq}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \(X, Y\) be schemes over a base \(S\). A \emph{partial map} \(X \dashrightarrow Y\)
  is a morphism to \(Y\) from a dense open subscheme of \(X\) (its \emph{domain}); a
  \emph{rational map} is an equivalence class of partial maps, two being equivalent when
  they agree on a common dense open. For \(X\) irreducible with generic point \(\xi\) and
  function field \(K(X) = \struct{X,\xi}\), a partial map \(g\) restricts to a morphism
  \(\Spec K(X) \to Y\) (its \emph{function-field morphism}), which determines the rational
  map. For \(X\) integral and \(Y\) locally of finite type over \(S\):
  \begin{enumerate}
    \item every \(S\)-morphism \(\Spec K(X) \to Y\) arises as the function-field morphism
      of a unique rational \(S\)-map \(X \dashrightarrow Y\) (spreading out);
    \item if moreover an \(S\)-morphism \(\Spec \struct{X,x} \to Y\) restricting to the
      given one on \(\Spec K(X)\) exists at a point \(x\), then \(x\) lies in the domain
      of definition of that rational map (the union of the domains of its
      representatives);
    \item if \(Y\) is separated, a rational map has a largest representative, defined on
      its whole domain of definition.
  \end{enumerate}
\end{definition}

\begin{lemma}[Restriction of a partial map to the function field]
  \label{lem:partialMap_fromFunctionField_eq}
  \lean{AlgebraicGeometry.Scheme.PartialMap.fromFunctionField_eq}
  \uses{def:rational_map_machinery, lem:fromSpecStalkOfMem_stalkSpecializes}
  \leanok
  Let \(X\) be a scheme with irreducible underlying space, \(g : X \dashrightarrow Y\) a
  partial map and \(x\) a point of its domain. Then the function-field morphism of \(g\)
  is the composite
  \[
    \Spec K(X) \longrightarrow \Spec \struct{X,x}
      \longrightarrow Y,
  \]
  where the first arrow is induced by the canonical map
  \(\struct{X,x} \to K(X) = \struct{X,\xi}\) and the second is the restriction of \(g\) to
  \(\Spec \struct{X,x}\).
\end{lemma}
\begin{proof}
  \leanok
  The function-field morphism is by definition the restriction of \(g\) to
  \(\Spec\) of the stalk at the generic point, which is a generalization of \(x\); apply
  \ref{lem:fromSpecStalkOfMem_stalkSpecializes} inside the domain of \(g\).
\end{proof}

\begin{definition}[The structure map of a stalk]
  \label{def:structureStalk}
  \lean{AlgebraicGeometry.Scheme.Hom.structureStalk}
  \leanok
  Let \(f : X \to \Spec k\) be a scheme over \(k\) and \(x \in X\). The structure map of
  the stalk at \(x\) is the composite ring homomorphism
  \(k \to \Gamma(X, X) \to \struct{X,x}\) of the map induced by \(f\) on global sections
  with the germ at \(x\); it makes every stalk of \(X\) a ring under \(k\).
\end{definition}

\begin{lemma}[Coherence of the structure maps of stalks]
  \label{lem:structureStalk_coherence}
  \lean{AlgebraicGeometry.Scheme.Hom.Spec_map_structureStalk,
    AlgebraicGeometry.Scheme.Hom.structureStalk_stalkSpecializes}
  \uses{def:structureStalk}
  \leanok
  Let \(f : X \to \Spec k\) and \(x \in X\).
  \begin{enumerate}
    \item Applying \(\Spec\) to the structure map of \ref{def:structureStalk} yields the
      composite \(\Spec \struct{X,x} \to X \xrightarrow{f} \Spec k\) of the canonical
      morphism with \(f\).
    \item For a generalization \(y\) of \(x\), composing the structure map at \(x\) with
      the canonical map \(\struct{X,x} \to \struct{X,y}\) yields the structure map at
      \(y\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \leanok
  (1) is the compatibility of the canonical morphism \(\Spec \struct{X,x} \to X\) with
  global sections: its composite with \(f\) corresponds, under the anti-equivalence of
  affine schemes and rings, to the composite \(k \to \Gamma(X, X) \to \struct{X,x}\).
  (2) is the compatibility of germs with the canonical maps of stalks: the germ at \(x\)
  followed by restriction of germs to \(y\) is the germ at \(y\).
\end{proof}

\begin{theorem}[A smooth projective curve maps locally quasi-finitely and dominantly to the line]
  \label{thm:exists_lqf_dominant_toP1}
  \lean{AlgebraicGeometry.exists_locallyQuasiFinite_isDominant_toP1}
  \uses{def:P1_structureMap}
  \leanok
  Let \(X\) be an integral scheme, proper and smooth of relative dimension one over the
  field \(k\). Then there is a morphism \(\pi : X \to \PP^1\) over \(k\) which is locally
  quasi-finite and dominant.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:relDim1_transcendental, thm:relDim1_stalks_valuation, thm:relDim1_specializes,
    def:structureStalk, lem:structureStalk_coherence, def:P1_fromSpecChart,
    lem:P1_fromSpecChart_over, lem:P1_fromSpecChart_natural, thm:P1_gluing_identity,
    thm:P1_fromSpecChart_generic, def:rational_map_machinery,
    lem:partialMap_fromFunctionField_eq, lem:height_one_closed_points,
    thm:height_one_finite_closed, lem:P1_exists_ne_generic, lem:P1_closed_points,
    thm:P1_separated, thm:P1_proper}
  Write \(\xi\) for the generic point of \(X\) and \(K(X) = \struct{X,\xi}\) for the
  function field, a field under \(k\) via the structure map of \ref{def:structureStalk}.

  (a) \emph{The generic morphism.} By \ref{thm:relDim1_transcendental} choose
  \(f_0 \in K(X)\) transcendental over \(k\); in particular \(f_0 \neq 0\) (the polynomial
  \(T\) does not vanish at \(f_0\)). Let
  \(\varphi_K = [1 : f_0] : \Spec K(X) \to \PP^1\) be the chart-\(0\) morphism of
  \ref{def:P1_fromSpecChart}. It lies over \(k\), compatibly with the canonical morphism
  \(\Spec K(X) \to X\), by \ref{lem:P1_fromSpecChart_over} and
  \ref{lem:structureStalk_coherence}(1).

  (b) \emph{Local regularity.} Let \(x \in X\). The stalk \(\struct{X,x}\) is a valuation
  ring (\ref{thm:relDim1_stalks_valuation}) with fraction field \(K(X)\), so \(f_0\) or
  \(f_0^{-1}\) lies in \(\struct{X,x}\). In the first case, with \(f_0 = a\) in
  \(\struct{X,x}\), set \(\varphi_x = [1 : a] : \Spec \struct{X,x} \to \PP^1\) through
  chart \(0\); in the second, with \(f_0^{-1} = b\), set \(\varphi_x = [b : 1]\) through
  chart \(1\). In both cases \(\varphi_x\) lies over \(k\)
  (\ref{lem:P1_fromSpecChart_over}, \ref{lem:structureStalk_coherence}(1)), and its
  restriction along \(\Spec K(X) \to \Spec \struct{X,x}\) is \(\varphi_K\): in the first
  case by naturality (\ref{lem:P1_fromSpecChart_natural}) together with
  \ref{lem:structureStalk_coherence}(2), since \(a \mapsto f_0\) under
  \(\struct{X,x} \to K(X)\); in the second case, naturality gives the chart-\(1\)
  morphism \([f_0^{-1} : 1]\) on \(\Spec K(X)\), which equals \([1 : f_0]\) by the gluing
  identity \ref{thm:P1_gluing_identity} applied to the unit \(f_0\) of the field
  \(K(X)\).

  (c) \emph{Spreading out.} The projective line is locally of finite type and separated
  over \(k\) (\ref{thm:P1_proper}). By \ref{def:rational_map_machinery}(1), \(\varphi_K\)
  is the function-field morphism of a rational \(k\)-map
  \(F : X \dashrightarrow \PP^1\). Every point \(x\) lies in the domain of definition of
  \(F\): the morphism \(\varphi_x\) of (b) spreads out to a partial map defined at \(x\)
  (\ref{def:rational_map_machinery}(2)) whose function-field morphism is the restriction
  of \(\varphi_x\) to \(\Spec K(X)\) (\ref{lem:partialMap_fromFunctionField_eq}), i.e.\
  \(\varphi_K\) --- so this partial map represents \(F\). Since \(X\) is reduced and
  \(\PP^1\) separated (\ref{thm:P1_separated}), \(F\) has a largest representative
  (\ref{def:rational_map_machinery}(3)), defined on the whole of \(X\): an honest
  morphism \(\pi : X \to \PP^1\) whose restriction to \(\Spec K(X)\) is \(\varphi_K\).

  (d) \emph{\(\pi\) lies over \(k\).} The canonical morphism \(\Spec K(X) \to X\) hits the
  generic point, hence is dominant, and \(\PP^1\) is separated; two morphisms out of the
  reduced scheme \(X\) to a separated scheme agreeing after composition with a dominant
  morphism agree. Both \(\pi\) followed by the structure morphism of \(\PP^1\) and the
  structure morphism \(f\) of \(X\) restrict on \(\Spec K(X)\) to the structure morphism
  of \(\Spec K(X)\) (step (a)), so they agree.

  (e) \emph{\(\pi\) is proper and locally of finite type.} By (d), \(\pi\) followed by the
  separated structure morphism of \(\PP^1\) is the proper, locally of finite type
  morphism \(f\); properness and local finite-typeness descend along such factorizations
  (cancellation).

  (f) \emph{\(\pi\) maps \(\xi\) to the generic point of \(\PP^1\).} The point
  \(\pi(\xi)\) is the image of the unique point of \(\Spec K(X)\) under \(\varphi_K\),
  and \(\varphi_K = [1 : f_0]\) sends it to the generic point of \(\PP^1\) by
  \ref{thm:P1_fromSpecChart_generic} (the hypothesis is the transcendence of \(f_0\), and
  the unique point of \(\Spec K(X)\) is its generic point).

  (g) \emph{All fibers of \(\pi\) are finite.} The underlying space of \(X\) is Noetherian:
  \(X\) is locally of finite type over a field, hence locally Noetherian, and
  quasi-compact (proper). Its specialization order has height one
  (\ref{thm:relDim1_specializes}).

  \emph{The fiber of the generic point of \(\PP^1\) is contained in \(\{\xi\}\):} suppose
  \(x \neq \xi\) with \(\pi(x)\) generic. Then \(\{x\}\) is closed
  (\ref{lem:height_one_closed_points}), and \(\pi\), being proper, is a closed map, so
  \(\{\pi(x)\}\) is closed in \(\PP^1\). But the closure of the generic point is all of
  \(\PP^1\), which has a second point (\ref{lem:P1_exists_ne_generic}) --- a
  contradiction.

  \emph{Any other fiber is finite:} for \(y\) a non-generic point of \(\PP^1\), the
  singleton \(\{y\}\) is closed (\ref{lem:P1_closed_points}), so the fiber
  \(\pi^{-1}(y)\) is closed in \(X\), and it avoids \(\xi\) because
  \(\pi(\xi)\) is the generic point of \(\PP^1\) (step (f)), which differs from \(y\).
  By \ref{thm:height_one_finite_closed} the fiber is finite.

  (h) A morphism which is locally of finite type and has finite fibers is locally
  quasi-finite; by (e) and (g), \(\pi\) is locally quasi-finite.

  (i) \emph{\(\pi\) is dominant.} By (f) the image of \(\pi\) contains the generic point
  of \(\PP^1\), whose closure is all of \(\PP^1\); so the image of \(\pi\) is dense, i.e.\
  \(\pi\) is dominant.
\end{proof}

\begin{theorem}[A smooth projective curve maps locally quasi-finitely to the line]
  \label{thm:exists_lqf_toP1}
  \lean{AlgebraicGeometry.exists_locallyQuasiFinite_toP1}
  \uses{def:P1_structureMap}
  \leanok
  Let \(X\) be an integral scheme, proper and smooth of relative dimension one over the
  field \(k\). Then there is a morphism \(\pi : X \to \PP^1\) over \(k\) which is locally
  quasi-finite.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:exists_lqf_dominant_toP1}
  The morphism of \ref{thm:exists_lqf_dominant_toP1}, forgetting that it is dominant.
\end{proof}

\section{A finite morphism to the projective line}

\begin{theorem}[Zariski's main theorem, cancellation form]
  \label{thm:zmt_cancellation}
  \lean{AlgebraicGeometry.IsFinite.of_locallyQuasiFinite_of_comp}
  \leanok
  Let \(\pi : X \to Y\) and \(g : Y \to S\) be morphisms of schemes with \(\pi\) locally
  quasi-finite, \(g\) separated and \(g \circ \pi\) proper. Then \(\pi\) is finite.
\end{theorem}
\begin{proof}
  \leanok
  By the cancellation property of proper morphisms (using that \(g\) is separated), \(\pi\)
  is proper. A proper, locally quasi-finite morphism is finite (Zariski's main theorem).
\end{proof}

\begin{lemma}[Locally quasi-finite maps to the projective line are finite]
  \label{lem:finite_toP1_of_lqf}
  \lean{AlgebraicGeometry.isFinite_toP1_of_locallyQuasiFinite}
  \uses{def:P1_structureMap}
  \leanok
  Let \(X\) be a scheme, proper over \(k\), and let \(\pi : X \to \PP^1\) be a locally
  quasi-finite morphism over \(k\) (i.e.\ its composite with the structure morphism of
  \(\PP^1\) is the structure morphism of \(X\)). Then \(\pi\) is finite.
\end{lemma}
\begin{proof}
  \leanok
  \uses{thm:zmt_cancellation, thm:P1_proper}
  The structure morphism of \(\PP^1\) is proper (\ref{thm:P1_proper}), in particular
  separated, and the composite of \(\pi\) with it is the structure morphism of \(X\), which
  is proper. Apply \ref{thm:zmt_cancellation}.
\end{proof}

\begin{lemma}[Reduction to local quasi-finiteness]
  \label{lem:exists_finite_of_lqf}
  \lean{AlgebraicGeometry.exists_isFinite_toP1_of_locallyQuasiFinite}
  \uses{def:P1_structureMap}
  \leanok
  Let \(C\) be a scheme, proper over \(k\). If there exists a locally quasi-finite morphism
  \(C \to \PP^1\) over \(k\), then there exists a finite morphism \(C \to \PP^1\) over \(k\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:finite_toP1_of_lqf}
  Immediate from \ref{lem:finite_toP1_of_lqf}: the given locally quasi-finite morphism is
  itself finite.
\end{proof}

\begin{theorem}[Existence of a finite morphism to the projective line]
  \label{thm:exists_finite_toP1}
  \lean{AlgebraicGeometry.exists_isFinite_toP1}
  \uses{def:P1, def:P1_structureMap}
  \leanok
  Let \(C\) be a smooth curve over \(k\) (proper, smooth of relative dimension one,
  geometrically irreducible). Then there exists a finite morphism \(\pi : C \to \PP^1\) over
  \(k\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:relDim_geometrically_reduced, prop:curve_integral, thm:exists_lqf_toP1,
    lem:exists_finite_of_lqf}
  \(C\) is geometrically reduced over \(k\) (\ref{lem:relDim_geometrically_reduced}), and
  being also geometrically irreducible, it is an integral scheme
  (\ref{prop:curve_integral}). By \ref{thm:exists_lqf_toP1} there is a locally quasi-finite
  morphism \(C \to \PP^1\) over \(k\), and by \ref{lem:exists_finite_of_lqf} it may be
  taken finite.
\end{proof}

\begin{theorem}[Existence of a finite dominant morphism to the projective line]
  \label{thm:exists_finite_dominant_toP1}
  \lean{AlgebraicGeometry.exists_isFinite_isDominant_toP1}
  \uses{def:P1, def:P1_structureMap}
  \leanok
  Let \(C\) be a smooth curve over \(k\) (proper, smooth of relative dimension one,
  geometrically irreducible). Then there exists a finite morphism \(\pi : C \to \PP^1\)
  over \(k\) which is moreover \emph{dominant}. The dominance is part of the output of the
  construction --- the constructed \(\pi\) sends the generic point of \(C\) to the generic
  point of \(\PP^1\) --- and is not asserted as a formal consequence of finiteness alone.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:relDim_geometrically_reduced, prop:curve_integral, thm:exists_lqf_dominant_toP1,
    lem:finite_toP1_of_lqf}
  \(C\) is geometrically reduced over \(k\) (\ref{lem:relDim_geometrically_reduced}), and
  being also geometrically irreducible, it is an integral scheme
  (\ref{prop:curve_integral}). By \ref{thm:exists_lqf_dominant_toP1} there is a locally
  quasi-finite \emph{dominant} morphism \(\pi : C \to \PP^1\) over \(k\), and by
  \ref{lem:finite_toP1_of_lqf} this same morphism \(\pi\) is finite. Since the finiteness
  upgrade concerns the very morphism already constructed, its dominance and its
  compatibility with the structure morphisms persist unchanged.
\end{proof}

\begin{lemma}[Preimages of the charts are affine]
  \label{lem:preimage_chart_affine}
  \lean{AlgebraicGeometry.isAffineOpen_preimage_chartOpen}
  \uses{def:P1_chartOpen}
  \leanok
  Let \(\pi : Y \to \PP^1\) be an affine morphism (for instance a finite one). Then
  \(\pi^{-1}(U_i)\) is an affine open of \(Y\) for \(i \in \{0,1\}\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_chartOpen_affine}
  The charts are affine (\ref{lem:P1_chartOpen_affine}), and the preimage of an affine open
  under an affine morphism is affine.
\end{proof}

\begin{lemma}[Preimages of the charts cover]
  \label{lem:preimage_chart_sup}
  \lean{AlgebraicGeometry.preimage_chartOpen_sup}
  \uses{def:P1_chartOpen}
  \leanok
  For any morphism \(\pi : Y \to \PP^1\), the preimages of the two standard charts cover
  \(Y\): \(\pi^{-1}(U_0) \cup \pi^{-1}(U_1) = Y\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_chartOpen_sup}
  Preimages of a cover form a cover (\ref{lem:P1_chartOpen_sup}).
\end{proof}

\begin{lemma}[Module-finiteness over the charts]
  \label{lem:finite_app_chart}
  \lean{AlgebraicGeometry.finite_app_chartOpen}
  \uses{def:P1_chartOpen}
  \leanok
  Let \(\pi : Y \to \PP^1\) be a finite morphism. For \(i \in \{0,1\}\), the induced ring
  homomorphism \(\Gamma(\PP^1, U_i) \to \Gamma(Y, \pi^{-1}(U_i))\) is module-finite. (By
  \ref{def:P1_chartSectionsEquiv0}--\ref{def:P1_chartSectionsEquiv1}, the source is the
  polynomial ring \(k[t]\).)
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_chartOpen_affine}
  A finite morphism induces module-finite maps on sections over affine opens; the charts are
  affine by \ref{lem:P1_chartOpen_affine}.
\end{proof}

\begin{lemma}[Module-finiteness over the overlap]
  \label{lem:finite_app_overlap}
  \lean{AlgebraicGeometry.finite_app_overlap}
  \uses{lem:P1_chartOpen_inf}
  \leanok
  Let \(\pi : Y \to \PP^1\) be a finite morphism. The induced ring homomorphism
  \(\Gamma(\PP^1, U_0 \cap U_1) \to \Gamma(Y, \pi^{-1}(U_0 \cap U_1))\) is module-finite.
  (By \ref{def:P1_overlapSectionsEquiv}, the source is the Laurent polynomial ring
  \(k[T,T^{-1}]\).)
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_overlap_affine}
  As in \ref{lem:finite_app_chart}, with the overlap affine by \ref{lem:P1_overlap_affine}.
\end{proof}

\section{An affine two-chart cover of the curve, and its stability under base change}

The two standard charts of \(\PP^1\) pull back, along a finite morphism \(C \to \PP^1\), to a
cover of the curve \(C\) by two affine opens with affine overlap. This section records that
cover as a structure in its own right, together with its stability under base change of the
test algebra.

\begin{definition}[Affine two-chart cover]
  \label{def:AffineTwoCover}
  \lean{AlgebraicGeometry.Scheme.AffineTwoCover}
  \leanok
  Let \(Y\) be a scheme. An \emph{affine two-chart cover} of \(Y\) is a pair of affine open
  subschemes \(V_0, V_1 \subseteq Y\) with \(V_0 \cup V_1 = Y\), whose overlap \(V_0 \cap V_1\)
  is again affine.
\end{definition}

\begin{theorem}[Existence of an affine two-chart cover of the curve]
  \label{thm:AffineTwoCover_nonempty_of_curve}
  \lean{AlgebraicGeometry.Scheme.AffineTwoCover.nonempty_of_curve}
  \uses{def:AffineTwoCover, thm:exists_finite_toP1, lem:preimage_chart_affine,
    lem:preimage_chart_sup, lem:P1_chartOpen_inf, lem:P1_overlap_affine}
  \leanok
  Let \(C\) be a smooth, proper, geometrically irreducible curve over a field \(k\). Then \(C\)
  admits an affine two-chart cover.
\end{theorem}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:exists_finite_toP1} there is a finite morphism \(\pi : C \to \PP^1\) over
  \(k\). Take \(V_0 := \pi^{-1}(U_0)\) and \(V_1 := \pi^{-1}(U_1)\), the preimages of the two
  standard charts of \(\PP^1\) (Definition~\ref{def:P1_chartOpen}); each is affine, since \(\pi\)
  is finite, hence affine, and preimages of affine opens under affine morphisms are affine
  (Lemma~\ref{lem:preimage_chart_affine}). The preimages cover \(C\)
  (Lemma~\ref{lem:preimage_chart_sup}). For the overlap, preimage commutes with intersection, so
  \(V_0 \cap V_1 = \pi^{-1}(U_0 \cap U_1)\); since \(U_0 \cap U_1 = D_+(X_0X_1)\)
  (Lemma~\ref{lem:P1_chartOpen_inf}) is affine (Lemma~\ref{lem:P1_overlap_affine}), its preimage
  \(V_0 \cap V_1\) is affine as well, again because preimages of affine opens under the affine
  morphism \(\pi\) are affine. Hence \((V_0, V_1)\) is an affine two-chart cover of \(C\).
\end{proof}

\begin{theorem}[Base change of an affine two-chart cover]
  \label{thm:AffineTwoCover_pullbackProd}
  \lean{AlgebraicGeometry.Scheme.AffineTwoCover.pullbackProd}
  \uses{def:AffineTwoCover}
  \leanok
  Let \(k\) be a field, \(C\) an object of \(\Over(\Spec k)\), and \(D = (V_0,V_1)\) an affine
  two-chart cover of the underlying scheme of \(C\). Let \(R\) be a commutative \(k\)-algebra,
  and write \(C \otimes \Spec R\) for the fibre product of \(C\) with the object \(\Spec R\) of
  \(\Over(\Spec k)\) (the \(k\)-algebra structure of \(R\) making \(\Spec R\) an object of
  \(\Over(\Spec k)\)), with first projection \(\mathrm{pr}_1 : C \otimes \Spec R \to C\). Then
  \(\bigl(\mathrm{pr}_1^{-1}(V_0),\ \mathrm{pr}_1^{-1}(V_1)\bigr)\) is an affine two-chart cover
  of \(C \otimes \Spec R\).
\end{theorem}
\begin{proof}
  \leanok
  The projection \(\mathrm{pr}_1\) is an affine morphism: it is the base change, along the
  structure morphism of \(C\), of the structure morphism \(\Spec R \to \Spec k\) (a morphism
  between affine schemes, hence affine), and affineness of morphisms is stable under base
  change. Preimages of affine opens under an affine morphism are affine, so
  \(\mathrm{pr}_1^{-1}(V_0)\) and \(\mathrm{pr}_1^{-1}(V_1)\) are affine. Preimage commutes with
  union and with intersection, so these two preimages cover \(C \otimes \Spec R\) (since
  \(V_0 \cup V_1 = C\)) and their overlap is \(\mathrm{pr}_1^{-1}(V_0 \cap V_1)\), the preimage
  of the affine overlap of \(D\), hence itself affine. Thus the two preimages form an affine
  two-chart cover of \(C \otimes \Spec R\).
\end{proof}

\section{Product charts on a fibre product}

Let \(X\) and \(T\) be objects of \(\Over(\Spec k)\), with the two projections
\(\mathrm{fst} \colon X \otimes T \to X\) and \(\mathrm{snd} \colon X \otimes T \to T\)
exhibiting the underlying scheme of the fibre product \(X \otimes T\) as
\(X \times_{\Spec k} T\). For opens \(U\) of \(X\) and \(V\) of \(T\) this section builds the
open \(\mathfrak W(U,V) \subseteq X \otimes T\) cut out by the two projections and, for \(U, V\)
affine, identifies its section ring with the tensor product \(\Gamma(X,U) \otimes_k \Gamma(T,V)\).
All \(k\)-algebra structures on section rings are those obtained by pulling back along the
structure morphism to \(\Spec k\).

\begin{definition}[The product chart]
  \label{def:productChart}
  \lean{AlgebraicGeometry.Over.productChart, AlgebraicGeometry.Over.isAffineOpen_productChart}
  \leanok
  For opens \(U\) of \(X\) and \(V\) of \(T\), the \emph{product chart} is the open
  \[
    \mathfrak W(U,V) \;:=\; \mathrm{fst}^{-1}(U) \cap \mathrm{snd}^{-1}(V) \;\subseteq\; X \otimes T .
  \]
  It is monotone in \(U\) and \(V\). If \(U\) and \(V\) are affine, then \(\mathfrak W(U,V)\) is
  affine.
\end{definition}
\begin{proof}
  \leanok
  Monotonicity follows from monotonicity of preimages and of intersections. For affineness, the
  two projections exhibit \(X \otimes T\) as the fibre product \(X \times_{\Spec k} T\).
  Restricting this cartesian square to the opens \(U \subseteq X\), \(V \subseteq T\) and the
  whole base \(\Spec k\) presents the restriction of \(X \otimes T\) to
  \(\mathrm{fst}^{-1}(U) \cap \mathrm{snd}^{-1}(V) = \mathfrak W(U,V)\) as the fibre product
  \(U \times_{\Spec k} V\) of the restricted schemes. When \(U\), \(V\) and the base \(\Spec k\)
  are affine, this is a fibre product of affine schemes over an affine scheme, hence affine; so
  \(\mathfrak W(U,V)\) is an affine open.
\end{proof}

\begin{definition}[The sections identification]
  \label{def:productChartSections}
  \lean{AlgebraicGeometry.Over.isPushout_productChartSections,
    AlgebraicGeometry.Over.productChartSections,
    AlgebraicGeometry.Over.productChartSectionsAlgEquiv,
    AlgebraicGeometry.Over.productChartSections_tmul,
    AlgebraicGeometry.Over.productChartSections_naturality}
  \uses{def:productChart}
  \leanok
  Let \(U\) and \(V\) be affine. The square of section rings
  \[
    \begin{array}{ccc}
      \Gamma(\Spec k, \struct{}) & \longrightarrow & \Gamma(X, U) \\
      \downarrow & & \downarrow \\
      \Gamma(T, V) & \longrightarrow & \Gamma\bigl(X \otimes T,\ \mathfrak W(U,V)\bigr)
    \end{array}
  \]
  --- the top and left edges the pullbacks along the two structure morphisms to \(\Spec k\), the
  bottom and right edges the two projection pullbacks \(\mathrm{fst}^\sharp\),
  \(\mathrm{snd}^\sharp\) --- is a pushout of commutative rings. Since
  \(\Gamma(\Spec k, \struct{}) = k\), it follows that there is a \(k\)-algebra isomorphism
  \[
    \Gamma(X, U) \otimes_k \Gamma(T, V) \;\xrightarrow{\ \sim\ }\;
      \Gamma\bigl(X \otimes T,\ \mathfrak W(U,V)\bigr), \qquad
      s \otimes t \;\longmapsto\; \mathrm{fst}^\sharp(s) \cdot \mathrm{snd}^\sharp(t),
  \]
  natural in restriction in both factors: for affine opens \(U' \subseteq U\) and
  \(V' \subseteq V\), restricting an identified section to \(\mathfrak W(U', V')\) equals
  identifying the section obtained by restricting the two tensor factors to \(U'\) and \(V'\).
\end{definition}
\begin{proof}
  \leanok
  The square is a pushout by the base-change theorem for the sections of a fibre product, in the
  affine case: for a cartesian square of schemes and compatible opens over which the base and the
  two source opens are affine, the induced square of section rings is a pushout; here the base
  \(\Spec k\) and the opens \(U\), \(V\) are affine, and no flatness hypothesis is needed. On the
  other hand the tensor product \(\Gamma(X,U) \otimes_k \Gamma(T,V)\) is the pushout of the span
  \(k \to \Gamma(X,U)\), \(k \to \Gamma(T,V)\) of \(k\)-algebra structure maps. Comparing the two
  pushouts of this common span yields the displayed \(k\)-algebra isomorphism; it sends the two
  coprojections \(s \otimes 1\) and \(1 \otimes t\) to \(\mathrm{fst}^\sharp(s)\) and
  \(\mathrm{snd}^\sharp(t)\), hence a pure tensor \(s \otimes t = (s \otimes 1)(1 \otimes t)\) to
  the product \(\mathrm{fst}^\sharp(s) \cdot \mathrm{snd}^\sharp(t)\). Naturality is checked on
  pure tensors: both sides send \(s \otimes t\) to the restriction of
  \(\mathrm{fst}^\sharp(s) \cdot \mathrm{snd}^\sharp(t)\) to \(\mathfrak W(U',V')\), because
  projection pullback commutes with restriction of sections.
\end{proof}

\begin{theorem}[The lift-app rule]
  \label{thm:appLE_productChartSections}
  \lean{AlgebraicGeometry.Over.appLE_productChartSections_tmul,
    AlgebraicGeometry.Over.appLE_productChartSections_tmul_lift,
    AlgebraicGeometry.Over.appLE_productChartSections_sub}
  \uses{def:productChartSections}
  \leanok
  Let \(U\), \(V\) be affine and let \(q \colon Z \to X \otimes T\) be a morphism of
  \(\Over(\Spec k)\) with components \(a := \mathrm{fst} \circ q \colon Z \to X\) and
  \(b := \mathrm{snd} \circ q \colon Z \to T\). Then on any open \(W\) of \(Z\) contained in
  \(q^{-1}\mathfrak W(U,V)\), in \(a^{-1}(U)\) and in \(b^{-1}(V)\), the pullback \(q^\sharp\)
  sends the identified pure tensor and its difference shape to
  \[
    q^\sharp\bigl(s \otimes t\bigr) = a^\sharp(s) \cdot b^\sharp(t), \qquad
    q^\sharp\bigl(s \otimes 1 - 1 \otimes t\bigr) = a^\sharp(s) - b^\sharp(t).
  \]
  In particular, for the morphism \(\langle a, b\rangle \colon Z \to X \otimes T\) into the
  product determined by two maps \(a \colon Z \to X\), \(b \colon Z \to T\), the pullback
  \(\langle a, b\rangle^\sharp\) sends \(s \otimes t\) to \(a^\sharp(s) \cdot b^\sharp(t)\).
\end{theorem}
\begin{proof}
  \leanok
  The identification sends \(s \otimes t\) to
  \(\mathrm{fst}^\sharp(s) \cdot \mathrm{snd}^\sharp(t)\)
  (Definition~\ref{def:productChartSections}). Pulling back along \(q\) and using functoriality
  of section pullback, \(q^\sharp \circ \mathrm{fst}^\sharp = (\mathrm{fst} \circ q)^\sharp = a^\sharp\)
  and \(q^\sharp \circ \mathrm{snd}^\sharp = b^\sharp\) over the opens in question, so
  \(q^\sharp(s \otimes t) = a^\sharp(s) \cdot b^\sharp(t)\). The difference formula follows by
  additivity together with \(s \otimes 1 \mapsto a^\sharp(s)\), \(1 \otimes t \mapsto b^\sharp(t)\)
  and \(a^\sharp(1) = b^\sharp(1) = 1\). For \(\langle a,b\rangle\) one has
  \(\mathrm{fst} \circ \langle a,b\rangle = a\) and \(\mathrm{snd} \circ \langle a,b\rangle = b\),
  so the general rule applies with \(q = \langle a, b\rangle\).
\end{proof}

\begin{lemma}[Basic open of a pure tensor]
  \label{lem:basicOpen_productChartSections_tmul}
  \lean{AlgebraicGeometry.Over.basicOpen_productChartSections_tmul}
  \uses{def:productChart, def:productChartSections}
  \leanok
  Let \(U\), \(V\) be affine, \(s \in \Gamma(X,U)\) and \(t \in \Gamma(T,V)\). The basic open of
  the identified pure tensor is the product chart of the two factor basic opens:
  \[
    D\bigl(\mathrm{fst}^\sharp(s) \cdot \mathrm{snd}^\sharp(t)\bigr)
      \;=\; \mathfrak W\bigl(D(s),\, D(t)\bigr).
  \]
\end{lemma}
\begin{proof}
  \leanok
  The basic open of a product is the intersection of the two basic opens, and the basic open of a
  pullback \(\mathrm{fst}^\sharp(s)\) is the preimage \(\mathrm{fst}^{-1}(D(s))\) of the basic open
  of \(s\) (likewise for \(\mathrm{snd}^\sharp(t)\)). Hence
  \(D(\mathrm{fst}^\sharp(s) \cdot \mathrm{snd}^\sharp(t)) = \mathrm{fst}^{-1}(D(s)) \cap \mathrm{snd}^{-1}(D(t))
  = \mathfrak W(D(s), D(t))\), using \(D(s) \subseteq U\) and \(D(t) \subseteq V\).
\end{proof}

\begin{theorem}[Sections over a basic open localize the tensor ring]
  \label{thm:isLocalization_away_basicOpen_productChartSections}
  \lean{AlgebraicGeometry.Over.isLocalization_away_basicOpen_productChartSections,
    AlgebraicGeometry.Over.isAffineOpen_basicOpen_productChartSections}
  \uses{def:productChart, def:productChartSections}
  \leanok
  Let \(U\), \(V\) be affine and \(x \in \Gamma(X,U) \otimes_k \Gamma(T,V)\); write \(\xi\) for
  the section of \(\mathfrak W(U,V)\) identified with \(x\). Then the basic open
  \(D(\xi) \subseteq \mathfrak W(U,V)\) is affine, and its section ring, regarded as a
  \(\Gamma(X,U) \otimes_k \Gamma(T,V)\)-algebra through the identification followed by restriction
  to \(D(\xi)\), is the localization of \(\Gamma(X,U) \otimes_k \Gamma(T,V)\) away from \(x\).
\end{theorem}
\begin{proof}
  \leanok
  The chart \(\mathfrak W(U,V)\) is affine (Definition~\ref{def:productChart}), so a basic open of
  it is affine, and the section ring over \(D(\xi)\) is the localization of
  \(\Gamma(X \otimes T, \mathfrak W(U,V))\) away from \(\xi\). Transporting along the ring
  isomorphism of Definition~\ref{def:productChartSections}, which carries \(x\) to \(\xi\) and the
  powers of \(x\) to the powers of \(\xi\), identifies this with the localization of
  \(\Gamma(X,U) \otimes_k \Gamma(T,V)\) away from \(x\).
\end{proof}

\section{The diagonal of the curve square}

Fix an object \(C\) of \(\Over(\Spec k)\) and form the fibre-product square \(C \otimes C\) with
its two projections \(\mathrm{fst}, \mathrm{snd} \colon C \otimes C \to C\). The diagonal is the
graph of the identity; when \(C\) is separated over \(\Spec k\) it is a closed immersion, and its
image is the closed set along which the per-chart local equation of the next section cuts out the
diagonal.

\begin{definition}[The diagonal of the curve square]
  \label{def:diagonal}
  \lean{AlgebraicGeometry.Over.diagonal,
    AlgebraicGeometry.Over.isClosedImmersion_diagonal_left,
    AlgebraicGeometry.Over.isClosed_range_diagonal,
    AlgebraicGeometry.Over.diagonalComplement,
    AlgebraicGeometry.Over.coe_support_ker_diagonal,
    AlgebraicGeometry.Over.diagonal_preimage_productChart}
  \uses{def:productChart}
  \leanok
  \source{kleiman-picard}
  The \emph{diagonal} of \(C \otimes C\) is the morphism into the product determined by the
  identity in both components,
  \[
    \delta \;:=\; \langle \id_C, \id_C \rangle \colon C \longrightarrow C \otimes C, \qquad
    \mathrm{fst} \circ \delta = \id_C, \quad \mathrm{snd} \circ \delta = \id_C .
  \]
  For opens \(U, V\) of \(C\) its preimage of a product chart is the intersection of the factors,
  \(\delta^{-1}\mathfrak W(U,V) = U \cap V\). If moreover \(C\) is separated over \(\Spec k\),
  then \(\delta\) is a closed immersion; its image \(\Delta := \delta(C)\) is closed, with open
  complement \(\Delta^{\mathrm{c}} := (C \otimes C) \setminus \Delta\); and the support of the
  kernel ideal sheaf of \(\delta\) is exactly \(\Delta\).
\end{definition}
\begin{proof}
  \leanok
  The morphism \(\langle \id_C, \id_C\rangle\) is the unique one with both composites equal to
  \(\id_C\), by the universal property of the product. A point \(z\) lies in
  \(\delta^{-1}\mathfrak W(U,V)\) iff \(\mathrm{fst}(\delta z) \in U\) and
  \(\mathrm{snd}(\delta z) \in V\); since \(\mathrm{fst} \circ \delta = \mathrm{snd} \circ \delta = \id_C\),
  this means \(z \in U\) and \(z \in V\), i.e. \(z \in U \cap V\).

  Now assume \(C\) separated. The second projection \(\mathrm{snd} \colon C \otimes C \to C\) is
  the base change of the structure morphism \(C \to \Spec k\) along itself, hence separated
  because \(C\) is. The composite \(\mathrm{snd} \circ \delta = \id_C\) is a closed immersion; and
  if a composite \(g \circ f\) is a closed immersion and \(g\) is separated, then \(f\) is a
  closed immersion. Applying this with \(f = \delta\), \(g = \mathrm{snd}\) shows \(\delta\) is a
  closed immersion. A closed immersion is a closed embedding, so its image \(\Delta\) is closed
  and \(\Delta^{\mathrm{c}}\) is open. Finally, the support of the kernel ideal sheaf of a
  quasi-compact morphism is the closure of its image; since \(\Delta\) is closed, this support
  equals \(\Delta\).
\end{proof}

\section{The per-chart local equation of the diagonal}

Fix an affine open \(U\) of \(C\) and write \(B := \Gamma(C, U)\). Suppose \(B\) carries the
abstract \'etale-coordinate data of Definition~\ref{def:diagonalSetup} and
Theorem~\ref{thm:exists_idempotent_lift}: a \(k[X]\)-algebra structure making \(k \to k[X] \to B\)
a tower, an \'etale coordinate \(u \in B\) (the image of \(X\)), and an idempotent lift
\(\mathrm{elift} \in B \otimes_k B\) whose base change to \(B \otimes_{k[X]} B\) is idempotent and
generates the \(k[X]\)-diagonal ideal. On such a chart the diagonal of \(C \otimes C\) is, in one
affine piece, the vanishing locus of the single diagonal equation \(u \otimes 1 - 1 \otimes u\);
this section makes that precise and records the regularity of the equation.

\begin{definition}[The diagonal member and its equation]
  \label{def:diagonalChart}
  \lean{AlgebraicGeometry.Over.diagonalChart,
    AlgebraicGeometry.Over.isAffineOpen_diagonalChart,
    AlgebraicGeometry.Over.diagonalChartEqn,
    AlgebraicGeometry.Over.diagonal_appLE_productChartSections,
    AlgebraicGeometry.Over.diagonal_preimage_diagonalChart}
  \uses{def:productChart, def:productChartSections, def:diagonal, def:diagonalSetup}
  \leanok
  Let \(\vartheta \in \Gamma(C \otimes C, \mathfrak W(U,U))\) be the section identified with
  \(1 - \mathrm{elift}\) (Definition~\ref{def:productChartSections}). The \emph{diagonal member}
  attached to the chart \(U\) is the affine basic open
  \[
    \mathfrak D(U) \;:=\; D(\vartheta) \;\subseteq\; \mathfrak W(U,U).
  \]
  The \emph{diagonal equation} \(e_U \in \Gamma(C \otimes C, \mathfrak D(U))\) is the restriction
  to \(\mathfrak D(U)\) of the section of \(\mathfrak W(U,U)\) identified with the diagonal
  generator \(u \otimes 1 - 1 \otimes u\). Writing \(\xi_x\) for the section of
  \(\mathfrak W(U,U)\) identified with \(x \in B \otimes_k B\), the pullback along the diagonal is
  multiplication: over \(\delta^{-1}\mathfrak W(U,U) = U\),
  \[
    \delta^\sharp(\xi_x) \;=\; \mu(x) \;\in\; \Gamma(C, U), \qquad
    \mu \colon B \otimes_k B \to B, \quad x \otimes y \mapsto xy .
  \]
  Consequently, if \(\mu(\mathrm{elift}) = 0\), then \(\delta^{-1}\mathfrak D(U) = U\).
\end{definition}
\begin{proof}
  \leanok
  \uses{thm:appLE_productChartSections, thm:isLocalization_away_basicOpen_productChartSections}
  Affineness of \(\mathfrak D(U)\) is affineness of a basic open of the affine chart
  \(\mathfrak W(U,U)\) (Theorem~\ref{thm:isLocalization_away_basicOpen_productChartSections}). For
  the pullback formula, apply the lift-app rule (Theorem~\ref{thm:appLE_productChartSections}) to
  \(q = \delta\), whose components are \(\mathrm{fst} \circ \delta = \mathrm{snd} \circ \delta = \id_C\):
  on a pure tensor \(s \otimes t\) it gives
  \(\delta^\sharp(\xi_{s \otimes t}) = \id^\sharp(s) \cdot \id^\sharp(t) = st = \mu(s \otimes t)\),
  and both sides are additive in \(x\), so \(\delta^\sharp(\xi_x) = \mu(x)\) for every \(x\).
  Finally, \(\mathfrak D(U) = D(\vartheta)\) and \(\vartheta = \xi_{1 - \mathrm{elift}}\), so its
  \(\delta\)-preimage is the basic open of
  \(\delta^\sharp(\vartheta) = \mu(1 - \mathrm{elift}) = 1 - \mu(\mathrm{elift}) = 1\) when
  \(\mu(\mathrm{elift}) = 0\); the basic open of \(1\) is everything, whence
  \(\delta^{-1}\mathfrak D(U) = \delta^{-1}\mathfrak W(U,U) = U \cap U = U\) using
  \(\delta^{-1}\mathfrak W(U,U) = U\) (Definition~\ref{def:diagonal}).
\end{proof}

\begin{theorem}[The per-chart kernel of the diagonal is principal]
  \label{thm:diagonal_ker_ideal_diagonalChart}
  \lean{AlgebraicGeometry.Over.diagonal_ker_ideal_diagonalChart}
  \uses{def:diagonal, def:diagonalChart}
  \leanok
  \source{kleiman-picard}
  Assume \(C\) is separated over \(\Spec k\). On the diagonal member \(\mathfrak D(U)\) the kernel
  ideal sheaf of the diagonal is principal, generated by the diagonal equation:
  \[
    \bigl(\ker \delta\bigr)\bigl(\mathfrak D(U)\bigr) \;=\; (e_U).
  \]
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:isLocalization_away_basicOpen_productChartSections, thm:ker_map_localization_eq,
    thm:exists_diagonalLocalization, def:diagonalSetup}
  Because the base change of \(\mathrm{elift}\) generates the \(k[X]\)-diagonal ideal, the
  multiplication kills it, \(\mu(\mathrm{elift}) = 0\)
  (Theorem~\ref{thm:exists_diagonalLocalization}); hence \(\delta^{-1}\mathfrak D(U) = U\)
  (Definition~\ref{def:diagonalChart}), and restriction of sections along this equality of opens
  is a ring isomorphism, in particular injective. On the affine open \(\mathfrak D(U)\) the value
  of the kernel ideal sheaf is the kernel of the section map
  \(\delta^\sharp \colon \Gamma(C \otimes C, \mathfrak D(U)) \to \Gamma(C, U)\).

  By Theorem~\ref{thm:isLocalization_away_basicOpen_productChartSections} the ring
  \(\Gamma(C \otimes C, \mathfrak D(U))\) is the localization of \(B \otimes_k B\) away from
  \(1 - \mathrm{elift}\), through the identification followed by restriction; write
  \(\lambda \colon B \otimes_k B \to \Gamma(C \otimes C, \mathfrak D(U))\) for its structure map,
  so that \(e_U = \lambda(u \otimes 1 - 1 \otimes u)\) and, by the pullback formula of
  Definition~\ref{def:diagonalChart}, \(\delta^\sharp(\lambda(z)) = \mu(z)\big|_{U}\) for all
  \(z \in B \otimes_k B\).

  \emph{The equation lies in the kernel.} One has
  \(\delta^\sharp(e_U) = \mu(u \otimes 1 - 1 \otimes u)\big|_{U} = 0\), because
  \(\mu(u \otimes 1 - 1 \otimes u) = u - u = 0\) (Definition~\ref{def:diagonalSetup}); so
  \((e_U) \subseteq (\ker \delta)(\mathfrak D(U))\).

  \emph{Every kernel element is a multiple of the equation.} Let \(s\) lie in the kernel. As
  \(\Gamma(C \otimes C, \mathfrak D(U))\) is a localization away from \(1 - \mathrm{elift}\), write
  \(s \cdot \lambda(m) = \lambda(r)\) with \(r \in B \otimes_k B\) and \(m\) a power of
  \(1 - \mathrm{elift}\), whose image \(\lambda(m)\) is a unit. Applying \(\delta^\sharp\),
  \(\delta^\sharp(\lambda(r)) = \delta^\sharp(s) \cdot \delta^\sharp(\lambda(m)) = 0\); but
  \(\delta^\sharp(\lambda(r)) = \mu(r)\big|_{U}\) and restriction along
  \(\delta^{-1}\mathfrak D(U) = U\) is injective, so \(\mu(r) = 0\), i.e. \(r\) lies in the
  \(k\)-diagonal ideal \(\ker \mu\). By the localized principality of the \(k\)-diagonal ideal
  (Theorem~\ref{thm:ker_map_localization_eq}), the extension of \(\ker \mu\) along \(\lambda\) is
  generated by \(\lambda(u \otimes 1 - 1 \otimes u) = e_U\); hence \(\lambda(r) \in (e_U)\). Since
  \(\lambda(m)\) is a unit and \(s = \lambda(r) \cdot \lambda(m)^{-1}\), we conclude \(s \in (e_U)\).
\end{proof}

\begin{lemma}[Germs of a regular section on an affine open]
  \label{lem:affineOpen_germ_mem_nonZeroDivisors}
  \lean{AlgebraicGeometry.IsAffineOpen.germ_mem_nonZeroDivisors}
  \uses{lem:flat_mem_nonZeroDivisors}
  \leanok
  Let \(W\) be an affine open of a scheme \(X\) and \(s \in \Gamma(X, W)\) a nonzerodivisor. Then
  for every point \(y \in W\) the germ of \(s\) at \(y\) is a nonzerodivisor of the stalk
  \(\struct{X, y}\).
\end{lemma}
\begin{proof}
  \leanok
  On an affine open the stalk \(\struct{X, y}\) is the localization of \(\Gamma(X, W)\) at the
  prime corresponding to \(y\), and the germ map is the localization map. A localization is flat,
  so the germ map is a flat ring homomorphism, and a flat ring homomorphism carries the
  nonzerodivisor \(s\) to a nonzerodivisor (Lemma~\ref{lem:flat_mem_nonZeroDivisors}).
\end{proof}

\begin{theorem}[Regularity of the diagonal equation]
  \label{thm:diagonalChartEqn_regular}
  \lean{AlgebraicGeometry.Over.diagonalChartEqn_mem_nonZeroDivisors,
    AlgebraicGeometry.Over.germ_diagonalChartEqn_mem_nonZeroDivisors}
  \uses{def:diagonalChart}
  \leanok
  Assume in addition that \(B\) is flat over \(k[X]\). Then the diagonal equation \(e_U\) is a
  nonzerodivisor of \(\Gamma(C \otimes C, \mathfrak D(U))\), and its germ at every point of
  \(\mathfrak D(U)\) is a nonzerodivisor of the corresponding stalk.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:diagonal_regularity_engine, lem:flat_mem_nonZeroDivisors,
    lem:affineOpen_germ_mem_nonZeroDivisors, def:productChartSections,
    thm:isLocalization_away_basicOpen_productChartSections}
  With \(B\) flat over \(k[X]\), the diagonal generator \(u \otimes 1 - 1 \otimes u\) is a
  nonzerodivisor of \(B \otimes_k B\) (Theorem~\ref{thm:diagonal_regularity_engine}). The structure
  map \(\lambda \colon B \otimes_k B \to \Gamma(C \otimes C, \mathfrak D(U))\) factors as the ring
  isomorphism of Definition~\ref{def:productChartSections} followed by the localization to the
  basic open \(\mathfrak D(U)\)
  (Theorem~\ref{thm:isLocalization_away_basicOpen_productChartSections}); both are flat, so
  \(\lambda\) is flat. A flat ring homomorphism preserves nonzerodivisors
  (Lemma~\ref{lem:flat_mem_nonZeroDivisors}), and \(e_U = \lambda(u \otimes 1 - 1 \otimes u)\),
  so \(e_U\) is a nonzerodivisor. Since \(\mathfrak D(U)\) is affine
  (Definition~\ref{def:diagonalChart}), the germ regularity follows from the section regularity by
  Lemma~\ref{lem:affineOpen_germ_mem_nonZeroDivisors}.
\end{proof}

\begin{theorem}[The diagonal member meets the diagonal complement in a basic open]
  \label{thm:diagonalChart_inf_diagonalComplement}
  \lean{AlgebraicGeometry.Over.diagonalChart_inf_diagonalComplement,
    AlgebraicGeometry.Over.isUnit_res_diagonalChartEqn}
  \uses{def:diagonal, def:diagonalChart}
  \leanok
  Assume \(C\) is separated over \(\Spec k\). The overlap of the diagonal member with the diagonal
  complement is the basic open of the diagonal equation,
  \[
    \mathfrak D(U) \cap \Delta^{\mathrm{c}} \;=\; D(e_U),
  \]
  and the restriction of \(e_U\) to this overlap is a unit.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:diagonal_ker_ideal_diagonalChart}
  On the affine \(\mathfrak D(U)\) the kernel ideal sheaf of the diagonal is generated by \(e_U\)
  (Theorem~\ref{thm:diagonal_ker_ideal_diagonalChart}), so the support of the kernel ideal sheaf,
  intersected with \(\mathfrak D(U)\), is the zero locus \(V(e_U) \cap \mathfrak D(U)\). That
  support is the diagonal \(\Delta\) (Definition~\ref{def:diagonal}), whence
  \(\Delta \cap \mathfrak D(U) = V(e_U) \cap \mathfrak D(U)\). Taking complements inside
  \(\mathfrak D(U)\) gives
  \(\mathfrak D(U) \cap \Delta^{\mathrm{c}} = \mathfrak D(U) \setminus V(e_U) = D(e_U)\). A section
  is a unit on its own basic open, so the restriction of \(e_U\) to
  \(D(e_U) = \mathfrak D(U) \cap \Delta^{\mathrm{c}}\) is a unit.
\end{proof}

\section{The frozen étale-coordinate chart data}

The per-chart local equation of the previous section runs on any affine chart carrying the
abstract étale-coordinate data of Definition~\ref{def:diagonalSetup}. To assemble a single
divisor on the whole square \(C \otimes C\) we must \emph{freeze} one such chart, with its
coordinate and idempotent lift, per point of the curve; this section makes the choice and
records the per-chart deliverables specialised to it.

\begin{definition}[The frozen chart data of a smooth curve]
  \label{def:diagonalChartData}
  \lean{AlgebraicGeometry.Over.exists_diagonalChartAt, AlgebraicGeometry.Over.DiagonalChartData,
    AlgebraicGeometry.Over.diagonalChartData,
    AlgebraicGeometry.Over.DiagonalChartData.elift,
    AlgebraicGeometry.Over.DiagonalChartData.lmul'_elift,
    AlgebraicGeometry.Over.DiagonalChartData.isIdempotentElem_baseChange_elift,
    AlgebraicGeometry.Over.DiagonalChartData.ker_lmul'_eq_span_baseChange_elift}
  \uses{def:diagonalSetup, thm:exists_diagonalLocalization}
  \leanok
  Let \(C\) be smooth of relative dimension one over \(\Spec k\). Then every point \(p\) of \(C\)
  has an affine open \(U \ni p\) whose section ring \(B := \Gamma(C, U)\) carries an étale
  \(k[X]\)-algebra structure --- an étale coordinate \(u \in B\) --- compatible with the section
  \(k\)-algebra structure (making \(k \to k[X] \to B\) a tower).

  A \emph{chart datum} for \(C\) is a choice, one per point \(p\), of such a chart
  \(\mathrm{chart}(p) \ni p\) with its étale coordinate. On each chart the coordinate is flat,
  formally unramified and essentially of finite type, so the packaged diagonal localisation
  (Theorem~\ref{thm:exists_diagonalLocalization}) supplies a frozen idempotent lift
  \(\mathrm{elift}(p) \in B \otimes_k B\) with \(\mu_k(\mathrm{elift}(p)) = 0\), whose base change
  is idempotent and generates the \(k[X]\)-diagonal ideal.
\end{definition}
\begin{proof}
  \leanok
  Smoothness of relative dimension one over the one-point base \(\Spec k\) yields, at each \(p\), a
  standard-smooth affine chart whose section ring is standard smooth of relative dimension one over
  \(\Gamma(\Spec k, \top)\). Transport the base along the ring isomorphism \(k \cong \Gamma(\Spec
  k, \top)\) --- standard-smoothness is stable under composition with a relative-dimension-zero
  isomorphism, dispatching the base-field-versus-\(\Gamma(\Spec k)\) subtlety at the level of ring
  homomorphisms --- to get \(\Gamma(C, U)\) standard smooth of relative dimension one over \(k\).
  The structure theorem for standard-smooth homomorphisms produces an étale factorisation
  \(k[X_1] \to \Gamma(C, U)\) through the one-variable polynomial ring; transporting the source
  along \(k[X_1] \cong k[X]\) gives the étale coordinate. Étaleness entails flatness, formal
  unramifiedness and essential finiteness, the hypotheses under which
  Theorem~\ref{thm:exists_diagonalLocalization} produces the idempotent lift and its properties.
  Choosing one such chart per point gives the chart datum; every point of the curve has one, so a
  datum exists.
\end{proof}

\begin{theorem}[The frozen diagonal equation on a chart]
  \label{thm:diagonalChartData_equation}
  \lean{AlgebraicGeometry.Over.DiagonalChartData.chartEqn,
    AlgebraicGeometry.Over.DiagonalChartData.ker_ideal_eq_span_chartEqn,
    AlgebraicGeometry.Over.DiagonalChartData.germ_chartEqn_mem_nonZeroDivisors,
    AlgebraicGeometry.Over.DiagonalChartData.chartEqn_inf_diagonalComplement,
    AlgebraicGeometry.Over.DiagonalChartData.span_res_chartEqn,
    AlgebraicGeometry.Over.DiagonalChartData.res_chartEqn_mem_nonZeroDivisors}
  \uses{def:diagonalChartData, def:diagonalChart, thm:diagonal_ker_ideal_diagonalChart,
    thm:diagonalChartEqn_regular, thm:diagonalChart_inf_diagonalComplement}
  \leanok
  Fix a chart datum on a separated \(C\) and a point \(p\), and write \(\mathfrak D_p\) for the
  diagonal member \(\mathfrak D(\mathrm{chart}(p))\) and \(e_p\) for its diagonal equation
  (Definition~\ref{def:diagonalChart}) built with the frozen coordinate. Then:
  \begin{itemize}
    \item the kernel ideal sheaf of the diagonal on \(\mathfrak D_p\) is principal, \((\ker
      \delta)(\mathfrak D_p) = (e_p)\);
    \item the germ of \(e_p\) at every point of \(\mathfrak D_p\) is a nonzerodivisor;
    \item the diagonal member meets the diagonal complement in the basic open of the equation,
      \(\mathfrak D_p \cap \Delta^{\mathrm c} = D(e_p)\);
    \item for every affine open \(W \le \mathfrak D_p\), the restriction \(e_p|_W\) generates the
      kernel ideal sheaf there, \(\mathrm{span}\{e_p|_W\} = (\ker \delta)(W)\), and \(e_p|_W\) is a
      nonzerodivisor of \(\Gamma(C \otimes C, W)\).
  \end{itemize}
\end{theorem}
\begin{proof}
  \leanok
  The first three are the per-chart deliverables (Theorems~\ref{thm:diagonal_ker_ideal_diagonalChart},
  \ref{thm:diagonalChartEqn_regular}, \ref{thm:diagonalChart_inf_diagonalComplement}) read on the
  frozen chart, whose coordinate instance is baked into the definition of \(e_p\). For the fourth,
  the ideal sheaf of a closed subscheme is compatible with restriction to a smaller affine open, so
  the principal generator on \(\mathfrak D_p\) restricts to a generator on \(W\): \(\mathrm{span}\{e_p|_W\}
  = (\ker \delta)(W)\). The section regularity of \(e_p|_W\) is the propagation of germ regularity:
  a section whose every germ is a nonzerodivisor is itself a nonzerodivisor, because sections inject
  into the product of their germs; the germs of \(e_p|_W\) are those of \(e_p\), which are
  nonzerodivisors.
\end{proof}

\begin{lemma}[Regular generators of a principal ideal differ by a unit]
  \label{lem:exists_isUnit_of_span_singleton_eq}
  \lean{AlgebraicGeometry.Over.exists_isUnit_of_span_singleton_eq}
  \leanok
  Let \(R\) be a commutative ring and \(a, b \in R\) with \(\mathrm{span}\{a\} = \mathrm{span}\{b\}\).
  If \(a\) is a nonzerodivisor, then \(a\) and \(b\) differ by a unit: there is a unit \(u \in
  R^{\times}\) with \(a = u\,b\).
\end{lemma}
\begin{proof}
  \leanok
  From \(a \in \mathrm{span}\{b\}\) and \(b \in \mathrm{span}\{a\}\) write \(a = c\,b\) and \(b =
  d\,a\). Substituting, \(a = c\,d\,a\), so \((1 - c\,d)\,a = 0\); as \(a\) is a nonzerodivisor this
  forces \(c\,d = 1\), so \(c\) is a unit with inverse \(d\). Taking \(u = c\) gives \(a = u\,b\).
\end{proof}

\begin{definition}[The diagonal pointed cover and its equation]
  \label{def:diagonalCover}
  \lean{AlgebraicGeometry.Over.diagonalCover, AlgebraicGeometry.Over.diagonalEqn,
    AlgebraicGeometry.Over.diagonalCover_opens_of_mem,
    AlgebraicGeometry.Over.diagonalCover_opens_of_notMem,
    AlgebraicGeometry.Over.diagonalEqn_res_of_mem,
    AlgebraicGeometry.Over.diagonalEqn_of_notMem}
  \uses{def:diagonal, def:diagonalChart, def:diagonalChartData, thm:diagonalChartData_equation}
  \leanok
  Fix a chart datum on a separated \(C\). The \emph{diagonal pointed cover} of \(C \otimes C\)
  assigns to a point \(z\):
  \[
    \mathcal U(z) \;=\;
      \begin{cases}
        \mathfrak D_{\mathrm{fst}(z)} & z \in \Delta \ (\text{i.e. } z \text{ in the range of } \delta),\\
        \Delta^{\mathrm c} & z \notin \Delta,
      \end{cases}
  \]
  the diagonal member of the chart at the first projection of \(z\) on the diagonal, the complement
  off it. The \emph{diagonal equation} is \(e_z = e_{\mathrm{fst}(z)}|_{\mathcal U(z)}\) on the
  diagonal and \(e_z = 1\) off it.
\end{definition}
\begin{proof}
  \leanok
  Each assignment is an open containing \(z\): on the diagonal, \(z = \delta(\mathrm{fst}(z))\)
  lies in \(\mathfrak D_{\mathrm{fst}(z)}\) because \(\delta^{-1}\mathfrak D(U) = U\) contains
  \(\mathrm{fst}(z)\) (Definition~\ref{def:diagonalChart}, using \(\mu_k(\mathrm{elift}) = 0\), and
  \(\mathrm{fst}(z) \in \mathrm{chart}(\mathrm{fst}(z))\)); off the diagonal, \(z \in
  \Delta^{\mathrm c}\) by definition of the complement. The equation is well typed by restriction
  along \(\mathcal U(z) = \mathfrak D_{\mathrm{fst}(z)}\), and its stated restriction behaviour is
  the definition unfolded.
\end{proof}

\begin{theorem}[The diagonal as an effective divisor in local equations]
  \label{thm:diagonalLocalEquations}
  \lean{AlgebraicGeometry.Over.diagonalLocalEquationsOfData,
    AlgebraicGeometry.Over.diagonalPicClassOfData,
    AlgebraicGeometry.Over.diagonalLocalEquations, AlgebraicGeometry.Over.diagonalPicClass}
  \uses{def:diagonalCover, thm:diagonalChartData_equation, lem:exists_isUnit_of_span_singleton_eq,
    def:localEquations, def:localEquations_picClass, def:diagonalChartData}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be smooth of relative dimension one and separated over \(\Spec k\). The diagonal cover
  and equation of Definition~\ref{def:diagonalCover} (for the frozen chart datum) form a system of
  local equations (Definition~\ref{def:localEquations}) on \(C \otimes C\), cutting out the
  diagonal \(\Delta\). Its Picard class is the class of the diagonal,
  \[
    \mathrm{diagonalPicClass}(C) \;=\; \struct{C \otimes C}(\Delta) \;\in\; \Pic(C \otimes C).
  \]
\end{theorem}
\begin{proof}
  \leanok
  \emph{Regularity.} On a diagonal member the equation is \(e_p\), germ-regular everywhere
  (Theorem~\ref{thm:diagonalChartData_equation}); off the diagonal it is the constant \(1\), whose
  germs are units, hence nonzerodivisors.

  \emph{Overlap ratios are units.} Consider two cover members over points \(x, y\). If both are on
  the diagonal, their overlap \(W = \mathcal U(x) \cap \mathcal U(y)\) is affine and contained in
  both diagonal members; there both \(e_{\mathrm{fst}(x)}|_W\) and \(e_{\mathrm{fst}(y)}|_W\)
  generate the same kernel ideal sheaf \((\ker \delta)(W)\)
  (Theorem~\ref{thm:diagonalChartData_equation}), and \(e_{\mathrm{fst}(x)}|_W\) is a nonzerodivisor,
  so by Lemma~\ref{lem:exists_isUnit_of_span_singleton_eq} the two differ by a unit. If one is on
  the diagonal and the other off, the overlap lies in \(\mathfrak D \cap \Delta^{\mathrm c} =
  D(e_p)\) (Theorem~\ref{thm:diagonalChartData_equation}), where \(e_p\) restricts to a unit, and
  the off-diagonal equation is \(1\); so the ratio is a unit (or its inverse). If both are off the
  diagonal, both equations are \(1\) and the ratio is \(1\). Thus the data is a local-equation
  system.

  Its Picard class (Definition~\ref{def:localEquations_picClass}) is by construction the class of
  the effective divisor it cuts out, which is the diagonal \(\Delta\); that is, \(\struct{C \otimes
  C}(\Delta)\). The diagonal is an effective (relative Cartier) divisor precisely because \(C\) is
  smooth, matching Kleiman's criterion.
\end{proof}

\section{The graph of a curve point as an effective divisor}

Fix \(C\) smooth of relative dimension one and separated over \(\Spec k\). For a test object \(T\)
and a point \(t \colon T \to C\) (a morphism of \(\Over(\Spec k)\)), the \emph{graph}
\(\Gamma_t \subseteq C \otimes T\) is realised as the pullback of the diagonal divisor along the
graph lift \(\langle \mathrm{fst}, \mathrm{snd} \circ t\rangle \colon C \otimes T \to C \otimes C\).
The pullback of the local-equation system is available once the pulled equations stay regular; this
is the content of the section.

\begin{lemma}[The graph-lift whisker square]
  \label{lem:whiskerLeft_comp_graphLift}
  \lean{AlgebraicGeometry.Over.whiskerLeft_comp_graphLift}
  \leanok
  For \(g \colon T' \to T\) and \(t \colon T \to C\), whiskering the graph lift of \(t\) by
  \(C \lhd g\) is the graph lift of the restricted point \(g \circ t\):
  \[
    (C \lhd g) \circ \langle \mathrm{fst}_{C,T},\, \mathrm{snd}_{C,T} \circ t\rangle
      \;=\; \langle \mathrm{fst}_{C,T'},\, \mathrm{snd}_{C,T'} \circ g \circ t\rangle .
  \]
\end{lemma}
\begin{proof}
  \leanok
  Both sides are maps into the product \(C \otimes C\); by the universal property it suffices to
  compare their two projections. Post-composing with \(\mathrm{fst}\): the left side gives \((C
  \lhd g) \circ \mathrm{fst}_{C,T} = \mathrm{fst}_{C,T'}\), the right side gives
  \(\mathrm{fst}_{C,T'}\). Post-composing with \(\mathrm{snd}\): the left side gives \((C \lhd g)
  \circ \mathrm{snd}_{C,T} \circ t = \mathrm{snd}_{C,T'} \circ g \circ t\) (as \(\mathrm{snd} \circ
  (C \lhd g) = g \circ \mathrm{snd}\)), matching the right side.
\end{proof}

\begin{theorem}[Regularity of the pulled-back diagonal equation]
  \label{thm:graph_pullback_regular}
  \lean{AlgebraicGeometry.Over.graph_pullback_regular}
  \uses{def:diagonalCover, thm:diagonalChartData_equation, def:diagonalChart, def:productChart,
    def:productChartSections, thm:appLE_productChartSections, thm:diagonal_regularity_engine,
    lem:flat_mem_nonZeroDivisors, lem:affineOpen_germ_mem_nonZeroDivisors,
    def:localEquations_pullback, def:diagonalChartData, def:diagonalSetup}
  \leanok
  For a chart datum on a separated \(C\) and a point \(t \colon T \to C\), the pullback of the
  diagonal equation along the graph lift \(q = \langle \mathrm{fst}, \mathrm{snd} \circ t\rangle\)
  is germ-regular at every point of the pullback cover.
\end{theorem}
\begin{proof}
  \leanok
  Fix a point \(y\) of the pullback cover and a point \(z\) of its member. Off the diagonal (i.e.\
  \(q(y) \notin \Delta\)) the diagonal equation at \(q(y)\) is \(1\), so its \(q\)-pullback is
  \(q^{\sharp}(1) = 1\), whose germ is a unit, hence a nonzerodivisor.

  On the diagonal, set \(p_0 = \mathrm{fst}(q(y))\), let \(U = \mathrm{chart}(p_0)\) with étale
  coordinate \(u\), so the member is \(q^{-1}\mathfrak D(U)\). Choose an affine open \(V\) of \(T\)
  with \((\mathrm{snd})(z) \in V \subseteq t^{-1}U\), and pass to the affine product chart
  \(\mathfrak W(U, V)\) (Definition~\ref{def:productChart}) through \(z\); on the overlap \(W\) of
  the member with \(\mathfrak W(U, V)\), the pulled equation restricts to the product-chart section
  of \(u \otimes 1 - 1 \otimes b\), where \(b := t^{\sharp}(u) \in \Gamma(T, V)\). This is the
  lift-app rule (Theorem~\ref{thm:appLE_productChartSections}) for \(q\), whose components are
  \(\mathrm{fst} \circ q = \mathrm{fst}\) and \(\mathrm{snd} \circ q = \mathrm{snd} \circ t\): the
  diagonal generator \(u \otimes 1 - 1 \otimes u\) (Definition~\ref{def:diagonalSetup}) pulls back
  to \(\mathrm{fst}^{\sharp}(u) - (\mathrm{snd} \circ t)^{\sharp}(u) = \mathrm{fst}^{\sharp}(u) -
  \mathrm{snd}^{\sharp}(b)\), i.e.\ the identified \(u \otimes 1 - 1 \otimes b\)
  (Definition~\ref{def:productChartSections}).

  Now \(u \otimes 1 - 1 \otimes b\) is a nonzerodivisor of \(\Gamma(C, U) \otimes_k \Gamma(T, V)\)
  by the regularity engine (Theorem~\ref{thm:diagonal_regularity_engine}), which holds uniformly in
  the second tensor factor \(\Gamma(T, V)\) and the element \(b\) --- no integrality of \(C \otimes
  T\) is used. The product-chart identification is a ring isomorphism, hence flat, so it carries
  this nonzerodivisor to a nonzerodivisor of \(\Gamma(C \otimes T, \mathfrak W(U, V))\)
  (Lemma~\ref{lem:flat_mem_nonZeroDivisors}). Since \(\mathfrak W(U, V)\) is affine, the germ at
  \(z\) is a nonzerodivisor (Lemma~\ref{lem:affineOpen_germ_mem_nonZeroDivisors}); matching this
  germ to the pullback germ across the overlap \(W\) (germs are compatible with restriction) gives
  the claim.
\end{proof}

\begin{definition}[The graph divisor and its Picard class]
  \label{def:graphLocalEquations}
  \lean{AlgebraicGeometry.Over.graphLocalEquations, AlgebraicGeometry.Over.graphPicClass,
    AlgebraicGeometry.Over.graphPicClass_eq}
  \uses{thm:diagonalLocalEquations, def:localEquations_pullback, thm:graph_pullback_regular,
    thm:localEquations_picClass_pullback}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be smooth of relative dimension one and separated over \(\Spec k\), \(T\) a test object
  and \(t \colon T \to C\) a point. The \emph{graph divisor} \(\Gamma_t \subseteq C \otimes T\) is
  cut out by the pullback of the diagonal local-equation system
  (Theorem~\ref{thm:diagonalLocalEquations}) along the graph lift \(\langle \mathrm{fst},
  \mathrm{snd} \circ t\rangle\); the pullback is a local-equation system by
  Theorem~\ref{thm:graph_pullback_regular}. Its Picard class \(\mathrm{graphPicClass}(C, t) =
  \struct{C \otimes T}(\Gamma_t)\) is the pullback of the diagonal class:
  \[
    \struct{C \otimes T}(\Gamma_t)
      \;=\; \langle \mathrm{fst}, \mathrm{snd} \circ t\rangle^{*}\,\struct{C \otimes C}(\Delta).
  \]
\end{definition}
\begin{proof}
  \leanok
  The diagonal is a local-equation system (Theorem~\ref{thm:diagonalLocalEquations}); its pullback
  along the graph lift is again a local-equation system by
  Definition~\ref{def:localEquations_pullback}, whose regularity hypothesis is discharged by
  Theorem~\ref{thm:graph_pullback_regular}. The Picard class of a pullback of a local-equation
  system is the pullback of its Picard class (Theorem~\ref{thm:localEquations_picClass_pullback}),
  giving the displayed identity. This is Kleiman's graph divisor \(\Gamma_t\), a relative effective
  divisor on \(X \times T\).
\end{proof}

\begin{theorem}[Base change of the graph class]
  \label{thm:graphLocalEquations_base_change}
  \lean{AlgebraicGeometry.Over.graphLocalEquations_base_change}
  \uses{def:graphLocalEquations, lem:whiskerLeft_comp_graphLift}
  \leanok
  For \(g \colon T' \to T\) and \(t \colon T \to C\), the class of the graph of the restricted
  point \(g \circ t\) is the pullback of the class of the graph of \(t\) along \(C \lhd g\):
  \[
    \struct{C \otimes T'}(\Gamma_{g \circ t})
      \;=\; (C \lhd g)^{*}\,\struct{C \otimes T}(\Gamma_t).
  \]
\end{theorem}
\begin{proof}
  \leanok
  By Definition~\ref{def:graphLocalEquations} each side is a pullback of the diagonal class
  \(\struct{C \otimes C}(\Delta)\): the left along the graph lift of \(g \circ t\), the right along
  the graph lift of \(t\) followed by \(C \lhd g\). Contravariant functoriality of the pullback of
  Picard classes turns the latter into the pullback along the composite \((C \lhd g) \circ
  \langle\mathrm{fst}, \mathrm{snd} \circ t\rangle\), which is the graph lift of \(g \circ t\) by
  the whisker square (Lemma~\ref{lem:whiskerLeft_comp_graphLift}). Hence the two pullbacks agree.
\end{proof}

\section{The graph square and the graph fibre}
\label{sec:graphFibre}

The graph divisor of the previous section is supported, over a field test, on a single
point: the graph is the base change of the diagonal, and the fibre of a one-point test is
one point. This section proves the pullback square and extracts the support statement.

\begin{lemma}[The graph square commutes]
  \label{lem:sectionOfPoint_comp_graphLift}
  \lean{AlgebraicGeometry.Over.sectionOfPoint_comp_graphLift}
  \uses{def:sectionOfPoint, def:diagonal}
  \leanok
  For a point \(t \colon T \to C\), the section of the projection followed by the graph
  lift is the point followed by the diagonal:
  \[
    \langle \mathrm{fst}, \mathrm{snd} \circ t\rangle \circ g_t
      \;=\; \Delta \circ t
    \qquad\text{as morphisms } T \to C \otimes C .
  \]
\end{lemma}
\begin{proof}
  \leanok
  Compare the two projections. Onto the first factor: \(\mathrm{fst} \circ q \circ g_t =
  \mathrm{fst} \circ g_t = t\) and \(\mathrm{fst} \circ \Delta \circ t = t\). Onto the
  second: \(\mathrm{snd} \circ q \circ g_t = t \circ \mathrm{snd} \circ g_t = t\) and
  \(\mathrm{snd} \circ \Delta \circ t = t\), using the projection identities of the section
  (Definition~\ref{def:sectionOfPoint}) and of the diagonal (Definition~\ref{def:diagonal}).
\end{proof}

\begin{theorem}[The graph square is a pullback]
  \label{thm:isPullback_graphLift}
  \lean{AlgebraicGeometry.Over.isPullback_graphLift}
  \uses{lem:sectionOfPoint_comp_graphLift, lem:over_isPullback_left, def:sectionOfPoint,
    def:diagonal}
  \leanok
  \source{kleiman-picard}
  For any test object \(T\) and point \(t \colon T \to C\), the commuting square of
  underlying schemes
  \[
    \begin{array}{ccc}
      T_{\mathrm{left}} & \xrightarrow{\ t\ } & C_{\mathrm{left}} \\
      \downarrow g_t & & \downarrow \Delta \\
      (C \otimes T)_{\mathrm{left}} & \xrightarrow{\ q\ } & (C \otimes C)_{\mathrm{left}}
    \end{array}
  \]
  (\(q = \langle\mathrm{fst}, \mathrm{snd} \circ t\rangle\) the graph lift) is a pullback:
  the graph of \(t\) is the base change of the diagonal along the graph lift — Kleiman's
  \(\Gamma_g = (1 \times g)^{-1}\Delta\). No separatedness or properness is used.
\end{theorem}
\begin{proof}
  \leanok
  Two paste-cancellations on the product bridge (Lemma~\ref{lem:over_isPullback_left}).
  First, the middle square: the square with horizontals \(q\) and \(t\) and verticals the
  two second projections is a pullback, by right-cancellation of the product square of
  \(C \otimes C\) against the product square of \(C \otimes T\) (whose first projection
  factors as \(\mathrm{fst} \circ q\)). Second, the top square: the square with verticals
  \(g_t\) and \(\Delta\) pastes with the middle square to the square with verticals
  \(g_t \circ \mathrm{snd} = \id\) and \(\Delta \circ \mathrm{snd} = \id\), which is a
  pullback (vertical isomorphisms); bottom-cancellation against the middle square, using
  commutativity (Lemma~\ref{lem:sectionOfPoint_comp_graphLift}), makes the top square a
  pullback.
\end{proof}

\begin{theorem}[The range of the section is the graph]
  \label{thm:range_sectionOfPoint_left}
  \lean{AlgebraicGeometry.Over.range_sectionOfPoint_left}
  \uses{thm:isPullback_graphLift}
  \leanok
  For any point \(t \colon T \to C\), the topological range of the section of the
  projection is the graph-lift preimage of the diagonal:
  \[
    \operatorname{range}(g_t) \;=\; q^{-1}\bigl(\operatorname{range}\Delta\bigr)
    \quad\text{in } (C \otimes T)_{\mathrm{left}} .
  \]
\end{theorem}
\begin{proof}
  \leanok
  A pullback of schemes surjects onto the topological fibre product
  (Theorem~\ref{thm:isPullback_graphLift} plus the surjectivity of scheme pullbacks onto
  fibre products of spaces); the fibre product of \(\Delta\) and \(q\) projects onto
  exactly the points of \((C \otimes T)_{\mathrm{left}}\) whose \(q\)-image lies in the
  range of \(\Delta\), and the projection to \((C \otimes T)_{\mathrm{left}}\) is carried
  by the square onto the range of \(g_t\).
\end{proof}

\begin{definition}[The graph point of a field test]
  \label{def:graphPoint}
  \lean{AlgebraicGeometry.Over.graphPoint,
    AlgebraicGeometry.Over.range_sectionOfPoint_left_eq_singleton,
    AlgebraicGeometry.Over.mem_range_diagonal_graphLift_iff,
    AlgebraicGeometry.Over.fst_graphPoint, AlgebraicGeometry.Over.graphLift_graphPoint}
  \uses{thm:range_sectionOfPoint_left, def:sectionOfPoint}
  \leanok
  Let \(K\) be a field extension of \(k\) and \(t \colon \Spec K \to C\) a field point. The
  \emph{graph point} \(x_t \in (C \otimes \Spec K)_{\mathrm{left}}\) is the image of the
  unique point of \(\Spec K\) under the section \(g_t\). It is the entire graph fibre:
  \[
    q(z) \in \operatorname{range}\Delta \iff z = x_t ,
  \]
  its first projection is the image point of \(t\), and \(q(x_t) = \Delta(t(\ast))\).
\end{definition}
\begin{proof}
  \leanok
  \(\Spec K\) has a single point, so
  \(\operatorname{range}(g_t) = \{x_t\}\); by
  Theorem~\ref{thm:range_sectionOfPoint_left} the \(q\)-preimage of the diagonal is that
  singleton, which is the displayed equivalence. The two projection formulas follow from
  \(\mathrm{fst} \circ g_t = t\) and the commuting graph square
  (Definition~\ref{def:sectionOfPoint},
  Lemma~\ref{lem:sectionOfPoint_comp_graphLift}).
\end{proof}

\section{Rational points over a separably closed field}
\label{sec:separablyClosedPoints}

Over a separably closed field \(K\) the \(K\)-rational points of a smooth curve are
\emph{dense}: every nonempty open contains one. Over an imperfect separably closed field
not every closed point is rational (on \(\mathbb{A}^1_K\) there are closed points with residue
field \(K(a^{1/p})\)), so the algebraically-closed argument through closed points fails;
what survives is density, through the standard-smooth chart, which is \'etale over the
affine line. There is no classical source anchored here; the statements are as formalised.

\begin{lemma}[A separably closed field is infinite]
  \label{lem:sepClosed_infinite}
  \lean{AlgebraicGeometry.SeparablyClosed.instInfiniteOfIsSepClosed}
  \leanok
  A separably closed field is infinite.
\end{lemma}
\begin{proof}
  \leanok
  Suppose \(K\) had exactly \(n\) elements. The polynomial \(f = X^{n+1} - 1\) is separable
  over \(K\): in characteristic zero this is clear, and in characteristic \(p > 0\) the
  cardinality \(n\) is a power of \(p\), so \(n + 1 \equiv 1 \not\equiv 0 \pmod p\); hence
  the derivative \((n+1)X^{n}\) is a nonzero monomial, sharing no root with \(f\) (a common
  root would satisfy \(x = 0\) and \(x^{n+1} = 1\)). A separable polynomial over a separably
  closed field splits with distinct roots, so \(K\) contains \(n + 1\) distinct roots of
  \(f\) — more than \(n\) elements, a contradiction. (This mirrors the classical argument
  that an algebraically closed field is infinite, with the splitting input replaced by
  separable splitting.)
\end{proof}

\begin{definition}[Rational points of the affine line]
  \label{def:ratPt}
  \lean{AlgebraicGeometry.SeparablyClosed.ratPt,
    AlgebraicGeometry.SeparablyClosed.mem_ratPt_basicOpen}
  \leanok
  For a field \(K\) and a value \(x \in K\), the \(K\)-rational point of
  \(\mathbb{A}^1 = \Spec K[X]\) at \(x\): the maximal ideal \(\ker(\mathrm{ev}_x) = (X - x)\). It
  lies in a basic open \(D(h)\) iff \(h(x) \neq 0\).
\end{definition}
\begin{proof}
  \leanok
  \(\mathrm{ev}_x\) is a surjection onto the field \(K\), so its kernel is maximal, hence
  prime. Membership in \(D(h)\) means \(h \notin \ker(\mathrm{ev}_x)\), i.e.\
  \(h(x) \neq 0\).
\end{proof}

\begin{lemma}[A rational base point under an \'etale algebra]
  \label{lem:exists_ratPt_mem_range}
  \lean{AlgebraicGeometry.SeparablyClosed.exists_ratPt_mem_range}
  \uses{def:ratPt, lem:sepClosed_infinite}
  \leanok
  Let \(K\) be an infinite field and \(S \neq 0\) a \(K\)-algebra \'etale over
  \(K[X]\). Then the image of \(\Spec S \to \mathbb{A}^1\) contains a \(K\)-rational point.
\end{lemma}
\begin{proof}
  \leanok
  \'Etale maps are flat and of finite presentation, so the image of \(\Spec S\) is open
  (going-down plus finite presentation makes the induced map on spectra open); it is
  nonempty since \(S \neq 0\). A nonempty open of \(\Spec K[X]\) contains a nonempty basic
  open \(D(h)\), \(h \neq 0\). Over the infinite field \(K\) the nonzero polynomial \(h\)
  has a non-vanishing value \(x\) (a nonzero polynomial function on an infinite field is
  not identically zero), and \(\mathrm{ratPt}(x) \in D(h)\)
  (Definition~\ref{def:ratPt}) lies in the image.
\end{proof}

\begin{lemma}[\'Etale algebras over a separably closed field split]
  \label{lem:exists_algHom_to_base}
  \lean{AlgebraicGeometry.SeparablyClosed.exists_algHom_to_base}
  \leanok
  A nonzero \'etale algebra \(A\) over a separably closed field \(K\) admits a \(K\)-algebra
  homomorphism \(A \to K\).
\end{lemma}
\begin{proof}
  \leanok
  Over a separably closed field, a (formally) \'etale algebra splits as a finite product of
  copies of \(K\); \(A \neq 0\) means the product is nonempty, and any factor projection is
  a \(K\)-point.
\end{proof}

\begin{theorem}[The commutative-algebra core of the density theorem]
  \label{thm:exists_algHom_of_etale_mvPoly}
  \lean{AlgebraicGeometry.SeparablyClosed.exists_algHom_of_etale_mvPoly}
  \uses{lem:exists_ratPt_mem_range, lem:exists_algHom_to_base, lem:sepClosed_infinite,
    def:ratPt}
  \leanok
  Let \(K\) be separably closed and \(S \neq 0\) a \(K\)-algebra \'etale over \(K[X]\).
  Then \(S\) has a \(K\)-point: a \(K\)-algebra homomorphism \(S \to K\).
\end{theorem}
\begin{proof}
  \leanok
  \(K\) is infinite (Lemma~\ref{lem:sepClosed_infinite}); pick a \(K\)-rational point
  \(x\) of \(\mathbb{A}^1\) in the image of \(\Spec S\)
  (Lemma~\ref{lem:exists_ratPt_mem_range}). The fibre
  \(S_x := K \otimes_{K[X]} S\) (base change along \(\mathrm{ev}_x\)) is \'etale over \(K\)
  (base change of \'etale is \'etale) and nonzero: a prime \(q\) of \(S\) over
  \(\mathrm{ratPt}(x)\) yields a \(K[X]\)-algebra map \(S_x \to S/q\) — lift
  \(K \to S/q\) through the surjection \(K[X] \twoheadrightarrow K\), whose kernel dies in
  \(S/q\) precisely because \(q\) lies over \(\ker(\mathrm{ev}_x)\), and pair it with the
  residue map — and \(S/q \neq 0\). By the splitting lemma
  (Lemma~\ref{lem:exists_algHom_to_base}) the fibre has a \(K\)-point, which composes with
  \(S \to K \otimes_{K[X]} S\), \(s \mapsto 1 \otimes s\), to a \(K\)-point of \(S\).
\end{proof}

\begin{theorem}[A nonempty smooth curve over a separably closed field has a rational point]
  \label{thm:exists_rationalPoint_sepClosed}
  \lean{AlgebraicGeometry.SeparablyClosed.exists_rationalPoint_of_smoothOfRelativeDimension_one}
  \uses{thm:exists_algHom_of_etale_mvPoly, thm:standard_smooth_etale_structure}
  \leanok
  Let \(K\) be separably closed and \(X\) a nonempty scheme smooth of relative dimension
  \(1\) over \(K\). Then \(X\) has a \(K\)-point over \(K\): a morphism
  \(p \colon \Spec K \to X\) with \(p \circ f = \id\).
\end{theorem}
\begin{proof}
  \leanok
  Pick a point \(x_0 \in X\) and a standard-smooth chart \(V \ni x_0\) of relative
  dimension \(1\). Its section ring is \'etale over a one-variable polynomial ring
  (Theorem~\ref{thm:standard_smooth_etale_structure}), and transporting along the
  identification \(\Gamma(\Spec K, \top) \cong K\) makes \(\Gamma(X, V)\) an \'etale
  \(K[X]\)-algebra, nonzero since \(V \ni x_0\) is nonempty. The core
  (Theorem~\ref{thm:exists_algHom_of_etale_mvPoly}) yields a \(K\)-algebra map
  \(\varphi \colon \Gamma(X,V) \to K\); \(\Spec\varphi\) composed with the canonical map of
  the affine open \(V\) is a scheme point \(\Spec K \to X\). It lies over \(K\): composing
  with the structure morphism corresponds, on rings, to
  \(\varphi \circ (\text{chart map } K \to \Gamma(X,V))\), which is the identity of \(K\)
  since \(\varphi\) is a \(K\)-algebra map.
\end{proof}

\begin{theorem}[Density of rational points over a separably closed field]
  \label{thm:exists_rationalPoint_mem}
  \lean{AlgebraicGeometry.SeparablyClosed.exists_rationalPoint_mem,
    AlgebraicGeometry.Over.exists_rationalPoint_mem}
  \uses{thm:exists_rationalPoint_sepClosed}
  \leanok
  Let \(K\) be separably closed, \(f \colon X \to \Spec K\) smooth of relative dimension
  \(1\), and \(W \subseteq X\) a nonempty open. Then there is a \(K\)-point
  \(p \colon \Spec K \to X\) over \(K\) whose topological image lies in \(W\). In
  particular, for a curve pack \(C\) over a separably closed field, every nonempty open of
  the underlying space of \(C\) contains a rational point.
\end{theorem}
\begin{proof}
  \leanok
  Smoothness of relative dimension \(1\) is local on the source, so the open subscheme
  \(W\) is itself smooth of relative dimension \(1\) over \(K\), and nonempty; by
  Theorem~\ref{thm:exists_rationalPoint_sepClosed} it has a \(K\)-point over \(K\), whose
  composite with the open immersion \(W \to X\) is the required point of \(X\), with image
  in \(W\).
\end{proof}

\section{Coheight and the Krull dimension of stalks}
\label{sec:coheight_stalk}

For a point \(z\) of a topological space, the \emph{coheight} of \(z\) is the supremum
of the lengths of strictly increasing chains starting at \(z\) in the specialisation
preorder (\(y \leq z\) iff \(z\) specialises to \(y\), i.e.\ \(y \in \overline{\{z\}}\));
on a scheme it measures the codimension of the closure of \(z\). This section identifies
it with the Krull dimension of the stalk.

\begin{lemma}[Coheight is local on opens]
  \label{lem:coheight_open_embedding}
  \lean{Order.coheight_eq_of_isOpenEmbedding}
  \leanok
  Let \(X\) be a topological space, \(U \subseteq X\) an open subset and \(z \in U\).
  The coheight of \(z\) computed in \(X\) (for the specialisation preorder) equals the
  coheight of \(z\) computed in the subspace \(U\).
\end{lemma}
\begin{proof}
  \leanok
  (\(\geq\)) The inclusion \(U \to X\) is continuous, hence monotone for the
  specialisation preorders, and injective; a strictly increasing chain in \(U\) starting
  at \(z\) therefore maps to one in \(X\) of the same length (strictness is preserved:
  if the images were comparable both ways they would be equal).

  (\(\leq\)) Conversely, let \(z = p_0 < p_1 < \dots < p_n\) be a chain in \(X\)
  starting at \(z\). Each \(p_i\) is a generisation of \(z\): \(z \in
  \overline{\{p_i\}}\). Since \(U\) is open and \(z \in U\), every generisation of a
  point of \(U\) lies in \(U\) (an open set containing a point of the closure of
  \(\{p_i\}\) meets \(\{p_i\}\)), so all \(p_i \in U\). The specialisation preorder of
  the subspace \(U\) agrees with that of \(X\) on points of \(U\) when \(U\) is open, so
  the chain lives in \(U\) with the same strict inequalities and the same length.
\end{proof}

\begin{lemma}[Coheight in an affine scheme is the height of the prime]
  \label{lem:coheight_spec_height}
  \lean{Order.coheight_spec_eq_height_primeSpectrum}
  \leanok
  Let \(R\) be a commutative ring and \(p\) a point of \(\Spec R\), with corresponding
  prime ideal \(\mathfrak p\). The coheight of \(p\) in the specialisation preorder of
  \(\Spec R\) equals the height of \(\mathfrak p\) (the supremum of lengths of chains of
  primes descending from \(\mathfrak p\)).
\end{lemma}
\begin{proof}
  \leanok
  In \(\Spec R\), a point \(q\) specialises to \(p\) exactly when
  \(\mathfrak p \supseteq \mathfrak q\); so the specialisation preorder on
  \(\Spec R\) is the opposite of the inclusion order on primes, and the order
  isomorphism \(\Spec R \cong (\text{primes of } R)^{\mathrm{op}}\) converts coheight at
  \(p\) into height at \(\mathfrak p\) (chains going up from \(p\) in the
  specialisation preorder are chains of primes going down from \(\mathfrak p\)).
\end{proof}

\begin{theorem}[Stalk dimension equals coheight]
  \label{thm:stalk_dim_coheight}
  \lean{AlgebraicGeometry.Scheme.ringKrullDim_stalk_eq_coheight}
  \uses{lem:coheight_open_embedding, lem:coheight_spec_height}
  \leanok
  Let \(X\) be a scheme and \(z \in X\) a point. Then the Krull dimension of the stalk
  \(\struct{X,z}\) equals the coheight of \(z\) in the underlying topological space of
  \(X\).
\end{theorem}
\begin{proof}
  \leanok
  Choose an affine open \(U \ni z\), say \(U \cong \Spec A\) with
  \(A = \Gamma(X, U)\), and let \(\mathfrak p\) be the prime of \(A\) corresponding to
  \(z\). The stalk \(\struct{X,z}\) is the localisation \(A_{\mathfrak p}\), whose Krull
  dimension is the height of \(\mathfrak p\) (primes of the localisation are the primes
  of \(A\) contained in \(\mathfrak p\)). By \ref{lem:coheight_open_embedding}, the
  coheight of \(z\) in \(X\) equals its coheight in \(U\); the isomorphism
  \(U \cong \Spec A\) is a homeomorphism, hence an isomorphism of specialisation
  preorders, so this equals the coheight of \(\mathfrak p\) in \(\Spec A\), which is the
  height of \(\mathfrak p\) by \ref{lem:coheight_spec_height}. Chaining the equalities
  gives \(\dim \struct{X,z} = \mathrm{coheight}(z)\).
\end{proof}

\begin{lemma}[Codimension-one points have one-dimensional stalks]
  \label{lem:stalk_dimLE_one}
  \lean{AlgebraicGeometry.Scheme.ringKrullDimLE_of_coheight_eq_one}
  \uses{thm:stalk_dim_coheight}
  \leanok
  Let \(X\) be a scheme and \(z \in X\) with \(\mathrm{coheight}(z) = 1\). Then the
  stalk \(\struct{X,z}\) has Krull dimension \(\leq 1\).
\end{lemma}
\begin{proof}
  \leanok
  By \ref{thm:stalk_dim_coheight}, \(\dim \struct{X,z} = \mathrm{coheight}(z) = 1\).
\end{proof}

\section{The dimension of a standard-smooth algebra at a maximal ideal}
\label{sec:standard_smooth_dimension}

This section proves the dimension half of the smooth-implies-regular pipeline at closed
points: for a standard-smooth algebra of relative dimension \(n\) over a field, every
maximal ideal has height at least \(n\).

\begin{theorem}[Maximal ideals of polynomial rings have full height]
  \label{thm:mvpoly_maximal_height}
  \lean{MvPolynomial.height_eq_natCard_of_isMaximal}
  \leanok
  Let \(k\) be a field, \(\iota\) a finite index type, and \(M\) a maximal ideal of the
  polynomial ring \(k[x_i : i \in \iota]\). Then the height of \(M\) is \(\#\iota\).
\end{theorem}
\begin{proof}
  \leanok
  Induct on the finite type \(\iota\) (along equivalences, the empty type, and adding
  one variable). Heights are invariant under ring isomorphisms, which handles transport
  along an equivalence \(\iota \cong \iota'\). If \(\iota\) is empty the ring is the
  field \(k\), of Krull dimension \(0\), so every maximal ideal has height \(0 =
  \#\iota\). For \(\iota = \{*\} \sqcup \alpha\), identify
  \(k[x_i : i \in \iota] \cong R[X]\) with \(R = k[x_i : i \in \alpha]\), and let
  \(M \subseteq R[X]\) be maximal. The ring \(R\), a finitely generated algebra over a
  field, is a Jacobson ring, so the contraction \(\mathfrak p = M \cap R\) is again
  \emph{maximal}. For a maximal ideal of \(R[X]\) lying over a maximal ideal
  \(\mathfrak p\) of a Noetherian ring one has the height formula
  \(\mathrm{ht}(M) = \mathrm{ht}(\mathfrak p) + 1\) (the fibre
  \(R[X] \otimes_R R/\mathfrak p = (R/\mathfrak p)[X]\) is a principal ideal domain over
  the field \(R/\mathfrak p\), and \(M\) generates a nonzero --- because maximal ---
  prime there). By the inductive hypothesis \(\mathrm{ht}(\mathfrak p) = \#\alpha\), so
  \(\mathrm{ht}(M) = \#\alpha + 1 = \#\iota\).
\end{proof}

\begin{theorem}[Height lower bound at maximal ideals of standard-smooth algebras]
  \label{thm:standard_smooth_height_lower}
  \lean{Algebra.IsStandardSmoothOfRelativeDimension.natCast_le_height_of_isMaximal}
  \uses{thm:mvpoly_maximal_height}
  \leanok
  \source{stacks-project}
  Let \(k\) be a field and \(S\) a standard-smooth \(k\)-algebra of relative dimension
  \(n\). Then every maximal ideal \(\mathfrak m \subseteq S\) has
  \(\mathrm{ht}(\mathfrak m) \geq n\).
\end{theorem}
\begin{proof}
  \leanok
  Choose a submersive presentation \(S = P/\ker\), where
  \(P = k[x_i : i \in \iota]\) is a polynomial ring on \(\#\iota\) generators, the
  kernel of \(P \twoheadrightarrow S\) is generated by \(\#\sigma\) relations, and
  \(n = \#\iota - \#\sigma\) (with \(\#\sigma \leq \#\iota\)). The pullback
  \(M \subseteq P\) of \(\mathfrak m\) is a maximal ideal (the quotient map is
  surjective), of height \(\#\iota\) by \ref{thm:mvpoly_maximal_height}, and it contains
  the kernel. Krull's height theorem, in the relative form
  \(\mathrm{ht}(M) \leq \mathrm{ht}(M/\ker) + \mu(\ker)\) for a prime containing an
  ideal generated by \(\mu(\ker)\) elements, gives
  \[
    \#\iota = \mathrm{ht}(M) \leq \mathrm{ht}(\mathfrak m) + \#\sigma
  \]
  (the first isomorphism theorem identifies \(M/\ker\) with \(\mathfrak m\), and heights
  are preserved by this identification). Subtracting \(\#\sigma\) yields
  \(n = \#\iota - \#\sigma \leq \mathrm{ht}(\mathfrak m)\).
\end{proof}

\begin{lemma}[Localised form of the height lower bound]
  \label{lem:standard_smooth_dim_lower_localized}
  \lean{Algebra.IsStandardSmoothOfRelativeDimension.le_ringKrullDim_of_isLocalization_atPrime}
  \uses{thm:standard_smooth_height_lower}
  \leanok
  In the setting of \ref{thm:standard_smooth_height_lower}, for any localisation
  \(S_{\mathfrak m}\) of \(S\) at a maximal ideal \(\mathfrak m\),
  \(\dim S_{\mathfrak m} \geq n\).
\end{lemma}
\begin{proof}
  \leanok
  The Krull dimension of the localisation at a prime is the height of that prime
  (primes of \(S_{\mathfrak m}\) are the primes of \(S\) contained in
  \(\mathfrak m\)); apply \ref{thm:standard_smooth_height_lower}.
\end{proof}

\begin{lemma}[Regularity from the cotangent upper bound]
  \label{lem:regular_of_cotangent_le_dim}
  \lean{IsRegularLocalRing.of_finrank_cotangentSpace_le_ringKrullDim}
  \leanok
  Let \((A, \mathfrak m)\) be a Noetherian local ring with
  \(\dim_\kappa \mathfrak m/\mathfrak m^2 \leq \dim A\). Then \(A\) is a regular local
  ring.
\end{lemma}
\begin{proof}
  \leanok
  By Nakayama, \(\dim_\kappa \mathfrak m/\mathfrak m^2\) is the minimal number
  \(\mu(\mathfrak m)\) of generators of \(\mathfrak m\), and Krull's height theorem
  gives the reverse inequality \(\dim A \leq \mu(\mathfrak m)\) in any Noetherian local
  ring. So the hypothesis forces equality, which is the definition of regularity.
\end{proof}

\section{The trdeg--height inequality and smooth-prime regularity}
\label{sec:smooth_prime_regularity}

This section closes the smooth-implies-regular pipeline at \emph{arbitrary} primes of a
standard-smooth algebra over a perfect field, with no recourse to Serre's homological
characterisation of regularity (and hence no need for the theorem that localisations of
regular local rings are regular): the cotangent dimension at a prime is computed
directly from the conormal sequence, and matched against a transcendence-degree/height
inequality proved by induction on the number of variables.

\begin{lemma}[One-variable step of the trdeg--height inequality]
  \label{lem:polynomial_step_height_trdeg}
  \lean{Polynomial.step_height_trdeg_of_isPrime}
  \leanok
  \source{stacks-project}
  Let \(k\) be a field, \(R\) a Noetherian \(k\)-algebra, \(P \subseteq R[X]\) a prime
  ideal and \(\mathfrak p = P \cap R\). Then one of the following holds:
  \begin{enumerate}
    \item \(\mathrm{ht}(\mathfrak p) + 1 \leq \mathrm{ht}(P)\) and
      \(\mathrm{trdeg}_k(R/\mathfrak p) \leq \mathrm{trdeg}_k(R[X]/P)\); or
    \item \(\mathrm{ht}(P) = \mathrm{ht}(\mathfrak p)\) and
      \(\mathrm{trdeg}_k(R/\mathfrak p) + 1 \leq \mathrm{trdeg}_k(R[X]/P)\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \leanok
  Write \(A = R/\mathfrak p\), a domain. The extension \(R \to R[X]\) is free, hence
  flat, hence has the going-down property, so the dimension formula for a prime lying
  over \(\mathfrak p\) applies (Stacks 00ON):
  \(\mathrm{ht}(P) = \mathrm{ht}(\mathfrak p) + \mathrm{ht}(\bar P)\), where
  \(\bar P\) is the image of \(P\) in the fibre ring
  \(R[X]/\mathfrak p R[X] \cong A[X]\) --- a prime \(Q \subseteq A[X]\) contracting to
  \((0)\) in \(A\) (because \(P \cap R = \mathfrak p\)).

  \emph{Case \(Q = (0)\).} Then \(\mathrm{ht}(P) = \mathrm{ht}(\mathfrak p)\), and
  \(R[X]/P \cong A[X]/Q = A[X]\) as \(k\)-algebras. Adjoining a variable to the domain
  \(A\) raises the transcendence degree by one
  (\(\mathrm{trdeg}_k A[X] \geq \mathrm{trdeg}_k A + \mathrm{trdeg}_A A[X]
  = \mathrm{trdeg}_k A + 1\)), giving case (2).

  \emph{Case \(Q \neq (0)\).} Then \((0) \subsetneq Q\) is a chain of primes in
  \(A[X]\), so \(\mathrm{ht}(Q) \geq 1\) and
  \(\mathrm{ht}(P) \geq \mathrm{ht}(\mathfrak p) + 1\). Moreover \(Q\) contracts to
  \((0)\) in \(A\), so the composite \(A \to A[X] \to A[X]/Q \cong R[X]/P\) is
  injective, whence
  \(\mathrm{trdeg}_k(A) \leq \mathrm{trdeg}_k(R[X]/P)\), giving case (1).
\end{proof}

\begin{theorem}[The trdeg--height inequality in polynomial rings]
  \label{thm:trdeg_height_polynomial}
  \lean{MvPolynomial.exists_le_trdeg_and_natCard_le_height_add}
  \uses{lem:polynomial_step_height_trdeg}
  \leanok
  Let \(k\) be a field, \(\iota\) a finite index type, and \(P\) a prime ideal of
  \(k[x_i : i \in \iota]\). Then there is a natural number \(d\) with
  \[
    d \leq \mathrm{trdeg}_k\bigl(k[x_i : i \in \iota]/P\bigr)
    \quad\text{and}\quad
    \#\iota \leq \mathrm{ht}(P) + d.
  \]
\end{theorem}
\begin{proof}
  \leanok
  Induct on the finite type \(\iota\) (along equivalences, the empty type, and adding
  one variable); heights and transcendence degrees are invariant under \(k\)-algebra
  isomorphisms, which handles equivalences. For \(\iota\) empty take \(d = 0\). For
  \(\iota = \{*\} \sqcup \alpha\), identify the ring with \(R[X]\),
  \(R = k[x_i : i \in \alpha]\), and let \(\mathfrak p = P \cap R\); by the inductive
  hypothesis pick \(d\) with \(d \leq \mathrm{trdeg}_k(R/\mathfrak p)\) and
  \(\#\alpha \leq \mathrm{ht}(\mathfrak p) + d\). Apply
  \ref{lem:polynomial_step_height_trdeg}. In case (1) (height jump) keep the witness
  \(d\):
  \(d \leq \mathrm{trdeg}_k(R/\mathfrak p) \leq \mathrm{trdeg}_k(R[X]/P)\) and
  \(\#\iota = \#\alpha + 1 \leq \mathrm{ht}(\mathfrak p) + 1 + d \leq
  \mathrm{ht}(P) + d\). In case (2) (transcendence jump) take \(d + 1\):
  \(d + 1 \leq \mathrm{trdeg}_k(R/\mathfrak p) + 1 \leq \mathrm{trdeg}_k(R[X]/P)\) and
  \(\#\iota = \#\alpha + 1 \leq \mathrm{ht}(\mathfrak p) + d + 1 = \mathrm{ht}(P) +
  (d + 1)\).
\end{proof}

\begin{theorem}[The trdeg--height inequality for standard-smooth algebras]
  \label{thm:trdeg_height_standard_smooth}
  \lean{Algebra.IsStandardSmoothOfRelativeDimension.exists_le_trdeg_and_natCast_le_height_add}
  \uses{thm:trdeg_height_polynomial}
  \leanok
  Let \(k\) be a field and \(S\) a standard-smooth \(k\)-algebra of relative dimension
  \(n\). For every prime ideal \(\mathfrak q \subseteq S\) there is a natural number
  \(d\) with
  \[
    d \leq \mathrm{trdeg}_k(S/\mathfrak q)
    \quad\text{and}\quad
    n \leq \mathrm{ht}(\mathfrak q) + d.
  \]
\end{theorem}
\begin{proof}
  \leanok
  As in \ref{thm:standard_smooth_height_lower}: choose a submersive presentation
  \(P = k[x_i : i \in \iota] \twoheadrightarrow S\) with kernel generated by
  \(\#\sigma\) relations and \(n = \#\iota - \#\sigma\). Let \(M \subseteq P\) be the
  pullback of \(\mathfrak q\), a prime containing the kernel. By
  \ref{thm:trdeg_height_polynomial} pick \(d\) with \(d \leq \mathrm{trdeg}_k(P/M)\) and
  \(\#\iota \leq \mathrm{ht}(M) + d\). The induced map \(P/M \to S/\mathfrak q\) is an
  injective \(k\)-algebra map (indeed an isomorphism by the first isomorphism theorem),
  so \(d \leq \mathrm{trdeg}_k(S/\mathfrak q)\). Krull's height theorem bounds the
  height defect by the number of relations,
  \(\mathrm{ht}(M) \leq \mathrm{ht}(\mathfrak q) + \#\sigma\), so
  \(\#\iota \leq \mathrm{ht}(\mathfrak q) + \#\sigma + d\) and
  \(n = \#\iota - \#\sigma \leq \mathrm{ht}(\mathfrak q) + d\).
\end{proof}

\begin{theorem}[K\"ahler rank equals transcendence degree over a perfect field]
  \label{thm:kaehler_rank_trdeg}
  \lean{Algebra.rank_kaehlerDifferential_eq_trdeg}
  \leanok
  Let \(k\) be a perfect field and \(K\) a field extension of \(k\) that is essentially
  of finite type. Then
  \[
    \dim_K \Omega_{K/k} = \mathrm{trdeg}_k(K).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Since \(k\) is perfect and \(K\) essentially of finite type over \(k\), \(K\) admits a
  \emph{separating} transcendence basis \(s \subseteq K\): a transcendence basis such
  that \(K\) is separable algebraic over the intermediate field \(F = k(s)\). A
  separable algebraic extension is formally \'etale, so base change along \(F \to K\)
  identifies \(\Omega_{K/k} \cong K \otimes_F \Omega_{F/k}\); in particular
  \(\dim_K \Omega_{K/k} = \dim_F \Omega_{F/k}\). The field \(F\) is \(k\)-isomorphic to
  the fraction field of the polynomial ring \(k[x_i : i \in s]\), and K\"ahler
  differentials localise: \(\Omega_{F/k}\) is the localisation of the free module
  \(\Omega_{k[x_i]/k}\) with basis \(\{dx_i : i \in s\}\), hence is \(F\)-free on
  \(\{dx_i\}\). Therefore
  \(\dim_F \Omega_{F/k} = \#s = \mathrm{trdeg}_k(K)\), the last equality because \(s\)
  is a transcendence basis.
\end{proof}

\begin{theorem}[The conormal dimension identity]
  \label{thm:conormal_dim_identity}
  \lean{finrank_cotangentSpace_add_finrank_kaehler_residueField}
  \leanok
  \source{stacks-project}
  Let \(R\) be a commutative ring and \((S, \mathfrak m)\) a local \(R\)-algebra that is
  formally smooth over \(R\), whose residue field \(\kappa = S/\mathfrak m\) is also
  formally smooth over \(R\), and whose K\"ahler differentials \(\Omega_{S/R}\) are
  \(S\)-free of rank \(n \in \mathbb{N}\). Then
  \[
    \dim_\kappa \mathfrak m/\mathfrak m^2 + \dim_\kappa \Omega_{\kappa/R} = n.
  \]
\end{theorem}
\begin{proof}
  \leanok
  Consider the conormal (second fundamental) exact sequence of the surjection
  \(S \twoheadrightarrow \kappa\) with kernel \(\mathfrak m\) (Stacks 00RU):
  \[
    \mathfrak m/\mathfrak m^2 \xrightarrow{\ c\ }
      \kappa \otimes_S \Omega_{S/R} \longrightarrow \Omega_{\kappa/R} \longrightarrow 0,
    \qquad c(\bar f) = df \otimes 1.
  \]
  Because \(\kappa\) is formally smooth over \(R\), the surjection
  \(S \twoheadrightarrow \kappa\) admits enough infinitesimal liftings to \emph{split}
  the conormal map: \(c\) is (split) injective. All three terms are
  \(\kappa\)-vector spaces and the middle has dimension
  \(\dim_\kappa (\kappa \otimes_S \Omega_{S/R}) = n\) (base change of a free rank-\(n\)
  module). The map onto \(\Omega_{\kappa/R}\) is surjective with kernel exactly the
  image of \(c\), which has dimension \(\dim_\kappa \mathfrak m/\mathfrak m^2\) by
  injectivity; rank--nullity gives the identity. (Finite-dimensionality of all terms
  follows from that of the middle term.)
\end{proof}

\begin{theorem}[Smooth-prime regularity over a perfect field]
  \label{thm:smooth_prime_regularity}
  \lean{isRegularLocalRing_of_isLocalization_atPrime_of_isStandardSmooth_of_perfectField}
  \uses{thm:trdeg_height_standard_smooth, thm:kaehler_rank_trdeg,
    thm:conormal_dim_identity, lem:regular_of_cotangent_le_dim}
  \leanok
  \source{stacks-project}
  Let \(k\) be a perfect field (for instance an algebraically closed field) and \(S\) a
  nonzero standard-smooth \(k\)-algebra. For every prime ideal
  \(\mathfrak q \subseteq S\), every localisation \(S_{\mathfrak q}\) of \(S\) at
  \(\mathfrak q\) is a regular local ring.
\end{theorem}
\begin{proof}
  \leanok
  \(S\) is of finite type over \(k\), hence Noetherian, and so is the localisation
  \(A := S_{\mathfrak q}\), a local ring with maximal ideal \(\mathfrak m\) and residue
  field \(\kappa\). Fix \(n\) with \(S\) standard smooth of relative dimension \(n\)
  over \(k\).

  \emph{The K\"ahler package at \(A\).} \(\Omega_{S/k}\) is \(S\)-free of rank \(n\)
  (standard smoothness), and K\"ahler differentials localise, so \(\Omega_{A/k}\) is
  \(A\)-free of rank \(n\). Localisations of (formally) smooth algebras are formally
  smooth, so \(A\) is formally smooth over \(k\); and \(\kappa\), a field extension of
  the perfect field \(k\) essentially of finite type, is formally smooth over \(k\) as
  well. The conormal identity \ref{thm:conormal_dim_identity} thus gives
  \[
    \dim_\kappa \mathfrak m/\mathfrak m^2 \;=\; n - \dim_\kappa \Omega_{\kappa/k}.
  \]

  \emph{The dimension count.} By \ref{thm:kaehler_rank_trdeg},
  \(\dim_\kappa \Omega_{\kappa/k} = \mathrm{trdeg}_k(\kappa)\). By
  \ref{thm:trdeg_height_standard_smooth} there is \(d\) with
  \(d \leq \mathrm{trdeg}_k(S/\mathfrak q)\) and
  \(n \leq \mathrm{ht}(\mathfrak q) + d\); and \(S/\mathfrak q\) embeds into \(\kappa\)
  as \(k\)-algebras (localisation at \(\mathfrak q\) followed by reduction is injective
  on \(S/\mathfrak q\)), so
  \(d \leq \mathrm{trdeg}_k(\kappa) = \dim_\kappa \Omega_{\kappa/k}\). Combining,
  \[
    \dim_\kappa \mathfrak m/\mathfrak m^2
      = n - \dim_\kappa \Omega_{\kappa/k}
      \leq \bigl(\mathrm{ht}(\mathfrak q) + d\bigr) - \dim_\kappa \Omega_{\kappa/k}
      \leq \mathrm{ht}(\mathfrak q) = \dim A.
  \]
  By \ref{lem:regular_of_cotangent_le_dim}, \(A\) is a regular local ring.
\end{proof}

\label{chap:Cohomology}

Fix a commutative ring \(R\); for the genus of a curve, \(R\) will be the base field \(k\).
This chapter defines the cohomology of sheaves of \(R\)-modules on a small site as
\(\Ext\)-groups from the constant sheaf, and more generally the cohomology of an object of
the site as \(\Ext\)-groups from a free sheaf of \(R\)-modules; it identifies degree-zero
cohomology with (global) sections and proves the vanishing of degree-one cohomology of the
structure sheaf on an affine open of a scheme. It then develops the Mayer--Vietoris
\((0,1)\)-slice for a sheaf of \(R\)-modules on a site and specializes it to a scheme
covered by two affine opens, producing an explicit description of \(H^1(X,\struct{X/k})\)
as the cokernel of a map of section modules. It then runs the
two-lattice ladder of Chapter~\ref{chap:Algebra} on that cokernel along a finite morphism
to the projective line, proving the finiteness of \(H^1(C, \struct C)\) --- so that the
genus of Definition~\ref{def:genus} is the dimension of a finite-dimensional vector space.
The two closing sections glue a twisted sheaf out of a unit cocycle on a two-chart cover
and prove that the two-cover \(H^1\) of the relative curve --- for the structure sheaf,
and termwise for the twisted sheaf --- commutes with arbitrary change of the affine test
ring.

\section{Cohomology on a site}

Let \((\mathcal C, J)\) be a small site: a small category \(\mathcal C\) with a Grothendieck
topology \(J\). The category of sheaves of \(R\)-modules on \((\mathcal C, J)\) is a
Grothendieck abelian category; in particular it has enough injectives, and all
\(\Ext\)-groups exist and carry \(R\)-module structures.

\begin{definition}[The constant sheaf]
  \label{def:constModuleSheaf}
  \lean{CategoryTheory.Sheaf.constModuleSheaf}
  \leanok
  The constant sheaf \(R_J\) of \(R\)-modules on \((\mathcal C, J)\) with value \(R\): the
  sheafification of the constant presheaf with value \(R\).
\end{definition}

\begin{definition}[Sheaf cohomology]
  \label{def:HModule}
  \lean{CategoryTheory.Sheaf.HModule}
  \uses{def:constModuleSheaf}
  \leanok
  For a sheaf \(F\) of \(R\)-modules on \((\mathcal C, J)\) and \(n \ge 0\), the degree-\(n\)
  cohomology of \(F\) is the \(R\)-module
  \[
    H^n(F) \;=\; \Ext^n\bigl(R_J,\, F\bigr),
  \]
  the \(\Ext\)-group computed in the category of sheaves of \(R\)-modules.
\end{definition}

\begin{definition}[Functoriality]
  \label{def:HModule_map}
  \lean{CategoryTheory.Sheaf.HModule.map}
  \uses{def:HModule}
  \leanok
  A morphism of sheaves \(f : F \to G\) induces an \(R\)-linear map
  \(H^n(F) \to H^n(G)\) for every \(n\), by covariant functoriality of \(\Ext\) in the second
  argument. The identity induces the identity, and a composite induces the composite.
\end{definition}
\begin{proof}
  \leanok
  Functoriality of \(\Ext^n(R_J, -)\); the \(R\)-linearity comes from the \(R\)-linear
  structure of the sheaf category.
\end{proof}

\begin{lemma}[No higher cohomology on injectives]
  \label{lem:HModule_injective_vanishing}
  \lean{CategoryTheory.Sheaf.HModule.instSubsingletonHAddNatOfNat}
  \uses{def:HModule}
  \leanok
  If \(F\) is an injective object of the category of sheaves of \(R\)-modules, then
  \(H^{n+1}(F) = 0\) for every \(n \ge 0\).
\end{lemma}
\begin{proof}
  \leanok
  Positive-degree \(\Ext\)-groups into an injective object vanish.
\end{proof}

\begin{definition}[The adjunction, linearly]
  \label{def:constAdjHomEquiv}
  \lean{CategoryTheory.Sheaf.constantSheafAdjHomLinearEquiv}
  \leanok
  Assume the category \(\mathcal C\) has a terminal object \(\top\). For every \(R\)-module
  \(M\) and every sheaf \(F\) of \(R\)-modules there is an \(R\)-linear equivalence
  \[
    \Hom\bigl(\underline{M},\, F\bigr) \;\cong\; \Hom_R\bigl(M,\, F(\top)\bigr),
  \]
  where \(\underline{M}\) denotes the constant sheaf with value \(M\); it is the hom-bijection
  of the adjunction between the constant-sheaf functor and evaluation at \(\top\).
\end{definition}
\begin{proof}
  \leanok
  The constant-sheaf functor is left adjoint to evaluation at the terminal object. The
  bijection sends \(\varphi\) to the composite of the unit \(M \to \underline{M}(\top)\) with
  \(\varphi_\top\); both this assignment and its inverse are additive and commute with the
  \(R\)-action.
\end{proof}

\begin{definition}[Morphisms out of the constant sheaf are sections]
  \label{def:constHomEquiv}
  \lean{CategoryTheory.Sheaf.constModuleSheafHomEquiv}
  \uses{def:constModuleSheaf, def:constAdjHomEquiv}
  \leanok
  The \(R\)-linear equivalence
  \(\Hom(R_J, F) \cong F(\top)\): specialize \ref{def:constAdjHomEquiv} to \(M = R\) and
  compose with the canonical evaluation \(\Hom_R(R, N) \cong N\), \(u \mapsto u(1)\).
\end{definition}

\begin{lemma}[Naturality]
  \label{lem:constHomEquiv_naturality}
  \lean{CategoryTheory.Sheaf.constModuleSheafHomEquiv_naturality}
  \uses{def:constHomEquiv}
  \leanok
  The equivalence of \ref{def:constHomEquiv} is natural in the sheaf: for
  \(\varphi : R_J \to F\) and \(f : F \to G\), the section corresponding to
  \(f \circ \varphi\) is \(f_\top\) applied to the section corresponding to \(\varphi\).
\end{lemma}
\begin{proof}
  \leanok
  Naturality of the adjunction hom-bijection in the second variable, and naturality of the
  evaluation \(\Hom_R(R, N) \cong N\).
\end{proof}

\begin{definition}[Degree-zero cohomology is global sections]
  \label{def:HModule_linearEquiv0}
  \lean{CategoryTheory.Sheaf.HModule.linearEquiv₀}
  \uses{def:HModule, def:constHomEquiv}
  \leanok
  The \(R\)-linear equivalence \(H^0(F) \cong F(\top)\): the canonical identification
  \(\Ext^0(R_J, F) \cong \Hom(R_J, F)\) followed by \ref{def:constHomEquiv}.
\end{definition}

\begin{lemma}[Naturality in degree zero]
  \label{lem:HModule_linearEquiv0_naturality}
  \lean{CategoryTheory.Sheaf.HModule.linearEquiv₀_naturality}
  \uses{def:HModule_linearEquiv0, def:HModule_map}
  \leanok
  The equivalence \(H^0(F) \cong F(\top)\) of \ref{def:HModule_linearEquiv0} is natural: for
  \(f : F \to G\), applying \(f_\top\) to the section corresponding to \(x \in H^0(F)\)
  yields the section corresponding to the image of \(x\) under \(H^0(f)\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:constHomEquiv_naturality}
  The identification \(\Ext^0 \cong \Hom\) turns composition with the degree-zero class of
  \(f\) into postcomposition with \(f\); conclude by \ref{lem:constHomEquiv_naturality}.
\end{proof}

\section{Cohomology of an object of the site}

For an object \(U\) of \(\mathcal C\), this section defines the cohomology of \(U\) with
coefficients in a sheaf \(F\) of \(R\)-modules as \(\Ext\)-groups from a \emph{free} sheaf
of \(R\)-modules on \(U\), generalizing the previous section (where the implicit object was
the terminal object \(\top\)). This is the coefficient system needed to run the
Mayer--Vietoris sequence of Section~\ref{sec:mv-in-text} \(R\)-linearly, and it recovers the
cohomology of the site when \(U\) is terminal (Definition~\ref{def:HModule_linearEquivHModule'}
below).

\begin{definition}[The free sheaf of \(R\)-modules on an object of the site]
  \label{def:freeModuleSheaf}
  \lean{CategoryTheory.Sheaf.freeModuleSheaf}
  \leanok
  For an object \(U\) of \(\mathcal C\), the free sheaf of \(R\)-modules on \(U\), written
  \(R[U]\): the sheafification of the presheaf \(V \mapsto\) the free \(R\)-module on the
  set \(\Hom(V, U)\), with restriction maps induced by precomposition.
\end{definition}

\begin{definition}[Functoriality in the object of the site]
  \label{def:freeModuleSheafMap}
  \lean{CategoryTheory.Sheaf.freeModuleSheafMap}
  \uses{def:freeModuleSheaf}
  \leanok
  A morphism \(i : U \to V\) of \(\mathcal C\) induces a morphism of sheaves of
  \(R\)-modules \(R[i] : R[U] \to R[V]\): apply the free-\(R\)-module-on-a-set functor and
  sheafification to the induced map of representable presheaves
  \(\Hom(-,U) \to \Hom(-,V)\), \(g \mapsto i \circ g\).
\end{definition}

\begin{definition}[Free sheaves of modules represent sections]
  \label{def:freeModuleSheafHomEquiv}
  \lean{CategoryTheory.Sheaf.freeModuleSheafHomEquiv}
  \uses{def:freeModuleSheaf}
  \leanok
  For every object \(U\) of \(\mathcal C\) and every sheaf \(F\) of \(R\)-modules, an
  \(R\)-linear equivalence
  \[
    \Hom\bigl(R[U],\, F\bigr) \;\cong\; F(U).
  \]
\end{definition}
\begin{proof}
  \leanok
  Write \(y_U = \Hom(-,U)\) for the presheaf represented by \(U\), so that \(R[U]\) is the
  sheafification of the presheaf of \(R\)-modules obtained by applying the free-\(R\)-module
  functor to \(y_U\) objectwise. Compose three natural bijections:
  \begin{itemize}
    \item sheafification is left adjoint to the inclusion of sheaves into presheaves, giving
      \(\Hom(R[U],F) \cong \Hom_{\mathrm{PSh}}(y_U \otimes R,\, F)\), naturally in \(F\);
    \item on each object \(V\), the free-\(R\)-module functor is left adjoint to the
      forgetful functor from \(R\)-modules to sets, giving
      \(\Hom_{\mathrm{PSh}}(y_U \otimes R,\, F) \cong \Hom_{\mathrm{PSh}(\mathrm{Set})}(y_U,\, F)\)
      (\(F\) viewed as a presheaf of sets), naturally in \(F\);
    \item the Yoneda lemma identifies \(\Hom_{\mathrm{PSh}(\mathrm{Set})}(y_U, F) \cong F(U)\).
  \end{itemize}
  Each bijection is additive and \(R\)-linear in \(F\) (the first two are hom-sets of
  \(R\)-linear/additive adjunctions; the last carries the \(R\)-module structure of \(F(U)\)
  tautologically, evaluating a natural transformation at the identity of \(U\)), so the
  composite is an \(R\)-linear equivalence.
\end{proof}

\begin{lemma}[Naturality of the section equivalence]
  \label{lem:freeModuleSheafHomEquiv_naturality}
  \lean{CategoryTheory.Sheaf.freeModuleSheafHomEquiv_comp,
    CategoryTheory.Sheaf.freeModuleSheafHomEquiv_map}
  \uses{def:freeModuleSheafHomEquiv, def:freeModuleSheafMap}
  \leanok
  The equivalence of \ref{def:freeModuleSheafHomEquiv} is natural in both variables:
  \begin{enumerate}
    \item for \(\varphi : R[U] \to F\) and \(f : F \to G\), the section of \(G(U)\)
      corresponding to \(f \circ \varphi\) is \(f_U\) applied to the section of \(F(U)\)
      corresponding to \(\varphi\);
    \item for \(i : U \to V\) and \(\varphi : R[V] \to F\), the section of \(F(U)\)
      corresponding to the composite \(R[U] \xrightarrow{R[i]} R[V] \xrightarrow{\varphi} F\)
      is the restriction along \(i\) of the section of \(F(V)\) corresponding to \(\varphi\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \leanok
  Both are naturality of the composite of adjunction bijections used in
  \ref{def:freeModuleSheafHomEquiv}: (1) is naturality of each of the three bijections in
  the target sheaf \(F\); (2) is naturality of the Yoneda bijection
  \(\Hom_{\mathrm{PSh}(\mathrm{Set})}(y_U,-) \cong \mathrm{ev}_U\) in \(U\) (precomposition
  with \(y_i : y_U \to y_V\) corresponds to restriction along \(i\)), transported through the
  other two (fixed) bijections.
\end{proof}

\begin{definition}[Cohomology of an object of the site]
  \label{def:HModule'}
  \lean{CategoryTheory.Sheaf.HModule'}
  \uses{def:freeModuleSheaf}
  \leanok
  For an object \(U\) of \(\mathcal C\), a sheaf \(F\) of \(R\)-modules and \(n \ge 0\), the
  degree-\(n\) cohomology of \(U\) with coefficients in \(F\) is the \(R\)-module
  \[
    H'^n(U, F) \;=\; \Ext^n\bigl(R[U],\, F\bigr).
  \]
\end{definition}

\begin{definition}[Degree zero is sections]
  \label{def:HModule'_linearEquiv0}
  \lean{CategoryTheory.Sheaf.HModule'.linearEquiv₀}
  \uses{def:HModule', def:freeModuleSheafHomEquiv}
  \leanok
  The \(R\)-linear equivalence \(H'^0(U, F) \cong F(U)\): the canonical identification
  \(\Ext^0(R[U], F) \cong \Hom(R[U], F)\) followed by \ref{def:freeModuleSheafHomEquiv}.
\end{definition}

\begin{definition}[Restriction]
  \label{def:HModule'_res}
  \lean{CategoryTheory.Sheaf.HModule'.res}
  \uses{def:HModule', def:freeModuleSheafMap}
  \leanok
  For \(i : U \to V\) in \(\mathcal C\), restriction along \(i\) is the \(R\)-linear map
  \(H'^n(V, F) \to H'^n(U, F)\), \(x \mapsto x \circ R[i]\): precomposition with
  \(R[i] : R[U] \to R[V]\) (contravariant functoriality of \(\Ext^n(-, F)\)).
\end{definition}

\begin{definition}[Functoriality in the coefficient sheaf]
  \label{def:HModule'_mapCoeff}
  \lean{CategoryTheory.Sheaf.HModule'.mapCoeff,
    CategoryTheory.Sheaf.HModule'.mapCoeff_id_apply,
    CategoryTheory.Sheaf.HModule'.mapCoeff_comp_apply}
  \uses{def:HModule'}
  \leanok
  A morphism of sheaves of \(R\)-modules \(f : F \to G\) induces, for every object \(U\) of
  \(\mathcal C\) and every \(n\), an \(R\)-linear map \(H'^n(U, F) \to H'^n(U, G)\),
  \(x \mapsto x \cdot f\): composition (Yoneda product) with the degree-zero class of \(f\), i.e.\
  covariant functoriality of \(\Ext^n(R[U], -)\) in the coefficient variable. This is the
  coefficient-variable analogue of the restriction \ref{def:HModule'_res} (functoriality in the
  object of the site). The identity induces the identity, and a composite \(g \circ f\) induces the
  composite of the induced maps.
\end{definition}
\begin{proof}
  \leanok
  Postcomposition with the degree-zero \(\Ext\)-class of \(f\) is \(R\)-linear; it sends the
  degree-zero class of the identity to the identity operation, and by associativity of the Yoneda
  product it turns the class of a composite into the composite of the two postcompositions.
\end{proof}

\begin{definition}[Coefficient-isomorphism transport for cohomology of an object]
  \label{def:HModule'_congrCoeff}
  \lean{CategoryTheory.Sheaf.HModule'.congrCoeff}
  \uses{def:HModule'_mapCoeff}
  \leanok
  An isomorphism \(\alpha : F \cong G\) of coefficient sheaves of \(R\)-modules induces, for every
  object \(U\) and every \(n\), an \(R\)-linear isomorphism \(H'^n(U, F) \cong H'^n(U, G)\).
\end{definition}
\begin{proof}
  \leanok
  Take the induced maps of \ref{def:HModule'_mapCoeff} for \(\alpha\) and for \(\alpha^{-1}\). By
  functoriality their two composites are the maps induced by \(\alpha^{-1}\circ\alpha = \id_F\) and
  \(\alpha\circ\alpha^{-1} = \id_G\), which are the identity operations; hence the two induced maps
  are mutually inverse \(R\)-linear isomorphisms.
\end{proof}

\begin{lemma}[Transport of vanishing along a coefficient isomorphism]
  \label{lem:HModule'_subsingleton_of_congrCoeff}
  \lean{CategoryTheory.Sheaf.HModule'.subsingleton_of_congrCoeff}
  \uses{def:HModule'_congrCoeff}
  \leanok
  If \(F \cong G\) as coefficient sheaves of \(R\)-modules and \(H'^n(U, G) = 0\), then
  \(H'^n(U, F) = 0\).
\end{lemma}
\begin{proof}
  \leanok
  The \(R\)-linear isomorphism \(H'^n(U, F) \cong H'^n(U, G)\) of \ref{def:HModule'_congrCoeff}
  identifies \(H'^n(U, F)\) with the zero module \(H'^n(U, G)\).
\end{proof}

\begin{definition}[The free sheaf on a terminal object is the constant sheaf]
  \label{def:freeModuleSheafIsoConstModuleSheaf}
  \lean{CategoryTheory.Sheaf.freeModuleSheafIsoConstModuleSheaf}
  \uses{def:freeModuleSheaf, def:constModuleSheaf, def:freeModuleSheafHomEquiv,
    def:constHomEquiv}
  \leanok
  If \(T\) is a terminal object of \(\mathcal C\), a canonical isomorphism of sheaves of
  \(R\)-modules \(R[T] \cong R_J\).
\end{definition}
\begin{proof}
  \leanok
  Both sides corepresent the same functor: \(\Hom(R[T], -) \cong \mathrm{ev}_T\) by
  \ref{def:freeModuleSheafHomEquiv}, and \(\Hom(R_J, -) \cong \mathrm{ev}_T\) by
  \ref{def:constHomEquiv} (valid since \(T\) is terminal), both naturally in the sheaf
  argument. Two objects corepresenting the same functor via natural equivalences are
  canonically isomorphic: the isomorphism corresponds, under each equivalence, to the section
  of the other object at \(T\) that corresponds to its own identity morphism, and the two
  composites are the identity by naturality applied to the identity morphism of each side.
\end{proof}

\begin{definition}[Cohomology of the site is cohomology of a terminal object]
  \label{def:HModule_linearEquivHModule'}
  \lean{CategoryTheory.Sheaf.HModule.linearEquivHModule'}
  \uses{def:HModule, def:HModule', def:freeModuleSheafIsoConstModuleSheaf}
  \leanok
  For \(T\) terminal in \(\mathcal C\) and every \(n\), an \(R\)-linear equivalence
  \(H^n(F) \cong H'^n(T, F)\).
\end{definition}
\begin{proof}
  \leanok
  Apply the (contravariant, \(R\)-linear) functoriality of \(\Ext^n(-, F)\) to the
  isomorphism \(R[T] \cong R_J\) of \ref{def:freeModuleSheafIsoConstModuleSheaf}: an
  isomorphism of the first \(\Ext\)-argument induces, by composition (Yoneda product) with
  its degree-zero class, a natural \(R\)-linear isomorphism on \(\Ext\)-groups in every
  degree, with inverse given by composition with the inverse isomorphism.
\end{proof}

\section{The structure sheaf as a sheaf of modules}

Let \(k\) be a commutative ring and let \(X\) be a scheme over \(\Spec k\). The relevant site
is the \emph{small Zariski site} of \(X\): the partially ordered set of open subsets of
\(X\), with coverings the open coverings. The whole space is a terminal object of this site.

\begin{definition}[The algebra map on sections]
  \label{def:overAlgebraMap}
  \lean{AlgebraicGeometry.Scheme.overAlgebraMap}
  \leanok
  For every open \(U \subseteq X\), the canonical ring homomorphism \(k \to \Gamma(X, U)\):
  the map induced on global sections by the structure morphism, followed by restriction to
  \(U\). It commutes with the restriction maps of the structure sheaf; in particular each
  \(\Gamma(X, U)\) is a \(k\)-algebra --- hence a \(k\)-module --- and all restriction maps
  are \(k\)-linear.
\end{definition}
\begin{proof}
  \leanok
  Restriction maps are ring homomorphisms and commute with restriction from the global
  sections; the maps from \(k\) are fixed composites of such maps, so they commute with
  further restriction.
\end{proof}

\begin{definition}[The structure sheaf as a sheaf of \(k\)-modules]
  \label{def:moduleKSheaf}
  \lean{AlgebraicGeometry.Scheme.moduleKSheaf}
  \uses{def:overAlgebraMap}
  \leanok
  The structure sheaf of \(X\), viewed as a sheaf \(\struct{X/k}\) of \(k\)-modules on the
  small Zariski site of \(X\): its sections over an open \(U\) are \(\Gamma(X, U)\) with the
  \(k\)-module structure of \ref{def:overAlgebraMap}, and its restriction maps are those of
  the structure sheaf.
\end{definition}
\begin{proof}
  \leanok
  The restriction maps are \(k\)-linear by \ref{def:overAlgebraMap}, so this is a presheaf of
  \(k\)-modules. Its underlying presheaf of sets is that of the structure sheaf, which
  satisfies the sheaf condition; since limits of \(k\)-modules are computed on underlying
  sets, the presheaf of \(k\)-modules is a sheaf.
\end{proof}

\begin{definition}[Degree-zero cohomology of the structure sheaf]
  \label{def:moduleKSheafHZero}
  \lean{AlgebraicGeometry.Scheme.moduleKSheafHZero}
  \uses{def:moduleKSheaf, def:HModule_linearEquiv0}
  \leanok
  The \(k\)-linear equivalence \(H^0\bigl(X, \struct{X/k}\bigr) \cong \Gamma(X, \struct X)\).
\end{definition}
\begin{proof}
  \leanok
  The open \(X\) is a terminal object of the small Zariski site; apply
  \ref{def:HModule_linearEquiv0}.
\end{proof}

\section{\v{C}ech cobounding on affine opens}

For a scheme \(X\), a section \(g\) of the structure sheaf on an open \(V \subseteq X\) and
an open \(U \subseteq V\), we write \(D(g)\) for the basic open locus of \(V\) where \(g\) is
invertible, and \(g|_U\), \(s|_U\) for restrictions of sections.

\begin{lemma}[Denominator clearing on an affine open]
  \label{lem:denominator_clearing}
  \lean{AlgebraicGeometry.IsAffineOpen.exists_res_eq_pow_mul}
  \leanok
  Let \(X\) be a scheme, \(U \subseteq X\) an affine open, \(V \subseteq X\) an open with
  \(U \subseteq V\), and \(g \in \Gamma(X, V)\) a section of the structure sheaf on \(V\) (so
  that \(D(g) \subseteq V\) is its basic open). For every \(c \in \Gamma(X, U \cap D(g))\)
  there exist \(N \ge 0\) and \(e \in \Gamma(X, U)\) such that
  \[
    e|_{U \cap D(g)} \;=\; \bigl(g|_{U}\bigr)|_{U \cap D(g)}^{N} \cdot c .
  \]
\end{lemma}
\begin{proof}
  \leanok
  \(U \cap D(g)\) is the basic open of the affine \(U\) defined by \(g|_U\), and restriction
  identifies the sections over the basic open of an affine open with the localization:
  \(\Gamma(X, U \cap D(g)) = \Gamma(X, U)\bigl[1/(g|_U)\bigr]\) (quasi-coherence of the
  structure sheaf). Writing \(c\) as a fraction \(e / (g|_U)^N\) and clearing the denominator
  gives the claim.
\end{proof}

\begin{lemma}[Annihilation on an affine open]
  \label{lem:section_annihilation}
  \lean{AlgebraicGeometry.IsAffineOpen.exists_pow_mul_eq_zero_of_res_eq_zero}
  \leanok
  Let \(X\) be a scheme, \(U \subseteq X\) an affine open, \(V \subseteq X\) an open with
  \(U \subseteq V\), and \(g \in \Gamma(X, V)\) a section of the structure sheaf on \(V\) (so
  that \(D(g) \subseteq V\) is its basic open). If \(t \in \Gamma(X, U)\) restricts to zero
  on \(U \cap D(g)\), then \((g|_U)^{M} \cdot t = 0\) in \(\Gamma(X, U)\) for some \(M \ge 0\).
\end{lemma}
\begin{proof}
  \leanok
  As in \ref{lem:denominator_clearing}, \(\Gamma(X, U \cap D(g))\) is the localization of
  \(\Gamma(X, U)\) at the powers of \(g|_U\), and the kernel of the localization map consists
  of the elements annihilated by a power of \(g|_U\).
\end{proof}

\begin{theorem}[Degree-one \v{C}ech cobounding on an affine open]
  \label{thm:affine_open_cech_cobounding}
  \lean{AlgebraicGeometry.IsAffineOpen.exists_cech_cobounding}
  \leanok
  \source{stacks-project}
  Let \(X\) be a scheme and \(U\) an affine open of \(X\). Let \(f_1, \dots, f_n \in
  \Gamma(X, U)\) with \(D(f_1) \cup \dots \cup D(f_n) = U\). Let
  \(a_{ij} \in \Gamma\bigl(X, D(f_i) \cap D(f_j)\bigr)\) be a \v{C}ech \(1\)-cocycle: for all
  \(i, j, l\),
  \[
    a_{il} \;=\; a_{ij} + a_{jl}
    \qquad \text{on } D(f_i) \cap D(f_j) \cap D(f_l).
  \]
  Then there are sections \(b_i \in \Gamma\bigl(X, D(f_i)\bigr)\) with
  \[
    a_{ij} \;=\; b_i - b_j \qquad \text{on } D(f_i) \cap D(f_j)
  \]
  for all \(i, j\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:denominator_clearing, lem:section_annihilation}
  All restriction maps are suppressed from the notation. Note that each \(D(f_i)\) and each
  pairwise intersection \(D(f_i) \cap D(f_j) = D(f_i f_j)\) is an affine open of \(U\), hence
  of \(X\).

  \emph{Step 1: clear denominators with a uniform exponent.} For each pair \((i,j)\) apply
  \ref{lem:denominator_clearing} with affine open \(D(f_i)\), ambient open \(V = U\) and
  \(g = f_j\): there are \(N_{ij} \ge 0\) and \(e^0_{ij} \in \Gamma(X, D(f_i))\) with
  \(e^0_{ij} = f_j^{N_{ij}} a_{ij}\) on \(D(f_i) \cap D(f_j)\). Let \(N\) be the maximum of
  the \(N_{ij}\) and set \(e_{ij} = f_j^{\,N - N_{ij}}\, e^0_{ij}\), so that
  \(e_{ij} = f_j^{\,N} a_{ij}\) on \(D(f_i) \cap D(f_j)\).

  \emph{Step 2: kill the defects.} For \(i, j, l\) define, on \(D(f_i) \cap D(f_j)\),
  \[
    t_{ijl} \;=\; e_{il} - e_{jl} - f_l^{\,N} a_{ij}.
  \]
  On the triple intersection \(D(f_i) \cap D(f_j) \cap D(f_l)\) we have
  \(e_{il} = f_l^N a_{il}\) and \(e_{jl} = f_l^N a_{jl}\), so the cocycle identity gives
  \(t_{ijl} = f_l^N (a_{il} - a_{jl} - a_{ij}) = 0\) there. Since
  \(D(f_i) \cap D(f_j)\) is an affine open (of \(U\), hence of \(X\)) and the triple
  intersection is its basic open defined by \(f_l\), \ref{lem:section_annihilation} (with
  ambient open \(V = U\)) yields \(M_{ijl} \ge 0\) with
  \(f_l^{\,M_{ijl}}\, t_{ijl} = 0\) on \(D(f_i) \cap D(f_j)\). Let \(M\) be the maximum of
  the \(M_{ijl}\); then \(f_l^{\,M} t_{ijl} = 0\) for all \(i,j,l\).

  \emph{Step 3: partition of unity.} Since the \(D(f_i)\) cover the affine open \(U\), the
  \(f_i\) generate the unit ideal of \(\Gamma(X, U)\); hence so do the powers
  \(f_i^{\,N+M}\), and we may write \(1 = \sum_l h_l\, f_l^{\,N+M}\) with
  \(h_l \in \Gamma(X, U)\).

  \emph{Step 4: assemble the cobounding.} Set
  \(b_i = \sum_l h_l\, f_l^{\,M}\, e_{il} \in \Gamma\bigl(X, D(f_i)\bigr)\). On
  \(D(f_i) \cap D(f_j)\),
  \[
    b_i - b_j
      = \sum_l h_l f_l^{\,M} \bigl(e_{il} - e_{jl}\bigr)
      = \sum_l h_l f_l^{\,M} \bigl(f_l^{\,N} a_{ij} + t_{ijl}\bigr)
      = \Bigl(\sum_l h_l f_l^{\,N+M}\Bigr) a_{ij}
      = a_{ij},
  \]
  using \(f_l^{\,M} t_{ijl} = 0\) in the third equality.
\end{proof}

\begin{theorem}[Degree-one \v{C}ech cobounding on an affine scheme]
  \label{thm:cech_cobounding}
  \lean{AlgebraicGeometry.Scheme.exists_cech_cobounding}
  \uses{thm:affine_open_cech_cobounding}
  \leanok
  Let \(X\) be an affine scheme and let \(f_1, \dots, f_n\) be global sections of the
  structure sheaf with \(D(f_1) \cup \dots \cup D(f_n) = X\). Let
  \(a_{ij} \in \Gamma\bigl(X, D(f_i) \cap D(f_j)\bigr)\) be a \v{C}ech \(1\)-cocycle as in
  \ref{thm:affine_open_cech_cobounding}. Then there are sections
  \(b_i \in \Gamma\bigl(X, D(f_i)\bigr)\) with \(a_{ij} = b_i - b_j\) on
  \(D(f_i) \cap D(f_j)\) for all \(i, j\).
\end{theorem}
\begin{proof}
  \leanok
  The special case \(U = X\) of \ref{thm:affine_open_cech_cobounding}: an affine scheme is
  an affine open of itself.
\end{proof}

\section{Vanishing of degree-one cohomology on affine opens}

\begin{lemma}[A vanishing criterion for \(\Ext^1\)]
  \label{lem:ext_one_vanishing_criterion}
  \lean{CategoryTheory.Abelian.Ext.subsingleton_one_of_injective_of_surjective}
  \leanok
  Let \(\mathcal A\) be an abelian category (with \(\Ext\)-groups), let
  \(\iota : A \to I\) be a monomorphism with \(I\) injective, and let \(L\) be an object. If
  every morphism \(L \to \coker \iota\) lifts along the projection
  \(\pi : I \to \coker \iota\), then \(\Ext^1(L, A) = 0\).
\end{lemma}
\begin{proof}
  \leanok
  Consider the short exact sequence \(0 \to A \to I \to \coker \iota \to 0\) and the induced
  long exact sequence
  \[
    \Hom(L, I) \xrightarrow{\;\pi_*\;} \Hom(L, \coker \iota)
      \xrightarrow{\;\delta\;} \Ext^1(L, A) \longrightarrow \Ext^1(L, I).
  \]
  Let \(z \in \Ext^1(L, A)\). Its image in \(\Ext^1(L, I)\) vanishes because \(I\) is
  injective, so by exactness \(z = \delta(x)\) for some \(x : L \to \coker \iota\). By
  hypothesis \(x = \pi \circ \psi\) for some \(\psi : L \to I\), and
  \(\delta \circ \pi_* = 0\) (composite of consecutive maps of the long exact sequence);
  hence \(z = \delta(\pi_*(\psi)) = 0\).
\end{proof}

\begin{lemma}[Sections are left exact]
  \label{lem:sections_left_exact}
  \lean{CategoryTheory.Sheaf.exists_app_eq_of_cokernelπ_app_eq_zero}
  \leanok
  Let \(\iota : F \to G\) be a monomorphism of sheaves of \(R\)-modules on a site and let
  \(U\) be an object of the site. If \(c \in G(U)\) maps to zero in \((\coker \iota)(U)\),
  then \(c = \iota_U(a)\) for a (unique) \(a \in F(U)\).
\end{lemma}
\begin{proof}
  \leanok
  In an abelian category, a monomorphism is a kernel of its cokernel. Evaluation of sheaves
  at \(U\) preserves limits: it is the composite of the inclusion of sheaves into presheaves
  (a right adjoint, sheafification being left adjoint to it) with evaluation of presheaves at
  \(U\) (limits of presheaves are computed objectwise). Hence
  \(F(U) \to G(U)\) is a kernel of \(G(U) \to (\coker \iota)(U)\), which is the claim.
\end{proof}

\begin{lemma}[Monomorphisms are injective on sections]
  \label{lem:app_injective_of_mono}
  \lean{CategoryTheory.Sheaf.app_injective_of_mono}
  \leanok
  A monomorphism of sheaves of \(R\)-modules on a site is injective on sections over every
  object of the site.
\end{lemma}
\begin{proof}
  \leanok
  Evaluation of sheaves at an object preserves limits (as in
  \ref{lem:sections_left_exact}), hence preserves monomorphisms, and a monomorphism of
  \(R\)-modules is an injective map.
\end{proof}

\begin{theorem}[Sections surjectivity on an affine open]
  \label{thm:cokernel_app_surjective_affine_open}
  \lean{AlgebraicGeometry.IsAffineOpen.cokernel_app_surjective}
  \uses{def:moduleKSheaf}
  \leanok
  Let \(k\) be a commutative ring, \(X\) a scheme over \(\Spec k\), \(U\) an affine open of
  \(X\), \(G\) a sheaf of \(k\)-modules on the small Zariski site of \(X\), and
  \(\iota : \struct{X/k} \to G\) a monomorphism. Then every section of
  \(\coker \iota\) over \(U\) lifts to a section of \(G\) over \(U\): the map
  \(G(U) \to (\coker \iota)(U)\) is surjective.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:sections_left_exact, lem:app_injective_of_mono, thm:affine_open_cech_cobounding}
  Let \(q \in (\coker \iota)(U)\) and write \(\pi : G \to \coker \iota\) for the projection.

  (a) \(\pi\) is an epimorphism of sheaves, hence locally surjective on sections: every point
  of \(U\) has an open neighbourhood on which the restriction of \(q\) lifts to \(G\).
  Shrinking, and since the basic opens of \(U\) form a basis of \(U\) (as \(U\) is affine),
  every point of \(U\) lies in some basic open \(D(g) \subseteq U\) carrying a lift of
  \(q|_{D(g)}\).

  (b) \(U\) is quasi-compact (it is affine), so there are finitely many sections
  \(f_1, \dots, f_n \in \Gamma(X, U)\) with \(D(f_1) \cup \dots \cup D(f_n) = U\) and lifts
  \(s_i \in G(D(f_i))\) with \(\pi(s_i) = q|_{D(f_i)}\).

  (c) On \(D(f_i) \cap D(f_j)\) the difference \(s_i - s_j\) is killed by \(\pi\), so by
  \ref{lem:sections_left_exact} there is a unique
  \(a_{ij} \in \Gamma\bigl(X, D(f_i) \cap D(f_j)\bigr)\) with
  \(\iota(a_{ij}) = s_i - s_j\).

  (d) The \(a_{ij}\) form a \v{C}ech \(1\)-cocycle: on triple intersections,
  \(\iota(a_{il}) = s_i - s_l = (s_i - s_j) + (s_j - s_l) = \iota(a_{ij} + a_{jl})\), and
  \(\iota\) is injective on sections (\ref{lem:app_injective_of_mono}).

  (e) By \ref{thm:affine_open_cech_cobounding} (applied to the affine open \(U\)) there are
  \(b_i \in \Gamma\bigl(X, D(f_i)\bigr)\) with \(a_{ij} = b_i - b_j\) on overlaps. The
  corrected lifts \(s_i - \iota(b_i)\) then agree on all overlaps, so by the sheaf condition
  they glue to a section \(s \in G(U)\).

  (f) Finally \(\pi(s) = q\): on each \(D(f_i)\) we have
  \(\pi(s) = \pi(s_i) - \pi(\iota(b_i)) = q|_{D(f_i)}\) since \(\pi \circ \iota = 0\), and
  sections of the sheaf \(\coker \iota\) that agree on a cover of \(U\) agree on \(U\).
\end{proof}

\begin{theorem}[Vanishing of \(H^1{}'\) on affine opens]
  \label{thm:affine_open_h1_vanishing}
  \lean{AlgebraicGeometry.IsAffineOpen.subsingleton_moduleKSheaf_hModule'_one}
  \uses{def:HModule', def:moduleKSheaf, thm:cokernel_app_surjective_affine_open}
  \leanok
  \source{stacks-project}
  Let \(k\) be a commutative ring, \(X\) a scheme over \(\Spec k\) and \(U\) an affine open
  of \(X\). Then
  \[
    H'^1\bigl(U, \struct{X/k}\bigr) \;=\; 0 .
  \]
  No hypothesis on \(X\) beyond the affineness of \(U\) is needed.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:ext_one_vanishing_criterion, def:freeModuleSheafHomEquiv}
  The category of sheaves of \(k\)-modules on the small Zariski site of \(X\) is Grothendieck
  abelian, hence has enough injectives: choose a monomorphism
  \(\iota : \struct{X/k} \to G\) with \(G\) injective. By
  \ref{lem:ext_one_vanishing_criterion} (with \(L = k[U]\) the free sheaf of \(k\)-modules on
  \(U\)), it suffices to lift every morphism \(k[U] \to \coker \iota\) along
  \(G \to \coker \iota\). By \ref{def:freeModuleSheafHomEquiv}, morphisms out of \(k[U]\) are,
  compatibly with postcomposition, sections over \(U\); so the required lifting is exactly
  the surjectivity of \(G(U) \to (\coker \iota)(U)\), which is
  \ref{thm:cokernel_app_surjective_affine_open}.
\end{proof}

\begin{theorem}[Vanishing of \(H^1\) on affine schemes]
  \label{thm:affine_vanishing}
  \lean{AlgebraicGeometry.Scheme.subsingleton_moduleKSheaf_hModule_one}
  \uses{def:HModule, def:moduleKSheaf}
  \leanok
  \source{stacks-project}
  Let \(k\) be a commutative ring and \(X\) an affine scheme over \(\Spec k\). Then
  \[
    H^1\bigl(X, \struct{X/k}\bigr) \;=\; 0 .
  \]
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:ext_one_vanishing_criterion, thm:cokernel_app_surjective_affine_open,
    def:constHomEquiv, lem:constHomEquiv_naturality}
  The category of sheaves of \(k\)-modules on the small Zariski site of \(X\) is Grothendieck
  abelian, hence has enough injectives: choose a monomorphism
  \(\iota : \struct{X/k} \to G\) with \(G\) injective. By
  \ref{lem:ext_one_vanishing_criterion} (with \(L = k_J\) the constant sheaf), it suffices to
  lift every morphism \(k_J \to \coker \iota\) along \(G \to \coker \iota\). By
  \ref{def:constHomEquiv} and its naturality \ref{lem:constHomEquiv_naturality}, morphisms
  out of \(k_J\) are global sections, compatibly with postcomposition; so the required
  lifting is exactly the surjectivity of \(G(X) \to (\coker \iota)(X)\), i.e.\ of
  \(G(\top) \to (\coker \iota)(\top)\), which is
  \ref{thm:cokernel_app_surjective_affine_open} applied to the affine open \(U = \top\)
  (an affine scheme is an affine open of itself).
\end{proof}

\section{Twisted affine vanishing: quasi-coherent coefficients}
\label{sec:qcoh_vanishing}

The vanishing of the previous section is stated for the structure sheaf, but Serre's argument
only ever uses two features of \(\struct{X/k}\): that ambient sections act on sections, and that
sections localise on affine opens. This section isolates those two features as a packaging on an
arbitrary sheaf of \(k\)-modules and reruns the argument, obtaining degree-one vanishing on an
affine open with those coefficients. The intended application is to line bundles trivialised on
an affine chart, for which the packaging holds chart by chart.

For a sheaf \(F\) of \(k\)-modules on the small Zariski site of \(X\) and an inclusion of opens
\(W \subseteq V\), write \(s|_W\) (\emph{section restriction}) for the image of \(s \in F(V)\)
under the \(k\)-linear restriction \(F(V) \to F(W)\); it is functorial in the inclusion and
natural in \(F\).

\begin{definition}[Quasi-coherence packaging on an open]
  \label{def:qcohOn}
  \lean{AlgebraicGeometry.Scheme.QcohOn}
  \leanok
  Let \(X\) be a scheme, \(U\) an open of \(X\), and \(F\) a sheaf of \(k\)-modules on the small
  Zariski site of \(X\). A \emph{quasi-coherence packaging} of \(F\) on \(U\) is the data of:
  \begin{itemize}
    \item \textbf{(P1) an action} of the fixed ring \(\Gamma(X, U)\): for every open \(W \le U\)
      a scaling operation \(r \cdot m\) of \(r \in \Gamma(X, U)\) on \(m \in F(W)\), satisfying
      the module laws over \(\Gamma(X, U)\) (unit, associativity, and both distributivities) and
      natural under section restriction, \((r \cdot m)|_{W'} = r \cdot (m|_{W'})\) for \(W' \le
      W\);
    \item \textbf{(P2) localisation on affine opens} \(V \le U\), for every \(g \in \Gamma(X,
      U)\), in the two-lemma form of localisation away from \(g\):
      \begin{itemize}
        \item \emph{denominator clearing} — every \(c \in F(V \cap D(g))\) is \((g^N \cdot
          e)|_{V \cap D(g)}\) for some \(N \ge 0\) and \(e \in F(V)\);
        \item \emph{defect annihilation} — every \(t \in F(V)\) with \(t|_{V \cap D(g)} = 0\) is
          killed by a power of \(g\): \(g^M \cdot t = 0\) for some \(M \ge 0\).
      \end{itemize}
  \end{itemize}
  The action is by the single ring \(\Gamma(X, U)\) (not a per-open module structure), with the
  inclusion \(W \le U\) an explicit argument.
\end{definition}

\begin{theorem}[The structure sheaf is quasi-coherently packaged]
  \label{thm:moduleKSheaf_qcohOn}
  \lean{AlgebraicGeometry.Scheme.moduleKSheaf.instQcohOn}
  \uses{def:qcohOn, def:moduleKSheaf, lem:denominator_clearing, lem:section_annihilation}
  \leanok
  For \(X\) a scheme over \(\Spec k\), the structure sheaf \(\struct{X/k}\), viewed as a sheaf of
  \(k\)-modules, carries a quasi-coherence packaging on every open \(U\): the action of \(r \in
  \Gamma(X, U)\) on \(s \in \Gamma(X, W)\) is \(r|_W \cdot s\), the ordinary
  restriction-then-multiplication.
\end{theorem}
\begin{proof}
  \leanok
  The (P1) module laws are the ring axioms of \(\Gamma(X, W)\), and naturality under restriction
  holds because restriction is a ring homomorphism. The two (P2) axioms, with the action spelled
  out, are exactly denominator clearing (\ref{lem:denominator_clearing}) and annihilation
  (\ref{lem:section_annihilation}) for the structure sheaf.
\end{proof}

\begin{theorem}[Degree-one \v{C}ech cobounding, quasi-coherent coefficients]
  \label{thm:cech_cobounding_qcoh}
  \lean{AlgebraicGeometry.IsAffineOpen.exists_cech_cobounding_of_qcoh}
  \uses{def:qcohOn}
  \leanok
  Let \(U\) be an affine open of a scheme \(X\), covered by basic opens \(D(f_1), \dots, D(f_n)\),
  and let \(F\) be a sheaf of \(k\)-modules with a quasi-coherence packaging on \(U\). Every
  \v{C}ech \(1\)-cocycle \(a_{ij} \in F(D(f_i) \cap D(f_j))\) (with \(a_{il} = a_{ij} + a_{jl}\)
  on triple overlaps) is a coboundary: there are \(b_i \in F(D(f_i))\) with \(a_{ij} = b_i|_{D(f_i)
  \cap D(f_j)} - b_j|_{D(f_i) \cap D(f_j)}\).
\end{theorem}
\begin{proof}
  \leanok
  Verbatim the structure-sheaf argument \ref{thm:affine_open_cech_cobounding}, reading the
  packaging axioms in place of the structure-sheaf localisation. Clear denominators with one
  uniform exponent \(N\) (denominator clearing of the packaging), producing \(e_{ij} \in
  F(D(f_i))\) with \(e_{ij}|_{D(f_i) \cap D(f_j)} = f_j^N \cdot a_{ij}\). The triple-overlap
  defects \(t_{ijl} = e_{il} - e_{jl} - f_l^N \cdot a_{ij}\) vanish on the triple intersections by
  the cocycle identity, hence are killed by a uniform power \(f_l^M\) (defect annihilation). With
  a partition of unity \(1 = \sum_l h_l f_l^{N+M}\) of the affine \(U\), set \(b_i = \sum_l h_l
  f_l^M \cdot e_{il}\); the assembly \(b_i - b_j = \sum_l h_l f_l^M(e_{il} - e_{jl}) = (\sum_l h_l
  f_l^{N+M}) \cdot a_{ij} = a_{ij}\) uses only that the action distributes over restriction and
  sums, i.e.\ the (P1) mixin.
\end{proof}

\begin{theorem}[Sections surjectivity on an affine open, quasi-coherent coefficients]
  \label{thm:cokernel_app_surjective_qcoh}
  \lean{AlgebraicGeometry.IsAffineOpen.cokernel_app_surjective_of_qcoh}
  \uses{def:qcohOn, thm:cech_cobounding_qcoh, lem:sections_left_exact, lem:app_injective_of_mono}
  \leanok
  Let \(U\) be an affine open of a scheme \(X\), let \(F\) be a sheaf of \(k\)-modules with a
  quasi-coherence packaging on \(U\), and let \(\iota : F \to G\) be a monomorphism of sheaves of
  \(k\)-modules. Then every section of \(\coker \iota\) over \(U\) lifts to a section of \(G\)
  over \(U\).
\end{theorem}
\begin{proof}
  \leanok
  Verbatim \ref{thm:cokernel_app_surjective_affine_open} with \(F\) in place of \(\struct{X/k}\).
  Local lifts of \(q \in (\coker \iota)(U)\) exist on a finite basic cover \(D(f_i)\) of \(U\) by
  local surjectivity of the epimorphism \(\coker\iota\)-projection and quasi-compactness. On
  overlaps the differences of the lifts are killed by the projection, so by left-exactness of
  sections (\ref{lem:sections_left_exact}) they come from \(F\)-sections \(a_{ij}\); these form a
  \v{C}ech \(1\)-cocycle (\(\iota\) is injective on sections, \ref{lem:app_injective_of_mono}),
  which cobounds by \ref{thm:cech_cobounding_qcoh}. The corrected lifts glue to a section of \(G\)
  over \(U\) mapping to \(q\).
\end{proof}

\begin{theorem}[Twisted affine vanishing of \(H^1{}'\)]
  \label{thm:hModule1_vanishing_qcoh}
  \lean{AlgebraicGeometry.IsAffineOpen.subsingleton_hModule'_one_of_qcoh}
  \uses{def:qcohOn, def:HModule', thm:cokernel_app_surjective_qcoh,
    lem:ext_one_vanishing_criterion, def:freeModuleSheafHomEquiv}
  \leanok
  Let \(U\) be an affine open of a scheme \(X\) and \(F\) a sheaf of \(k\)-modules with a
  quasi-coherence packaging on \(U\). Then the degree-one cohomology of the object \(U\) with
  coefficients in \(F\) vanishes:
  \[
    H'^1(U, F) \;=\; 0 .
  \]
  Taking \(F = \struct{X/k}\) recovers \ref{thm:affine_open_h1_vanishing}.
\end{theorem}
\begin{proof}
  \leanok
  As in \ref{thm:affine_open_h1_vanishing}: choose a monomorphism \(\iota : F \to G\) with \(G\)
  injective; by the \(\Ext^1\) vanishing criterion \ref{lem:ext_one_vanishing_criterion} (with
  \(L = k[U]\) the free sheaf of \(k\)-modules on \(U\)) it suffices to lift every morphism
  \(k[U] \to \coker \iota\) along \(G \to \coker \iota\), which by \ref{def:freeModuleSheafHomEquiv}
  is the surjectivity of \(G(U) \to (\coker \iota)(U)\) — Theorem
  \ref{thm:cokernel_app_surjective_qcoh}.
\end{proof}

\begin{theorem}[Twisted affine vanishing of \(H^1\)]
  \label{thm:hModule_vanishing_qcoh}
  \lean{AlgebraicGeometry.Scheme.subsingleton_hModule_one_of_qcoh}
  \uses{def:qcohOn, def:HModule, thm:hModule1_vanishing_qcoh, def:HModule_linearEquivHModule'}
  \leanok
  Let \(X\) be an affine scheme and \(F\) a sheaf of \(k\)-modules with a quasi-coherence
  packaging on \(\top\). Then the degree-one cohomology of the site vanishes,
  \(H^1(X, F) = 0\). Taking \(F = \struct{X/k}\) recovers \ref{thm:affine_vanishing}.
\end{theorem}
\begin{proof}
  \leanok
  Apply \ref{thm:hModule1_vanishing_qcoh} to the affine open \(U = \top\) (an affine scheme is an
  affine open of itself) and transport the object-cohomology vanishing to the site cohomology
  along the equivalence \ref{def:HModule_linearEquivHModule'}.
\end{proof}

The two (P2) axioms of the packaging are not merely \emph{sufficient} for Serre's argument:
they say precisely that restriction from an affine chart to a basic open of the chart is a
localisation of modules. The remaining nodes of this section record that bridge, which lets
any packaged sheaf on an affine chart be read through the general theory of localised
modules --- in particular, it is how the two-lattice description of the two-cover complex
consumes the packaging.

\begin{definition}[The chart-ring module structure on packaged sections]
  \label{def:qcohOn_module}
  \lean{AlgebraicGeometry.Scheme.QcohOn.moduleOfLE}
  \uses{def:qcohOn}
  \leanok
  Let \(F\) carry a quasi-coherence packaging on \(U\) and let \(V \le U\). The (P1) action
  makes the \(k\)-module \(F(V)\) a module over the chart ring \(\Gamma(X, U)\): the unit,
  associativity and distributivity laws are the (P1) axioms, and the remaining law
  \(0 \cdot m = 0\) follows by adding \(0 \cdot m\) to both sides of
  \((0 + 0) \cdot m = 0 \cdot m\) and cancelling.
\end{definition}

\begin{definition}[Restriction is linear over the chart ring]
  \label{def:qcohOn_secRes_linear}
  \lean{AlgebraicGeometry.Scheme.QcohOn.secResₗ}
  \uses{def:qcohOn_module}
  \leanok
  For opens \(V \le W \le U\), section restriction \(F(W) \to F(V)\) is
  \(\Gamma(X, U)\)-linear for the module structures of \ref{def:qcohOn_module}: it is
  additive, being a map of \(k\)-modules, and it commutes with the action by the (P1)
  restriction-naturality \((r \cdot m)|_V = r \cdot (m|_V)\).
\end{definition}

\begin{theorem}[The packaging axioms are the localisation axioms]
  \label{thm:qcohOn_isLocalizedModule}
  \lean{AlgebraicGeometry.Scheme.QcohOn.isLocalizedModule_secResₗ}
  \uses{def:qcohOn, def:qcohOn_module, def:qcohOn_secRes_linear}
  \leanok
  Let \(U\) be an affine open of a scheme \(X\), let \(F\) be a sheaf of \(k\)-modules with
  a quasi-coherence packaging on \(U\), and let \(g \in \Gamma(X, U)\) act invertibly on
  \(F(U \cap D(g))\) (for the module structure of \ref{def:qcohOn_module}). Then the
  restriction map \(F(U) \to F(U \cap D(g))\) exhibits \(F(U \cap D(g))\) as the
  localisation of the \(\Gamma(X, U)\)-module \(F(U)\) at the multiplicative set
  \(S = \{1, g, g^2, \dots\}\) of powers of \(g\); that is:
  \begin{enumerate}
    \item every element of \(S\) acts invertibly on \(F(U \cap D(g))\);
    \item every \(c \in F(U \cap D(g))\) is of the form \(g^{-N} \cdot (e|_{U \cap D(g)})\)
      for some \(N \ge 0\) and \(e \in F(U)\);
    \item any two sections of \(F(U)\) with equal restriction to \(U \cap D(g)\) differ by
      an element killed by a power of \(g\).
  \end{enumerate}
  These three properties characterise the localisation map \(M \to S^{-1}M\) up to unique
  isomorphism under \(F(U)\).
\end{theorem}
\begin{proof}
  \leanok
  Each axiom is the term-for-term image of one piece of the packaging data. (1) Powers of
  an invertibly-acting element act invertibly. (2) Denominator clearing on the affine open
  \(U\) itself produces, for \(c \in F(U \cap D(g))\), an exponent \(N\) and a section
  \(e \in F(U)\) with \(e|_{U \cap D(g)} = g^N \cdot c\); acting by the inverse of
  \(g^N\) gives \(c = g^{-N} \cdot (e|_{U \cap D(g)})\). (3) If
  \(x_1|_{U \cap D(g)} = x_2|_{U \cap D(g)}\) then \(x_1 - x_2\) restricts to \(0\) on
  \(U \cap D(g)\), so defect annihilation yields \(M \ge 0\) with
  \(g^M \cdot (x_1 - x_2) = 0\).
\end{proof}

\begin{theorem}[Sections over a basic open are the localised sections]
  \label{thm:qcohOn_isLocalizedModule_moduleKSheaf}
  \lean{AlgebraicGeometry.Scheme.QcohOn.isLocalizedModule_secResₗ_moduleKSheaf}
  \uses{thm:qcohOn_isLocalizedModule, thm:moduleKSheaf_qcohOn, def:moduleKSheaf}
  \leanok
  Let \(X\) be a scheme over \(\Spec k\), \(U\) an affine open, and \(g \in \Gamma(X, U)\).
  Then restriction exhibits \(\Gamma(X, U \cap D(g))\) as the localisation of
  \(\Gamma(X, U)\) at the powers of \(g\) --- the classical
  \(\Gamma(X, D(g)) = \Gamma(X, U)_g\), with no hypothesis on \(g\).
\end{theorem}
\begin{proof}
  \leanok
  The structure sheaf carries the packaging on \(U\) (\ref{thm:moduleKSheaf_qcohOn}), with
  the action of \(r \in \Gamma(X, U)\) given by restriction-then-multiplication. The unit
  hypothesis of \ref{thm:qcohOn_isLocalizedModule} is discharged for free: \(g\) restricts
  to a unit on \(D(g)\), hence on \(U \cap D(g)\), so multiplication by
  \(g|_{U \cap D(g)}\) --- which is the packaging action of \(g\) --- is invertible on
  \(\Gamma(X, U \cap D(g))\). Apply \ref{thm:qcohOn_isLocalizedModule}.
\end{proof}

\section{The Mayer--Vietoris \((0,1)\)-slice}
\label{sec:mv-in-text}

For a Mayer--Vietoris square \(S\) (typically: opens \(X_1 = U \cap V\), \(X_2 = U\),
\(X_3 = V\), \(X_4 = U \cup V\) of a topological space) and a sheaf of \(R\)-modules \(F\) on
the site, this section produces the exactness of
\[
  0 \to F(X_4) \to F(X_2) \times F(X_3) \to F(X_1)
    \xrightarrow{\;\delta\;} H'^1(X_4, F) \to H'^1(X_2, F) \times H'^1(X_3, F)
\]
and derives the two-cover cokernel computation: if \(H'^1(X_2, F)\) and \(H'^1(X_3, F)\)
vanish, then \(F(X_1)/\mathrm{range}(\text{difference of restrictions}) \cong H'^1(X_4, F)\),
the quotient map being the connecting homomorphism \(\delta\).

\begin{definition}[Mayer--Vietoris square]
  \label{def:MayerVietorisSquare}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \((\mathcal C, J)\) be a small site. A Mayer--Vietoris square consists of four objects
  \(X_1, X_2, X_3, X_4\) of \(\mathcal C\) and morphisms \(f_{12} : X_1 \to X_2\),
  \(f_{13} : X_1 \to X_3\), \(f_{24} : X_2 \to X_4\), \(f_{34} : X_3 \to X_4\) such that the
  two composites \(X_1 \to X_2 \to X_4\) and \(X_1 \to X_3 \to X_4\) agree, \(f_{13}\) is a
  monomorphism, and, after applying the representable-presheaf-then-sheafification functor
  \(\mathcal C \to \mathrm{Sh}(\mathcal C, J; \mathrm{Set})\), the resulting square of
  sheaves of sets is a pushout square: the image of \(X_4\) is the pushout, over the image of
  \(X_1\), of the images of \(X_2\) and \(X_3\). The prototypical example is
  \(X_1 = U \cap V\), \(X_2 = U\), \(X_3 = V\), \(X_4 = U \cup V\) for two opens \(U, V\) of a
  topological space, with the evident inclusions.
\end{definition}

\begin{definition}[The sheaf condition of a Mayer--Vietoris square]
  \label{def:mv_sheaf_condition}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.SheafCondition,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.sheafCondition_of_sheaf}
  \uses{def:MayerVietorisSquare}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \(S = (X_1,X_2,X_3,X_4,f_{12},f_{13},f_{24},f_{34})\) be a Mayer--Vietoris square on
  \((\mathcal C, J)\) and let \(P\) be a presheaf on \(\mathcal C\). Say \(P\) satisfies the
  sheaf condition for \(S\) when the square \(P(X_4) \to P(X_2) \to P(X_1)\),
  \(P(X_4) \to P(X_3) \to P(X_1)\) (restriction along \(f_{24}, f_{12}\) and along
  \(f_{34}, f_{13}\)) is a pullback square: equivalently, restriction identifies \(P(X_4)\)
  with the pairs \((u,v) \in P(X_2) \times P(X_3)\) of equal restriction to \(X_1\). Every
  sheaf satisfies the sheaf condition for every Mayer--Vietoris square of its site.
\end{definition}

\begin{definition}[The Mayer--Vietoris short complex of free sheaves]
  \label{def:moduleShortComplex}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleShortComplex}
  \uses{def:MayerVietorisSquare, def:freeModuleSheaf, def:freeModuleSheafMap}
  \leanok
  For a Mayer--Vietoris square \(S\) on \((\mathcal C, J)\), the complex of sheaves of
  \(R\)-modules
  \[
    R[X_1] \xrightarrow{\ (R[f_{12}],\, -R[f_{13}])\ } R[X_2] \oplus R[X_3]
      \xrightarrow{\ R[f_{24}] + R[f_{34}]\ } R[X_4],
  \]
  whose composite is zero by the commutativity of \(S\)'s square.
\end{definition}

\begin{theorem}[The Mayer--Vietoris short complex is short exact]
  \label{thm:moduleShortComplex_shortExact}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleShortComplex_shortExact}
  \uses{def:moduleShortComplex}
  \leanok
  For every Mayer--Vietoris square \(S\), the complex of \ref{def:moduleShortComplex} is a
  short exact sequence of sheaves of \(R\)-modules:
  \[
    0 \to R[X_1] \to R[X_2] \oplus R[X_3] \to R[X_4] \to 0 .
  \]
\end{theorem}
\begin{proof}
  \leanok
  \emph{The square of free sheaves is a pushout.} The free-\(R\)-module-sheaf functor
  \(U \mapsto R[U]\) (\ref{def:freeModuleSheafMap} on morphisms) is a left adjoint of the
  forgetful functor to sheaves of sets (it factors the free-\(R\)-module-on-a-set functor,
  itself a left adjoint, through sheafification, also a left adjoint). Left adjoints
  preserve colimits, in particular pushout squares; applying this functor to the defining
  pushout square of \(S\) (Definition~\ref{def:MayerVietorisSquare}: the square of
  sheafified representables at \(X_1,X_2,X_3,X_4\)) shows that the square
  \(R[X_1] \to R[X_2]\), \(R[X_1] \to R[X_3]\), \(R[X_2] \to R[X_4]\),
  \(R[X_3] \to R[X_4]\) is again a pushout, now in the category of sheaves of
  \(R\)-modules.

  \emph{Pushout along a mono is short exact.} In an additive category with biproducts, a
  commuting square with legs \(p : A \to B\), \(q : A \to C\), \(r : B \to D\),
  \(s : C \to D\) is a pushout square exactly when \(D\), together with the map
  \((r,s) : B \oplus C \to D\), is a cokernel of the difference map
  \((p,-q) : A \to B \oplus C\). Applied to the pushout square above, this shows that
  \(R[X_4]\), with the sum map, is a cokernel of the difference map
  \(R[X_1] \to R[X_2] \oplus R[X_3]\); that is, the complex of \ref{def:moduleShortComplex}
  is exact at \(R[X_2] \oplus R[X_3]\) and at \(R[X_4]\), with the map to \(R[X_4]\) an
  epimorphism.

  \emph{The difference map is a monomorphism.} By definition of a Mayer--Vietoris square,
  \(f_{13} : X_1 \to X_3\) is a monomorphism of \(\mathcal C\); postcomposition with a
  monomorphism is injective on morphism sets, so the representable-presheaf map it induces
  is a monomorphism of presheaves of sets, and both the free-\(R\)-module functor (on a set,
  mapping along an injection of index sets is injective on finitely supported functions) and
  sheafification preserve monomorphisms. Hence \(R[f_{13}] : R[X_1] \to R[X_3]\) is a
  monomorphism of sheaves of \(R\)-modules, and so is its negative. The second component of
  the difference map \((R[f_{12}], -R[f_{13}]) : R[X_1] \to R[X_2] \oplus R[X_3]\) (its
  composite with the projection to \(R[X_3]\)) is exactly \(-R[f_{13}]\); since a composite
  \(g \circ h\) being a monomorphism forces \(h\) to be a monomorphism, the difference map
  itself is a monomorphism.

  Together, the three paragraphs give short exactness.
\end{proof}

\begin{definition}[The restriction-difference map]
  \label{def:moduleDiff}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleDiff}
  \uses{def:MayerVietorisSquare}
  \leanok
  For a Mayer--Vietoris square \(S\) and a sheaf \(F\) of \(R\)-modules, the \(R\)-linear map
  \[
    F(X_2) \times F(X_3) \longrightarrow F(X_1), \qquad
    (s_2, s_3) \longmapsto s_2|_{X_1} - s_3|_{X_1},
  \]
  restricting along \(f_{12}\) and \(f_{13}\) respectively and taking the difference.
\end{definition}

\begin{lemma}[Degree-zero exactness]
  \label{lem:mv_exact_degree0}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.sections_ext,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.exists_glue_of_moduleDiff_eq_zero}
  \uses{def:moduleDiff, def:mv_sheaf_condition}
  \leanok
  For a Mayer--Vietoris square \(S\) and a sheaf \(F\) of \(R\)-modules, the sequence
  \[
    0 \to F(X_4) \xrightarrow{\ (\mathrm{res},\,\mathrm{res})\ } F(X_2) \times F(X_3)
      \xrightarrow{\ \mathrm{moduleDiff}\ } F(X_1)
  \]
  is exact: the pair of restrictions to \(X_2, X_3\) is injective, and its image is exactly
  the kernel of \ref{def:moduleDiff}.
\end{lemma}
\begin{proof}
  \leanok
  This is the sheaf condition of \(S\) for (the sheaf of sets underlying) \(F\)
  (Definition~\ref{def:mv_sheaf_condition}): the map \(F(X_4) \to F(X_2) \times F(X_3)\) has
  image exactly the pairs with equal restriction to \(X_1\) (i.e.\
  \(\ker(\mathrm{moduleDiff})\)), and two elements of \(F(X_4)\) with the same pair of
  restrictions are equal.
\end{proof}

\begin{lemma}[Contravariant long exact sequence of \(\Ext\)]
  \label{lem:ext_contravariant_les}
  \lean{CategoryTheory.Abelian.Ext.contravariant_sequence_exact₁,
    CategoryTheory.Abelian.Ext.contravariant_sequence_exact₃,
    CategoryTheory.ShortComplex.ShortExact.extClass,
    CategoryTheory.Abelian.Ext.biprodAddEquiv}
  \mathlibok
  \textit{Provided by Mathlib.}
  Let \(0 \to A \xrightarrow{f} B \xrightarrow{g} C \to 0\) be a short exact sequence in an
  abelian category with \(\Ext\)-groups and let \(Y\) be any object. There is a canonical
  extension class \(\delta \in \Ext^1(C, A)\) (built from the connecting homomorphism of the
  sequence), and for every \(n \ge 0\) the sequence of abelian groups
  \[
    \Ext^n(C,Y) \xrightarrow{g^*} \Ext^n(B,Y) \xrightarrow{f^*} \Ext^n(A,Y)
      \xrightarrow{\ \delta \cdot (-)\ } \Ext^{n+1}(C,Y) \xrightarrow{g^*} \Ext^{n+1}(B,Y)
      \xrightarrow{f^*} \Ext^{n+1}(A,Y)
  \]
  is exact at each of the four inner terms, where \(f^*, g^*\) are precomposition
  (contravariant functoriality of \(\Ext(-,Y)\)) and \(\delta \cdot (-)\) is composition
  (Yoneda product) with \(\delta\). (Convention: \(\Ext^0 = \Hom\).) If \(B = X_2 \oplus X_3\)
  is a direct sum, \(\Ext^n(B,Y) \cong \Ext^n(X_2,Y) \times \Ext^n(X_3,Y)\) naturally,
  compatibly with \(f^*, g^*\).
\end{lemma}

\begin{definition}[The connecting map]
  \label{def:moduleDelta}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleDelta}
  \uses{def:HModule'_linearEquiv0, thm:moduleShortComplex_shortExact,
    lem:ext_contravariant_les}
  \leanok
  For a Mayer--Vietoris square \(S\) and a sheaf \(F\) of \(R\)-modules, the connecting map
  \(F(X_1) \to H'^1(X_4, F)\): the identification
  \(F(X_1) \cong H'^0(X_1,F) = \Ext^0(R[X_1], F)\) of \ref{def:HModule'_linearEquiv0},
  followed by the map \(\delta \cdot (-) : \Ext^0(R[X_1],F) \to \Ext^1(R[X_4],F) = H'^1(X_4,F)\)
  of \ref{lem:ext_contravariant_les} for the short exact sequence of
  \ref{thm:moduleShortComplex_shortExact} (\(A = R[X_1]\), \(B = R[X_2] \oplus R[X_3]\),
  \(C = R[X_4]\)).
\end{definition}

\begin{lemma}[Exactness at \(F(X_1)\)]
  \label{lem:mv_exact_at_X1}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleDelta_moduleDiff,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.exists_of_moduleDelta_eq_zero}
  \uses{def:moduleDelta, def:moduleDiff}
  \leanok
  For a Mayer--Vietoris square \(S\) and a sheaf \(F\) of \(R\)-modules,
  \(\ker(\mathrm{moduleDelta}) = \mathrm{range}(\mathrm{moduleDiff})\) as submodules of
  \(F(X_1)\): the connecting class of a difference of restrictions vanishes, and conversely
  every section of \(F(X_1)\) with vanishing connecting class is such a difference.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:ext_contravariant_les, thm:moduleShortComplex_shortExact,
    lem:freeModuleSheafHomEquiv_naturality}
  This is exactness of the sequence of \ref{lem:ext_contravariant_les} (for \(n=0\), the
  short exact sequence of \ref{thm:moduleShortComplex_shortExact}, \(Y=F\)) at the term
  \(\Ext^0(A,F) = F(X_1)\), transported along the identifications
  \(\Ext^0(B,F) \cong F(X_2) \times F(X_3)\) (\ref{lem:ext_contravariant_les}, direct sum) and
  \(\Ext^0(A,F) \cong F(X_1)\) (\ref{def:HModule'_linearEquiv0}): under these identifications
  \(f^* : \Ext^0(B,F) \to \Ext^0(A,F)\) becomes \(\mathrm{moduleDiff}\) and
  \(\delta \cdot (-) : \Ext^0(A,F) \to \Ext^1(C,F)\) becomes \(\mathrm{moduleDelta}\), by
  naturality of the section equivalence in the site variable
  (\ref{lem:freeModuleSheafHomEquiv_naturality}), which identifies precomposition at the
  level of morphisms out of a free sheaf with restriction at the level of sections.
\end{proof}

\begin{lemma}[Exactness at \(H'^1(X_4,F)\)]
  \label{lem:mv_exact_at_H1X4}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.res_moduleDelta₂,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.res_moduleDelta₃,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.exists_moduleDelta_eq}
  \uses{def:moduleDelta, def:HModule'_res}
  \leanok
  For a Mayer--Vietoris square \(S\) and a sheaf \(F\) of \(R\)-modules,
  \(\ker(\mathrm{res}_{f_{24}}) \cap \ker(\mathrm{res}_{f_{34}}) = \mathrm{range}(\mathrm{moduleDelta})\)
  as submodules of \(H'^1(X_4,F)\), where
  \(\mathrm{res}_{f_{24}}, \mathrm{res}_{f_{34}} : H'^1(X_4,F) \to H'^1(X_2,F), H'^1(X_3,F)\)
  are the restrictions of \ref{def:HModule'_res}: the connecting class of any section of
  \(F(X_1)\) restricts to zero on both \(X_2\) and \(X_3\), and conversely every class
  restricting to zero on both is a connecting class.
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:ext_contravariant_les, thm:moduleShortComplex_shortExact}
  As in \ref{lem:mv_exact_at_X1}, this is exactness of the sequence of
  \ref{lem:ext_contravariant_les} (for \(n=0\), i.e.\ at the term \(\Ext^1(C,F)\) between
  \(\delta \cdot (-)\) and \(g^*\)) transported along the same identifications, together
  with the splitting \(\Ext^1(B,F) \cong H'^1(X_2,F) \times H'^1(X_3,F)\) under which
  \(g^*\) becomes the pair \((\mathrm{res}_{f_{24}}, \mathrm{res}_{f_{34}})\).
\end{proof}

\begin{theorem}[Surjectivity of the connecting map]
  \label{thm:moduleDelta_surjective}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleDelta_surjective}
  \uses{lem:mv_exact_at_H1X4}
  \leanok
  If \(H'^1(X_2,F)\) and \(H'^1(X_3,F)\) are both zero, then
  \(\mathrm{moduleDelta} : F(X_1) \to H'^1(X_4,F)\) is surjective.
\end{theorem}
\begin{proof}
  \leanok
  Immediate from \ref{lem:mv_exact_at_H1X4}:
  \(\ker(\mathrm{res}_{f_{24}}) \cap \ker(\mathrm{res}_{f_{34}}) = H'^1(X_4,F)\) once both
  targets vanish, so \(\mathrm{range}(\mathrm{moduleDelta}) = H'^1(X_4,F)\).
\end{proof}

\begin{definition}[The connecting map on the cokernel]
  \label{def:moduleDeltaQuotient}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.moduleDeltaQuotient}
  \uses{def:moduleDelta, lem:mv_exact_at_X1}
  \leanok
  Since \(\mathrm{range}(\mathrm{moduleDiff}) \subseteq \ker(\mathrm{moduleDelta})\)
  (\ref{lem:mv_exact_at_X1}), \(\mathrm{moduleDelta}\) descends to an \(R\)-linear map
  \[
    F(X_1)/\mathrm{range}(\mathrm{moduleDiff}) \longrightarrow H'^1(X_4,F).
  \]
\end{definition}

\begin{theorem}[The Mayer--Vietoris two-cover cokernel computation]
  \label{thm:h1LinearEquiv}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.h1LinearEquiv}
  \uses{def:moduleDeltaQuotient, lem:mv_exact_at_X1, thm:moduleDelta_surjective}
  \leanok
  \source{stacks-project}
  If \(H'^1(X_2,F)\) and \(H'^1(X_3,F)\) are both zero, the map of
  \ref{def:moduleDeltaQuotient} is an \(R\)-linear isomorphism
  \[
    F(X_1)/\mathrm{range}(\mathrm{moduleDiff}) \;\cong\; H'^1(X_4,F).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Injectivity: if the class of \(s \in F(X_1)\) maps to \(0\), then
  \(\mathrm{moduleDelta}(s) = 0\), so by \ref{lem:mv_exact_at_X1}
  \(s \in \mathrm{range}(\mathrm{moduleDiff})\), i.e.\ the class of \(s\) is already \(0\).
  Surjectivity is \ref{thm:moduleDelta_surjective}.
\end{proof}

\begin{lemma}[Compatibility with the connecting map]
  \label{lem:h1LinearEquiv_mk}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.h1LinearEquiv_mk}
  \uses{thm:h1LinearEquiv}
  \leanok
  Under the isomorphism of \ref{thm:h1LinearEquiv}, the class of \(s \in F(X_1)\)
  corresponds to \(\mathrm{moduleDelta}(s)\).
\end{lemma}
\begin{proof}
  \leanok
  Immediate from the construction of \ref{def:moduleDeltaQuotient} and
  \ref{thm:h1LinearEquiv}.
\end{proof}

\section{The two-affine-cover cokernel bridge}

For a scheme \(X\) over \(\Spec k\) covered by two affine opens \(U_0 \cup U_1 = X\), this
section computes the degree-one cohomology of the structure sheaf as
\[
  H^1\bigl(X, \struct{X/k}\bigr) \;\cong\;
    \Gamma(X, U_0 \cap U_1) \big/
      \mathrm{range}\bigl((s_0,s_1) \mapsto s_0|_{U_0 \cap U_1} - s_1|_{U_0 \cap U_1}\bigr),
\]
the computational access point for the genus of a curve. No hypothesis on the intersection
\(U_0 \cap U_1\) is needed: the derived Mayer--Vietoris sequence of Section~\ref{sec:mv-in-text}
is exact regardless, and affineness of the two pieces alone kills their degree-one
cohomology (\ref{thm:affine_open_h1_vanishing}) --- the classical affine-intersection
hypothesis is needed only for the \v{C}ech-complex identification of \(H^1\), which this
route bypasses.

\begin{definition}[Mayer--Vietoris square of two opens]
  \label{def:opens_mayerVietorisSquare'}
  \lean{Opens.mayerVietorisSquare'}
  \uses{def:MayerVietorisSquare}
  \mathlibok
  \textit{Provided by Mathlib.}
  For a topological space \(T\) and opens \(X_1,X_2,X_3,X_4 \subseteq T\) with
  \(X_1 = X_2 \cap X_3\) and \(X_4 = X_2 \cup X_3\), the square \((X_1,X_2,X_3,X_4)\) with the
  inclusion morphisms is a Mayer--Vietoris square (Definition~\ref{def:MayerVietorisSquare})
  on the small Zariski site of \(T\).
\end{definition}

\begin{definition}[The two-cover square]
  \label{def:twoCoverSquare}
  \lean{AlgebraicGeometry.Scheme.twoCoverSquare}
  \uses{def:opens_mayerVietorisSquare'}
  \leanok
  For a scheme \(X\) and opens \(U_0, U_1 \subseteq X\) with \(U_0 \cup U_1 = X\), the
  Mayer--Vietoris square \((U_0 \cap U_1,\, U_0,\, U_1,\, X)\) on the small Zariski site of
  \(X\) (Definition~\ref{def:opens_mayerVietorisSquare'}, specialized to \(X_4 = X\)), with
  the inclusion morphisms.
\end{definition}

\begin{theorem}[The two-cover \(H^1\) computation, general coefficients]
  \label{thm:twoCoverH1LinearEquiv}
  \lean{AlgebraicGeometry.Scheme.twoCoverH1LinearEquiv}
  \uses{def:twoCoverSquare, def:HModule_linearEquivHModule', thm:h1LinearEquiv}
  \leanok
  \source{stacks-project}
  Let \(k\) be a commutative ring, \(X\) a scheme over \(\Spec k\), \(U_0, U_1 \subseteq X\)
  opens with \(U_0 \cup U_1 = X\), and \(F\) a sheaf of \(k\)-modules on the small Zariski
  site of \(X\) with \(H'^1(U_0,F) = H'^1(U_1,F) = 0\). Then
  \[
    H^1(X,F) \;\cong\;
      F(U_0 \cap U_1) \big/ \mathrm{range}\bigl((s_0,s_1) \mapsto
        s_0|_{U_0 \cap U_1} - s_1|_{U_0 \cap U_1}\bigr) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Compose the isomorphism \(H^1(X,F) \cong H'^1(X,F)\) of
  \ref{def:HModule_linearEquivHModule'} (\(X\) is a terminal object of its own small Zariski
  site) with the inverse of the isomorphism of \ref{thm:h1LinearEquiv} for the two-cover
  square of \ref{def:twoCoverSquare}, whose \(\mathrm{moduleDiff}\) is exactly the displayed
  restriction-difference map.
\end{proof}

\begin{definition}[The two-cover restriction-difference map]
  \label{def:TwoCover_diff}
  \lean{AlgebraicGeometry.TwoCover.diff}
  \uses{def:moduleKSheaf}
  \leanok
  Let \(k\) be a commutative ring, \(X\) a scheme over \(\Spec k\), and \(U_0, U_1 \subseteq X\)
  opens. The \(k\)-linear map
  \[
    \Gamma(X,U_0) \times \Gamma(X,U_1) \longrightarrow \Gamma(X, U_0 \cap U_1), \qquad
    (s_0,s_1) \longmapsto s_0|_{U_0 \cap U_1} - s_1|_{U_0 \cap U_1} .
  \]
  When \(U_0 \cup U_1 = X\), this is the map \ref{def:moduleDiff} of the two-cover square
  (Definition~\ref{def:twoCoverSquare}) for the structure sheaf \(\struct{X/k}\).
\end{definition}

\begin{definition}[The two-cover cokernel carrier]
  \label{def:TwoCover_H1Cok}
  \lean{AlgebraicGeometry.TwoCover.H1Cok}
  \uses{def:TwoCover_diff}
  \leanok
  The \(k\)-module \(\Gamma(X, U_0 \cap U_1)/\mathrm{range}(\mathrm{diff})\), the cokernel of
  the map of \ref{def:TwoCover_diff}.
\end{definition}

\begin{lemma}[Sections extending to one piece vanish in the cokernel]
  \label{lem:TwoCover_h1Cok_mk_res}
  \lean{AlgebraicGeometry.TwoCover.h1Cok_mk_resHom_left,
    AlgebraicGeometry.TwoCover.h1Cok_mk_resHom_right}
  \uses{def:TwoCover_H1Cok}
  \leanok
  For \(t \in \Gamma(X,U_0)\), the class of \(t|_{U_0 \cap U_1}\) in
  \ref{def:TwoCover_H1Cok} is zero; symmetrically, for \(t \in \Gamma(X,U_1)\) the class of
  \(t|_{U_0 \cap U_1}\) is zero.
\end{lemma}
\begin{proof}
  \leanok
  The first is the class of \(\mathrm{diff}(t,0)\), the second of \(\mathrm{diff}(0,-t)\)
  (Definition~\ref{def:TwoCover_diff}), both in the range of \(\mathrm{diff}\).
\end{proof}

\begin{definition}[The two-cover connecting map]
  \label{def:TwoCover_delta}
  \lean{AlgebraicGeometry.TwoCover.delta}
  \uses{def:twoCoverSquare, def:HModule_linearEquivHModule', def:moduleDelta}
  \leanok
  Assume \(U_0 \cup U_1 = X\). The \(k\)-linear map
  \(\Gamma(X, U_0 \cap U_1) \to H^1(X, \struct{X/k})\): the connecting map
  \ref{def:moduleDelta} of the two-cover square (Definition~\ref{def:twoCoverSquare}) for
  \(F = \struct{X/k}\), followed by the inverse of the isomorphism
  \(H^1(X,\struct{X/k}) \cong H'^1(X,\struct{X/k})\) of
  \ref{def:HModule_linearEquivHModule'}.
\end{definition}

\begin{lemma}[The connecting class of a difference vanishes]
  \label{lem:TwoCover_delta_diff}
  \lean{AlgebraicGeometry.TwoCover.delta_diff}
  \uses{def:TwoCover_delta, def:TwoCover_diff, lem:mv_exact_at_X1}
  \leanok
  For \(t \in \Gamma(X,U_0) \times \Gamma(X,U_1)\), \(\mathrm{delta}(\mathrm{diff}(t)) = 0\).
\end{lemma}
\begin{proof}
  \leanok
  \(\mathrm{diff}(t)\) equals the two-cover square's \(\mathrm{moduleDiff}(t)\)
  (Definition~\ref{def:TwoCover_diff}), whose connecting class vanishes by
  \ref{lem:mv_exact_at_X1}; transport along the (linear, hence class-zero-preserving)
  isomorphism of \ref{def:HModule_linearEquivHModule'} used in the definition of
  \(\mathrm{delta}\).
\end{proof}

\begin{lemma}[The connecting class of an extending section vanishes]
  \label{lem:TwoCover_delta_resHom}
  \lean{AlgebraicGeometry.TwoCover.delta_resHom_left,
    AlgebraicGeometry.TwoCover.delta_resHom_right}
  \uses{lem:TwoCover_delta_diff}
  \leanok
  For \(t \in \Gamma(X,U_0)\), \(\mathrm{delta}(t|_{U_0 \cap U_1}) = 0\); symmetrically, for
  \(t \in \Gamma(X,U_1)\), \(\mathrm{delta}(t|_{U_0 \cap U_1}) = 0\).
\end{lemma}
\begin{proof}
  \leanok
  \(t|_{U_0 \cap U_1} = \mathrm{diff}(t,0)\), resp.\ \(-\mathrm{diff}(0,t)\)
  (Definition~\ref{def:TwoCover_diff}), so this is \ref{lem:TwoCover_delta_diff} (using
  \(\mathrm{delta}\)'s linearity in the second case).
\end{proof}

\begin{theorem}[Surjectivity of the two-cover connecting map]
  \label{thm:TwoCover_delta_surjective}
  \lean{AlgebraicGeometry.TwoCover.delta_surjective}
  \uses{def:TwoCover_delta, thm:affine_open_h1_vanishing, thm:moduleDelta_surjective}
  \leanok
  If \(U_0\) and \(U_1\) are affine opens of \(X\) (still with \(U_0 \cup U_1 = X\)), then
  \(\mathrm{delta} : \Gamma(X, U_0 \cap U_1) \to H^1(X,\struct{X/k})\) is surjective.
\end{theorem}
\begin{proof}
  \leanok
  By \ref{thm:affine_open_h1_vanishing}, \(H'^1(U_0,\struct{X/k}) = H'^1(U_1,\struct{X/k}) = 0\);
  by \ref{thm:moduleDelta_surjective} applied to the two-cover square, its connecting map
  \(\mathrm{moduleDelta}\) is surjective onto \(H'^1(X,\struct{X/k})\), and transporting
  along the isomorphism of \ref{def:HModule_linearEquivHModule'} used to define
  \(\mathrm{delta}\) preserves surjectivity.
\end{proof}

\begin{theorem}[The two-affine-cover \(H^1\) cokernel bridge]
  \label{thm:TwoCover_h1CokEquiv}
  \lean{AlgebraicGeometry.TwoCover.h1CokEquiv}
  \uses{thm:affine_open_h1_vanishing, thm:h1LinearEquiv, def:HModule_linearEquivHModule',
    def:TwoCover_H1Cok}
  \leanok
  \source{stacks-project}
  Let \(k\) be a commutative ring, \(X\) a scheme over \(\Spec k\), and \(U_0, U_1\) affine
  opens of \(X\) with \(U_0 \cup U_1 = X\). There is a \(k\)-linear isomorphism
  \[
    H^1\bigl(X, \struct{X/k}\bigr) \;\cong\; \Gamma(X, U_0 \cap U_1)\big/\mathrm{range}(\mathrm{diff}),
  \]
  where \(\mathrm{diff}(s_0,s_1) = s_0|_{U_0 \cap U_1} - s_1|_{U_0 \cap U_1}\)
  (\ref{def:TwoCover_diff}). No hypothesis on \(U_0 \cap U_1\) (affineness, separatedness, or
  even quasi-compactness) is needed: the derived Mayer--Vietoris sequence of
  \ref{thm:moduleShortComplex_shortExact} is exact regardless, and affineness of \(U_0, U_1\)
  alone kills their degree-one cohomology (\ref{thm:affine_open_h1_vanishing}); the classical
  hypothesis on the intersection is needed only for the \v{C}ech-complex identification of
  \(H^1\), which this route bypasses.
\end{theorem}
\begin{proof}
  \leanok
  By \ref{thm:affine_open_h1_vanishing}, \(H'^1(U_0,\struct{X/k}) = H'^1(U_1,\struct{X/k}) = 0\).
  Apply \ref{thm:h1LinearEquiv} to the two-cover square of \ref{def:twoCoverSquare} with
  \(F = \struct{X/k}\), giving
  \(\Gamma(X, U_0 \cap U_1)/\mathrm{range}(\mathrm{diff}) \cong H'^1(X,\struct{X/k})\), and
  compose with the inverse of the isomorphism
  \(H^1(X,\struct{X/k}) \cong H'^1(X,\struct{X/k})\) of
  \ref{def:HModule_linearEquivHModule'}.
\end{proof}

\begin{lemma}[Compatibility with the connecting map]
  \label{lem:TwoCover_h1CokEquiv_delta}
  \lean{AlgebraicGeometry.TwoCover.h1CokEquiv_delta}
  \uses{thm:TwoCover_h1CokEquiv, def:TwoCover_delta, lem:h1LinearEquiv_mk}
  \leanok
  Under the isomorphism of \ref{thm:TwoCover_h1CokEquiv}, the class
  \(\mathrm{delta}(s)\) (Definition~\ref{def:TwoCover_delta}) corresponds, for every
  \(s \in \Gamma(X, U_0 \cap U_1)\), to the class of \(s\) in
  \(\Gamma(X,U_0 \cap U_1)/\mathrm{range}(\mathrm{diff})\).
\end{lemma}
\begin{proof}
  \leanok
  Unwind the definitions of \ref{thm:TwoCover_h1CokEquiv} and \ref{def:TwoCover_delta} (both
  built from the same two ingredients, \ref{thm:h1LinearEquiv} and
  \ref{def:HModule_linearEquivHModule'}) and apply the compatibility \ref{lem:h1LinearEquiv_mk}
  of the Mayer--Vietoris cokernel isomorphism with its connecting map.
\end{proof}

\begin{lemma}[Compatibility with the connecting map, inverse form]
  \label{lem:TwoCover_h1CokEquiv_symm_mk}
  \lean{AlgebraicGeometry.TwoCover.h1CokEquiv_symm_mk}
  \uses{lem:TwoCover_h1CokEquiv_delta}
  \leanok
  The inverse of the isomorphism of \ref{thm:TwoCover_h1CokEquiv} sends the class of
  \(s \in \Gamma(X, U_0 \cap U_1)\) to \(\mathrm{delta}(s)\).
\end{lemma}
\begin{proof}
  \leanok
  Apply the isomorphism of \ref{thm:TwoCover_h1CokEquiv} to both sides of
  \ref{lem:TwoCover_h1CokEquiv_delta} and use injectivity.
\end{proof}

\section{Base change of the two-cover cohomology over an affine test ring}

Fix a field \(k\) and an object \(C\) of \(\Over(\Spec k)\). For a commutative \(k\)-algebra \(R\)
--- the \emph{affine test ring} --- base change produces the relative curve
\(C_R = C \otimes \Spec R\) over \(\Spec R\); an affine two-chart cover of \(C\)
(Section~\ref{sec:mv-in-text} and Chapter~\ref{chap:Curves}) pulls back to one of \(C_R\), and the
two-affine-cover bridge of the previous section then computes \(H^1(C_R, \struct{C_R/R})\) as an
explicit two-cover cokernel of \(R\)-modules. When \(C\) is a smooth curve, the degree-zero
cohomology of the relative curve is the test ring itself, \(H^0(C_R, \struct{C_R/R}) = R\).

\begin{definition}[The relative curve over the test ring]
  \label{def:relCurve}
  \lean{AlgebraicGeometry.relCurve, AlgebraicGeometry.relCurve.instOver}
  \leanok
  For \(C \in \Over(\Spec k)\) and a commutative \(k\)-algebra \(R\), the \emph{relative curve}
  \(C_R\) is the underlying scheme of the fibre product \(C \otimes \Spec R\) of \(C\) with the
  object \(\Spec R\) of \(\Over(\Spec k)\), regarded as a scheme over \(\Spec R\) via the second
  projection \(\mathrm{pr}_2 : C \otimes \Spec R \to \Spec R\).
\end{definition}

\begin{definition}[The base-changed affine two-cover]
  \label{def:relCover}
  \lean{AlgebraicGeometry.relCover}
  \uses{def:relCurve, def:AffineTwoCover, thm:AffineTwoCover_pullbackProd}
  \leanok
  Let \(D = (V_0, V_1)\) be an affine two-chart cover (\ref{def:AffineTwoCover}) of the underlying
  scheme of \(C\). The \emph{base-changed cover} of the relative curve \(C_R\) is the pair of
  preimages \(\bigl(\mathrm{pr}_1^{-1} V_0,\ \mathrm{pr}_1^{-1} V_1\bigr)\) of the charts of \(D\)
  under the first projection \(\mathrm{pr}_1 : C_R \to C\); by
  \ref{thm:AffineTwoCover_pullbackProd} it is again an affine two-chart cover, now of \(C_R\).
\end{definition}

\begin{lemma}[The base-changed charts are affine and cover the relative curve]
  \label{lem:relCover_charts}
  \lean{AlgebraicGeometry.relCover_isAffineOpen₀, AlgebraicGeometry.relCover_isAffineOpen₁,
    AlgebraicGeometry.relCover_sup}
  \uses{def:relCover}
  \leanok
  The two charts \(\mathrm{pr}_1^{-1} V_0\) and \(\mathrm{pr}_1^{-1} V_1\) of the base-changed cover
  are affine open, and their union is all of \(C_R\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{thm:AffineTwoCover_pullbackProd}
  These are the affineness of the two charts and the covering property recorded in the
  affine-two-chart-cover structure \(\mathrm{pr}_1^{-1} D\) of \ref{thm:AffineTwoCover_pullbackProd}.
\end{proof}

\begin{lemma}[The overlap of the base-changed charts]
  \label{lem:relCover_inf}
  \lean{AlgebraicGeometry.relCover_inf}
  \uses{def:relCover}
  \leanok
  The overlap of the two base-changed charts is the preimage of the overlap of \(D\):
  \[
    \mathrm{pr}_1^{-1} V_0 \cap \mathrm{pr}_1^{-1} V_1 = \mathrm{pr}_1^{-1}(V_0 \cap V_1).
  \]
\end{lemma}
\begin{proof}
  \leanok
  Taking preimages under \(\mathrm{pr}_1\) commutes with intersection of opens.
\end{proof}

\begin{definition}[The relative two-cover cohomology carrier]
  \label{def:relTwoCoverH1}
  \lean{AlgebraicGeometry.relTwoCoverH1}
  \uses{def:relCurve, def:relCover, def:moduleKSheaf, def:TwoCover_diff, def:TwoCover_H1Cok}
  \leanok
  For the structure sheaf of the relative curve \(C_R\) viewed as a sheaf of \(R\)-modules, its
  degree-one cohomology over \(R\) is the two-cover cokernel of the base-changed cover: an
  \(R\)-linear isomorphism
  \[
    H^1\bigl(C_R, \struct{C_R/R}\bigr) \;\cong\;
      \Gamma\bigl(C_R,\ \mathrm{pr}_1^{-1}V_0 \cap \mathrm{pr}_1^{-1}V_1\bigr)\big/
        \mathrm{range}(\mathrm{diff}),
  \]
  where \(\mathrm{diff}(s_0,s_1) = s_0|_\cap - s_1|_\cap\) (\ref{def:TwoCover_diff}).
\end{definition}
\begin{proof}
  \leanok
  \uses{thm:TwoCover_h1CokEquiv, lem:relCover_charts}
  The base-changed charts are affine and cover \(C_R\) (\ref{lem:relCover_charts}), so this is the
  two-affine-cover \(H^1\) cokernel bridge \ref{thm:TwoCover_h1CokEquiv} applied over the base ring
  \(R\) to the scheme \(C_R\) with its base-changed cover; the affine-vanishing inputs required by
  that bridge are exactly the affineness of the two charts.
\end{proof}

\begin{theorem}[Degree-zero cohomology of the relative curve is the test ring]
  \label{thm:relStructureSectionsTop}
  \lean{AlgebraicGeometry.relStructureSectionsTop}
  \uses{def:relCurve, thm:isIso_appLE_snd}
  \leanok
  Let \(C\) be a smooth curve over \(k\) (proper, smooth of relative dimension one, geometrically
  irreducible), so that \(C\) is in particular geometrically reduced. For every commutative
  \(k\)-algebra \(R\), the degree-zero cohomology of the structure sheaf of the relative curve is
  the test ring itself:
  \[
    H^0\bigl(C_R, \struct{C_R/R}\bigr) \;=\; \Gamma(C_R, \top) \;\cong\; R,
  \]
  the isomorphism being pullback of global sections along the second projection
  \(\mathrm{pr}_2 : C_R \to \Spec R\). This is the degree-zero case of ``cohomology commutes with
  base change'', universal in the test ring \(R\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{def:moduleKSheafHZero}
  Degree-zero cohomology is global sections, \(H^0(C_R, \struct{C_R/R}) \cong \Gamma(C_R, \top)\)
  (\ref{def:moduleKSheafHZero}, over the base ring \(R\)). Specialize the base-change isomorphism
  \ref{thm:isIso_appLE_snd} to the test object \(T = \Spec R\) and its affine open \(V = \top\):
  pullback along the second projection is an isomorphism
  \(\Gamma(\Spec R, \top) \xrightarrow{\sim} \Gamma(C_R, \mathrm{pr}_2^{-1}\top) = \Gamma(C_R, \top)\)
  (the hypotheses of \ref{thm:isIso_appLE_snd} --- \(C\) proper, geometrically irreducible and
  geometrically reduced --- hold for a smooth curve). Composing with the identification
  \(\Gamma(\Spec R, \top) \cong R\) gives \(\Gamma(C_R, \top) \cong R\).
\end{proof}

\section{The projective line: inputs for the finiteness argument}

This section collects the facts about \(\PP^1\) and about morphisms over \(\Spec k\) that
the finiteness argument of the next section consumes. It builds on the description of
\(\PP^1\), its standard charts \(U_0, U_1\), the chart coordinates
\(t_{ij} = X_j/X_i \in A_{(X_i)}\), and the section-ring identifications
\(\gamma_0, \gamma_1, \gamma_{01}\) developed in Chapter~\ref{chap:Curves}
(Definitions~\ref{def:P1_chartOpen}, \ref{def:P1_chartCoord},
\ref{def:P1_chartSectionsEquiv0}--\ref{def:P1_overlapSectionsEquiv}); the statements here
are recorded in this chapter because they are private inputs of the finiteness glue rather
than general theory of the projective line. Throughout, for a homogeneous \(f\) of positive
degree we write \(A_{(f)} \to \Gamma(\PP^1, D_+(f))\) for the canonical map from the
degree-zero localization to the sections over the basic open (an isomorphism).

\begin{lemma}[Morphisms over the base intertwine the structure algebra maps]
  \label{lem:appTop_map_appLE}
  \lean{AlgebraicGeometry.Scheme.Hom.appTop_map_appLE}
  \leanok
  Let \(k\) be a commutative ring, let \(X, Y\) be schemes over \(\Spec k\) and let
  \(\pi : X \to Y\) be a morphism compatible with the structure morphisms. For opens
  \(U \subseteq Y\) and \(V \subseteq X\) with \(V \subseteq \pi^{-1}(U)\), the two
  composite ring homomorphisms
  \[
    \Gamma(\Spec k, \top) \to \Gamma(Y, \top) \to \Gamma(Y, U)
      \xrightarrow{\ \pi^\sharp\ } \Gamma(X, V)
    \qquad\text{and}\qquad
    \Gamma(\Spec k, \top) \to \Gamma(X, \top) \to \Gamma(X, V)
  \]
  agree, where the unlabeled maps are induced by the structure morphisms and by
  restriction.
\end{lemma}
\begin{proof}
  \leanok
  Pulling back sections along \(\pi\) commutes with restriction, so the first composite is
  the map on sections induced by \(\pi\) composed with the structure morphism of \(Y\),
  restricted to \(V\); by compatibility this composite of morphisms is the structure
  morphism of \(X\).
\end{proof}

\begin{lemma}[Pulling back the structure algebra map]
  \label{lem:appLE_overAlgebraMap}
  \lean{AlgebraicGeometry.Scheme.Hom.appLE_overAlgebraMap}
  \uses{def:overAlgebraMap, lem:appTop_map_appLE}
  \leanok
  In the situation of \ref{lem:appTop_map_appLE}, for every \(r \in k\) the map
  \(\pi^\sharp : \Gamma(Y, U) \to \Gamma(X, V)\) sends the image of \(r\) under the
  structure algebra map of \(Y\) (Definition~\ref{def:overAlgebraMap}) to the image of
  \(r\) under the structure algebra map of \(X\).
\end{lemma}
\begin{proof}
  \leanok
  Evaluate the equality of ring homomorphisms of \ref{lem:appTop_map_appLE} at the section
  corresponding to \(r\).
\end{proof}

\begin{lemma}[The basic-open models lie over the base]
  \label{lem:P1_awayi_structureMap}
  \lean{AlgebraicGeometry.P1.awayι_structureMap}
  \uses{def:P1_structureMap}
  \leanok
  Let \(f \in k[X_0, X_1]\) be homogeneous of positive degree. The composite of the affine
  model \(\Spec A_{(f)} \to \PP^1\) of the basic open \(D_+(f)\) with the structure
  morphism \(\PP^1 \to \Spec k\) is the morphism induced by the algebra map
  \(k \to A_{(f)}\). (This generalizes \ref{lem:P1_chartIota_structureMap} from the two
  standard charts to all standard basic opens.)
\end{lemma}
\begin{proof}
  \leanok
  \uses{def:P1_gradeZero}
  As for \ref{lem:P1_chartIota_structureMap}: the canonical morphism
  \(\Proj A \to \Spec A_0\), restricted to the affine model of a basic open, is induced by
  the ring homomorphism \(A_0 \to A_{(f)}\), and composing with the isomorphism
  \(k \cong A_0\) of \ref{def:P1_gradeZero} gives the claim.
\end{proof}

\begin{lemma}[The basic-open inclusion factors through its affine model]
  \label{lem:P1_basicOpen_iota_eq}
  \lean{AlgebraicGeometry.P1.basicOpen_ι_eq}
  \uses{def:P1}
  \leanok
  Let \(f \in k[X_0, X_1]\) be homogeneous of positive degree. The inclusion
  \(D_+(f) \to \PP^1\) is the composite of the canonical identification
  \(D_+(f) \cong \Spec A_{(f)}\) with the affine model \(\Spec A_{(f)} \to \PP^1\).
\end{lemma}
\begin{proof}
  \leanok
  The affine model is by construction an open immersion with image \(D_+(f)\), and the
  canonical identification is the induced isomorphism onto the image; composing the two
  recovers the inclusion.
\end{proof}

\begin{lemma}[The structure algebra map on a basic open]
  \label{lem:P1_structureMap_appTop_awayToSection}
  \lean{AlgebraicGeometry.P1.structureMap_appTop_awayToSection}
  \uses{def:P1_structureMap, lem:P1_awayi_structureMap, lem:P1_basicOpen_iota_eq}
  \leanok
  Let \(f \in k[X_0, X_1]\) be homogeneous of positive degree. The composite
  \[
    \Gamma(\Spec k, \top) \to \Gamma(\PP^1, \top) \to \Gamma\bigl(\PP^1, D_+(f)\bigr)
  \]
  (structure morphism on global sections, then restriction) is the composite of the
  identification \(\Gamma(\Spec k, \top) \cong k\), the algebra map \(k \to A_{(f)}\), and
  the canonical map \(A_{(f)} \to \Gamma(\PP^1, D_+(f))\).
\end{lemma}
\begin{proof}
  \leanok
  By \ref{lem:P1_basicOpen_iota_eq} and \ref{lem:P1_awayi_structureMap}, the composite of
  the inclusion \(D_+(f) \to \PP^1\) with the structure morphism is the identification
  \(D_+(f) \cong \Spec A_{(f)}\) followed by the morphism induced by \(k \to A_{(f)}\).
  Taking global sections of this equality of scheme morphisms, and identifying the global
  sections of the open subscheme \(D_+(f)\) with \(\Gamma(\PP^1, D_+(f))\) --- under which
  the map on sections induced by the identification with \(\Spec A_{(f)}\) becomes the
  canonical map \(A_{(f)} \to \Gamma(\PP^1, D_+(f))\) --- yields the claim.
\end{proof}

\begin{lemma}[The distinguished fraction of a chart pair is the chart coordinate]
  \label{lem:P1_isLocalizationElem_X_eq}
  \lean{AlgebraicGeometry.P1.isLocalizationElem_X_eq}
  \uses{def:P1_chartCoord}
  \leanok
  For \(i, j \in \{0,1\}\), the canonical degree-zero fraction
  \(X_j^{\deg X_i} / X_i^{\deg X_j}\) attached to the pair \((X_i, X_j)\) of homogeneous
  elements equals the chart coordinate \(t_{ij} = X_j / X_i \in A_{(X_i)}\).
\end{lemma}
\begin{proof}
  \leanok
  Both degrees are one, and a first power is the element itself.
\end{proof}

\begin{theorem}[The chart coordinate cuts out the overlap]
  \label{thm:P1_basicOpen_chartCoord}
  \lean{AlgebraicGeometry.P1.basicOpen_awayToSection_chartCoord}
  \uses{def:P1_chartOpen, def:P1_chartCoord, lem:P1_basicOpen_iota_eq,
    lem:P1_isLocalizationElem_X_eq}
  \leanok
  For \(i, j \in \{0,1\}\), regard the chart coordinate \(t_{ij} \in A_{(X_i)}\) as a
  section of the structure sheaf over the chart \(U_i = D_+(X_i)\), via the canonical map
  \(A_{(X_i)} \to \Gamma(\PP^1, U_i)\). Then the basic open of this section in the scheme
  \(\PP^1\) --- the locus of \(U_i\) where it is invertible --- is the chart overlap:
  \[
    D(t_{ij}) \;=\; U_i \cap U_j .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both sides are open subsets of \(U_i\) (the basic open of a section over \(U_i\) is
  contained in \(U_i\)), so it suffices to show that they have the same preimage under the
  identification \(U_i \cong \Spec A_{(X_i)}\), and to transport the equality forward
  along this open immersion. No stalks are involved: everything is transported through
  the affine model.

  On the one hand, the preimage of the basic open \(D(t_{ij})\) is the basic open of
  \(\Spec A_{(X_i)}\) at the ring element \(t_{ij}\): under the identification of an
  affine open with the spectrum of its section ring, scheme-level basic opens of sections
  correspond to spectrum-level basic opens of ring elements.

  On the other hand, the preimage of \(U_j = D_+(X_j)\) under the affine model
  \(\Spec A_{(X_i)} \to \PP^1\) (through which the inclusion of \(U_i\) factors,
  \ref{lem:P1_basicOpen_iota_eq}) is the basic open at the canonical degree-zero fraction
  attached to the pair \((X_i, X_j)\): a homogeneous prime avoiding \(X_i\) avoids
  \(X_j\) exactly when the degree-zero fraction \(X_j/X_i\) is invertible in the
  corresponding localization. By \ref{lem:P1_isLocalizationElem_X_eq} this fraction is
  \(t_{ij}\), so the preimage of \(U_i \cap U_j\) is again the basic open at
  \(t_{ij}\).
\end{proof}

\begin{lemma}[The Laurent generators as restrictions from the charts]
  \label{lem:P1_laurent_generators}
  \lean{AlgebraicGeometry.P1.overlapSectionsEquiv_symm_T,
    AlgebraicGeometry.P1.overlapSectionsEquiv_symm_T_neg,
    AlgebraicGeometry.P1.overlapSectionsEquiv_symm_algebraMap}
  \uses{def:P1_overlapSectionsEquiv, def:P1_chartCoord}
  \leanok
  Under the identification
  \(\gamma_{01} : \Gamma(\PP^1, U_0 \cap U_1) \cong k[T, T^{-1}]\) of
  \ref{def:P1_overlapSectionsEquiv}:
  \begin{enumerate}
    \item \(T\) corresponds to the restriction to the overlap of the chart coordinate
      \(t_{01}\), regarded as a section over \(U_0\);
    \item \(T^{-1}\) corresponds to the restriction to the overlap of the chart
      coordinate \(t_{10}\), regarded as a section over \(U_1\);
    \item each scalar \(r \in k\) corresponds to the section over the overlap given by
      the image of \(r\) under the algebra map \(k \to A_{(X_0X_1)}\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:P1_res_left, lem:P1_res_right}
  (1) and (2): by \ref{lem:P1_res_left} (resp.\ \ref{lem:P1_res_right}), restriction from
  the chart \(U_0\) (resp.\ \(U_1\)) to the overlap corresponds, under the
  identifications \(\gamma_0, \gamma_1, \gamma_{01}\), to \(t \mapsto T\) (resp.\
  \(t \mapsto T^{-1}\)); apply this to the sections corresponding to the polynomial
  \(t\), which are the chart coordinates. (3): \(\gamma_{01}\) is built from the
  \(k\)-algebra isomorphism \(\theta\) of \ref{def:P1_overlapAlgEquiv}, hence matches the
  two algebra maps from \(k\).
\end{proof}

\section{Finiteness of the first cohomology}

Combining the two-affine-cover cokernel bridge with the two-lattice ladder of
Chapter~\ref{chap:Algebra} along a finite morphism to the projective line yields the
finiteness of \(H^1\). Classically this computation goes back to the explicit \v{C}ech
computation of the cohomology of projective space --- for \(\PP^1\) itself, the
description of \(H^1\) as the cokernel of the two-chart restriction-difference map into
the Laurent ring, spanned by the finitely many ``negative'' monomials --- extended to a
curve by pushing forward along a finite morphism; the two-lattice ladder is exactly the
abstraction of that monomial bookkeeping.

\begin{theorem}[Finiteness of \(H^1\) along a finite morphism to the projective line]
  \label{thm:moduleFinite_hModule_one_of_isFinite_toP1}
  \lean{AlgebraicGeometry.moduleFinite_hModule_one_of_isFinite_toP1}
  \uses{def:HModule, def:moduleKSheaf, def:P1_structureMap}
  \leanok
  \source{hartshorne-algebraic-geometry:page-0242, hartshorne-algebraic-geometry:page-0243}
  Let \(k\) be a field, \(X\) a scheme over \(\Spec k\), and \(\pi : X \to \PP^1\) a
  finite morphism over \(k\) (its composite with the structure morphism of \(\PP^1\) is
  the structure morphism of \(X\)). Then \(H^1\bigl(X, \struct{X/k}\bigr)\) is a finite
  \(k\)-module.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:preimage_chart_affine, lem:preimage_chart_sup, lem:finite_app_overlap,
    lem:P1_chartOpen_inf, thm:TwoCover_h1CokEquiv, def:TwoCover_diff, def:TwoCover_H1Cok,
    def:P1_overlapSectionsEquiv, def:P1_chartCoord, lem:P1_laurent_generators,
    lem:appLE_overAlgebraMap, lem:P1_structureMap_appTop_awayToSection,
    thm:P1_basicOpen_chartCoord, cor:two_lattice_loc_pow}
  Write \(U_0, U_1\) for the standard charts of \(\PP^1\) and set
  \(V_i = \pi^{-1}(U_i)\).

  (a) \emph{The cover and the cokernel.} Since \(\pi\) is finite, hence affine, the
  \(V_i\) are affine opens of \(X\) (\ref{lem:preimage_chart_affine}), and they cover
  \(X\) (\ref{lem:preimage_chart_sup}). By the two-affine-cover bridge
  \ref{thm:TwoCover_h1CokEquiv},
  \[
    H^1\bigl(X, \struct{X/k}\bigr) \;\cong\;
      N \big/ \mathrm{range}(\mathrm{diff}),
    \qquad N := \Gamma(X, V_0 \cap V_1),
  \]
  with \(\mathrm{diff}(s_0, s_1) = s_0|_{V_0 \cap V_1} - s_1|_{V_0 \cap V_1}\)
  (\ref{def:TwoCover_diff}). It therefore suffices to prove that this quotient is a
  finite \(k\)-module.

  (b) \emph{The Laurent module structure.} Preimages commute with intersections, and
  \(U_0 \cap U_1 = D_+(X_0X_1)\) (\ref{lem:P1_chartOpen_inf}), so
  \(V_0 \cap V_1 = \pi^{-1}(U_0 \cap U_1)\). Make \(N\) an algebra over the Laurent
  polynomial ring via the composite
  \[
    k[T, T^{-1}] \xrightarrow{\ \gamma_{01}^{-1}\ } \Gamma(\PP^1, U_0 \cap U_1)
      \xrightarrow{\ \pi^\sharp\ } \Gamma\bigl(X, \pi^{-1}(U_0 \cap U_1)\bigr) = N
  \]
  (\ref{def:P1_overlapSectionsEquiv}). This structure is compatible with the \(k\)-module
  structure of \(N\): a scalar \(r \in k[T,T^{-1}]\) corresponds under \(\gamma_{01}\) to
  the image of \(r\) under the algebra map into the overlap ring
  (\ref{lem:P1_laurent_generators}(3)), which is the structure algebra map of \(\PP^1\)
  on \(U_0 \cap U_1\) (\ref{lem:P1_structureMap_appTop_awayToSection}), and \(\pi\) pulls
  the structure algebra map of \(\PP^1\) back to that of \(X\)
  (\ref{lem:appLE_overAlgebraMap}). Hence the \(k\)-module structure of \(N\) is the
  restriction of scalars of the \(k[T,T^{-1}]\)-structure along the canonical map
  \(k \to k[T,T^{-1}]\).

  (c) \emph{Module-finiteness over the Laurent ring.} Since \(\pi\) is finite and
  \(U_0 \cap U_1\) is an affine open of \(\PP^1\), the map
  \(\pi^\sharp : \Gamma(\PP^1, U_0 \cap U_1) \to N\) is module-finite
  (\ref{lem:finite_app_overlap}); composing with the isomorphism \(\gamma_{01}^{-1}\),
  \(N\) is a finite \(k[T,T^{-1}]\)-module.

  (d) \emph{The two lattices, and the range of the difference map.} Let
  \(Q_0, Q_1 \subseteq N\) be the images of the (\(k\)-linear) restriction maps
  \(\Gamma(X, V_0) \to N\) and \(\Gamma(X, V_1) \to N\). Then
  \(\mathrm{range}(\mathrm{diff}) = Q_0 + Q_1\): every value
  \(s_0| - s_1|\) of \(\mathrm{diff}\) is the sum of \(s_0| \in Q_0\) and
  \(-(s_1|) = (-s_1)| \in Q_1\); conversely \(s_0| = \mathrm{diff}(s_0, 0) \) and
  \(s_1| = \mathrm{diff}(0, -s_1)\) exhibit every element of \(Q_0\) and of \(Q_1\) as a
  value of \(\mathrm{diff}\) --- the sign is absorbed because \(Q_1\) is the image of a
  linear map.

  (e) \emph{Lattice stability.} Let
  \(\tau_0 = \pi^\sharp(t_{01}) \in \Gamma(X, V_0)\) and
  \(\tau_1 = \pi^\sharp(t_{10}) \in \Gamma(X, V_1)\) be the pullbacks of the chart
  coordinates, regarded as sections over the charts
  (Definition~\ref{def:P1_chartCoord}). By \ref{lem:P1_laurent_generators}(1) and the
  compatibility of \(\pi^\sharp\) with restriction, \(T\) acts on \(N\) as
  multiplication by \(\tau_0|_{V_0 \cap V_1}\); symmetrically \(T^{-1}\) acts as
  multiplication by \(\tau_1|_{V_0 \cap V_1}\) (\ref{lem:P1_laurent_generators}(2)).
  Hence \(Q_0\) is stable under multiplication by \(T\): for \(s \in \Gamma(X, V_0)\),
  \[
    T \cdot s|_{V_0 \cap V_1} \;=\; \tau_0|\cdot s| \;=\; (\tau_0 s)|_{V_0 \cap V_1}
      \;\in\; Q_0,
  \]
  and symmetrically \(Q_1\) is stable under multiplication by \(T^{-1}\).

  (f) \emph{Absorption up to powers.} The overlap is a basic open inside each chart
  preimage: pulling back the identity \(D(t_{ij}) = U_i \cap U_j\) of
  \ref{thm:P1_basicOpen_chartCoord} along \(\pi\) (basic opens of sections pull back to
  basic opens of the pulled-back sections) gives
  \[
    V_0 \cap V_1 = D(\tau_0) \subseteq V_0,
    \qquad
    V_0 \cap V_1 = D(\tau_1) \subseteq V_1 .
  \]
  Since \(V_0\) is affine and \(V_0 \cap V_1\) is its basic open defined by \(\tau_0\),
  restriction identifies \(N\) with the localization of \(\Gamma(X, V_0)\) at the powers
  of \(\tau_0\) (quasi-coherence of the structure sheaf). Hence for every \(n \in N\)
  there are \(m \ge 0\) and \(a \in \Gamma(X, V_0)\) with
  \(n \cdot (\tau_0|)^m = a|\), i.e.\ \(T^m \cdot n \in Q_0\). Symmetrically, every
  \(n \in N\) satisfies \(T^{-m} \cdot n \in Q_1\) for some \(m \ge 0\).

  (g) \emph{The ladder.} By (b), (c), (e) and (f), the module \(N\) over
  \(k[T,T^{-1}]\) with the \(k\)-submodules \(Q_0, Q_1\) satisfies all hypotheses of the
  two-lattice finiteness theorem in its localization form via powers of the generator
  (\ref{cor:two_lattice_loc_pow}); hence \(N/(Q_0 + Q_1)\) is a finite \(k\)-module. By
  (d) this quotient is \(N/\mathrm{range}(\mathrm{diff})\), and by (a) it is
  \(H^1\bigl(X, \struct{X/k}\bigr)\).
\end{proof}

\begin{theorem}[Finiteness of \(H^1\) of the curve]
  \label{thm:moduleFinite_hModule_one}
  \lean{AlgebraicGeometry.moduleFinite_hModule_one}
  \uses{def:HModule, def:moduleKSheaf}
  \leanok
  Let \(k\) be a field and \(C\) a smooth curve over \(k\) (proper, smooth of relative
  dimension one, geometrically irreducible). Then
  \(H^1\bigl(C, \struct{C/k}\bigr)\) is a finite \(k\)-module; equivalently, it is a
  finite-dimensional \(k\)-vector space.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:exists_finite_toP1, thm:moduleFinite_hModule_one_of_isFinite_toP1}
  By \ref{thm:exists_finite_toP1} there is a finite morphism \(\pi : C \to \PP^1\) over
  \(k\); apply \ref{thm:moduleFinite_hModule_one_of_isFinite_toP1}.
\end{proof}

\begin{remark}[The genus is the dimension of a finite-dimensional space]
  \label{rem:genus_finite}
  \uses{def:genus, thm:moduleFinite_hModule_one}
  \leanok
  For a smooth curve \(C\) over \(k\), the genus of Definition~\ref{def:genus} is the
  \(k\)-dimension of \(H^1(C, \struct C)\), which by
  \ref{thm:moduleFinite_hModule_one} is a finite-dimensional \(k\)-vector space; the
  genus is therefore a well-defined natural number, attained as the cardinality of any
  basis.
\end{remark}

\section{The cocycle-glued twisted sheaf on a two-cover}
\label{sec:twisted_sheaf}

Let \(k\) be a commutative ring and \(X\) a scheme over \(\Spec k\), its structure sheaf
viewed as a sheaf of \(k\)-modules (\ref{def:moduleKSheaf}). Fix two opens
\(V_0, V_1 \subseteq X\) and a \emph{unit cocycle}: an invertible section
\(g \in \Gamma(X, V_0 \cap V_1)^{\times}\). (On a two-chart cover a \v{C}ech
\(1\)-cocycle has a single component and the cocycle condition on triple overlaps is
vacuous.) This section glues from \(g\) a sheaf \(F_g\) of \(k\)-modules --- for
\(V_0 \cup V_1 = X\), the line bundle with transition function \(g\), trivialised on each
chart --- and computes its degree-one cohomology as a two-cover cokernel, by transporting
the quasi-coherence packaging of Section~\ref{sec:qcoh_vanishing} through the chart
trivialisations.

\begin{definition}[Transport of the packaging along a sections-level trivialisation]
  \label{def:qcohOn_transport}
  \lean{AlgebraicGeometry.Scheme.QcohOn.ofSectionsEquiv}
  \uses{def:qcohOn}
  \leanok
  Let \(F\) and \(G\) be sheaves of \(k\)-modules on the small Zariski site of \(X\), let
  \(U\) be an open, and suppose given \(k\)-linear equivalences
  \(e_W : F(W) \cong G(W)\) for every open \(W \le U\), commuting with section
  restriction. If \(G\) carries a quasi-coherence packaging on \(U\)
  (\ref{def:qcohOn}), then so does \(F\), with the conjugated action
  \(r \cdot m := e_W^{-1}\bigl(r \cdot e_W(m)\bigr)\).
\end{definition}
\begin{proof}
  \leanok
  Each (P1) law for \(F\) follows by conjugating the corresponding law for \(G\) through
  the equivalences, and naturality under restriction combines the (P1) naturality for
  \(G\) with the compatibility of \(e\) with restriction. For (P2): given
  \(c \in F(V \cap D(g))\) on an affine \(V \le U\), denominator clearing for \(G\)
  applied to \(e(c)\) produces \(N\) and \(e' \in G(V)\) with
  \(e'|_{V \cap D(g)} = g^N \cdot e(c)\); then \(e_V^{-1}(e')\) clears the denominator
  for \(c\), since \(e\) commutes with restriction and the action is conjugated. Defect
  annihilation transports the same way.
\end{proof}

\begin{definition}[Twisted sections of a unit cocycle]
  \label{def:twistSections}
  \lean{AlgebraicGeometry.twistDefect, AlgebraicGeometry.twistSubmodule}
  \uses{def:moduleKSheaf}
  \leanok
  For an open \(W \subseteq X\), the \emph{defect map} of the cocycle \(g\) over \(W\) is
  the \(k\)-linear map
  \[
    \Gamma(X, W \cap V_0) \times \Gamma(X, W \cap V_1) \longrightarrow
      \Gamma(X, W \cap V_0 \cap V_1), \qquad
    (s_0, s_1) \longmapsto s_0| - g \cdot s_1|,
  \]
  where both restrictions are to \(W \cap V_0 \cap V_1\) and \(g\) acts through its
  restriction there. The module of \emph{twisted sections} \(F_g(W)\) is the kernel of
  the defect map: the pairs \((s_0, s_1)\) that match through \(g\) on the overlap.
\end{definition}

\begin{lemma}[Twisted sections form a presheaf]
  \label{lem:twistSections_presheaf}
  \lean{AlgebraicGeometry.twistRes, AlgebraicGeometry.twistSubmodule_res,
    AlgebraicGeometry.twistPresheaf}
  \uses{def:twistSections}
  \leanok
  For \(W' \le W\), componentwise restriction carries \(F_g(W)\) into \(F_g(W')\), and
  the resulting \(k\)-linear maps are functorial in the inclusion; so \(W \mapsto F_g(W)\)
  is a presheaf of \(k\)-modules.
\end{lemma}
\begin{proof}
  \leanok
  Restrict the matching identity \(s_0| = g \cdot s_1|\) from \(W \cap V_0 \cap V_1\) to
  \(W' \cap V_0 \cap V_1\): restriction of the structure sheaf is a ring homomorphism
  commuting with further restriction, so the restricted pair again matches.
  Functoriality is functoriality of restriction in each component.
\end{proof}

\begin{theorem}[The twisted sheaf]
  \label{thm:twistSheaf}
  \lean{AlgebraicGeometry.isSheaf_twistPresheaf, AlgebraicGeometry.twistSheaf}
  \uses{lem:twistSections_presheaf}
  \leanok
  The presheaf \(F_g\) of twisted sections is a sheaf of \(k\)-modules on the small
  Zariski site of \(X\).
\end{theorem}
\begin{proof}
  \leanok
  Let \(\{U_i\}\) be an open cover of \(W\) and \((s_0^i, s_1^i) \in F_g(U_i)\) sections
  agreeing on overlaps. The first components are sections of the structure sheaf over the
  cover \(\{U_i \cap V_0\}\) of \(W \cap V_0\), compatible on its overlaps; by the sheaf
  property of the structure sheaf they glue to a unique \(t_0 \in \Gamma(X, W \cap V_0)\),
  and likewise the second components glue to a unique \(t_1 \in \Gamma(X, W \cap V_1)\).
  The matching \(t_0| = g \cdot t_1|\) on \(W \cap V_0 \cap V_1\) may be checked on the
  cover \(\{U_i \cap V_0 \cap V_1\}\), where it restricts to the matching of
  \((s_0^i, s_1^i)\); by separation of the structure sheaf it holds on the union. So
  \((t_0, t_1) \in F_g(W)\) restricts to every \((s_0^i, s_1^i)\), and it is the unique
  such element because each of its components is determined by separation.
\end{proof}

\begin{definition}[Chart trivialisations of the twisted sheaf]
  \label{def:twistTriv}
  \lean{AlgebraicGeometry.twistTriv₀, AlgebraicGeometry.twistTriv₁}
  \uses{def:twistSections}
  \leanok
  Let \(W \le V_0\) (so \(W \cap V_0 = W\) and \(W \cap V_0 \cap V_1 = W \cap V_1\)).
  Projection to the first component is a \(k\)-linear equivalence
  \[
    \mathrm{triv}_0 : F_g(W) \;\cong\; \Gamma(X, W), \qquad (s_0, s_1) \mapsto s_0,
  \]
  with inverse \(s \mapsto (s,\ g^{-1} \cdot s|_{W \cap V_1})\). Symmetrically, for
  \(W \le V_1\), projection to the second component is a \(k\)-linear equivalence
  \(\mathrm{triv}_1 : F_g(W) \cong \Gamma(X, W)\) with inverse
  \(s \mapsto (g \cdot s|_{W \cap V_0},\ s)\).
\end{definition}
\begin{proof}
  \leanok
  For \(W \le V_0\) the matching relation of a pair \((s_0, s_1) \in F_g(W)\) reads
  \(s_0| = g \cdot s_1\) on \(W \cap V_1\), i.e.\ \(s_1 = g^{-1} \cdot s_0|\): the second
  component is rebuilt from the first, so projection and the displayed inverse are
  mutually inverse; the pair \((s, g^{-1} \cdot s|)\) matches by construction. Both maps
  are \(k\)-linear, multiplication by the fixed sections \(g^{\pm 1}\) being
  \(k\)-linear. The second chart is symmetric.
\end{proof}

\begin{lemma}[The trivialisations commute with restriction]
  \label{lem:twistTriv_res}
  \lean{AlgebraicGeometry.twistTriv₀_res, AlgebraicGeometry.twistTriv₁_res}
  \uses{def:twistTriv, lem:twistSections_presheaf}
  \leanok
  For \(W' \le W \le V_0\), trivialising after restricting equals restricting after
  trivialising: \(\mathrm{triv}_0(p|_{W'}) = (\mathrm{triv}_0\, p)|_{W'}\); likewise on
  the second chart.
\end{lemma}
\begin{proof}
  \leanok
  Both sides are the first (resp.\ second) component of \(p\) restricted to \(W'\);
  componentwise restriction is functorial.
\end{proof}

\begin{theorem}[The twisted sheaf is quasi-coherently packaged on each chart]
  \label{thm:twistSheaf_qcohOn}
  \lean{AlgebraicGeometry.twistSheaf.instQcohOn₀, AlgebraicGeometry.twistSheaf.instQcohOn₁}
  \uses{thm:twistSheaf, def:qcohOn_transport, def:twistTriv, lem:twistTriv_res,
    thm:moduleKSheaf_qcohOn}
  \leanok
  The twisted sheaf \(F_g\) carries a quasi-coherence packaging on \(V_0\) and on
  \(V_1\).
\end{theorem}
\begin{proof}
  \leanok
  The chart trivialisations give \(k\)-linear equivalences
  \(F_g(W) \cong \Gamma(X, W)\) for every \(W \le V_0\) (resp.\ \(W \le V_1\)),
  compatible with restriction (\ref{lem:twistTriv_res}); the structure sheaf is packaged
  on every open (\ref{thm:moduleKSheaf_qcohOn}); transport the packaging along the
  trivialisation (\ref{def:qcohOn_transport}).
\end{proof}

\begin{theorem}[Twisted affine vanishing]
  \label{thm:twistSheaf_affine_vanishing}
  \lean{AlgebraicGeometry.subsingleton_hModule'_twistSheaf_one₀,
    AlgebraicGeometry.subsingleton_hModule'_twistSheaf_one₁}
  \uses{def:HModule', thm:twistSheaf_qcohOn, thm:hModule1_vanishing_qcoh}
  \leanok
  If \(V_0\) (resp.\ \(V_1\)) is an affine open of \(X\), then
  \(H'^1(V_0, F_g) = 0\) (resp.\ \(H'^1(V_1, F_g) = 0\)).
\end{theorem}
\begin{proof}
  \leanok
  The twisted affine vanishing theorem \ref{thm:hModule1_vanishing_qcoh}, applied to the
  packaging of \ref{thm:twistSheaf_qcohOn}.
\end{proof}

\begin{definition}[The two-cover \(H^1\) carrier of the twisted sheaf]
  \label{def:twistTwoCoverH1}
  \lean{AlgebraicGeometry.twistTwoCoverH1}
  \uses{thm:twistSheaf, def:twoCoverSquare, thm:twistSheaf_affine_vanishing,
    thm:twoCoverH1LinearEquiv}
  \leanok
  Let \(V_0, V_1\) be affine opens with \(V_0 \cup V_1 = X\). Then the degree-one
  cohomology of the twisted sheaf is the two-cover cokernel of twisted sections: a
  \(k\)-linear isomorphism
  \[
    H^1(X, F_g) \;\cong\;
      F_g(V_0 \cap V_1) \big/ \mathrm{range}\bigl((p_0, p_1) \mapsto
        p_0|_{V_0 \cap V_1} - p_1|_{V_0 \cap V_1}\bigr),
  \]
  the restriction-difference map being that of the two-cover square
  (\ref{def:twoCoverSquare}) with coefficients in \(F_g\). (The overlap sections
  \(F_g(V_0 \cap V_1)\) are further identified with \(\Gamma(X, V_0 \cap V_1)\) by the
  chart trivialisation at \(V_0 \cap V_1 \le V_0\), \ref{def:twistTriv}.)
\end{definition}
\begin{proof}
  \leanok
  The two charts are affine, so \(H'^1(V_i, F_g) = 0\)
  (\ref{thm:twistSheaf_affine_vanishing}); apply the two-cover \(H^1\) computation with
  general coefficients (\ref{thm:twoCoverH1LinearEquiv}) to \(F = F_g\).
\end{proof}

\begin{definition}[The relative twisted sheaf]
  \label{def:relTwistSheaf}
  \lean{AlgebraicGeometry.relUnitCocycle, AlgebraicGeometry.relTwistSheaf}
  \uses{def:relCurve, def:relCover, lem:relCover_inf, def:twistSections, thm:twistSheaf}
  \leanok
  Let \(k\) be a field, \(C \in \Over(\Spec k)\), \(R\) a commutative \(k\)-algebra, and
  \(D = (V_0, V_1)\) an affine two-chart cover of \(C\). A unit cocycle
  \(g_k \in \Gamma(C, V_0 \cap V_1)^{\times}\) pulls back along the first projection to a
  unit cocycle on the base-changed cover of the relative curve:
  \(\mathrm{pr}_1^{\sharp}(g_k) \in
  \Gamma\bigl(C_R,\ \mathrm{pr}_1^{-1}V_0 \cap \mathrm{pr}_1^{-1}V_1\bigr)^{\times}\)
  (pullback of sections is a ring homomorphism, so it preserves units; the overlap of the
  base-changed charts is the preimage of \(V_0 \cap V_1\) by \ref{lem:relCover_inf}). The
  \emph{relative twisted sheaf} of a unit cocycle \(g\) on the base-changed cover is the
  twisted sheaf \(F_g\) on \(C_R\), a sheaf of \(R\)-modules.
\end{definition}

\begin{definition}[The relative twisted \(H^1\) carrier]
  \label{def:relTwistTwoCoverH1}
  \lean{AlgebraicGeometry.relTwistTwoCoverH1}
  \uses{def:relTwistSheaf, def:twistTwoCoverH1, lem:relCover_charts}
  \leanok
  In the setting of \ref{def:relTwistSheaf}, the degree-one cohomology of the relative
  twisted sheaf is the explicit two-cover cokernel of \(R\)-modules: an \(R\)-linear
  isomorphism
  \[
    H^1(C_R, F_g) \;\cong\;
      F_g\bigl(\mathrm{pr}_1^{-1}V_0 \cap \mathrm{pr}_1^{-1}V_1\bigr) \big/
        \mathrm{range}(\mathrm{diff}) .
  \]
\end{definition}
\begin{proof}
  \leanok
  The base-changed charts are affine and cover \(C_R\) (\ref{lem:relCover_charts});
  apply \ref{def:twistTwoCoverH1} over the base ring \(R\).
\end{proof}

\section{Base change of the two-term complex and of \(H^1\) on the relative curve}
\label{sec:relative_h1_base_change}

Fix a field \(k\), an object \(C \in \Over(\Spec k)\), and a homomorphism \(R \to R'\) of
commutative \(k\)-algebras --- a change of affine test rings. This section identifies the
sections of the relative curve as the free base change of the sections of \(C\), builds
the comparison morphism \(C_{R'} \to C_R\), base-changes the two-term two-cover complex
of Section~\ref{sec:mv-in-text} along \(R \to R'\) termwise, and concludes that the
degree-one cohomology of the structure sheaf of the relative curve commutes with
\emph{every} change of test ring --- no flatness of \(R \to R'\) is needed, because the
two-cover \(H^1\) is a cokernel and cokernels commute with arbitrary base change
(Chapter~\ref{chap:Algebra}).

\begin{theorem}[Sections of the relative curve are the base change of sections]
  \label{thm:sectionsBaseChange}
  \lean{AlgebraicGeometry.Over.sectionsBaseChange, AlgebraicGeometry.Over.sectionsBaseChange_tmul}
  \uses{def:relCurve}
  \leanok
  Let \(k\) be a field, \(C \in \Over(\Spec k)\), \(R\) a commutative \(k\)-algebra, and
  \(V \subseteq C\) a quasi-compact quasi-separated open (for instance any affine open,
  or a finite intersection or union of affine opens of a quasi-separated scheme). Write
  \(V_R := \mathrm{pr}_1^{-1} V \subseteq C_R\). Then there is a ring isomorphism
  \[
    \Gamma(C, V) \otimes_k R \;\cong\; \Gamma(C_R, V_R), \qquad
    s \otimes a \longmapsto \mathrm{pr}_1^{\sharp}(s) \cdot \mathrm{pr}_2^{\sharp}(a),
  \]
  where \(\mathrm{pr}_1^{\sharp}\) is pullback of sections along the first projection,
  and \(\mathrm{pr}_2^{\sharp}(a)\) is the pullback along the second projection of the
  global section \(a \in R = \Gamma(\Spec R, \top)\). (The \(k\)-algebra structure on
  \(\Gamma(C, V)\) is restriction of scalars along the structure morphism.)
\end{theorem}
\begin{proof}
  \leanok
  The displayed assignment is a well-defined \(k\)-algebra map \(\chi_V\) out of the
  tensor product: both pullbacks are \(k\)-algebra homomorphisms into the commutative
  ring \(\Gamma(C_R, V_R)\), and the tensor product of commutative \(k\)-algebras is
  their pushout.

  \emph{Step 1: \(V\) affine.} The open \(V_R = \mathrm{pr}_1^{-1}(V)\) of the fibre
  product \(C_R = C \times_{\Spec k} \Spec R\) is the fibre product
  \(V \times_{\Spec k} \Spec R\) of the open subscheme \(V\), a fibre product of affine
  schemes, hence the affine scheme \(\Spec(\Gamma(V) \otimes_k R)\): \(\Spec\) converts
  the pushout of commutative rings into the fibre product of affine schemes. Under this
  identification \(\chi_V\) is the canonical isomorphism.

  \emph{Step 2: \(V\) quasi-compact quasi-separated.} Choose a finite affine cover
  \(V = U_1 \cup \dots \cup U_n\) (quasi-compactness); each intersection
  \(U_i \cap U_j\) is quasi-compact (quasi-separatedness), so it in turn has a finite
  affine cover \(\{W^{ij}_l\}\). The sheaf axiom writes \(\Gamma(C, V)\) as the
  equaliser of the two restriction maps between the finite products
  \(\prod_i \Gamma(U_i)\) and \(\prod_{i,j,l} \Gamma(W^{ij}_l)\). The preimages
  \(\mathrm{pr}_1^{-1} U_i\) form an affine cover of \(V_R\) (Step 1) whose pairwise
  intersections are covered by the affine \(\mathrm{pr}_1^{-1} W^{ij}_l\) (preimage
  commutes with unions and intersections), so \(\Gamma(C_R, V_R)\) is the equaliser of
  the corresponding restriction maps for the preimage cover. Since \(R\) is a free,
  hence flat, \(k\)-module (\(k\) is a field), the functor \(- \otimes_k R\) is exact
  and commutes with finite products, so it carries the first equaliser diagram to an
  equaliser diagram. The maps \(\chi\) on the terms commute with the two restriction
  maps (pullback commutes with restriction) and are isomorphisms on the product terms by
  Step 1; hence the induced map on equalisers, which is \(\chi_V\), is an isomorphism.
\end{proof}

\begin{definition}[Relative sections as a free \(R\)-module base change]
  \label{def:relSectionsBaseChange}
  \lean{AlgebraicGeometry.relPullbackSection, AlgebraicGeometry.relSectionsBaseChange,
    AlgebraicGeometry.relSectionsBaseChange_tmul,
    AlgebraicGeometry.Over.sectionsBaseChange_one_tmul_overAlgebraMap}
  \uses{thm:sectionsBaseChange}
  \leanok
  In the setting of \ref{thm:sectionsBaseChange}, endow \(\Gamma(C_R, V_R)\) with the
  \(R\)-module structure \(r \cdot y := \mathrm{pr}_2^{\sharp}(r) \cdot y\) given by
  pullback along the structure morphism \(\mathrm{pr}_2 : C_R \to \Spec R\). The
  isomorphism of \ref{thm:sectionsBaseChange}, read with the tensor factors flipped, is
  an \(R\)-linear equivalence
  \[
    R \otimes_k \Gamma(C, V) \;\cong\; \Gamma(C_R, V_R), \qquad
    a \otimes s \longmapsto \mathrm{pr}_2^{\sharp}(a) \cdot \mathrm{pr}_1^{\sharp}(s),
  \]
  with \(R\) acting on the left tensor factor; in particular
  \(1 \otimes r \mapsto \mathrm{pr}_2^{\sharp}(r)\).
\end{definition}
\begin{proof}
  \leanok
  Only \(R\)-linearity needs comment: on a pure tensor,
  \(r \cdot (a \otimes s) = (ra) \otimes s\) maps to
  \(\mathrm{pr}_2^{\sharp}(ra) \cdot \mathrm{pr}_1^{\sharp}(s) =
  \mathrm{pr}_2^{\sharp}(r) \cdot \bigl(\mathrm{pr}_2^{\sharp}(a) \cdot
  \mathrm{pr}_1^{\sharp}(s)\bigr)\), because \(\mathrm{pr}_2^{\sharp}\) is a ring
  homomorphism --- and the right-hand side is \(r\) acting on the image.
\end{proof}

\begin{definition}[The comparison morphism of relative curves]
  \label{def:relCurveMap}
  \lean{AlgebraicGeometry.overSpecMap, AlgebraicGeometry.relCurveMap}
  \uses{def:relCurve}
  \leanok
  Let \(\varphi : R \to R'\) be a homomorphism of commutative \(k\)-algebras. Applying
  \(\Spec\) gives a morphism \(\Spec R' \to \Spec R\) over \(\Spec k\), and the induced
  morphism of fibre products
  \[
    \rho \;=\; \mathrm{id}_C \times \Spec(\varphi) \;:\; C_{R'} \longrightarrow C_R
  \]
  is the \emph{comparison morphism} between the relative curves.
\end{definition}

\begin{lemma}[Projection identities of the comparison morphism]
  \label{lem:relCurveMap_proj}
  \lean{AlgebraicGeometry.relCurveMap_fst, AlgebraicGeometry.relCurveMap_snd,
    AlgebraicGeometry.relCurveMap_preimage}
  \uses{def:relCurveMap}
  \leanok
  The comparison morphism satisfies
  \(\mathrm{pr}_1 \circ \rho = \mathrm{pr}_1\) and
  \(\mathrm{pr}_2 \circ \rho = \Spec(\varphi) \circ \mathrm{pr}_2\); consequently
  \(\rho^{-1}(V_R) = V_{R'}\) for every open \(V \subseteq C\).
\end{lemma}
\begin{proof}
  \leanok
  The first two identities are the compatibility of the induced morphism of fibre
  products with the two projections; the third follows from the first by taking
  preimages of \(V\).
\end{proof}

\begin{definition}[The sections comparison map]
  \label{def:relSectionsMap}
  \lean{AlgebraicGeometry.relSectionsMap}
  \uses{def:relCurveMap, lem:relCurveMap_proj}
  \leanok
  For \(V \subseteq C\) open, pullback of sections along \(\rho\) (allowed since
  \(\rho^{-1}(V_R) = V_{R'}\), \ref{lem:relCurveMap_proj}) is a ring homomorphism
  \[
    \rho^{\sharp} \;:\; \Gamma(C_R, V_R) \longrightarrow \Gamma(C_{R'}, V_{R'}) .
  \]
\end{definition}

\begin{lemma}[Governing identities of the sections comparison map]
  \label{lem:relSectionsMap_props}
  \lean{AlgebraicGeometry.relSectionsMap_pullback,
    AlgebraicGeometry.relSectionsMap_overAlgebraMap,
    AlgebraicGeometry.relSectionsMap_smul, AlgebraicGeometry.relSectionsMap_resHom}
  \uses{def:relSectionsMap, lem:relCurveMap_proj, def:relSectionsBaseChange}
  \leanok
  The sections comparison map \(\rho^{\sharp}\):
  \begin{enumerate}
    \item commutes with the curve pullbacks:
      \(\rho^{\sharp}(\mathrm{pr}_1^{\sharp} s) = \mathrm{pr}_1^{\sharp} s\) for
      \(s \in \Gamma(C, V)\);
    \item intertwines the structure pullbacks:
      \(\rho^{\sharp}(\mathrm{pr}_2^{\sharp} r) = \mathrm{pr}_2^{\sharp}(\varphi(r))\)
      for \(r \in R\);
    \item hence is semilinear along \(\varphi\):
      \(\rho^{\sharp}(r \cdot y) = \varphi(r) \cdot \rho^{\sharp}(y)\) for the module
      structures of \ref{def:relSectionsBaseChange};
    \item commutes with restriction along \(W \le V\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \leanok
  (1) is pullback along \(\mathrm{pr}_1 \circ \rho = \mathrm{pr}_1\)
  (\ref{lem:relCurveMap_proj}); (2) is pullback along
  \(\mathrm{pr}_2 \circ \rho = \Spec(\varphi) \circ \mathrm{pr}_2\), and the pullback of
  the global section \(r\) along \(\Spec(\varphi)\) is \(\varphi(r)\); (3) is (2)
  together with multiplicativity of \(\rho^{\sharp}\); (4) is functoriality of pullback
  of sections with respect to inclusions of opens.
\end{proof}

\begin{theorem}[CBC-1: termwise base change of relative sections]
  \label{thm:relTermBaseChange}
  \lean{AlgebraicGeometry.relTermBaseChange, AlgebraicGeometry.relTermBaseChange_tmul}
  \uses{def:relSectionsBaseChange, lem:relSectionsMap_props}
  \leanok
  Let \(R \to R'\) be a homomorphism of test rings and \(V \subseteq C\) a quasi-compact
  quasi-separated open. There is an \(R'\)-linear equivalence
  \[
    R' \otimes_R \Gamma(C_R, V_R) \;\cong\; \Gamma(C_{R'}, V_{R'}), \qquad
    r' \otimes y \longmapsto r' \cdot \rho^{\sharp}(y) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Compose the free identifications of \ref{def:relSectionsBaseChange} over \(R\) and
  over \(R'\) with the tensor cancellation
  \(R' \otimes_R (R \otimes_k M) \cong R' \otimes_k M\):
  \[
    R' \otimes_R \Gamma(C_R, V_R) \;\cong\; R' \otimes_R \bigl(R \otimes_k \Gamma(C, V)\bigr)
      \;\cong\; R' \otimes_k \Gamma(C, V) \;\cong\; \Gamma(C_{R'}, V_{R'}) .
  \]
  For the formula, both sides are additive in \(y\) and \(R'\)-linear in \(r'\), so it
  suffices to treat \(y = \mathrm{pr}_2^{\sharp}(a) \cdot \mathrm{pr}_1^{\sharp}(s)\)
  (the images of pure tensors, which span). Chasing \(r' \otimes y\) through the
  composite gives \(\mathrm{pr}_2^{\sharp}\bigl(r' \varphi(a)\bigr) \cdot
  \mathrm{pr}_1^{\sharp}(s) = r' \cdot \bigl(\mathrm{pr}_2^{\sharp}(\varphi(a)) \cdot
  \mathrm{pr}_1^{\sharp}(s)\bigr)\), which by (1) and (2) of
  \ref{lem:relSectionsMap_props} is \(r' \cdot \rho^{\sharp}(y)\).
\end{proof}

\begin{lemma}[CBC-1: the two-cover complex base-changes]
  \label{lem:relDiffBaseChange}
  \lean{AlgebraicGeometry.relDiffDomBaseChange, AlgebraicGeometry.relDiffCodBaseChange,
    AlgebraicGeometry.relDiffBaseChange, AlgebraicGeometry.relDiffBaseChange_range}
  \uses{thm:relTermBaseChange, def:TwoCover_diff, def:relCover, lem:relCover_charts,
    lem:relCover_inf, lem:relSectionsMap_props}
  \leanok
  Let \(D = (V_0, V_1)\) be an affine two-chart cover of \(C\), and write
  \(\mathrm{diff}_R\) for the two-cover restriction-difference map
  (\ref{def:TwoCover_diff}) of \(C_R\) with its base-changed cover
  (\ref{def:relCover}). Under the term equivalences of \ref{thm:relTermBaseChange} ---
  the product of the two chart equivalences on the domain, the overlap equivalence on the
  codomain --- the base change \(\mathrm{diff}_R \otimes_R R'\) corresponds to
  \(\mathrm{diff}_{R'}\): the evident square commutes. In particular the overlap term
  equivalence carries \(\mathrm{range}(\mathrm{diff}_R \otimes_R R')\) onto
  \(\mathrm{range}(\mathrm{diff}_{R'})\).
\end{lemma}
\begin{proof}
  \leanok
  Both composites are additive, so it suffices to compare them on
  \(r' \otimes (s_0, s_1)\). Along the top and right, the result is
  \(r' \cdot \rho^{\sharp}\bigl(s_0|_{\cap} - s_1|_{\cap}\bigr)\); along the left and
  bottom, it is \(\mathrm{diff}_{R'}\bigl(r' \cdot \rho^{\sharp} s_0,\ r' \cdot
  \rho^{\sharp} s_1\bigr) = \bigl(r' \cdot \rho^{\sharp} s_0\bigr)|_{\cap} -
  \bigl(r' \cdot \rho^{\sharp} s_1\bigr)|_{\cap}\). These agree because
  \(\rho^{\sharp}\) commutes with restriction (\ref{lem:relSectionsMap_props}(4)) and
  the \(R'\)-action commutes with restriction (the structure pullback restricts to the
  structure pullback). The range statement follows because the domain equivalence is
  surjective.
\end{proof}

\begin{theorem}[CBC-2, cokernel form: the two-cover \(H^1\) carrier base-changes]
  \label{thm:relH1CokBaseChange}
  \lean{AlgebraicGeometry.relH1CokBaseChange, AlgebraicGeometry.relH1CokBaseChange_tmul_mk}
  \uses{thm:quot_range_baseChange, lem:relDiffBaseChange, def:TwoCover_H1Cok}
  \leanok
  In the setting of \ref{lem:relDiffBaseChange} there is an \(R'\)-linear equivalence
  \[
    R' \otimes_R \Bigl(\Gamma\bigl(C_R, \cap\bigr)\big/\mathrm{range}(\mathrm{diff}_R)\Bigr)
    \;\cong\;
    \Gamma\bigl(C_{R'}, \cap\bigr)\big/\mathrm{range}(\mathrm{diff}_{R'}),
    \qquad r' \otimes [s] \longmapsto [\,r' \cdot \rho^{\sharp} s\,],
  \]
  where \(\cap\) denotes the overlap of the respective base-changed covers
  (\ref{def:TwoCover_H1Cok}). No hypothesis on \(R \to R'\) is needed.
\end{theorem}
\begin{proof}
  \leanok
  Base change commutes with cokernels (\ref{thm:quot_range_baseChange}, with
  \(N = \Gamma(C_R, \cap)\), \(f = \mathrm{diff}_R\), \(S = R'\)):
  \(R' \otimes_R \bigl(N/\mathrm{range}\,f\bigr) \cong (R' \otimes_R N)/
  \mathrm{range}(f \otimes_R R')\). Then pass along the overlap term equivalence, which
  identifies \(\mathrm{range}(\mathrm{diff}_R \otimes_R R')\) with
  \(\mathrm{range}(\mathrm{diff}_{R'})\) (\ref{lem:relDiffBaseChange}), hence descends to
  the quotients. The composite sends \(r' \otimes [s]\) to
  \([\,r' \cdot \rho^{\sharp} s\,]\) by \ref{thm:relTermBaseChange}.
\end{proof}

\begin{theorem}[CBC-2: \(H^1\) of the relative curve commutes with change of the test ring]
  \label{thm:relH1BaseChange}
  \lean{AlgebraicGeometry.relH1BaseChange}
  \uses{def:relTwoCoverH1, thm:relH1CokBaseChange}
  \leanok
  \source{kleiman-picard}
  For every homomorphism \(R \to R'\) of commutative \(k\)-algebras there is an
  \(R'\)-linear equivalence
  \[
    R' \otimes_R H^1\bigl(C_R, \struct{C_R/R}\bigr) \;\cong\;
      H^1\bigl(C_{R'}, \struct{C_{R'}/R'}\bigr) :
  \]
  degree-one cohomology of the structure sheaf of the relative curve commutes with
  \emph{every} base change of the test ring. No flatness of \(R \to R'\) is required:
  the two-cover \(H^1\) is the cokernel of a two-term complex whose terms base-change
  freely, and cokernels commute with arbitrary base change.
\end{theorem}
\begin{proof}
  \leanok
  Conjugate the cokernel equivalence of \ref{thm:relH1CokBaseChange} by the relative
  two-cover identifications \(H^1(C_R, \struct{C_R/R}) \cong
  \Gamma(C_R, \cap)/\mathrm{range}(\mathrm{diff}_R)\) of \ref{def:relTwoCoverH1}, over
  \(R\) and over \(R'\).
\end{proof}

\begin{definition}[Base change of the unit cocycle]
  \label{def:relCocycleBaseChange}
  \lean{AlgebraicGeometry.relCocycleBaseChange}
  \uses{def:relTwistSheaf, def:relSectionsMap, lem:relCurveMap_proj}
  \leanok
  For a unit cocycle \(g\) on the base-changed cover of \(C_R\), the image
  \(\rho^{\sharp}(g)\) is a unit cocycle on the base-changed cover of \(C_{R'}\): the
  ring homomorphism \(\rho^{\sharp}\) preserves units, and the overlaps correspond under
  \(\rho\) (\ref{lem:relCurveMap_proj}).
\end{definition}

\begin{definition}[CBC-1 for the twisted sheaf: term equivalences]
  \label{def:relTwistTermBaseChange}
  \lean{AlgebraicGeometry.relTwistTermBaseChange₀, AlgebraicGeometry.relTwistTermBaseChange₁,
    AlgebraicGeometry.relTwistOverlapBaseChange}
  \uses{def:relTwistSheaf, def:relCocycleBaseChange, def:twistTriv, thm:relTermBaseChange,
    lem:relDiffBaseChange}
  \leanok
  Let \(g\) be a unit cocycle on the base-changed cover of \(C_R\) and
  \(g' = \rho^{\sharp}(g)\) its base change (\ref{def:relCocycleBaseChange}). For each
  term of the twisted two-cover complex --- the two charts and their overlap --- the
  composite of the chart trivialisation over \(R\) (\ref{def:twistTriv}), the
  structure-sheaf term base change of \ref{thm:relTermBaseChange} (at the overlap: the
  codomain equivalence of \ref{lem:relDiffBaseChange}), and the inverse chart
  trivialisation over \(R'\) is an \(R'\)-linear equivalence
  \[
    R' \otimes_R F_g(\text{term over } R) \;\cong\; F_{g'}(\text{term over } R') .
  \]
  On the overlap, the first-chart trivialisation (at
  \(\mathrm{pr}_1^{-1}V_0 \cap \mathrm{pr}_1^{-1}V_1 \le \mathrm{pr}_1^{-1}V_0\)) is
  used.
\end{definition}

\section{The base-field transition and its sections base change}
\label{sec:base_field_transition}

Fix a field \(k\) and an object \(C \in \Over(\Spec k)\). For a field extension \(K/k\)
write \(C_K := (C \otimes \Spec K)_{\mathrm{left}}\) for the base-changed curve, a scheme
over \(\Spec K\) through the second projection. A \(k\)-algebra homomorphism
\(\varphi : K_1 \to K_2\) between field extensions of \(k\) induces the
\emph{base-field transition}
\[
  \pi \;=\; \bigl(C \lhd \Spec(\varphi)\bigr)_{\mathrm{left}} \;:\; C_{K_2}
  \longrightarrow C_{K_1},
\]
the whiskering of \(C\) with \(\Spec\varphi\) between the test objects
(\ref{def:overSpecMap}). This section provides the transition's geometric toolkit and
identifies the sections of \(C_{K_2}\) over the preimage of an affine open with the base
change of the sections of \(C_{K_1}\).

A design point governs everything that follows: the ``base-field shuffle''
\(C_{K_1} \otimes_{K_1} K_2 \cong C_{K_2}\) is \emph{never constructed as an isomorphism
of schemes}. All statements are made against the transition square below, which exhibits
\(\pi\) as a base change of \(\Spec\varphi\) directly. In particular, the sections base
change of this section is deliberately \emph{not} obtained by instantiating
Theorem~\ref{thm:sectionsBaseChange} (whose tensor factor is anchored at the base field
\(k\)) over the base \(K_1\) and transporting along a shuffle isomorphism --- the short
pushout argument is re-run against the pasted square instead, with the
\(K_1\)-algebra structure on sections carried by the second projection.

\begin{lemma}[The product bridge]
  \label{lem:over_isPullback_left}
  \lean{AlgebraicGeometry.Over.isPullback_left}
  \leanok
  Let \(S\) be a scheme and \(X, T \in \Over(S)\). The underlying scheme of the
  cartesian-monoidal product, with its two projections, is the fibre product of the
  structure morphisms:
  \[
    \begin{array}{ccc}
      (X \otimes T)_{\mathrm{left}} & \xrightarrow{\ \mathrm{fst}\ } & X_{\mathrm{left}} \\
      \downarrow \mathrm{snd} & & \downarrow X.\mathrm{hom} \\
      T_{\mathrm{left}} & \xrightarrow{\ T.\mathrm{hom}\ } & S
    \end{array}
  \]
  is a pullback square of schemes. This is the single point where the product of the over
  category is unfolded to a scheme-level pullback.
\end{lemma}
\begin{proof}
  \leanok
  The cartesian-monoidal product of the over category is constructed as the chosen pullback
  of the structure morphisms, with the two projections as its legs; the square is that
  chosen pullback square.
\end{proof}

\begin{theorem}[The pasted square of a morphism of test objects]
  \label{thm:isPullback_whiskerLeft_left}
  \lean{AlgebraicGeometry.Over.isPullback_whiskerLeft_left}
  \uses{lem:over_isPullback_left}
  \leanok
  Let \(S\) be a scheme, \(X \in \Over(S)\), and \(t : T' \to T\) a morphism of
  \(\Over(S)\). The square
  \[
    \begin{array}{ccc}
      (X \otimes T')_{\mathrm{left}} & \xrightarrow{(X \lhd t)_{\mathrm{left}}} &
        (X \otimes T)_{\mathrm{left}} \\
      \downarrow \mathrm{pr}_2' & & \downarrow \mathrm{pr}_2 \\
      T'_{\mathrm{left}} & \xrightarrow{\ t_{\mathrm{left}}\ } & T_{\mathrm{left}}
    \end{array}
  \]
  (verticals the second projections) is a pullback of schemes. This generalises the
  base-change square of the product (\ref{thm:isPullback_whiskerLeft_snd}) from the base
  \(\Spec k\) to an arbitrary base \(S\); it is stated for an arbitrary morphism of test
  objects so that later campaigns can re-instantiate it without re-proving.
\end{theorem}
\begin{proof}
  \leanok
  Paste the two cartesian squares expressing \(X \otimes T\) and \(X \otimes T'\) as
  products over \(S\). The first-projection triangle
  \((X \lhd t)_{\mathrm{left}} \circ \mathrm{fst} = \mathrm{fst}'\) and the base identity
  \(t_{\mathrm{left}} \circ (T.\mathrm{hom}) = T'.\mathrm{hom}\) exhibit the outer
  rectangle over \(X_{\mathrm{left}} \times S\) as the product square of
  \(X \otimes T'\); the right-cancellation property of pullback squares applied to the
  product square of \(X \otimes T\) then makes the displayed square a pullback.
\end{proof}

\begin{theorem}[The base-field transition square]
  \label{thm:isPullback_baseFieldTransition}
  \lean{AlgebraicGeometry.isPullback_baseFieldTransition}
  \uses{thm:isPullback_whiskerLeft_left, def:overSpecMap}
  \leanok
  Let \(k\) be a commutative ring, \(C \in \Over(\Spec k)\), and
  \(\varphi : K_1 \to K_2\) a \(k\)-algebra homomorphism. The square
  \[
    \begin{array}{ccc}
      C_{K_2} & \xrightarrow{\ \pi\ } & C_{K_1} \\
      \downarrow \mathrm{pr}_2 & & \downarrow \mathrm{pr}_2 \\
      \Spec K_2 & \xrightarrow{\Spec \varphi} & \Spec K_1
    \end{array}
  \]
  is a pullback of schemes: the base-field transition is the base change of
  \(\Spec\varphi\) along the second projection of the \(K_1\)-curve.
\end{theorem}
\begin{proof}
  \leanok
  Instantiate the pasted square (\ref{thm:isPullback_whiskerLeft_left}) at the morphism
  of test objects \(\Spec\varphi : \Spec K_2 \to \Spec K_1\) over \(\Spec k\)
  (\ref{def:overSpecMap}).
\end{proof}

The pasted square above compares two tests over one base. The next squares cross a
morphism of \emph{bases} \(f : S' \to S\): the slice product of the base change
\(f^{*}X\) with a test over \(S'\) agrees, as a scheme, with the slice product of \(X\)
itself with the test pushed forward to \(S\). Throughout, \(f^{*}X \in \Over(S')\)
denotes the base change of \(X \in \Over(S)\) along \(f\) --- its underlying scheme is
the fibre product \(X_{\mathrm{left}} \times_S S'\), its structure morphism the second
projection --- and \(f_{!}T \in \Over(S)\) denotes a test \(T \in \Over(S')\) regarded
over \(S\) through \(f\): the same underlying scheme, with structure morphism
\(f \circ T.\mathrm{hom}\).

\begin{theorem}[The cross-base pasted square]
  \label{thm:over_isPullback_crossBase}
  \lean{AlgebraicGeometry.Over.isPullback_crossBase}
  \uses{lem:over_isPullback_left}
  \leanok
  Let \(f : S' \to S\) be a morphism of schemes, \(X \in \Over(S)\), and
  \(T \in \Over(S')\). The square
  \[
    \begin{array}{ccc}
      (f^{*}X \otimes T)_{\mathrm{left}} &
        \xrightarrow{\ \mathrm{pr}_1 \circ\, \mathrm{fst}\ } & X_{\mathrm{left}} \\
      \downarrow \mathrm{snd} & & \downarrow X.\mathrm{hom} \\
      T_{\mathrm{left}} & \xrightarrow{\ f \circ T.\mathrm{hom}\ } & S
    \end{array}
  \]
  is a pullback of schemes; here the top edge is the first slice projection
  \(\mathrm{fst} : (f^{*}X \otimes T)_{\mathrm{left}} \to (f^{*}X)_{\mathrm{left}}
  = X_{\mathrm{left}} \times_S S'\) followed by the first projection of the fibre
  product, and the bottom edge \(f \circ T.\mathrm{hom}\) is the structure morphism of
  \(f_{!}T\). Thus the slice product \(f^{*}X \otimes T\), formed over \(S'\), is at the
  same time a pullback of the \emph{cross-base} cospan
  \(X_{\mathrm{left}} \to S \leftarrow T_{\mathrm{left}}\).
\end{theorem}
\begin{proof}
  \leanok
  Paste horizontally the slice-product square of \(f^{*}X\) and \(T\) over \(S'\)
  (\ref{lem:over_isPullback_left}) --- horizontals \(\mathrm{fst}\) and
  \(T.\mathrm{hom}\), verticals \(\mathrm{snd}\) and the structure morphism of
  \(f^{*}X\) --- with the defining base-change square of \(f^{*}X\),
  \[
    \begin{array}{ccc}
      X_{\mathrm{left}} \times_S S' & \xrightarrow{\ \mathrm{pr}_1\ } &
        X_{\mathrm{left}} \\
      \downarrow \mathrm{pr}_2 & & \downarrow X.\mathrm{hom} \\
      S' & \xrightarrow{\ f\ } & S
    \end{array}
  \]
  whose left vertical \(\mathrm{pr}_2\) \emph{is} that structure morphism. The two
  pullback squares share this middle edge, and a horizontal paste of two pullback
  squares is a pullback; the outer rectangle is the displayed square, its top the
  composite \(\mathrm{pr}_1 \circ \mathrm{fst}\) and its bottom the composite
  \(f \circ T.\mathrm{hom}\).
\end{proof}

\begin{definition}[The cross-base comparison isomorphism]
  \label{def:crossBaseIso}
  \lean{AlgebraicGeometry.Over.crossBaseIso}
  \uses{thm:over_isPullback_crossBase, lem:over_isPullback_left}
  \leanok
  In the situation of \ref{thm:over_isPullback_crossBase}, the \emph{cross-base
  comparison isomorphism} is the isomorphism of schemes
  \[
    (f^{*}X \otimes T)_{\mathrm{left}} \;\cong\; (X \otimes f_{!}T)_{\mathrm{left}}
  \]
  identifying the two pullbacks of the common cospan
  \(X_{\mathrm{left}} \to S \leftarrow T_{\mathrm{left}}\): the left-hand side by the
  cross-base pasted square (\ref{thm:over_isPullback_crossBase}), the right-hand side
  by the product bridge for \(X\) and \(f_{!}T\) over \(S\)
  (\ref{lem:over_isPullback_left}). It is compatible with the projections: composed
  with the first projection of the right-hand side it is the top edge
  \(\mathrm{pr}_1 \circ \mathrm{fst}\) of the pasted square, and composed with the
  second projection it is \(\mathrm{snd}\).
\end{definition}
\begin{proof}
  \leanok
  Two pullbacks of one cospan are canonically isomorphic: each limiting cone factors
  uniquely through the other, and the two factorizations compose to endomorphisms of
  limiting cones commuting with the projections, hence to the identities. The stated
  projection compatibilities are the defining property of the factorization.
\end{proof}

\begin{theorem}[Naturality of the cross-base isomorphism in the test]
  \label{thm:crossBaseIso_naturality}
  \lean{AlgebraicGeometry.Over.crossBaseIso_naturality}
  \uses{def:crossBaseIso, lem:over_isPullback_left}
  \leanok
  For a morphism \(t : T' \to T\) of \(\Over(S')\), the comparison isomorphisms of
  \ref{def:crossBaseIso} intertwine the two whiskered morphisms: the square
  \[
    \begin{array}{ccc}
      (f^{*}X \otimes T')_{\mathrm{left}} &
        \xrightarrow{(f^{*}X \lhd t)_{\mathrm{left}}} &
        (f^{*}X \otimes T)_{\mathrm{left}} \\
      \downarrow \cong & & \downarrow \cong \\
      (X \otimes f_{!}T')_{\mathrm{left}} &
        \xrightarrow{(X \lhd f_{!}t)_{\mathrm{left}}} &
        (X \otimes f_{!}T)_{\mathrm{left}}
    \end{array}
  \]
  commutes, where \(f_{!}t\) is \(t\) regarded as a morphism \(f_{!}T' \to f_{!}T\)
  over \(S\).
\end{theorem}
\begin{proof}
  \leanok
  Two morphisms into the pullback \((X \otimes f_{!}T)_{\mathrm{left}}\)
  (\ref{lem:over_isPullback_left}) are equal once they agree after composing with both
  projections. With the first projection: whiskering leaves the first factor untouched,
  and the comparison isomorphisms identify the first projections with the top edges of
  the pasted squares (\ref{def:crossBaseIso}), so both composites equal the top edge
  \(\mathrm{pr}_1 \circ \mathrm{fst}'\) of the square of \(T'\). With the second
  projection: whiskering acts on the second factor by \(t\) --- whose underlying
  morphism of schemes is also that of \(f_{!}t\) --- and the comparison isomorphisms
  identify the second projections, so both composites equal
  \(t_{\mathrm{left}} \circ \mathrm{snd}'\). Hence the square commutes.
\end{proof}

\begin{theorem}[The cross-base square at a base-changed curve]
  \label{thm:crossBase_baseChange}
  \lean{AlgebraicGeometry.isPullback_crossBase, AlgebraicGeometry.crossBaseIso,
    AlgebraicGeometry.crossBaseIso_naturality}
  \uses{thm:over_isPullback_crossBase, def:crossBaseIso, thm:crossBaseIso_naturality,
    def:baseChange}
  \leanok
  Let \(k \to L\) be a field extension, \(\sigma : \Spec L \to \Spec k\) the induced
  morphism of spectra, and \(C \in \Over(\Spec k)\), with base change
  \(\sigma^{*}C \in \Over(\Spec L)\) along \(L/k\) (\ref{def:baseChange}). Then for
  every test object \(T \in \Over(\Spec L)\): the slice product
  \((\sigma^{*}C \otimes T)_{\mathrm{left}}\), formed over \(\Spec L\), is a pullback
  of \(C.\mathrm{hom}\) against the structure morphism of \(\sigma_{!}T\), and the
  comparison isomorphism of schemes
  \[
    (\sigma^{*}C \otimes T)_{\mathrm{left}} \;\cong\;
      (C \otimes \sigma_{!}T)_{\mathrm{left}}
  \]
  is natural in \(T\).
\end{theorem}
\begin{proof}
  \leanok
  Base change along \(L/k\) is the slice pullback along \(\sigma\)
  (\ref{def:baseChange}), so this is \ref{thm:over_isPullback_crossBase},
  \ref{def:crossBaseIso} and \ref{thm:crossBaseIso_naturality} instantiated at
  \(f = \sigma\) and \(X = C\).
\end{proof}

\begin{definition}[Pushing an affine test down a field extension]
  \label{def:mapOverSpecIso}
  \lean{AlgebraicGeometry.mapOverSpecIso}
  \leanok
  Let \(k \to L\) be a field extension, \(\sigma : \Spec L \to \Spec k\) the induced
  morphism, and \(A\) an \(L\)-algebra whose \(k\)-algebra structure is the restriction
  through \(L\) (a scalar tower \(k \to L \to A\)). Write \(\Spec A / \Spec F\) for the
  affine test attached to an \(F\)-algebra \(A\): the object \(\Spec A\) of
  \(\Over(\Spec F)\) with structure morphism \(\Spec\) of the algebra map. Then pushing
  the affine test of \(A\) over \(L\) forward along \(\sigma\) gives the affine test of
  \(A\) over \(k\): there is an isomorphism
  \[
    \sigma_{!}\bigl(\Spec A / \Spec L\bigr) \;\cong\; \Spec A / \Spec k
    \quad \text{in } \Over(\Spec k),
  \]
  whose underlying morphism of schemes is the identity of \(\Spec A\).
\end{definition}
\begin{proof}
  \leanok
  The push-forward keeps the underlying scheme \(\Spec A\) and composes the structure
  morphism with \(\sigma\). The algebra map \(k \to A\) is the composite
  \(k \to L \to A\) (the tower identity), so by contravariant functoriality of
  \(\Spec\) the composed structure morphism
  \(\sigma \circ \Spec(L \to A)\) is \(\Spec\) of the algebra map \(k \to A\) --- which
  is exactly the structure morphism of the affine test of \(A\) over \(k\). Hence the
  identity of \(\Spec A\) is an isomorphism between the two objects of
  \(\Over(\Spec k)\).
\end{proof}

\begin{lemma}[The transition is flat, affine and surjective]
  \label{lem:baseFieldTransition_flat_affine_surjective}
  \lean{AlgebraicGeometry.flat_specMap_algHom, AlgebraicGeometry.surjective_specMap_algHom,
    AlgebraicGeometry.flat_baseFieldTransition,
    AlgebraicGeometry.isAffineHom_baseFieldTransition,
    AlgebraicGeometry.surjective_baseFieldTransition}
  \uses{thm:isPullback_baseFieldTransition}
  \leanok
  Let \(K_1\) be a field and \(K_2\) a nonzero commutative ring. Then
  \(\Spec\varphi : \Spec K_2 \to \Spec K_1\) is flat and surjective, and it is affine
  since both schemes are affine. Consequently, for field extensions \(K_1, K_2\) of
  \(k\), the base-field transition \(\pi : C_{K_2} \to C_{K_1}\) is flat, affine and
  surjective.
\end{lemma}
\begin{proof}
  \leanok
  Flatness of \(\Spec\varphi\) is flatness of \(K_2\) as a \(K_1\)-module, and every
  module over a field is flat (free). Surjectivity: \(\Spec K_1\) is a one-point space
  and \(\Spec K_2\) is nonempty (as \(K_2 \neq 0\)), so the unique point is hit. Each of
  the three properties --- flatness, affineness, surjectivity --- is stable under base
  change of schemes, and the transition square
  (\ref{thm:isPullback_baseFieldTransition}) exhibits \(\pi\) as a base change of
  \(\Spec\varphi\); so all three transport to \(\pi\).
\end{proof}

\begin{lemma}[Generic points under surjective morphisms]
  \label{lem:genericPoint_eq_of_surjective}
  \lean{AlgebraicGeometry.genericPoint_eq_of_surjective}
  \leanok
  A surjective morphism \(f : X \to Y\) of schemes with irreducible underlying spaces
  maps the generic point to the generic point: \(f(\eta_X) = \eta_Y\).
\end{lemma}
\begin{proof}
  \leanok
  Choose \(z \in X\) with \(f(z) = \eta_Y\). The generic point \(\eta_X\) specialises to
  every point of \(X\), in particular \(\eta_X \rightsquigarrow z\); applying the
  continuous map \(f\) gives \(f(\eta_X) \rightsquigarrow \eta_Y\). Conversely
  \(\eta_Y\) specialises to every point of \(Y\), so
  \(\eta_Y \rightsquigarrow f(\eta_X)\). The underlying space of a scheme is sober,
  hence \(T_0\), so the two specialisations force \(f(\eta_X) = \eta_Y\).
\end{proof}

\begin{lemma}[The transition matches generic points]
  \label{lem:baseFieldTransition_genericPoint}
  \lean{AlgebraicGeometry.baseFieldTransition_genericPoint}
  \uses{lem:genericPoint_eq_of_surjective, lem:baseFieldTransition_flat_affine_surjective,
    thm:baseChangeCurve_integral}
  \leanok
  Let \(C\) be smooth of relative dimension one and geometrically irreducible over the
  field \(k\), and let \(K_1, K_2\) be field extensions of \(k\). Then the base-field
  transition satisfies \(\pi(\eta_{C_{K_2}}) = \eta_{C_{K_1}}\).
\end{lemma}
\begin{proof}
  \leanok
  Both base-changed curves are integral (\ref{thm:baseChangeCurve_integral}), in
  particular irreducible, and \(\pi\) is surjective
  (\ref{lem:baseFieldTransition_flat_affine_surjective}); apply
  \ref{lem:genericPoint_eq_of_surjective}.
\end{proof}

\begin{definition}[Pullback of rational functions]
  \label{def:functionFieldMap}
  \lean{AlgebraicGeometry.Scheme.Hom.functionFieldMap,
    AlgebraicGeometry.Scheme.Hom.functionFieldMapUnits,
    AlgebraicGeometry.Scheme.Hom.coe_functionFieldMapUnits}
  \leanok
  Let \(f : X \to Y\) be a morphism of schemes with irreducible underlying spaces such
  that \(f(\eta_X) = \eta_Y\). The \emph{function-field map}
  \[
    f^{\sharp} : K(Y) \longrightarrow K(X)
  \]
  is the stalk map of \(f\) at \(\eta_X\), preceded by the canonical identification of
  the stalk of \(Y\) at \(f(\eta_X)\) with the stalk at \(\eta_Y\). It induces a group
  homomorphism \(K(Y)^{\times} \to K(X)^{\times}\) on units. For the base-field
  transition (with \ref{lem:baseFieldTransition_genericPoint} matching the generic
  points) this is the pullback of rational functions
  \(\pi^{\sharp} : K(C_{K_1}) \to K(C_{K_2})\).
\end{definition}

\begin{lemma}[Germ naturality and injectivity of the function-field map]
  \label{lem:functionFieldMap_germ}
  \lean{AlgebraicGeometry.Scheme.Hom.functionFieldMap_germ,
    AlgebraicGeometry.Scheme.Hom.functionFieldMap_injective}
  \uses{def:functionFieldMap}
  \leanok
  In the setting of \ref{def:functionFieldMap}: for an open \(U \subseteq Y\) containing
  \(\eta_Y\) and a section \(s \in \Gamma(Y, U)\),
  \[
    f^{\sharp}\bigl(\mathrm{germ}_{\eta_Y}(s)\bigr)
      \;=\; \mathrm{germ}_{\eta_X}\bigl(f^{\sharp}s\bigr)
      \qquad \text{in } K(X),
  \]
  where \(f^{\sharp}s \in \Gamma(X, f^{-1}U)\) is the pullback of the section (note
  \(\eta_X \in f^{-1}U\) since \(f(\eta_X) = \eta_Y \in U\)). If moreover \(X\) and
  \(Y\) are integral, the function-field map is injective.
\end{lemma}
\begin{proof}
  \leanok
  Germ naturality: the stalk identification carries \(\mathrm{germ}_{\eta_Y}(s)\) to the
  germ of \(s\) at the point \(f(\eta_X) \in U\), and the stalk map of \(f\) at a point
  sends the germ of a section to the germ of its pullback --- the defining compatibility
  of the stalk map with germs. Injectivity: on integral schemes both function fields are
  fields, and a ring homomorphism out of a field is injective.
\end{proof}

\begin{theorem}[Base change of sections along the transition, pushout form]
  \label{thm:isPushout_transitionSections}
  \lean{AlgebraicGeometry.Over.isPushout_transitionSections_of_isAffineOpen}
  \uses{thm:isPullback_baseFieldTransition}
  \leanok
  Let \(K_1, K_2\) be field extensions of \(k\), \(\varphi : K_1 \to K_2\) a
  \(k\)-algebra homomorphism, and \(V \subseteq C_{K_1}\) an \emph{affine} open. The
  square of section rings
  \[
    \begin{array}{ccc}
      \Gamma(\Spec K_1, \top) & \xrightarrow{\ \mathrm{pr}_2^{\sharp}\ } &
        \Gamma(C_{K_1}, V) \\
      \downarrow (\Spec\varphi)^{\sharp} & & \downarrow \pi^{\sharp} \\
      \Gamma(\Spec K_2, \top) & \xrightarrow{\ \mathrm{pr}_2^{\sharp}\ } &
        \Gamma\bigl(C_{K_2},\, \pi^{-1}V\bigr)
    \end{array}
  \]
  is a pushout of commutative rings. No flatness enters in the affine case.
\end{theorem}
\begin{proof}
  \leanok
  Restrict the transition square (\ref{thm:isPullback_baseFieldTransition}) over the
  affine opens: \(\pi^{-1}V\) is the fibre product \(V \times_{\Spec K_1} \Spec K_2\) of
  the open subscheme \(V\), a fibre product of affine schemes, hence affine with
  \(\Gamma(\pi^{-1}V) = \Gamma(V) \otimes_{\Gamma(\Spec K_1)} \Gamma(\Spec K_2)\):
  \(\Spec\) converts pushouts of commutative rings into fibre products of affine
  schemes. The four maps of the displayed square are the section-level maps of that
  restricted square, so the square is the tensor-product pushout.
\end{proof}

\begin{definition}[The second-projection algebra structure on sections]
  \label{def:baseChangeSectionsAlgebra}
  \lean{AlgebraicGeometry.baseChangeBundle, AlgebraicGeometry.baseChangeSectionsAlgebra,
    AlgebraicGeometry.ofHom_algebraMap_baseChangeSections}
  \uses{thm:baseChangeCurve_bundle}
  \leanok
  Let \(K/k\) be a field extension and \(V \subseteq C_K\) an open. The base-changed
  curve, bundled over \(\Spec K\) by its second projection
  (\ref{thm:baseChangeCurve_bundle}), endows \(\Gamma(C_K, V)\) with a \(K\)-algebra
  structure: the structure map is the pullback of global sections of \(\Spec K\) along
  \(\mathrm{pr}_2\), followed by restriction to \(V\),
  \[
    K \;=\; \Gamma(\Spec K, \top) \xrightarrow{\ \mathrm{pr}_2^{\sharp}\ }
      \Gamma(C_K, V).
  \]
  All \(K\)-linear statements about sections of \(C_K\) below refer to this structure.
\end{definition}

\begin{lemma}[Restriction of sections is \(K\)-algebraic]
  \label{lem:baseChangeResAlgHom}
  \lean{AlgebraicGeometry.ofHom_algebraMap_baseChangeSections_comp_res,
    AlgebraicGeometry.baseChangeResAlgHom, AlgebraicGeometry.baseChangeResAlgHom_apply}
  \uses{def:baseChangeSectionsAlgebra}
  \leanok
  For opens \(W \le V\) of \(C_K\), the structure maps of
  \ref{def:baseChangeSectionsAlgebra} intertwine restriction --- restricting the
  pullback of a constant is the pullback of the constant --- so restriction
  \(\Gamma(C_K, V) \to \Gamma(C_K, W)\) is a homomorphism of \(K\)-algebras.
\end{lemma}
\begin{proof}
  \leanok
  Both maps \(K \to \Gamma(C_K, W)\) --- structure map of \(W\), and structure map of
  \(V\) followed by restriction --- are the pullback of global sections of \(\Spec K\)
  along \(\mathrm{pr}_2\) restricted to \(W\), since pullback of sections commutes with
  restriction. A ring homomorphism commuting with the structure maps is a map of
  \(K\)-algebras.
\end{proof}

\begin{theorem}[The algebra-corner pushout square]
  \label{thm:isPushout_algebraMap_transitionSections}
  \lean{AlgebraicGeometry.Over.isPushout_algebraMap_transitionSections}
  \uses{thm:isPushout_transitionSections, def:baseChangeSectionsAlgebra}
  \leanok
  In the setting of \ref{thm:isPushout_transitionSections}, the square
  \[
    \begin{array}{ccc}
      K_1 & \longrightarrow & \Gamma(C_{K_1}, V) \\
      \downarrow \varphi & & \downarrow \pi^{\sharp} \\
      K_2 & \longrightarrow & \Gamma\bigl(C_{K_2},\, \pi^{-1}V\bigr)
    \end{array}
  \]
  --- top and bottom the structure maps of the second-projection algebra structures
  (\ref{def:baseChangeSectionsAlgebra}), left the homomorphism \(\varphi\) itself --- is
  a pushout of commutative rings. It is stated for an arbitrary \(k\)-algebra
  homomorphism \(\varphi\); no \(K_1\)-algebra structure on \(K_2\) is chosen.
\end{theorem}
\begin{proof}
  \leanok
  Identify the corners \(\Gamma(\Spec K_i, \top) = K_i\) of the pushout square of
  \ref{thm:isPushout_transitionSections} by the canonical isomorphisms. Under these, the
  left edge \((\Spec\varphi)^{\sharp}\) becomes \(\varphi\) (naturality of the
  identification in the ring), and the two horizontal edges become the structure maps of
  \ref{def:baseChangeSectionsAlgebra}. A square isomorphic to a pushout square is a
  pushout square.
\end{proof}

\begin{definition}[Sections base change along the base-field transition]
  \label{def:transitionSectionsBaseChange}
  \lean{AlgebraicGeometry.Over.transitionSectionsBaseChangeIso,
    AlgebraicGeometry.Over.transitionSectionsBaseChange}
  \uses{thm:isPushout_algebraMap_transitionSections, def:baseChangeSectionsAlgebra}
  \leanok
  Let \(K_1 \subseteq K_2\) be a tower of field extensions of \(k\) (that is, a
  \(K_1\)-algebra structure on \(K_2\) compatible with the \(k\)-structures), with
  \(\varphi\) the inclusion, and let \(V \subseteq C_{K_1}\) be an affine open. There is
  an isomorphism of rings
  \[
    \Gamma(C_{K_1}, V) \otimes_{K_1} K_2 \;\cong\;
      \Gamma\bigl(C_{K_2},\, \pi^{-1}V\bigr),
  \]
  the \(K_1\)-module structure on \(\Gamma(C_{K_1}, V)\) being the second-projection one
  (\ref{def:baseChangeSectionsAlgebra}).
\end{definition}
\begin{proof}
  \leanok
  The tensor product \(\Gamma(C_{K_1}, V) \otimes_{K_1} K_2\) with its two canonical
  maps is a pushout of the same span \(K_1 \to \Gamma(C_{K_1}, V)\), \(K_1 \to K_2\)
  --- the tensor product of commutative algebras is their pushout --- as the square of
  \ref{thm:isPushout_algebraMap_transitionSections}. Two pushouts of one span are
  canonically isomorphic under the corners.
\end{proof}

\begin{lemma}[The base change on pure tensors]
  \label{lem:transitionSectionsBaseChange_tmul}
  \lean{AlgebraicGeometry.Over.transitionSectionsBaseChange_tmul_one,
    AlgebraicGeometry.Over.transitionSectionsBaseChange_one_tmul,
    AlgebraicGeometry.Over.transitionSectionsBaseChange_tmul}
  \uses{def:transitionSectionsBaseChange}
  \leanok
  The isomorphism of \ref{def:transitionSectionsBaseChange} sends
  \[
    s \otimes 1 \longmapsto \pi^{\sharp}(s), \qquad
    1 \otimes a \longmapsto \mathrm{pr}_2^{\sharp}(a), \qquad
    s \otimes a \longmapsto \pi^{\sharp}(s) \cdot \mathrm{pr}_2^{\sharp}(a),
  \]
  for \(s \in \Gamma(C_{K_1}, V)\) and \(a \in K_2\).
\end{lemma}
\begin{proof}
  \leanok
  The comparison isomorphism of two pushouts of one span commutes with the two
  coprojections. On the tensor-product side the coprojections are \(s \mapsto s \otimes
  1\) and \(a \mapsto 1 \otimes a\); on the sections side they are \(\pi^{\sharp}\) and
  \(\mathrm{pr}_2^{\sharp}\) (\ref{thm:isPushout_algebraMap_transitionSections}). This
  gives the first two rules, and the third follows since \(s \otimes a = (s \otimes 1)
  \cdot (1 \otimes a)\) and the comparison is a ring homomorphism.
\end{proof}

\begin{lemma}[Naturality of the base change in the open]
  \label{lem:transitionSectionsBaseChange_naturality}
  \lean{AlgebraicGeometry.Over.transitionSectionsBaseChange_naturality}
  \uses{def:transitionSectionsBaseChange, lem:transitionSectionsBaseChange_tmul,
    lem:baseChangeResAlgHom}
  \leanok
  For affine opens \(W \le V\) of \(C_{K_1}\), restricting the base-changed section is
  base-changing the restriction: the square
  \[
    \begin{array}{ccc}
      \Gamma(C_{K_1}, V) \otimes_{K_1} K_2 & \cong &
        \Gamma\bigl(C_{K_2},\, \pi^{-1}V\bigr) \\
      \downarrow \mathrm{res} \otimes \mathrm{id} & & \downarrow \mathrm{res} \\
      \Gamma(C_{K_1}, W) \otimes_{K_1} K_2 & \cong &
        \Gamma\bigl(C_{K_2},\, \pi^{-1}W\bigr)
    \end{array}
  \]
  commutes, the left vertical being the (\(K_1\)-algebraic,
  \ref{lem:baseChangeResAlgHom}) restriction tensored with the identity of \(K_2\).
\end{lemma}
\begin{proof}
  \leanok
  Both composites are additive, so it suffices to compare them on a pure tensor
  \(s \otimes a\). By \ref{lem:transitionSectionsBaseChange_tmul} the top-right composite
  gives \(\bigl(\pi^{\sharp}(s) \cdot \mathrm{pr}_2^{\sharp}(a)\bigr)|_{\pi^{-1}W} =
  \pi^{\sharp}(s)|_{\pi^{-1}W} \cdot \mathrm{pr}_2^{\sharp}(a)|_{\pi^{-1}W}\)
  (restriction is a ring homomorphism), while the left-bottom composite gives
  \(\pi^{\sharp}(s|_W) \cdot \mathrm{pr}_2^{\sharp}(a)\) read over \(\pi^{-1}W\). These
  agree because pullback of sections commutes with restriction on both factors.
\end{proof}

\section{Two-lattice pairs and their cohomology}
\label{sec:two_lattice_pairs}

The remaining sections of this chapter build the module-level core of the two-term
pushforward engine. All schemes disappear: a \emph{two-lattice pair} axiomatises, in pure
commutative algebra, exactly the data that an affine two-cover extracts from a
quasi-coherent sheaf --- the two chart section modules, the overlap module, the two chart
coordinates, and the two restriction maps, each exhibiting the overlap as a localization
of its chart (the module counterpart of denominator clearing and annihilation on affine
opens, \ref{lem:denominator_clearing} and \ref{lem:section_annihilation}). The \v{C}ech
complex of the two-cover (\ref{def:TwoCover_diff}, \ref{def:TwoCover_H1Cok}) becomes a
two-term complex of modules; this section studies its cohomology in degrees zero and one
and its functoriality, the next section proves the six-term exact sequence of a short
exact sequence of pairs, and the following two sections compute the line-bundle models on
the two-chart projective line and deduce the coherence theorems: finiteness of \(H^1\)
over an \emph{arbitrary} commutative base ring, and of \(H^0\) over a Noetherian one. The
fibrewise Nakayama arguments and the split-rigidity theorems of
Chapter~\ref{chap:Algebra} (Sections~\ref{sec:nakayama_vanishing}
and~\ref{sec:split_rigidity}) consume the finiteness produced here.

Throughout, \(R\) is a commutative ring.

\begin{definition}[Two-lattice pair]
  \label{def:twoLatticePair}
  \lean{TwoLatticePair}
  \leanok
  A \emph{two-lattice pair} \(P\) over \(R\) consists of:
  \begin{itemize}
    \item \(R\)-modules \(M_0\), \(M_1\) (the \emph{chart lattices}) and \(N\) (the
      \emph{overlap module});
    \item \(R\)-linear endomorphisms \(t_0\) of \(M_0\) and \(t_1\) of \(M_1\) (the
      \emph{coordinate actions}) and an \emph{invertible} \(R\)-linear endomorphism
      \(u\) of \(N\);
    \item \(R\)-linear maps \(\iota_0 : M_0 \to N\) and \(\iota_1 : M_1 \to N\) (the
      \emph{restrictions to the overlap}) intertwining the actions:
      \(\iota_0(t_0 x) = u(\iota_0 x)\) for all \(x \in M_0\) and
      \(\iota_1(t_1 y) = u^{-1}(\iota_1 y)\) for all \(y \in M_1\);
  \end{itemize}
  subject to the localization axioms:
  \begin{enumerate}
    \item \emph{denominator clearing}: every \(n \in N\) admits an integer \(m \ge 0\)
      and \(x \in M_0\) with \(u^m n = \iota_0 x\), and an integer \(m' \ge 0\) and
      \(y \in M_1\) with \(u^{-m'} n = \iota_1 y\);
    \item \emph{annihilation}: if \(\iota_0 x = 0\) then \(t_0^m x = 0\) for some
      \(m \ge 0\), and if \(\iota_1 y = 0\) then \(t_1^m y = 0\) for some \(m \ge 0\).
  \end{enumerate}
  Regarding \(M_0\) and \(N\) as modules over the polynomial ring \(R[t]\), with \(t\)
  acting as \(t_0\) on \(M_0\) and as \(u\) on \(N\), the three conditions ---
  invertibility of \(u\) on \(N\), clearing, annihilation --- say precisely that
  \(\iota_0\) exhibits \(N\) as the localization of \(M_0\) at the powers of \(t\);
  likewise \(\iota_1\) exhibits \(N\) as the localization of \(M_1\) at the powers of
  \(t\), for the structures through \(t_1\) and \(u^{-1}\). In the geometric application
  \(M_0, M_1\) are the sections of a quasi-coherent sheaf on the two charts of an affine
  two-cover, \(N\) its sections on the overlap, and \(t_0, t_1\) the two chart
  coordinates, mutually inverse on the overlap.
\end{definition}

\begin{definition}[The two-term complex of a pair]
  \label{def:twoLattice_diff}
  \lean{TwoLatticePair.diff}
  \uses{def:twoLatticePair}
  \leanok
  The \emph{difference map} of a two-lattice pair \(P\) is the \(R\)-linear map
  \[
    \delta_P : M_0 \times M_1 \longrightarrow N, \qquad
    \delta_P(x, y) \;=\; \iota_0 x - \iota_1 y .
  \]
  The two-term complex \(M_0 \times M_1 \xrightarrow{\ \delta_P\ } N\) is the module
  avatar of the two-cover \v{C}ech complex.
\end{definition}

\begin{definition}[\(H^0\) of a pair]
  \label{def:twoLattice_H0}
  \lean{TwoLatticePair.H0}
  \uses{def:twoLattice_diff}
  \leanok
  The degree-zero cohomology of the pair \(P\) is the kernel of the difference map,
  \[
    H^0(P) \;=\; \ker \delta_P
    \;=\; \{\, (x, y) \in M_0 \times M_1 : \iota_0 x = \iota_1 y \,\},
  \]
  an \(R\)-submodule of \(M_0 \times M_1\): the pairs of chart sections agreeing on the
  overlap.
\end{definition}

\begin{definition}[\(H^1\) of a pair]
  \label{def:twoLattice_H1}
  \lean{TwoLatticePair.H1, TwoLatticePair.imageLattice, TwoLatticePair.h1Mk}
  \uses{def:twoLatticePair}
  \leanok
  The \emph{image lattice} of the pair \(P\) is the \(R\)-submodule
  \(Q(P) = \iota_0(M_0) + \iota_1(M_1) \subseteq N\), and the degree-one cohomology of
  \(P\) is the quotient
  \[
    H^1(P) \;=\; N \big/ Q(P),
  \]
  with quotient projection \(N \twoheadrightarrow H^1(P)\), \(n \mapsto [n]\).
\end{definition}

\begin{lemma}[\(H^1\) is the cokernel of the difference map]
  \label{lem:twoLattice_range_diff}
  \lean{TwoLatticePair.range_diff_eq}
  \uses{def:twoLattice_diff, def:twoLattice_H1}
  \leanok
  The image of \(\delta_P\) is the image lattice: \(\delta_P(M_0 \times M_1) = Q(P)\).
  In particular \(H^1(P)\) is the cokernel of \(\delta_P\), so \(H^0(P)\) and \(H^1(P)\)
  are the two cohomology modules of the two-term complex of \ref{def:twoLattice_diff}.
\end{lemma}
\begin{proof}
  \leanok
  Each value \(\delta_P(x,y) = \iota_0 x - \iota_1 y\) is a difference of an element of
  \(\iota_0(M_0)\) and an element of \(\iota_1(M_1)\), hence lies in \(Q(P)\).
  Conversely \(\iota_0 x = \delta_P(x, 0)\) and \(\iota_1 y = \delta_P(0, -y)\), so both
  summands of \(Q(P)\) lie in the image, and the image is a submodule.
\end{proof}

\begin{definition}[Map of two-lattice pairs]
  \label{def:twoLattice_hom}
  \lean{TwoLatticePair.Hom}
  \uses{def:twoLatticePair}
  \leanok
  A \emph{map of two-lattice pairs} \(f : P \to P'\) is a triple of \(R\)-linear maps
  \(f_0 : M_0 \to M_0'\), \(f_1 : M_1 \to M_1'\), \(f_N : N \to N'\) commuting with the
  coordinate actions and the restrictions:
  \[
    f_0 \circ t_0 = t_0' \circ f_0, \quad
    f_1 \circ t_1 = t_1' \circ f_1, \quad
    f_N \circ u = u' \circ f_N, \quad
    f_N \circ \iota_0 = \iota_0' \circ f_0, \quad
    f_N \circ \iota_1 = \iota_1' \circ f_1 .
  \]
  Compatibility with the \emph{inverse} overlap action is automatic: applying the
  \(u\)-compatibility to \(u^{-1} n\) gives \(f_N(n) = u'\bigl(f_N(u^{-1} n)\bigr)\),
  whence \(f_N(u^{-1} n) = u'^{-1}(f_N n)\).
\end{definition}

\begin{lemma}[Naturality of the difference map]
  \label{lem:twoLattice_diff_natural}
  \lean{TwoLatticePair.Hom.diff_comm}
  \uses{def:twoLattice_hom, def:twoLattice_diff}
  \leanok
  For a map of pairs \(f : P \to P'\) and \((x, y) \in M_0 \times M_1\),
  \[
    \delta_{P'}\bigl(f_0 x, f_1 y\bigr) \;=\; f_N\bigl(\delta_P(x, y)\bigr) .
  \]
\end{lemma}
\begin{proof}
  \leanok
  Expand both sides:
  \(\delta_{P'}(f_0 x, f_1 y) = \iota_0'(f_0 x) - \iota_1'(f_1 y)
  = f_N(\iota_0 x) - f_N(\iota_1 y) = f_N(\iota_0 x - \iota_1 y)\), using the two
  restriction compatibilities and linearity of \(f_N\).
\end{proof}

\begin{definition}[The induced map on \(H^0\)]
  \label{def:twoLattice_h0Map}
  \lean{TwoLatticePair.Hom.h0Map}
  \uses{def:twoLattice_hom, def:twoLattice_H0}
  \leanok
  A map of pairs \(f : P \to P'\) induces an \(R\)-linear map
  \(H^0(f) : H^0(P) \to H^0(P')\), \((x, y) \mapsto (f_0 x, f_1 y)\).
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_diff_natural}
  If \(\delta_P(x,y) = 0\) then
  \(\delta_{P'}(f_0 x, f_1 y) = f_N(\delta_P(x,y)) = 0\) by naturality
  (\ref{lem:twoLattice_diff_natural}), so the restriction of \(f_0 \times f_1\) to
  \(H^0(P)\) lands in \(H^0(P')\); it is \(R\)-linear as a restriction of an \(R\)-linear
  map.
\end{proof}

\begin{definition}[The induced map on \(H^1\)]
  \label{def:twoLattice_h1Map}
  \lean{TwoLatticePair.Hom.h1Map}
  \uses{def:twoLattice_hom, def:twoLattice_H1}
  \leanok
  A map of pairs \(f : P \to P'\) induces an \(R\)-linear map
  \(H^1(f) : H^1(P) \to H^1(P')\), \([n] \mapsto [f_N n]\).
\end{definition}
\begin{proof}
  \leanok
  \(f_N\) carries the image lattice into the image lattice:
  \(f_N(\iota_0 x) = \iota_0'(f_0 x)\) and \(f_N(\iota_1 y) = \iota_1'(f_1 y)\), so
  \(f_N(Q(P)) \subseteq Q(P')\) and \(f_N\) descends to the quotients.
\end{proof}

\begin{lemma}[Right exactness of \(H^1\) in the pair]
  \label{lem:twoLattice_h1Map_surjective}
  \lean{TwoLatticePair.Hom.h1Map_surjective}
  \uses{def:twoLattice_h1Map}
  \leanok
  If a map of pairs \(f : P \to P'\) is surjective on overlap modules, then
  \(H^1(f) : H^1(P) \to H^1(P')\) is surjective.
\end{lemma}
\begin{proof}
  \leanok
  A class in \(H^1(P')\) is \([n']\) for some \(n' \in N'\); write \(n' = f_N(n)\) by
  surjectivity; then \(H^1(f)[n] = [f_N n] = [n']\).
\end{proof}

\section{The six-term exact sequence of two-lattice pairs}
\label{sec:two_lattice_sixterm}

A short exact sequence of two-lattice pairs induces the entire long exact cohomology
sequence of the two-term complexes; since a two-term complex has no cohomology beyond
degree one, the sequence has six terms and closes on both ends:
\[
  0 \to H^0(P) \to H^0(P') \to H^0(P'')
    \xrightarrow{\ \partial\ } H^1(P) \to H^1(P') \to H^1(P'') \to 0 .
\]
The connecting map and the six exactness statements are proved by explicit element
chases on the two-term complexes.

\begin{definition}[Short exact sequence of pairs]
  \label{def:twoLattice_shortExact}
  \lean{TwoLatticePair.IsShortExact}
  \uses{def:twoLattice_hom}
  \leanok
  A pair of maps of two-lattice pairs \(\varphi : P \to P'\) and \(\psi : P' \to P''\)
  is a \emph{short exact sequence} \(0 \to P \to P' \to P'' \to 0\) if it is
  componentwise short exact: on each of the three carriers (the two chart lattices and
  the overlap module), \(\varphi\) is injective, \(\psi\) is surjective, and the image
  of \(\varphi\) is the kernel of \(\psi\).
\end{definition}

\begin{definition}[The connecting homomorphism]
  \label{def:twoLattice_delta}
  \lean{TwoLatticePair.IsShortExact.delta, TwoLatticePair.IsShortExact.delta_apply}
  \uses{def:twoLattice_shortExact, def:twoLattice_H0, def:twoLattice_H1}
  \leanok
  For a short exact sequence \(0 \to P \xrightarrow{\varphi} P' \xrightarrow{\psi}
  P'' \to 0\) of two-lattice pairs, the \emph{connecting homomorphism}
  \[
    \partial : H^0(P'') \longrightarrow H^1(P)
  \]
  is the \(R\)-linear map characterized by: whenever \(z = (z_0, z_1) \in H^0(P'')\),
  \(e_0 \in M_0'\) and \(e_1 \in M_1'\) satisfy \(\psi_0 e_0 = z_0\) and
  \(\psi_1 e_1 = z_1\), and \(n \in N\) satisfies
  \(\varphi_N n = \delta_{P'}(e_0, e_1)\), then \(\partial z = [n]\).
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_diff_natural, lem:twoLattice_range_diff}
  \emph{Existence of the chase data.} Given \(z \in H^0(P'')\), componentwise
  surjectivity of \(\psi\) provides lifts \(e_0, e_1\). Then
  \(\psi_N\bigl(\delta_{P'}(e_0,e_1)\bigr) = \delta_{P''}(\psi_0 e_0, \psi_1 e_1)
  = \delta_{P''}(z) = 0\) by naturality (\ref{lem:twoLattice_diff_natural}) and
  \(z \in H^0(P'')\), so \(\delta_{P'}(e_0,e_1)\) lies in \(\ker \psi_N =
  \varphi_N(N)\), and \(n\) exists; it is unique because \(\varphi_N\) is injective.

  \emph{Independence of the lifts.} If \(e_0', e_1'\) is a second componentwise lift of
  \(z\), with \(\varphi_N n' = \delta_{P'}(e_0', e_1')\), then
  \(\psi_0(e_0' - e_0) = 0\) and \(\psi_1(e_1' - e_1) = 0\), so by componentwise
  exactness \(e_0' - e_0 = \varphi_0 a\) and \(e_1' - e_1 = \varphi_1 b\) for some
  \(a \in M_0\), \(b \in M_1\). Then
  \[
    \varphi_N(n' - n) \;=\; \delta_{P'}(\varphi_0 a, \varphi_1 b)
    \;=\; \varphi_N\bigl(\delta_P(a, b)\bigr)
  \]
  by naturality, and injectivity of \(\varphi_N\) gives
  \(n' - n = \delta_P(a,b) \in Q(P)\) (\ref{lem:twoLattice_range_diff}); hence
  \([n'] = [n]\) in \(H^1(P)\).

  \emph{Linearity.} The chase data may be chosen additively --- lifts of a sum as the
  sum of lifts, and similarly for scalar multiples --- and \(n\) depends linearly on
  the chosen data; since the class \([n]\) is independent of the choices, \(\partial\)
  is \(R\)-linear.
\end{proof}

\begin{theorem}[Six-term exactness, left end]
  \label{thm:twoLattice_h0Map_injective}
  \lean{TwoLatticePair.IsShortExact.h0Map_injective}
  \uses{def:twoLattice_shortExact, def:twoLattice_h0Map}
  \leanok
  For a short exact sequence \(0 \to P \xrightarrow{\varphi} P' \xrightarrow{\psi}
  P'' \to 0\), the map \(H^0(\varphi) : H^0(P) \to H^0(P')\) is injective.
\end{theorem}
\begin{proof}
  \leanok
  \(H^0(\varphi)\) acts componentwise as \((\varphi_0, \varphi_1)\), and both
  \(\varphi_0\) and \(\varphi_1\) are injective.
\end{proof}

\begin{theorem}[Six-term exactness at \(H^0(P')\)]
  \label{thm:twoLattice_exact_h0_middle}
  \lean{TwoLatticePair.IsShortExact.range_h0Map_eq_ker_h0Map}
  \uses{def:twoLattice_shortExact, def:twoLattice_h0Map}
  \leanok
  In the situation of \ref{thm:twoLattice_h0Map_injective}, the image of
  \(H^0(\varphi)\) equals the kernel of \(H^0(\psi)\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_diff_natural}
  \(\subseteq\): \(\psi \circ \varphi\) vanishes componentwise (image of \(\varphi\)
  inside kernel of \(\psi\)), so \(H^0(\psi) \circ H^0(\varphi) = 0\).
  \(\supseteq\): let \((z_0, z_1) \in H^0(P')\) with \(\psi_0 z_0 = 0\) and
  \(\psi_1 z_1 = 0\). By componentwise exactness \(z_0 = \varphi_0 a\) and
  \(z_1 = \varphi_1 b\). The pair \((a, b)\) lies in \(H^0(P)\): by naturality
  (\ref{lem:twoLattice_diff_natural})
  \(\varphi_N\bigl(\delta_P(a,b)\bigr) = \delta_{P'}(z_0, z_1) = 0\), and
  \(\varphi_N\) is injective. Then \(H^0(\varphi)(a, b) = (z_0, z_1)\).
\end{proof}

\begin{theorem}[Six-term exactness at \(H^0(P'')\)]
  \label{thm:twoLattice_exact_h0_delta}
  \lean{TwoLatticePair.IsShortExact.range_h0Map_eq_ker_delta}
  \uses{def:twoLattice_delta, def:twoLattice_h0Map}
  \leanok
  In the situation of \ref{thm:twoLattice_h0Map_injective}, the image of
  \(H^0(\psi)\) equals the kernel of the connecting homomorphism \(\partial\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_range_diff, lem:twoLattice_diff_natural}
  \(\subseteq\): for \(z = H^0(\psi)(w)\) with \(w \in H^0(P')\), take the components
  of \(w\) themselves as the lifts in the characterization of \(\partial\)
  (\ref{def:twoLattice_delta}); their difference is \(\delta_{P'}(w) = 0 =
  \varphi_N(0)\), so \(\partial z = [0] = 0\).
  \(\supseteq\): let \(z \in H^0(P'')\) with \(\partial z = 0\); choose lifts
  \(e_0, e_1\) and \(n\) with \(\varphi_N n = \delta_{P'}(e_0, e_1)\), so that
  \(\partial z = [n]\). Vanishing of \([n]\) means \(n \in Q(P) =
  \delta_P(M_0 \times M_1)\) (\ref{lem:twoLattice_range_diff}); write
  \(n = \delta_P(a, b)\). Then \(w := (e_0 - \varphi_0 a,\, e_1 - \varphi_1 b)\)
  satisfies
  \(\delta_{P'}(w) = \delta_{P'}(e_0,e_1) - \varphi_N(\delta_P(a,b)) = 0\)
  by naturality, so \(w \in H^0(P')\); and since \(\psi\circ\varphi = 0\)
  componentwise, \(H^0(\psi)(w) = (\psi_0 e_0, \psi_1 e_1) = z\).
\end{proof}

\begin{theorem}[Six-term exactness at \(H^1(P)\)]
  \label{thm:twoLattice_exact_delta_h1}
  \lean{TwoLatticePair.IsShortExact.range_delta_eq_ker_h1Map}
  \uses{def:twoLattice_delta, def:twoLattice_h1Map}
  \leanok
  In the situation of \ref{thm:twoLattice_h0Map_injective}, the image of the
  connecting homomorphism \(\partial\) equals the kernel of \(H^1(\varphi)\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_range_diff, lem:twoLattice_diff_natural}
  \(\subseteq\): if \(\partial z = [n]\) with \(\varphi_N n = \delta_{P'}(e_0, e_1)\),
  then \(H^1(\varphi)[n] = [\varphi_N n] = [\delta_{P'}(e_0,e_1)] = 0\), the class of
  an element of the image lattice (\ref{lem:twoLattice_range_diff}).
  \(\supseteq\): let \([n] \in H^1(P)\) with \(H^1(\varphi)[n] = 0\), i.e.\
  \(\varphi_N n \in Q(P') = \delta_{P'}(M_0' \times M_1')\); write
  \(\varphi_N n = \delta_{P'}(e_0, e_1)\). Then
  \(z := (\psi_0 e_0, \psi_1 e_1)\) lies in \(H^0(P'')\):
  \(\delta_{P''}(z) = \psi_N\bigl(\delta_{P'}(e_0,e_1)\bigr) = \psi_N(\varphi_N n) = 0\)
  by naturality and \(\psi\circ\varphi = 0\). By the characterization of \(\partial\)
  (\ref{def:twoLattice_delta}), \(\partial z = [n]\).
\end{proof}

\begin{theorem}[Six-term exactness at \(H^1(P')\)]
  \label{thm:twoLattice_exact_h1_middle}
  \lean{TwoLatticePair.IsShortExact.range_h1Map_eq_ker_h1Map}
  \uses{def:twoLattice_shortExact, def:twoLattice_h1Map}
  \leanok
  In the situation of \ref{thm:twoLattice_h0Map_injective}, the image of
  \(H^1(\varphi)\) equals the kernel of \(H^1(\psi)\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_range_diff, lem:twoLattice_diff_natural}
  \(\subseteq\): \(H^1(\psi)\bigl(H^1(\varphi)[n]\bigr) = [\psi_N(\varphi_N n)] = 0\).
  \(\supseteq\): let \([n'] \in H^1(P')\) with \([\psi_N n'] = 0\), i.e.\
  \(\psi_N n' \in Q(P'') = \delta_{P''}(M_0'' \times M_1'')\); write
  \(\psi_N n' = \delta_{P''}(z_0, z_1)\) and lift \(z_0 = \psi_0 e_0\),
  \(z_1 = \psi_1 e_1\). Then
  \(\psi_N\bigl(n' - \delta_{P'}(e_0, e_1)\bigr) =
  \psi_N n' - \delta_{P''}(z_0, z_1) = 0\) by naturality, so by exactness on the
  overlap \(n' - \delta_{P'}(e_0,e_1) = \varphi_N w\) for some \(w \in N\). Since
  \([\delta_{P'}(e_0,e_1)] = 0\) in \(H^1(P')\) (\ref{lem:twoLattice_range_diff}),
  \([n'] = [\varphi_N w] = H^1(\varphi)[w]\).
\end{proof}

\begin{theorem}[Six-term exactness, right end]
  \label{thm:twoLattice_h1Map_surjective_ses}
  \lean{TwoLatticePair.IsShortExact.h1Map_surjective}
  \uses{def:twoLattice_shortExact, def:twoLattice_h1Map}
  \leanok
  In the situation of \ref{thm:twoLattice_h0Map_injective}, the map
  \(H^1(\psi) : H^1(P') \to H^1(P'')\) is surjective.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_h1Map_surjective}
  \(\psi\) is surjective on overlap modules; apply the right exactness of \(H^1\) in
  the pair (\ref{lem:twoLattice_h1Map_surjective}).
\end{proof}

\section{The line-bundle models and the finite surjection}
\label{sec:two_lattice_models}

The coherence theorems are proved by comparing an arbitrary pair with \emph{models}: the
two-lattice pairs of the direct sums \(\bigoplus_{i} \mathcal O(m_i)\) of line bundles on
the two-chart projective line over \(R\), whose cohomology is the classical monomial
window. Say a two-lattice pair \(P\) has \emph{finite lattices} if \(M_0\) is a finitely
generated module over the polynomial ring \(R[t]\), with \(t\) acting as \(t_0\), and
likewise \(M_1\) over \(R[t]\) through \(t_1\). Every pair with finite lattices receives
a componentwise surjection from a model --- the two-cover form of the finite free
approximation used by Mumford in the coherence dévissage on abelian varieties, here
terminating in one step because generation is measured over \(R[t]\) rather than over
\(R\).

\begin{definition}[The family line-bundle model]
  \label{def:twoLattice_model}
  \lean{TwoLatticePair.model}
  \uses{def:twoLatticePair}
  \leanok
  Let \(I\) be a finite index set and \(m : I \to \Z\) a family of twists. The
  \emph{model} \(E(m)\) is the two-lattice pair over \(R\) with chart lattices
  \(M_0 = M_1 = (R[t])^I\), overlap module \(N = (R[t, t^{-1}])^I\), coordinate actions
  \(t_0 = t_1 =\) componentwise multiplication by \(t\), invertible overlap action
  \(u =\) componentwise multiplication by \(t\), and restrictions
  \[
    \iota_0(p)_i \;=\; p_i(t), \qquad
    \iota_1(q)_i \;=\; t^{m_i} \cdot q_i\bigl(t^{-1}\bigr) ,
  \]
  the componentwise inclusion of polynomials into Laurent polynomials on the chart-0
  side, and the twisted substitution \(t \mapsto t^{-1}\) on the chart-1 side. It is
  the pair of the sheaf \(\bigoplus_{i \in I} \mathcal O(m_i)\) on the two standard
  charts of the projective line over \(R\).
\end{definition}
\begin{proof}
  \leanok
  The axioms of a two-lattice pair hold. \emph{Equivariance:} on the chart-0 side,
  multiplying a polynomial by \(t\) multiplies its Laurent image by \(t\); on the
  chart-1 side, \(t^{m_i} \cdot (t q)(t^{-1}) = t^{m_i} \cdot t^{-1} \cdot q(t^{-1})\),
  so \(\iota_1(t_1 q) = u^{-1}(\iota_1 q)\). \emph{Denominator clearing:} a Laurent
  vector \(n\) has finitely many components, each with exponents bounded below, so a
  single power \(u^M\) (componentwise multiplication by \(t^M\)) makes every component a
  polynomial and lands \(n\) in \(\iota_0\bigl((R[t])^I\bigr)\). Symmetrically, the
  exponents of each \(n_i\) are bounded above, say by \(D_i\); for any
  \(M' \ge \max_i (D_i - m_i)\) with \(M' \ge 0\), every exponent of
  \(t^{-M' - m_i}\, n_i\) is nonpositive, so there is a polynomial \(q_i\) with
  \(q_i(t^{-1}) = t^{-M' - m_i}\, n_i\), and then
  \(\bigl(u^{-M'} n\bigr)_i = t^{-M'} n_i = t^{m_i}\, q_i(t^{-1})\), i.e.\
  \(u^{-M'} n = \iota_1(q)\). \emph{Annihilation:} both
  \(\iota_0\) and \(\iota_1\) are injective --- the inclusion of polynomials is
  injective, the substitution \(t \mapsto t^{-1}\) is an automorphism of the Laurent
  ring, and multiplication by the unit \(t^{m_i}\) is injective --- so a section
  vanishing on the overlap is already zero.
\end{proof}

\begin{theorem}[The monomial window: \(H^1\) of a model over any ring]
  \label{thm:moduleFinite_h1_model}
  \lean{TwoLatticePair.moduleFinite_h1_model}
  \uses{def:twoLattice_model, def:twoLattice_H1}
  \leanok
  \source{hartshorne-algebraic-geometry:page-0242, hartshorne-algebraic-geometry:page-0243}
  Let \(R\) be \emph{any} commutative ring, \(I\) finite and \(m : I \to \Z\). Then
  \(H^1\bigl(E(m)\bigr)\) is a finite \(R\)-module. (It is spanned by the classes of
  the monomials \(t^j\) in the components \(i\) with \(m_i < j < 0\) --- the classical
  negative-monomial window of the projective line.)
\end{theorem}
\begin{proof}
  \leanok
  \uses{cor:two_lattice_loc_pow}
  Apply the two-lattice finiteness ladder (\ref{cor:two_lattice_loc_pow}) with
  \(k = R\), the Laurent module \(N = (R[t,t^{-1}])^I\) --- finitely generated over
  \(R[t,t^{-1}]\), being free on \(I\) --- and the \(R\)-submodules
  \(Q_0 = \iota_0\bigl((R[t])^I\bigr)\), \(Q_1 = \iota_1\bigl((R[t])^I\bigr)\). \(Q_0\)
  is stable under multiplication by \(t\) and \(Q_1\) under multiplication by
  \(t^{-1}\), by the equivariance of \(\iota_0\) and \(\iota_1\)
  (\ref{def:twoLattice_model}); and every element of \(N\) is absorbed into \(Q_0\) by
  a large power of \(t\) and into \(Q_1\) by a large power of \(t^{-1}\), by the
  denominator-clearing axioms verified in \ref{def:twoLattice_model}. The ladder
  concludes that \(N/(Q_0 + Q_1) = H^1\bigl(E(m)\bigr)\) is a finite \(R\)-module.
\end{proof}

\begin{theorem}[The degree window: \(H^0\) of a model over a Noetherian ring]
  \label{thm:moduleFinite_h0_model}
  \lean{TwoLatticePair.moduleFinite_h0_model}
  \uses{def:twoLattice_model, def:twoLattice_H0}
  \leanok
  \source{hartshorne-algebraic-geometry:page-0242, hartshorne-algebraic-geometry:page-0243}
  Let \(R\) be a \emph{Noetherian} commutative ring, \(I\) finite and \(m : I \to \Z\).
  Then \(H^0\bigl(E(m)\bigr)\) is a finite \(R\)-module.
\end{theorem}
\begin{proof}
  \leanok
  A class in \(H^0(E(m))\) is a pair \((p, q)\) of polynomial vectors with
  \(p_i(t) = t^{m_i} q_i(t^{-1})\) in \(R[t,t^{-1}]\) for every \(i\). Comparing
  coefficients: the right side has no exponent above \(m_i\) (the exponents of
  \(q_i(t^{-1})\) are \(\le 0\)), so \(\deg p_i \le m_i\) --- in particular \(p_i = 0\)
  when \(m_i < 0\). Moreover the first component determines the class: \(\iota_1\) is
  injective (\ref{def:twoLattice_model}) and \(\iota_1 q = \iota_0 p\). Hence
  \(H^0(E(m))\) embeds \(R\)-linearly into
  \(\bigoplus_{i} \{\, p \in R[t] : \deg p \le m_i \,\}\), a finitely generated free
  \(R\)-module (of rank \(\sum_i \max(m_i + 1, 0)\)). A submodule of a finitely
  generated module over the Noetherian ring \(R\) is finitely generated.
\end{proof}

\begin{definition}[The Laurent action on the overlap module]
  \label{def:twoLattice_laurentToEnd}
  \lean{TwoLatticePair.laurentToEnd}
  \uses{def:twoLatticePair}
  \leanok
  For a two-lattice pair \(P\), the \(R\)-algebra homomorphism
  \[
    R[t, t^{-1}] \longrightarrow \operatorname{End}_R(N), \qquad t \longmapsto u ,
  \]
  extending the assignment \(t^j \mapsto u^j\) (\(j \in \Z\), negative powers through
  the inverse of \(u\)) by \(R\)-linearity. It exists because \(u\) is invertible, so
  \(j \mapsto u^j\) is a homomorphism from \(\Z\) to the units of
  \(\operatorname{End}_R(N)\), and the
  Laurent ring is the monoid algebra of \(\Z\) over \(R\). We write \(g(u)\) for the
  action of \(g \in R[t,t^{-1}]\) on \(N\).
\end{definition}

\begin{lemma}[The Laurent action intertwines the chart actions]
  \label{lem:twoLattice_laurent_intertwine}
  \lean{TwoLatticePair.laurentToEnd_toLaurent_ι₀,
    TwoLatticePair.laurentToEnd_invert_toLaurent_ι₁}
  \uses{def:twoLattice_laurentToEnd}
  \leanok
  For a polynomial \(g \in R[t]\), an element \(x \in M_0\) and an element
  \(y \in M_1\),
  \[
    g(u)\bigl(\iota_0 x\bigr) = \iota_0\bigl(g(t_0)\, x\bigr)
    \qquad\text{and}\qquad
    g\bigl(u^{-1}\bigr)\bigl(\iota_1 y\bigr) = \iota_1\bigl(g(t_1)\, y\bigr) ,
  \]
  where \(g(t_0)\) and \(g(t_1)\) denote the evaluations of \(g\) at the coordinate
  actions.
\end{lemma}
\begin{proof}
  \leanok
  Both sides are additive in \(g\), so it suffices to treat a monomial
  \(g = c\,t^k\). Iterating the equivariance \(\iota_0(t_0 x) = u(\iota_0 x)\) gives
  \(\iota_0(t_0^k x) = u^k(\iota_0 x)\), and multiplying by \(c\) gives the chart-0
  identity; iterating \(\iota_1(t_1 y) = u^{-1}(\iota_1 y)\) gives the chart-1
  identity with \(u^{-k}\).
\end{proof}

\begin{definition}[The model map determined by matched generators]
  \label{def:twoLattice_modelHom}
  \lean{TwoLatticePair.modelHom}
  \uses{def:twoLattice_model, def:twoLattice_hom, def:twoLattice_laurentToEnd}
  \leanok
  Let \(P\) be a two-lattice pair, \(I\) a finite index set, \(m : I \to \Z\), and let
  \(a : I \to M_0\) and \(b : I \to M_1\) be families whose overlap images match up to
  the twist:
  \[
    u^{m_i}\bigl(\iota_0 a_i\bigr) \;=\; \iota_1 b_i \qquad (i \in I).
  \]
  The \emph{model map} \(f : E(m) \to P\) is the map of pairs with components
  \[
    f_0(p) = \sum_{i \in I} p_i(t_0)\, a_i, \qquad
    f_1(q) = \sum_{i \in I} q_i(t_1)\, b_i, \qquad
    f_N(n) = \sum_{i \in I} n_i(u)\, \bigl(\iota_0 a_i\bigr) ,
  \]
  the polynomial actions on the generators on the charts and the Laurent action
  (\ref{def:twoLattice_laurentToEnd}) on their overlap images.
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:twoLattice_laurent_intertwine}
  The five compatibilities of a map of pairs (\ref{def:twoLattice_hom}) hold term by
  term. Compatibility with the coordinate actions: multiplying \(p_i\) (resp.\ \(q_i\),
  \(n_i\)) by \(t\) multiplies \(p_i(t_0)\) (resp.\ \(q_i(t_1)\), \(n_i(u)\)) by
  \(t_0\) (resp.\ \(t_1\), \(u\)), which is exactly the model action carried to \(P\).
  Compatibility with \(\iota_0\): for a polynomial vector \(p\),
  \(f_N(\iota_0 p) = \sum_i p_i(u)(\iota_0 a_i) = \sum_i \iota_0\bigl(p_i(t_0)a_i\bigr)
  = \iota_0(f_0 p)\) by the chart-0 intertwining
  (\ref{lem:twoLattice_laurent_intertwine}). Compatibility with \(\iota_1\): for a
  polynomial vector \(q\), the \(i\)-th term of \(f_N(\iota_1 q)\) is
  \(\bigl(t^{m_i} q_i(t^{-1})\bigr)(u)\,(\iota_0 a_i) =
  q_i(u^{-1})\Bigl(u^{m_i}(\iota_0 a_i)\Bigr) = q_i(u^{-1})(\iota_1 b_i)
  = \iota_1\bigl(q_i(t_1) b_i\bigr)\), using the matching hypothesis and the chart-1
  intertwining; summing gives \(f_N(\iota_1 q) = \iota_1(f_1 q)\).
\end{proof}

\begin{lemma}[Models have finite lattices]
  \label{lem:moduleFinite_aeval_model}
  \lean{TwoLatticePair.moduleFinite_aeval_model_t₀, TwoLatticePair.moduleFinite_aeval_model_t₁}
  \uses{def:twoLattice_model}
  \leanok
  The chart lattices of a model \(E(m)\) are finite: \((R[t])^I\), with \(t\) acting by
  componentwise multiplication, is a finitely generated \(R[t]\)-module.
\end{lemma}
\begin{proof}
  \leanok
  The \(R[t]\)-module structure through the coordinate action coincides with the
  standard one on the free module \((R[t])^I\), which is generated by the \(|I|\)
  standard basis vectors.
\end{proof}

\begin{theorem}[The finite model surjection]
  \label{thm:exists_hom_model_surjective}
  \lean{TwoLatticePair.exists_hom_model_surjective}
  \uses{def:twoLattice_modelHom}
  \leanok
  Let \(P\) be a two-lattice pair with finite lattices over a commutative ring \(R\).
  Then there exist a finite index set \(I\), twists \(m : I \to \Z\), and a map of
  pairs \(f : E(m) \to P\) surjective on the chart-0 lattice, on the chart-1 lattice,
  \emph{and} on the overlap module.
\end{theorem}
\begin{proof}
  \leanok
  \uses{def:twoLatticePair, lem:twoLattice_laurent_intertwine}
  Choose finite generating families \((a_j)_{j \in J_0}\) of \(M_0\) over \(R[t]\)
  (acting through \(t_0\)) and \((b_j)_{j \in J_1}\) of \(M_1\) over \(R[t]\) (through
  \(t_1\)). Match each generator across the overlap by denominator clearing
  (\ref{def:twoLatticePair}): for \(j \in J_0\) there are \(k_j \ge 0\) and
  \(y_j \in M_1\) with \(u^{-k_j}(\iota_0 a_j) = \iota_1 y_j\); set \(m_j = -k_j\), so
  \(u^{m_j}(\iota_0 a_j) = \iota_1 y_j\). For \(j \in J_1\) there are \(k_j \ge 0\) and
  \(x_j \in M_0\) with \(u^{k_j}(\iota_1 b_j) = \iota_0 x_j\); set \(m_j = -k_j\), so
  \(u^{m_j}(\iota_0 x_j) = u^{-k_j} u^{k_j} (\iota_1 b_j) = \iota_1 b_j\). Take
  \(I = J_0 \sqcup J_1\), with generator pairs \((a_j, y_j)\) for \(j \in J_0\) and
  \((x_j, b_j)\) for \(j \in J_1\), and let \(f : E(m) \to P\) be the model map of
  \ref{def:twoLattice_modelHom}.

  \emph{Chart surjectivity.} Any \(x \in M_0\) is an \(R[t]\)-combination
  \(x = \sum_{j \in J_0} g_j(t_0)\, a_j\); the vector with components \(g_j\) on
  \(J_0\) and \(0\) on \(J_1\) maps to \(x\) under \(f_0\). Symmetrically for \(M_1\).

  \emph{Overlap surjectivity.} Given \(n \in N\), clear denominators:
  \(u^k n = \iota_0 x\) for some \(k \ge 0\), \(x \in M_0\); pick \(p\) with
  \(f_0(p) = x\). Since \(f\) commutes with the overlap actions and their inverses and
  with \(\iota_0\),
  \[
    f_N\Bigl(u_E^{-k}\bigl(\iota_0^{E} p\bigr)\Bigr)
    \;=\; u^{-k}\bigl(\iota_0(f_0 p)\bigr)
    \;=\; u^{-k}\bigl(u^{k} n\bigr) \;=\; n ,
  \]
  where \(u_E\) and \(\iota_0^E\) denote the overlap action and restriction of the
  model.
\end{proof}

\section{The coherence theorems for two-lattice pairs}
\label{sec:two_lattice_coherence}

The two finiteness keystones of the engine: for a pair with finite lattices, \(H^1\) is
a finite \(R\)-module over \emph{every} commutative ring \(R\), and \(H^0\) is a finite
\(R\)-module over every \emph{Noetherian} \(R\). Noetherianity enters only through
\(H^0\); every downstream consequence that only needs \(H^1\) --- vanishing propagation
and the openness of the vanishing locus (Section~\ref{sec:nakayama_vanishing}) --- holds
relative to an arbitrary base ring.

\begin{definition}[The kernel pair of a map of pairs]
  \label{def:twoLattice_kernelPair}
  \lean{TwoLatticePair.Hom.kernelPair, TwoLatticePair.Hom.kernelPairIncl}
  \uses{def:twoLattice_hom}
  \leanok
  For a map of two-lattice pairs \(f : P \to P'\), the \emph{kernel pair} \(K(f)\) is
  the two-lattice pair with carriers \(\ker f_0 \subseteq M_0\),
  \(\ker f_1 \subseteq M_1\), \(\ker f_N \subseteq N\), the restricted coordinate and
  overlap actions, and the restricted maps \(\iota_0, \iota_1\); the componentwise
  inclusions form a map of pairs \(K(f) \to P\).
\end{definition}
\begin{proof}
  \leanok
  \uses{def:twoLatticePair}
  The kernels are stable under the actions and the restrictions because \(f\) commutes
  with them (for the inverse overlap action, by the automatic compatibility of
  \ref{def:twoLattice_hom}), so all the structure restricts; the annihilation axioms
  restrict verbatim. Denominator clearing must be re-proved: let
  \(n \in \ker f_N\). Clearing in \(P\) gives \(k \ge 0\) and \(x \in M_0\) with
  \(u^k n = \iota_0 x\). Then
  \(\iota_0'\bigl(f_0 x\bigr) = f_N(u^k n) = u'^k\bigl(f_N n\bigr) = 0\), so by the
  annihilation axiom of \(P'\) there is \(j \ge 0\) with \(t_0'^j (f_0 x) = 0\), i.e.\
  \(f_0\bigl(t_0^j x\bigr) = 0\): the element \(t_0^j x\) lies in \(\ker f_0\), and
  \[
    u^{j + k}\, n \;=\; u^j\bigl(\iota_0 x\bigr) \;=\; \iota_0\bigl(t_0^j x\bigr)
  \]
  exhibits clearing inside the kernel pair. The chart-1 side is symmetric. The
  componentwise inclusions commute with all the structure by construction.
\end{proof}

\begin{lemma}[The kernel pair sits in a short exact sequence]
  \label{lem:twoLattice_kernelPair_shortExact}
  \lean{TwoLatticePair.Hom.isShortExact_kernelPairIncl}
  \uses{def:twoLattice_kernelPair, def:twoLattice_shortExact}
  \leanok
  If a map of pairs \(f : P \to P'\) is surjective on all three carriers, then
  \[
    0 \longrightarrow K(f) \longrightarrow P \xrightarrow{\ f\ } P' \longrightarrow 0
  \]
  is a short exact sequence of two-lattice pairs.
\end{lemma}
\begin{proof}
  \leanok
  On each carrier, the inclusion of the kernel is injective, its image is exactly the
  kernel of the corresponding component of \(f\), and that component is surjective by
  hypothesis.
\end{proof}

\begin{lemma}[Kernel lattices are finite over a Noetherian ring]
  \label{lem:moduleFinite_aeval_kernelPair}
  \lean{TwoLatticePair.Hom.moduleFinite_aeval_kernelPair_t₀,
    TwoLatticePair.Hom.moduleFinite_aeval_kernelPair_t₁}
  \uses{def:twoLattice_kernelPair}
  \leanok
  Let \(R\) be Noetherian and let \(f : P \to P'\) be a map of pairs where \(P\) has
  finite lattices. Then the kernel pair \(K(f)\) has finite lattices.
\end{lemma}
\begin{proof}
  \leanok
  \(\ker f_0\) is an \(R[t]\)-submodule of \(M_0\) for the structure through \(t_0\)
  (it is stable under \(t_0\)). By Hilbert's basis theorem \(R[t]\) is Noetherian, so
  the finitely generated \(R[t]\)-module \(M_0\) is a Noetherian module, and every
  submodule --- in particular \(\ker f_0\) --- is finitely generated. Symmetrically
  for \(\ker f_1\).
\end{proof}

\begin{theorem}[COH-1: coherence of \(H^1\) over any base ring]
  \label{thm:twoLattice_coh1}
  \lean{TwoLatticePair.moduleFinite_h1}
  \uses{def:twoLatticePair, def:twoLattice_H1}
  \leanok
  Let \(R\) be \emph{any} commutative ring --- no Noetherian hypothesis --- and let
  \(P\) be a two-lattice pair with finite lattices. Then \(H^1(P)\) is a finite
  \(R\)-module.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:exists_hom_model_surjective, thm:moduleFinite_h1_model,
    lem:twoLattice_h1Map_surjective}
  Choose a finite model surjection \(f : E(m) \to P\)
  (\ref{thm:exists_hom_model_surjective}). It is surjective on overlap modules, so
  \(H^1(f) : H^1(E(m)) \to H^1(P)\) is surjective
  (\ref{lem:twoLattice_h1Map_surjective}). The source is a finite \(R\)-module --- the
  monomial window (\ref{thm:moduleFinite_h1_model}) --- and a quotient of a finite
  module is finite.
\end{proof}

\begin{theorem}[COH-0: coherence of \(H^0\) over a Noetherian base ring]
  \label{thm:twoLattice_coh0}
  \lean{TwoLatticePair.moduleFinite_h0}
  \uses{def:twoLatticePair, def:twoLattice_H0}
  \leanok
  Let \(R\) be a \emph{Noetherian} commutative ring and let \(P\) be a two-lattice
  pair with finite lattices. Then \(H^0(P)\) is a finite \(R\)-module.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:exists_hom_model_surjective, def:twoLattice_kernelPair,
    lem:twoLattice_kernelPair_shortExact, lem:moduleFinite_aeval_kernelPair,
    lem:moduleFinite_aeval_model, def:twoLattice_delta, thm:twoLattice_exact_h0_delta,
    thm:twoLattice_coh1, thm:moduleFinite_h0_model}
  Choose a finite model surjection \(f : E(m) \to P\)
  (\ref{thm:exists_hom_model_surjective}), surjective on all three carriers, and form
  the short exact sequence \(0 \to K(f) \to E(m) \to P \to 0\) of
  \ref{lem:twoLattice_kernelPair_shortExact}. Its connecting homomorphism
  \(\partial : H^0(P) \to H^1(K(f))\) (\ref{def:twoLattice_delta}) has:
  \begin{itemize}
    \item kernel equal to the image of \(H^0(E(m)) \to H^0(P)\)
      (\ref{thm:twoLattice_exact_h0_delta}), a quotient of the finite \(R\)-module
      \(H^0(E(m))\) of the degree window (\ref{thm:moduleFinite_h0_model}, using that
      \(R\) is Noetherian), hence finite;
    \item image a submodule of \(H^1(K(f))\). The model has finite lattices
      (\ref{lem:moduleFinite_aeval_model}), so the kernel pair has finite lattices
      over the Noetherian \(R\) (\ref{lem:moduleFinite_aeval_kernelPair}), and COH-1
      applied to \(K(f)\) (\ref{thm:twoLattice_coh1}) makes \(H^1(K(f))\) a finite
      \(R\)-module; over the Noetherian \(R\) it is a Noetherian module, so the
      submodule \(\partial\bigl(H^0(P)\bigr)\) is finite.
  \end{itemize}
  Thus \(H^0(P)\) is an extension of the finite module \(\partial(H^0(P))\) by the
  finite module \(\ker \partial\), hence finite.
\end{proof}

\section{The rigid engine on a packaged two-cover}
\label{sec:rigid_engine_assembly}

This section assembles the module-level rigid engine --- the coherence theorems of
two-lattice pairs (\ref{thm:twoLattice_coh1}, \ref{thm:twoLattice_coh0}), the fibrewise
Nakayama propagation (Section~\ref{sec:nakayama_vanishing}) and the split rigidity
(Section~\ref{sec:split_rigidity}) --- at the level of sheaves. For a sheaf \(F\) of
\(R\)-modules on the small Zariski site of a scheme \(X\), packaged quasi-coherently
(\ref{def:qcohOn}) on both charts of an affine two-cover \(U_0 \cup U_1 = X\), a small
amount of coordinate data produces a two-lattice pair whose cohomology \emph{is} the
cohomology of the site with coefficients in \(F\); firing the engine on the pair yields
the curve-lite form of Kleiman's theorem on the module \(\mathcal Q\): vanishing of the
degree-one fibres forces \(H^1 = 0\) and makes \(H^0\) finite projective, with formation
of \(H^0\) commuting with all coefficients.

The degree-one carrier is the landed two-cover cokernel
(\ref{thm:twoCoverH1LinearEquiv}); the missing degree-zero carrier --- the kernel twin of
the cokernel bridge --- is built first.

\begin{theorem}[The Mayer--Vietoris degree-zero kernel bridge]
  \label{thm:sectionsKerEquiv}
  \lean{CategoryTheory.GrothendieckTopology.MayerVietorisSquare.sectionsToKerModuleDiff,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.sectionsToKerModuleDiff_coe,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.sectionsKerEquiv,
    CategoryTheory.GrothendieckTopology.MayerVietorisSquare.sectionsKerEquiv_apply_coe}
  \uses{def:moduleDiff, lem:mv_exact_degree0}
  \leanok
  For a Mayer--Vietoris square \(S\) and a sheaf \(F\) of \(R\)-modules, the pair of
  restrictions, corestricted to the kernel of the restriction-difference map
  (\ref{def:moduleDiff}), is an \(R\)-linear equivalence
  \[
    F(X_4) \;\cong\; \ker\bigl(\mathrm{moduleDiff} : F(X_2) \times F(X_3) \to
      F(X_1)\bigr),
    \qquad s \longmapsto \bigl(s|_{X_2},\, s|_{X_3}\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The map lands in the kernel and is injective and surjective onto it by degree-zero
  exactness (\ref{lem:mv_exact_degree0}): injectivity is the separation half of the
  sheaf condition of the square, surjectivity onto the kernel is the gluing half.
  Linearity is linearity of the two restrictions.
\end{proof}

\begin{theorem}[The two-cover \(H^0\) kernel bridge]
  \label{thm:twoCoverH0LinearEquiv}
  \lean{AlgebraicGeometry.Scheme.twoCoverH0LinearEquiv}
  \uses{thm:sectionsKerEquiv, def:twoCoverSquare, def:HModule_linearEquivHModule',
    def:HModule'_linearEquiv0}
  \leanok
  Let \(X\) be a scheme, \(U_0 \cup U_1 = X\) a two-cover by opens, and \(F\) \emph{any}
  sheaf of \(R\)-modules on the small Zariski site. Then degree-zero cohomology of the
  site is the kernel of the two-cover restriction-difference map: an \(R\)-linear
  equivalence
  \[
    H^0(X, F) \;\cong\;
      \ker\Bigl(F(U_0) \times F(U_1) \longrightarrow F(U_0 \cap U_1)\Bigr).
  \]
  No affineness is needed: degree-zero exactness is the sheaf condition alone.
\end{theorem}
\begin{proof}
  \leanok
  Identify \(H^0(X, F)\) with \(H'^0(\top, F) = F(\top)\)
  (\ref{def:HModule_linearEquivHModule'}, \ref{def:HModule'_linearEquiv0}), then apply
  the kernel bridge \ref{thm:sectionsKerEquiv} to the two-cover square
  (\ref{def:twoCoverSquare}), whose restriction-difference map is exactly the displayed
  one.
\end{proof}

\begin{definition}[The two-cover pair data of a packaged sheaf]
  \label{def:twoCoverPairData}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData}
  \uses{def:qcohOn}
  \leanok
  Let \(F\) be a sheaf of \(R\)-modules on the small Zariski site of \(X\), packaged
  quasi-coherently (\ref{def:qcohOn}) on two opens \(U_0, U_1\). \emph{Two-cover pair
  data} for \(F\) consists of chart coordinates \(g_0 \in \Gamma(X, U_0)\),
  \(g_1 \in \Gamma(X, U_1)\) such that:
  \begin{itemize}
    \item the overlap is the basic open of either coordinate:
      \(U_0 \cap U_1 = D(g_0) = D(g_1)\);
    \item the packaged actions of \(g_0\) and of \(g_1\) commute with the \(R\)-scalars
      on sections of every open \(W \le U_i\);
    \item on the overlap the two packaged actions are mutually inverse (the relation
      \(g_0\, g_1 = 1\), expressed on the actions: acting by \(g_0\) and then by
      \(g_1\), in either order, is the identity of \(F(U_0 \cap U_1)\)).
  \end{itemize}
\end{definition}

\begin{definition}[The two-lattice pair of a packaged sheaf]
  \label{def:twoCoverPairData_pair}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.end₀,
    AlgebraicGeometry.Scheme.TwoCoverPairData.end₁,
    AlgebraicGeometry.Scheme.TwoCoverPairData.end₀_apply,
    AlgebraicGeometry.Scheme.TwoCoverPairData.end₁_apply,
    AlgebraicGeometry.Scheme.TwoCoverPairData.end₀_pow_apply,
    AlgebraicGeometry.Scheme.TwoCoverPairData.end₁_pow_apply,
    AlgebraicGeometry.Scheme.TwoCoverPairData.pair,
    AlgebraicGeometry.Scheme.TwoCoverPairData.pair_diff,
    AlgebraicGeometry.Scheme.TwoCoverPairData.pair_t₀,
    AlgebraicGeometry.Scheme.TwoCoverPairData.pair_t₁}
  \uses{def:twoCoverPairData, def:twoLatticePair, def:qcohOn_module,
    def:qcohOn_secRes_linear, thm:qcohOn_isLocalizedModule, def:twoCoverSquare,
    def:moduleDiff}
  \leanok
  Let \(U_0, U_1\) be \emph{affine} opens and \(d\) two-cover pair data for a packaged
  sheaf \(F\). Then the data
  \[
    M_0 = F(U_0), \quad M_1 = F(U_1), \quad N = F(U_0 \cap U_1),
  \]
  with coordinate actions the packaged actions of \(g_0, g_1\) (made \(R\)-linear
  endomorphisms by the \(R\)-linearity field of \(d\)), overlap automorphism the action
  of \(g_0\) on \(N\) (invertible with inverse the action of \(g_1\), by the
  mutual-inverse field), and restrictions \(\iota_0, \iota_1\) the section restrictions
  to the overlap, is a two-lattice pair (\ref{def:twoLatticePair}) over \(R\). Its
  difference map is the Mayer--Vietoris restriction-difference map of the two-cover
  square with coefficients in \(F\), on the nose.
\end{definition}
\begin{proof}
  \leanok
  The intertwining laws \(\iota_i(g_i \cdot x) = g_i \cdot \iota_i(x)\) are the
  (P1) naturality of the packaged action under restriction. The localization axioms are
  the (P2) axioms of the packaging, transported to the overlap along the identification
  \(U_0 \cap U_1 = U_i \cap D(g_i)\): denominator clearing for the pair asks that every
  \(n \in N\) admit \(m \ge 0\) and \(x \in M_i\) with \(g_i^m \cdot n =
  \iota_i(x)\), which is (P2) denominator clearing on the affine open \(U_i\); and
  annihilation for the pair asks that \(\iota_i(x) = 0\) force \(g_i^m \cdot x = 0\),
  which is (P2) defect annihilation --- exactly the three-axiom match by which the
  packaging exhibits the overlap sections as the localization of the chart sections
  (\ref{thm:qcohOn_isLocalizedModule}). Powers of the action are the actions of powers
  (by (P1) associativity), which is used implicitly throughout. The difference map
  \((x, y) \mapsto \iota_0 x - \iota_1 y\) is by construction the
  restriction-difference map of \ref{def:moduleDiff} for the two-cover square
  (\ref{def:twoCoverSquare}).
\end{proof}

\begin{definition}[The cohomology carriers of the pair]
  \label{def:twoCoverPair_h0h1}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.h0Equiv,
    AlgebraicGeometry.Scheme.TwoCoverPairData.h1Equiv}
  \uses{def:twoCoverPairData_pair, thm:twoCoverH0LinearEquiv,
    thm:twoCoverH1LinearEquiv, thm:hModule1_vanishing_qcoh, def:twoLattice_H0,
    def:twoLattice_H1, lem:twoLattice_range_diff}
  \leanok
  Let \(U_0, U_1\) be affine opens with \(U_0 \cup U_1 = X\) and \(d\) two-cover pair
  data for the packaged sheaf \(F\), with pair \(P\)
  (\ref{def:twoCoverPairData_pair}). There are \(R\)-linear equivalences
  \[
    H^0(X, F) \;\cong\; H^0(P), \qquad H^1(X, F) \;\cong\; H^1(P) :
  \]
  the cohomology of the site with coefficients in \(F\) is the cohomology of the
  two-term complex of the pair.
\end{definition}
\begin{proof}
  \leanok
  Degree zero: the kernel bridge (\ref{thm:twoCoverH0LinearEquiv}) lands in the kernel
  of the restriction-difference map, which is the kernel of the pair's difference map
  since the two maps are equal (\ref{def:twoCoverPairData_pair}), i.e.\ \(H^0(P)\)
  (\ref{def:twoLattice_H0}). Degree one: the packaging on the two affine charts gives
  the twisted affine vanishing \(H'^1(U_i, F) = 0\)
  (\ref{thm:hModule1_vanishing_qcoh}), so the two-cover computation
  (\ref{thm:twoCoverH1LinearEquiv}) identifies \(H^1(X, F)\) with the cokernel of the
  restriction-difference map; and the cokernel of the pair's difference map is
  \(H^1(P)\) (\ref{lem:twoLattice_range_diff}, \ref{def:twoLattice_H1}).
\end{proof}

\begin{lemma}[Vanishing of \(H^1\) of the pair makes the differential surjective]
  \label{lem:twoCoverPair_surjective_diff}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.surjective_diff}
  \uses{def:twoCoverPairData_pair, lem:twoLattice_range_diff,
    lem:rigid_surjective_of_coker_zero}
  \leanok
  If \(H^1\) of the pair of \ref{def:twoCoverPairData_pair} is trivial (a
  subsingleton), then the difference map \(\delta : F(U_0) \times F(U_1) \to
  F(U_0 \cap U_1)\) is surjective.
\end{lemma}
\begin{proof}
  \leanok
  \(H^1\) of the pair is the cokernel of \(\delta\) (\ref{lem:twoLattice_range_diff}),
  and a map with trivial cokernel is surjective
  (\ref{lem:rigid_surjective_of_coker_zero}).
\end{proof}

\begin{theorem}[The rigid engine, sheaf level]
  \label{thm:twoCoverPair_rigidEngine}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.rigidEngine}
  \uses{def:twoCoverPair_h0h1, def:twoCoverPairData_pair}
  \leanok
  \source{kleiman-picard}
  Let \(R\) be Noetherian, \(U_0, U_1\) affine opens covering \(X\), and \(d\)
  two-cover pair data for the packaged sheaf \(F\) whose pair \(P\) has finite lattices
  (the chart sections \(F(U_i)\) are finite over \(R[t]\) through the coordinate
  actions). Assume the section modules are tame: \(F(U_0) \times F(U_1)\) is a flat
  \(R\)-module and \(F(U_0 \cap U_1)\) is a projective \(R\)-module (in the intended
  applications all three are free). If every residue-field fibre of \(H^1\) of the pair
  vanishes,
  \[
    H^1(P) \otimes_R \kappa(\mathfrak p) = 0 \quad \text{for every prime }
      \mathfrak p \subseteq R,
  \]
  then
  \[
    H^1(X, F) = 0, \qquad \text{and } H^0(X, F) \text{ is a finite projective }
      R\text{-module}.
  \]
  This is the curve-lite form of Kleiman's criterion for the module \(\mathcal Q\):
  vanishing of the degree-one cohomology of the fibres ((v) of the source) forces the
  representing module to be free/projective ((i)) --- here delivered on a two-chart
  cover with the two-term \v Cech complex playing the role of the pushforward. The
  fibre hypothesis is deliberately consumed in this \emph{complex} form (fibres of
  \(H^1\) of the pair); its sheaf-level discharge --- identifying the fibre of the
  complex with the cohomology of a fibre sheaf --- is a seam of a later campaign and is
  not part of this statement.
\end{theorem}
\begin{proof}
  \leanok
  \uses{thm:twoLattice_coh1, thm:twoLattice_coh0, thm:fibrewise_vanishing_propagates,
    lem:twoCoverPair_surjective_diff, thm:rigid_projective_ker}
  \(H^1(P)\) is a finite \(R\)-module by COH-1 (\ref{thm:twoLattice_coh1}), so the
  fibrewise vanishing hypothesis propagates to \(H^1(P) = 0\) by Nakayama
  (\ref{thm:fibrewise_vanishing_propagates}), and along the degree-one carrier
  (\ref{def:twoCoverPair_h0h1}) this gives \(H^1(X, F) = 0\). The differential is then
  surjective (\ref{lem:twoCoverPair_surjective_diff}). \(H^0(P) = \ker\delta\) is
  finite over the Noetherian \(R\) by COH-0 (\ref{thm:twoLattice_coh0}), and the split
  rigidity of a surjective two-term complex with flat domain and projective codomain
  makes the finite kernel projective (\ref{thm:rigid_projective_ker}). Transport both
  along the degree-zero carrier (\ref{def:twoCoverPair_h0h1}).
\end{proof}

\begin{theorem}[The openness export]
  \label{thm:twoCoverPair_isOpen_vanishing}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.rigidEngine_isOpen_vanishing}
  \uses{def:twoCoverPairData_pair, thm:twoLattice_coh1, thm:isOpen_fibre_vanishing}
  \leanok
  \source{kleiman-picard}
  In the setting of \ref{def:twoCoverPairData_pair}, with finite lattices but \emph{no}
  Noetherian hypothesis on \(R\), the fibrewise-vanishing locus
  \[
    \bigl\{\, \mathfrak p \in \Spec R :
      H^1(P) \otimes_R \kappa(\mathfrak p) = 0 \,\bigr\}
  \]
  is open in \(\Spec R\). (In the source the analogous openness is obtained from
  Serre's finiteness theorem over a Noetherian base; here it falls out of the coherence
  of \(H^1\) over an arbitrary base ring, Noetherian-free.)
\end{theorem}
\begin{proof}
  \leanok
  \(H^1(P)\) is a finite \(R\)-module over any commutative \(R\)
  (\ref{thm:twoLattice_coh1}); for a finite module the fibrewise-vanishing locus is the
  complement of the support, which is closed (\ref{thm:isOpen_fibre_vanishing}).
\end{proof}

\begin{definition}[The module-coefficient clause]
  \label{def:twoCoverPair_h0TensorEquiv}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.h0TensorEquiv}
  \uses{def:twoCoverPair_h0h1, lem:twoCoverPair_surjective_diff, thm:rigid_ker_tensor}
  \leanok
  \source{kleiman-picard}
  In the setting of \ref{def:twoCoverPair_h0h1}, assume \(H^1(P)\) is trivial and the
  overlap module \(F(U_0 \cap U_1)\) is flat over \(R\). Then for \emph{every}
  \(R\)-module \(P'\) there is an \(R\)-linear equivalence
  \[
    H^0(X, F) \otimes_R P' \;\cong\;
      \ker\bigl(\delta \otimes_R P'\bigr) :
  \]
  formation of \(H^0\) commutes with all module coefficients. This is the two-chart
  form of the isomorphism (eq.\ Q of the source)
  \(\mathrm{Hom}(\mathcal Q, \mathcal N) \cong f_*(\mathcal F \otimes f^*\mathcal N)\)
  in its right-exact regime: on the vanishing locus the functor
  \(P' \mapsto \ker(\delta \otimes P')\) is represented by \(H^0\).
\end{definition}
\begin{proof}
  \leanok
  The differential is surjective (\ref{lem:twoCoverPair_surjective_diff}) with flat
  codomain, so the kernel-tensor rigidity (\ref{thm:rigid_ker_tensor}) gives
  \(\ker(\delta) \otimes P' \cong \ker(\delta \otimes P')\); compose with the
  degree-zero carrier (\ref{def:twoCoverPair_h0h1}) tensored with \(P'\).
\end{proof}

\begin{definition}[The ring-map clause, abstract half]
  \label{def:twoCoverPair_h0BaseChangeEquiv}
  \lean{AlgebraicGeometry.Scheme.TwoCoverPairData.h0BaseChangeEquiv}
  \uses{def:twoCoverPair_h0h1, lem:twoCoverPair_surjective_diff, thm:rigid_ker_baseChange}
  \leanok
  In the setting of \ref{def:twoCoverPair_h0TensorEquiv}, for every commutative
  \(R\)-algebra \(R'\) there is an \(R'\)-\emph{linear} equivalence
  \[
    R' \otimes_R H^0(X, F) \;\cong\; \ker\bigl(\delta \otimes_R R'\bigr),
  \]
  the module-coefficient clause upgraded to carry the \(R'\)-structure. Reaching
  \(H^0\) of a base-changed \emph{sheaf} on the nose is a separate step: it threads
  this equivalence through term identifications of the base-changed complex
  (\ref{def:relTwistH0BaseChange} below, for the relative twisted sheaf).
\end{definition}
\begin{proof}
  \leanok
  As in \ref{def:twoCoverPair_h0TensorEquiv}, with the \(R'\)-linear kernel base-change
  form of the rigidity (\ref{thm:rigid_ker_baseChange}) in place of the module form.
\end{proof}

\section{The pair data of the twisted sheaf}
\label{sec:twist_pair_data}

The Layer-2 discharge of the pair data for the cocycle-glued twisted sheaf \(F_g\) of
Section~\ref{sec:twisted_sheaf}, generic in the base ring \(k\): every field of
\ref{def:twoCoverPairData} reduces, through the chart trivialisations, to section
algebra in the structure sheaf.

\begin{definition}[Multiplication by a section as an endomorphism]
  \label{def:mulSectionEnd}
  \lean{AlgebraicGeometry.Scheme.mulSectionEnd, AlgebraicGeometry.Scheme.mulSectionEnd_apply}
  \uses{def:moduleKSheaf}
  \leanok
  Let \(X\) be a scheme over \(\Spec k\) and \(U\) an open. Multiplication by a fixed
  section \(c \in \Gamma(X, U)\) is a \(k\)-linear endomorphism of \(\Gamma(X, U)\)
  (for the \(k\)-structure through the structure morphism, \ref{def:moduleKSheaf}):
  the comparison endomorphism through which the twisted pair's coordinate actions are
  identified with honest section multiplication.
\end{definition}

\begin{lemma}[The packaged action of the twisted sheaf, and its \(k\)-linearity]
  \label{lem:twistSheaf_qsmul_eq}
  \lean{AlgebraicGeometry.twistSheaf_qsmul₀_eq, AlgebraicGeometry.twistSheaf_qsmul₁_eq,
    AlgebraicGeometry.twistSheaf_smul_qsmul₀, AlgebraicGeometry.twistSheaf_smul_qsmul₁}
  \uses{thm:twistSheaf_qcohOn, def:twistTriv, def:qcohOn_transport}
  \leanok
  Fix opens \(V_0, V_1\) and a unit cocycle \(g\), with twisted sheaf \(F_g\). For
  \(W \le V_i\), the packaged action (\ref{thm:twistSheaf_qcohOn}) of
  \(r \in \Gamma(X, V_i)\) on \(F_g(W)\) is
  trivialise--multiply--untrivialise:
  \[
    r \cdot m \;=\; \mathrm{triv}_i^{-1}\bigl(r|_W \cdot \mathrm{triv}_i(m)\bigr),
  \]
  and it commutes with the \(k\)-scalars.
\end{lemma}
\begin{proof}
  \leanok
  The packaging of \(F_g\) on the chart \(V_i\) is by definition the transport
  (\ref{def:qcohOn_transport}) of the structure-sheaf packaging along the chart
  trivialisation (\ref{def:twistTriv}), whose action is exactly the displayed conjugate;
  the first claim is definitional. For \(k\)-linearity: multiplication of sections
  commutes with the \(k\)-scalars (both are multiplications in a commutative ring), and
  the trivialisations are \(k\)-linear, so the conjugate commutes with the scalars too.
\end{proof}

\begin{lemma}[The two trivialisations differ by the cocycle on the overlap]
  \label{lem:twistTriv_inf_eq}
  \lean{AlgebraicGeometry.twistTriv₀_inf_eq, AlgebraicGeometry.twistTriv₁_inf_eq}
  \uses{def:twistTriv, def:twistSections}
  \leanok
  On the overlap sections \(F_g(V_0 \cap V_1)\),
  \[
    \mathrm{triv}_0(p) \;=\; g \cdot \mathrm{triv}_1(p), \qquad
    \mathrm{triv}_1(p) \;=\; g^{-1} \cdot \mathrm{triv}_0(p).
  \]
\end{lemma}
\begin{proof}
  \leanok
  A twisted section \(p = (s_0, s_1)\) over \(V_0 \cap V_1\) satisfies the matching
  relation \(s_0| = g \cdot s_1|\) on \((V_0 \cap V_1) \cap V_0 \cap V_1 = V_0 \cap
  V_1\) (\ref{def:twistSections}); the two trivialisations are the two components
  (\ref{def:twistTriv}), so the relation reads \(\mathrm{triv}_0(p) = g \cdot
  \mathrm{triv}_1(p)\). Multiply by \(g^{-1}\) for the second form.
\end{proof}

\begin{lemma}[The mutual-inverse law of the coordinate actions]
  \label{lem:twistSheaf_qsmul_inverse}
  \lean{AlgebraicGeometry.twistSheaf_qsmul₀_qsmul₁, AlgebraicGeometry.twistSheaf_qsmul₁_qsmul₀}
  \uses{lem:twistSheaf_qsmul_eq, lem:twistTriv_inf_eq}
  \leanok
  Let \(r_0 \in \Gamma(X, V_0)\), \(r_1 \in \Gamma(X, V_1)\) satisfy
  \(r_0|_{\cap} \cdot r_1|_{\cap} = 1\) on the overlap. Then the packaged actions of
  \(r_0\) and \(r_1\) on \(F_g(V_0 \cap V_1)\) are mutually inverse.
\end{lemma}
\begin{proof}
  \leanok
  Compute the composite on \(m\) through the chart-0 trivialisation. Acting by \(r_1\)
  is \(\mathrm{triv}_1^{-1}(r_1| \cdot \mathrm{triv}_1(m))\)
  (\ref{lem:twistSheaf_qsmul_eq}); by \ref{lem:twistTriv_inf_eq} its chart-0
  trivialisation is \(g \cdot r_1| \cdot g^{-1} \cdot \mathrm{triv}_0(m)
  = r_1| \cdot \mathrm{triv}_0(m)\) (the ring is commutative). Acting then by \(r_0\)
  multiplies by \(r_0|\), giving \(r_0|\, r_1| \cdot \mathrm{triv}_0(m) =
  \mathrm{triv}_0(m)\); untrivialising returns \(m\). The other order is symmetric,
  through the chart-1 trivialisation.
\end{proof}

\begin{definition}[The pair data of the twisted sheaf]
  \label{def:twistPairData}
  \lean{AlgebraicGeometry.twistPairData}
  \uses{def:twoCoverPairData, thm:twistSheaf_qcohOn, lem:twistSheaf_qsmul_eq,
    lem:twistSheaf_qsmul_inverse}
  \leanok
  Let \(r_0 \in \Gamma(X, V_0)\) and \(r_1 \in \Gamma(X, V_1)\) satisfy
  \(V_0 \cap V_1 = D(r_0) = D(r_1)\) and \(r_0|_{\cap} \cdot r_1|_{\cap} = 1\). Then
  \((r_0, r_1)\) is two-cover pair data (\ref{def:twoCoverPairData}) for the twisted
  sheaf \(F_g\) on \((V_0, V_1)\): the basic-open identifications are the hypotheses,
  \(k\)-linearity of the packaged actions is \ref{lem:twistSheaf_qsmul_eq}, and the
  mutual-inverse law is \ref{lem:twistSheaf_qsmul_inverse}.
\end{definition}

\begin{theorem}[Chart-lattice finiteness of the twisted pair]
  \label{thm:moduleFinite_aeval_twistPair}
  \lean{AlgebraicGeometry.moduleFinite_aeval'_twistPair_t₀,
    AlgebraicGeometry.moduleFinite_aeval'_twistPair_t₁}
  \uses{def:twistPairData, def:twoCoverPairData_pair, def:mulSectionEnd, def:twistTriv,
    lem:aevalCongr}
  \leanok
  In the setting of \ref{def:twistPairData} with \(V_0, V_1\) affine: if the chart
  sections \(\Gamma(X, V_i)\) are finite over \(k[t]\) with \(t\) acting as
  multiplication by \(r_i\) (\ref{def:mulSectionEnd}), then the pair of the twisted
  sheaf (\ref{def:twoCoverPairData_pair}) has finite lattices.
\end{theorem}
\begin{proof}
  \leanok
  The chart trivialisation \(\mathrm{triv}_i : F_g(V_i) \cong \Gamma(X, V_i)\)
  (\ref{def:twistTriv}) intertwines the pair's coordinate action --- which is
  trivialise--multiply--untrivialise (\ref{lem:twistSheaf_qsmul_eq}) --- with
  multiplication by \(r_i\). Chart-lattice finiteness transports along an equivariant
  equivalence (\ref{lem:aevalCongr}).
\end{proof}

\begin{theorem}[Freeness of the twisted section modules]
  \label{thm:free_twistSheafSections}
  \lean{AlgebraicGeometry.free_twistSheafSections₀, AlgebraicGeometry.free_twistSheafSections₁}
  \uses{def:twistTriv}
  \leanok
  For \(W \le V_i\), if \(\Gamma(X, W)\) is a free \(k\)-module then so is
  \(F_g(W)\): transport a basis along the chart trivialisation
  (\ref{def:twistTriv}).
\end{theorem}
\begin{proof}
  \leanok
  A module equivalent to a free module is free.
\end{proof}

\section{The pinned relative cover: coordinates, finiteness and freeness}
\label{sec:relative_cover_coordinates}

The geometric half of the engine's Layer-2 discharge: the pinned affine two-cover of the
curve --- the chart preimages of a finite morphism \(\pi\) to \(\PP^1\) --- carries
polynomial chart algebras through which the finiteness of \(\pi\) becomes chart-lattice
finiteness, first over the field \(k\) and then, by base change, over every test ring
\(R\). Throughout, \(k\) is a field and \(\pi : Y \to \PP^1\) an affine morphism (finite
where stated).

\begin{definition}[The pinned affine two-cover]
  \label{def:fiberTwoCover}
  \lean{AlgebraicGeometry.fiberTwoCover, AlgebraicGeometry.fiberTwoCover_V₀,
    AlgebraicGeometry.fiberTwoCover_V₁}
  \uses{def:AffineTwoCover, lem:preimage_chart_affine, lem:preimage_chart_sup,
    def:fiberCover, lem:P1_chartOpen_inf}
  \leanok
  For an affine morphism \(\pi : Y \to \PP^1\), the chart preimages
  \(V_0 = \pi^{-1}D_+(X_0)\), \(V_1 = \pi^{-1}D_+(X_1)\) form an \emph{affine two-cover}
  of \(Y\) (\ref{def:AffineTwoCover}): both charts are affine
  (\ref{lem:preimage_chart_affine}), they cover \(Y\)
  (\ref{lem:preimage_chart_sup}), and the overlap
  \(V_0 \cap V_1 = \pi^{-1}D_+(X_0 X_1)\) (\ref{lem:P1_chartOpen_inf}) is affine, being
  the preimage of an affine open under an affine morphism. This is the cover of
  \ref{def:fiberCover}, upgraded with the affineness of the overlap; the whole engine
  runs on it and on its base change.
\end{definition}

\begin{theorem}[The overlap is the basic open of the chart-1 coordinate]
  \label{thm:preimage_inf_eq_basicOpen_fiberCoord1}
  \lean{AlgebraicGeometry.preimage_inf_eq_basicOpen_fiberCoord₁}
  \uses{def:fiberCover, def:fiberCoordUnit, thm:P1_basicOpen_chartCoord}
  \leanok
  \(V_0 \cap V_1 = D(t_1)\), where \(t_1 = \pi^{\sharp}(X_0/X_1) \in \Gamma(Y, V_1)\)
  is the pulled-back chart-1 coordinate (\ref{def:fiberCoordUnit}) --- the chart-1 twin
  of the identification \(V_0 \cap V_1 = D(t_0)\) of \ref{def:fiberCover}.
\end{theorem}
\begin{proof}
  \leanok
  On \(\PP^1\) the basic open of the chart-1 coordinate \(X_0/X_1\) in \(D_+(X_1)\) is
  the chart overlap (\ref{thm:P1_basicOpen_chartCoord}); basic opens commute with
  pullback of sections, so applying \(\pi^{-1}\) gives
  \(V_1 \cap V_0 = D\bigl(\pi^{\sharp}(X_0/X_1)\bigr)\).
\end{proof}

\begin{definition}[The chart polynomial algebras]
  \label{def:fiberPolyHom}
  \lean{AlgebraicGeometry.fiberPolyHom₀, AlgebraicGeometry.fiberPolyHom₁,
    AlgebraicGeometry.fiberPolyHom₀_X, AlgebraicGeometry.fiberPolyHom₁_X}
  \uses{def:P1_chartSectionsEquiv0, def:P1_chartSectionsEquiv1, def:fiberCover,
    def:fiberCoordUnit}
  \leanok
  The \emph{chart-\(i\) polynomial algebra} is the ring homomorphism
  \[
    k[t] \;\cong\; \Gamma\bigl(\PP^1, D_+(X_i)\bigr)
      \xrightarrow{\ \pi^{\sharp}\ } \Gamma(Y, V_i),
  \]
  the chart identification (\ref{def:P1_chartSectionsEquiv0},
  \ref{def:P1_chartSectionsEquiv1}) followed by pullback along \(\pi\). It sends \(t\)
  to the pulled-back chart coordinate: \(t \mapsto t_0 = \pi^{\sharp}(X_1/X_0)\) on
  chart \(0\) (\ref{def:fiberCover}) and \(t \mapsto t_1 = \pi^{\sharp}(X_0/X_1)\) on
  chart \(1\) (\ref{def:fiberCoordUnit}).
\end{definition}
\begin{proof}
  \leanok
  Only the values at \(t\) need comment: the chart identification matches \(t\) with
  the chart coordinate \(X_{1-i}/X_i \in \Gamma(\PP^1, D_+(X_i))\), whose pullback is
  \(t_i\) by definition.
\end{proof}

\begin{theorem}[E-i: the chart polynomial algebras are finite ring maps]
  \label{thm:fiberPolyHom_finite}
  \lean{AlgebraicGeometry.fiberPolyHom₀_finite, AlgebraicGeometry.fiberPolyHom₁_finite}
  \uses{def:fiberPolyHom, lem:finite_app_chart}
  \leanok
  If \(\pi\) is finite, both chart polynomial algebras
  \(k[t] \to \Gamma(Y, V_i)\) are finite ring homomorphisms.
\end{theorem}
\begin{proof}
  \leanok
  For a finite morphism, the induced map on sections over an affine chart of the target
  is a finite ring map (\ref{lem:finite_app_chart}); precomposing with the ring
  isomorphism \(k[t] \cong \Gamma(\PP^1, D_+(X_i))\) preserves finiteness.
\end{proof}

\begin{theorem}[Scalar compatibility of the chart polynomial algebras]
  \label{thm:fiberPolyHom_algebraMap}
  \lean{AlgebraicGeometry.fiberPolyHom₀_algebraMap, AlgebraicGeometry.fiberPolyHom₁_algebraMap}
  \uses{def:fiberPolyHom, lem:P1_structureMap_appTop_awayToSection,
    lem:appLE_overAlgebraMap, def:overAlgebraMap}
  \leanok
  Let \(Y = C\) be the challenge curve and suppose \(\pi\) factors the structure
  morphism, \(\pi \circ (\text{structure map of } \PP^1) = (C \to \Spec k)\). Then the
  chart polynomial algebras carry constants to the structure algebra map
  (\ref{def:overAlgebraMap}): for \(c \in k\),
  \[
    \text{fiberPolyHom}_i(c) \;=\; \text{the image of } c \text{ under }
      k \to \Gamma(C, V_i).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The chart identification carries the constant \(c \in k[t]\) to the restriction to
  \(D_+(X_i)\) of the structure algebra map of \(\PP^1\)
  (\ref{lem:P1_structureMap_appTop_awayToSection}). Pullback along \(\pi\) carries the
  structure algebra map of \(\PP^1\) to that of \(C\), because \(\pi\) commutes with
  the two structure morphisms (\ref{lem:appLE_overAlgebraMap}, applied to the
  factorization hypothesis).
\end{proof}

\begin{theorem}[E-i in chart-lattice form, field level]
  \label{thm:moduleFinite_aeval_fiberCoord}
  \lean{AlgebraicGeometry.moduleFinite_aeval'_mulLeft_fiberCoord₀,
    AlgebraicGeometry.moduleFinite_aeval'_mulLeft_fiberCoord₁}
  \uses{thm:fiberPolyHom_finite, thm:fiberPolyHom_algebraMap, lem:moduleFinite_aeval_ringHom}
  \leanok
  In the setting of \ref{thm:fiberPolyHom_algebraMap} with \(\pi\) finite: the chart
  sections \(\Gamma(C, V_i)\) are finite over \(k[t]\), with \(t\) acting as
  multiplication by the pulled-back chart coordinate \(t_i\).
\end{theorem}
\begin{proof}
  \leanok
  Apply the finite-ring-map criterion (\ref{lem:moduleFinite_aeval_ringHom}) to the
  chart polynomial algebra: it is finite (\ref{thm:fiberPolyHom_finite}), sends \(t\)
  to \(t_i\) (\ref{def:fiberPolyHom}), and sends constants to the structure algebra
  map, which is the \(k\)-scalar action on sections
  (\ref{thm:fiberPolyHom_algebraMap}).
\end{proof}

\begin{definition}[The relative chart coordinates]
  \label{def:relFiberCoord}
  \lean{AlgebraicGeometry.relFiberCoord₀, AlgebraicGeometry.relFiberCoord₁,
    AlgebraicGeometry.relPullbackSection_mul}
  \uses{def:relSectionsBaseChange, def:relCover, def:fiberTwoCover, def:fiberCover,
    def:fiberCoordUnit}
  \leanok
  Let \(R\) be a commutative \(k\)-algebra and consider the base-changed pinned cover
  \(V_i^R = \mathrm{pr}_1^{-1} V_i\) of the relative curve \(C_R\)
  (\ref{def:relCover}, \ref{def:fiberTwoCover}). The \emph{relative chart coordinates}
  are the pullbacks along the first projection,
  \[
    t_0^R \;=\; \mathrm{pr}_1^{\sharp}(t_0) \in \Gamma(C_R, V_0^R), \qquad
    t_1^R \;=\; \mathrm{pr}_1^{\sharp}(t_1) \in \Gamma(C_R, V_1^R)
  \]
  (\ref{def:relSectionsBaseChange}); pullback of sections is multiplicative.
\end{definition}

\begin{theorem}[The relative overlap identifications]
  \label{thm:relCover_inf_eq_basicOpen}
  \lean{AlgebraicGeometry.relCover_fiberTwoCover_inf_eq_basicOpen₀,
    AlgebraicGeometry.relCover_fiberTwoCover_inf_eq_basicOpen₁}
  \uses{def:relFiberCoord, lem:relCover_inf, def:fiberCover,
    thm:preimage_inf_eq_basicOpen_fiberCoord1}
  \leanok
  On the base-changed pinned cover,
  \[
    V_0^R \cap V_1^R \;=\; D(t_0^R) \;=\; D(t_1^R).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The overlap of the base-changed cover is the preimage of the overlap
  (\ref{lem:relCover_inf}); the overlap downstairs is \(D(t_0) = D(t_1)\)
  (\ref{def:fiberCover}, \ref{thm:preimage_inf_eq_basicOpen_fiberCoord1}); and basic
  opens commute with pullback of sections along \(\mathrm{pr}_1\).
\end{proof}

\begin{theorem}[The relative coordinates are mutually inverse on the overlap]
  \label{thm:relFiberCoord_mul}
  \lean{AlgebraicGeometry.relFiberCoord_mul}
  \uses{def:relFiberCoord, def:fiberCoordUnit, lem:relCover_inf}
  \leanok
  \(t_0^R|_{\cap} \cdot t_1^R|_{\cap} = 1\) in
  \(\Gamma\bigl(C_R,\ V_0^R \cap V_1^R\bigr)\).
\end{theorem}
\begin{proof}
  \leanok
  The identity \(t_0|_{\cap} \cdot t_1|_{\cap} = 1\) holds downstairs
  (\ref{def:fiberCoordUnit}); pull it back along \(\mathrm{pr}_1^{\sharp}\) over the
  overlap, a ring homomorphism commuting with restriction, using
  \(\mathrm{pr}_1^{-1}(V_0 \cap V_1) = V_0^R \cap V_1^R\) (\ref{lem:relCover_inf}).
\end{proof}

\begin{theorem}[The relative E-i: chart-lattice finiteness over the test ring]
  \label{thm:moduleFinite_aeval_relFiberCoord}
  \lean{AlgebraicGeometry.moduleFinite_aeval'_mulSectionEnd_relFiberCoord₀,
    AlgebraicGeometry.moduleFinite_aeval'_mulSectionEnd_relFiberCoord₁}
  \uses{thm:moduleFinite_aeval_fiberCoord, thm:moduleFinite_aeval_baseChange,
    lem:aevalCongr, def:relSectionsBaseChange, def:relFiberCoord, def:mulSectionEnd}
  \leanok
  In the setting of \ref{thm:moduleFinite_aeval_fiberCoord}, for every commutative
  \(k\)-algebra \(R\): the relative chart sections \(\Gamma(C_R, V_i^R)\) are finite
  over \(R[t]\), with \(t\) acting as multiplication by the relative coordinate
  \(t_i^R\) (\ref{def:mulSectionEnd}).
\end{theorem}
\begin{proof}
  \leanok
  The field-level chart lattice is finite over \(k[t]\)
  (\ref{thm:moduleFinite_aeval_fiberCoord}); its base change to \(R\) is finite over
  \(R[t]\) (\ref{thm:moduleFinite_aeval_baseChange}). The sections base change
  \(R \otimes_k \Gamma(C, V_i) \cong \Gamma(C_R, V_i^R)\)
  (\ref{def:relSectionsBaseChange}) intertwines the base-changed multiplication
  endomorphism \(\mathrm{id} \otimes (t_i \cdot)\) with multiplication by \(t_i^R\):
  on pure tensors, \(a \otimes t_i s \mapsto \mathrm{pr}_2^{\sharp}(a)\,
  \mathrm{pr}_1^{\sharp}(t_i s) = t_i^R \cdot \bigl(\mathrm{pr}_2^{\sharp}(a)\,
  \mathrm{pr}_1^{\sharp}(s)\bigr)\), since \(\mathrm{pr}_1^{\sharp}\) is multiplicative
  (\ref{def:relFiberCoord}). Chart-lattice finiteness transports along the equivariant
  equivalence (\ref{lem:aevalCongr}).
\end{proof}

\begin{theorem}[Freeness of the relative section modules]
  \label{thm:free_relSections}
  \lean{AlgebraicGeometry.free_relSections}
  \uses{def:relSectionsBaseChange}
  \leanok
  For every quasi-compact quasi-separated open \(V \subseteq C\) and every commutative
  \(k\)-algebra \(R\), the \(R\)-module \(\Gamma(C_R, \mathrm{pr}_1^{-1}V)\) is free:
  a \(k\)-basis of \(\Gamma(C, V)\) becomes an \(R\)-basis through the sections base
  change (\ref{def:relSectionsBaseChange}). This feeds the flatness and projectivity
  hypotheses of the engine: all three section modules of the pinned relative cover are
  free.
\end{theorem}
\begin{proof}
  \leanok
  \(\Gamma(C, V)\) is a free \(k\)-module (\(k\) is a field), so
  \(R \otimes_k \Gamma(C, V)\) is a free \(R\)-module, and freeness transports along
  the \(R\)-linear equivalence of \ref{def:relSectionsBaseChange}.
\end{proof}

\section{The rigid engine on the relative twisted sheaf}
\label{sec:rel_twist_rigid_engine}

The keystones: the engine of Section~\ref{sec:rigid_engine_assembly} fired on the
relative twisted sheaf \(F_g\) on the base change of the pinned cover, with every
hypothesis discharged from the preceding two sections --- and the base-change clause
threaded, through the term identifications of Section~\ref{sec:relative_h1_base_change},
onto \(H^0\) of the base-changed sheaf on the nose.

One staging note, recorded here because it is the honest state of the statements: the
engine's vanishing hypothesis is consumed in \emph{complex form} --- vanishing of the
residue-field fibres of \(H^1\) of the two-lattice pair of \(F_g\). Its sheaf-level
discharge (identifying the glued fibre sheaf with the divisor sheaf of a witness and
citing the fibrewise large-twist vanishing of Chapter~\ref{chap:RiemannRoch}), and the
rank export \(\dim_{\kappa(\mathfrak p)} H^0 \otimes \kappa(\mathfrak p) = \deg +
\chi\), are deliberately staged behind a later seam and are \emph{not} claimed by the
statements below; consumers supply the fibre hypothesis.

Throughout: \(k\) a field, \(C\) the challenge curve, \(\pi : C \to \PP^1\) finite,
\(R\) a commutative \(k\)-algebra, and \(g\) a unit cocycle on the overlap of the
base-changed pinned cover \((V_0^R, V_1^R)\) of \(C_R\), with relative twisted sheaf
\(F_g\) (\ref{def:relTwistSheaf}).

\begin{definition}[The pair data of the relative twisted sheaf]
  \label{def:relTwistPairData}
  \lean{AlgebraicGeometry.relTwistSheaf.instQcohOn₀,
    AlgebraicGeometry.relTwistSheaf.instQcohOn₁, AlgebraicGeometry.relTwistPairData}
  \uses{def:relTwistSheaf, def:twistPairData, thm:twistSheaf_qcohOn, def:relFiberCoord,
    thm:relCover_inf_eq_basicOpen, thm:relFiberCoord_mul, def:fiberTwoCover}
  \leanok
  The relative twisted sheaf is packaged quasi-coherently on both base-changed charts
  (\ref{thm:twistSheaf_qcohOn}, read on the cover of \(C_R\)), and the relative chart
  coordinates \((t_0^R, t_1^R)\) satisfy the two hypotheses of \ref{def:twistPairData}
  on the base-changed pinned cover: the overlap-as-basic-open identifications
  (\ref{thm:relCover_inf_eq_basicOpen}) and the mutual-inverse relation
  (\ref{thm:relFiberCoord_mul}). This yields the two-cover pair data of \(F_g\), and
  with it the two-lattice pair of the relative twisted sheaf that the engine consumes.
\end{definition}

\begin{theorem}[Chart-lattice finiteness of the relative twisted pair]
  \label{thm:moduleFinite_aeval_relTwistPair}
  \lean{AlgebraicGeometry.moduleFinite_aeval'_relTwistPair_t₀,
    AlgebraicGeometry.moduleFinite_aeval'_relTwistPair_t₁}
  \uses{def:relTwistPairData, thm:moduleFinite_aeval_twistPair,
    thm:moduleFinite_aeval_relFiberCoord}
  \leanok
  If \(R\) acts through the structure factorization of \(\pi\) (the hypothesis of
  \ref{thm:fiberPolyHom_algebraMap}), the pair of the relative twisted sheaf
  (\ref{def:relTwistPairData}) has finite lattices over \(R[t]\).
\end{theorem}
\begin{proof}
  \leanok
  The relative E-i gives finiteness of the structure-sheaf chart lattices at the
  relative coordinates (\ref{thm:moduleFinite_aeval_relFiberCoord}); the twisted pair's
  lattices are trivialisation-transports of these
  (\ref{thm:moduleFinite_aeval_twistPair}).
\end{proof}

\begin{theorem}[Freeness of the twisted section modules on the pinned relative cover]
  \label{thm:free_relTwistSections}
  \lean{AlgebraicGeometry.free_relTwistSections₀, AlgebraicGeometry.free_relTwistSections₁,
    AlgebraicGeometry.free_relTwistSectionsOverlap}
  \uses{thm:free_relSections, thm:free_twistSheafSections, def:fiberTwoCover,
    def:relTwistPairData}
  \leanok
  The three section modules of the pair of the relative twisted sheaf --- the two
  charts and the overlap --- are free \(R\)-modules.
\end{theorem}
\begin{proof}
  \leanok
  The charts and the overlap of the pinned cover are affine
  (\ref{def:fiberTwoCover}), in particular quasi-compact and quasi-separated, so the
  structure-sheaf sections of their base changes are free
  (\ref{thm:free_relSections}); the twisted sections are trivialisation-equivalent to
  them (\ref{thm:free_twistSheafSections}).
\end{proof}

\begin{theorem}[The rigid engine on the relative twisted sheaf]
  \label{thm:relTwistRigidEngine}
  \lean{AlgebraicGeometry.relTwistRigidEngine}
  \uses{thm:twoCoverPair_rigidEngine, def:relTwistPairData,
    thm:moduleFinite_aeval_relTwistPair, thm:free_relTwistSections, lem:relCover_charts}
  \leanok
  \source{kleiman-picard}
  Let \(R\) be Noetherian. If every residue-field fibre of \(H^1\) of the pair of
  \(F_g\) vanishes,
  \[
    H^1(\text{pair}) \otimes_R \kappa(\mathfrak p) = 0 \quad \text{for every prime }
      \mathfrak p \subseteq R,
  \]
  then
  \[
    H^1\bigl(C_R, F_g\bigr) = 0, \qquad \text{and } H^0\bigl(C_R, F_g\bigr)
      \text{ is a finite projective } R\text{-module}.
  \]
  Every other hypothesis of the abstract engine is discharged: this is the curve-lite
  Kleiman criterion, (v)\,\(\Rightarrow\)\,(i), on the relative twisted sheaf. The
  fibre hypothesis remains in complex form (see the staging note at the head of this
  section).
\end{theorem}
\begin{proof}
  \leanok
  The base-changed pinned cover is an affine two-cover of \(C_R\)
  (\ref{lem:relCover_charts}); the pair data is \ref{def:relTwistPairData}; the chart
  lattices are finite (\ref{thm:moduleFinite_aeval_relTwistPair}); the section modules
  are free (\ref{thm:free_relTwistSections}), so the product of the chart modules is
  flat and the overlap module is projective. Fire the sheaf-level engine
  (\ref{thm:twoCoverPair_rigidEngine}).
\end{proof}

\begin{lemma}[Fibrewise vanishing propagates to the pair]
  \label{lem:relTwist_subsingleton_pairH1}
  \lean{AlgebraicGeometry.relTwist_subsingleton_pairH1}
  \uses{thm:moduleFinite_aeval_relTwistPair, thm:twoLattice_coh1,
    thm:fibrewise_vanishing_propagates}
  \leanok
  With no Noetherian hypothesis on \(R\): if every residue-field fibre of \(H^1\) of
  the pair of \(F_g\) vanishes, then \(H^1\) of the pair vanishes. (Consumers holding
  the fibrewise hypothesis use this to feed the two clauses below, which are stated on
  the vanishing locus.)
\end{lemma}
\begin{proof}
  \leanok
  \(H^1\) of the pair is a finite \(R\)-module by COH-1
  (\ref{thm:twoLattice_coh1}, with the finite lattices of
  \ref{thm:moduleFinite_aeval_relTwistPair}); fibrewise vanishing of a finite module
  propagates by Nakayama (\ref{thm:fibrewise_vanishing_propagates}).
\end{proof}

\begin{theorem}[The openness export on the relative twisted sheaf]
  \label{thm:relTwistRigidEngine_isOpen}
  \lean{AlgebraicGeometry.relTwistRigidEngine_isOpen_vanishing}
  \uses{thm:twoCoverPair_isOpen_vanishing, thm:moduleFinite_aeval_relTwistPair}
  \leanok
  \source{kleiman-picard}
  With no Noetherian hypothesis on \(R\), the fibrewise-vanishing locus
  \(\{\mathfrak p \in \Spec R : H^1(\text{pair of } F_g) \otimes_R
  \kappa(\mathfrak p) = 0\}\) is open in \(\Spec R\) --- the strata over which the
  engine fires.
\end{theorem}
\begin{proof}
  \leanok
  The openness export of the abstract engine
  (\ref{thm:twoCoverPair_isOpen_vanishing}), with the finite lattices of
  \ref{thm:moduleFinite_aeval_relTwistPair}.
\end{proof}

\begin{definition}[The module-coefficient clause on the relative twisted sheaf]
  \label{def:relTwistH0TensorEquiv}
  \lean{AlgebraicGeometry.relTwistH0TensorEquiv}
  \uses{def:twoCoverPair_h0TensorEquiv, thm:free_relTwistSections, def:relTwistPairData}
  \leanok
  \source{kleiman-picard}
  On the vanishing locus (\(H^1\) of the pair of \(F_g\) trivial), for every
  \(R\)-module \(P\) there is an \(R\)-linear equivalence
  \[
    H^0\bigl(C_R, F_g\bigr) \otimes_R P \;\cong\;
      \ker\bigl(\delta_{F_g} \otimes_R P\bigr),
  \]
  \(\delta_{F_g}\) the twisted two-cover differential: formation of the twisted
  \(H^0\) commutes with all module coefficients (the curve-lite eq.\ Q).
\end{definition}
\begin{proof}
  \leanok
  The abstract module-coefficient clause (\ref{def:twoCoverPair_h0TensorEquiv}), the
  flatness of the overlap module coming from its freeness
  (\ref{thm:free_relTwistSections}).
\end{proof}

\begin{definition}[The ring-map clause on the relative twisted sheaf, abstract half]
  \label{def:relTwistH0BaseChangeEquiv}
  \lean{AlgebraicGeometry.relTwistH0BaseChangeEquiv}
  \uses{def:twoCoverPair_h0BaseChangeEquiv, thm:free_relTwistSections, def:relTwistPairData}
  \leanok
  On the vanishing locus, for every commutative \(R\)-algebra \(R'\) there is an
  \(R'\)-linear equivalence
  \[
    R' \otimes_R H^0\bigl(C_R, F_g\bigr) \;\cong\;
      \ker\bigl(\delta_{F_g} \otimes_R R'\bigr).
  \]
\end{definition}
\begin{proof}
  \leanok
  The abstract ring-map clause (\ref{def:twoCoverPair_h0BaseChangeEquiv}), with
  flatness of the overlap module from freeness (\ref{thm:free_relTwistSections}).
\end{proof}

\begin{lemma}[The twisted differential in trivialised coordinates]
  \label{lem:twistTriv_pairDiff}
  \lean{AlgebraicGeometry.twistTriv₀_pairDiff}
  \uses{def:twistTriv, lem:twistTriv_res, lem:twistTriv_inf_eq}
  \leanok
  For any twisted sheaf \(F_g\) on opens \(V_0, V_1\): under the chart-0
  trivialisation of the overlap, the twisted restriction-difference map
  \((p_0, p_1) \mapsto p_0|_{\cap} - p_1|_{\cap}\) becomes
  \[
    (s_0, s_1) \longmapsto s_0|_{\cap} - g \cdot s_1|_{\cap},
    \qquad s_i = \mathrm{triv}_i(p_i) :
  \]
  the defect-map shape of \ref{def:twistSections}, with the cocycle carrying the
  chart-1 term across.
\end{lemma}
\begin{proof}
  \leanok
  The trivialisations commute with restriction (\ref{lem:twistTriv_res}), so
  \(\mathrm{triv}_0(p_0|_{\cap}) = s_0|_{\cap}\); and on the overlap the chart-0
  trivialisation of \(p_1|_{\cap}\) is \(g\) times its chart-1 trivialisation
  (\ref{lem:twistTriv_inf_eq}), which is \(s_1|_{\cap}\), again by
  \ref{lem:twistTriv_res}. Subtract.
\end{proof}

\begin{definition}[CBC-1 for the twisted complex, assembled]
  \label{def:relTwistDomBaseChange}
  \lean{AlgebraicGeometry.relTwistDomBaseChange,
    AlgebraicGeometry.twistTriv₀_relTwistTermBaseChange₀,
    AlgebraicGeometry.twistTriv₁_relTwistTermBaseChange₁,
    AlgebraicGeometry.twistTriv₀_relTwistOverlapBaseChange}
  \uses{def:relTwistTermBaseChange, thm:relTermBaseChange, def:relSectionsMap,
    def:twistTriv, lem:relDiffBaseChange}
  \leanok
  Let \(R \to R'\) be a homomorphism of commutative \(k\)-algebras, \(D\) an affine
  two-chart cover of \(C\), \(g\) a unit cocycle on the base-changed cover of \(C_R\)
  and \(g' = \rho^{\sharp}(g)\) its base change. The product of the two chart term
  equivalences of \ref{def:relTwistTermBaseChange} is an \(R'\)-linear equivalence
  \[
    R' \otimes_R \bigl(F_g(V_0^R) \times F_g(V_1^R)\bigr) \;\cong\;
      F_{g'}(V_0^{R'}) \times F_{g'}(V_1^{R'}),
  \]
  the degree-zero term of the twisted complex base-changed. In trivialised coordinates
  each term equivalence computes, on a pure tensor \(r' \otimes p\), as
  \(r' \cdot \rho^{\sharp}\bigl(\mathrm{triv}(p)\bigr)\) --- the structure-sheaf term
  base change of \ref{thm:relTermBaseChange} (at the overlap, the codomain equivalence
  of \ref{lem:relDiffBaseChange}) read through the trivialisations.
\end{definition}
\begin{proof}
  \leanok
  Each twisted term equivalence is by construction
  (\ref{def:relTwistTermBaseChange}) the conjugate of the corresponding
  structure-sheaf term equivalence by the chart trivialisations over \(R\) and
  \(R'\); the displayed formula on pure tensors is the formula of
  \ref{thm:relTermBaseChange} for the structure sheaf, conjugated. The product of two
  \(R'\)-linear equivalences is one.
\end{proof}

\begin{theorem}[The twisted \(\delta\)-naturality square]
  \label{thm:relTwistDiffBaseChange}
  \lean{AlgebraicGeometry.relTwistDiff, AlgebraicGeometry.relTwistDiff_apply,
    AlgebraicGeometry.relTwistPair_diff, AlgebraicGeometry.relTwistDiffBaseChange,
    AlgebraicGeometry.relTwistPairDiffBaseChange}
  \uses{lem:twistTriv_pairDiff, def:relTwistDomBaseChange, def:relCocycleBaseChange,
    lem:relSectionsMap_props, def:relTwistTermBaseChange, def:relTwistSheaf}
  \leanok
  In the setting of \ref{def:relTwistDomBaseChange}, write \(\delta_g\) for the
  twisted restriction-difference map over \(R\) and \(\delta_{g'}\) for the one over
  \(R'\). Under the CBC-1 term identifications --- the domain equivalence of
  \ref{def:relTwistDomBaseChange} and the overlap equivalence of
  \ref{def:relTwistTermBaseChange} --- the base change of the twisted differential is
  carried to the twisted differential of the base-changed cocycle:
  \[
    \mathrm{overlap}\circ\bigl(\delta_g \otimes_R R'\bigr)
      \;=\; \delta_{g'} \circ \mathrm{dom} .
  \]
  This is the cocycle-conjugated analogue of the untwisted \(\delta\)-naturality
  (\ref{lem:relDiffBaseChange}); on the pinned cover, \(\delta_g\) is on the nose the
  differential of the pair of the relative twisted sheaf, so the square also reads on
  the pairs.
\end{theorem}
\begin{proof}
  \leanok
  Both composites are additive, so compare them on \(r' \otimes (p_0, p_1)\). Read
  everything in chart-0 trivialised coordinates. By \ref{lem:twistTriv_pairDiff} the
  twisted differential is \((s_0, s_1) \mapsto s_0|_{\cap} - g \cdot s_1|_{\cap}\), so
  along the top and right the tensor goes to
  \[
    r' \cdot \rho^{\sharp}\bigl(s_0|_{\cap}\bigr)
      - r' \cdot \rho^{\sharp}(g)\,\rho^{\sharp}\bigl(s_1|_{\cap}\bigr),
  \]
  by \ref{def:relTwistDomBaseChange} and multiplicativity of \(\rho^{\sharp}\). Along
  the left and bottom it goes to
  \(\bigl(r' \cdot \rho^{\sharp}s_0\bigr)\big|_{\cap} - g' \cdot \bigl(r' \cdot
  \rho^{\sharp}s_1\bigr)\big|_{\cap}\), where \(g' = \rho^{\sharp}(g)\)
  (\ref{def:relCocycleBaseChange}). The two agree because \(\rho^{\sharp}\) commutes
  with restriction (\ref{lem:relSectionsMap_props}), the \(R'\)-action commutes with
  restriction, and the \(g'\)-factor commutes with the \(R'\)-scalar (commutative
  ring). The pair form on the pinned cover is the same identity, the pair's
  differential being definitionally the twisted restriction-difference map.
\end{proof}

\begin{theorem}[\(H^1\) of the twisted sheaf vanishes after base change]
  \label{thm:relTwist_h1_baseChange}
  \lean{AlgebraicGeometry.relTwist_surjective_diff_baseChange,
    AlgebraicGeometry.relTwist_subsingleton_h1_baseChange}
  \uses{thm:relTwistDiffBaseChange, lem:twoCoverPair_surjective_diff, lem:kerCongr,
    def:twoCoverPair_h0h1, lem:twoLattice_range_diff, def:relTwistPairData}
  \leanok
  On the vanishing locus (\(H^1\) of the pair of \(F_g\) over \(R\) trivial), for
  every homomorphism \(R \to R'\) of commutative \(k\)-algebras: the twisted
  differential over \(R'\) at the base-changed cocycle \(g'\) is surjective, and
  \[
    H^1\bigl(C_{R'},\, F_{g'}\bigr) \;=\; 0 .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Over \(R\) the twisted differential is surjective
  (\ref{lem:twoCoverPair_surjective_diff}); tensoring with \(R'\) preserves
  surjectivity (right exactness), and surjectivity transports across the
  \(\delta\)-naturality square (\ref{thm:relTwistDiffBaseChange}) by
  \ref{lem:kerCongr}. So \(\delta_{g'}\) is surjective; hence \(H^1\) of the pair of
  \(F_{g'}\) --- its cokernel (\ref{lem:twoLattice_range_diff}) --- is trivial, and
  the degree-one carrier over \(R'\) (\ref{def:twoCoverPair_h0h1}, for the pair data
  of \(F_{g'}\), \ref{def:relTwistPairData}) transports the vanishing to
  \(H^1(C_{R'}, F_{g'})\).
\end{proof}

\begin{definition}[\(H^0\) base change on the nose]
  \label{def:relTwistH0BaseChange}
  \lean{AlgebraicGeometry.relTwistH0BaseChange}
  \uses{def:relTwistH0BaseChangeEquiv, lem:kerCongr, thm:relTwistDiffBaseChange,
    def:twoCoverPair_h0h1, def:relTwistPairData}
  \leanok
  \source{kleiman-picard}
  On the vanishing locus, for every homomorphism \(R \to R'\) of commutative
  \(k\)-algebras there is an \(R'\)-linear equivalence
  \[
    R' \otimes_R H^0\bigl(C_R, F_g\bigr) \;\cong\;
      H^0\bigl(C_{R'},\, F_{g'}\bigr), \qquad g' = \rho^{\sharp}(g) :
  \]
  formation of the twisted \(H^0\) commutes on the nose with every change of the test
  ring --- the curve-lite form of Kleiman's clause (iii) at ring maps.
\end{definition}
\begin{proof}
  \leanok
  Compose three equivalences: the abstract ring-map clause
  \(R' \otimes_R H^0(C_R, F_g) \cong \ker(\delta_g \otimes_R R')\)
  (\ref{def:relTwistH0BaseChangeEquiv}); the kernel transport
  \(\ker(\delta_g \otimes_R R') \cong \ker(\delta_{g'})\) along the twisted
  \(\delta\)-naturality square (\ref{lem:kerCongr},
  \ref{thm:relTwistDiffBaseChange}); and the inverse of the degree-zero carrier of the
  pair of \(F_{g'}\) (\ref{def:twoCoverPair_h0h1}, \ref{def:relTwistPairData}),
  \(\ker(\delta_{g'}) \cong H^0(C_{R'}, F_{g'})\).
\end{proof}

\section{Base-field invariance of \(H^0\), \(H^1\) and the genus}
\label{sec:h1_base_field_invariance}

Fix a field \(k\) and an object \(C \in \Over(\Spec k)\). Section
\ref{sec:relative_h1_base_change} base-changed the two-cover complex along a
homomorphism \(R \to R'\) of test rings; this section runs the same mechanism once more
with the \emph{absolute} curve as source, for an arbitrary commutative \(k\)-algebra
\(R\): the two-term \v{C}ech complex of an affine two-cover of \(C\) base-changes
termwise by the free identification \ref{def:relSectionsBaseChange}, and \(H^1\), being
its cokernel, commutes with any base change by right-exactness. Specialised to a field
extension \(R = K\), this yields \(H^i(C, \struct C) \otimes_k K \cong
H^i(C_K, \struct{C_K})\) for \(i = 0, 1\) and the base-field invariance of the genus.
No flatness, semicontinuity or exchange argument is used.

\begin{lemma}[Pullback of sections commutes with restriction]
  \label{lem:relPullbackSection_resHom}
  \lean{AlgebraicGeometry.relPullbackSection_resHom}
  \uses{def:relSectionsBaseChange}
  \leanok
  Let \(R\) be a commutative \(k\)-algebra and \(W \leq V\) opens of \(C\). For a
  section \(s \in \Gamma(C, V)\), restricting on \(C\) and then pulling back along the
  first projection \(\mathrm{pr}_1 : C_R \to C\) agrees with pulling back and then
  restricting on the relative curve:
  \[
    \mathrm{pr}_1^{\sharp}\bigl(s|_W\bigr)
      = \bigl(\mathrm{pr}_1^{\sharp} s\bigr)\big|_{\mathrm{pr}_1^{-1} W}.
  \]
\end{lemma}
\begin{proof}
  \leanok
  Both sides are the image of \(s\) under the map of sections induced by
  \(\mathrm{pr}_1\) from \(V\) to \(\mathrm{pr}_1^{-1}W \subseteq \mathrm{pr}_1^{-1}V\):
  pullback along a morphism of schemes is compatible with restriction on source and
  target.
\end{proof}

\begin{definition}[Termwise base change of the two-cover complex of the curve]
  \label{def:curveDiffTermsBaseChange}
  \lean{AlgebraicGeometry.curveDiffDomBaseChange, AlgebraicGeometry.curveDiffCodBaseChange,
    AlgebraicGeometry.curveDiffCodBaseChange_tmul}
  \uses{def:relSectionsBaseChange, def:relCover, lem:relCover_inf, def:AffineTwoCover}
  \leanok
  Let \(D = (V_0, V_1)\) be an affine two-cover of \(C\) and \(R\) a commutative
  \(k\)-algebra. The two terms of the two-cover complex of \(C\) base-change freely by
  \ref{def:relSectionsBaseChange}: an \(R\)-linear equivalence
  \[
    R \otimes_k \bigl(\Gamma(C, V_0) \times \Gamma(C, V_1)\bigr)
    \;\cong\;
    \Gamma(C_R, V_0^R) \times \Gamma(C_R, V_1^R)
  \]
  on the degree-zero term (product of the two chart identifications; the charts are
  affine, hence qcqs), and
  \[
    R \otimes_k \Gamma(C, V_0 \cap V_1) \;\cong\; \Gamma(C_R, V_0^R \cap V_1^R)
  \]
  on the overlap term (the overlap of affines is qcqs, and
  \(V_0^R \cap V_1^R = \mathrm{pr}_1^{-1}(V_0 \cap V_1)\) by \ref{lem:relCover_inf}),
  where \(V_i^R = \mathrm{pr}_1^{-1} V_i\). On a pure tensor the overlap identification
  is \(a \otimes s \mapsto a \cdot \mathrm{pr}_1^\sharp(s)\).
\end{definition}

\begin{theorem}[The base-changed difference map is the relative difference map]
  \label{thm:curveDiffBaseChange}
  \lean{AlgebraicGeometry.curveDiffBaseChange, AlgebraicGeometry.curveDiffBaseChange_range}
  \uses{def:curveDiffTermsBaseChange, def:TwoCover_diff, lem:relPullbackSection_resHom}
  \leanok
  Under the two term equivalences of \ref{def:curveDiffTermsBaseChange}, the base
  change \(\mathrm{id}_R \otimes \mathrm{diff}\) of the two-cover
  restriction-difference map of \(C\) (\ref{def:TwoCover_diff}) is carried to the
  restriction-difference map of the relative curve \(C_R\) with its base-changed cover.
  In particular the overlap-term equivalence maps
  \(\mathrm{range}(\mathrm{id}_R \otimes \mathrm{diff})\) onto
  \(\mathrm{range}(\mathrm{diff}_R)\).
\end{theorem}
\begin{proof}
  \leanok
  Both sides are \(R\)-linear, so it suffices to check on a pure tensor
  \(a \otimes (s_0, s_1)\). The left leg gives
  \(a \cdot \mathrm{pr}_1^\sharp\bigl(s_0|_\cap - s_1|_\cap\bigr)\). The right leg
  first sends \(a \otimes (s_0, s_1)\) to
  \((a \cdot \mathrm{pr}_1^\sharp s_0,\, a \cdot \mathrm{pr}_1^\sharp s_1)\), then takes
  the difference of restrictions on \(C_R\). By
  \ref{lem:relPullbackSection_resHom}, \(\mathrm{pr}_1^\sharp(s_i|_\cap) =
  (\mathrm{pr}_1^\sharp s_i)|_{\cap_R}\); restriction on \(C_R\) is \(R\)-linear (the
  \(R\)-action is pullback of constants along \(\mathrm{pr}_2\), itself compatible with
  restriction), so the right leg gives
  \(a \cdot \bigl((\mathrm{pr}_1^\sharp s_0)|_{\cap_R} -
  (\mathrm{pr}_1^\sharp s_1)|_{\cap_R}\bigr)\), the same element. The range statement
  follows since both term equivalences are surjective.
\end{proof}

\begin{theorem}[Base change of the two-cover \(H^1\) cokernel of the curve]
  \label{thm:curveH1CokBaseChange}
  \lean{AlgebraicGeometry.curveH1CokBaseChange, AlgebraicGeometry.curveH1CokBaseChange_tmul_mk}
  \uses{thm:quot_range_baseChange, thm:curveDiffBaseChange, def:TwoCover_H1Cok}
  \leanok
  For every commutative \(k\)-algebra \(R\) there is an \(R\)-linear equivalence
  \[
    R \otimes_k \mathrm{H1Cok}(C; V_0, V_1) \;\cong\;
      \mathrm{H1Cok}(C_R; V_0^R, V_1^R),
  \]
  sending \(a \otimes [s]\) to \([a \cdot \mathrm{pr}_1^\sharp(s)]\). No flatness of
  \(R\) is needed.
\end{theorem}
\begin{proof}
  \leanok
  \(\mathrm{H1Cok}\) is the cokernel of \(\mathrm{diff}\) (\ref{def:TwoCover_H1Cok}),
  and base change commutes with cokernels (\ref{thm:quot_range_baseChange}):
  \(R \otimes_k \mathrm{H1Cok}(C) \cong (R \otimes_k \Gamma(C, V_0 \cap V_1)) /
  \mathrm{range}(\mathrm{id}_R \otimes \mathrm{diff})\). Now transport along the
  overlap-term equivalence of \ref{def:curveDiffTermsBaseChange}, which by
  \ref{thm:curveDiffBaseChange} carries the range of
  \(\mathrm{id}_R \otimes \mathrm{diff}\) onto the range of the relative difference
  map; the induced map of quotients is the displayed equivalence, and its effect on the
  class of a pure tensor is read off the overlap identification.
\end{proof}

\begin{theorem}[Cohomology commutes with base change in degree one, from the absolute
  curve]
  \label{thm:curveH1BaseChange}
  \lean{AlgebraicGeometry.curveH1BaseChange}
  \uses{thm:TwoCover_h1CokEquiv, thm:curveH1CokBaseChange, def:relTwoCoverH1,
    def:moduleKSheaf, def:HModule}
  \leanok
  Let \(D\) be an affine two-cover of \(C\) and \(R\) a commutative \(k\)-algebra.
  There is an \(R\)-linear equivalence
  \[
    R \otimes_k H^1\bigl(C, \struct{C}\bigr) \;\cong\;
      H^1\bigl(C_R, \struct{C_R}\bigr)
  \]
  on the cohomology carriers.
\end{theorem}
\begin{proof}
  \leanok
  Compose: the base change of the absolute cokernel bridge
  \(H^1(C, \struct C) \cong \mathrm{H1Cok}(C)\) (\ref{thm:TwoCover_h1CokEquiv},
  tensored with \(R\)); the cokernel base change
  \(R \otimes_k \mathrm{H1Cok}(C) \cong \mathrm{H1Cok}(C_R)\)
  (\ref{thm:curveH1CokBaseChange}); and the inverse of the relative cokernel bridge
  \(H^1(C_R, \struct{C_R}) \cong \mathrm{H1Cok}(C_R)\) (\ref{def:relTwoCoverH1}).
\end{proof}

\begin{definition}[A pinned affine two-cover of the challenge curve]
  \label{def:curveCover}
  \lean{AlgebraicGeometry.curveCover}
  \uses{thm:AffineTwoCover_nonempty_of_curve}
  \leanok
  For the challenge curve \(C\) (proper, smooth of relative dimension one,
  geometrically irreducible over \(k\)), fix once and for all an affine two-chart cover
  of \(C\), which exists by \ref{thm:AffineTwoCover_nonempty_of_curve}; all base-change
  equivalences below are built on this one cover.
\end{definition}

\begin{theorem}[Cohomology commutes with base change in degree zero]
  \label{thm:curveH0BaseChange}
  \lean{AlgebraicGeometry.curveH0BaseChange}
  \uses{def:moduleKSheafHZero, def:relSectionsBaseChange}
  \leanok
  Let \(C\) be the challenge curve and \(R\) a commutative \(k\)-algebra. There is an
  \(R\)-linear equivalence
  \[
    R \otimes_k H^0\bigl(C, \struct C\bigr) \;\cong\; H^0\bigl(C_R, \struct{C_R}\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both carriers are global sections (\ref{def:moduleKSheafHZero}, over \(k\) and over
  \(R\)). The total space \(\top \subseteq C\) is quasi-compact (\(C\) is proper over a
  field) and quasi-separated, so the free sections base change
  \ref{def:relSectionsBaseChange} applies at \(V = \top\):
  \(R \otimes_k \Gamma(C, \top) \cong \Gamma(C_R, \top)\). Conjugating by the two
  degree-zero identifications gives the claim.
\end{proof}

\begin{theorem}[\(H^1\) base-field invariance]
  \label{thm:h1BaseFieldEquiv}
  \lean{AlgebraicGeometry.h1BaseFieldEquiv}
  \uses{thm:curveH1BaseChange, def:curveCover, thm:baseChangeCurve_bundle}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be the challenge curve over \(k\) and \(K/k\) a field extension. Then
  \[
    H^1\bigl(C, \struct C\bigr) \otimes_k K \;\cong\; H^1\bigl(C_K, \struct{C_K}\bigr)
  \]
  as \(K\)-vector spaces, where \(C_K\) is the base-changed curve regarded over
  \(\Spec K\) (\ref{thm:baseChangeCurve_bundle}).
\end{theorem}
\begin{proof}
  \leanok
  Specialise \ref{thm:curveH1BaseChange} to the algebra \(R = K\) and the pinned cover
  of \ref{def:curveCover}; the relative curve \(C_K\) over \(\Spec K\) is the
  base-changed curve of \ref{thm:baseChangeCurve_bundle}.
\end{proof}

\begin{theorem}[\(H^0\) base-field invariance]
  \label{thm:h0BaseFieldEquiv}
  \lean{AlgebraicGeometry.h0BaseFieldEquiv}
  \uses{thm:curveH0BaseChange, thm:baseChangeCurve_bundle}
  \leanok
  In the setting of \ref{thm:h1BaseFieldEquiv},
  \(H^0(C, \struct C) \otimes_k K \cong H^0(C_K, \struct{C_K})\) as \(K\)-vector
  spaces.
\end{theorem}
\begin{proof}
  \leanok
  Specialise \ref{thm:curveH0BaseChange} to \(R = K\).
\end{proof}

\begin{theorem}[The scalar identities of base-field invariance]
  \label{thm:finrank_h1_baseField}
  \lean{AlgebraicGeometry.finrank_h1_baseField, AlgebraicGeometry.finrank_h0_baseField,
    AlgebraicGeometry.finrank_h1_baseField_eq_genus}
  \uses{thm:h1BaseFieldEquiv, thm:h0BaseFieldEquiv, def:genus}
  \leanok
  For the challenge curve \(C\) over \(k\) and any field extension \(K/k\),
  \[
    \dim_K H^1\bigl(C_K, \struct{C_K}\bigr) = \dim_k H^1\bigl(C, \struct C\bigr)
      = \genus(C),
    \qquad
    \dim_K H^0\bigl(C_K, \struct{C_K}\bigr) = \dim_k H^0\bigl(C, \struct C\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Extension of scalars multiplies no dimensions:
  \(\dim_K(V \otimes_k K) = \dim_k V\) for any \(k\)-vector space \(V\). Apply this
  across the equivalences of \ref{thm:h1BaseFieldEquiv} and \ref{thm:h0BaseFieldEquiv};
  the \(\genus(C)\) identification is Definition~\ref{def:genus}.
\end{proof}

\begin{theorem}[Base-field invariance of the genus]
  \label{thm:genus_baseField}
  \lean{AlgebraicGeometry.genus_baseField}
  \uses{thm:finrank_h1_baseField, thm:baseChangeCurve_bundle, def:genus}
  \leanok
  Let \(C\) be the challenge curve over \(k\) and \(K/k\) a field extension. The
  base-changed curve \(C_K\), a legal challenge curve over \(K\)
  (\ref{thm:baseChangeCurve_bundle}), satisfies
  \[
    \genus(C_K) = \genus(C).
  \]
\end{theorem}
\begin{proof}
  \leanok
  By Definition~\ref{def:genus} applied over \(K\),
  \(\genus(C_K) = \dim_K H^1(C_K, \struct{C_K})\), which equals \(\genus(C)\) by
  \ref{thm:finrank_h1_baseField}.
\end{proof}

\label{chap:PicardEtale}

For a curve \(C\) over \(k\) and an affine test scheme \(\Spec A\), the \'etale-sheafified
relative Picard group is computed by a single \emph{plus construction}: a class is represented
by a relative Picard class on an \'etale cover of \(\Spec A\) satisfying a descent condition,
and two representatives are identified when they agree on a common refinement. This chapter
constructs that plus, on affine test schemes indexed by a \(k\)-algebra \(A\); we recall from
elsewhere in this project the ambient functor it sheafifies. For an object \(T\) of
\(\Over(\Spec k)\) write \(\mathrm{relPic}(C,T)\) for the relative Picard group of \(C\) at
\(T\) --- the quotient of the Picard group of \(C \otimes T\) by the subgroup of classes pulled
back from \(T\) along the second projection --- a commutative group, with restriction
homomorphisms \(g^{*} \colon \mathrm{relPic}(C,T) \to \mathrm{relPic}(C,T')\) for a morphism
\(g \colon T' \to T\) of \(\Over(\Spec k)\), satisfying \((\id_T)^{*} = \id\) and
\((g \circ h)^{*} = h^{*} \circ g^{*}\). For a commutative \(k\)-algebra \(A\), write \(\Spec A\)
also for the object of \(\Over(\Spec k)\) it determines via the structure morphism
\(\Spec A \to \Spec k\) induced by the \(k\)-algebra structure of \(A\); a homomorphism of
\(k\)-algebras \(A \to A'\) induces, via \(\Spec\), a morphism \(\Spec A' \to \Spec A\) of
\(\Over(\Spec k)\). We abbreviate \(\mathrm{relPic}(C,A) := \mathrm{relPic}(C,\Spec A)\).

\section{The relative Picard group as a quotient}

The group \(\mathrm{relPic}(C,T)\) of the preamble is realised concretely as a quotient of
the \v Cech Picard group of the product: this section records the quotient presentation and
its exact coset relation, the calculus every later rigidification and degree statement
cascades through.

\begin{definition}[The relative Picard group]
  \label{def:relPic}
  \lean{AlgebraicGeometry.picFromBase, AlgebraicGeometry.mem_picFromBase_iff,
    AlgebraicGeometry.relPic, AlgebraicGeometry.relPicMk,
    AlgebraicGeometry.relPicMk_surjective, AlgebraicGeometry.relPicMk_eq_relPicMk_iff}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be an object of \(\Over(\Spec k)\) and \(T\) a test object. Write
  \(H_T \le \Pic(C \otimes T)\) for the subgroup of \v Cech Picard classes \emph{pulled back
  from the base}: the range of \(\mathrm{pr}_2^{*} = \mathrm{snd}^{*} \colon \Pic(T) \to
  \Pic(C \otimes T)\), so \(L \in H_T\) iff \(L = \mathrm{snd}^{*} N\) for some
  \(N \in \Pic(T)\). The \emph{relative Picard group} is the quotient
  \[
    \mathrm{relPic}(C,T) \;:=\; \Pic(C \otimes T) \,/\, H_T ,
  \]
  a commutative group, with surjective projection \(\pi_T \colon \Pic(C \otimes T) \to
  \mathrm{relPic}(C,T)\). The \emph{exact coset relation} holds: \(\pi_T L = \pi_T L'\) iff
  \(L / L' \in H_T\) — a genuine range condition, involving no choice.
\end{definition}
\begin{proof}
  \leanok
  \(H_T\) is the range of a group homomorphism, hence a subgroup, and \(\Pic(C \otimes T)\)
  is commutative, so \(H_T\) is normal and the quotient is a commutative group with a
  surjective projection homomorphism. The coset relation is the defining property of a
  quotient group: two elements have equal images exactly when their ratio lies in the
  subgroup.
\end{proof}

\begin{definition}[Restriction of relative Picard classes]
  \label{def:relPicMap}
  \lean{AlgebraicGeometry.picFromBase_le_comap, AlgebraicGeometry.relPicMap,
    AlgebraicGeometry.relPicMap_mk, AlgebraicGeometry.relPicMap_id,
    AlgebraicGeometry.relPicMap_comp, AlgebraicGeometry.relPicFunctor}
  \uses{def:relPic}
  \leanok
  For a morphism \(g \colon T' \to T\) of test objects, pullback of \v Cech classes along
  \(C \lhd g \colon C \otimes T' \to C \otimes T\) descends to the quotients: a homomorphism
  \(g^{*} \colon \mathrm{relPic}(C,T) \to \mathrm{relPic}(C,T')\) with
  \(g^{*}(\pi_T L) = \pi_{T'}\bigl((C \lhd g)^{*} L\bigr)\). It satisfies
  \((\id_T)^{*} = \id\) and \((h \circ g)^{*} = g'^{*}\)-composition contravariantly, so
  \(T \mapsto \mathrm{relPic}(C,T)\) is a presheaf of commutative groups on
  \(\Over(\Spec k)\) — the relative Picard functor of Grothendieck--Kleiman.
\end{definition}
\begin{proof}
  \leanok
  Well-definedness on cosets: for \(L = \mathrm{snd}_T^{*} N \in H_T\),
  \[
    (C \lhd g)^{*}\,\mathrm{snd}_T^{*} N
      = \bigl(\mathrm{snd}_T \circ (C \lhd g)\bigr)^{*} N
      = (g \circ \mathrm{snd}_{T'})^{*} N
      = \mathrm{snd}_{T'}^{*}(g^{*} N) \in H_{T'},
  \]
  using \(\mathrm{snd}_T \circ (C \lhd g) = g \circ \mathrm{snd}_{T'}\) (the whiskering
  identity of the cartesian product). So the composite
  \(\Pic(C \otimes T) \to \mathrm{relPic}(C,T')\) kills \(H_T\) and factors through the
  quotient. The functor laws follow from
  \(C \lhd \id = \id\) and \(C \lhd (h \circ g) = (C \lhd h) \circ (C \lhd g)\) together
  with functoriality of pullback of \v Cech classes, checked on representatives via the
  computation rule.
\end{proof}

\begin{lemma}[Naturality in the curve]
  \label{lem:relPicMapCurve}
  \lean{AlgebraicGeometry.picFromBase_le_comap_whiskerRight,
    AlgebraicGeometry.relPicMapCurveApp, AlgebraicGeometry.relPicMapCurveApp_mk,
    AlgebraicGeometry.relPicMapCurve, AlgebraicGeometry.relPicMapCurve_app_mk,
    AlgebraicGeometry.relPicMapCurve_id, AlgebraicGeometry.relPicMapCurve_comp,
    AlgebraicGeometry.relPicMapCurveApp_id, AlgebraicGeometry.relPicMapCurveApp_comp,
    AlgebraicGeometry.relPicMap_relPicMapCurveApp,
    AlgebraicGeometry.relPicAlgMap_relPicMapCurveApp}
  \uses{def:relPic, def:relPicMap, def:relPicAlgMap}
  \leanok
  A morphism of curves \(g \colon C' \to C\) over \(\Spec k\) induces, by pullback along
  \(g \rhd T\) on representatives, a natural transformation of relative Picard functors
  \(\mathrm{relPic}(C,-) \to \mathrm{relPic}(C',-)\); the assignment is contravariantly
  functorial in \(g\) on the nose. In particular, at every test object the transports
  satisfy the functor laws, and they commute with restriction along any test morphism ---
  in particular along \(\Spec f\) for a \(k\)-algebra map \(f\) of affine tests.
\end{lemma}
\begin{proof}
  \leanok
  Well-definedness on cosets: \((g \rhd T)^{*}\,\mathrm{snd}_{C,T}^{*} N =
  \mathrm{snd}_{C',T}^{*} N\) since \(\mathrm{snd}_{C,T} \circ (g \rhd T) =
  \mathrm{snd}_{C',T}\). Naturality against a test morphism \(t \colon T' \to T\) is the
  exchange identity \((C' \lhd t) \circ (g \rhd T') = (g \rhd T) \circ (C \lhd t)\) of
  whiskerings, applied to representatives. The functor laws follow from
  \(\id \rhd T = \id\) and \((g' \circ g) \rhd T = (g \rhd T) \circ (g' \rhd T)\).
\end{proof}

\begin{lemma}[Constant curve morphisms kill relative Picard classes]
  \label{lem:relPicMapCurveConstant}
  \lean{AlgebraicGeometry.cechPicMap_toUnit_whiskerRight_mem_picFromBase,
    AlgebraicGeometry.relPicMapCurveApp_toUnit_comp}
  \uses{def:relPic, lem:relPicMapCurve}
  \leanok
  Let \(g \colon C' \to C\) be a morphism of curve bundles over \(\Spec k\) that factors
  through the terminal object \(\Spec k\) of \(\Over(\Spec k)\). Then for every test
  object \(T\) the induced map \(\mathrm{relPic}(C,T) \to \mathrm{relPic}(C',T)\) is
  trivial.
\end{lemma}
\begin{proof}
  \leanok
  Write \(g = e \circ u\) with \(u \colon C' \to \Spec k\) the unique morphism to the
  terminal object and \(e \colon \Spec k \to C\). Pullback along \(g \rhd T\) then factors
  through pullback along \(u \rhd T \colon C' \otimes T \to \Spec k \otimes T\), so it
  suffices to show that every Picard class on \(\Spec k \otimes T\) pulls back along
  \(u \rhd T\) into the subgroup \(H_T\) of classes pulled back from \(T\). The second
  projection \(\mathrm{snd} \colon \Spec k \otimes T \to T\) is the left unitor, hence an
  isomorphism, so an arbitrary class \(X\) on \(\Spec k \otimes T\) is
  \(\mathrm{snd}^{*} N\) for \(N := (\mathrm{snd}^{-1})^{*} X\). Since
  \(\mathrm{snd} \circ (u \rhd T) = \mathrm{snd}_{C',T}\), we get
  \((u \rhd T)^{*} X = (u \rhd T)^{*}\,\mathrm{snd}^{*} N = \mathrm{snd}_{C',T}^{*} N \in
  H_T\). Every pulled-back class therefore lies in \(H_T\) and dies in the quotient
  \(\mathrm{relPic}(C',T)\).
\end{proof}

At the \v Cech level the constant-morphism collapse is sharper than
Lemma~\ref{lem:relPicMapCurveConstant}: a morphism of bundles whose set-range is a
single closed point kills every \v Cech Picard class outright --- before passing to any
quotient --- because it factors through the spectrum of a residue field, whose \v Cech
Picard group is trivial.

\begin{theorem}[Morphisms factoring through a residue field kill \v Cech classes]
  \label{thm:cechPicMap_eq_one_of_factorization}
  \lean{AlgebraicGeometry.cechPicMap_eq_one_of_factorization}
  \leanok
  Let \(K\) be a field, \(D, E\) objects of \(\Over(\Spec K)\), and \(h : D \to E\) a
  morphism of \(\Over(\Spec K)\) whose underlying morphism factors as
  \(D \to \Spec \kappa(x) \to E\) through the canonical morphism from the spectrum of
  the residue field of a point \(x\) of \(E\). Then for every \v Cech Picard class
  \(L \in \Pic(E)\),
  \[
    h^{*}L \;=\; 1 .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Write the factorization as \(h = \iota \circ q\) with
  \(q : D \to \Spec \kappa(x)\) and \(\iota : \Spec \kappa(x) \to E\). Pullback of
  \v Cech Picard classes is functorial, so \(h^{*}L = q^{*}(\iota^{*}L)\). The
  underlying space of \(\Spec \kappa(x)\) is a single point (the spectrum of a field),
  and the \v Cech Picard group of a scheme whose space has at most one point is
  trivial: any two members of a pointed cover coincide as opens --- each is determined
  by whether it is empty, and members contain their base points --- so every unit
  \v Cech \(1\)-cocycle lives on a cover by a single open, where it is a coboundary.
  Hence \(\iota^{*}L = 1\), and \(q^{*}\), a homomorphism, gives
  \(h^{*}L = q^{*}(1) = 1\).
\end{proof}

\begin{corollary}[Morphisms with one-point range kill \v Cech classes]
  \label{cor:cechPicMap_eq_one_of_range_eq_singleton}
  \lean{AlgebraicGeometry.cechPicMap_eq_one_of_range_eq_singleton}
  \uses{thm:cechPicMap_eq_one_of_factorization, thm:hom_factors_fromSpecResidueField}
  \leanok
  Let \(K\) be a field, \(D, E\) objects of \(\Over(\Spec K)\) with \(D\) reduced, and
  \(h : D \to E\) a morphism of \(\Over(\Spec K)\) whose underlying morphism is
  quasi-compact and whose set-range is a single closed point \(x\) of \(E\). Then
  \(h^{*}L = 1\) for every \v Cech Picard class \(L \in \Pic(E)\).
\end{corollary}
\begin{proof}
  \leanok
  By the factorization through the residue field of a closed point
  (\ref{thm:hom_factors_fromSpecResidueField}), the underlying morphism of \(h\)
  factors as \(D \to \Spec \kappa(x) \to E\). Apply
  \ref{thm:cechPicMap_eq_one_of_factorization}.
\end{proof}

\section{Presented \'etale covers of an affine scheme}

Throughout this section \(A\) is a commutative ring (no field or \(k\)-algebra structure is
needed here). An \'etale cover of \(\Spec A\) in the sense consumed by the plus construction is
a faithfully flat \'etale \(A\)-algebra; to keep the index of covers of a fixed base
small --- which is what makes the plus construction below a legitimate colimit, rather than one
indexed by a proper class of isomorphism types --- we realize such algebras through an explicit
finite-variable presentation, at the cost of carrying a witness of the presentation as data.

\begin{definition}[Presented \'etale cover]
  \label{def:etale_cover}
  \lean{Algebra.EtaleCover, Algebra.EtaleCover.Carrier}
  \leanok
  A \emph{presented \'etale cover} \(E\) of \(A\) consists of a natural number \(n\), an ideal
  \(I\) of the polynomial ring \(A[x_1,\dots,x_n]\), a proof that the quotient algebra
  \(B_E := A[x_1,\dots,x_n]/I\) is \'etale over \(A\), and a proof that the induced map of
  spectra \(\Spec B_E \to \Spec A\) is surjective. We call \(B_E\) the \emph{carrier} of \(E\).
  Since \'etale algebras are flat, surjectivity of \(\Spec B_E \to \Spec A\) together with
  flatness makes \(B_E\) faithfully flat over \(A\).
\end{definition}

\begin{definition}[Presented covers from an \'etale algebra]
  \label{def:etale_cover_of}
  \lean{Algebra.EtaleCover.of}
  \uses{def:etale_cover}
  \leanok
  Let \(B\) be an \'etale \(A\)-algebra such that \(\Spec B \to \Spec A\) is surjective. Since
  \'etale algebras are of finite presentation, \(B\) admits a presentation as a quotient of a
  polynomial ring in finitely many variables over \(A\); choosing one such presentation
  produces a presented \'etale cover \(E\) of \(A\), denoted \(E = \mathrm{of}(B)\).
\end{definition}

\begin{lemma}[Carrier of a presented cover from an algebra]
  \label{lem:etale_cover_ofEquiv}
  \lean{Algebra.EtaleCover.ofEquiv}
  \uses{def:etale_cover_of}
  \leanok
  In the situation of Definition~\ref{def:etale_cover_of}, the carrier \(B_E\) of
  \(E = \mathrm{of}(B)\) is isomorphic to \(B\) as an \(A\)-algebra.
\end{lemma}
\begin{proof}
  \leanok
  Immediate from the construction: \(E\) is built from a chosen presentation
  \(A[x_1,\dots,x_n] \twoheadrightarrow B\), and the carrier of the resulting cover is the
  quotient of \(A[x_1,\dots,x_n]\) by the kernel of that presentation, which is isomorphic to
  \(B\) by the first isomorphism theorem for algebras.
\end{proof}

\begin{definition}[Refinement]
  \label{def:etale_cover_refines}
  \lean{Algebra.EtaleCover.Refines}
  \uses{def:etale_cover}
  \leanok
  For presented \'etale covers \(E, E'\) of \(A\), we say \(E'\) \emph{refines} \(E\) if there
  exists a homomorphism of \(A\)-algebras \(B_E \to B_{E'}\) (equivalently, a morphism
  \(\Spec B_{E'} \to \Spec B_E\) over \(\Spec A\)). This is a mere existence statement: no
  particular refinement map is remembered as data.
\end{definition}

\begin{lemma}[Refinement is a preorder]
  \label{lem:etale_cover_refines_preorder}
  \lean{Algebra.EtaleCover.refines_refl, Algebra.EtaleCover.Refines.trans}
  \uses{def:etale_cover_refines}
  \leanok
  Every presented \'etale cover \(E\) of \(A\) refines itself, and if \(E''\) refines \(E'\)
  and \(E'\) refines \(E\) then \(E''\) refines \(E\).
\end{lemma}
\begin{proof}
  \leanok
  Reflexivity: the identity homomorphism of \(B_E\) witnesses that \(E\) refines itself.
  Transitivity: composing a homomorphism \(B_{E'} \to B_{E''}\) witnessing that \(E''\) refines
  \(E'\) with a homomorphism \(B_E \to B_{E'}\) witnessing that \(E'\) refines \(E\) gives a
  homomorphism \(B_E \to B_{E''}\) witnessing that \(E''\) refines \(E\).
\end{proof}

\begin{definition}[Common refinement]
  \label{def:etale_cover_prod}
  \lean{Algebra.EtaleCover.prod, Algebra.EtaleCover.prodEquiv}
  \uses{def:etale_cover_of}
  \leanok
  For presented \'etale covers \(E, E'\) of \(A\), the \emph{common refinement} \(E \times E'\)
  is the presented \'etale cover of \(A\) with carrier \(B_E \otimes_A B_{E'}\) (\'etale over
  \(A\) because it is \'etale over the \'etale algebra \(B_E\), which is \'etale over \(A\); and
  faithfully flat by transitivity of faithfully flat extensions), obtained by applying
  Definition~\ref{def:etale_cover_of} to \(B_E \otimes_A B_{E'}\).
\end{definition}

\begin{definition}[Coprojections of the common refinement]
  \label{def:etale_cover_prod_coproj}
  \lean{Algebra.EtaleCover.prodInl, Algebra.EtaleCover.prodInr}
  \uses{def:etale_cover_prod}
  \leanok
  The two canonical homomorphisms of \(A\)-algebras
  \(B_E \to B_{E \times E'} \cong B_E \otimes_A B_{E'}\), \(b \mapsto b \otimes 1\), and
  \(B_{E'} \to B_{E \times E'}\), \(b' \mapsto 1 \otimes b'\), transported along the carrier
  identification of Definition~\ref{def:etale_cover_prod}.
\end{definition}

\begin{lemma}[The common refinement refines both factors]
  \label{lem:etale_cover_prod_refines}
  \lean{Algebra.EtaleCover.prod_refines_left, Algebra.EtaleCover.prod_refines_right}
  \uses{def:etale_cover_prod_coproj, def:etale_cover_refines}
  \leanok
  \(E \times E'\) refines both \(E\) and \(E'\).
\end{lemma}
\begin{proof}
  \leanok
  The two coprojections of Definition~\ref{def:etale_cover_prod_coproj} are homomorphisms of
  \(A\)-algebras out of \(B_E\), respectively \(B_{E'}\), witnessing the two refinements.
\end{proof}

\begin{definition}[Universal map out of the common refinement]
  \label{def:etale_cover_prodLift}
  \lean{Algebra.EtaleCover.prodLift}
  \uses{def:etale_cover_prod}
  \leanok
  Given homomorphisms of \(A\)-algebras \(f \colon B_E \to B_F\) and \(g \colon B_{E'} \to
  B_F\), the induced homomorphism of \(A\)-algebras \(B_{E \times E'} \to B_F\), obtained from
  the universal property of the tensor product \(B_E \otimes_A B_{E'}\) applied to \(f\) and
  \(g\) (whose images commute in the commutative ring \(B_F\)), transported along the carrier
  identification of Definition~\ref{def:etale_cover_prod}.
\end{definition}

\begin{lemma}[The universal map is a common section]
  \label{lem:etale_cover_prodLift_comp}
  \lean{Algebra.EtaleCover.prodLift_comp_prodInl, Algebra.EtaleCover.prodLift_comp_prodInr}
  \uses{def:etale_cover_prodLift, def:etale_cover_prod_coproj}
  \leanok
  In the situation of Definition~\ref{def:etale_cover_prodLift}, the induced map composed with
  each coprojection recovers the corresponding map: the composite \(B_E \to B_{E \times E'} \to
  B_F\) equals \(f\), and the composite \(B_{E'} \to B_{E \times E'} \to B_F\) equals \(g\).
\end{lemma}
\begin{proof}
  \leanok
  This is the defining property of the map induced by the universal property of the tensor
  product: on elementary tensors, \(b \otimes 1 \mapsto f(b) g(1) = f(b)\) and
  \(1 \otimes b' \mapsto f(1) g(b') = g(b')\).
\end{proof}

\begin{theorem}[Directedness]
  \label{thm:etale_cover_exists_refines_prod}
  \lean{Algebra.EtaleCover.exists_refines_prod}
  \uses{def:etale_cover_refines}
  \leanok
  Any two presented \'etale covers \(E, E'\) of \(A\) admit a common refinement: there is a
  presented \'etale cover \(E''\) of \(A\) which refines both \(E\) and \(E'\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:etale_cover_prod_refines}
  Take \(E'' = E \times E'\); it refines both factors by Lemma~\ref{lem:etale_cover_prod_refines}.
\end{proof}

\begin{definition}[The trivial cover]
  \label{def:etale_cover_self}
  \lean{Algebra.EtaleCover.self, Algebra.EtaleCover.selfEquiv}
  \uses{def:etale_cover_of}
  \leanok
  The presented \'etale cover of \(A\) by itself, obtained by applying
  Definition~\ref{def:etale_cover_of} to \(B = A\) (with structure morphism \(\Spec A \to
  \Spec A\) the identity, trivially surjective). Its carrier is isomorphic to \(A\).
\end{definition}

\begin{definition}[Canonical map from the trivial cover]
  \label{def:etale_cover_fromSelf}
  \lean{Algebra.EtaleCover.fromSelf}
  \uses{def:etale_cover_self}
  \leanok
  For a presented \'etale cover \(E\) of \(A\), the canonical homomorphism of \(A\)-algebras
  from the carrier of the trivial cover to \(B_E\): under the identification of the carrier of
  the trivial cover with \(A\) (Definition~\ref{def:etale_cover_self}), the structure
  homomorphism \(A \to B_E\).
\end{definition}

\begin{lemma}[Every cover refines the trivial cover]
  \label{lem:etale_cover_refines_self}
  \lean{Algebra.EtaleCover.refines_self}
  \uses{def:etale_cover_fromSelf, def:etale_cover_refines}
  \leanok
  Every presented \'etale cover \(E\) of \(A\) refines the trivial cover.
\end{lemma}
\begin{proof}
  \leanok
  The canonical map of Definition~\ref{def:etale_cover_fromSelf} witnesses the refinement.
\end{proof}

\begin{definition}[Base change of a cover]
  \label{def:etale_cover_baseChange}
  \lean{Algebra.EtaleCover.baseChange, Algebra.EtaleCover.baseChangeEquiv}
  \uses{def:etale_cover_of}
  \leanok
  Let \(A'\) be a commutative \(A\)-algebra and \(E\) a presented \'etale cover of \(A\). The
  \emph{base change} \(E_{A'}\) is the presented \'etale cover of \(A'\) with carrier
  \(A' \otimes_A B_E\) (\'etale over \(A'\) and faithfully flat over \(A'\), both by base
  change of the corresponding properties of \(B_E\) over \(A\)), obtained by applying
  Definition~\ref{def:etale_cover_of} to \(A' \otimes_A B_E\).
\end{definition}

\begin{definition}[Canonical inclusion into the base change]
  \label{def:etale_cover_baseChangeInclude}
  \lean{Algebra.EtaleCover.baseChangeInclude}
  \uses{def:etale_cover_baseChange}
  \leanok
  The canonical homomorphism of \(A\)-algebras \(\kappa_E \colon B_E \to B_{E_{A'}}\), which
  under the carrier identification \(B_{E_{A'}} \cong A' \otimes_A B_E\) of
  Definition~\ref{def:etale_cover_baseChange} is \(b \mapsto 1 \otimes b\).
\end{definition}

\begin{definition}[Base change of a refinement map]
  \label{def:etale_cover_baseChangeMap}
  \lean{Algebra.EtaleCover.baseChangeMap}
  \uses{def:etale_cover_baseChange}
  \leanok
  For presented \'etale covers \(E, F\) of \(A\) and a homomorphism of \(A\)-algebras
  \(h \colon B_E \to B_F\), the induced homomorphism of \(A'\)-algebras \(B_{E_{A'}} \to
  B_{F_{A'}}\) which, under the carrier identifications of
  Definition~\ref{def:etale_cover_baseChange}, is \(\id_{A'} \otimes h\).
\end{definition}

\begin{lemma}[Naturality of the canonical inclusion]
  \label{lem:etale_cover_baseChangeMap_comp_baseChangeInclude}
  \lean{Algebra.EtaleCover.baseChangeMap_comp_baseChangeInclude}
  \uses{def:etale_cover_baseChangeMap, def:etale_cover_baseChangeInclude}
  \leanok
  For \(h \colon B_E \to B_F\) as in Definition~\ref{def:etale_cover_baseChangeMap}, the square
  of \(A\)-algebra homomorphisms commutes: the composite \(B_E \to B_{E_{A'}} \to B_{F_{A'}}\)
  (canonical inclusion followed by the base-changed map) equals the composite
  \(B_E \to B_F \to B_{F_{A'}}\) (\(h\) followed by the canonical inclusion).
\end{lemma}
\begin{proof}
  \leanok
  Both composites send \(b \in B_E\) to \(1 \otimes h(b) \in A' \otimes_A B_F\) under the
  carrier identifications: the first computes \(b \mapsto 1 \otimes b \mapsto
  (\id_{A'}\otimes h)(1 \otimes b) = 1 \otimes h(b)\), and the second computes
  \(b \mapsto h(b) \mapsto 1 \otimes h(b)\).
\end{proof}

\begin{lemma}[Nontrivial carrier]
  \label{lem:etale_cover_nontrivial_carrier}
  \lean{Algebra.EtaleCover.nontrivial_carrier}
  \uses{def:etale_cover}
  \leanok
  If \(A\) is a nontrivial ring, then the carrier \(B_E\) of any presented \'etale cover \(E\)
  of \(A\) is nontrivial.
\end{lemma}
\begin{proof}
  \leanok
  Since \(A\) is nontrivial, \(\Spec A\) is nonempty; since \(\Spec B_E \to \Spec A\) is
  surjective, \(\Spec B_E\) is nonempty, and a ring with nonempty spectrum is nontrivial.
\end{proof}

\begin{theorem}[Field cofinality]
  \label{thm:etale_cover_field_cofinality}
  \lean{Algebra.EtaleCover.exists_finiteSeparableField_algHom}
  \uses{def:etale_cover}
  \leanok
  Let \(K\) be a field and \(E\) a presented \'etale cover of \(K\). Then there exist a field
  \(L\), finite and separable over \(K\), and a homomorphism of \(K\)-algebras
  \(B_E \to L\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:etale_cover_nontrivial_carrier}
  By the structure theorem for \'etale algebras over a field, \(B_E\) is isomorphic, as a
  \(K\)-algebra, to a finite product \(\prod_{i \in I} L_i\) of finite separable field
  extensions \(L_i\) of \(K\). By Lemma~\ref{lem:etale_cover_nontrivial_carrier}, \(B_E\) is
  nontrivial (\(K\) being a field is nontrivial), so the product is nonempty: \(I \neq
  \emptyset\), for the empty product is the zero ring. Choose \(i_0 \in I\) and set
  \(L = L_{i_0}\); the composite of the structure isomorphism with the projection onto the
  \(i_0\)-th factor is the required homomorphism \(B_E \to L\).
\end{proof}

A finite separable field extension \(L\) of a field \(K\) is automatically \'etale over \(K\):
it is formally \'etale because it is formally unramified (separability) and formally smooth
(finiteness plus the algebra being a field, hence regular), and it is of finite presentation
because it is a finite-type algebra over a field which is moreover finite as a module.

\begin{definition}[Field extension covers]
  \label{def:etale_cover_ofField}
  \lean{Algebra.EtaleCover.ofField, Algebra.EtaleCover.ofFieldEquiv}
  \uses{def:etale_cover_of}
  \leanok
  Let \(K\) be a field and \(L\) a finite separable field extension of \(K\). Since \(\Spec K\)
  is a single point, the spectrum map \(\Spec L \to \Spec K\) is trivially surjective, so
  Definition~\ref{def:etale_cover_of} applied to \(L\) produces a presented \'etale cover of
  \(K\) with carrier isomorphic to \(L\).
\end{definition}

\section{The algebra-indexed relative Picard functor}

In this section \(k\) is a field and \(C\) is an object of \(\Over(\Spec k)\).

\begin{definition}[\(\Spec\) of an algebra map, as a morphism of test objects]
  \label{def:overSpecMap}
  \lean{AlgebraicGeometry.Over.overSpecMap}
  \leanok
  For commutative \(k\)-algebras \(A, B\) and a homomorphism of \(k\)-algebras
  \(f \colon A \to B\), the induced morphism \(\Spec B \to \Spec A\) of \(\Over(\Spec k)\):
  \(\Spec f\), which lies over \(\Spec k\) because \(f\) is a homomorphism of \(k\)-algebras.
\end{definition}

\begin{lemma}[Functoriality of \(\Spec\) on algebra maps]
  \label{lem:overSpecMap_functor}
  \lean{AlgebraicGeometry.Over.overSpecMap_id, AlgebraicGeometry.Over.overSpecMap_comp}
  \uses{def:overSpecMap}
  \leanok
  \(\Spec\) of the identity homomorphism of \(A\) is the identity morphism of \(\Spec A\); and
  for homomorphisms of \(k\)-algebras \(f \colon A \to B\) and \(g \colon B \to C'\),
  \(\Spec(g \circ f) = \Spec f \circ \Spec g\) as morphisms \(\Spec C' \to \Spec A\).
\end{lemma}
\begin{proof}
  \leanok
  \(\Spec\) is a contravariant functor from commutative rings to schemes, so it sends the
  identity to the identity and a composite \(g \circ f\) to \(\Spec f \circ \Spec g\); the
  morphisms of \(\Over(\Spec k)\) so obtained are equal to the corresponding morphisms of
  schemes on their underlying data, so the identities transport.
\end{proof}

\begin{definition}[Restriction of relative Picard classes along an algebra map]
  \label{def:relPicAlgMap}
  \lean{AlgebraicGeometry.relPicAlgMap}
  \uses{def:overSpecMap, def:relPicMap}
  \leanok
  For a homomorphism of \(k\)-algebras \(f \colon A \to B\), the induced homomorphism of groups
  \(f^{*} \colon \mathrm{relPic}(C,A) \to \mathrm{relPic}(C,B)\): restriction of relative
  Picard classes (Definition~\ref{def:relPicMap}) along the morphism
  \(\Spec f \colon \Spec B \to \Spec A\) of Definition~\ref{def:overSpecMap}.
\end{definition}

\begin{lemma}[Functoriality in the algebra]
  \label{lem:relPicAlgMap_functor}
  \lean{AlgebraicGeometry.relPicAlgMap_id, AlgebraicGeometry.relPicAlgMap_comp}
  \uses{def:relPicAlgMap, lem:overSpecMap_functor}
  \leanok
  For every \(k\)-algebra \(A\), \((\id_A)^{*} = \id\) on \(\mathrm{relPic}(C,A)\); and for
  homomorphisms of \(k\)-algebras \(f \colon A \to B\) and \(g \colon B \to C'\),
  \((g \circ f)^{*} = g^{*} \circ f^{*}\) on \(\mathrm{relPic}(C,A)\). Thus
  \(A \mapsto \mathrm{relPic}(C,A)\), \(f \mapsto f^{*}\), is a covariant functor from
  \(k\)-algebras to commutative groups.
\end{lemma}
\begin{proof}
  \leanok
  Restriction of relative Picard classes along \(\Spec\) of a scheme morphism satisfies the
  functor laws \(\id^{*} = \id\) and \((\varphi \circ \psi)^{*} = \psi^{*} \circ \varphi^{*}\)
  in the morphism of \(\Over(\Spec k)\). Combined with
  Lemma~\ref{lem:overSpecMap_functor}, which shows \(\Spec\) of the identity algebra map is the
  identity morphism and \(\Spec\) of a composite \(g \circ f\) is \(\Spec f \circ \Spec g\), the
  two claimed identities for \(f^{*} := \Spec f{}^{*}\) follow.
\end{proof}

\section{Descent classes on an \'etale cover}

Throughout this section \(k\) is a field, \(C\) is an object of \(\Over(\Spec k)\), and \(A\) is
a commutative \(k\)-algebra. For a presented \'etale cover \(E\) of \(A\)
(Definition~\ref{def:etale_cover}) with carrier \(B_E\), the self-tensor product
\(B_E \otimes_A B_E\) is the carrier of the common refinement \(E \times E\) of \(E\) with
itself (Definition~\ref{def:etale_cover_prod}): it is the algebra of the \emph{double cover}
\(\Spec(B_E \otimes_A B_E) \to \Spec B_E\), whose two projections to \(\Spec B_E\) record the
overlap data of the cover \(E\).

\begin{definition}[Coprojections of the double cover]
  \label{def:doubleInl_doubleInr}
  \lean{AlgebraicGeometry.doubleInl, AlgebraicGeometry.doubleInr}
  \uses{def:etale_cover}
  \leanok
  For a presented \'etale cover \(E\) of \(A\), the two homomorphisms of \(k\)-algebras
  \(B_E \to B_E \otimes_A B_E\), \(b \mapsto b \otimes 1\) and \(b \mapsto 1 \otimes b\) ---
  homomorphisms of \(A\)-algebras, in particular of \(k\)-algebras since \(A\) is a
  \(k\)-algebra.
\end{definition}

\begin{definition}[Descent classes]
  \label{def:descentClasses}
  \lean{AlgebraicGeometry.descentClasses, AlgebraicGeometry.mem_descentClasses_iff}
  \uses{def:doubleInl_doubleInr, def:relPicAlgMap}
  \source{kleiman-picard}
  \leanok
  For a presented \'etale cover \(E\) of \(A\), the subgroup
  \(\mathrm{Desc}(C,E) \subseteq \mathrm{relPic}(C,B_E)\) of classes \(\lambda\) satisfying the
  \emph{descent condition}: the two pullbacks of \(\lambda\) along the coprojections of the
  double cover (Definition~\ref{def:doubleInl_doubleInr}) agree,
  \[
    \mathrm{Desc}(C,E) := \bigl\{\, \lambda \in \mathrm{relPic}(C,B_E) : \mathrm{inl}_E^{*}
    \lambda = \mathrm{inr}_E^{*} \lambda \text{ in } \mathrm{relPic}(C, B_E \otimes_A B_E)
    \,\bigr\},
  \]
  the equalizer of the two homomorphisms \(\mathrm{inl}_E^{*}, \mathrm{inr}_E^{*} \colon
  \mathrm{relPic}(C,B_E) \to \mathrm{relPic}(C, B_E \otimes_A B_E)\) of
  Definition~\ref{def:relPicAlgMap}, hence itself a subgroup.
\end{definition}

\begin{lemma}[Naturality of the descent condition]
  \label{lem:relPicAlgMap_mem_descentClasses}
  \lean{AlgebraicGeometry.relPicAlgMap_mem_descentClasses}
  \uses{def:descentClasses}
  \leanok
  Let \(E, F\) be presented \'etale covers of \(A\) and \(h \colon B_E \to B_F\) a
  homomorphism of \(A\)-algebras. If \(\lambda \in \mathrm{Desc}(C,E)\), then
  \(h^{*}\lambda \in \mathrm{Desc}(C,F)\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:relPicAlgMap_functor}
  The homomorphism \(h \otimes h \colon B_E \otimes_A B_E \to B_F \otimes_A B_F\) intertwines
  the coprojections: \(\mathrm{inl}_F \circ h = (h \otimes h) \circ \mathrm{inl}_E\) and
  \(\mathrm{inr}_F \circ h = (h \otimes h) \circ \mathrm{inr}_E\), since both sides send
  \(b \mapsto h(b) \otimes 1\), respectively \(b \mapsto 1 \otimes h(b)\). By functoriality
  (Lemma~\ref{lem:relPicAlgMap_functor}),
  \[
    \mathrm{inl}_F^{*}(h^{*}\lambda) = (h \otimes h)^{*}(\mathrm{inl}_E^{*}\lambda)
    = (h \otimes h)^{*}(\mathrm{inr}_E^{*}\lambda) = \mathrm{inr}_F^{*}(h^{*}\lambda),
  \]
  using \(\lambda \in \mathrm{Desc}(C,E)\) in the middle equality. Hence
  \(h^{*}\lambda \in \mathrm{Desc}(C,F)\).
\end{proof}

\begin{definition}[Transport of descent classes]
  \label{def:descentMap}
  \lean{AlgebraicGeometry.descentMap}
  \uses{lem:relPicAlgMap_mem_descentClasses}
  \leanok
  For \(h \colon B_E \to B_F\) a homomorphism of \(A\)-algebras between the carriers of two
  presented \'etale covers of \(A\), the induced homomorphism of groups \(h_{*} \colon
  \mathrm{Desc}(C,E) \to \mathrm{Desc}(C,F)\), \(\lambda \mapsto h^{*}\lambda\), well-defined by
  Lemma~\ref{lem:relPicAlgMap_mem_descentClasses}.
\end{definition}

\begin{lemma}[Transport along the identity]
  \label{lem:descentMap_id}
  \lean{AlgebraicGeometry.descentMap_id}
  \uses{def:descentMap}
  \leanok
  For every presented \'etale cover \(E\) of \(A\), transport along the identity homomorphism
  of \(B_E\) is the identity on \(\mathrm{Desc}(C,E)\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:relPicAlgMap_functor}
  Immediate from \((\id_{B_E})^{*} = \id\) (Lemma~\ref{lem:relPicAlgMap_functor}).
\end{proof}

\begin{lemma}[Transport is functorial]
  \label{lem:descentMap_comp}
  \lean{AlgebraicGeometry.descentMap_comp}
  \uses{def:descentMap}
  \leanok
  For homomorphisms of \(A\)-algebras \(h \colon B_E \to B_F\) and \(h' \colon B_F \to B_G\)
  between carriers of presented \'etale covers of \(A\), transport along \(h' \circ h\) equals
  transport along \(h'\) followed by transport along \(h\): \((h' \circ h)_{*} = h'_{*} \circ
  h_{*}\) on \(\mathrm{Desc}(C,E)\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:relPicAlgMap_functor}
  Immediate from \((h' \circ h)^{*} = h'^{*} \circ h^{*}\) (Lemma~\ref{lem:relPicAlgMap_functor}),
  restricted to \(\mathrm{Desc}(C,E)\).
\end{proof}

\begin{theorem}[Refinement independence, the keystone]
  \label{thm:relPicAlgMap_congr}
  \lean{AlgebraicGeometry.relPicAlgMap_congr}
  \uses{def:descentClasses}
  \leanok
  Let \(E\) be a presented \'etale cover of \(A\) with carrier \(B = B_E\), let \(R\) be a
  commutative \(k\)-algebra equipped with a compatible \(A\)-algebra structure (so that
  \(k \to A \to R\) is a tower of algebras), and let \(j_1, j_2 \colon B \to R\) be two
  homomorphisms of \(A\)-algebras. If \(\lambda \in \mathrm{Desc}(C,E)\), then
  \(j_1^{*}\lambda = j_2^{*}\lambda\) in \(\mathrm{relPic}(C,R)\).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:relPicAlgMap_functor}
  Let \(H \colon B \otimes_A B \to R\) be the homomorphism of \(A\)-algebras induced by the
  universal property of the tensor product from the pair \((j_1, j_2)\) (their images commute
  in the commutative ring \(R\)): \(H(b \otimes b') = j_1(b) j_2(b')\). Then
  \(H \circ \mathrm{inl}_E = j_1\) (since \(H(b \otimes 1) = j_1(b) j_2(1) = j_1(b)\)) and
  \(H \circ \mathrm{inr}_E = j_2\) (since \(H(1 \otimes b) = j_1(1) j_2(b) = j_2(b)\)). By
  functoriality (Lemma~\ref{lem:relPicAlgMap_functor}),
  \[
    j_1^{*}\lambda = H^{*}(\mathrm{inl}_E^{*}\lambda) = H^{*}(\mathrm{inr}_E^{*}\lambda)
    = j_2^{*}\lambda,
  \]
  using \(\lambda \in \mathrm{Desc}(C,E)\), i.e. \(\mathrm{inl}_E^{*}\lambda =
  \mathrm{inr}_E^{*}\lambda\), in the middle equality.
\end{proof}

\begin{theorem}[Refinement-map independence]
  \label{thm:descentMap_congr}
  \lean{AlgebraicGeometry.descentMap_congr}
  \uses{thm:relPicAlgMap_congr, def:descentMap}
  \leanok
  Let \(E, F\) be presented \'etale covers of \(A\) and \(h_1, h_2 \colon B_E \to B_F\) two
  homomorphisms of \(A\)-algebras. Then \(h_{1,*} = h_{2,*}\) as maps
  \(\mathrm{Desc}(C,E) \to \mathrm{Desc}(C,F)\): transport of a descent class along \(h_1\) and
  along \(h_2\) always agree.
\end{theorem}
\begin{proof}
  \leanok
  Apply Theorem~\ref{thm:relPicAlgMap_congr} with \(R = B_F\) (an \(A\)-algebra which is also a
  \(k\)-algebra compatibly, since \(F\) is a cover of the \(k\)-algebra \(A\)), \(j_1 = h_1\),
  \(j_2 = h_2\).
\end{proof}

\section{The one-step \'etale plus}

\begin{definition}[The refinement equivalence]
  \label{def:picEtAffSetoid}
  \lean{AlgebraicGeometry.picEtAffSetoid}
  \uses{thm:descentMap_congr, def:etale_cover_prod, def:etale_cover_prod_coproj}
  \leanok
  Consider pairs \((E,\lambda)\) with \(E\) a presented \'etale cover of \(A\) and
  \(\lambda \in \mathrm{Desc}(C,E)\). Declare \((E,\lambda) \sim (F,\mu)\) if there exist a
  presented \'etale cover \(G\) of \(A\) and homomorphisms of \(A\)-algebras
  \(f \colon B_E \to B_G\), \(g \colon B_F \to B_G\) with \(f_{*}\lambda = g_{*}\mu\) in
  \(\mathrm{Desc}(C,G)\). This is an equivalence relation.
\end{definition}
\begin{proof}
  \leanok
  \uses{lem:descentMap_comp}
  \emph{Reflexivity.} \((E,\lambda) \sim (E,\lambda)\) via \(G = E\), \(f = g = \id_{B_E}\).

  \emph{Symmetry.} If \((E,\lambda) \sim (F,\mu)\) via \((G,f,g)\), then \((F,\mu) \sim
  (E,\lambda)\) via \((G,g,f)\).

  \emph{Transitivity.} Suppose \((E,\lambda) \sim (F,\mu)\) via \((G,f,g)\), so \(f_{*}\lambda =
  g_{*}\mu\), and \((F,\mu) \sim (H,\nu)\) via \((G',f',g')\), so \(f'_{*}\mu = g'_{*}\nu\). Use
  the common refinement \(G \times G'\) with the maps \(\mathrm{inl}_{G,G'} \circ f \colon B_E
  \to B_{G \times G'}\) and \(\mathrm{inr}_{G,G'} \circ g' \colon B_H \to B_{G \times G'}\).
  Using functoriality of transport (Lemma~\ref{lem:descentMap_comp}) and refinement-map
  independence (Theorem~\ref{thm:descentMap_congr}, applied to the two maps
  \(\mathrm{inl}_{G,G'} \circ g\) and \(\mathrm{inr}_{G,G'} \circ f'\) out of \(B_F\)),
  \[
    (\mathrm{inl}_{G,G'} \circ f)_{*}\lambda = \mathrm{inl}_{G,G',*}(f_{*}\lambda) =
    \mathrm{inl}_{G,G',*}(g_{*}\mu) = (\mathrm{inl}_{G,G'} \circ g)_{*}\mu
  \]
  \[
    = (\mathrm{inr}_{G,G'} \circ f')_{*}\mu = \mathrm{inr}_{G,G',*}(f'_{*}\mu) =
    \mathrm{inr}_{G,G',*}(g'_{*}\nu) = (\mathrm{inr}_{G,G'} \circ g')_{*}\nu,
  \]
  so \((E,\lambda) \sim (H,\nu)\) via \((G \times G', \mathrm{inl}_{G,G'} \circ f,
  \mathrm{inr}_{G,G'} \circ g')\).
\end{proof}

\begin{definition}[The one-step \'etale plus]
  \label{def:PicEtAff}
  \lean{AlgebraicGeometry.PicEtAff}
  \uses{def:picEtAffSetoid}
  \source{kleiman-picard}
  \leanok
  The set of pairs \((E,\lambda)\) as in Definition~\ref{def:picEtAffSetoid}, modulo the
  equivalence relation there, is denoted \(\mathrm{PicEtAff}(C,A)\): the one-step \'etale plus
  of the relative Picard functor at \(A\). On affine test schemes this is the \'etale
  sheafification of \(\mathrm{relPic}(C,-)\), one plus construction sufficing because that
  presheaf is separated for the \'etale topology (established elsewhere).
\end{definition}

\begin{definition}[The plus class of a descent class]
  \label{def:PicEtAff_mk}
  \lean{AlgebraicGeometry.PicEtAff.mk}
  \uses{def:PicEtAff}
  \leanok
  For a presented \'etale cover \(E\) of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\), write
  \([E,\lambda] \in \mathrm{PicEtAff}(C,A)\) for the class of the pair \((E,\lambda)\).
\end{definition}

\begin{lemma}[Every plus class is so represented]
  \label{lem:PicEtAff_ind}
  \lean{AlgebraicGeometry.PicEtAff.ind}
  \uses{def:PicEtAff_mk}
  \leanok
  Every element of \(\mathrm{PicEtAff}(C,A)\) is of the form \([E,\lambda]\) for some presented
  \'etale cover \(E\) of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\).
\end{lemma}
\begin{proof}
  \leanok
  Immediate: \(\mathrm{PicEtAff}(C,A)\) is a quotient of the set of such pairs, and every class
  in a quotient is the class of some representative.
\end{proof}

\begin{theorem}[Equality of plus classes]
  \label{thm:PicEtAff_mk_eq_mk_iff}
  \lean{AlgebraicGeometry.PicEtAff.mk_eq_mk_iff}
  \uses{def:PicEtAff_mk, def:picEtAffSetoid}
  \leanok
  \([E,\lambda] = [F,\mu]\) in \(\mathrm{PicEtAff}(C,A)\) if and only if there exist a presented
  \'etale cover \(G\) of \(A\) and homomorphisms of \(A\)-algebras \(f \colon B_E \to B_G\),
  \(g \colon B_F \to B_G\) with \(f_{*}\lambda = g_{*}\mu\).
\end{theorem}
\begin{proof}
  \leanok
  This is exactly the defining relation of Definition~\ref{def:picEtAffSetoid}, restated as an
  equality of classes in the quotient.
\end{proof}

\begin{lemma}[Transport to a finer cover preserves the plus class]
  \label{lem:PicEtAff_mk_descentMap}
  \lean{AlgebraicGeometry.PicEtAff.mk_descentMap}
  \uses{thm:PicEtAff_mk_eq_mk_iff, def:descentMap}
  \leanok
  For \(h \colon B_E \to B_F\) a homomorphism of \(A\)-algebras between carriers of presented
  \'etale covers of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\), \([F, h_{*}\lambda] =
  [E,\lambda]\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:descentMap_id}
  Take \(G = F\) with \(f = \id_{B_F}\) and \(g = h\) in Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff}:
  \(f_{*}(h_{*}\lambda) = h_{*}\lambda = g_{*}\lambda\) by Lemma~\ref{lem:descentMap_id}.
\end{proof}

\section{The group structure and the unit}

\begin{lemma}[Transport through the universal map collapses]
  \label{lem:PicEtAff_descentMap_prodLift}
  \lean{AlgebraicGeometry.PicEtAff.descentMap_prodLift_inl,
    AlgebraicGeometry.PicEtAff.descentMap_prodLift_inr}
  \uses{lem:etale_cover_prodLift_comp, lem:descentMap_comp}
  \leanok
  Let \(E, F, H\) be presented \'etale covers of \(A\), \(f \colon B_E \to B_H\) and
  \(g \colon B_F \to B_H\) homomorphisms of \(A\)-algebras, and let
  \(\langle f,g\rangle \colon B_{E \times F} \to B_H\) be the induced map of
  Definition~\ref{def:etale_cover_prodLift}. Then for \(\lambda \in \mathrm{Desc}(C,E)\) and
  \(\mu \in \mathrm{Desc}(C,F)\):
  \[
    \langle f,g\rangle_{*}(\mathrm{inl}_{E,F,*}\lambda) = f_{*}\lambda, \qquad
    \langle f,g\rangle_{*}(\mathrm{inr}_{E,F,*}\mu) = g_{*}\mu.
  \]
\end{lemma}
\begin{proof}
  \leanok
  By functoriality of transport (Lemma~\ref{lem:descentMap_comp}), the left-hand sides equal
  \((\langle f,g\rangle \circ \mathrm{inl}_{E,F})_{*}\lambda\), respectively
  \((\langle f,g\rangle \circ \mathrm{inr}_{E,F})_{*}\mu\); by
  Lemma~\ref{lem:etale_cover_prodLift_comp}, \(\langle f,g\rangle \circ \mathrm{inl}_{E,F} = f\)
  and \(\langle f,g\rangle \circ \mathrm{inr}_{E,F} = g\).
\end{proof}

\begin{theorem}[Multiplication]
  \label{thm:PicEtAff_mk_mul_mk}
  \lean{AlgebraicGeometry.PicEtAff.instMul, AlgebraicGeometry.PicEtAff.mk_mul_mk}
  \uses{lem:PicEtAff_descentMap_prodLift, thm:PicEtAff_mk_eq_mk_iff, thm:descentMap_congr,
    def:etale_cover_prod_coproj}
  \leanok
  \(\mathrm{PicEtAff}(C,A)\) carries a multiplication, defined on representatives by transport
  to a common refinement product cover: for presented \'etale covers \(E, F\) of \(A\) and
  \(\lambda \in \mathrm{Desc}(C,E)\), \(\mu \in \mathrm{Desc}(C,F)\),
  \[
    [E,\lambda] \cdot [F,\mu] = \bigl[\,E \times F,\ \mathrm{inl}_{E,F,*}\lambda \cdot
    \mathrm{inr}_{E,F,*}\mu\,\bigr].
  \]
\end{theorem}
\begin{proof}
  \leanok
  It remains to check that the formula is independent of the chosen representatives, i.e. that
  if \((E,\lambda) \sim (E',\lambda')\) via \((H,f,f')\) (so \(f_{*}\lambda = f'_{*}\lambda'\))
  and \((F,\mu) \sim (F',\mu')\) via \((G,g,g')\) (so \(g_{*}\mu = g'_{*}\mu'\)), then the two
  resulting products agree. Use the common refinement \(H \times G\) of \(E \times F\) and
  \(E' \times F'\), with the maps
  \(\langle \mathrm{inl}_{H,G} \circ f,\ \mathrm{inr}_{H,G} \circ g\rangle \colon B_{E \times F}
  \to B_{H \times G}\) and
  \(\langle \mathrm{inl}_{H,G} \circ f',\ \mathrm{inr}_{H,G} \circ g'\rangle \colon
  B_{E' \times F'} \to B_{H \times G}\)
  (Definition~\ref{def:etale_cover_prodLift}). Since transport is a homomorphism of groups
  (Definition~\ref{def:descentMap}), transporting the product
  \(\mathrm{inl}_{E,F,*}\lambda \cdot \mathrm{inr}_{E,F,*}\mu\) along the first map yields, by
  Lemma~\ref{lem:PicEtAff_descentMap_prodLift} applied twice,
  \(\mathrm{inl}_{H,G,*}(f_{*}\lambda) \cdot \mathrm{inr}_{H,G,*}(g_{*}\mu)\); transporting the
  primed product along the second map yields
  \(\mathrm{inl}_{H,G,*}(f'_{*}\lambda') \cdot \mathrm{inr}_{H,G,*}(g'_{*}\mu')\); these agree
  term by term since \(f_{*}\lambda = f'_{*}\lambda'\) and \(g_{*}\mu = g'_{*}\mu'\). Hence the
  two products transport to the same class on \(H \times G\), so by
  Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff} they define the same element of
  \(\mathrm{PicEtAff}(C,A)\).
\end{proof}

\begin{theorem}[Multiplication of classes on the same cover]
  \label{thm:PicEtAff_mk_mul_mk_same}
  \lean{AlgebraicGeometry.PicEtAff.mk_mul_mk_same}
  \uses{thm:PicEtAff_mk_mul_mk, thm:descentMap_congr, lem:PicEtAff_mk_descentMap}
  \leanok
  For a presented \'etale cover \(E\) of \(A\) and \(\lambda, \mu \in \mathrm{Desc}(C,E)\),
  \([E,\lambda] \cdot [E,\mu] = [E, \lambda \mu]\).
\end{theorem}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:PicEtAff_mk_mul_mk}, \([E,\lambda][E,\mu] = [E \times E,
  \mathrm{inl}_{E,E,*}\lambda \cdot \mathrm{inr}_{E,E,*}\mu]\). By refinement-map independence
  (Theorem~\ref{thm:descentMap_congr}, applied to the two maps \(\mathrm{inr}_{E,E}\) and
  \(\mathrm{inl}_{E,E}\) out of \(B_E\)), \(\mathrm{inr}_{E,E,*}\mu = \mathrm{inl}_{E,E,*}\mu\).
  Since transport is a homomorphism of groups,
  \(\mathrm{inl}_{E,E,*}\lambda \cdot \mathrm{inl}_{E,E,*}\mu = \mathrm{inl}_{E,E,*}(\lambda
  \mu)\). Hence \([E,\lambda][E,\mu] = [E \times E, \mathrm{inl}_{E,E,*}(\lambda\mu)] =
  [E,\lambda\mu]\), the last equality by Lemma~\ref{lem:PicEtAff_mk_descentMap}.
\end{proof}

\begin{definition}[Identity]
  \label{def:PicEtAff_one}
  \lean{AlgebraicGeometry.PicEtAff.instOne, AlgebraicGeometry.PicEtAff.one_def}
  \uses{def:etale_cover_self, def:PicEtAff_mk}
  \leanok
  The identity element of \(\mathrm{PicEtAff}(C,A)\) is \(1 := [\mathrm{self}(A), 1]\), the
  class of the identity descent datum on the trivial cover.
\end{definition}

\begin{theorem}[The identity is represented on every cover]
  \label{thm:PicEtAff_mk_one}
  \lean{AlgebraicGeometry.PicEtAff.mk_one}
  \uses{def:PicEtAff_one, def:etale_cover_fromSelf, thm:PicEtAff_mk_eq_mk_iff}
  \leanok
  For every presented \'etale cover \(E\) of \(A\), \([E,1] = 1\) in \(\mathrm{PicEtAff}(C,A)\).
\end{theorem}
\begin{proof}
  \leanok
  Apply Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff} with \(G = E\), \(f = \id_{B_E}\), and \(g\)
  the canonical map from the trivial cover (Definition~\ref{def:etale_cover_fromSelf}): since
  transport is a homomorphism of groups, both \(f_{*}1\) and \(g_{*}1\) equal \(1\), regardless
  of \(f\) and \(g\), so they agree.
\end{proof}

\begin{definition}[Inverse]
  \label{def:PicEtAff_inv}
  \lean{AlgebraicGeometry.PicEtAff.instInv, AlgebraicGeometry.PicEtAff.mk_inv}
  \uses{def:PicEtAff_mk, def:picEtAffSetoid}
  \leanok
  \(\mathrm{PicEtAff}(C,A)\) carries an inversion, defined on representatives by
  \([E,\lambda]^{-1} = [E,\lambda^{-1}]\); well-defined because if \((E,\lambda) \sim (F,\mu)\)
  via \((G,f,g)\), so \(f_{*}\lambda = g_{*}\mu\), then applying the group homomorphism
  \(f_{*}\), respectively \(g_{*}\), to inverses gives \(f_{*}(\lambda^{-1}) =
  (f_{*}\lambda)^{-1} = (g_{*}\mu)^{-1} = g_{*}(\mu^{-1})\), so \((E,\lambda^{-1}) \sim
  (F,\mu^{-1})\) via the same \((G,f,g)\).
\end{definition}

\begin{theorem}[\(\mathrm{PicEtAff}(C,A)\) is a commutative group]
  \label{thm:PicEtAff_commGroup}
  \lean{AlgebraicGeometry.PicEtAff.instCommGroup}
  \uses{thm:PicEtAff_mk_mul_mk_same, thm:PicEtAff_mk_one, def:PicEtAff_inv,
    lem:PicEtAff_ind, lem:PicEtAff_mk_descentMap, def:etale_cover_prod_coproj}
  \leanok
  With the multiplication of Theorem~\ref{thm:PicEtAff_mk_mul_mk}, the identity of
  Definition~\ref{def:PicEtAff_one}, and the inversion of Definition~\ref{def:PicEtAff_inv},
  \(\mathrm{PicEtAff}(C,A)\) is a commutative group.
\end{theorem}
\begin{proof}
  \leanok
  By Lemma~\ref{lem:PicEtAff_ind} every element is of the form \([E,\lambda]\), so it suffices
  to check the axioms on such representatives, re-expressing every class involved as a class on
  one common cover by Lemma~\ref{lem:PicEtAff_mk_descentMap} (transporting a representative up
  along a chosen refinement map does not change its plus class) and then applying
  Theorem~\ref{thm:PicEtAff_mk_mul_mk_same} to compute products of classes living on the same
  cover.

  \emph{Associativity.} For \(a = [E,\lambda]\), \(b = [F,\mu]\), \(c = [G,\nu]\), rewrite
  \(a\), \(b\), \(c\) as classes on the common cover \((E \times F) \times G\), transporting
  \(\lambda\) along \(\mathrm{inl}_{E \times F, G} \circ \mathrm{inl}_{E,F}\), \(\mu\) along
  \(\mathrm{inl}_{E \times F, G} \circ \mathrm{inr}_{E,F}\), and \(\nu\) along
  \(\mathrm{inr}_{E \times F, G}\) (Lemma~\ref{lem:PicEtAff_mk_descentMap}); the three
  transported representatives \(\lambda', \mu', \nu' \in \mathrm{Desc}(C, (E \times F) \times
  G)\) now satisfy, by Theorem~\ref{thm:PicEtAff_mk_mul_mk_same}, \((ab)c = [(E \times F)
  \times G, (\lambda'\mu')\nu']\) and \(a(bc) = [(E \times F) \times G, \lambda'(\mu'\nu')]\);
  these agree by associativity of multiplication in the group \(\mathrm{Desc}(C,(E \times F)
  \times G)\).

  \emph{Identity.} For \(a = [E,\lambda]\), \(1 \cdot a = [\mathrm{self}(A) \times E,
  \mathrm{inl}_{*}1 \cdot \mathrm{inr}_{*}\lambda] = [\mathrm{self}(A) \times E,
  \mathrm{inr}_{*}\lambda] = [E,\lambda] = a\), using that transport preserves the identity and
  Lemma~\ref{lem:PicEtAff_mk_descentMap}; similarly \(a \cdot 1 = a\).

  \emph{Inverses.} For \(a = [E,\lambda]\), \(a^{-1} a = [E,\lambda^{-1}][E,\lambda] =
  [E,\lambda^{-1}\lambda] = [E,1] = 1\), by Theorem~\ref{thm:PicEtAff_mk_mul_mk_same} and
  Theorem~\ref{thm:PicEtAff_mk_one}.

  \emph{Commutativity.} For \(a = [E,\lambda]\), \(b = [F,\mu]\), transport both to the common
  cover \(E \times F\) via \(\mathrm{inl}_{E,F}\), respectively \(\mathrm{inr}_{E,F}\)
  (Lemma~\ref{lem:PicEtAff_mk_descentMap}): \(a = [E \times F, \mathrm{inl}_{*}\lambda]\), \(b =
  [E \times F, \mathrm{inr}_{*}\mu]\); by Theorem~\ref{thm:PicEtAff_mk_mul_mk_same}, \(ab = [E
  \times F, \mathrm{inl}_{*}\lambda \cdot \mathrm{inr}_{*}\mu]\) and \(ba = [E \times F,
  \mathrm{inr}_{*}\mu \cdot \mathrm{inl}_{*}\lambda]\), which agree because \(\mathrm{Desc}(C,E
  \times F)\), a subgroup of the commutative group \(\mathrm{relPic}(C, B_E \otimes_A B_F)\),
  is commutative.
\end{proof}

\begin{lemma}[Tautological descent datum]
  \label{lem:PicEtAff_tautological_mem_descentClasses}
  \lean{AlgebraicGeometry.PicEtAff.tautological_mem_descentClasses}
  \uses{def:descentClasses, def:doubleInl_doubleInr}
  \leanok
  Let \(E\) be a presented \'etale cover of \(A\) and \(\iota_E \colon A \to B_E\) the
  structure homomorphism. For every \(x \in \mathrm{relPic}(C,A)\), the class
  \(\iota_E^{*}x \in \mathrm{relPic}(C,B_E)\) satisfies the descent condition:
  \(\iota_E^{*}x \in \mathrm{Desc}(C,E)\).
\end{lemma}
\begin{proof}
  \leanok
  The two composites \(\mathrm{inl}_E \circ \iota_E\) and \(\mathrm{inr}_E \circ \iota_E\), both
  maps \(A \to B_E \otimes_A B_E\), coincide: each sends \(a \mapsto \iota_E(a) \otimes 1 = 1
  \otimes \iota_E(a)\), the two descriptions of the structure homomorphism of the tensor
  product \(B_E \otimes_A B_E\) over \(A\). By functoriality (Lemma~\ref{lem:relPicAlgMap_functor}),
  \(\mathrm{inl}_E^{*}(\iota_E^{*}x) = (\mathrm{inl}_E \circ \iota_E)^{*}x = (\mathrm{inr}_E
  \circ \iota_E)^{*}x = \mathrm{inr}_E^{*}(\iota_E^{*}x)\).
\end{proof}

\begin{definition}[The unit of the plus construction]
  \label{def:PicEtAff_unit}
  \lean{AlgebraicGeometry.PicEtAff.unit}
  \uses{lem:PicEtAff_tautological_mem_descentClasses, def:etale_cover_self,
    thm:PicEtAff_mk_one, thm:PicEtAff_mk_mul_mk_same}
  \source{kleiman-picard}
  \leanok
  The homomorphism of groups \(\eta_A \colon \mathrm{relPic}(C,A) \to
  \mathrm{PicEtAff}(C,A)\) sending \(x\) to the class \([\mathrm{self}(A), \iota^{*}x]\) of \(x\)
  pulled back to the trivial cover with its tautological descent datum
  (Lemma~\ref{lem:PicEtAff_tautological_mem_descentClasses}).
\end{definition}
\begin{proof}
  \leanok
  \(\eta_A\) preserves the identity: the tautological descent datum of \(1 \in
  \mathrm{relPic}(C,A)\) is \(1 \in \mathrm{Desc}(C,\mathrm{self}(A))\) (transport preserves
  the identity), so \(\eta_A(1) = [\mathrm{self}(A),1] = 1\) by
  Theorem~\ref{thm:PicEtAff_mk_one}. It preserves products: the tautological descent datum of
  \(xy\) is the product of the tautological descent data of \(x\) and \(y\) (transport is a
  homomorphism), so \(\eta_A(xy) = [\mathrm{self}(A), \iota^{*}x \cdot \iota^{*}y] =
  [\mathrm{self}(A),\iota^{*}x][\mathrm{self}(A),\iota^{*}y] = \eta_A(x)\eta_A(y)\) by
  Theorem~\ref{thm:PicEtAff_mk_mul_mk_same}.
\end{proof}

\section{Functoriality in the test algebra}

Throughout this section \(k\) is a field, \(C\) is an object of \(\Over(\Spec k)\), \(A\) is a
commutative \(k\)-algebra, and \(A'\) is a commutative \(k\)-algebra additionally equipped with
an \(A\)-algebra structure compatible with the tower \(k \to A \to A'\) (following the
homomorphism-along-instances idiom, this exhibits a homomorphism of \(k\)-algebras \(A \to
A'\), extracted from the tower as \(\tau \colon A \to A'\)). For a presented \'etale cover \(E\)
of \(A\), write \(E_{A'}\) for its base change (Definition~\ref{def:etale_cover_baseChange}) and
\(\kappa_E \colon B_E \to B_{E_{A'}}\) for the canonical inclusion
(Definition~\ref{def:etale_cover_baseChangeInclude}).

\begin{lemma}[Descent survives base change of the cover]
  \label{lem:baseChangeInclude_mem_descentClasses}
  \lean{AlgebraicGeometry.baseChangeInclude_mem_descentClasses}
  \uses{def:etale_cover_baseChangeInclude, thm:relPicAlgMap_congr, def:descentClasses}
  \leanok
  Let \(E\) be a presented \'etale cover of \(A\) and \(\lambda \in \mathrm{Desc}(C,E)\). Then
  \(\kappa_E^{*}\lambda \in \mathrm{Desc}(C, E_{A'})\).
\end{lemma}
\begin{proof}
  \leanok
  The two coprojections of the double cover of \(E_{A'}\)
  (Definition~\ref{def:doubleInl_doubleInr}), composed with \(\kappa_E\), are two
  homomorphisms of \(A\)-algebras \(B_E \to B_{E_{A'}} \otimes_{A'} B_{E_{A'}}\) (both factor
  through the \(A\)-algebra structure of the target inherited from \(A \to A'\)): namely
  \(\mathrm{inl} \circ \kappa_E\) and \(\mathrm{inr} \circ \kappa_E\), sending \(b \mapsto
  (1 \otimes b) \otimes 1\), respectively \(b \mapsto 1 \otimes (1 \otimes b)\), under the
  carrier identifications. By the keystone (Theorem~\ref{thm:relPicAlgMap_congr}), applied with
  \(R = B_{E_{A'}} \otimes_{A'} B_{E_{A'}}\) and \(j_1 = \mathrm{inl} \circ \kappa_E\), \(j_2 =
  \mathrm{inr} \circ \kappa_E\), the class \(\lambda \in \mathrm{Desc}(C,E)\) satisfies
  \(j_1^{*}\lambda = j_2^{*}\lambda\); by functoriality this reads \(\mathrm{inl}^{*}
  (\kappa_E^{*}\lambda) = \mathrm{inr}^{*}(\kappa_E^{*}\lambda)\), the descent condition for
  \(\kappa_E^{*}\lambda\) on \(E_{A'}\).
\end{proof}

\begin{definition}[Transport along base change of the cover]
  \label{def:descentBaseChange}
  \lean{AlgebraicGeometry.descentBaseChange}
  \uses{lem:baseChangeInclude_mem_descentClasses}
  \leanok
  The induced homomorphism of groups \(\mathrm{Desc}(C,E) \to \mathrm{Desc}(C,E_{A'})\),
  \(\lambda \mapsto \kappa_E^{*}\lambda\).
\end{definition}

\begin{lemma}[Naturality of base-change transport]
  \label{lem:descentMap_baseChangeMap}
  \lean{AlgebraicGeometry.descentMap_baseChangeMap}
  \uses{def:descentBaseChange, lem:etale_cover_baseChangeMap_comp_baseChangeInclude,
    def:descentMap}
  \leanok
  Let \(E, F\) be presented \'etale covers of \(A\) and \(h \colon B_E \to B_F\) a
  homomorphism of \(A\)-algebras. Then base-change transport commutes with refinement
  transport: for \(\lambda \in \mathrm{Desc}(C,E)\),
  \[
    \mathrm{baseChangeMap}(h)_{*}\bigl(\kappa_{E}^{*}\lambda\bigr) = \kappa_{F}^{*}(h_{*}\lambda)
  \]
  in \(\mathrm{Desc}(C,F_{A'})\), where \(\mathrm{baseChangeMap}(h) \colon B_{E_{A'}} \to
  B_{F_{A'}}\) is the base change of \(h\) (Definition~\ref{def:etale_cover_baseChangeMap}).
\end{lemma}
\begin{proof}
  \leanok
  By Lemma~\ref{lem:etale_cover_baseChangeMap_comp_baseChangeInclude},
  \(\mathrm{baseChangeMap}(h) \circ \kappa_E = \kappa_F \circ h\) as homomorphisms of
  \(A\)-algebras \(B_E \to B_{F_{A'}}\). Both sides of the claimed identity equal, by
  functoriality of transport, the transport of \(\lambda\) along this common composite.
\end{proof}

\begin{definition}[Restriction along a base extension]
  \label{def:PicEtAff_map}
  \lean{AlgebraicGeometry.PicEtAff.map}
  \uses{def:descentBaseChange, lem:descentMap_baseChangeMap, thm:PicEtAff_mk_mul_mk,
    thm:descentMap_congr}
  \leanok
  The homomorphism of groups \(\tau^{*} \colon \mathrm{PicEtAff}(C,A) \to
  \mathrm{PicEtAff}(C,A')\), \([E,\lambda] \mapsto [E_{A'}, \kappa_E^{*}\lambda]\).
\end{definition}
\begin{proof}
  \leanok
  \emph{Well-defined on plus classes.} If \((E,\lambda) \sim (F,\mu)\) via \((G,f,g)\)
  (so \(f_{*}\lambda = g_{*}\mu\)), then base-changing gives \((E_{A'},\kappa_E^{*}\lambda) \sim
  (F_{A'},\kappa_F^{*}\mu)\) via \((G_{A'}, \mathrm{baseChangeMap}(f),
  \mathrm{baseChangeMap}(g))\): by Lemma~\ref{lem:descentMap_baseChangeMap},
  \(\mathrm{baseChangeMap}(f)_{*}(\kappa_E^{*}\lambda) = \kappa_G^{*}(f_{*}\lambda) =
  \kappa_G^{*}(g_{*}\mu) = \mathrm{baseChangeMap}(g)_{*}(\kappa_F^{*}\mu)\).

  \emph{Multiplicativity.} For \(a = [E,\lambda]\), \(b = [F,\mu]\), first transport \(a\) and
  \(b\) to the common refinement \(E \times F\) (Lemma~\ref{lem:PicEtAff_mk_descentMap}):
  \(a = [E \times F, \mathrm{inl}_{*}\lambda]\), \(b = [E \times F, \mathrm{inr}_{*}\mu]\), so
  \(\tau^{*}a = [(E \times F)_{A'}, \kappa_{E \times F}^{*}(\mathrm{inl}_{*}\lambda)]\) and
  \(\tau^{*}b = [(E \times F)_{A'}, \kappa_{E \times F}^{*}(\mathrm{inr}_{*}\mu)]\); by
  Theorem~\ref{thm:PicEtAff_mk_mul_mk_same},
  \[
    \tau^{*}a \cdot \tau^{*}b = \bigl[(E \times F)_{A'},\ \kappa_{E \times F}^{*}
    (\mathrm{inl}_{*}\lambda) \cdot \kappa_{E \times F}^{*}(\mathrm{inr}_{*}\mu)\bigr].
  \]
  On the other hand, \(ab = [E \times F, \mathrm{inl}_{*}\lambda \cdot \mathrm{inr}_{*}\mu]\)
  (Theorem~\ref{thm:PicEtAff_mk_mul_mk}), so, since \(\kappa_{E \times F}^{*}\) is a
  homomorphism of groups, \(\tau^{*}(ab) = [(E \times F)_{A'}, \kappa_{E \times F}^{*}
  (\mathrm{inl}_{*}\lambda) \cdot \kappa_{E \times F}^{*}(\mathrm{inr}_{*}\mu)]\) as well. Hence
  \(\tau^{*}(ab) = \tau^{*}a \cdot \tau^{*}b\).
\end{proof}

\begin{theorem}[Naturality of the unit]
  \label{thm:PicEtAff_map_unit}
  \lean{AlgebraicGeometry.PicEtAff.map_unit}
  \uses{def:PicEtAff_map, def:PicEtAff_unit}
  \leanok
  For \(x \in \mathrm{relPic}(C,A)\), \(\tau^{*}(\eta_A(x)) = \eta_{A'}(\tau^{*}x)\) in
  \(\mathrm{PicEtAff}(C,A')\), where on the right \(\tau^{*} \colon \mathrm{relPic}(C,A) \to
  \mathrm{relPic}(C,A')\) is restriction along the algebra map \(\tau\)
  (Definition~\ref{def:relPicAlgMap}).
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:PicEtAff_mk_descentMap, lem:PicEtAff_tautological_mem_descentClasses}
  Let \(\sigma \colon B_{\mathrm{self}(A')} \to B_{\mathrm{self}(A)_{A'}}\) be the canonical map
  from the trivial cover of \(A'\) (Definition~\ref{def:etale_cover_fromSelf}, for the cover
  \(\mathrm{self}(A)_{A'}\) of \(A'\)). The two composite \(A\)-algebra homomorphisms
  \(A \to B_{\mathrm{self}(A)_{A'}}\) given by \(\kappa_{\mathrm{self}(A)} \circ \iota_{
  \mathrm{self}(A)}\) and by \(\sigma \circ \iota_{\mathrm{self}(A')} \circ \tau\) both equal
  the structure homomorphism of \(B_{\mathrm{self}(A)_{A'}}\) as an \(A\)-algebra: the first,
  because \(\kappa_{\mathrm{self}(A)}\) and \(\iota_{\mathrm{self}(A)}\) are structure
  homomorphisms; the second, because algebra-map formation is compatible with the tower
  \(A \to A' \to B_{\mathrm{self}(A)_{A'}}\) (the structure map of an \(A\)-algebra obtained by
  restriction of scalars along \(A \to A'\) factors through \(A'\)). Hence the two composites
  coincide, and by functoriality (Lemma~\ref{lem:relPicAlgMap_functor}), for \(x \in
  \mathrm{relPic}(C,A)\),
  \[
    \kappa_{\mathrm{self}(A)}^{*}(\iota_{\mathrm{self}(A)}^{*}x) = \sigma^{*}\bigl(
    \iota_{\mathrm{self}(A')}^{*}(\tau^{*}x)\bigr).
  \]
  The left side represents \(\tau^{*}(\eta_A(x)) = [\mathrm{self}(A)_{A'},
  \kappa_{\mathrm{self}(A)}^{*}(\iota_{\mathrm{self}(A)}^{*}x)]\)
  (Definition~\ref{def:PicEtAff_map} applied to the representative \([\mathrm{self}(A),
  \iota_{\mathrm{self}(A)}^{*}x]\) of \(\eta_A(x)\)). By the displayed equality this equals
  \([\mathrm{self}(A)_{A'}, \sigma^{*}(\iota_{\mathrm{self}(A')}^{*}(\tau^{*}x))]\), which by
  Lemma~\ref{lem:PicEtAff_mk_descentMap} (transport along \(\sigma\)) equals
  \([\mathrm{self}(A'), \iota_{\mathrm{self}(A')}^{*}(\tau^{*}x)] = \eta_{A'}(\tau^{*}x)\).
\end{proof}

\begin{theorem}[Restriction along the trivial extension is the identity]
  \label{thm:PicEtAff_map_id}
  \lean{AlgebraicGeometry.PicEtAff.map_id}
  \uses{def:PicEtAff_map}
  \leanok
  When \(A' = A\) with \(\tau = \id_A\), the induced homomorphism \(\tau^{*} \colon
  \mathrm{PicEtAff}(C,A) \to \mathrm{PicEtAff}(C,A)\) is the identity.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:PicEtAff_mk_descentMap}
  For \([E,\lambda] \in \mathrm{PicEtAff}(C,A)\), base-changing \(E\) along \(A \to A\) gives a
  cover with canonical inclusion \(\kappa_E \colon B_E \to B_{E_A}\) itself an \(A\)-algebra
  refinement map, and by construction transport of \(\lambda\) along \(\kappa_E\) computes the
  same class as \(\kappa_E^{*}\lambda\) in the sense of Definition~\ref{def:descentMap}. Hence
  \(\tau^{*}[E,\lambda] = [E_A, \kappa_E^{*}\lambda] = [E,\lambda]\) by
  Lemma~\ref{lem:PicEtAff_mk_descentMap}, applied to the refinement map \(\kappa_E \colon B_E
  \to B_{E_A}\).
\end{proof}

\begin{theorem}[Restriction is transitive]
  \label{thm:PicEtAff_map_map}
  \lean{AlgebraicGeometry.PicEtAff.map_map}
  \uses{def:PicEtAff_map, thm:relPicAlgMap_congr, thm:PicEtAff_mk_eq_mk_iff}
  \leanok
  Let \(A''\) be a commutative \(k\)-algebra with compatible algebra structures forming a tower
  \(k \to A \to A' \to A''\). Then, writing \(\tau' \colon A' \to A''\) and \(\tau'' \colon A
  \to A''\) for the induced maps, restriction along \(A \to A' \to A''\) equals restriction
  along \(A \to A''\) directly:
  \(\tau'^{*} \circ \tau^{*} = \tau''^{*}\) as homomorphisms \(\mathrm{PicEtAff}(C,A) \to
  \mathrm{PicEtAff}(C,A'')\).
\end{theorem}
\begin{proof}
  \leanok
  Fix \([E,\lambda] \in \mathrm{PicEtAff}(C,A)\), and write \(E_{A''}\) for the direct base
  change along \(A \to A''\) and \((E_{A'})_{A''}\) for the iterated base change along
  \(A \to A' \to A''\). Both \(\tau'^{*}(\tau^{*}[E,\lambda])\) and \(\tau''^{*}[E,\lambda]\)
  restrict, respectively, to classes on \((E_{A'})_{A''}\) and on \(E_{A''}\); the two
  canonical inclusions of \(B_E\) into these two carriers, mapped further into the common
  refinement \((E_{A'})_{A''} \times E_{A''}\) via its two coprojections
  (Definition~\ref{def:etale_cover_prod_coproj}), are two homomorphisms of \(A\)-algebras out
  of \(B_E\) landing in the same ring. By the keystone (Theorem~\ref{thm:relPicAlgMap_congr}),
  since \(\lambda \in \mathrm{Desc}(C,E)\), these two composite pullbacks of \(\lambda\) agree;
  unwinding this equality through functoriality of transport identifies the transports of
  \(\tau'^{*}(\tau^{*}[E,\lambda])\) and \(\tau''^{*}[E,\lambda]\) to the common refinement
  \((E_{A'})_{A''} \times E_{A''}\), so by Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff},
  \(\tau'^{*}(\tau^{*}[E,\lambda]) = \tau''^{*}[E,\lambda]\).
\end{proof}

\section{Separatedness I: pullback along the projection is injective}

The plus construction of the preceding sections is a legitimate computation of the \'etale
sheafification only because \emph{one} plus suffices, and that rests on the relative Picard
functor being separated for the \'etale topology. This section establishes the geometric heart
of that separatedness: pullback of Picard classes along the projection
\(\mathrm{pr} \colon C \otimes T \to T\) is \emph{injective}, for every test object \(T\).

Throughout, \(k\) is a field and \(C\) is an object of \(\Over(\Spec k)\) which is proper,
geometrically irreducible and geometrically reduced over \(k\). We recall from elsewhere in
this project the definitional Picard layer on a scheme \(X\): a \emph{pointed cover}
\(\mathcal U\) of \(X\) assigns to each point \(x \in X\) an open \(\mathcal U(x) \ni x\);
pointed covers are ordered by pointwise inclusion (a \emph{refinement}
\(\mathcal W \le \mathcal U\)), with pointwise intersection as meet; a \emph{unit \v Cech
\(1\)-cocycle} \(\gamma\) on \(\mathcal U\) assigns to each pair \(x,y\) a unit
\(\gamma_{xy} \in \struct X(\mathcal U(x) \cap \mathcal U(y))^{\times}\) satisfying
\(\gamma_{xy}\gamma_{yz} = \gamma_{xz}\) on triple intersections; \(\check H^1(\mathcal U)\)
is the group of such cocycles modulo coboundaries \((\delta\alpha)_{xy} =
\alpha_x\alpha_y^{-1}\) for families of units \(\alpha_x \in
\struct X(\mathcal U(x))^{\times}\); restriction along a refinement is a group homomorphism
\(\check H^1(\mathcal U) \to \check H^1(\mathcal W)\); and the Picard group
\(\Pic(X)\) is the colimit of the \(\check H^1(\mathcal U)\) along the (directed) refinement
order, with structure maps written \([\mathcal U, a] \in \Pic(X)\), and with contravariant
pullback \(f^{*} \colon \Pic(Y) \to \Pic(X)\) along a morphism \(f \colon X \to Y\), computed
by pulling back the cover pointwise and the cocycle by \(f^{\sharp}\).

\begin{lemma}[Separation for unit sections]
  \label{lem:units_separation}
  \lean{AlgebraicGeometry.Scheme.unitsRestrict_eq_of_locally_eq}
  \leanok
  Let \(X\) be a scheme, \(V \subseteq X\) open, and \((W_i)_{i \in I}\) a family of opens
  with \(W_i \subseteq V\) and \(V \subseteq \bigcup_i W_i\). If two units
  \(s, t \in \struct X(V)^{\times}\) satisfy \(s|_{W_i} = t|_{W_i}\) for all \(i\), then
  \(s = t\).
\end{lemma}
\begin{proof}
  \leanok
  Units are equal once their underlying sections are, and the underlying sections agree on a
  cover of \(V\); conclude by the separation half of the sheaf axiom for \(\struct X\).
\end{proof}

\begin{lemma}[Gluing for unit sections]
  \label{lem:units_gluing}
  \lean{AlgebraicGeometry.Scheme.exists_unitsRestrict_eq}
  \leanok
  Let \(X\) be a scheme, \(V \subseteq X\) open, and \((W_i)_{i \in I}\) a family of opens
  with \(W_i \subseteq V\) and \(V \subseteq \bigcup_i W_i\). Any family of units
  \(u_i \in \struct X(W_i)^{\times}\) with \(u_i|_{W_i \cap W_j} = u_j|_{W_i \cap W_j}\) for
  all \(i,j\) glues to a unit \(s \in \struct X(V)^{\times}\) with \(s|_{W_i} = u_i\).
\end{lemma}
\begin{proof}
  \leanok
  \uses{lem:units_separation}
  The underlying sections \((u_i)\) form a compatible family, as do the inverses
  \((u_i^{-1})\); by the sheaf axiom they glue to sections \(s, s' \in \struct X(V)\)
  respectively. The products \(s s'\) and \(s' s\) restrict to \(1\) on every \(W_i\), hence
  equal \(1\) by the separation half of the sheaf axiom; so \(s\) is a unit, and it restricts
  to \(u_i\) because its underlying section does.
\end{proof}

\begin{lemma}[Restriction of unit sections is transitive]
  \label{lem:unitsRestrict_trans}
  \lean{AlgebraicGeometry.Scheme.unitsRestrict_unitsRestrict}
  \leanok
  For opens \(W \subseteq V \subseteq U\) of a scheme \(X\) and
  \(u \in \struct X(U)^{\times}\), restricting \(u\) to \(V\) and then to \(W\) is
  restricting \(u\) to \(W\).
\end{lemma}
\begin{proof}
  \leanok
  Functoriality of the structure presheaf, applied to the underlying sections.
\end{proof}

\begin{theorem}[Refinement injectivity in degree one]
  \label{thm:unitsRes_injective}
  \lean{AlgebraicGeometry.Scheme.unitsRes_injective}
  \leanok
  Let \(X\) be a scheme and \(\mathcal W \le \mathcal U\) pointed covers of \(X\). Then
  restriction \(\check H^1(\mathcal U) \to \check H^1(\mathcal W)\) is injective.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:units_separation, lem:units_gluing, lem:unitsRestrict_trans}
  Restriction is a group homomorphism, so it suffices to show a cocycle \(\gamma\) on
  \(\mathcal U\) whose restriction to \(\mathcal W\) is a coboundary, say
  \(\gamma_{zz'}|_{\mathcal W(z) \cap \mathcal W(z')} = \alpha_z \alpha_{z'}^{-1}\) with
  \(\alpha_z \in \struct X(\mathcal W(z))^{\times}\), is itself a coboundary. Fix a point
  \(i\) and consider, for each point \(z\), the \emph{comparison unit}
  \[ s_{i,z} := \alpha_z \cdot \gamma_{iz}^{-1}
     \in \struct X\bigl(\mathcal U(i) \cap \mathcal W(z)\bigr)^{\times}, \]
  which makes sense since \(\mathcal W(z) \subseteq \mathcal U(z)\). On the overlap
  \((\mathcal U(i) \cap \mathcal W(z)) \cap (\mathcal U(i) \cap \mathcal W(z'))\) the cocycle
  identity \(\gamma_{iz}\gamma_{zz'} = \gamma_{iz'}\) at \((i,z,z')\) and the coboundary
  relation \(\alpha_z \gamma_{zz'} = \alpha_{z'}\) give
  \(s_{i,z'} = \alpha_z\gamma_{zz'}\cdot(\gamma_{iz}\gamma_{zz'})^{-1} = s_{i,z}\). Since
  every point \(w \in \mathcal U(i)\) lies in \(\mathcal U(i) \cap \mathcal W(w)\), these
  opens cover \(\mathcal U(i)\), and by gluing (Lemma~\ref{lem:units_gluing}) there is
  \(\beta_i \in \struct X(\mathcal U(i))^{\times}\) with
  \(\beta_i|_{\mathcal U(i) \cap \mathcal W(z)} = s_{i,z}\) for all \(z\). Finally, for any
  \(i, j\), on each member \(\mathcal U(i) \cap \mathcal U(j) \cap \mathcal W(z)\) of a cover
  of \(\mathcal U(i) \cap \mathcal U(j)\) we compute, using the cocycle identity at
  \((i,j,z)\),
  \[ \beta_i \gamma_{ij} = \alpha_z \gamma_{iz}^{-1}\gamma_{ij}
       = \alpha_z \gamma_{jz}^{-1} = \beta_j , \]
  so \(\beta_i \gamma_{ij} = \beta_j\) on \(\mathcal U(i) \cap \mathcal U(j)\) by separation
  (Lemma~\ref{lem:units_separation}); that is, \(\gamma = \delta(\beta^{-1})\) is a
  coboundary.
\end{proof}

\begin{corollary}[Triviality is detected on the representing cover]
  \label{cor:cechPic_mk_eq_one}
  \lean{AlgebraicGeometry.Scheme.CechPic.mk_eq_one_iff}
  \leanok
  For a pointed cover \(\mathcal U\) of a scheme \(X\) and \(a \in \check H^1(\mathcal U)\),
  the Picard class \([\mathcal U, a] \in \Pic(X)\) is trivial if and only if \(a = 1\).
\end{corollary}
\begin{proof}
  \leanok
  \uses{thm:unitsRes_injective}
  If \([\mathcal U, a] = 1\) then \(a\) and \(1\) restrict to the same class on some common
  refinement \(\mathcal W \le \mathcal U\); by refinement injectivity
  (Theorem~\ref{thm:unitsRes_injective}) already \(a = 1\). The converse is immediate.
\end{proof}

\begin{corollary}[\(\check H^1\) of a cover embeds in the Picard group]
  \label{cor:cechPic_mk_injective}
  \lean{AlgebraicGeometry.Scheme.CechPic.mk_injective}
  \leanok
  For every pointed cover \(\mathcal U\) of a scheme \(X\), the canonical map
  \(\check H^1(\mathcal U) \to \Pic(X)\), \(a \mapsto [\mathcal U, a]\), is injective.
\end{corollary}
\begin{proof}
  \leanok
  \uses{cor:cechPic_mk_eq_one}
  The map is a group homomorphism, and its kernel is trivial by
  Corollary~\ref{cor:cechPic_mk_eq_one}.
\end{proof}

\begin{lemma}[Everything is flat over a field]
  \label{lem:flat_of_field}
  \lean{AlgebraicGeometry.Flat.of_field}
  \leanok
  Every morphism of schemes \(X \to \Spec K\), \(K\) a field, is flat.
\end{lemma}
\begin{proof}
  \leanok
  Flatness is Zariski-local on the source, so it suffices to treat
  \(\Spec B \to \Spec K\), i.e.\ a ring homomorphism \(K \to B\); every module over a field
  is free, hence flat.
\end{proof}

\begin{lemma}[Affine refinement of pointed covers]
  \label{lem:pointedCover_affine_refinement}
  \lean{AlgebraicGeometry.Scheme.PointedCover.exists_isAffineOpen_le}
  \leanok
  Every pointed cover of a scheme admits a refinement all of whose members are affine open.
\end{lemma}
\begin{proof}
  \leanok
  The affine opens form a basis of the topology of a scheme: for each point \(x\) choose an
  affine open \(V(x)\) with \(x \in V(x) \subseteq \mathcal U(x)\).
\end{proof}

\begin{theorem}[Sections over an affine open pull back bijectively]
  \label{thm:isIso_appLE_snd}
  \lean{AlgebraicGeometry.Over.isIso_appLE_snd}
  \leanok
  Let \(T\) be an object of \(\Over(\Spec k)\) and \(V \subseteq T\) an affine open. Then
  pullback of sections along the second projection
  \(\mathrm{pr} \colon C \otimes T \to T\) is an isomorphism
  \[ \Gamma(T, V) \;\xrightarrow{\ \sim\ }\; \Gamma\bigl(C \otimes T,\
     \mathrm{pr}^{-1}V\bigr). \]
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:flat_of_field, cor:curve_sections}
  The underlying scheme of \(C \otimes T\) is the fibre product
  \(C \times_{\Spec k} T\). Since \(C\) is proper over the field \(k\), its underlying space
  is quasi-compact and quasi-separated, and \(T \to \Spec k\) is flat
  (Lemma~\ref{lem:flat_of_field}); therefore the canonical square of section rings
  \[ \begin{array}{ccc}
     \Gamma(\Spec k, \struct{}) & \longrightarrow & \Gamma(C, \struct C) \\
     \downarrow & & \downarrow \\
     \Gamma(T, V) & \longrightarrow & \Gamma(C \otimes T, \mathrm{pr}^{-1}V)
     \end{array} \]
  --- with the affine slots at \(\Spec k\) (all of it) and at \(V \subseteq T\), and the
  quasi-compact quasi-separated slot at all of \(C\) --- is a pushout of commutative rings:
  the flat-base-change theorem for sections of fibre products. The top edge is an
  isomorphism, \(\Gamma(C, \struct C) = k\) (Corollary~\ref{cor:curve_sections}); a pushout
  of an isomorphism is an isomorphism, so the bottom edge is one too.
\end{proof}

\begin{corollary}[Sections pull back injectively over every open]
  \label{cor:appLE_snd_injective}
  \lean{AlgebraicGeometry.Over.appLE_snd_injective}
  \leanok
  Let \(T\) be an object of \(\Over(\Spec k)\) and \(W \subseteq T\) any open. Then pullback
  of sections along the second projection,
  \(\Gamma(T, W) \to \Gamma(C \otimes T, \mathrm{pr}^{-1}W)\), is injective.
\end{corollary}
\begin{proof}
  \leanok
  \uses{thm:isIso_appLE_snd}
  Let \(s, t \in \Gamma(T,W)\) have equal pullbacks. For every affine open \(V \subseteq W\),
  restriction to \(\mathrm{pr}^{-1}V\) followed by the bijection of
  Theorem~\ref{thm:isIso_appLE_snd} shows \(s|_V = t|_V\); the affine opens contained in
  \(W\) cover \(W\), so \(s = t\) by separation for \(\struct T\).
\end{proof}

\begin{corollary}[Unit sections over an affine open pull back bijectively]
  \label{cor:unitsAppLE_snd_bijective}
  \lean{AlgebraicGeometry.Over.unitsAppLE_snd_bijective}
  \leanok
  Let \(T\) be an object of \(\Over(\Spec k)\) and \(V \subseteq T\) an affine open. Then
  pullback along the second projection is a bijection
  \(\Gamma(T, V)^{\times} \to \Gamma(C \otimes T, \mathrm{pr}^{-1}V)^{\times}\) of unit
  groups.
\end{corollary}
\begin{proof}
  \leanok
  \uses{thm:isIso_appLE_snd, cor:appLE_snd_injective}
  Injectivity on units follows from injectivity on sections
  (Corollary~\ref{cor:appLE_snd_injective}). For surjectivity, a unit
  \(y \in \Gamma(C \otimes T, \mathrm{pr}^{-1}V)^{\times}\) and its inverse are pullbacks of
  sections \(a, b \in \Gamma(T,V)\) by Theorem~\ref{thm:isIso_appLE_snd}; the products
  \(ab\) and \(ba\) pull back to \(1\), hence equal \(1\) by injectivity, so \(a\) is a unit
  pulling back to \(y\).
\end{proof}

\begin{lemma}[The projection is surjective]
  \label{lem:surjective_snd}
  \lean{AlgebraicGeometry.Over.surjective_snd_left}
  \leanok
  For every object \(T\) of \(\Over(\Spec k)\), the second projection
  \(C \otimes T \to T\) is surjective on points.
\end{lemma}
\begin{proof}
  \leanok
  The space of \(C\) is irreducible (geometric irreducibility over the one-point base), in
  particular nonempty, and \(\Spec k\) is a single point; so \(C \to \Spec k\) is
  surjective. Surjectivity of morphisms of schemes is stable under base change, and the
  second projection is the base change of \(C \to \Spec k\) along \(T \to \Spec k\).
\end{proof}

\begin{theorem}[Pullback along the projection is injective on Picard groups]
  \label{thm:prPullback_injective}
  \lean{AlgebraicGeometry.Over.prPullback_injective}
  \leanok
  \source{kleiman-picard}
  For every object \(T\) of \(\Over(\Spec k)\), pullback of Picard classes along the second
  projection, \(\mathrm{pr}^{*} \colon \Pic(T) \to \Pic(C \otimes T)\), is injective.
\end{theorem}
\begin{proof}
  \leanok
  \uses{cor:cechPic_mk_eq_one, lem:pointedCover_affine_refinement, thm:unitsRes_injective,
    cor:appLE_snd_injective, cor:unitsAppLE_snd_bijective, lem:surjective_snd,
    lem:unitsRestrict_trans}
  Pullback is a group homomorphism, so let \(\lambda \in \Pic(T)\) satisfy
  \(\mathrm{pr}^{*}\lambda = 1\). By Lemma~\ref{lem:pointedCover_affine_refinement} and
  invariance of the class under refinement we may represent \(\lambda = [\mathcal U, \gamma]\)
  with \(\mathcal U\) a pointed cover of \(T\) all of whose members \(\mathcal U(t)\) are
  affine. The pullback class is represented on the pulled-back pointed cover
  \(z \mapsto \mathrm{pr}^{-1}\mathcal U(\mathrm{pr}(z))\) by the pulled-back cocycle
  \(\mathrm{pr}^{\sharp}\gamma\), and it is trivial; by
  Corollary~\ref{cor:cechPic_mk_eq_one}, \(\mathrm{pr}^{\sharp}\gamma\) is a coboundary
  \emph{on the pulled-back cover itself}: there are units
  \(w_z \in \struct{C \otimes T}(\mathrm{pr}^{-1}\mathcal U(\mathrm{pr} z))^{\times}\) with
  \[ w_z \cdot \mathrm{pr}^{\sharp}(\gamma_{\mathrm{pr}z, \mathrm{pr}z'}) = w_{z'}
     \qquad\text{on } \mathrm{pr}^{-1}\bigl(\mathcal U(\mathrm{pr}z) \cap
       \mathcal U(\mathrm{pr}z')\bigr). \]
  The projection is surjective (Lemma~\ref{lem:surjective_snd}); choose for each point
  \(t \in T\) a point \(\sigma(t) \in C \otimes T\) over it. Since \(\mathcal U(t)\) is
  affine, the unit \(w_{\sigma(t)} \in
  \struct{C \otimes T}(\mathrm{pr}^{-1}\mathcal U(t))^{\times}\) is the pullback of a unique
  unit \(v_t \in \struct T(\mathcal U(t))^{\times}\)
  (Corollary~\ref{cor:unitsAppLE_snd_bijective}). For any \(t, t'\), applying the injectivity
  of pullback of unit sections on \(\mathcal U(t) \cap \mathcal U(t')\)
  (Corollary~\ref{cor:appLE_snd_injective}, applied to the underlying sections of units) to
  the displayed coboundary relation at \((\sigma(t), \sigma(t'))\) yields
  \(v_t \cdot \gamma_{t t'} = v_{t'}\) on \(\mathcal U(t) \cap \mathcal U(t')\). Hence
  \(\gamma\) is a coboundary, \(\lambda = [\mathcal U, \gamma] = 1\).
\end{proof}

\section{The \v Cech--Picard dictionary}

For a commutative ring \(A\), write \(\operatorname{Pic}(A)\) for its \emph{module} Picard
group: the group, under \(\otimes_A\), of isomorphism classes of invertible \(A\)-modules
--- those \(A\)-modules \(N\) admitting an \(A\)-module \(N'\) with \(N \otimes_A N' \cong A\).
This section identifies, for an affine scheme \(X\) with global ring \(A := \Gamma(X,\struct
X)\), the \v Cech Picard group \(\Pic(X)\) recalled at the head of the previous section ---
the colimit of the groups \(\check H^1(\mathcal U)\) of unit \v Cech \(1\)-cocycles on pointed
covers \(\mathcal U\) of \(X\) --- with \(\operatorname{Pic}(A)\).

For \(f \in A\), write \(D(f) \subseteq X\) for its basic open, the largest open on which the
image of \(f\) in every stalk is a unit; \(D(f) \cap D(g) = D(fg)\), and, \(X\) being affine, a
family \((D(f))_{f \in S}\) covers \(X\) exactly when \(S\) generates the unit ideal of \(A\).
A \emph{finite basic refinement} of a pointed cover \(\mathcal U\) is a finite pointed cover
\(\mathcal W\) refining \(\mathcal U\) all of whose members are basic opens \(D(r_i)\),
\(i \in I\), of elements \(r_i \in A\); since \(X\) is quasi-compact, being affine, every
pointed cover admits one. A unit \v Cech \(1\)-cocycle \(\delta\) on such a \(\mathcal W\)
determines a \emph{descent datum} for the finite faithfully flat algebra
\(A \to \prod_{i \in I} \Gamma(X, D(r_i))\), by twisting the tautological gluing data of the
free rank-one modules \(\Gamma(X,D(r_i))\) by the transition units \(\delta_{ij}\); faithfully
flat descent produces from this datum an \(A\)-module, well defined up to isomorphism, the
\emph{module descended from \(\delta\)}.

\begin{theorem}[Trivializing elements span the unit ideal]
  \label{thm:invertible_span_free}
  \lean{Module.Invertible.span_tensor_free_eq_top}
  \leanok
  Let \(A\) be a commutative ring and \(N\) an invertible \(A\)-module. The ideal generated by
  \[
    \{\, f \in A : S \otimes_A N \text{ is a free } S\text{-module for every localization } S
    \text{ of } A \text{ away from } f \,\}
  \]
  is the unit ideal of \(A\).
\end{theorem}
\begin{proof}
  \leanok
  An invertible module is finitely presented, and for every prime ideal \(\mathfrak p\) of
  \(A\) the localization of \(N\) at \(\mathfrak p\) is a finite flat module over the local
  ring \(A_{\mathfrak p}\), hence free; by finite presentation, freeness at \(\mathfrak p\)
  spreads out to freeness of \(S \otimes_A N\) for \(S\) a localization away from some single
  element \(f \notin \mathfrak p\). If the ideal generated by all such \(f\) were proper, it
  would be contained in some maximal ideal \(\mathfrak m\), contradicting the existence of a
  trivializing element outside \(\mathfrak m\). Hence the ideal is all of \(A\).
\end{proof}

\begin{lemma}[Existence of a trivializing family]
  \label{lem:trivializingFamily_nonempty}
  \lean{AlgebraicGeometry.Scheme.TrivializingFamily.nonempty}
  \uses{thm:invertible_span_free}
  \leanok
  Let \(X\) be an affine scheme with global ring \(A = \Gamma(X,\struct X)\) and \(N\) an
  invertible \(A\)-module. There exists a \emph{trivializing family} for \(N\): an assignment,
  to each point \(x \in X\), of a section \(s_x \in A\) with \(x \in D(s_x)\), together with a
  trivialization
  \[
    \Gamma(X,D(s_x)) \otimes_A N \;\cong\; \Gamma(X,D(s_x))
  \]
  of the base change of \(N\) to \(D(s_x)\).
\end{lemma}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:invertible_span_free} the elements \(f \in A\) over which \(N\) becomes
  free after localizing away from \(f\) generate the unit ideal, so their basic opens \(D(f)\)
  cover \(X\). For each point \(x \in X\) choose one such \(f\) with \(x \in D(f)\) and set
  \(s_x := f\), together with the resulting trivialization of \(\Gamma(X,D(s_x)) \otimes_A
  N\).
\end{proof}

\begin{definition}[The cocycle of a trivializing family]
  \label{def:trivializingFamily_cocycle}
  \lean{AlgebraicGeometry.Scheme.TrivializingFamily.cocycle}
  \uses{lem:trivializingFamily_nonempty}
  \leanok
  Let \(F = (s_x, \mathrm{triv}_x)_{x \in X}\) be a trivializing family for \(N\) as in
  Lemma~\ref{lem:trivializingFamily_nonempty}, and let \(\mathcal U_F(x) := D(s_x)\) be the
  associated pointed cover. For points \(x,y \in X\), pushing \(\mathrm{triv}_x\) and
  \(\mathrm{triv}_y\) forward along the restriction maps to \(D(s_xs_y) = \mathcal U_F(x) \cap
  \mathcal U_F(y)\) produces two trivializations of \(N\) over \(D(s_xs_y)\); their
  \emph{transition unit} is the unique unit \(\gamma_{xy} \in \Gamma(X,D(s_xs_y))^{\times}\)
  with
  \[
    \gamma_{xy} \cdot \bigl(\text{pushforward of } \mathrm{triv}_x\bigr)(1 \otimes n) =
    \bigl(\text{pushforward of } \mathrm{triv}_y\bigr)(1 \otimes n) \qquad \text{for all } n \in
    N.
  \]
  The assignment \((x,y) \mapsto \gamma_{xy}\) is a unit \v Cech \(1\)-cocycle on
  \(\mathcal U_F\).
\end{definition}
\begin{proof}
  \leanok
  The diagonal identity \(\gamma_{xx} = 1\) holds because the two pushforwards of
  \(\mathrm{triv}_x\) to \(D(s_x^2)\) coincide, both being the unique \(A\)-algebra
  homomorphism out of the localization \(\Gamma(X,D(s_x))\) composed with \(\mathrm{triv}_x\).
  For the cocycle identity, push the trivializations \(\mathrm{triv}_x, \mathrm{triv}_y,
  \mathrm{triv}_z\) of a triple \(x,y,z\) forward to the triple overlap \(D(s_xs_ys_z)\): since
  the transition unit between two trivializations composes along a chain of further
  pushforwards --- pushing \(\gamma_{xy}\) and \(\gamma_{yz}\) both forward to
  \(D(s_xs_ys_z)\) compares \(\mathrm{triv}_x\) to \(\mathrm{triv}_y\) and \(\mathrm{triv}_y\)
  to \(\mathrm{triv}_z\) there --- their product equals the transition unit comparing
  \(\mathrm{triv}_x\) directly to \(\mathrm{triv}_z\), which restricts to \(\gamma_{xz}\).
\end{proof}

\begin{theorem}[Descent identification for the trivializing cocycle]
  \label{thm:trivializingFamily_pic_cocycle}
  \lean{AlgebraicGeometry.Scheme.TrivializingFamily.pic_cocycle}
  \uses{def:trivializingFamily_cocycle}
  \leanok
  In the situation of Definition~\ref{def:trivializingFamily_cocycle}, let \(\mathcal W \le
  \mathcal U_F\) be any finite basic refinement of the trivializing cover. Then the class in
  \(\operatorname{Pic}(A)\) of the module descended from the cocycle \(\gamma|_{\mathcal W}\)
  obtained by restricting the trivializing cocycle to \(\mathcal W\) equals the class of \(N\).
\end{theorem}
\begin{proof}
  \leanok
  Write \(\mathcal W(i) = D(r_i)\), \(i \in I\), with \(r_i\) a multiple of \(s_{p(i)}\) for a
  chosen point \(p(i)\) with \(\mathcal W(i) \subseteq \mathcal U_F(p(i))\). Restricting a
  transition unit is compatible with pushing forward its defining trivializations further, so
  the restricted cocycle \(\gamma|_{\mathcal W}\) is exactly the transition cocycle, on
  \(\mathcal W\), of the trivializations of \(N\) obtained by pushing \(\mathrm{triv}_{p(i)}\)
  forward from \(D(s_{p(i)})\) to \(D(r_i)\) for each \(i\). These pushed-forward
  trivializations assemble into one trivialization of \(N\) over the cover algebra
  \(\prod_i \Gamma(X,D(r_i))\), and it intertwines the descent datum twisted by
  \(\gamma|_{\mathcal W}\) with the canonical descent datum of \(N\) base-changed to the cover
  algebra, by the defining property of the transition units on each factor of the twisted
  double-overlap algebra \(\prod_i \Gamma(X,D(r_i)) \otimes_A \prod_i \Gamma(X,D(r_i))\). Since
  the cover algebra is faithfully flat over \(A\) (a finite family of basic opens covering the
  affine \(X\)), uniqueness of descended modules identifies the module descended from
  \(\gamma|_{\mathcal W}\) with \(N\) itself, so their classes in \(\operatorname{Pic}(A)\)
  agree.
\end{proof}

\begin{definition}[The \v Cech--Picard descent homomorphism]
  \label{def:cechPic_toPic}
  \lean{AlgebraicGeometry.Scheme.CechPic.toPic}
  \leanok
  For an affine scheme \(X\) with global ring \(A = \Gamma(X,\struct X)\), the homomorphism of
  groups
  \[
    \operatorname{toPic} \colon \Pic(X) \to \operatorname{Pic}(A), \qquad [\mathcal U,\gamma]
    \mapsto \bigl(\text{class of the module descended from } \gamma|_{\mathcal W}\bigr),
  \]
  where \(\mathcal W\) is any finite basic refinement of \(\mathcal U\) and
  \(\gamma|_{\mathcal W}\) is the cocycle obtained by restricting \(\gamma\) along
  \(\mathcal W \le \mathcal U\).
\end{definition}
\begin{proof}
  \leanok
  The class of the descended module does not depend on the choice of finite basic refinement
  \(\mathcal W\) of \(\mathcal U\): any two such refinements are dominated by a common one, along
  which the two descended modules become identified. Nor does it depend on the representative
  \((\mathcal U,\gamma)\) of the class \([\mathcal U,\gamma] \in \Pic(X)\): a further common
  refinement of two cohomologous representing cocycles carries cohomologous restricted
  cocycles, hence isomorphic descended modules. So \(\operatorname{toPic}\) is a well-defined
  function; it is a homomorphism because descending along a common refinement is compatible
  with the pointwise product of cocycles and with tensor product of the descended modules.
\end{proof}

\begin{theorem}[Injectivity of the descent homomorphism]
  \label{thm:cechPic_toPic_injective}
  \lean{AlgebraicGeometry.Scheme.CechPic.toPic_injective}
  \uses{def:cechPic_toPic, cor:cechPic_mk_eq_one}
  \leanok
  For every affine scheme \(X\), the descent homomorphism \(\operatorname{toPic} \colon
  \Pic(X) \to \operatorname{Pic}(A)\) of Definition~\ref{def:cechPic_toPic} is injective.
\end{theorem}
\begin{proof}
  \leanok
  It suffices to show that a class \([\mathcal U,\gamma]\) with
  \(\operatorname{toPic}[\mathcal U,\gamma] = 1\) is itself trivial. Represent
  \([\mathcal U,\gamma]\) along a finite basic refinement \(\mathcal W \le \mathcal U\) as in
  Definition~\ref{def:cechPic_toPic}: since the module descended from \(\gamma|_{\mathcal W}\)
  is isomorphic to \(A\), its twisted descent datum is isomorphic to the trivial descent datum
  on \(\prod_i \Gamma(X,\mathcal W(i))\), so the transition units of \(\gamma\) restricted to
  \(\mathcal W\) differ from those of the trivial cocycle by an index-wise coboundary. Since the
  opens of \(\mathcal W\) refine those of \(\mathcal U\) and, member by member, cover them, this
  coboundary glues, by the sheaf property of \(\struct X\), to a coboundary for \(\gamma\)
  itself on \(\mathcal U\): \(\gamma = 1\) in \(\check H^1(\mathcal U)\). By
  Corollary~\ref{cor:cechPic_mk_eq_one}, \([\mathcal U,\gamma] = 1\) in \(\Pic(X)\).
\end{proof}

\begin{theorem}[Surjectivity of the descent homomorphism]
  \label{thm:cechPic_toPic_surjective}
  \lean{AlgebraicGeometry.Scheme.CechPic.toPic_surjective}
  \uses{def:cechPic_toPic, lem:trivializingFamily_nonempty, thm:trivializingFamily_pic_cocycle}
  \leanok
  For every affine scheme \(X\), the descent homomorphism \(\operatorname{toPic} \colon
  \Pic(X) \to \operatorname{Pic}(A)\) is surjective.
\end{theorem}
\begin{proof}
  \leanok
  Let \(c \in \operatorname{Pic}(A)\) be represented by an invertible \(A\)-module \(N\). By
  Lemma~\ref{lem:trivializingFamily_nonempty}, \(N\) admits a trivializing family, giving a
  pointed cover \(\mathcal U_F\) together with the unit \v Cech \(1\)-cocycle \(\gamma_F\) of
  Definition~\ref{def:trivializingFamily_cocycle}. Since \(X\) is affine, hence quasi-compact,
  \(\mathcal U_F\) admits a finite basic refinement \(\mathcal W\). By
  Theorem~\ref{thm:trivializingFamily_pic_cocycle}, \(\operatorname{toPic}[\mathcal
  U_F,\gamma_F] = c\). As \(c\) was arbitrary, \(\operatorname{toPic}\) is surjective.
\end{proof}

\begin{theorem}[The \v Cech--Picard dictionary]
  \label{thm:cechPicEquivPic}
  \lean{AlgebraicGeometry.Scheme.cechPicEquivPic}
  \uses{thm:cechPic_toPic_injective, thm:cechPic_toPic_surjective}
  \leanok
  For every affine scheme \(X\) with global ring \(A = \Gamma(X,\struct X)\), the descent
  homomorphism of Definition~\ref{def:cechPic_toPic} is an isomorphism of groups
  \[
    \operatorname{toPic} \colon \Pic(X) \;\xrightarrow{\ \sim\ }\; \operatorname{Pic}(A).
  \]
  In particular the definitional \v Cech Picard group \(\Pic(X)\) on pointed Zariski covers of
  \(X\) is canonically isomorphic to mathlib's Picard group of invertible \(A\)-modules.
\end{theorem}
\begin{proof}
  \leanok
  \(\operatorname{toPic}\) is a bijective group homomorphism by
  Theorem~\ref{thm:cechPic_toPic_injective} (injectivity) and
  Theorem~\ref{thm:cechPic_toPic_surjective} (surjectivity), hence an isomorphism.
\end{proof}

\section{The cocycle presentation of the dictionary, and its naturality in the base}

The \v Cech--Picard dictionary of the previous section passes through a \emph{cocycle}
presentation of the descended module, algebraically equivalent to but more computable than
the trivializing-family presentation used there: a descent \(1\)-cocycle is a single unit of
\(B \otimes_A B\), for \(B\) the (faithfully flat) cover algebra, satisfying a normalization and
a cocycle identity. This section records that presentation and its main structural property,
\emph{naturality in the base ring}: the descended module, and hence its class in
\(\operatorname{Pic}\), is compatible with base change of \(A\) along a further ring map
\(A \to A'\). This is the algebraic counterpart of the compatibility, in the test object, of
the functors compared by Kleiman's Comparison Theorem for the relative Picard functor.

Throughout, \(A \to B\) is a homomorphism of commutative rings, exhibiting \(B\) as a
commutative \(A\)-algebra. Write \(\mu \colon B \otimes_A B \to B\) for the multiplication
homomorphism, \(x \otimes y \mapsto xy\), and, in the triple tensor product
\(B \otimes_A (B \otimes_A B)\), write
\[
  \partial_{23}(w) := 1 \otimes w, \qquad
  \partial_{12}(x \otimes y) := x \otimes (y \otimes 1), \qquad
  \partial_{13}(x \otimes y) := x \otimes (1 \otimes y)
\]
for the three \(A\)-algebra homomorphisms \(B \otimes_A B \to B \otimes_A (B \otimes_A B)\)
recording the three faces of the \(2\)-simplex of the cover \(B\) of \(A\).

\begin{definition}[Descent \(1\)-cocycle]
  \label{def:module_descent_cocycle}
  \lean{Module.IsDescentCocycle}
  \leanok
  A \emph{descent \(1\)-cocycle} relative to \(A \to B\) is a unit \(u \in (B \otimes_A
  B)^{\times}\) such that:
  \begin{enumerate}
    \item (normalization) \(\mu(u) = 1\);
    \item (cocycle identity) \(\partial_{23}(u) \cdot \partial_{12}(u) = \partial_{13}(u)\) in
      \(B \otimes_A (B \otimes_A B)\).
  \end{enumerate}
  When \(B = \prod_i A_{f_i}\) is a finite product of localizations covering \(\Spec A\), this
  is exactly a \v Cech \(1\)-cocycle of units on the cover by the basic opens \(D(f_i)\).
\end{definition}

\begin{definition}[The descended module of a cocycle]
  \label{def:module_descended}
  \lean{Module.IsDescentCocycle.descended}
  \uses{def:module_descent_cocycle}
  \leanok
  Let \(u\) be a descent \(1\)-cocycle relative to \(A \to B\). The \emph{descended} \(A\)-module
  of \(u\) is the \(A\)-submodule
  \[
    \mathrm{descended}(u) := \{\, x \in B : u \cdot (x \otimes 1) = 1 \otimes x \,\} \subseteq B,
  \]
  the equalizer of the two \(A\)-linear maps \(B \to B \otimes_A B\), \(x \mapsto u \cdot (x
  \otimes 1)\) and \(x \mapsto 1 \otimes x\); equivalently, the descended module of the descent
  datum on the \(B\)-module \(B\) whose coaction is \(x \mapsto u \cdot (x \otimes 1)\)
  (counitality is the normalization condition and coassociativity is the cocycle identity).
\end{definition}

\begin{definition}[The Picard class of a cocycle]
  \label{def:module_picClass}
  \lean{Module.IsDescentCocycle.picClass}
  \uses{def:module_descended}
  \leanok
  Assume moreover that \(B\) is faithfully flat over \(A\), and let \(u\) be a descent
  \(1\)-cocycle relative to \(A \to B\). The \emph{Picard class} of \(u\) is the class
  \(\mathrm{picClass}(u) \in \operatorname{Pic}(A)\) of the descended module
  \(\mathrm{descended}(u)\).
\end{definition}
\begin{proof}
  \leanok
  \(B\), as a module over itself, is free of rank one, hence invertible, and the coaction \(x
  \mapsto u \cdot (x \otimes 1)\) is a descent datum on \(B\) relative to \(A \to B\)
  (Definition~\ref{def:module_descended}) whose descended module is \(\mathrm{descended}(u)\) by
  definition. Since invertibility of modules descends along faithfully flat ring maps together
  with a descent datum, \(\mathrm{descended}(u)\) is an invertible \(A\)-module, so it has a
  well-defined class in \(\operatorname{Pic}(A)\).
\end{proof}

\begin{definition}[Base change of the tensor square and tensor cube of a cover]
  \label{def:module_tensorSqBaseChange}
  \lean{Module.tensorSqBaseChange, Module.tensorCubeBaseChange}
  \leanok
  Let \(A \to A'\) be a homomorphism of commutative rings and \(B\) a commutative
  \(A\)-algebra. The \emph{base change of the tensor square} of the cover \(B\) along
  \(A \to A'\) is the canonical \(A\)-algebra homomorphism
  \[
    B \otimes_A B \;\longrightarrow\; (A' \otimes_A B) \otimes_{A'} (A' \otimes_A B), \qquad
    x \otimes y \mapsto (1 \otimes x) \otimes (1 \otimes y).
  \]
  Likewise, the \emph{base change of the tensor cube} is the canonical \(A\)-algebra
  homomorphism on triple tensor products
  \[
    B \otimes_A (B \otimes_A B) \;\longrightarrow\; (A' \otimes_A B) \otimes_{A'} \bigl( (A'
    \otimes_A B) \otimes_{A'} (A' \otimes_A B) \bigr), \qquad
    x \otimes (y \otimes z) \mapsto (1 \otimes x) \otimes \bigl( (1 \otimes y) \otimes (1
    \otimes z) \bigr).
  \]
\end{definition}

\begin{theorem}[Base change of a descent cocycle]
  \label{thm:module_descentCocycle_baseChange}
  \lean{Module.IsDescentCocycle.baseChange}
  \uses{def:module_descent_cocycle, def:module_tensorSqBaseChange}
  \leanok
  Let \(A \to A'\) and \(A \to B\) be homomorphisms of commutative rings and let \(u\) be a
  descent \(1\)-cocycle relative to \(A \to B\). Then the image of \(u\) under the base-change
  homomorphism of Definition~\ref{def:module_tensorSqBaseChange} is a descent \(1\)-cocycle
  relative to \(A' \to A' \otimes_A B\).
\end{theorem}
\begin{proof}
  \leanok
  Write \(\varphi \colon B \otimes_A B \to (A' \otimes_A B) \otimes_{A'} (A' \otimes_A B)\) for
  the base-change homomorphism and \(\psi\) for its analogue on triple tensor products
  (Definition~\ref{def:module_tensorSqBaseChange}). On elementary tensors,
  \[
    \mu'(\varphi(x \otimes y)) = (1 \otimes x)(1 \otimes y) = 1 \otimes xy = \iota(\mu(x \otimes
    y)),
  \]
  where \(\iota \colon B \to A' \otimes_A B\), \(b \mapsto 1 \otimes b\), is the canonical
  inclusion and \(\mu'\) is the multiplication of \(A' \otimes_A B\); and, using
  \(1 \otimes_{A'} 1 = 1\) under the identification \(A' \otimes_A B \cong A' \otimes_{A'} (A'
  \otimes_A B)\),
  \[
    \partial'_{23}(\varphi(x \otimes y)) = \psi(\partial_{23}(x \otimes y)), \qquad
    \partial'_{12}(\varphi(x \otimes y)) = \psi(\partial_{12}(x \otimes y)), \qquad
    \partial'_{13}(\varphi(x \otimes y)) = \psi(\partial_{13}(x \otimes y)),
  \]
  where \(\partial'_{23}, \partial'_{12}, \partial'_{13}\) are the face maps of \(A' \to A'
  \otimes_A B\). Both sides of each displayed identity are \(A\)-bilinear in \(x, y\), so the
  identities extend from elementary tensors to all of \(B \otimes_A B\) by linearity.

  Applying \(\mu'\) to \(\varphi(u)\) and using the first identity together with the
  normalization \(\mu(u) = 1\) gives \(\mu'(\varphi(u)) = \iota(\mu(u)) = \iota(1) = 1\), the
  normalization of \(\varphi(u)\). Applying \(\psi\) to the cocycle identity \(\partial_{23}(u)
  \cdot \partial_{12}(u) = \partial_{13}(u)\) and using the remaining three identities gives
  \[
    \partial'_{23}(\varphi(u)) \cdot \partial'_{12}(\varphi(u)) = \psi\bigl(\partial_{23}(u)
    \cdot \partial_{12}(u)\bigr) = \psi(\partial_{13}(u)) = \partial'_{13}(\varphi(u)),
  \]
  the cocycle identity for \(\varphi(u)\). Hence \(\varphi(u)\) is a descent \(1\)-cocycle
  relative to \(A' \to A' \otimes_A B\).
\end{proof}

\begin{theorem}[Base change of the descended module]
  \label{thm:module_descendedBaseChangeEquiv}
  \lean{Module.descendedBaseChangeEquiv}
  \uses{thm:module_descentCocycle_baseChange, def:module_descended}
  \leanok
  Let \(A \to A'\) and \(A \to B\) be homomorphisms of commutative rings with \(B\) faithfully
  flat over \(A\), and let \(u\) be a descent \(1\)-cocycle relative to \(A \to B\), with base
  change \(u' := \varphi(u)\) relative to \(A' \to A' \otimes_A B\)
  (Theorem~\ref{thm:module_descentCocycle_baseChange}). Then there is a canonical isomorphism of
  \(A'\)-modules
  \[
    A' \otimes_A \mathrm{descended}(u) \;\cong\; \mathrm{descended}(u').
  \]
\end{theorem}
\begin{proof}
  \leanok
  Write \(B' := A' \otimes_A B\); since faithful flatness is preserved by base change, \(B'\) is
  faithfully flat over \(A'\), so \(\mathrm{descended}(u')\) is the descended module of the
  tautological descent datum on the \(B'\)-module \(B'\) twisted by \(u'\)
  (Definition~\ref{def:module_descended}), and by the uniqueness property of descended modules
  it suffices to produce a \(B'\)-linear isomorphism
  \(B' \otimes_{A'} \bigl(A' \otimes_A \mathrm{descended}(u)\bigr) \cong B'\) intertwining the
  base change of the coaction \(x \mapsto u \cdot (x \otimes 1)\) on \(\mathrm{descended}(u)\)
  with the coaction \(y \mapsto u' \cdot (y \otimes 1)\) on \(B'\).

  Cancelling the iterated base change identifies \(B'\)-modules
  \[
    B' \otimes_{A'} \bigl(A' \otimes_A \mathrm{descended}(u)\bigr) \;\cong\; B' \otimes_A
    \mathrm{descended}(u) \;\cong\; B' \otimes_B \bigl(B \otimes_A \mathrm{descended}(u)\bigr),
  \]
  and tensoring the descent isomorphism \(B \otimes_A \mathrm{descended}(u) \cong B\) attached to
  \(u\) with \(B'\) over \(B\) turns the right side into \(B' \otimes_B B \cong B'\). On
  elementary tensors, the resulting isomorphism sends \(b' \otimes (a' \otimes n)\), for
  \(b' \in B'\), \(a' \in A'\), \(n \in \mathrm{descended}(u)\), to \((a' b') \cdot n\) (viewing
  \(n \in \mathrm{descended}(u) \subseteq B\) inside \(B'\) via \(\iota\)); using the membership
  identity \(u \cdot (n \otimes 1) = 1 \otimes n\), this identification carries the base-changed
  coaction on the left to the coaction \(y \mapsto u' \cdot (y \otimes 1)\) on the right. Hence
  the isomorphism intertwines the two coactions, and uniqueness of descended modules produces
  the canonical isomorphism \(A' \otimes_A \mathrm{descended}(u) \cong \mathrm{descended}(u')\).
\end{proof}

\begin{theorem}[Naturality of the Picard class in the base ring]
  \label{thm:module_picClass_baseChange}
  \lean{Module.IsDescentCocycle.picClass_baseChange}
  \uses{thm:module_descendedBaseChangeEquiv, def:module_picClass}
  \source{kleiman-picard}
  \leanok
  Let \(A \to A'\) and \(A \to B\) be homomorphisms of commutative rings with \(B\) faithfully
  flat over \(A\) and \(A' \otimes_A B\) faithfully flat over \(A'\), and let \(u\) be a descent
  \(1\)-cocycle relative to \(A \to B\) with base change \(u'\) relative to \(A' \to A'
  \otimes_A B\) (Theorem~\ref{thm:module_descentCocycle_baseChange}). Then
  \[
    \mathrm{picClass}(u') = \bigl[A' \otimes_A \mathrm{descended}(u)\bigr] \quad \text{in }
    \operatorname{Pic}(A'),
  \]
  that is, the Picard class of the base-changed cocycle is the image of \(\mathrm{picClass}(u)\)
  under the base-change homomorphism \(\operatorname{Pic}(A) \to \operatorname{Pic}(A')\),
  \([N] \mapsto [A' \otimes_A N]\).
\end{theorem}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:module_descendedBaseChangeEquiv}, \(A' \otimes_A \mathrm{descended}(u)
  \cong \mathrm{descended}(u')\) as \(A'\)-modules, so these two invertible \(A'\)-modules have
  the same class in \(\operatorname{Pic}(A')\). The left side represents the image of
  \(\mathrm{picClass}(u) = [\mathrm{descended}(u)]\) under the base-change homomorphism
  \([N] \mapsto [A' \otimes_A N]\), and the right side represents \(\mathrm{picClass}(u')\) by
  definition; hence \(\mathrm{picClass}(u') = \bigl[A' \otimes_A \mathrm{descended}(u)\bigr]\)
  is the image of \(\mathrm{picClass}(u)\) under this homomorphism.
\end{proof}

\section{Base change of a finite localization cover cocycle}
\label{sec:awayCover_baseChange}

Fix a homomorphism of commutative rings \(A \to A'\) and a finite family \(f \colon \iota \to
A\).  For each index we fix localization models
\[
  S_i = A_{f_i}, \qquad T_{ij} = A_{f_i f_j}, \qquad W_{ijk} = A_{f_i f_j f_k},
\]
and the analogous \(A'\)-side models \(S'_i, T'_{ij}, W'_{ijk}\) for the pushed family
\(f'_i := \varphi(f_i)\), where \(\varphi \colon A \to A'\) is the structure map; each primed
model also carries the \(A\)-algebra structure of the tower \(A \to A' \to \cdot\).  This
section transports the whole \v Cech picture of the cover \(f\) to the cover \(f'\).

\begin{definition}[Base-change maps between localization models]
  \label{def:awayCover_baseChangeMaps}
  \lean{IsLocalization.AwayCover.mapAway, IsLocalization.AwayCover.mapOverlap,
    IsLocalization.AwayCover.mapTriple}
  \leanok
  Because \(f_i\) becomes invertible in \(S'_i\) through the tower \(A \to A' \to S'_i\),
  there is a unique \(A\)-algebra homomorphism \(S_i = A_{f_i} \to S'_i\); denote it by
  \(\mathrm{mapAway}_i\).  Likewise, \(f_i f_j\) is invertible in \(T'_{ij}\) and
  \(f_i f_j f_k\) in \(W'_{ijk}\), giving unique \(A\)-algebra homomorphisms
  \[
    \mathrm{mapOverlap}_{ij} \colon T_{ij} \to T'_{ij}, \qquad
    \mathrm{mapTriple}_{ijk} \colon W_{ijk} \to W'_{ijk}.
  \]
\end{definition}

\begin{theorem}[Base change of a cover cocycle]
  \label{thm:awayCover_isCoverCocycle_baseChange}
  \lean{IsLocalization.AwayCover.IsCoverCocycle.baseChange}
  \uses{def:awayCover_baseChangeMaps}
  \leanok
  Let \(\gamma = (\gamma_{ij})\) with \(\gamma_{ij} \in T_{ij}^{\times}\) be a cover cocycle
  for \(f\): its diagonal restrictions \(\gamma_{ii}\) map to \(1\) in \(T_{ii}\), and on
  triple overlaps the cocycle identity
  \(\partial_{23}\gamma_{jk} \cdot \partial_{12}\gamma_{ij} = \partial_{13}\gamma_{ik}\) holds
  in \(W_{ijk}\).  Then the pushed family
  \(\gamma'_{ij} := \mathrm{mapOverlap}_{ij}(\gamma_{ij}) \in (T'_{ij})^{\times}\) is a cover
  cocycle for \(f'\).
\end{theorem}
\begin{proof}
  \leanok
  Each restriction map in the \v Cech picture — the diagonal identification \(T_{ii} \to
  T_{ij}\) and the three face maps \(\partial_{12}, \partial_{13}, \partial_{23}\) from
  \(T\)-overlaps to \(W\)-triples — fits into a square with its primed analogue and the maps of
  Definition~\ref{def:awayCover_baseChangeMaps}.  Both composites in each such square are
  \(A\)-algebra homomorphisms out of a localization of \(A\), which admits at most one such
  homomorphism to any fixed target; hence the squares commute.  Applying the diagonal square to
  \(\gamma_{ii}\) and using \(\gamma_{ii} \mapsto 1\) shows \(\gamma'_{ii} \mapsto 1\); applying
  the three face squares to the cocycle identity for \(\gamma\) and using multiplicativity of
  \(\mathrm{mapTriple}_{ijk}\) yields the cocycle identity for \(\gamma'\).  Thus \(\gamma'\) is
  a cover cocycle for \(f'\).
\end{proof}

\begin{definition}[Base-change map of cover algebras]
  \label{def:awayCover_piBaseChangeLift}
  \lean{IsLocalization.AwayCover.piBaseChangeLift}
  \uses{def:awayCover_baseChangeMaps}
  \leanok
  The maps \(\mathrm{mapAway}_i\) assemble into a componentwise \(A\)-algebra homomorphism
  \(\prod_i S_i \to \prod_i S'_i\), and hence, by the universal property of base change, into a
  canonical \(A'\)-algebra homomorphism
  \[
    j \colon A' \otimes_A \Bigl(\prod_i S_i\Bigr) \longrightarrow \prod_i S'_i, \qquad
    a' \otimes s \mapsto a' \cdot \bigl(\mathrm{mapAway}_i(s_i)\bigr)_i,
  \]
  the \emph{base-change map of cover algebras}.
\end{definition}

\begin{theorem}[Base change of the descent unit]
  \label{thm:awayCover_cocycleUnit_baseChange}
  \lean{IsLocalization.AwayCover.cocycleUnit_baseChange}
  \uses{def:awayCover_baseChangeMaps, def:awayCover_piBaseChangeLift,
    thm:awayCover_isCoverCocycle_baseChange, def:module_tensorSqBaseChange}
  \leanok
  Under the canonical identification of the double product \(\prod_{i,j} T_{ij}\) with the
  tensor square \(\bigl(\prod_i S_i\bigr) \otimes_A \bigl(\prod_i S_i\bigr)\), a cover cocycle
  \(\gamma\) determines a descent unit \(c(\gamma) \in \bigl((\prod_i S_i) \otimes_A (\prod_i
  S_i)\bigr)^{\times}\).  Then the image of \(c(\gamma)\) under the base change of the tensor
  square (Definition~\ref{def:module_tensorSqBaseChange}) along \(A \to A'\), followed by the
  tensor square of the base-change map \(j\)
  (Definition~\ref{def:awayCover_piBaseChangeLift}), is the descent unit \(c(\gamma')\) of the
  pushed cocycle \(\gamma'\) (Theorem~\ref{thm:awayCover_isCoverCocycle_baseChange}):
  \[
    (j \otimes j)\bigl(\mathrm{tensorSqBaseChange}(c(\gamma))\bigr) = c(\gamma')
    \quad\text{in }\Bigl(\bigl(\textstyle\prod_i S'_i\bigr) \otimes_{A'} \bigl(\prod_i
    S'_i\bigr)\Bigr)^{\times}.
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both sides are units, so it suffices to compare their values under the identification of the
  tensor square \(\bigl(\prod_i S'_i\bigr) \otimes_{A'} \bigl(\prod_i S'_i\bigr)\) with the
  double product \(\prod_{i,j} T'_{ij}\).  The composite
  \[
    \Bigl(\prod_{i,j} T_{ij}\Bigr) \longrightarrow \bigl(\textstyle\prod_i S_i\bigr) \otimes_A
    \bigl(\prod_i S_i\bigr) \xrightarrow{\ \mathrm{tensorSqBaseChange}\ } \bigl(\textstyle\prod_i
    S'_i\bigr) \otimes_{A'} \bigl(\prod_i S'_i\bigr) \xrightarrow{\ j \otimes j\ }
    \Bigl(\prod_{i,j} T'_{ij}\Bigr)
  \]
  is an \(A\)-algebra homomorphism out of the product of localizations \(\prod_{i,j} T_{ij}\);
  by the pi-extensionality principle it is determined by its values on the coordinate
  idempotents \(e_{ij}\).  A direct computation on \(e_{ij}\) — unfolding
  \(\mathrm{tensorSqBaseChange}\), the tensor product \(j \otimes j\), and the componentwise
  maps \(\mathrm{mapAway}\) — shows the composite agrees coordinatewise with
  \(\bigl(\mathrm{mapOverlap}_{ij}\bigr)_{i,j}\).  Applying this identity of homomorphisms to the
  unit representing \(\gamma\) gives, coordinatewise, \(\gamma'_{ij} =
  \mathrm{mapOverlap}_{ij}(\gamma_{ij})\), i.e.\ the descent unit \(c(\gamma')\).
\end{proof}

\begin{lemma}[Base change preserves covering families]
  \label{lem:awayCover_span_range_baseChange}
  \lean{IsLocalization.AwayCover.span_range_algebraMap_eq_top}
  \leanok
  If the family \(f\) is covering, \(\mathrm{span}\,\{f_i\} = A\), then the pushed family
  \(f'_i = \varphi(f_i)\) is covering as well, \(\mathrm{span}\,\{f'_i\} = A'\).
\end{lemma}
\begin{proof}
  \leanok
  The ideal of \(A'\) generated by the pushed family is the extension along \(\varphi \colon A
  \to A'\) of the ideal generated by \(f\), that is \(\mathrm{span}\,\{\varphi(f_i)\}\) is the
  image ideal \(\varphi_{*}\bigl(\mathrm{span}\,\{f_i\}\bigr)\).  By hypothesis
  \(\mathrm{span}\,\{f_i\} = A\) is the unit ideal, and the extension of the unit ideal is again
  the unit ideal \(A'\); hence \(\mathrm{span}\,\{f'_i\} = A'\).
\end{proof}

\begin{lemma}[Base change of a covering product of localizations is faithfully flat]
  \label{lem:awayCover_faithfullyFlat_tensor}
  \lean{IsLocalization.AwayCover.faithfullyFlat_tensor}
  \uses{lem:awayCover_span_range_baseChange}
  \leanok
  If \(f\) is a covering family, \(\mathrm{span}\,\{f_i\} = A\), then the base change \(A'
  \otimes_A \bigl(\prod_i S_i\bigr)\) of the cover algebra is faithfully flat as an
  \(A'\)-module.
\end{lemma}
\begin{proof}
  \leanok
  For each index the base change \(A' \otimes_A S_i\) of the localization \(S_i = A_{f_i}\) is
  the localization \(A'_{f'_i}\) of \(A'\) at the pushed element \(f'_i = \varphi(f_i)\).  Since
  the pushed family \(f'\) is again covering
  (Lemma~\ref{lem:awayCover_span_range_baseChange}), the finite product \(\prod_i (A' \otimes_A
  S_i)\) of localizations at a covering family is faithfully flat over \(A'\).  Finally base
  change commutes with finite products, \(A' \otimes_A \bigl(\prod_i S_i\bigr) \cong \prod_i (A'
  \otimes_A S_i)\) as \(A'\)-modules, and faithful flatness transports along this isomorphism.
\end{proof}

\begin{theorem}[Naturality of the descent Picard class in the base ring]
  \label{thm:awayCover_pic_baseChange}
  \lean{IsLocalization.AwayCover.pic_baseChange}
  \uses{thm:awayCover_cocycleUnit_baseChange, thm:awayCover_isCoverCocycle_baseChange,
    thm:module_picClass_baseChange, def:module_picClass,
    lem:awayCover_span_range_baseChange, lem:awayCover_faithfullyFlat_tensor}
  \source{kleiman-picard}
  \leanok
  Assume the localization covers are faithfully flat, \(\prod_i S_i\) over \(A\) and \(\prod_i
  S'_i\) over \(A'\), and that \(f\) is a covering family, \(\mathrm{span}\,\{f_i\} = A\).  Then
  the Picard class of the descended module of the pushed cocycle \(\gamma'\) is the image of the
  Picard class of \(\gamma\) under the base-change homomorphism \(\Pic(A) \to \Pic(A')\),
  \([N] \mapsto [A' \otimes_A N]\):
  \[
    \mathrm{picClass}(c(\gamma')) = \bigl[A' \otimes_A \mathrm{descended}(c(\gamma))\bigr]
    \quad\text{in }\Pic(A').
  \]
\end{theorem}
\begin{proof}
  \leanok
  Since \(\mathrm{span}\,\{f_i\} = A\), the pushed family \(f'\) again spans \(A'\) (the ideal it
  generates is the image of the unit ideal under \(A \to A'\)), so \(\prod_i (A' \otimes_A S_i)
  \cong A' \otimes_A \prod_i S_i\) is faithfully flat over \(A'\), each factor being a
  localization \(A'_{f'_i}\).  By Theorem~\ref{thm:awayCover_cocycleUnit_baseChange} the descent
  unit \(c(\gamma')\) is the image of the base-changed unit
  \(\mathrm{tensorSqBaseChange}(c(\gamma))\) under the algebra map \(j\) of cover algebras
  (Definition~\ref{def:awayCover_piBaseChangeLift}); as the Picard class of a descent unit is
  unchanged by transport along an algebra map of the cover, \(\mathrm{picClass}(c(\gamma'))\)
  equals the Picard class of \(\mathrm{tensorSqBaseChange}(c(\gamma))\), which is the descent
  unit of the base change of the module cocycle \(c(\gamma)\).  By
  Theorem~\ref{thm:module_picClass_baseChange} this last class is \(\bigl[A' \otimes_A
  \mathrm{descended}(c(\gamma))\bigr]\), the image of
  \(\mathrm{picClass}(c(\gamma)) = [\mathrm{descended}(c(\gamma))]\)
  (Definition~\ref{def:module_picClass}) under \([N] \mapsto [A' \otimes_A N]\).
\end{proof}

\section{The projection-descent equivalence for unit sections}
\label{sec:projectionUnits}

Throughout this section \(C\) is a curve — proper, geometrically irreducible and geometrically
reduced — over a field \(k\), and \(T\) is a test object of \(\Over(\Spec k)\).  Write
\(\mathrm{pr} \colon (C \otimes T)_{\mathrm{left}} \to T_{\mathrm{left}}\) for the second
projection.

\begin{definition}[The projection-descent equivalence for unit sections]
  \label{def:unitsSndEquiv}
  \lean{AlgebraicGeometry.Over.unitsSndEquiv}
  \uses{cor:unitsAppLE_snd_bijective}
  \leanok
  For an affine open \(V \subseteq T_{\mathrm{left}}\), pullback of unit sections along the
  second projection is a group isomorphism
  \[
    \mathrm{unitsSndEquiv} \colon \Gamma(T_{\mathrm{left}}, V)^{\times} \;\xrightarrow{\ \sim\
    }\; \Gamma\bigl((C \otimes T)_{\mathrm{left}}, \mathrm{pr}^{-1} V\bigr)^{\times},
  \]
  the packaging as a multiplicative equivalence of the bijection
  (Corollary~\ref{cor:unitsAppLE_snd_bijective}) that pullback of unit sections over an affine
  open is bijective.  Its inverse is the \emph{descent} of a unit on the product to a unit on
  the base.
\end{definition}
\begin{proof}
  \leanok
  Pullback of unit sections is a group homomorphism, and it is bijective over the affine open
  \(V\) by Corollary~\ref{cor:unitsAppLE_snd_bijective}; a bijective group homomorphism is a
  group isomorphism.
\end{proof}

\begin{lemma}[Uniqueness of the descended unit]
  \label{lem:unitsSndEquiv_symm_eq_of_unitsAppLE}
  \lean{AlgebraicGeometry.Over.unitsSndEquiv_symm_eq_of_unitsAppLE}
  \uses{def:unitsSndEquiv}
  \leanok
  Let \(V \subseteq T_{\mathrm{left}}\) be an affine open, \(v \in \Gamma(T_{\mathrm{left}},
  V)^{\times}\) and \(w \in \Gamma((C \otimes T)_{\mathrm{left}}, \mathrm{pr}^{-1}
  V)^{\times}\).  If \(v\) pulls back to \(w\) along the projection, then \(v\) is the descent
  of \(w\), that is \(v = \mathrm{unitsSndEquiv}^{-1}(w)\).
\end{lemma}
\begin{proof}
  \leanok
  By Definition~\ref{def:unitsSndEquiv}, \(\mathrm{unitsSndEquiv}(v)\) is the pullback of \(v\),
  which by hypothesis is \(w\); applying the inverse isomorphism gives \(v =
  \mathrm{unitsSndEquiv}^{-1}(w)\).
\end{proof}

\begin{lemma}[Naturality of the descent equivalence in the affine open]
  \label{lem:unitsSndEquiv_unitsRestrict}
  \lean{AlgebraicGeometry.Over.unitsSndEquiv_unitsRestrict,
    AlgebraicGeometry.Over.unitsSndEquiv_symm_unitsRestrict}
  \uses{def:unitsSndEquiv}
  \leanok
  For affine opens \(V' \subseteq V \subseteq T_{\mathrm{left}}\), pullback of unit sections
  commutes with restriction:
  \[
    \mathrm{unitsSndEquiv}\bigl(v|_{V'}\bigr) = \bigl(\mathrm{unitsSndEquiv}(v)\bigr)
    \big|_{\mathrm{pr}^{-1} V'}, \qquad v \in \Gamma(T_{\mathrm{left}}, V)^{\times},
  \]
  and dually the descent commutes with restriction.
\end{lemma}
\begin{proof}
  \leanok
  Both sides are the value of \(\mathrm{pr}\) on unit sections composed with restriction; the two
  restriction squares of the structure sheaf commute, so the pullback of the restriction equals
  the restriction of the pullback.  Applying \(\mathrm{unitsSndEquiv}^{-1}\) and using the
  round-trips (Definition~\ref{def:unitsSndEquiv}) gives the dual identity.
\end{proof}

\begin{lemma}[The base square of the second projection]
  \label{lem:snd_left_naturality}
  \lean{AlgebraicGeometry.Over.snd_left_naturality,
    AlgebraicGeometry.Over.snd_left_preimage_naturality}
  \leanok
  For a morphism \(g \colon T' \to T\) of test objects, whiskering \(C \lhd g\) on the product
  intertwines the two projections:
  \[
    (C \lhd g)_{\mathrm{left}} \circ (\mathrm{snd}_{C,T})_{\mathrm{left}}
      = (\mathrm{snd}_{C,T'})_{\mathrm{left}} \circ g_{\mathrm{left}}.
  \]
  Consequently the two legs of this square have equal open preimages: for every open \(V
  \subseteq T_{\mathrm{left}}\), \((C \lhd g)^{-1}\mathrm{pr}^{-1} V = \mathrm{pr}'^{-1}
  g_{\mathrm{left}}^{-1} V\).
\end{lemma}
\begin{proof}
  \leanok
  The identity is the projection-compatibility of the cartesian monoidal structure,
  \((C \lhd g) \circ \mathrm{snd}_{C,T} = \mathrm{snd}_{C,T'} \circ g\), transported through the
  forgetful functor \(\Over(\Spec k) \to \mathrm{Sch}\).  Taking open preimages of \(V\) through
  both composites and using functoriality of preimage gives the second equality.
\end{proof}

\begin{theorem}[Naturality of the descent equivalence in the test object]
  \label{thm:unitsSndEquiv_naturality}
  \lean{AlgebraicGeometry.Over.unitsSndEquiv_naturality}
  \uses{def:unitsSndEquiv, lem:snd_left_naturality}
  \leanok
  Let \(g \colon T' \to T\) be a morphism of test objects and \(V \subseteq T_{\mathrm{left}}\)
  an affine open whose preimage \(g_{\mathrm{left}}^{-1} V \subseteq T'_{\mathrm{left}}\) is also
  affine.  For \(v \in \Gamma(T_{\mathrm{left}}, V)^{\times}\), descending \(v\) on \(T\) and
  then pulling back along \(C \lhd g\) equals first pulling \(v\) back along \(g\) and then
  descending on \(T'\); both are units over \(\mathrm{pr}'^{-1}(g_{\mathrm{left}}^{-1} V)\).
\end{theorem}
\begin{proof}
  \leanok
  Unfolding both sides as pullbacks of \(v\) along the two legs of the base square of
  Lemma~\ref{lem:snd_left_naturality}, the two composite pullbacks agree because the two legs are
  equal morphisms and the source opens are identified by the preimage identity of that lemma.
  The equality of pullbacks along equal morphisms then closes the goal.
\end{proof}

\section{Descent in stages for unit \(1\)-cocycles}
\label{sec:unitDescentComposite}

Let \(A \to B \to P\) be a tower of commutative rings.  This section relates \(A\)-descent
along the composite \(A \to P\) with \(B\)-descent along \(B \to P\), the cover being factored
through the intermediate ring \(B\).

\begin{definition}[The collapse maps on tensor squares and cubes]
  \label{def:module_tensorCollapse}
  \lean{Module.tensorCollapse, Module.tensorCubeCollapse}
  \leanok
  The \emph{collapse map} is the canonical \(A\)-algebra homomorphism
  \[
    \pi \colon P \otimes_A P \longrightarrow P \otimes_B P, \qquad x \otimes y \mapsto x \otimes
    y,
  \]
  identifying the two \(A\)-bilinear factors as \(B\)-bilinear.  Its analogue on tensor cubes is
  the \(A\)-algebra homomorphism
  \[
    \pi_3 \colon P \otimes_A (P \otimes_A P) \longrightarrow P \otimes_B (P \otimes_B P), \qquad
    x \otimes (y \otimes z) \mapsto x \otimes (y \otimes z),
  \]
  the receptacle for the collapse of the three face maps.
\end{definition}

\begin{theorem}[Collapse of a descent cocycle]
  \label{thm:module_descentCocycle_collapse}
  \lean{Module.IsDescentCocycle.collapse}
  \uses{def:module_descent_cocycle, def:module_tensorCollapse}
  \leanok
  Let \(v \in (P \otimes_A P)^{\times}\) be an \(A\)-descent \(1\)-cocycle relative to \(A \to
  P\).  Then its collapse \(\pi(v)\) is a \(B\)-descent \(1\)-cocycle relative to \(B \to P\).
\end{theorem}
\begin{proof}
  \leanok
  On elementary tensors, the multiplication \(\mu_B\) of \(P \otimes_B P\) satisfies \(\mu_B(\pi(x
  \otimes y)) = xy = \mu_A(x \otimes y)\), and each \(B\)-face map factors through the collapse:
  \(\partial^B_{12}(\pi(w)) = \pi_3(\partial^A_{12}(w))\) and likewise for \(\partial_{13},
  \partial_{23}\); both sides of each identity are \(A\)-bilinear, so the identities hold on all
  of \(P \otimes_A P\).  Applying \(\mu_B\) to \(\pi(v)\) and using the normalization
  \(\mu_A(v) = 1\) gives \(\mu_B(\pi(v)) = 1\); applying \(\pi_3\) to the cocycle identity
  \(\partial^A_{23}(v) \cdot \partial^A_{12}(v) = \partial^A_{13}(v)\) and using
  multiplicativity of \(\pi_3\) gives \(\partial^B_{23}(\pi(v)) \cdot \partial^B_{12}(\pi(v)) =
  \partial^B_{13}(\pi(v))\).  Hence \(\pi(v)\) is a \(B\)-descent \(1\)-cocycle.
\end{proof}

\begin{lemma}[The descended module lies in the collapsed descended module]
  \label{lem:module_descended_le_collapse}
  \lean{Module.descended_le_descended_collapse}
  \uses{def:module_descended, thm:module_descentCocycle_collapse}
  \leanok
  For an \(A\)-descent \(1\)-cocycle \(v\), the \(A\)-descended module of \(v\) is contained,
  as a subset of \(P\), in the \(B\)-descended module of the collapse \(\pi(v)\).
\end{lemma}
\begin{proof}
  \leanok
  An element \(m \in P\) lies in the \(A\)-descended module of \(v\) iff \(v \cdot (m \otimes_A
  1) = 1 \otimes_A m\) in \(P \otimes_A P\).  Applying the collapse \(\pi\) and using
  \(\pi(m \otimes_A 1) = m \otimes_B 1\), \(\pi(1 \otimes_A m) = 1 \otimes_B m\) and
  multiplicativity gives \(\pi(v) \cdot (m \otimes_B 1) = 1 \otimes_B m\), i.e.\ \(m\) lies in
  the \(B\)-descended module of \(\pi(v)\).
\end{proof}

\begin{theorem}[Descent in stages for the descended module]
  \label{thm:module_descendedCollapseEquiv}
  \lean{Module.descendedCollapseEquiv}
  \uses{thm:module_descentCocycle_collapse, def:module_descended}
  \leanok
  Assume \(A \to B\) and \(B \to P\) are faithfully flat (so \(A \to P\) is faithfully flat as
  well).  For an \(A\)-descent \(1\)-cocycle \(v\), the base change to \(B\) of the
  \(A\)-descended module of \(v\) is canonically isomorphic to the \(B\)-descended module of the
  collapse:
  \[
    B \otimes_A \mathrm{descended}(v) \;\cong\; \mathrm{descended}(\pi(v))
    \qquad (B\text{-linear}),\quad b \otimes m \mapsto b \cdot m.
  \]
\end{theorem}
\begin{proof}
  \leanok
  As \(B \to P\) is faithfully flat, \(\mathrm{descended}(\pi(v))\) is recognized by the
  uniqueness property of descended modules from any \(B\)-module \(N\) equipped with a
  \(P\)-linear isomorphism \(P \otimes_B N \cong P\) intertwining the tautological descent datum
  twisted by \(\pi(v)\).  Take \(N = B \otimes_A \mathrm{descended}(v)\) and the composite
  \[
    P \otimes_B \bigl(B \otimes_A \mathrm{descended}(v)\bigr) \;\cong\; P \otimes_A
    \mathrm{descended}(v) \;\cong\; P,
  \]
  the first isomorphism cancelling the iterated base change, the second the \(A\)-descent
  isomorphism attached to \(v\).  A computation on elementary tensors, using the membership
  identity \(v \cdot (m \otimes_A 1) = 1 \otimes_A m\), shows this composite intertwines the
  base change of the coaction \(x \mapsto v \cdot (x \otimes 1)\) with the coaction \(y \mapsto
  \pi(v) \cdot (y \otimes 1)\).  Uniqueness of descended modules then yields the stated
  isomorphism.
\end{proof}

\begin{theorem}[Naturality of the Picard class under descent in stages]
  \label{thm:module_picClass_collapse}
  \lean{Module.IsDescentCocycle.picClass_collapse}
  \uses{thm:module_descendedCollapseEquiv, def:module_picClass}
  \source{kleiman-picard}
  \leanok
  Under the hypotheses of Theorem~\ref{thm:module_descendedCollapseEquiv}, the Picard class over
  \(B\) of the collapsed cocycle is the image of the Picard class over \(A\) of \(v\) under the
  base-change homomorphism \(\Pic(A) \to \Pic(B)\):
  \[
    \mathrm{picClass}(\pi(v)) = \bigl[B \otimes_A \mathrm{descended}(v)\bigr] \quad\text{in }
    \Pic(B).
  \]
\end{theorem}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:module_descendedCollapseEquiv}, \(B \otimes_A \mathrm{descended}(v) \cong
  \mathrm{descended}(\pi(v))\) as \(B\)-modules, so the two invertible \(B\)-modules have the
  same class in \(\Pic(B)\).  The right side is \(\mathrm{picClass}(\pi(v))\) by definition
  (Definition~\ref{def:module_picClass}), and the left side is the image of
  \(\mathrm{picClass}(v) = [\mathrm{descended}(v)]\) under \([N] \mapsto [B \otimes_A N]\).
\end{proof}

\section{Naturality of the \v Cech--Picard dictionary in the affine scheme}
\label{sec:cechPic_naturality}

\begin{theorem}[Naturality of the \v Cech--Picard descent homomorphism in the affine scheme]
  \label{thm:cechPic_toPic_map}
  \lean{AlgebraicGeometry.Scheme.CechPic.toPic_map}
  \uses{def:cechPic_toPic, thm:awayCover_pic_baseChange, thm:prPullback_injective}
  \source{kleiman-picard}
  \leanok
  For a morphism \(g \colon X \to Y\) of affine schemes, base change of Picard classes along the
  ring map \(g^{\#} \colon \Gamma(Y, \top) \to \Gamma(X, \top)\) intertwines the \v
  Cech--Picard descent homomorphism (Definition~\ref{def:cechPic_toPic}) with the pullback of
  \v Cech classes; that is, for every \(L \in Y.\mathrm{CechPic}\),
  \[
    \mathrm{toPic}_X(g^{*} L) = \Pic(g^{\#})\bigl(\mathrm{toPic}_Y(L)\bigr) \quad\text{in }
    \Pic\bigl(\Gamma(X, \top)\bigr).
  \]
  This is the separatedness half of Kleiman, \emph{The Picard Scheme}, Theorem 2.5(1), in its
  \v Cech incarnation.
\end{theorem}
\begin{proof}
  \leanok
  Represent \(L\) by a unit cocycle \(\gamma\) on a pointed cover \(\mathcal U\) of \(Y\) and
  choose a finite basic refinement \(P\) of \(\mathcal U\).  Then \(\mathrm{toPic}_Y(L)\) is the
  Picard class descended from the cover cocycle of \(\gamma\) on the finite localization cover
  \(P.r \colon P.\iota \to \Gamma(Y, \top)\).  Base-changing this whole \v Cech picture along
  \(g^{\#}\) (Theorem~\ref{thm:awayCover_pic_baseChange}) computes \(\Pic(g^{\#})(\mathrm{toPic}_Y
  L)\) as the Picard class of the pushed cover cocycle on the pushed family \(f'_i = g^{\#}(P.r_i)\),
  whose basic opens \(X.\mathrm{basicOpen}(f'_i) = g^{-1} Y.\mathrm{basicOpen}(P.r_i)\) are the
  pullbacks of \(P\)'s basic opens.

  On the other side, \(\mathrm{toPic}_X(g^{*} L)\) is the Picard class descended from the cover
  cocycle of \(g^{*}\gamma\) on \emph{any} finite basic refinement of the pulled-back cover
  \(\mathcal U^{\mathrm{pb}}\).  As \(g\) need not be surjective, the pushed family \(f'\) is not
  itself a basic refinement of \(\mathcal U^{\mathrm{pb}}\); take the product refinement \(R\)
  indexed by \(P.\iota \times Q.\iota\), for an auxiliary basic refinement \(Q\) of \(\mathcal
  U^{\mathrm{pb}}\), with sections \(g^{\#}(P.r_i) \cdot Q.r_j\).  The pushed cover cocycle,
  refined to \(R\) by the first projection, differs from the cover cocycle of \(g^{*}\gamma\) on
  \(R\) by the index-wise coboundary of the cross evaluations \(\gamma\) pulled back through
  \(g\); two point-selections on a common refinement always differ by such a coboundary.  Since
  the descended Picard class is unchanged by a coboundary, the two Picard classes coincide, which
  is the asserted identity.
\end{proof}

\begin{theorem}[Algebra form of the naturality]
  \label{thm:cechPic_toPic_mapAlgebra}
  \lean{AlgebraicGeometry.Scheme.CechPic.toPic_mapAlgebra}
  \uses{thm:cechPic_toPic_map}
  \leanok
  With \(\Gamma(X, \top)\) regarded as a \(\Gamma(Y, \top)\)-algebra through \(g^{\#}\), the
  identity of Theorem~\ref{thm:cechPic_toPic_map} reads \(\mathrm{toPic}_X(g^{*} L) =
  \mathrm{mapAlgebra}\bigl(\mathrm{toPic}_Y(L)\bigr)\) for the base-change homomorphism of
  Picard groups attached to the algebra structure.
\end{theorem}
\begin{proof}
  \leanok
  The base-change homomorphism attached to the \(\Gamma(Y, \top)\)-algebra \(\Gamma(X, \top)\)
  is by construction \(\Pic(g^{\#})\); the statement is therefore
  Theorem~\ref{thm:cechPic_toPic_map} rephrased.
\end{proof}

\section{The class-level coherence seed for \'etale separatedness}
\label{sec:etaleSeparatedness}

Let \(k\) be a field and \(A \to B\) a homomorphism of \(k\)-algebras, and let \(C\) be a curve
over \(k\).  Write \(\Spec A, \Spec B\) for the corresponding test objects of \(\Over(\Spec
k)\).  This section records the class-level coherence seed of the (C1) \'etale-separatedness
theorem — the separatedness half of Kleiman, \emph{The Picard Scheme}, Theorem 2.5(1).

\begin{definition}[The two coprojections of a double cover of a test algebra]
  \label{def:tensorInl_tensorInr}
  \lean{AlgebraicGeometry.tensorInl, AlgebraicGeometry.tensorInr}
  \leanok
  The two \emph{coprojections} of the double cover \(B \otimes_A B\) of \(B\) are the
  \(k\)-algebra homomorphisms
  \[
    \mathrm{tensorInl} \colon B \to B \otimes_A B, \quad b \mapsto b \otimes 1, \qquad
    \mathrm{tensorInr} \colon B \to B \otimes_A B, \quad b \mapsto 1 \otimes b.
  \]
\end{definition}

\begin{lemma}[Diagonal coherence of the two coprojections]
  \label{lem:tensorInl_comp_ofId}
  \lean{AlgebraicGeometry.tensorInl_comp_ofId}
  \uses{def:tensorInl_tensorInr}
  \leanok
  Precomposed with the base inclusion \(A \to B\), the two coprojections agree:
  \(\mathrm{tensorInl} \circ (A \to B) = \mathrm{tensorInr} \circ (A \to B)\) as \(k\)-algebra
  homomorphisms \(A \to B \otimes_A B\).
\end{lemma}
\begin{proof}
  \leanok
  For \(a \in A\) with image \(\bar a \in B\), both sides send \(a\) to \(\bar a \otimes 1\)
  respectively \(1 \otimes \bar a\); over \(A\) these are equal, \(\bar a \otimes 1 = a \cdot (1
  \otimes 1) = 1 \otimes \bar a\), because tensoring is over \(A\).
\end{proof}

\begin{theorem}[The class-level coherence seed]
  \label{thm:cechPicMap_tensorInl_eq_tensorInr}
  \lean{AlgebraicGeometry.Over.cechPicMap_tensorInl_eq_tensorInr}
  \uses{def:tensorInl_tensorInr, lem:tensorInl_comp_ofId, thm:prPullback_injective,
    lem:snd_left_naturality, def:overSpecMap, lem:overSpecMap_functor}
  \source{kleiman-picard}
  \leanok
  Let \(L\) be a \v Cech Picard class on the curve-product \(C \otimes \Spec A\) and \(N\) a \v
  Cech Picard class on \(\Spec B\).  Suppose that over the test algebra \(A \to B\) the class
  \(L\) restricts to the pullback of \(N\) from the base:
  \[
    \mathrm{pr}_B^{*} N = (C \lhd \Spec(A \to B))^{*} L.
  \]
  Then the two base changes of \(N\) to \(\Spec(B \otimes_A B)\) along the coprojections
  coincide:
  \(\Spec(\mathrm{tensorInl})^{*} N = \Spec(\mathrm{tensorInr})^{*} N\).
\end{theorem}
\begin{proof}
  \leanok
  For each coprojection \(j \in \{\mathrm{tensorInl}, \mathrm{tensorInr}\}\), pull back
  \(\Spec(j)^{*} N\) along the projection \(\mathrm{pr}_{B \otimes_A B}\).  Using functoriality
  of \v Cech pullback (Lemma~\ref{lem:overSpecMap_functor}), the base square of the projection
  (Lemma~\ref{lem:snd_left_naturality}) and the hypothesis, this equals \((C \lhd \Spec(j
  \circ (A \to B)))^{*} L\).  By the diagonal coherence
  (Lemma~\ref{lem:tensorInl_comp_ofId}), \(\mathrm{tensorInl} \circ (A \to B) = \mathrm{tensorInr}
  \circ (A \to B)\), so the two composites \(\Spec(\mathrm{tensorInl})^{*} N\) and
  \(\Spec(\mathrm{tensorInr})^{*} N\) have the same pullback along \(\mathrm{pr}_{B \otimes_A
  B}\).  Pullback along the curve projection is injective on Picard classes
  (Theorem~\ref{thm:prPullback_injective}), hence the two base changes agree.
\end{proof}

\section{The Amitsur toolkit for \'etale separatedness}
\label{sec:amitsurCochain}

This section collects three reusable groups of statements consumed by the coherent-witness
step of the (C1) \'etale-separatedness assembly, all revolving around the fact that only global
units cross the curve projection \(\mathrm{pr}\).

\begin{theorem}[Global gluing of a compatible unit family]
  \label{thm:exists_global_unit_of_compatible}
  \lean{AlgebraicGeometry.Scheme.exists_global_unit_of_compatible,
    AlgebraicGeometry.Scheme.global_unit_ext}
  \uses{lem:units_gluing, lem:units_separation}
  \leanok
  Let \(\mathcal U\) be a pointed cover of a scheme \(X\).  A family of units \(\beta_x \in
  \Gamma(X, \mathcal U_x)^{\times}\) whose members agree on pairwise overlaps glues to a single
  global unit \(w \in \Gamma(X, \top)^{\times}\) restricting to each \(\beta_x\); and a global
  unit that restricts to \(1\) on every member of a pointed cover — more precisely, two global
  units agreeing on every member — is uniquely determined.
\end{theorem}
\begin{proof}
  \leanok
  The members \(\mathcal U_x\) cover \(\top\) because \(x \in \mathcal U_x\).  The gluing
  statement is the sheaf gluing for unit sections (Lemma~\ref{lem:units_gluing}) at the
  tautological cover \(V = \top\), \(W = \mathcal U\); the uniqueness statement is the
  separation for unit sections (Lemma~\ref{lem:units_separation}) at the same cover.
\end{proof}

\begin{definition}[The three cofaces on the triple tensor]
  \label{def:tensorFaces}
  \lean{AlgebraicGeometry.tensorFace₁₂, AlgebraicGeometry.tensorFace₁₃,
    AlgebraicGeometry.tensorFace₂₃}
  \leanok
  Extending the coprojection idiom of Definition~\ref{def:tensorInl_tensorInr}, the three
  \emph{cofaces} on the triple tensor are the \(k\)-algebra homomorphisms \(B \otimes_A B \to B
  \otimes_A (B \otimes_A B)\)
  \[
    \mathrm{tensorFace}_{12}(x \otimes y) = x \otimes (y \otimes 1), \quad
    \mathrm{tensorFace}_{13}(x \otimes y) = x \otimes (1 \otimes y), \quad
    \mathrm{tensorFace}_{23}(w) = 1 \otimes w,
  \]
  the \(k\)-restrictions of the \(A\)-linear descent cofaces.
\end{definition}

\begin{lemma}[Simplicial coincidences of the cofaces]
  \label{lem:tensorFace_comp}
  \lean{AlgebraicGeometry.tensorFace₁₂_comp_tensorInl,
    AlgebraicGeometry.tensorFace₁₂_comp_tensorInr,
    AlgebraicGeometry.tensorFace₁₃_comp_tensorInr}
  \uses{def:tensorFaces, def:tensorInl_tensorInr}
  \leanok
  The six composites \(\mathrm{tensorFace} \circ \mathrm{coprojection} \colon B \to B \otimes_A
  (B \otimes_A B)\) collapse onto the three insertions \(x \mapsto x \otimes (1 \otimes 1)\),
  \(x \mapsto 1 \otimes (x \otimes 1)\), \(x \mapsto 1 \otimes (1 \otimes x)\).  In particular
  \(\mathrm{tensorFace}_{12} \circ \mathrm{tensorInl} = \mathrm{tensorFace}_{13} \circ
  \mathrm{tensorInl}\), \(\mathrm{tensorFace}_{12} \circ \mathrm{tensorInr} =
  \mathrm{tensorFace}_{23} \circ \mathrm{tensorInl}\), and \(\mathrm{tensorFace}_{13} \circ
  \mathrm{tensorInr} = \mathrm{tensorFace}_{23} \circ \mathrm{tensorInr}\).
\end{lemma}
\begin{proof}
  \leanok
  Each identity is checked on a generator \(b \in B\): both sides insert \(b\) into the same
  tensor position and fill the remaining two positions with \(1\), by the definitions of the
  cofaces and coprojections.
\end{proof}

\begin{definition}[The top-open descent equivalence for global units]
  \label{def:unitsSndTopEquiv}
  \lean{AlgebraicGeometry.Over.unitsSndTopEquiv}
  \uses{def:unitsSndEquiv}
  \leanok
  Specializing the projection-descent equivalence (Definition~\ref{def:unitsSndEquiv}) to the
  affine open \(V = \top\), pullback of global units along the second projection is a group
  isomorphism
  \[
    \Gamma\bigl((\Spec R)_{\mathrm{left}}, \top\bigr)^{\times} \;\xrightarrow{\ \sim\ }\;
    \Gamma\bigl((C \otimes \Spec R)_{\mathrm{left}}, \top\bigr)^{\times}
  \]
  for a \(k\)-algebra \(R\); its forward map is pullback of global units along \(\mathrm{pr}\).
\end{definition}
\begin{proof}
  \leanok
  Both \((\Spec R)_{\mathrm{left}}\) and \((C \otimes \Spec R)_{\mathrm{left}}\) have affine top
  open, and the projection preimage of \(\top\) is \(\top\); so
  Definition~\ref{def:unitsSndEquiv} applies at \(V = \top\), and its forward map is pullback of
  global units.
\end{proof}

\begin{theorem}[Global-unit pullback is bijective]
  \label{thm:appTop_units_bijective}
  \lean{AlgebraicGeometry.Over.appTop_units_surjective,
    AlgebraicGeometry.Over.appTop_units_injective}
  \uses{def:unitsSndTopEquiv}
  \leanok
  Pullback of global units along the second projection \(\mathrm{pr} \colon (C \otimes \Spec
  R)_{\mathrm{left}} \to (\Spec R)_{\mathrm{left}}\) is bijective: every global unit on the
  product descends to a unique global unit on the base.
\end{theorem}
\begin{proof}
  \leanok
  This is the bijectivity of the group isomorphism of
  Definition~\ref{def:unitsSndTopEquiv}: surjectivity gives the descent of any global unit as
  the image of the inverse isomorphism, and injectivity is separation of global units by the
  projection.
\end{proof}

\begin{theorem}[Naturality of the top-open descent]
  \label{thm:unitsSndTopEquiv_naturality}
  \lean{AlgebraicGeometry.Over.unitsSndTopEquiv_naturality}
  \uses{def:unitsSndTopEquiv, thm:unitsSndEquiv_naturality}
  \leanok
  For a \(k\)-algebra homomorphism \(\varphi \colon R \to R'\), descending a global unit on
  \(\Spec R\) and pulling it back along \(C \lhd \Spec\varphi\) equals first pulling back along
  \(\Spec\varphi\) and then descending on \(\Spec R'\).
\end{theorem}
\begin{proof}
  \leanok
  This is the naturality of the projection-descent equivalence in the test object
  (Theorem~\ref{thm:unitsSndEquiv_naturality}) specialized to \(V = \top\) along the morphism
  \(\Spec\varphi\); all the opens occurring there are \(\top\) on the nose, so the general
  naturality square applies directly.
\end{proof}

\section{The pullback calculus for unit cochains}
\label{sec:cochainPullback}

The coherent-witness construction of the next section manipulates unit \v Cech cochains by
pulling them back along morphisms of schemes and combining the results multiplicatively. This
section records the elementary calculus of those operations over abstract schemes, so that the
concrete instances in the construction are single applications.

Throughout, for a morphism \(f \colon X \to Y\), a unit section \(s \in \struct Y(V)^{\times}\)
on an open \(V \subseteq Y\), and an open \(O \subseteq X\) contained in the preimage
\(f^{-1}(V)\), write \(f^{\sharp}_O s \in \struct X(O)^{\times}\) for the pullback of \(s\)
along \(f\), restricted to \(O\). This operation is a group homomorphism on units, is
functorial in the morphism, \((r \circ f)^{\sharp}_O s = f^{\sharp}_O (r^{\sharp} s)\) whenever
the composite is defined, and commutes with shrinking \(O\). When \(u \in \struct Y(\top)^{\times}\)
is a \emph{global} unit, its pullback \(f^{\sharp}_O(u|_\top)\) is the restriction to \(O\) of
the global-section pullback \(f^{\sharp}_\top u \in \struct X(\top)^{\times}\).

\begin{lemma}[Congruence in the morphism]
  \label{lem:unitsAppLE_congr_hom}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_section_congr_hom,
    AlgebraicGeometry.Scheme.Hom.unitsAppLE_pair_congr_hom}
  \leanok
  Let \(g, g' \colon X \to Y\) be two morphisms with \(g = g'\), let \(V\) assign to each point
  of \(Y\) an open of \(Y\), and let \(s\) assign to each point \(y\) a unit section
  \(s_y \in \struct Y(V(y))^{\times}\). Then for every \(x \in X\) and every open
  \(O \subseteq g^{-1}(V(g(x)))\),
  \[
    g^{\sharp}_O\, s_{g(x)} = (g')^{\sharp}_O\, s_{g'(x)} .
  \]
  The same holds for doubly point-indexed families \(V(y,y')\), \(s_{y,y'}\), such as the
  pair evaluations of a unit \v Cech cocycle.
\end{lemma}
\begin{proof}
  \leanok
  Since \(g = g'\), the two sides are identical: the equality of morphisms transports the
  source base point, the open \(V(g(x)) = V(g'(x))\), and the section
  \(s_{g(x)} = s_{g'(x)}\) simultaneously, so the pullbacks agree.
\end{proof}

\begin{lemma}[Pullback of a coboundary relation]
  \label{lem:unitsAppLE_coboundary_rel}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_coboundary_rel}
  \leanok
  Let \(\varphi \colon X \to Y\), \(r_1 \colon Y \to Z_1\), \(r_2 \colon Y \to Z_2\). Suppose a
  unit \(0\)-cochain \(c\) on a pointed cover \(\mathcal C\) of \(Y\) cobounds the comparison of
  two pair-indexed unit families \(E_1\) on \(Z_1\) and \(E_2\) on \(Z_2\), pulled back along
  \(r_1\) and \(r_2\): for all \(y, y' \in Y\), on the overlap
  \(\mathcal C(y) \cap \mathcal C(y')\),
  \[
    c_y \cdot \bigl(r_1^{\sharp} E_1\bigr)_{y y'}
      = \bigl(r_2^{\sharp} E_2\bigr)_{y y'} \cdot c_{y'} .
  \]
  Then for every \(x, x' \in X\) and every open \(O \subseteq \varphi^{-1}(\mathcal C(\varphi x)
  \cap \mathcal C(\varphi x'))\), the pullback of the relation along \(\varphi\) holds in
  composite normal form:
  \[
    \varphi^{\sharp}_O\, c_{\varphi x} \cdot \bigl((r_1\varphi)^{\sharp}_O E_1\bigr)_{x x'}
      = \bigl((r_2\varphi)^{\sharp}_O E_2\bigr)_{x x'} \cdot \varphi^{\sharp}_O\, c_{\varphi x'},
  \]
  where \(r_i\varphi\) denotes the composite \(X \xrightarrow{\varphi} Y \xrightarrow{r_i} Z_i\).
\end{lemma}
\begin{proof}
  \leanok
  Apply the pullback homomorphism \(\varphi^{\sharp}_O\) to both sides of the given relation at
  the points \(\varphi x, \varphi x'\). Being a group homomorphism on units it distributes over
  the products; and by functoriality it merges each pullback,
  \(\varphi^{\sharp}_O(r_i^{\sharp} E_i) = (r_i\varphi)^{\sharp}_O E_i\), while leaving
  \(\varphi^{\sharp}_O c\) unchanged. The two normal forms result.
\end{proof}

\begin{lemma}[The global-unit pullback in restriction form]
  \label{lem:global_unit_pullback}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_unitsRestrict_top,
    AlgebraicGeometry.unitsRestrict_top_self, AlgebraicGeometry.unitsAppLE_top_global}
  \leanok
  Let \(f \colon X \to Y\) and \(u \in \struct Y(\top)^{\times}\) a global unit. The restriction
  of \(u\) along \(\top \le \top\) is \(u\) itself; and for any point-indexed open \(V\) and any
  open \(O \subseteq f^{-1}(V)\), pulling the restricted unit back along \(f\) equals the
  restriction to \(O\) of the global-section pullback of \(u\):
  \[
    f^{\sharp}_O\bigl(u|_V\bigr) = \bigl(f^{\sharp}_\top u\bigr)\big|_O .
  \]
  In particular, at \(V = \top\) the open-indexed and global spellings of pulling back a global
  unit coincide.
\end{lemma}
\begin{proof}
  \leanok
  The restriction along the identity inclusion \(\top \le \top\) is the identity map on
  sections. For the second identity, both sides are the image of \(u\) under one and the same
  ring map \(\struct Y(\top) \to \struct X(O)\) — the composite of the comorphism of \(f\) on
  global sections with restriction to \(O\) — so they agree; the \(V = \top\) case is the same
  statement read backwards.
\end{proof}

\begin{lemma}[Functoriality of the global-unit pullback]
  \label{lem:units_map_appTop_comp}
  \lean{AlgebraicGeometry.units_map_appTop_comp}
  \leanok
  For morphisms \(f \colon X \to Y\), \(g \colon Y \to Z\) and a global unit
  \(u \in \struct Z(\top)^{\times}\), pulling \(u\) back along \(g\) and then along \(f\) equals
  pulling it back along the composite \(g \circ f\):
  \[
    f^{\sharp}_\top\bigl(g^{\sharp}_\top u\bigr) = (g \circ f)^{\sharp}_\top u .
  \]
\end{lemma}
\begin{proof}
  \leanok
  The comorphism of a composite of morphisms is the composite of the comorphisms in the
  reverse order; applying this on global sections and passing to units gives the claim.
\end{proof}

\begin{lemma}[Pushing a pullback through a product of cochain values]
  \label{lem:unitsAppLE_merge}
  \lean{AlgebraicGeometry.unitsAppLE_mulDiv_comp, AlgebraicGeometry.unitsAppLE_mulRatio_comp}
  \leanok
  Let \(\varphi \colon X \to Y\) and let \(a, b, c\) be pulled-back cochain values along
  morphisms \(g_1, g_2, g_3 \colon Y \to Z\), each a unit section on a common open \(V\) of
  \(Y\). For any open \(O \subseteq \varphi^{-1}(V)\),
  \[
    \varphi^{\sharp}_O\Bigl(\tfrac{a \cdot b}{c}\Bigr)
      = \frac{(g_1\varphi)^{\sharp}_O a \cdot (g_2\varphi)^{\sharp}_O b}{(g_3\varphi)^{\sharp}_O c},
  \]
  and likewise for a combination of the shape \(t \cdot (a/b)\); pushing the pullback through
  the combination merges each factor into a composite pullback.
\end{lemma}
\begin{proof}
  \leanok
  The pullback \(\varphi^{\sharp}_O\) is a group homomorphism on units, so it distributes over
  the products and quotients; each individual pullback then merges by functoriality,
  \(\varphi^{\sharp}_O(g^{\sharp} x) = (g\varphi)^{\sharp}_O x\).
\end{proof}

\begin{lemma}[Pullback of a glued identity in composite normal form]
  \label{lem:unitsAppLE_glued_pullback}
  \lean{AlgebraicGeometry.unitsAppLE_defect_pullback, AlgebraicGeometry.unitsAppLE_ratio_pullback}
  \uses{lem:global_unit_pullback, lem:unitsAppLE_merge}
  \leanok
  Let \(\varphi \colon X \to Y\) and morphisms \(m_1, m_2, m_3 \colon Y \to S\) with composites
  \(t_i = m_i \varphi \colon X \to S\). If a global unit \(W\) on \(Y\) restricts on an open
  \(V\) to a combination \(\tfrac{(m_1^{\sharp}\theta)(m_2^{\sharp}\theta)}{m_3^{\sharp}\theta}\)
  of pullbacks of a cochain \(\theta\), then the global-section pullback of \(W\) along
  \(\varphi\) restricts on any \(O \subseteq \varphi^{-1}(V)\) to the corresponding combination
  \(\tfrac{(t_1^{\sharp}\theta)(t_2^{\sharp}\theta)}{t_3^{\sharp}\theta}\) of the composite
  pullbacks. The analogous statement holds for a comparison combination of the shape
  \(t \cdot (a/b)\).
\end{lemma}
\begin{proof}
  \leanok
  By Lemma~\ref{lem:global_unit_pullback} the restriction of the global-section pullback of
  \(W\) to \(O\) equals \(\varphi^{\sharp}_O\) of the \(V\)-restriction of \(W\), which by
  hypothesis is the given combination of \(m_i\)-pullbacks; pushing \(\varphi^{\sharp}_O\)
  through that combination and merging the compositions (Lemma~\ref{lem:unitsAppLE_merge})
  produces the combination of \(t_i = m_i\varphi\) pullbacks. The output composites are the
  named \(t_i\) by hypothesis.
\end{proof}

\section{The Amitsur-coherent \v Cech witness}
\label{sec:coherentWitness}

Let \(k\) be a field, \(A \to B\) a homomorphism of \(k\)-algebras, and \(C\) an object of
\(\Over(\Spec k)\) which is proper, geometrically irreducible and geometrically reduced over
\(k\). Retain the coprojections \(q_1 = \Spec(\mathrm{tensorInl})\),
\(q_2 = \Spec(\mathrm{tensorInr}) \colon \Spec B \to \Spec(B \otimes_A B)\) of
Definition~\ref{def:tensorInl_tensorInr} and the three cofaces
\(f_{12}, f_{13}, f_{23} = \Spec(\mathrm{tensorFace}_{\bullet}) \colon \Spec(B \otimes_A B) \to
\Spec(B \otimes_A (B \otimes_A B))\) of Definition~\ref{def:tensorFaces}. This section
implements the coherent-witness step of the \'etale-separatedness argument of Kleiman,
\emph{The Picard Scheme}: starting from the class equality \(q_1^{*} N = q_2^{*} N\) supplied by
the class-level coherence seed (Theorem~\ref{thm:cechPicMap_tensorInl_eq_tensorInr}), it
produces a \v Cech witness cochain that is moreover \emph{Amitsur-coherent} over the triple
tensor, correcting an arbitrary witness by a single global unit.

\begin{lemma}[The coface coincidences at \(\Spec\) level and on the curve product]
  \label{lem:overSpec_whisker_face}
  \lean{AlgebraicGeometry.Over.overSpecMap_left_face₁₂_inl,
    AlgebraicGeometry.Over.overSpecMap_left_face₁₂_inr,
    AlgebraicGeometry.Over.overSpecMap_left_face₁₃_inr,
    AlgebraicGeometry.Over.whiskerLeft_face₁₂_inl,
    AlgebraicGeometry.Over.whiskerLeft_face₁₂_inr,
    AlgebraicGeometry.Over.whiskerLeft_face₁₃_inr}
  \uses{lem:tensorFace_comp, def:tensorFaces, def:tensorInl_tensorInr, def:overSpecMap}
  \leanok
  The three coface--coprojection coincidences of Lemma~\ref{lem:tensorFace_comp} persist after
  applying \(\Spec\) and after whiskering with \(C\): as morphisms of the corresponding
  curve products,
  \[
    f_{12} \circ q_1 = f_{13} \circ q_1, \qquad
    f_{12} \circ q_2 = f_{23} \circ q_1, \qquad
    f_{13} \circ q_2 = f_{23} \circ q_2,
  \]
  and the same three identities hold with each map replaced by its whiskering \(C \lhd (-)\).
\end{lemma}
\begin{proof}
  \leanok
  Each coincidence is the image of the corresponding tensor-algebra coincidence of
  Lemma~\ref{lem:tensorFace_comp} under the functor \(\Spec\) (on test objects), which is
  contravariant on algebra maps, respectively under the further whiskering functor
  \(C \lhd (-)\); both functors preserve composition, so the equal composites of algebra maps
  become equal composites of morphisms.
\end{proof}

\begin{lemma}[The diagonal coincidence on the curve product]
  \label{lem:whisker_inl_ofId}
  \lean{AlgebraicGeometry.Over.whiskerLeft_inl_ofId}
  \uses{lem:tensorInl_comp_ofId, def:tensorInl_tensorInr, def:overSpecMap}
  \leanok
  Composed with the whiskered base inclusion \(C \lhd \Spec(A \to B)\), the two whiskered
  coprojections agree:
  \[
    (C \lhd q_1) \circ \bigl(C \lhd \Spec(A \to B)\bigr)
      = (C \lhd q_2) \circ \bigl(C \lhd \Spec(A \to B)\bigr).
  \]
\end{lemma}
\begin{proof}
  \leanok
  This is the image of the diagonal coherence \(\mathrm{tensorInl} \circ (A \to B) =
  \mathrm{tensorInr} \circ (A \to B)\) of Lemma~\ref{lem:tensorInl_comp_ofId} under \(\Spec\)
  and the whiskering functor \(C \lhd (-)\), both of which preserve composition.
\end{proof}

\begin{definition}[The common refinement of the three coface pullbacks]
  \label{def:amitsurCover}
  \lean{AlgebraicGeometry.amitsurCover}
  \uses{def:tensorFaces}
  \leanok
  For a pointed cover \(\mathcal V\) of \(\Spec(B \otimes_A B)\), its \emph{Amitsur refinement}
  is the pointwise intersection
  \[
    \mathcal V_{123} := f_{23}^{*}\mathcal V \sqcap f_{12}^{*}\mathcal V \sqcap f_{13}^{*}\mathcal V
  \]
  of the pullbacks of \(\mathcal V\) along the three cofaces, a pointed cover of the triple
  tensor \(\Spec(B \otimes_A (B \otimes_A B))\).
\end{definition}

\begin{definition}[An Amitsur-coherent \v Cech witness]
  \label{def:CoherentCechWitness}
  \lean{AlgebraicGeometry.CoherentCechWitness}
  \uses{def:amitsurCover, def:tensorInl_tensorInr, def:tensorFaces}
  \source{kleiman-picard}
  \leanok
  Let \(\gamma\) be a unit \v Cech cocycle on a pointed cover \(\mathcal N\) of \(\Spec B\). An
  \emph{Amitsur-coherent \v Cech witness} for \(\gamma\) consists of a pointed cover
  \(\mathcal V\) of \(\Spec(B \otimes_A B)\) refining both coprojection pullbacks
  \(q_1^{*}\mathcal N\) and \(q_2^{*}\mathcal N\), together with a unit \(0\)-cochain
  \(\theta\) on \(\mathcal V\) such that:
  \begin{enumerate}
    \item (\emph{witness}) \(\theta\) cobounds the comparison of the two coprojection pullbacks
      of \(\gamma\): on the overlaps of \(\mathcal V\),
      \(\theta_x \cdot (q_1^{\sharp}\gamma)_{xy} = (q_2^{\sharp}\gamma)_{xy} \cdot \theta_y\);
    \item (\emph{coherent}) on the Amitsur refinement \(\mathcal V_{123}\), the three coface
      pullbacks of \(\theta\) satisfy the Amitsur cocycle relation
      \((f_{23}^{\sharp}\theta) \cdot (f_{12}^{\sharp}\theta) = f_{13}^{\sharp}\theta\).
  \end{enumerate}
  The witness relation records, at cocycle level, the class equality
  \(q_1^{*} N = q_2^{*} N\) for \(N = [\mathcal N, \gamma]\); the coherence relation is the
  triple-overlap cocycle identity that lets \(\theta\) itself descend.
\end{definition}

\begin{lemma}[Global-unit correction of a witness]
  \label{lem:nonempty_of_defect_eq_coboundary}
  \lean{AlgebraicGeometry.CoherentCechWitness.nonempty_of_defect_eq_coboundary}
  \uses{def:CoherentCechWitness, def:amitsurCover, lem:global_unit_pullback}
  \source{kleiman-picard}
  \leanok
  Let \(\theta_0\) be a witness cochain on a common refinement \(\mathcal V\) of the two
  coprojection pullbacks of \(\mathcal N\) (satisfying the witness relation for \(\gamma\)), and
  let \(\chi\) be a global unit on \(\Spec(B \otimes_A B)\) whose Amitsur coboundary
  \((f_{23}^{\sharp}\chi)(f_{12}^{\sharp}\chi)/(f_{13}^{\sharp}\chi)\) restricts, on
  \(\mathcal V_{123}\), to the Amitsur defect
  \((f_{23}^{\sharp}\theta_0)(f_{12}^{\sharp}\theta_0)/(f_{13}^{\sharp}\theta_0)\) of
  \(\theta_0\). Then the corrected cochain \(\theta := \theta_0/\chi\) is an Amitsur-coherent
  \v Cech witness for \(\gamma\).
\end{lemma}
\begin{proof}
  \leanok
  Take the cover of the witness to be \(\mathcal V\) and the cochain to be
  \(\theta = \theta_0/(\chi|)\), where \(\chi|\) is the restriction of the global unit \(\chi\)
  to the members of \(\mathcal V\). For the witness relation: dividing both sides of the
  witness relation for \(\theta_0\) by the central unit \(\chi\), which restricts the same way
  at \(x\) and \(y\), preserves it, so \(\theta\) is again a witness. For coherence: the Amitsur
  defect of \(\theta\) is the Amitsur defect of \(\theta_0\) divided by the Amitsur combination
  \((f_{23}^{\sharp}\chi)(f_{12}^{\sharp}\chi)/(f_{13}^{\sharp}\chi)\) of the coface restrictions
  of \(\chi\). Each coface pullback of the restricted global unit \(\chi\) is the restriction of
  its global-section pullback (Lemma~\ref{lem:global_unit_pullback}), so this Amitsur
  combination is exactly the restriction of the global unit displayed in the hypothesis; by
  hypothesis it equals the Amitsur defect of \(\theta_0\). The quotient is therefore \(1\),
  i.e.\ \((f_{23}^{\sharp}\theta)(f_{12}^{\sharp}\theta) = f_{13}^{\sharp}\theta\).
\end{proof}

\begin{definition}[The Amitsur defect of a witness cochain]
  \label{def:defectCochain}
  \lean{AlgebraicGeometry.Over.defectCochain}
  \uses{def:amitsurCover}
  \leanok
  The \emph{Amitsur defect} of a unit \(0\)-cochain \(\theta_0\) on a pointed cover
  \(\mathcal V\) of \(\Spec(B \otimes_A B)\) is the unit \(0\)-cochain
  \[
    \partial\theta_0 :=
      \frac{(f_{23}^{\sharp}\theta_0) \cdot (f_{12}^{\sharp}\theta_0)}{f_{13}^{\sharp}\theta_0}
  \]
  on the Amitsur refinement \(\mathcal V_{123}\). A witness is Amitsur-coherent precisely when
  its defect is the constant unit \(1\).
\end{definition}

\begin{theorem}[The Amitsur defect of a witness glues to a global unit]
  \label{thm:exists_glued_defect}
  \lean{AlgebraicGeometry.Over.exists_glued_defect}
  \uses{def:defectCochain, lem:unitsAppLE_coboundary_rel, lem:unitsAppLE_congr_hom,
    lem:overSpec_whisker_face, thm:exists_global_unit_of_compatible}
  \leanok
  If \(\theta_0\) is a witness cochain for \(\gamma\) on a common refinement \(\mathcal V\)
  (satisfying the witness relation), then its Amitsur defect \(\partial\theta_0\) has trivial
  \v Cech coboundary and glues to a global unit \(\bar\omega\) on the triple tensor
  \(\Spec(B \otimes_A (B \otimes_A B))\), restricting to \(\partial\theta_0\) on each member of
  \(\mathcal V_{123}\).
\end{theorem}
\begin{proof}
  \leanok
  Pull the witness relation for \(\theta_0\) back along each of the three cofaces
  \(f_{23}, f_{12}, f_{13}\) (Lemma~\ref{lem:unitsAppLE_coboundary_rel}), obtaining on the
  Amitsur refinement three coboundary relations between the coface pullbacks of \(\theta_0\) and
  the pulled-back coprojections of \(\gamma\). By the coface coincidences
  (Lemma~\ref{lem:overSpec_whisker_face}) the six composite maps
  \(f_{\bullet} \circ q_{\bullet}\) collapse onto the three insertions, so — after rewriting the
  point-indexed \(\gamma\)-terms accordingly (Lemma~\ref{lem:unitsAppLE_congr_hom}) — the three
  relations share matching \(\gamma\)-factors. Multiplying the \(f_{23}\)- and
  \(f_{12}\)-relations and dividing by the \(f_{13}\)-relation, the \(\gamma\)-factors cancel
  telescopically, leaving that the defect values \(\partial\theta_0\) at any two points of
  \(\mathcal V_{123}\) agree on their overlap. Thus \(\partial\theta_0\) is a compatible unit
  family, and by global gluing of a compatible family
  (Theorem~\ref{thm:exists_global_unit_of_compatible}) it glues to a global unit \(\bar\omega\).
\end{proof}

\begin{lemma}[Compatibility of a ratio cochain from two coboundary relations]
  \label{lem:ratio_compat}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_coboundary_ratio_compat}
  \uses{lem:unitsAppLE_coboundary_rel, lem:unitsAppLE_congr_hom}
  \leanok
  Let \(\varphi_t \colon X \to Y_c\) and \(\varphi_1, \varphi_2 \colon X \to Y_a\). Suppose a
  unit \(0\)-cochain \(c\) on \(Y_c\) cobounds the comparison of a family \(E_Z\) along two maps
  \(Y_c \to Z\), and a unit \(0\)-cochain \(a\) on \(Y_a\) cobounds the comparison of \(E_Z\)
  (along a map \(Y_a \to Z\)) with a family \(E_W\) (along a map \(Y_a \to W\)). If the
  pulled-back comparison composites coincide pairwise and the two maps \(\varphi_1, \varphi_2\)
  agree after the map to \(W\) (the diagonal coincidence), then the ratio cochain
  \(\varphi_t^{\sharp} c \cdot (\varphi_2^{\sharp} a / \varphi_1^{\sharp} a)\) on \(X\) is
  \v Cech-compatible: its values at any two points agree on a common open.
\end{lemma}
\begin{proof}
  \leanok
  Pull the two coboundary relations back to \(X\): the relation for \(c\) along \(\varphi_t\),
  and the relation for \(a\) along each of \(\varphi_1, \varphi_2\)
  (Lemma~\ref{lem:unitsAppLE_coboundary_rel}). The pairwise coincidence of composites lets us
  identify the \(E_Z\)-terms of the \(c\)-relation with those of the \(a\)-relations, and the
  diagonal coincidence identifies the two \(E_W\)-terms of the \(\varphi_1\)- and
  \(\varphi_2\)-pullbacks (Lemma~\ref{lem:unitsAppLE_congr_hom}). Writing \(Q_1, Q_2\) for the
  common \(E_Z\)-terms and \(L\) for the common \(E_W\)-term, the three relations read
  \(c_x Q_1 = Q_2 c_{x'}\), \(a_i Q_i = L\,a_i'\); a direct computation in the unit group then
  gives \(c_x (a_2/a_1) = c_{x'}(a_2'/a_1')\), which is compatibility of the ratio cochain.
\end{proof}

\begin{definition}[The comparison cover on the curve product]
  \label{def:comparisonCover}
  \lean{AlgebraicGeometry.Over.comparisonCover}
  \uses{def:tensorInl_tensorInr}
  \leanok
  On the curve product \(X_{B \otimes B} := C \otimes \Spec(B \otimes_A B)\), the
  \emph{comparison cover} of a witness cover \(\mathcal V\) of \(\Spec(B \otimes_A B)\) and an
  upstairs cover \(\mathcal A\) of \(X_B := C \otimes \Spec B\) is the pointwise intersection
  \[
    \mathrm{pr}^{*}\mathcal V \;\sqcap\; \bigl(u_1^{*}\mathcal A \sqcap u_2^{*}\mathcal A\bigr),
  \]
  where \(\mathrm{pr} \colon X_{B \otimes B} \to \Spec(B \otimes_A B)\) is the projection and
  \(u_1, u_2 = C \lhd q_1, C \lhd q_2 \colon X_{B \otimes B} \to X_B\) are the whiskered
  coprojections.
\end{definition}

\begin{definition}[The comparison cochain]
  \label{def:comparisonCochain}
  \lean{AlgebraicGeometry.Over.comparisonCochain}
  \uses{def:comparisonCover}
  \leanok
  Given a witness cochain \(\theta_0\) on \(\mathcal V\) and an upstairs witness cochain
  \(\alpha\) on \(\mathcal A\), their \emph{comparison cochain} on the comparison cover is the
  unit \(0\)-cochain
  \[
    \mathrm{pr}^{\sharp}\theta_0 \cdot
      \frac{u_2^{\sharp}\alpha}{u_1^{\sharp}\alpha} .
  \]
\end{definition}

\begin{theorem}[The comparison cochain is \v Cech-compatible]
  \label{thm:comparisonCochain_compat}
  \lean{AlgebraicGeometry.Over.comparisonCochain_compat}
  \uses{def:comparisonCochain, lem:ratio_compat, lem:whisker_inl_ofId, lem:snd_left_naturality}
  \leanok
  Let \(\theta_0\) be a witness cochain for \(\gamma\) downstairs and \(\alpha\) a witness
  cochain upstairs for the lift — that is, \(\alpha\) cobounds the comparison of the projection
  pullback of \(\gamma\) with the pullback along \(C \lhd \Spec(A \to B)\) of a unit cocycle
  \(\lambda\) representing the class \(L\). Then the comparison cochain of \(\theta_0\) against
  \(\alpha\) is \v Cech-compatible, hence has trivial coboundary.
\end{theorem}
\begin{proof}
  \leanok
  Apply the compatibility principle for ratio cochains (Lemma~\ref{lem:ratio_compat}) with
  \(\varphi_t = \mathrm{pr}\) and \(\varphi_1 = u_1\), \(\varphi_2 = u_2\): the witness relation
  for \(\theta_0\) downstairs and the witness relation for \(\alpha\) upstairs are the two
  coboundary relations. The base squares of the projection
  (Lemma~\ref{lem:snd_left_naturality}) identify \(\mathrm{pr}\) followed by each coprojection
  \(q_i\) with \(u_i\) followed by the projection \(\mathrm{pr}_B\), giving the pairwise
  coincidence of the \(\gamma\)-composites; and the diagonal coincidence
  (Lemma~\ref{lem:whisker_inl_ofId}) identifies \(u_1\) and \(u_2\) after the whiskered base
  inclusion, cancelling the \(\lambda\)-terms carrying the class \(L\). The hypotheses of
  Lemma~\ref{lem:ratio_compat} are met, and its conclusion is exactly compatibility of the
  comparison cochain.
\end{proof}

\begin{theorem}[The comparison cochain glues and descends to the correcting unit]
  \label{thm:exists_comparison_unit}
  \lean{AlgebraicGeometry.Over.exists_comparison_unit}
  \uses{thm:comparisonCochain_compat, thm:exists_global_unit_of_compatible, def:unitsSndTopEquiv}
  \leanok
  In the setting of Theorem~\ref{thm:comparisonCochain_compat}, the comparison cochain glues to
  a global unit on the curve product \(X_{B \otimes B}\), which descends through the projection
  to a global unit \(\chi\) on \(\Spec(B \otimes_A B)\) whose projection pullback restricts to
  the comparison cochain.
\end{theorem}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:comparisonCochain_compat} the comparison cochain is a compatible unit
  family, so it glues to a global unit \(\psi\) on \(X_{B \otimes B}\)
  (Theorem~\ref{thm:exists_global_unit_of_compatible}). Global-unit pullback along the
  projection is a group isomorphism (Definition~\ref{def:unitsSndTopEquiv}); let \(\chi\) be the
  image of \(\psi\) under its inverse. Then the projection pullback of \(\chi\) is \(\psi\),
  which restricts to the comparison cochain on each member of the comparison cover.
\end{proof}

\begin{theorem}[The glued defect is the Amitsur coboundary of the comparison unit]
  \label{thm:glued_defect_eq_amitsur_coboundary}
  \lean{AlgebraicGeometry.Over.glued_defect_eq_amitsur_coboundary}
  \uses{def:defectCochain, def:comparisonCochain, lem:unitsAppLE_glued_pullback,
    lem:global_unit_pullback, lem:units_map_appTop_comp, lem:overSpec_whisker_face,
    thm:appTop_units_bijective, lem:snd_left_naturality}
  \leanok
  Suppose the glued Amitsur defect \(\bar\omega\) of a witness cochain \(\theta_0\) restricts to
  the Amitsur defect \(\partial\theta_0\), and the comparison unit \(\chi\) pulls back on the
  curve product to the comparison cochain of \(\theta_0\) against an upstairs witness
  \(\alpha\). Then \(\bar\omega\) is the Amitsur coboundary of \(\chi\):
  \[
    \bar\omega
      = \frac{(f_{23}^{\sharp}\chi) \cdot (f_{12}^{\sharp}\chi)}{f_{13}^{\sharp}\chi} .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both sides are global units on the triple tensor; since global-unit pullback along the curve
  projection is injective (Theorem~\ref{thm:appTop_units_bijective}), it suffices to compare
  their pullbacks to the triple-tensor curve product. Pull \(\bar\omega\) back along the
  projection: by Lemma~\ref{lem:unitsAppLE_glued_pullback} and the base squares of the
  projection (Lemma~\ref{lem:snd_left_naturality}) it restricts to the Amitsur combination of
  the three whiskered-coface pullbacks of \(\theta_0\). Pull each coface pullback of \(\chi\)
  back along the projection: by functoriality of the global-unit pullback
  (Lemma~\ref{lem:global_unit_pullback}, Lemma~\ref{lem:units_map_appTop_comp}) and the base
  squares it becomes the corresponding whiskered-coface pullback of the descended comparison
  unit, which by Lemma~\ref{lem:unitsAppLE_glued_pullback} together with the coface coincidences
  (Lemma~\ref{lem:overSpec_whisker_face}) restricts to the same \(\theta_0\)-term times a
  telescoping combination of correction factors built from \(\alpha\). Forming the Amitsur
  combination of the three, the \(\alpha\)-telescope cancels exactly, leaving precisely the
  Amitsur combination of \(\theta_0\)-terms found for \(\bar\omega\). The two global units thus
  have equal projection pullbacks, hence are equal.
\end{proof}

\begin{theorem}[Existence of the Amitsur-coherent \v Cech witness]
  \label{thm:exists_coherentCechWitness}
  \lean{AlgebraicGeometry.Over.exists_coherentCechWitness}
  \uses{def:CoherentCechWitness, thm:cechPicMap_tensorInl_eq_tensorInr, thm:exists_glued_defect,
    thm:exists_comparison_unit, thm:glued_defect_eq_amitsur_coboundary,
    lem:nonempty_of_defect_eq_coboundary}
  \source{kleiman-picard}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced over the field
  \(k\), let \(k \to A \to B\) be a tower of algebras, let \(L\) be a \v Cech Picard class on
  \(C \otimes \Spec A\), and let \(\gamma\) be a unit cocycle on a pointed cover \(\mathcal N\)
  of \(\Spec B\) whose class \(N\) pulls back, on the curve product, from \(L\):
  \(\mathrm{pr}_B^{*} N = (C \lhd \Spec(A \to B))^{*} L\). Then there exists an Amitsur-coherent
  \v Cech witness for \(\gamma\) — a witness for the class equality
  \(q_1^{*} N = q_2^{*} N\) over \(\Spec(B \otimes_A B)\) whose coface pullbacks are Amitsur-coherent
  over the triple tensor.
\end{theorem}
\begin{proof}
  \leanok
  By the class-level coherence seed (Theorem~\ref{thm:cechPicMap_tensorInl_eq_tensorInr}) the
  hypothesis gives the equality \(q_1^{*} N = q_2^{*} N\); unwinding it through the
  equality criterion for \v Cech Picard classes yields a common refinement \(\mathcal V\) of the
  two coprojection pullbacks of \(\mathcal N\) and a witness cochain \(\theta_0\) on it
  satisfying the witness relation. Likewise, the hypothesis
  \(\mathrm{pr}_B^{*} N = (C \lhd \Spec(A \to B))^{*} L\) yields an upstairs witness cochain
  \(\alpha\) on a cover \(\mathcal A\) of \(X_B\), cobounding the comparison of the projection
  pullback of \(\gamma\) with the pullback of a representative \(\lambda\) of \(L\).
  The Amitsur defect of \(\theta_0\) glues to a global unit \(\bar\omega\)
  (Theorem~\ref{thm:exists_glued_defect}); the comparison of \(\theta_0\) against
  \(\alpha\) glues and descends to a global unit \(\chi\) on \(\Spec(B \otimes_A B)\)
  (Theorem~\ref{thm:exists_comparison_unit}); and \(\bar\omega\) is identified
  with the Amitsur coboundary of \(\chi\) (Theorem~\ref{thm:glued_defect_eq_amitsur_coboundary}).
  Thus \(\chi\) satisfies the hypothesis of the correction lemma
  (Lemma~\ref{lem:nonempty_of_defect_eq_coboundary}), and the corrected cochain
  \(\theta_0/\chi\) is the required Amitsur-coherent \v Cech witness.
\end{proof}

\section{The simplicial degeneracies of the tensor tower}
\label{sec:specDegeneracy}

Complementing the cofaces of Definition~\ref{def:tensorFaces} and their \(\Spec\)-level
coincidences (Lemma~\ref{lem:overSpec_whisker_face}), the composite descent unit pulls back
along the two \emph{degeneracies} of the tensor tower: the multiplication, whose \(\Spec\)
is the diagonal, and the first-two-positions multiplication, whose \(\Spec\) is a
degeneracy of the triple tensor.

\begin{definition}[The multiplication and the first degeneracy]
  \label{def:tensorMul}
  \lean{AlgebraicGeometry.tensorMul, AlgebraicGeometry.descentMul₁₂,
    AlgebraicGeometry.tensorMul₁₂}
  \uses{def:tensorInl_tensorInr, def:tensorFaces}
  \leanok
  The \emph{multiplication} is the \(k\)-algebra homomorphism
  \[
    \mathrm{tensorMul} \colon B \otimes_A B \to B, \qquad x \otimes y \mapsto xy ,
  \]
  whose \(\Spec\) is the diagonal \(\Delta \colon \Spec B \to \Spec(B \otimes_A B)\). The
  \emph{first degeneracy} is the \(k\)-algebra homomorphism multiplying the first two tensor
  positions,
  \[
    \mathrm{tensorMul}_{12} \colon B \otimes_A (B \otimes_A B) \to B \otimes_A B, \qquad
    x \otimes (y \otimes z) \mapsto xy \otimes z ,
  \]
  whose \(\Spec\) is the degeneracy \(\sigma \colon \Spec(B \otimes_A B) \to
  \Spec(B \otimes_A (B \otimes_A B))\).
\end{definition}

\begin{lemma}[Degeneracy identities at ring level]
  \label{lem:tensorMul_simplicial}
  \lean{AlgebraicGeometry.tensorMul_comp_tensorInl,
    AlgebraicGeometry.tensorMul_comp_tensorInr,
    AlgebraicGeometry.tensorMul₁₂_comp_tensorFace₂₃,
    AlgebraicGeometry.tensorMul₁₂_comp_tensorFace₁₂,
    AlgebraicGeometry.tensorMul₁₂_comp_tensorFace₁₃}
  \uses{def:tensorMul, def:tensorInl_tensorInr, def:tensorFaces}
  \leanok
  The degeneracies satisfy the simplicial identities against the coprojections and cofaces:
  \[
    \mathrm{tensorMul} \circ \mathrm{tensorInl} = \mathrm{id}_B
      = \mathrm{tensorMul} \circ \mathrm{tensorInr} ,
  \]
  and, on the triple tensor,
  \[
    \mathrm{tensorMul}_{12} \circ \mathrm{tensorFace}_{23} = \mathrm{id}, \quad
    \mathrm{tensorMul}_{12} \circ \mathrm{tensorFace}_{13} = \mathrm{id}, \quad
    \mathrm{tensorMul}_{12} \circ \mathrm{tensorFace}_{12}
      = \mathrm{tensorInl} \circ \mathrm{tensorMul} .
  \]
\end{lemma}
\begin{proof}
  \leanok
  Each identity is an equality of \(k\)-algebra homomorphisms, checked on a generator. For the
  first pair, \(\mathrm{tensorMul}(\mathrm{tensorInl}\,b) = \mathrm{tensorMul}(b \otimes 1) = b\)
  and \(\mathrm{tensorMul}(\mathrm{tensorInr}\,b) = \mathrm{tensorMul}(1 \otimes b) = b\). For
  the degeneracy against the cofaces, compute on \(x \otimes y\): \(\mathrm{tensorMul}_{12}(1
  \otimes (x \otimes y)) = x \otimes y\); \(\mathrm{tensorMul}_{12}(x \otimes (1 \otimes y)) =
  x \otimes y\); and \(\mathrm{tensorMul}_{12}(x \otimes (y \otimes 1)) = xy \otimes 1 =
  \mathrm{tensorInl}(xy) = \mathrm{tensorInl}(\mathrm{tensorMul}(x \otimes y))\).
\end{proof}

\begin{lemma}[The degeneracy coincidences at \(\Spec\) level]
  \label{lem:overSpecMap_left_degeneracy}
  \lean{AlgebraicGeometry.Over.overSpecMap_left_mul_inl,
    AlgebraicGeometry.Over.overSpecMap_left_mul_inr,
    AlgebraicGeometry.Over.overSpecMap_left_mul₁₂_face₂₃,
    AlgebraicGeometry.Over.overSpecMap_left_mul₁₂_face₁₂,
    AlgebraicGeometry.Over.overSpecMap_left_mul₁₂_face₁₃}
  \uses{lem:tensorMul_simplicial, def:overSpecMap}
  \leanok
  Applying \(\Spec\) to Lemma~\ref{lem:tensorMul_simplicial} gives the degeneracy coincidences
  of the affine test objects: as morphisms \(\Spec B \to \Spec B\) and
  \(\Spec(B \otimes_A B) \to \Spec(B \otimes_A B)\),
  \[
    \Delta \circ q_1 = \mathrm{id}, \quad \Delta \circ q_2 = \mathrm{id}, \quad
    \sigma \circ f_{23} = \mathrm{id}, \quad \sigma \circ f_{13} = \mathrm{id}, \quad
    \sigma \circ f_{12} = q_1 \circ \Delta .
  \]
\end{lemma}
\begin{proof}
  \leanok
  Each is the image of the corresponding ring-level identity of
  Lemma~\ref{lem:tensorMul_simplicial} under the contravariant functor \(\Spec\) on test
  objects (Definition~\ref{def:overSpecMap}), which turns each equal composite of algebra maps
  into the reversed equal composite of morphisms and sends the identity algebra map to the
  identity morphism.
\end{proof}

\section{The trivialization-corrected witness cochain}
\label{sec:witnessCorrection}

The values \(\theta_x\) of an Amitsur-coherent \v Cech witness
(Definition~\ref{def:CoherentCechWitness}) do not by themselves glue over a basic open of the
tensor square: their coboundary is the comparison of the two coprojection pullbacks of
\(\gamma\). The composite descent unit corrects them by cocycle values of \(\gamma\) anchored
at two distinguished points, after which they glue, satisfy the Amitsur cocycle identity, and
collapse onto the Zariski cover cocycle on the diagonal. This section develops that calculus
over abstract schemes; the concrete tensor-tower instantiation is
Section~\ref{sec:witnessComponents}.

Throughout, \(r_1, r_2 \colon Y \to Z\) are two morphisms (playing the coprojections
\(\Spec(B \otimes_A B) \to \Spec B\)); \(\mathcal C\) is a pointed cover of \(Y\) with a unit
\(0\)-cochain \(c\) (the witness cover and cochain); \(\mathcal N\) is a pointed cover of
\(Z\) with a unit cocycle \(\gamma_Z\) (the trivializing cover of \(\Spec B\)); \(a, b \in Z\)
are two points; and \(D \subseteq Y\) is an open on which \(r_1\) lands in \(\mathcal N_a\) and
\(r_2\) in \(\mathcal N_b\).

\begin{definition}[The corrected witness cochain]
  \label{def:unitsCorrCochain}
  \lean{AlgebraicGeometry.unitsCorrCochain}
  \leanok
  The \emph{corrected witness value} at a point \(y \in Y\) is the unit on
  \(\mathcal C_y \cap D\)
  \[
    (\mathrm{corr}\,c)_y := r_1^{\sharp}\gamma_Z(a,\, r_1 y) \cdot (c_y)^{-1} \cdot
      r_2^{\sharp}\gamma_Z(r_2 y,\, b) ,
  \]
  the two correction factors being the coprojection pullbacks of the cocycle values of
  \(\gamma_Z\) anchored \(a \to r_1 y\) on the left and \(r_2 y \to b\) on the right, with the
  witness entering inverted. This is the unique orientation whose coboundary cancels the
  coboundary of \(\theta^{-1}\), and which on the diagonal — where the coherent witness is
  \(1\) — telescopes to the cocycle value \(\gamma_Z(a, b)\).
\end{definition}

\begin{theorem}[The corrected values are \v Cech-compatible]
  \label{thm:unitsCorrCochain_compat}
  \lean{AlgebraicGeometry.unitsCorrCochain_compat}
  \uses{def:unitsCorrCochain}
  \leanok
  Assume the witness relation for \(c\): on the overlaps of \(\mathcal C\),
  \(c_x \cdot r_1^{\sharp}\gamma_Z(r_1 x, r_1 y) = r_2^{\sharp}\gamma_Z(r_2 x, r_2 y) \cdot c_y\).
  Then the corrected values agree on overlaps: the restrictions of \((\mathrm{corr}\,c)_y\) and
  \((\mathrm{corr}\,c)_{y'}\) to \((\mathcal C_y \cap D) \cap (\mathcal C_{y'} \cap D)\)
  coincide.
\end{theorem}
\begin{proof}
  \leanok
  Restrict all data to the overlap \(O := (\mathcal C_y \cap D) \cap (\mathcal C_{y'} \cap D)\).
  Three relations hold on \(O\): the cocycle identity of \(\gamma_Z\) at \((a, r_1 y, r_1 y')\)
  pulled back along \(r_1\), which expresses the left factor at \(y\) times the
  \(r_1\)-comparison term \(r_1^{\sharp}\gamma_Z(r_1 y, r_1 y')\) as the left factor at \(y'\);
  the witness relation for \(c\) at \((y, y')\), relating the two witness values through the
  \(r_1\)- and \(r_2\)-comparison terms; and the cocycle identity at \((r_2 y, r_2 y', b)\)
  pulled back along \(r_2\), which relates the two right factors symmetrically. Writing the
  three as \(A_y Q_1 = A_{y'}\), \(t_y Q_1 = Q_2 t_{y'}\), \(Q_2 C_{y'} = C_y\) in the
  commutative group of units on \(O\) (with \(A\) the left factors, \(t\) the witnesses, \(C\)
  the right factors, \(Q_1, Q_2\) the comparison terms), substituting \(Q_2 = t_y Q_1 t_{y'}^{-1}\)
  and cancelling \(t_y^{-1} t_y\) turns \(A_y t_y^{-1} C_y\) into \(A_{y'} t_{y'}^{-1} C_{y'}\),
  which is the asserted equality of corrected values.
\end{proof}

\begin{theorem}[The corrected values glue to a unit]
  \label{thm:exists_glued_unitsCorrCochain}
  \lean{AlgebraicGeometry.exists_glued_unitsCorrCochain}
  \uses{def:unitsCorrCochain, thm:unitsCorrCochain_compat, lem:units_gluing}
  \leanok
  Under the witness relation of Theorem~\ref{thm:unitsCorrCochain_compat}, the corrected values
  glue to a single unit \(u \in \Gamma(Y, D)^{\times}\) whose restriction to each
  \(\mathcal C_y \cap D\) is \((\mathrm{corr}\,c)_y\).
\end{theorem}
\begin{proof}
  \leanok
  The opens \(\{\mathcal C_y \cap D\}_{y}\) cover \(D\), since \(y \in \mathcal C_y\). The
  corrected values agree on overlaps by Theorem~\ref{thm:unitsCorrCochain_compat}, so the sheaf
  gluing for unit sections (Lemma~\ref{lem:units_gluing}) produces the glued unit \(u\) on
  \(D\).
\end{proof}

\begin{theorem}[Pullback expansion of a glued corrected unit]
  \label{thm:unitsAppLE_glued_corr}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_glued_corr}
  \uses{def:unitsCorrCochain, thm:exists_glued_unitsCorrCochain}
  \leanok
  Let \(\varphi \colon X' \to Y\) and let \(O \subseteq X'\) be an open inside
  \(\varphi^{-1}(\mathcal C_{\varphi x} \cap D)\). Then the \(\varphi\)-pullback of a glued
  corrected unit \(u\) expands into its three factors, the correction factors pulled back along
  the composites \(\varphi \circ r_1\) and \(\varphi \circ r_2\):
  \[
    \varphi^{\sharp} u =
      (\varphi r_1)^{\sharp}\gamma_Z(a,\, (\varphi r_1)x) \cdot
      \bigl(\varphi^{\sharp} c_{\varphi x}\bigr)^{-1} \cdot
      (\varphi r_2)^{\sharp}\gamma_Z((\varphi r_2)x,\, b) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  By the defining property of \(u\) (Theorem~\ref{thm:exists_glued_unitsCorrCochain}), its
  restriction to \(\mathcal C_{\varphi x} \cap D\) is \((\mathrm{corr}\,c)_{\varphi x}\). Pull
  this equality back along \(\varphi\) into \(O\) and distribute the pullback over the product
  and inverse; each point-indexed factor pulled back along \(\varphi\) then along \(r_i\)
  becomes its pullback along the composite \(\varphi \circ r_i\), which is the displayed normal
  form.
\end{proof}

\begin{theorem}[Coherence kills the witness along a coface section]
  \label{thm:unitsAppLE_eq_one_of_coherent}
  \lean{AlgebraicGeometry.unitsAppLE_eq_one_of_coherent}
  \uses{def:CoherentCechWitness}
  \leanok
  Let \(g_{23}, g_{12}, g_{13} \colon T \to Y\) satisfy the Amitsur coherence relation for a
  witness cochain \(c\) on a pointed cover \(\mathcal C\) of \(Y\):
  \((g_{23}^{\sharp} c) \cdot (g_{12}^{\sharp} c) = g_{13}^{\sharp} c\) on the common
  refinement of the three coface pullbacks. If \(\sigma \colon Y \to T\) and \(\delta_r \colon
  Y \to Y\) satisfy \(\sigma \circ g_{23} = \mathrm{id}\), \(\sigma \circ g_{12} = \delta_r\)
  and \(\sigma \circ g_{13} = \mathrm{id}\), then the \(\delta_r\)-pullback of \(c\) is
  trivial: \(\delta_r^{\sharp} c = 1\).
\end{theorem}
\begin{proof}
  \leanok
  Pull the coherence relation at the point \(\sigma y\) back along \(\sigma\) onto a suitable
  open. By the composite-section identities \(\sigma \circ g_{23} = \mathrm{id}\),
  \(\sigma \circ g_{12} = \delta_r\), \(\sigma \circ g_{13} = \mathrm{id}\), the three pulled
  back witness terms become \(c\), \(\delta_r^{\sharp} c\) and \(c\) respectively, so the
  relation reads \(c \cdot \delta_r^{\sharp} c = c\). Cancelling the unit \(c\) gives
  \(\delta_r^{\sharp} c = 1\).
\end{proof}

\begin{theorem}[Diagonal triviality of a coherent witness]
  \label{thm:unitsAppLE_diag_eq_one_of_coherent}
  \lean{AlgebraicGeometry.unitsAppLE_diag_eq_one_of_coherent}
  \uses{thm:unitsAppLE_eq_one_of_coherent}
  \leanok
  Let \(\delta \colon Z \to Y\) and \(\delta_r \colon Y \to Y\) satisfy \(\delta \circ
  \delta_r = \delta\), and suppose the \(\delta_r\)-pullback of \(c\) is trivial. Then the
  \(\delta\)-pullback of \(c\) is trivial: \(\delta^{\sharp} c = 1\).
\end{theorem}
\begin{proof}
  \leanok
  Pull the identity \(\delta_r^{\sharp} c = 1\) (at the point \(\delta v\)) back along
  \(\delta\); by \(\delta \circ \delta_r = \delta\) the composite \(\delta \circ \delta_r\)
  reduces to \(\delta\), so the pullback of \(\delta_r^{\sharp} c\) along \(\delta\) is
  \(\delta^{\sharp} c\), while the pullback of the constant \(1\) is \(1\). Hence
  \(\delta^{\sharp} c = 1\).
\end{proof}

\begin{theorem}[The glued corrected units satisfy the Amitsur cocycle identity]
  \label{thm:glued_corr_amitsur}
  \lean{AlgebraicGeometry.glued_corr_amitsur}
  \uses{def:unitsCorrCochain, thm:unitsAppLE_glued_corr}
  \leanok
  Let \(g_{23}, g_{12}, g_{13} \colon T \to Y\) satisfy the simplicial coincidences
  \(g_{13} \circ r_1 = g_{12} \circ r_1\), \(g_{23} \circ r_1 = g_{12} \circ r_2\),
  \(g_{23} \circ r_2 = g_{13} \circ r_2\), and let \(c\) be Amitsur-coherent. Let \(u_{23},
  u_{12}, u_{13}\) be the glued corrected units for the point pairs \((b, c')\), \((a, b)\),
  \((a, c')\) on opens \(D_{23}, D_{12}, D_{13}\). Then, on any \(D_T\) inside the three
  preimages,
  \[
    g_{23}^{\sharp} u_{23} \cdot g_{12}^{\sharp} u_{12} = g_{13}^{\sharp} u_{13} .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Check the identity on each member of the cover \(\{(\mathcal C\text{-triple-overlap})_z \cap
  D_T\}\) of \(D_T\). On such a member, expand the three pulled back glued units by
  Theorem~\ref{thm:unitsAppLE_glued_corr}; the six correction factors, pulled back along the
  composites \(g_{\bullet} \circ r_{\bullet}\), collapse by the three simplicial coincidences
  onto matching cocycle values. Grouping, the left correction factor of \(u_{23}\) and the
  right correction factor of \(u_{12}\) are the two \(\gamma_Z\)-values anchored at \(b\); by
  the cocycle identity of \(\gamma_Z\) at \((b, \cdot, b)\) and \(\gamma_Z(b,b) = 1\) they
  cancel, leaving the remaining correction factors as the correction factors of \(u_{13}\). The
  three witness terms combine by the coherence relation
  \((g_{23}^{\sharp} c)(g_{12}^{\sharp} c) = g_{13}^{\sharp} c\). What remains is exactly
  \(g_{13}^{\sharp} u_{13}\); this is the commutative-group telescope of the paired correction
  factors against the coherence relation.
\end{proof}

\begin{theorem}[The glued corrected unit collapses onto the cocycle value on the diagonal]
  \label{thm:glued_corr_collapse}
  \lean{AlgebraicGeometry.glued_corr_collapse}
  \uses{def:unitsCorrCochain, thm:unitsAppLE_glued_corr}
  \leanok
  Let \(\delta \colon Z \to Y\) be a common section of \(r_1, r_2\) (\(\delta \circ r_1 =
  \mathrm{id} = \delta \circ r_2\)) along which the witness is trivial
  (\(\delta^{\sharp} c = 1\)). Then, on an open \(E\) with \(\delta(E) \subseteq D\) and
  \(E \subseteq \mathcal N_a \cap \mathcal N_b\), the \(\delta\)-pullback of the glued corrected
  unit for the pair \((a, b)\) is the restriction of the cocycle value:
  \(\delta^{\sharp} u = \gamma_Z(a, b)\).
\end{theorem}
\begin{proof}
  \leanok
  Check the identity on each member of the cover \(\{\delta^{-1}\mathcal C_{\delta v} \cap E\}\)
  of \(E\). On such a member, expand \(\delta^{\sharp} u\) by
  Theorem~\ref{thm:unitsAppLE_glued_corr}; since \(\delta \circ r_1 = \mathrm{id} = \delta
  \circ r_2\), the two correction factors become \(\gamma_Z(a, \delta v)\) and
  \(\gamma_Z(\delta v, b)\), and the witness factor is \(1\) by hypothesis. The product of the
  two correction factors telescopes through the cocycle identity of \(\gamma_Z\) at
  \((a, \delta v, b)\) to \(\gamma_Z(a, b)\).
\end{proof}

\section{The glued witness components on the tensor square}
\label{sec:witnessComponents}

We now instantiate the corrected-witness calculus on the tensor towers \(\Spec B \leftarrow
\Spec(B \otimes_A B) \leftarrow \Spec(B \otimes_A (B \otimes_A B))\). Fix an
Amitsur-coherent \v Cech witness \(\theta' \colon \mathrm{CoherentCechWitness}\) for
\(\gamma\) (Definition~\ref{def:CoherentCechWitness}) and a \emph{finite basic refinement}
\(P\) of the trivializing cover \(\mathcal N\): a finite family of sections \(P.r_i \in
\Gamma(\Spec B, \top)\) whose basic opens \(D(P.r_i)\) refine \(\mathcal N\), each with a
distinguished point \(P.\mathrm{pt}_i \in \mathcal N\). Write \(q_1, q_2\) for the
coprojections and \(f_{12}, f_{13}, f_{23}\) for the cofaces.

\begin{definition}[The double and triple basic sections]
  \label{def:pairTripleSection}
  \lean{AlgebraicGeometry.Over.pairSection, AlgebraicGeometry.Over.tripleSection}
  \uses{def:tensorInl_tensorInr, def:tensorFaces}
  \leanok
  The \emph{double basic section} cutting out the double basic open of \(\Spec(B \otimes_A B)\)
  is
  \[
    \mathrm{pairSection}(i, j) := q_1^{\sharp}(P.r_i) \cdot q_2^{\sharp}(P.r_j)
    \in \Gamma(\Spec(B \otimes_A B), \top) ,
  \]
  and the \emph{triple basic section} cutting out the triple basic open of
  \(\Spec(B \otimes_A (B \otimes_A B))\) is
  \[
    \mathrm{tripleSection}(i, j, l) := (f_{12} q_1)^{\sharp}(P.r_i) \cdot
      \bigl( (f_{12} q_2)^{\sharp}(P.r_j) \cdot (f_{13} q_2)^{\sharp}(P.r_l) \bigr) ,
  \]
  spelled through the three canonical insertions \(f_{12} \circ q_1\), \(f_{12} \circ q_2\),
  \(f_{13} \circ q_2\).
\end{definition}

\begin{definition}[The glued witness component]
  \label{def:witnessBasicSection}
  \lean{AlgebraicGeometry.Over.witnessBasicSection}
  \uses{def:pairTripleSection, def:unitsCorrCochain, thm:exists_glued_unitsCorrCochain,
    def:CoherentCechWitness}
  \leanok
  The \emph{glued witness component} \(\mathrm{witnessBasicSection}(i, j)\) is the glued unit on
  the double basic open \(D(\mathrm{pairSection}(i, j))\) obtained from
  Theorem~\ref{thm:exists_glued_unitsCorrCochain} applied to the coprojections \(q_1, q_2\), the
  witness cover and cochain of \(\theta'\), the trivializing cocycle \(\gamma\), and the two
  distinguished points \(P.\mathrm{pt}_i, P.\mathrm{pt}_j\); its restriction to each
  \(\mathcal V_x \cap D(\mathrm{pairSection}(i, j))\) is the corrected witness value at \(x\).
\end{definition}

\begin{theorem}[Diagonal triviality of the coherent witness]
  \label{thm:witnessAppLE_diag_eq_one}
  \lean{AlgebraicGeometry.Over.witnessAppLE_diag_eq_one}
  \uses{thm:unitsAppLE_diag_eq_one_of_coherent, thm:unitsAppLE_eq_one_of_coherent,
    lem:overSpecMap_left_degeneracy, def:CoherentCechWitness}
  \leanok
  The witness cochain \(\theta\) of \(\theta'\) is trivial along the diagonal \(\Delta =
  \Spec(\mathrm{tensorMul})\): the \(\Delta\)-pullback of \(\theta\) is \(1\).
\end{theorem}
\begin{proof}
  \leanok
  Apply the diagonal-triviality transport (Theorem~\ref{thm:unitsAppLE_diag_eq_one_of_coherent})
  with \(\delta = \Delta\) and \(\delta_r = q_1 \circ \Delta\); the required identity
  \(\Delta \circ (q_1 \circ \Delta) = \Delta\) follows from \(\Delta \circ q_1 = \mathrm{id}\)
  (Lemma~\ref{lem:overSpecMap_left_degeneracy}). Its hypothesis — triviality of the
  \((q_1 \circ \Delta)\)-pullback of \(\theta\) — is
  Theorem~\ref{thm:unitsAppLE_eq_one_of_coherent} for the degeneracy \(\sigma\) against the
  three cofaces, whose section identities \(\sigma \circ f_{23} = \mathrm{id}\),
  \(\sigma \circ f_{12} = q_1 \circ \Delta\), \(\sigma \circ f_{13} = \mathrm{id}\) are the
  degeneracy coincidences of Lemma~\ref{lem:overSpecMap_left_degeneracy} and whose coherence
  hypothesis is the Amitsur coherence of \(\theta'\).
\end{proof}

\begin{theorem}[The Amitsur cocycle identity of the glued components]
  \label{thm:witnessBasicSection_amitsur}
  \lean{AlgebraicGeometry.Over.witnessBasicSection_amitsur}
  \uses{def:witnessBasicSection, thm:glued_corr_amitsur, lem:overSpec_whisker_face,
    def:pairTripleSection, def:CoherentCechWitness}
  \leanok
  Over the triple basic open of \(\Spec(B \otimes_A (B \otimes_A B))\), the coface pullbacks of
  the glued witness components satisfy the Amitsur cocycle identity:
  \[
    f_{23}^{\sharp}\,\mathrm{witnessBasicSection}(j, l) \cdot
      f_{12}^{\sharp}\,\mathrm{witnessBasicSection}(i, j)
      = f_{13}^{\sharp}\,\mathrm{witnessBasicSection}(i, l) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  This is Theorem~\ref{thm:glued_corr_amitsur} applied along the cofaces \(f_{23}, f_{12},
  f_{13}\) and coprojections \(q_1, q_2\), for the point pairs
  \((P.\mathrm{pt}_j, P.\mathrm{pt}_l)\), \((P.\mathrm{pt}_i, P.\mathrm{pt}_j)\),
  \((P.\mathrm{pt}_i, P.\mathrm{pt}_l)\) on the three double basic opens. Its simplicial
  coincidences \(f_{12} q_1 = f_{13} q_1\), \(f_{12} q_2 = f_{23} q_1\), \(f_{13} q_2 = f_{23}
  q_2\) are the coface coincidences of Lemma~\ref{lem:overSpec_whisker_face}, and its coherence
  input is the Amitsur coherence of \(\theta'\); the containments of the triple basic open in
  the three coface preimages hold because \(\mathrm{tripleSection}\) is divisible by each coface
  pullback of the relevant \(\mathrm{pairSection}\).
\end{proof}

\begin{theorem}[The diagonal collapse of the glued components]
  \label{thm:witnessBasicSection_collapse}
  \lean{AlgebraicGeometry.Over.witnessBasicSection_collapse}
  \uses{def:witnessBasicSection, thm:glued_corr_collapse, thm:witnessAppLE_diag_eq_one,
    lem:overSpecMap_left_degeneracy, def:pairTripleSection}
  \leanok
  The \(\Delta\)-pullback of the glued witness component onto the Zariski overlap
  \(D(P.r_i \cdot P.r_j) \subseteq \Spec B\) is the Zariski cover cocycle value \(\gamma_{ij}\)
  of \(P\):
  \[
    \Delta^{\sharp}\,\mathrm{witnessBasicSection}(i, j) = \gamma_{ij} .
  \]
\end{theorem}
\begin{proof}
  \leanok
  This is Theorem~\ref{thm:glued_corr_collapse} applied with the common section \(\delta =
  \Delta\) of \(q_1, q_2\), whose identities \(\Delta \circ q_1 = \mathrm{id} = \Delta \circ
  q_2\) are the degeneracy coincidences of Lemma~\ref{lem:overSpecMap_left_degeneracy}. Its
  hypothesis of diagonal triviality of the witness is
  Theorem~\ref{thm:witnessAppLE_diag_eq_one}; the point pair is \((P.\mathrm{pt}_i,
  P.\mathrm{pt}_j)\), and the target open \(D(P.r_i \cdot P.r_j)\) lands in \(\mathcal
  N_{P.\mathrm{pt}_i} \cap \mathcal N_{P.\mathrm{pt}_j}\) and in the \(\Delta\)-preimage of the
  double basic open. The resulting cocycle value \(\gamma(P.\mathrm{pt}_i, P.\mathrm{pt}_j)\)
  restricted to the overlap is, by definition, the Zariski cover cocycle \(\gamma_{ij}\) of the
  basic refinement.
\end{proof}

\section{Section rings on basic opens as two-base localizations}
\label{sec:witnessAway}

To pass the three identities of Section~\ref{sec:witnessComponents} to the pure-algebra
assembly of Section~\ref{sec:piAssembly}, the section rings on the basic opens of the tensor
towers are identified with the algebraic tensor localizations. All section rings of
\(\Spec R\) carry the canonical \(R\)-algebra structure whose structure map is the inverse of
the global-sections isomorphism \(\Gamma\Spec\)-iso followed by restriction.

\begin{theorem}[Section rings on basic opens are localizations of the ring]
  \label{thm:isLocalization_away_sections}
  \lean{AlgebraicGeometry.isLocalization_away_sections}
  \leanok
  For a commutative ring \(R\) and a global section \(g \in \Gamma(\Spec R, \top)\), the
  section ring on the basic open \(D(g)\) is the localization of \(R\) itself away from the
  element \(\Gamma\Spec\text{-}\mathrm{iso}(g) \in R\).
\end{theorem}
\begin{proof}
  \leanok
  The canonical \(\Gamma(\Spec R, \top)\)-algebra structure on \(\Gamma(\Spec R, D(g))\)
  exhibits it as the localization of \(\Gamma(\Spec R, \top)\) away from \(g\). Transport this
  along the ring isomorphism \(R \cong \Gamma(\Spec R, \top)\) given by the global-sections
  isomorphism: the powers of \(g\) correspond to the powers of its image in \(R\), and the two
  algebra structures agree, so \(\Gamma(\Spec R, D(g))\) is the localization of \(R\) away from
  that image.
\end{proof}

\begin{lemma}[The localization elements of the basic sections]
  \label{lem:GammaSpecIso_hom_pairTripleSection}
  \lean{AlgebraicGeometry.Over.ΓSpecIso_hom_pairSection,
    AlgebraicGeometry.Over.ΓSpecIso_hom_tripleSection}
  \uses{def:pairTripleSection, def:tensorInl_tensorInr, def:tensorFaces}
  \leanok
  Write \(b_i \in B\) for the element cutting out \(D(P.r_i)\). The global-sections
  isomorphism carries the double basic section to the two-base localization element
  \[
    \mathrm{pairSection}(i, j) \mapsto (b_i \otimes 1)(1 \otimes b_j)
    \quad\text{in } B \otimes_A B ,
  \]
  and the triple basic section to
  \[
    \mathrm{tripleSection}(i, j, l) \mapsto
      (b_i \otimes 1)\bigl(1 \otimes \bigl((b_j \otimes 1)(1 \otimes b_l)\bigr)\bigr)
    \quad\text{in } B \otimes_A (B \otimes_A B) .
  \]
\end{lemma}
\begin{proof}
  \leanok
  The global-sections isomorphism intertwines \(q_1^{\sharp}\) with \(\mathrm{tensorInl}\) and
  \(q_2^{\sharp}\) with \(\mathrm{tensorInr}\) (its naturality against
  \(\Spec(\mathrm{tensorInl})\), \(\Spec(\mathrm{tensorInr})\)), so it sends
  \(q_1^{\sharp}(P.r_i)\) to \(b_i \otimes 1\) and \(q_2^{\sharp}(P.r_j)\) to \(1 \otimes b_j\);
  multiplying gives the double element. For the triple element, apply naturality once more
  against the cofaces \(f_{12}, f_{13}\), computing the three insertions
  \(f_{12}^{\sharp} q_1^{\sharp}(P.r_i)\), \(f_{12}^{\sharp} q_2^{\sharp}(P.r_j)\),
  \(f_{13}^{\sharp} q_2^{\sharp}(P.r_l)\) as \(b_i \otimes (1 \otimes 1)\),
  \(1 \otimes (b_j \otimes 1)\), \(1 \otimes (1 \otimes b_l)\), and rearranging the product.
\end{proof}

\begin{definition}[The two-base localization identifications]
  \label{def:pairTripleAwayEquiv}
  \lean{AlgebraicGeometry.Over.pairAwayEquiv, AlgebraicGeometry.Over.tripleAwayEquiv}
  \uses{def:tensorAwayEquiv, thm:isLocalization_away_sections, thm:isLocalization_away_tensor,
    lem:GammaSpecIso_hom_pairTripleSection, def:pairTripleSection}
  \leanok
  Let \(S_i := \Gamma(\Spec B, D(P.r_i))\), a localization of \(B\) away from \(b_i\)
  (Theorem~\ref{thm:isLocalization_away_sections}). The comparison of tensor localizations
  (Definition~\ref{def:tensorAwayEquiv}) gives the two-base identifications
  \[
    \mathrm{pairAwayEquiv} \colon S_i \otimes_A S_j \;\xrightarrow{\ \sim\ }\;
      \Gamma\bigl(\Spec(B \otimes_A B), D(\mathrm{pairSection}(i, j))\bigr), \qquad
  \]
  \[
    \mathrm{tripleAwayEquiv} \colon S_i \otimes_A (S_j \otimes_A S_l) \;\xrightarrow{\ \sim\ }\;
      \Gamma\bigl(\Spec(B \otimes_A (B \otimes_A B)), D(\mathrm{tripleSection}(i, j, l))\bigr) ,
  \]
  the target section rings being the localizations of \(B \otimes_A B\), resp.\
  \(B \otimes_A (B \otimes_A B)\), at the two-base elements of
  Lemma~\ref{lem:GammaSpecIso_hom_pairTripleSection}. For the triple identification the inner
  factor \(S_j \otimes_A S_l\) is first recognized as a localization of \(B \otimes_A B\)
  (Theorem~\ref{thm:isLocalization_away_tensor}), so that
  \(S_i \otimes_A (S_j \otimes_A S_l)\) is a two-base localization over
  \(B \otimes_A (B \otimes_A B)\).
\end{definition}

\section{Transport of the simplicial maps through the two-base identifications}
\label{sec:witnessTransport}

The restriction maps of the section rings along the diagonal \(\Delta\) and the three cofaces
correspond, under the identifications of Definition~\ref{def:pairTripleAwayEquiv}, to the
index-wise collapse and faces of the pure-algebra assembly. Each is an instance of the
uniqueness of maps out of a localization: both composites are computed on structure-map
images and agree there, and extensionality is invoked over \(B \otimes_A B\) — where the
components are \(\mathrm{Away}\) localizations — never over \(A\).

\begin{lemma}[The diagonal pullback is the index-wise collapse]
  \label{lem:pairAwayEquiv_appLE_diag}
  \lean{AlgebraicGeometry.Over.pairAwayEquiv_appLE_diag}
  \uses{def:pairTripleAwayEquiv, def:componentCollapse, thm:isLocalization_away_tensor,
    lem:overSpecMap_left_degeneracy}
  \leanok
  Under the identification \(\mathrm{pairAwayEquiv}\), the \(\Delta\)-pullback
  \(\Gamma(D(\mathrm{pairSection}(i, j))) \to \Gamma(D(P.r_i \cdot P.r_j))\) is the index-wise
  collapse \(\kappa_{ij} \colon S_i \otimes_A S_j \to T_{ij}\) onto the Zariski overlap ring
  \(T_{ij} = \Gamma(\Spec B, D(P.r_i \cdot P.r_j))\).
\end{lemma}
\begin{proof}
  \leanok
  Both maps are \(A\)-algebra homomorphisms out of the localization \(S_i \otimes_A S_j\) of
  \(B \otimes_A B\) (Theorem~\ref{thm:isLocalization_away_tensor}), so by uniqueness of maps out
  of a localization it suffices to compare their composites with the structure map
  \(B \otimes_A B \to S_i \otimes_A S_j\). On a structure-map image the \(\Delta\)-pullback
  computes, through the naturality of the global-sections isomorphism against
  \(\Spec(\mathrm{tensorMul})\) and the diagonal coincidence
  (Lemma~\ref{lem:overSpecMap_left_degeneracy}), as the multiplication \(B \otimes_A B \to B\)
  followed by the structure map into \(T_{ij}\); and the index-wise collapse on a structure-map
  image is that same composite (Definition~\ref{def:componentCollapse}). The two agree, hence so
  do the maps.
\end{proof}

\begin{lemma}[The coface pullbacks are the index-wise faces]
  \label{lem:tripleAwayEquiv_faceA}
  \lean{AlgebraicGeometry.Over.tripleAwayEquiv_faceA₂₃,
    AlgebraicGeometry.Over.tripleAwayEquiv_faceA₁₂,
    AlgebraicGeometry.Over.tripleAwayEquiv_faceA₁₃}
  \uses{def:pairTripleAwayEquiv, def:indexwiseMaps, lem:faceA_comp_tensorMap,
    thm:isLocalization_away_tensor, lem:overSpec_whisker_face, def:pairTripleSection}
  \leanok
  Under the identifications \(\mathrm{pairAwayEquiv}\) and \(\mathrm{tripleAwayEquiv}\), the
  three coface pullbacks \(f_{23}^{\sharp}, f_{12}^{\sharp}, f_{13}^{\sharp}\) between the
  basic-open section rings are the index-wise faces \(\mathrm{face}_{23}, \mathrm{face}_{12},
  \mathrm{face}_{13}\) of Definition~\ref{def:indexwiseMaps}.
\end{lemma}
\begin{proof}
  \leanok
  Fix the coface \(\bullet \in \{12, 13, 23\}\). Both \(\mathrm{tripleAwayEquiv} \circ
  \mathrm{face}_{\bullet}\) and \(f_{\bullet}^{\sharp} \circ \mathrm{pairAwayEquiv}\) are
  \(A\)-algebra homomorphisms out of the localization \(S_j \otimes_A S_l\) (resp.\ \(S_i
  \otimes_A S_j\), \(S_i \otimes_A S_l\)) of \(B \otimes_A B\)
  (Theorem~\ref{thm:isLocalization_away_tensor}), so by uniqueness of maps out of a localization
  it suffices to compare their composites with the structure map \(B \otimes_A B \to S_\bullet
  \otimes_A S_\bullet\). On a structure-map image the coface pullback computes, through the
  naturality of the global-sections isomorphism and the coface coincidences
  (Lemma~\ref{lem:overSpec_whisker_face}), as the descent coface followed by the triple
  structure map; and the index-wise face intertwines the double and triple structure maps over
  that same descent coface (Lemma~\ref{lem:faceA_comp_tensorMap}). The two composites agree.
\end{proof}

\section{The composite descent unit of the \'etale-separatedness assembly}
\label{sec:witnessAssembly}

Assembling the glued witness components into the composite \(A\)-descent unit yields the two
halves of the deliverable and the headline class equation handed onward. Write \(S_i :=
\Gamma(\Spec B, D(P.r_i))\) and \(P_{\!\bullet} := \prod_i S_i\).

\begin{definition}[The witness component]
  \label{def:witnessComponent}
  \lean{AlgebraicGeometry.Over.witnessComponent}
  \uses{def:witnessBasicSection, def:pairTripleAwayEquiv}
  \leanok
  The \emph{witness component} \(w_{ij} \in (S_i \otimes_A S_j)^{\times}\) is the glued witness
  component \(\mathrm{witnessBasicSection}(i, j)\) transported through the two-base
  identification \(\mathrm{pairAwayEquiv}\) (Definition~\ref{def:pairTripleAwayEquiv}).
\end{definition}

\begin{definition}[The composite descent unit of the assembly]
  \label{def:assemblyUnit}
  \lean{AlgebraicGeometry.Over.assemblyUnit}
  \uses{def:witnessComponent, def:piAssemblyUnit}
  \leanok
  The \emph{composite descent unit} \(\mathrm{assemblyUnit} \in (P_{\!\bullet} \otimes_A
  P_{\!\bullet})^{\times}\) is the pi-assembly (Definition~\ref{def:piAssemblyUnit}) of the
  family of witness components \((w_{ij})\).
\end{definition}

\begin{theorem}[The witness components collapse onto the Zariski cover cocycle]
  \label{thm:componentCollapse_witnessComponent}
  \lean{AlgebraicGeometry.Over.componentCollapse_witnessComponent}
  \uses{def:witnessComponent, lem:pairAwayEquiv_appLE_diag, thm:witnessBasicSection_collapse,
    def:componentCollapse}
  \leanok
  The index-wise collapse of the witness component is the Zariski cover cocycle value:
  \(\kappa_{ij}(w_{ij}) = \gamma_{ij}\).
\end{theorem}
\begin{proof}
  \leanok
  By Lemma~\ref{lem:pairAwayEquiv_appLE_diag} the collapse \(\kappa_{ij}\) is, through
  \(\mathrm{pairAwayEquiv}\), the \(\Delta\)-pullback; applied to the witness component it is the
  \(\Delta\)-pullback of \(\mathrm{witnessBasicSection}(i, j)\), which is \(\gamma_{ij}\) by
  Theorem~\ref{thm:witnessBasicSection_collapse}.
\end{proof}

\begin{theorem}[The witness components satisfy the index-wise cocycle identity]
  \label{thm:faceA_cocycle_witnessComponent}
  \lean{AlgebraicGeometry.Over.faceA_cocycle_witnessComponent}
  \uses{def:witnessComponent, lem:tripleAwayEquiv_faceA, thm:witnessBasicSection_amitsur,
    def:indexwiseMaps}
  \leanok
  The witness components satisfy the index-wise cocycle identity:
  \(\mathrm{face}_{23}(w_{jl}) \cdot \mathrm{face}_{12}(w_{ij}) = \mathrm{face}_{13}(w_{il})\).
\end{theorem}
\begin{proof}
  \leanok
  Apply the injective identification \(\mathrm{tripleAwayEquiv}\). By
  Lemma~\ref{lem:tripleAwayEquiv_faceA} it carries each index-wise face of a witness component
  to the corresponding coface pullback of the glued component
  \(\mathrm{witnessBasicSection}\); the transported identity is then the Amitsur cocycle
  identity of the glued components (Theorem~\ref{thm:witnessBasicSection_amitsur}).
\end{proof}

\begin{theorem}[The assembled witness unit is an \(A\)-descent \(1\)-cocycle]
  \label{thm:isDescentCocycle_assemblyUnit}
  \lean{AlgebraicGeometry.Over.isDescentCocycle_assemblyUnit}
  \uses{def:assemblyUnit, thm:isDescentCocycle_piAssemblyUnit,
    thm:diagA_eq_one_of_componentCollapse, thm:componentCollapse_witnessComponent,
    thm:faceA_cocycle_witnessComponent}
  \source{kleiman-picard}
  \leanok
  The composite descent unit \(\mathrm{assemblyUnit}\) is an \(A\)-descent \(1\)-cocycle
  relative to \(A \to P_{\!\bullet}\).
\end{theorem}
\begin{proof}
  \leanok
  Apply the descent-cocycle criterion for a pi-assembly
  (Theorem~\ref{thm:isDescentCocycle_piAssemblyUnit}). Its index-wise cocycle hypothesis is
  Theorem~\ref{thm:faceA_cocycle_witnessComponent}. Its diagonal-normalization hypothesis is
  automatic: the witness components collapse onto the Zariski cover cocycle
  (Theorem~\ref{thm:componentCollapse_witnessComponent}), whose diagonal is \(1\) since the
  cover cocycle is a genuine \v Cech cocycle, so
  Theorem~\ref{thm:diagA_eq_one_of_componentCollapse} gives \(\mathrm{diag}(w_{ii}) = 1\). This
  is precisely the descent construction of Kleiman's separatedness argument: the assembled unit
  \(v'_{23} v'_{12} = v'_{13}\) descends the componentwise trivializations to a single datum on
  the base.
\end{proof}

\begin{theorem}[The collapse of the assembled unit is the descent unit of the cover cocycle]
  \label{thm:tensorCollapse_assemblyUnit}
  \lean{AlgebraicGeometry.Over.tensorCollapse_assemblyUnit}
  \uses{def:assemblyUnit, thm:tensorCollapse_piAssemblyUnit,
    thm:componentCollapse_witnessComponent, def:module_tensorCollapse}
  \leanok
  The collapse of the composite descent unit along the tower \(A \to \Gamma(\Spec B, \top) \to
  P_{\!\bullet}\) is the descent unit of the Zariski cover cocycle of \(P\):
  \[
    \pi\bigl(\mathrm{assemblyUnit}\bigr) = \mathrm{cocycleUnit}(\gamma_{\bullet}) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  This is the collapse identity for a pi-assembly
  (Theorem~\ref{thm:tensorCollapse_piAssemblyUnit}), whose hypothesis — that the witness
  components collapse onto the cover cocycle, \(\kappa_{ij}(w_{ij}) = \gamma_{ij}\) — is
  Theorem~\ref{thm:componentCollapse_witnessComponent}; the intermediate ring of the collapse
  tower is the scheme-side base ring \(\Gamma(\Spec B, \top)\).
\end{proof}

\begin{lemma}[Faithful flatness of the global sections of \(\Spec B\)]
  \label{lem:faithfullyFlat_sectionsTop}
  \lean{AlgebraicGeometry.Over.sectionsTopAlgEquiv,
    AlgebraicGeometry.Over.faithfullyFlat_sectionsTop}
  \leanok
  The global-sections isomorphism is an isomorphism of \(A\)-algebras \(\Gamma(\Spec B, \top)
  \cong B\) for the composed \(A\)-structure. Consequently, if \(A \to B\) is faithfully flat,
  then \(A \to \Gamma(\Spec B, \top)\) is faithfully flat.
\end{lemma}
\begin{proof}
  \leanok
  The global-sections isomorphism is a ring isomorphism commuting with the two structure maps
  from \(A\) (both send \(a\) to the image of \(a\), via restriction of \(\Gamma\Spec\)-iso),
  hence an \(A\)-algebra isomorphism. Faithful flatness of a module transports along a linear
  isomorphism, so faithful flatness of \(A \to B\) gives faithful flatness of \(A \to
  \Gamma(\Spec B, \top)\).
\end{proof}

\begin{theorem}[The class equation of the composite descent unit]
  \label{thm:mapAlgebra_picClass_assemblyUnit}
  \lean{AlgebraicGeometry.Over.mapAlgebra_picClass_assemblyUnit}
  \uses{thm:isDescentCocycle_assemblyUnit, thm:tensorCollapse_assemblyUnit,
    thm:module_picClass_collapse, lem:faithfullyFlat_sectionsTop, thm:pi_tower,
    def:module_picClass, thm:trivializingFamily_pic_cocycle}
  \source{kleiman-picard}
  \leanok
  Assume \(A \to B\) is faithfully flat. Then the Picard class of the composite descent unit
  maps, under the base-change homomorphism \(\Pic(A) \to \Pic(\Gamma(\Spec B, \top))\) along
  \(A \to \Gamma(\Spec B, \top)\), to the Picard class of the Zariski cover cocycle of \(P\):
  \[
    \Pic(A \to \Gamma(\Spec B, \top))\bigl(\mathrm{picClass}(\mathrm{assemblyUnit})\bigr)
      = \mathrm{pic}(\gamma) ,
  \]
  which is \([N]\) when \(\gamma\) is the trivializing cocycle of an invertible module \(N\).
\end{theorem}
\begin{proof}
  \leanok
  Set \(P_0 := \Gamma(\Spec B, \top)\). The tower \(A \to P_0 \to P_{\!\bullet}\) is faithfully
  flat: \(A \to P_0\) by Lemma~\ref{lem:faithfullyFlat_sectionsTop}, and \(P_0 \to
  P_{\!\bullet}\) because \(P_{\!\bullet} = \prod_i S_i\) is the product of the localizations of
  \(P_0\) at the covering family \(P.r\) (Theorem~\ref{thm:pi_tower}); hence \(A \to
  P_{\!\bullet}\) is faithfully flat. By naturality of the Picard class under descent in stages
  (Theorem~\ref{thm:module_picClass_collapse}) applied to \(\mathrm{assemblyUnit}\)
  (Theorem~\ref{thm:isDescentCocycle_assemblyUnit}), the base change to \(P_0\) of
  \(\mathrm{picClass}(\mathrm{assemblyUnit})\) is the Picard class over \(P_0\) of the collapse
  \(\pi(\mathrm{assemblyUnit})\). By Theorem~\ref{thm:tensorCollapse_assemblyUnit} that collapse
  is the descent unit of the Zariski cover cocycle, whose Picard class is \(\mathrm{pic}(\gamma)\)
  by definition (Definition~\ref{def:module_picClass}); and when \(\gamma\) trivializes an
  invertible module \(N\), \(\mathrm{pic}(\gamma) = [N]\) by
  Theorem~\ref{thm:trivializingFamily_pic_cocycle}. This is the invertible descended sheaf of
  Kleiman's separatedness argument, in its \v Cech incarnation.
\end{proof}

\section{Faithfully flat descent of sections along the base change of the curve product}
\label{sec:sectionsDescent}

Fix a field \(k\), a curve \(C\) over \(k\) (proper, geometrically irreducible and geometrically
reduced), and a tower \(k \to A \to B\) with \(A \to B\) faithfully flat. Write \(X_A := (C
\otimes \Spec A)_{\mathrm{left}}\), \(X_B := (C \otimes \Spec B)_{\mathrm{left}}\), and
\(\mathrm{cg} := (C \lhd \Spec(A \to B))_{\mathrm{left}} \colon X_B \to X_A\) for the base-change
morphism of the curve product; the two coprojections \(u_1, u_2 \colon (C \otimes \Spec(B
\otimes_A B))_{\mathrm{left}} \to X_B\) are the whiskered coprojections of \(B \otimes_A B\).
This section proves that sections of the structure sheaf, and of its units, descend along
\(\mathrm{cg}\): the fppf sheaf property along the whiskered base inclusion.

\begin{theorem}[The base-change square of the product is a pullback]
  \label{thm:isPullback_whiskerLeft_snd}
  \lean{AlgebraicGeometry.Over.isPullback_whiskerLeft_snd}
  \uses{lem:snd_left_naturality}
  \leanok
  For \(C, T, T'\) over \(\Spec k\) and \(g \colon T' \to T\), the square with horizontal legs
  \((C \lhd g)_{\mathrm{left}}\) and \(g_{\mathrm{left}}\) and vertical legs the two second
  projections is a pullback of schemes:
  \[
    \begin{array}{ccc}
      (C \otimes T')_{\mathrm{left}} & \xrightarrow{(C \lhd g)_{\mathrm{left}}} &
        (C \otimes T)_{\mathrm{left}} \\
      \downarrow \mathrm{pr}' & & \downarrow \mathrm{pr} \\
      T'_{\mathrm{left}} & \xrightarrow{\ g_{\mathrm{left}}\ } & T_{\mathrm{left}}.
    \end{array}
  \]
\end{theorem}
\begin{proof}
  \leanok
  Paste the two cartesian squares expressing \(C \otimes T\) and \(C \otimes T'\) as products
  over \(\Spec k\).  The first-projection triangle \((C \lhd g)_{\mathrm{left}} \circ
  (\mathrm{fst}_{C,T})_{\mathrm{left}} = (\mathrm{fst}_{C,T'})_{\mathrm{left}}\) and the base
  identity \(g_{\mathrm{left}} \circ T.\mathrm{hom} = T'.\mathrm{hom}\) exhibit the outer
  rectangle over \(C \times \Spec k\) as the product square of \(C \otimes T'\); together with
  the naturality square of the second projection (Lemma~\ref{lem:snd_left_naturality}), the
  right-cancellation property of pullbacks gives that the second-projection square is itself a
  pullback.
\end{proof}

\begin{theorem}[Descent of sections along the base change of the curve product]
  \label{thm:existsUnique_appLE_eq}
  \lean{AlgebraicGeometry.Over.existsUnique_appLE_eq}
  \uses{thm:isPullback_whiskerLeft_snd, thm:descent_existsUnique_tmul_one,
    def:tensorInl_tensorInr}
  \leanok
  Let \(U \subseteq X_A\) be an affine open. A section \(t \in \Gamma(X_B, \mathrm{cg}^{-1}U)\)
  whose two coprojection pullbacks to \(C \otimes \Spec(B \otimes_A B)\) agree,
  \(u_1^{*} t = u_2^{*} t\), descends uniquely along \(\mathrm{cg}\): there is a unique \(s \in
  \Gamma(X_A, U)\) with \(\mathrm{cg}^{*} s = t\).
\end{theorem}
\begin{proof}
  \leanok
  Over the affine open \(U\), the base-change square (Theorem~\ref{thm:isPullback_whiskerLeft_snd})
  identifies the sections of \(X_B\) over \(\mathrm{cg}^{-1}U\) with the base change \(\Gamma(X_A,
  U) \otimes_A B\), and those of \(C \otimes \Spec(B \otimes_A B)\) with \(\Gamma(X_A, U)
  \otimes_A (B \otimes_A B)\), the two coprojection pullbacks becoming the two faces
  \(\id \otimes (b \mapsto b \otimes 1)\) and \(\id \otimes (b \mapsto 1 \otimes b)\)
  (Definition~\ref{def:tensorInl_tensorInr}).  Under these identifications \(t\) corresponds to
  an element \(x \in \Gamma(X_A, U) \otimes_A B\) with equal faces, so by the degree-zero Amitsur
  equalizer (Theorem~\ref{thm:descent_existsUnique_tmul_one}) there is a unique \(s \in \Gamma(X_A,
  U)\) with \(s \otimes 1 = x\); this \(s\) is the unique section with \(\mathrm{cg}^{*} s = t\).
\end{proof}

\begin{theorem}[Injectivity of pullback along the base change]
  \label{thm:appLE_whiskerLeft_injective}
  \lean{AlgebraicGeometry.Over.appLE_whiskerLeft_injective}
  \uses{thm:isPullback_whiskerLeft_snd, lem:units_separation}
  \leanok
  For every open \(W \subseteq X_A\), pullback of sections along \(\mathrm{cg}\) is injective,
  \(\Gamma(X_A, W) \to \Gamma(X_B, \mathrm{cg}^{-1}W)\).
\end{theorem}
\begin{proof}
  \leanok
  First over an affine open \(V\): by the base-change square
  (Theorem~\ref{thm:isPullback_whiskerLeft_snd}) the pullback is \(s \mapsto s \otimes 1\) into
  \(\Gamma(X_A, V) \otimes_A B\), which is injective because \(B\) is faithfully flat over
  \(A\).  For an arbitrary open \(W\), if two sections have equal pullbacks, then their
  restrictions to each affine open \(V \subseteq W\) have equal pullbacks (pullback commutes
  with restriction), hence agree by the affine case; as the affine opens contained in \(W\)
  cover \(W\), the two sections agree by separation for the structure sheaf
  (Lemma~\ref{lem:units_separation}).
\end{proof}

\begin{theorem}[Descent of unit sections along the base change]
  \label{thm:exists_unitsAppLE_eq}
  \lean{AlgebraicGeometry.Over.exists_unitsAppLE_eq}
  \uses{thm:existsUnique_appLE_eq, thm:appLE_whiskerLeft_injective}
  \leanok
  Let \(U \subseteq X_A\) be an affine open. A unit \(t \in \Gamma(X_B,
  \mathrm{cg}^{-1}U)^{\times}\) whose two coprojection pullbacks agree, \(u_1^{*} t = u_2^{*}
  t\), descends to a unit: there is \(s \in \Gamma(X_A, U)^{\times}\) with \(\mathrm{cg}^{*} s =
  t\).
\end{theorem}
\begin{proof}
  \leanok
  Both \(t\) and \(t^{-1}\) satisfy the equalizer hypothesis, so by
  Theorem~\ref{thm:existsUnique_appLE_eq} they descend to sections \(a, b \in \Gamma(X_A, U)\)
  with \(\mathrm{cg}^{*} a = t\), \(\mathrm{cg}^{*} b = t^{-1}\).  The pullback of \(ab\) is \(t
  t^{-1} = 1 = \mathrm{cg}^{*} 1\), so \(ab = 1\) by injectivity of the pullback over the affine
  open \(U\) (Theorem~\ref{thm:appLE_whiskerLeft_injective}); likewise \(ba = 1\).  Hence \(a\)
  is a unit and \(\mathrm{cg}^{*} a = t\).
\end{proof}

\section{Saturated affine pieces of the base-change cover}
\label{sec:effectivityPieces}

Retain the field \(k\), the curve \(C\) over \(k\), and the tower \(k \to A \to B\) of the
previous section, with \(X_A = (C \otimes \Spec A)_{\mathrm{left}}\), \(X_B = (C \otimes \Spec
B)_{\mathrm{left}}\), the projections \(\mathrm{pr}_A \colon X_A \to \Spec A\), \(\mathrm{pr}_B
\colon X_B \to \Spec B\), and the base-change morphism \(\mathrm{cg} \colon X_B \to X_A\). This
section refines the \(\top\)-case identification \(\Gamma(X_B, \top) \cong B\)
(Lemma~\ref{lem:faithfullyFlat_sectionsTop}) to an arbitrary affine open of \(X_A\): over such an
open the section ring of the cover piece is the base change of the base section ring along \(A
\to B\). Nothing here uses flatness or properness (except where explicitly assumed); these are
the geometric pieces on which a covering-and-overlaps effectivity argument runs.

\begin{theorem}[The cover inclusion is an affine morphism]
  \label{thm:isAffineHom_cg}
  \lean{AlgebraicGeometry.Over.isAffineHom_cg, AlgebraicGeometry.Over.isAffineOpen_cgPreimage}
  \uses{thm:isPullback_whiskerLeft_snd}
  \leanok
  The base-change morphism \(\mathrm{cg} \colon X_B \to X_A\) is affine. Consequently the
  preimage \(\mathrm{cg}^{-1}U\) of every affine open \(U \subseteq X_A\) is affine.
\end{theorem}
\begin{proof}
  \leanok
  By the base-change square (Theorem~\ref{thm:isPullback_whiskerLeft_snd}, with \(T = \Spec A\),
  \(T' = \Spec B\) and \(g = \Spec(A \to B)\)) the morphism \(\mathrm{cg}\) is the base change of
  \(\Spec(A \to B) \colon \Spec B \to \Spec A\) along the projection \(\mathrm{pr}_A\). The
  morphism \(\Spec(A \to B)\) is affine, being the spectrum of a ring homomorphism, and affine
  morphisms are stable under base change; hence \(\mathrm{cg}\) is affine. The preimage of an
  affine open under an affine morphism is affine.
\end{proof}

\begin{theorem}[The section rings of a saturated affine piece form a pushout square]
  \label{thm:isPushout_cgSectionRing}
  \uses{thm:isAffineHom_cg, thm:isPullback_whiskerLeft_snd}
  \lean{AlgebraicGeometry.Over.isPushout_cgSections,
    AlgebraicGeometry.Over.isPushout_cgAlgebraMap}
  \leanok
  Give \(\Gamma(X_A, U)\) its \(A\)-algebra structure by pullback along the projection
  \(\mathrm{pr}_A\). For every affine open \(U \subseteq X_A\) the square of commutative rings
  \[
    \begin{array}{ccc}
      A & \longrightarrow & \Gamma(X_A, U) \\
      \downarrow & & \downarrow \mathrm{cg}^{\sharp} \\
      B & \longrightarrow & \Gamma\bigl(X_B, \mathrm{cg}^{-1}U\bigr)
    \end{array}
  \]
  --- with top and left legs the two structure maps from \(A\), right leg the pullback
  \(\mathrm{cg}^{\sharp}\), and bottom leg the pullback along \(\mathrm{pr}_B\) --- is a pushout
  (cocartesian). No flatness or properness is used.
\end{theorem}
\begin{proof}
  \leanok
  The base-change square of schemes (Theorem~\ref{thm:isPullback_whiskerLeft_snd}) has one leg,
  \(\Spec(A \to B)\), affine, and \(U\) is affine; for such a fibre square the induced square of
  section rings over \(U\) --- with the two \(\top\)-corners \(\Gamma(\Spec A, \top)\) and
  \(\Gamma(\Spec B, \top)\) --- is a pushout. Re-cornering along the canonical identifications
  \(\Gamma(\Spec A, \top) \cong A\) and \(\Gamma(\Spec B, \top) \cong B\) (which intertwine the
  structure maps, as in Lemma~\ref{lem:faithfullyFlat_sectionsTop}) replaces those two corners by
  \(A\) and \(B\), yielding the displayed pushout.
\end{proof}

\begin{definition}[The section-ring identification]
  \label{def:pieceRingEquiv}
  \uses{thm:isPushout_cgSectionRing}
  \lean{AlgebraicGeometry.Over.pieceTensorIso, AlgebraicGeometry.Over.pieceRingEquiv,
    AlgebraicGeometry.Over.pieceRingEquiv_tmul_one, AlgebraicGeometry.Over.pieceRingEquiv_one_tmul,
    AlgebraicGeometry.Over.pieceRingEquiv_tmul}
  \leanok
  For every affine open \(U \subseteq X_A\) there is a ring isomorphism
  \[
    \Gamma(X_A, U) \otimes_A B \;\xrightarrow{\ \sim\ }\; \Gamma\bigl(X_B, \mathrm{cg}^{-1}U\bigr),
    \qquad s \otimes b \;\longmapsto\; \mathrm{cg}^{\sharp}(s)\cdot \mathrm{pr}_B^{\sharp}(b),
  \]
  the affine-open generalization of the \(\top\)-case \(\Gamma(X_B, \top) \cong B\)
  (Lemma~\ref{lem:faithfullyFlat_sectionsTop}). In particular \(s \otimes 1 \mapsto
  \mathrm{cg}^{\sharp}(s)\) and \(1 \otimes b \mapsto \mathrm{pr}_B^{\sharp}(b)\).
\end{definition}
\begin{proof}
  \leanok
  The base-change tensor product \(\Gamma(X_A, U) \otimes_A B\) is the pushout of \(\Gamma(X_A, U)
  \leftarrow A \to B\) in commutative rings. Comparing it with the pushout square of
  Theorem~\ref{thm:isPushout_cgSectionRing}, which has the same span, yields a unique ring
  isomorphism between the two apices; its universal property sends the image of \(\Gamma(X_A, U)\)
  to \(\mathrm{cg}^{\sharp}(s)\) and the image of \(B\) to \(\mathrm{pr}_B^{\sharp}(b)\), hence
  \(s \otimes b\) to their product.
\end{proof}

\begin{definition}[The identification is an isomorphism of base-piece algebras]
  \label{def:pieceAlgEquiv}
  \uses{def:pieceRingEquiv}
  \lean{AlgebraicGeometry.Over.pieceCoverAlgebra, AlgebraicGeometry.Over.pieceTensorAlgEquiv,
    AlgebraicGeometry.Over.pieceEquiv}
  \leanok
  Give the cover-piece ring \(\Gamma(X_B, \mathrm{cg}^{-1}U)\) its \(\Gamma(X_A,
  U)\)-algebra structure by pullback along \(\mathrm{cg}\). Then the identification of
  Definition~\ref{def:pieceRingEquiv} is an isomorphism of \(\Gamma(X_A, U)\)-algebras
  \[
    \Gamma\bigl(X_B, \mathrm{cg}^{-1}U\bigr) \;\cong\; \Gamma(X_A, U) \otimes_A B .
  \]
\end{definition}
\begin{proof}
  \leanok
  The structure map of the \(\Gamma(X_A, U)\)-algebra \(\Gamma(X_B, \mathrm{cg}^{-1}U)\) is
  \(s \mapsto \mathrm{cg}^{\sharp}(s)\), which the identification carries to \(s \otimes 1\)
  (Definition~\ref{def:pieceRingEquiv}); this is the structure map of the base-change algebra
  \(\Gamma(X_A, U) \otimes_A B\). So the ring isomorphism intertwines the two structure maps from
  \(\Gamma(X_A, U)\), hence is an isomorphism of \(\Gamma(X_A, U)\)-algebras.
\end{proof}

\begin{theorem}[Faithful flatness of a saturated affine piece]
  \label{thm:faithfullyFlat_pieceCover}
  \uses{def:pieceAlgEquiv}
  \lean{AlgebraicGeometry.Over.faithfullyFlat_pieceCover}
  \leanok
  Assume \(A \to B\) is faithfully flat. Then for every affine open \(U \subseteq X_A\) the
  structure map \(\Gamma(X_A, U) \to \Gamma(X_B, \mathrm{cg}^{-1}U)\) is faithfully flat.
\end{theorem}
\begin{proof}
  \leanok
  Faithful flatness is stable under base change, so \(\Gamma(X_A, U) \to \Gamma(X_A, U)
  \otimes_A B\) is faithfully flat. Transporting along the isomorphism of \(\Gamma(X_A,
  U)\)-algebras of Definition~\ref{def:pieceAlgEquiv} gives faithful flatness of \(\Gamma(X_A, U)
  \to \Gamma(X_B, \mathrm{cg}^{-1}U)\).
\end{proof}

\begin{theorem}[Restriction naturality of the identification]
  \label{thm:pieceRingEquiv_naturality}
  \uses{def:pieceRingEquiv}
  \lean{AlgebraicGeometry.Over.pieceRingEquiv_naturality}
  \leanok
  Let \(W \le V\) be affine opens of \(X_A\), so \(\mathrm{cg}^{-1}W \le \mathrm{cg}^{-1}V\). The
  identification of Definition~\ref{def:pieceRingEquiv} commutes with restriction: for every \(x
  \in \Gamma(X_A, V) \otimes_A B\),
  \[
    \bigl(\mathrm{cg}^{-1}W \le \mathrm{cg}^{-1}V\bigr)^{*}\bigl(\Phi_V(x)\bigr)
      = \Phi_W\bigl((\rho^{V}_{W} \otimes \id_B)(x)\bigr),
  \]
  where \(\Phi_V, \Phi_W\) are the identifications over \(V, W\) and \(\rho^{V}_{W} \colon
  \Gamma(X_A, V) \to \Gamma(X_A, W)\) is restriction (an \(A\)-algebra homomorphism).
\end{theorem}
\begin{proof}
  \leanok
  Both sides are \(A\)-algebra homomorphisms out of \(\Gamma(X_A, V) \otimes_A B\), so it
  suffices to check them on pure tensors \(s \otimes b\). There the left side restricts
  \(\mathrm{cg}^{\sharp}(s)\cdot \mathrm{pr}_B^{\sharp}(b)\) and the right side is
  \(\mathrm{cg}^{\sharp}(\rho^{V}_{W} s)\cdot \mathrm{pr}_B^{\sharp}(b)\); the two agree because
  restriction of sections commutes with the two pullbacks \(\mathrm{cg}^{\sharp}\) and
  \(\mathrm{pr}_B^{\sharp}\) (pullback of a section, then restrict, equals restrict, then
  pullback).
\end{proof}

\begin{theorem}[Saturated affine opens form a basis]
  \label{thm:exists_isAffineOpen_cg_le}
  \uses{thm:isAffineHom_cg}
  \lean{AlgebraicGeometry.Over.exists_isAffineOpen_cg_le}
  \leanok
  Every neighbourhood \(V\) of a point \(x\) of \(X_A\) contains an affine open \(W\) with \(x \in
  W\) whose preimage \(\mathrm{cg}^{-1}W\) is again affine.
\end{theorem}
\begin{proof}
  \leanok
  The affine opens of \(X_A\) form a basis of its topology, so there is an affine open \(W\) with
  \(x \in W \le V\). Its preimage \(\mathrm{cg}^{-1}W\) is affine because \(\mathrm{cg}\) is an
  affine morphism (Theorem~\ref{thm:isAffineHom_cg}).
\end{proof}

\begin{theorem}[The curve product over a proper curve is separated]
  \label{thm:isSeparated_left}
  \lean{AlgebraicGeometry.Over.isSeparated_left}
  \leanok
  Assume \(C\) is proper over \(k\). Then \(X_A = (C \otimes \Spec A)_{\mathrm{left}}\) is a
  separated scheme.
\end{theorem}
\begin{proof}
  \leanok
  Properness of \(C\) makes its structure morphism separated, and separatedness is stable under
  base change, so the projection \(\mathrm{pr}_A \colon X_A \to \Spec A\) is separated; composing
  with the affine (hence separated) morphisms \(\Spec A \to \Spec k \to \ast\) shows the structure
  morphism of \(X_A\) is separated, i.e.\ \(X_A\) is a separated scheme.
\end{proof}

\begin{theorem}[The overlaps of the affine family are affine]
  \label{thm:isAffineOpen_inf}
  \uses{thm:isSeparated_left}
  \lean{AlgebraicGeometry.Over.isAffineOpen_inf}
  \leanok
  Assume \(C\) is proper over \(k\). Then the affine opens of \(X_A\) are closed under
  intersection: if \(V, W \subseteq X_A\) are affine open, so is \(V \cap W\).
\end{theorem}
\begin{proof}
  \leanok
  A separated scheme (Theorem~\ref{thm:isSeparated_left}) has affine diagonal, and the
  intersection of two affine opens of a scheme with affine diagonal is affine.
\end{proof}

\section{The descent unit of a killed \v Cech class}
\label{sec:kernelDescentUnit}

Let \(\gamma = \mathrm{lam}\) be a unit \v Cech cocycle on a pointed cover \(\mathcal E\) of
\(X_A\) whose base-change class \(\mathrm{cg}^{*}[\mathcal E, \mathrm{lam}]\) is trivial. Fixing
a trivializing \(0\)-cochain of the pulled-back cocycle, this section produces a single global
unit of \(\Spec(B \otimes_A B)\) that records, on the curve product, the coprojection ratio of
that \(0\)-cochain and whose ring avatar is a descent \(1\)-cocycle — the algebraic seed of the
descended line bundle.

\begin{theorem}[The descent unit of a killed class]
  \label{thm:exists_kernelDescentUnit}
  \lean{AlgebraicGeometry.Over.exists_kernelDescentUnit}
  \uses{thm:exists_global_unit_of_compatible, thm:appTop_units_bijective, def:tensorFaces,
    lem:overSpecMap_left_degeneracy, def:tensorMul, def:module_descent_cocycle,
    lem:tensorMul_simplicial}
  \leanok
  Let \(\mathrm{lam}\) be a unit \v Cech cocycle on a pointed cover \(\mathcal E\) of \(X_A\),
  and let \(\beta\) be a unit \(0\)-cochain on a pointed cover \(\mathcal A\) of \(X_B\) refining
  the base-change pullback of \(\mathcal E\), trivializing the pulled-back cocycle: on overlaps,
  \(\beta_v \cdot (\mathrm{cg}^{\sharp}\mathrm{lam})_{vv'} = \beta_{v'}\). Then there is a global
  unit \(w \in \Gamma(\Spec(B \otimes_A B), \top)^{\times}\) such that
  \begin{enumerate}
    \item on the common refinement of the two coprojection pullbacks of \(\mathcal A\), the
      curve-product pullback of \(w\) is the ratio \(u_1^{*}\beta / u_2^{*}\beta\) of the two
      coprojection pullbacks of \(\beta\); and
    \item the \(\Gamma\Spec\)-avatar of \(w\) in \((B \otimes_A B)^{\times}\) is a descent
      \(1\)-cocycle relative to \(A \to B\).
  \end{enumerate}
\end{theorem}
\begin{proof}
  \leanok
  The two coprojection pullbacks \(u_1^{*}\beta, u_2^{*}\beta\) are units over the members of
  the common refinement \(u_1^{*}\mathcal A \cap u_2^{*}\mathcal A\), and their ratio is
  compatible on overlaps: the coboundary hypothesis on \(\beta\), pulled back through the
  coprojection compatibility \(u_1 \circ \mathrm{cg} = u_2 \circ \mathrm{cg}\) of the whiskered
  faces, cancels the two \(\mathrm{lam}\)-factors and leaves the ratios agreeing on double
  overlaps.  By gluing of unit sections (Theorem~\ref{thm:exists_global_unit_of_compatible})
  the ratio family glues to a global section, which by surjectivity of the global-section
  pullback (Theorem~\ref{thm:appTop_units_bijective}) is the curve-product pullback of a global
  unit \(w\) on \(\Spec(B \otimes_A B)\); this is (1).

  For (2), work upstream on \(\Spec(B \otimes_A (B \otimes_A B))\).  Applying the three Amitsur
  cofaces (Definition~\ref{def:tensorFaces}) to the local ratio form of \(w\) and using the
  simplicial coincidences among the coprojections, the \(\beta\)-telescope cancels exactly to
  give the cocycle identity \((f_{23}^{\sharp} w)(f_{12}^{\sharp} w) = f_{13}^{\sharp} w\) of the
  avatar.  The diagonal normalization \(\mu(w) = 1\) is the whiskered degeneracy of the tensor
  diagonal (Definition~\ref{def:tensorMul}, Lemma~\ref{lem:tensorMul_simplicial},
  Lemma~\ref{lem:overSpecMap_left_degeneracy}), under which the two coprojection pullbacks of
  \(\beta\) coincide and their ratio is \(1\).  These are exactly the descent \(1\)-cocycle
  conditions (Definition~\ref{def:module_descent_cocycle}) for the avatar of \(w\).
\end{proof}

\section{The \v Cech representative of a descended Picard class}
\label{sec:descentClassRep}

The descent unit \(w\) of the previous section is the descent datum of an invertible module
\(\mathrm{descended}(w)\) over \(A\).  This section presents the \v Cech class of that module on
\(\Spec A\), together with the trivializing units of its base change to \(\Spec B\), whose
coprojection ratio is exactly \(w\).  Throughout, \(\mathrm{gS} := \Spec(A \to B)_{\mathrm{left}}
\colon \Spec B \to \Spec A\) and \(q_1, q_2 \colon \Spec(B \otimes_A B) \to \Spec B\) are the two
coprojections.

\begin{definition}[The evaluation transform of a section–module tensor]
  \label{def:evalT}
  \lean{AlgebraicGeometry.Over.evalT}
  \leanok
  Let \(N\) be an \(A\)-submodule of \(B\) and \(V \subseteq \Spec A\), \(U \subseteq \Spec B\)
  opens with \(U \subseteq \mathrm{gS}^{-1}V\).  The \emph{evaluation transform} is the
  \(A\)-linear map
  \[
    \mathrm{evalT} \colon \Gamma(\Spec A, V) \otimes_A N \longrightarrow \Gamma(\Spec B, U),
    \qquad s \otimes m \longmapsto (\mathrm{gS}^{*} s) \cdot \bigl(\Gamma\Spec^{-1} m\bigr)
    \big|_{U},
  \]
  the product of the \(\mathrm{gS}\)-pullback of the section \(s\) with the restriction to
  \(U\) of the section-avatar of \(m \in B\).  It is compatible with restriction in both opens.
\end{definition}

\begin{lemma}[The coprojection ratio of an evaluation]
  \label{lem:evalT_ratio}
  \lean{AlgebraicGeometry.Over.evalT_ratio}
  \uses{def:evalT, def:tensorInl_tensorInr}
  \leanok
  Let \(w \in \Gamma(\Spec(B \otimes_A B), \top)^{\times}\) and suppose every \(m \in N\)
  satisfies the descent equation of \(w\): \(1 \otimes m = \Gamma\Spec(w) \cdot (m \otimes 1)\)
  in \(B \otimes_A B\).  Then, over any open \(O\) below both coprojection preimages of \(U\),
  the two coprojection pullbacks of an evaluation differ by the restriction of \(w\):
  \[
    q_2^{*}\bigl(\mathrm{evalT}(x)\bigr) = w|_{O} \cdot q_1^{*}\bigl(\mathrm{evalT}(x)\bigr),
    \qquad x \in \Gamma(\Spec A, V) \otimes_A N.
  \]
\end{lemma}
\begin{proof}
  \leanok
  Both sides are additive in \(x\), so it suffices to treat a pure tensor \(s \otimes m\).  The
  two coprojections send the section factor \(\mathrm{gS}^{*} s\) to the same value, the
  pullback along the common composite \(q_1 \circ \mathrm{gS} = q_2 \circ \mathrm{gS}\); and
  they send the module factor to the two coprojection-avatars \(\Gamma\Spec^{-1}(m \otimes 1)\)
  and \(\Gamma\Spec^{-1}(1 \otimes m)\) (Definition~\ref{def:tensorInl_tensorInr}).  The descent
  equation of \(w\) applied to \(m\) turns the second avatar into \(w\) times the first, and the
  central unit \(w\) factors out, giving the stated ratio.
\end{proof}

\begin{definition}[The \v Cech representative of a descended class]
  \label{def:DescentClassRep}
  \lean{AlgebraicGeometry.Over.DescentClassRep}
  \uses{def:module_descent_cocycle, def:tensorInl_tensorInr}
  \leanok
  Let \(w\) be a global unit of \(\Spec(B \otimes_A B)\) whose avatar is a descent
  \(1\)-cocycle.  A \emph{\v Cech representative} of the descended class consists of a pointed
  cover \(\mathcal C\) of \(\Spec A\), a unit \v Cech cocycle \(d\) on \(\mathcal C\), and a
  family of trivializing units \(\mu_a \in \Gamma(\Spec B, \mathrm{gS}^{-1}\mathcal
  C(a))^{\times}\) of the \(\mathrm{gS}\)-pullback, subject to:
  \begin{enumerate}
    \item (\emph{ratio}) the two coprojection pullbacks of each \(\mu_a\) differ by \(w\):
      \(q_2^{*}\mu_a = w \cdot q_1^{*}\mu_a\) on any sub-open of the double preimage of
      \(\mathcal C(a)\);
    \item (\emph{transition}) on overlaps the \(\mu\)'s differ by the \(\mathrm{gS}\)-pullback
      of the cocycle value: \(\mu_a = \mathrm{gS}^{*} d_{ab} \cdot \mu_b\) on \(\mathrm{gS}^{-1}
      (\mathcal C(a) \cap \mathcal C(b))\).
  \end{enumerate}
\end{definition}

\begin{theorem}[Existence of the \v Cech representative]
  \label{thm:descentClassRep}
  \lean{AlgebraicGeometry.Over.descentClassRep}
  \uses{def:DescentClassRep, lem:trivializingFamily_nonempty, def:module_descended,
    lem:evalT_ratio, thm:isUnit_map_rTensor_generator, def:descentMulEval}
  \leanok
  For every global unit \(w\) of \(\Spec(B \otimes_A B)\) whose avatar is a descent
  \(1\)-cocycle, a \v Cech representative (Definition~\ref{def:DescentClassRep}) of the descended
  class exists.
\end{theorem}
\begin{proof}
  \leanok
  Let \(N := \mathrm{descended}(w)\) be the invertible \(A\)-module descended by the avatar of
  \(w\) (Definition~\ref{def:module_descended}), and pass to its section-ring avatar
  \(\Gamma(\Spec A, \top) \otimes_A N\).  Choose a trivializing family of that invertible module
  (Lemma~\ref{lem:trivializingFamily_nonempty}): a pointed cover \(\mathcal C\) of \(\Spec A\)
  by basic opens \(D(g_a)\) with local trivializations, giving the cover \(\mathcal C\) and its
  cover cocycle \(d\).  On the base change to \(\Spec B\), define \(\mu_a\) as the evaluation of
  the collapsed generator of the \(a\)-trivialization through the surjective evaluation of the
  base-changed descent equivalence (Definition~\ref{def:descentMulEval}); this value is a unit
  by the unit-production principle (Theorem~\ref{thm:isUnit_map_rTensor_generator}).  The ratio
  condition is the coprojection ratio of an evaluation (Lemma~\ref{lem:evalT_ratio}), whose
  hypothesis is the descent equation of \(w\) satisfied by the elements of \(N\).  The
  transition condition follows because the trivializations are compatible across the cover and
  the transition units act on the restricted generators by the cover cocycle \(d\).
\end{proof}

\section{The cobounding units on an affine chart}
\label{sec:kernelCobounding}

The trivializing \(0\)-cochain \(\beta\), the cocycle \(\mathrm{lam}\), and the trivializing
units \(\mu\) of the representative are assembled into a single unit on the base-change pullback
of each chart of \(X_A\), which then descends through \(\mathrm{cg}\).  These descended units are
the cobounding \(0\)-cochain that exhibits \([\mathcal E, \mathrm{lam}]\) as pulled back from
\(\Spec A\).

\begin{theorem}[The cobounding unit at an affine chart]
  \label{thm:exists_kernelCobounding}
  \lean{AlgebraicGeometry.Over.exists_kernelCobounding}
  \uses{def:DescentClassRep, thm:exists_kernelDescentUnit, thm:exists_unitsAppLE_eq,
    lem:units_gluing}
  \leanok
  Keep the data \((\mathcal E, \mathrm{lam}, \beta)\) of the descent unit \(w\)
  (Theorem~\ref{thm:exists_kernelDescentUnit}) and a \v Cech representative \((\mathcal C, d,
  \mu)\) of the descended class (Definition~\ref{def:DescentClassRep}).  For every affine open
  \(U \subseteq X_A\) contained in \(\mathcal E(s)\) and in \(\mathrm{pr}_A^{-1}\mathcal
  C(\mathrm{pr}_A(s))\), there is a unit \(c \in \Gamma(X_A, U)^{\times}\) whose
  \(\mathrm{cg}\)-pullback has, on every small enough sub-open, the glued local form
  \[
    (\mathrm{cg}^{*} c) = \beta_x^{-1} \cdot (\mathrm{cg}^{\sharp}\mathrm{lam}_{\mathrm{cg}(x),s})^{-1}
      \cdot (\mathrm{pr}_B^{\sharp}\mu_{\mathrm{pr}_A(s)})^{-1}.
  \]
\end{theorem}
\begin{proof}
  \leanok
  On each member of the base-change pullback of \(\mathcal E\) meeting \(\mathrm{cg}^{-1}U\),
  form the displayed product of the inverse trivialization \(\beta_x\), the inverse
  \(\mathrm{cg}\)-pullback of the cross-evaluation of \(\mathrm{lam}\), and the inverse
  \(\mathrm{pr}_B\)-pullback of \(\mu\).  These local pieces agree on overlaps: the coboundary
  relation of \(\beta\) against \(\mathrm{lam}\) and the cocycle identity of \(\mathrm{lam}\)
  telescope the \(\beta\)- and \(\mathrm{lam}\)-factors, while the \(\mu\)-factor is independent
  of \(x\).  By gluing of unit sections (Lemma~\ref{lem:units_gluing}) they glue to a unit \(G\)
  on \(\mathrm{cg}^{-1}U\).  Its two coprojection pullbacks to \(C \otimes \Spec(B \otimes_A B)\)
  agree: the local ratio form of the descent unit \(w\)
  (Theorem~\ref{thm:exists_kernelDescentUnit}) and the ratio field of the representative
  (Definition~\ref{def:DescentClassRep}) exactly account for the two coprojection ratios of the
  three factors.  Since \(U\) is affine, \(G\) therefore descends to a unit \(c \in \Gamma(X_A,
  U)^{\times}\) with \(\mathrm{cg}^{*} c = G\) (Theorem~\ref{thm:exists_unitsAppLE_eq}), which is
  the claim.
\end{proof}

\section{The \v Cech kernel lemma and the close of \'etale separatedness}
\label{sec:cechKernelLemma}

The pieces now compose.  The kernel lemma isolates the genuinely fppf content — a \v Cech class
killed by the cover pullback is pulled back from the base — and the class-level reduction and the
plus unfold deliver, from it, the injectivity of the unit of the \'etale plus construction:
Kleiman's separatedness of the relative Picard functor.

\begin{theorem}[The \v Cech kernel lemma]
  \label{thm:exists_cechPic_map_snd_of_ker_whiskerLeft}
  \lean{AlgebraicGeometry.Over.exists_cechPic_map_snd_of_ker_whiskerLeft}
  \uses{thm:exists_kernelDescentUnit, thm:descentClassRep, thm:exists_kernelCobounding,
    thm:appLE_whiskerLeft_injective, lem:pointedCover_affine_refinement, thm:unitsRes_injective,
    cor:cechPic_mk_eq_one}
  \source{kleiman-picard}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced over \(k\), and \(A
  \to B\) faithfully flat.  Then the kernel of the base-change pullback \(\mathrm{cg}^{*} \colon
  \Pic(X_A) \to \Pic(X_B)\) is contained in the image of the projection pullback
  \(\mathrm{pr}_A^{*} \colon \Pic(\Spec A) \to \Pic(X_A)\): every class \(E\) on \(X_A\) with
  \(\mathrm{cg}^{*} E = 1\) is \(\mathrm{pr}_A^{*} M_1\) for some class \(M_1\) on \(\Spec A\).
\end{theorem}
\begin{proof}
  \leanok
  Represent \(E\) by a unit cocycle \(\mathrm{lam}\) on a pointed cover \(\mathcal E\) of
  \(X_A\).  Since \(\mathrm{cg}^{*} E = 1\), the pulled-back cocycle is a coboundary: there is a
  trivializing \(0\)-cochain \(\beta\) on a refinement of \(\mathrm{cg}^{*}\mathcal E\) with
  \(\beta_v \cdot (\mathrm{cg}^{\sharp}\mathrm{lam})_{vv'} = \beta_{v'}\).  Feed \((\mathcal E,
  \mathrm{lam}, \beta)\) to the descent unit (Theorem~\ref{thm:exists_kernelDescentUnit}),
  obtaining a global unit \(w\) whose avatar is a descent \(1\)-cocycle; take a \v Cech
  representative \((\mathcal C, d, \mu)\) of its descended class
  (Theorem~\ref{thm:descentClassRep}).  Refine \(\mathcal E \cap \mathrm{pr}_A^{-1}\mathcal C\)
  to a cover \(\mathcal U\) by affine opens (Lemma~\ref{lem:pointedCover_affine_refinement}); on
  each chart \(U = \mathcal U(s)\), the cobounding unit
  (Theorem~\ref{thm:exists_kernelCobounding}) gives \(c_s \in \Gamma(X_A, U)^{\times}\).

  It remains to check that the \(c_s\) cobound \(\mathrm{lam}\), restricted to \(\mathcal U\),
  against the \(\mathrm{pr}_A\)-pullback of the representing cocycle \(d\); that is,
  \[
    c_s|_{U_s \cap U_t} \cdot \mathrm{pr}_A^{*} d_{\,\mathrm{pr}_A s,\,\mathrm{pr}_A t}
      = \mathrm{lam}_{s t}\big|_{U_s \cap U_t} \cdot c_t|_{U_s \cap U_t}.
  \]
  Both sides pull back injectively along \(\mathrm{cg}\)
  (Theorem~\ref{thm:appLE_whiskerLeft_injective}); after pullback, the glued local forms of
  \(c_s, c_t\), the \(\mu\)-transition of the representative, and the cocycle identity of
  \(\mathrm{lam}\) telescope to the required identity.  Hence \(\mathrm{lam}\) and
  \(\mathrm{pr}_A^{*} d\) are cohomologous on \(\mathcal U\), so \([\mathcal U, \mathrm{lam}] =
  \mathrm{pr}_A^{*}[\mathcal C, d]\) by refinement injectivity in degree one
  (Theorem~\ref{thm:unitsRes_injective}, Corollary~\ref{cor:cechPic_mk_eq_one}); that is, \(E =
  \mathrm{pr}_A^{*} M_1\) with \(M_1 = [\mathcal C, d]\).  This is the descent-datum step of
  Kleiman's separatedness argument in its \v Cech incarnation: the trivialization \(\beta\)
  descends the class from the faithfully flat cover to the base.
\end{proof}

\begin{theorem}[The class-level reduction]
  \label{thm:exists_cechPic_map_snd_eq_of_ker}
  \lean{AlgebraicGeometry.Over.exists_cechPic_map_snd_eq_of_ker}
  \uses{thm:exists_coherentCechWitness, thm:isDescentCocycle_assemblyUnit,
    thm:mapAlgebra_picClass_assemblyUnit, thm:cechPicEquivPic, thm:cechPic_toPic_injective,
    thm:cechPic_toPic_map, lem:snd_left_naturality, def:module_picClass}
  \source{kleiman-picard}
  \leanok
  Assume the kernel property of \(\mathrm{cg}^{*}\) (Theorem~\ref{thm:exists_cechPic_map_snd_of_ker_whiskerLeft}).
  Let \(L\) be a \v Cech Picard class on \(X_A\) and \(N_0\) a class on \(\Spec B\) with
  \(\mathrm{pr}_B^{*} N_0 = \mathrm{cg}^{*} L\).  Then \(L\) is pulled back from the base:
  \(L = \mathrm{pr}_A^{*} M\) for some class \(M\) on \(\Spec A\).
\end{theorem}
\begin{proof}
  \leanok
  From the hypothesis \(\mathrm{pr}_B^{*} N_0 = \mathrm{cg}^{*} L\), the coherent \v Cech witness
  (Theorem~\ref{thm:exists_coherentCechWitness}) provides an Amitsur-coherent trivialization of
  the two coprojection pullbacks of \(N_0\), and the assembly of the previous chapter builds from
  it a composite \(A\)-descent unit whose avatar is a descent \(1\)-cocycle
  (Theorem~\ref{thm:isDescentCocycle_assemblyUnit}).  Let \(M\) be the \v Cech class on \(\Spec
  A\) corresponding, through the \v Cech–Picard dictionary
  (Theorem~\ref{thm:cechPicEquivPic}), to the Picard class of the descended module
  (Definition~\ref{def:module_picClass}) of that composite unit.  By the class equation of the
  assembly (Theorem~\ref{thm:mapAlgebra_picClass_assemblyUnit}) and naturality of the dictionary
  in the affine scheme (Theorem~\ref{thm:cechPic_toPic_map}), the base change \(\mathrm{gS}^{*}
  M\) has the same descent homomorphism image as \(N_0\); since that homomorphism is injective
  (Theorem~\ref{thm:cechPic_toPic_injective}), \(\mathrm{gS}^{*} M = N_0\) on the nose.  Then,
  using the projection base square (Lemma~\ref{lem:snd_left_naturality}),
  \[
    \mathrm{cg}^{*}\bigl(\mathrm{pr}_A^{*} M\bigr) = \mathrm{pr}_B^{*}\bigl(\mathrm{gS}^{*} M\bigr)
      = \mathrm{pr}_B^{*} N_0 = \mathrm{cg}^{*} L ,
  \]
  so \(L \cdot (\mathrm{pr}_A^{*} M)^{-1}\) is killed by \(\mathrm{cg}^{*}\).  The kernel
  property yields \(M_1\) with \(\mathrm{pr}_A^{*} M_1 = L \cdot (\mathrm{pr}_A^{*} M)^{-1}\),
  whence \(L = \mathrm{pr}_A^{*}(M \cdot M_1)\).
\end{proof}

\begin{theorem}[The plus unfold of \'etale separatedness]
  \label{thm:PicEtAff_unit_injective_of_ker}
  \lean{AlgebraicGeometry.PicEtAff.unit_injective_of_ker}
  \uses{def:PicEtAff_unit, thm:PicEtAff_mk_eq_mk_iff, def:PicEtAff_one,
    thm:exists_cechPic_map_snd_eq_of_ker, def:relPicAlgMap, def:descentClasses}
  \leanok
  Fix \(A\).  Suppose the kernel property of the base-change pullback holds for every tower \(A
  \to B\) with \(A \to B\) faithfully flat.  Then the unit \(\eta_A \colon \mathrm{relPic}(C,A)
  \to \mathrm{PicEtAff}(C,A)\) of the plus construction (Definition~\ref{def:PicEtAff_unit}) is
  injective.
\end{theorem}
\begin{proof}
  \leanok
  As \(\eta_A\) is a group homomorphism it suffices to show its kernel is trivial.  Let \(x =
  [\Spec A, L] \in \mathrm{relPic}(C,A)\) with \(\eta_A(x) = 1\).  Unwinding the plus-class
  equality \([\mathrm{self}(A), \iota^{*}x] = 1\) through the presentation criterion
  (Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff}) and the essential uniqueness of \(A\)-algebra maps
  out of \(A\), the datum reduces to a single presented \'etale cover \(A \to B_G\): the base
  change \((\mathrm{ofId}\ A\ B_G)^{*}L\) lies in the descent-trivial subgroup of
  \(\mathrm{relPic}(C,B_G)\) (Definition~\ref{def:relPicAlgMap},
  Definition~\ref{def:descentClasses}).  Concretely there is a class \(N_0\) on \(\Spec B_G\)
  with \(\mathrm{pr}_{B_G}^{*} N_0 = \mathrm{cg}^{*} L\) — the hypothesis of the reduction.  Since
  a presented \'etale cover is in particular faithfully flat, the reduction
  (Theorem~\ref{thm:exists_cechPic_map_snd_eq_of_ker}) pulls \(L\) back from the base, \(L =
  \mathrm{pr}_A^{*} M\); that is exactly \(x = 1\) in \(\mathrm{relPic}(C,A)\), using the
  normalization of the unit at the identity (Definition~\ref{def:PicEtAff_one}).
\end{proof}

\begin{theorem}[\'Etale separatedness of the relative Picard functor]
  \label{thm:PicEtAff_unit_injective}
  \lean{AlgebraicGeometry.PicEtAff.unit_injective}
  \uses{thm:PicEtAff_unit_injective_of_ker, thm:exists_cechPic_map_snd_of_ker_whiskerLeft}
  \source{kleiman-picard}
  \leanok
  Let \(C\) be a curve over \(k\) that is proper, geometrically irreducible and geometrically
  reduced, and let \(A\) be any \(k\)-algebra.  Then the unit \(\eta_A \colon
  \mathrm{relPic}(C,A) \to \mathrm{PicEtAff}(C,A)\) of the one-step \'etale plus construction is
  injective.  Equivalently, the relative Picard functor of \(C\) is separated for the \'etale
  topology — the separatedness half of Kleiman, \emph{The Picard Scheme}, Theorem 2.5(1).
\end{theorem}
\begin{proof}
  \leanok
  The kernel property of the base-change pullback holds for every faithfully flat tower \(A \to
  B\) by the \v Cech kernel lemma
  (Theorem~\ref{thm:exists_cechPic_map_snd_of_ker_whiskerLeft}).  Feeding it to the plus unfold
  (Theorem~\ref{thm:PicEtAff_unit_injective_of_ker}) gives the injectivity of \(\eta_A\).  This
  is exactly Part 1 of Kleiman's comparison theorem in the \'etale case: the natural map
  \(\Pic_{X/S} \hookrightarrow \Pic_{(X/S)\mathrm{\acute et}}\) is injective, so a single
  \'etale plus computes the sheafification and \(\mathrm{PicEtAff}\) is separated on the \'etale
  site of affines.
\end{proof}


\section{Unit sections across an open immersion}

Throughout this section \(w \colon Z \to Y\) is an open immersion of schemes. Over an open
\(V \subseteq Y\) contained in the image of \(w\), pullback of sections along \(w\) is
bijective; this transports \emph{unit} sections between \(Y\) and \(Z\) and is the substrate
for decomposing \v Cech Picard classes along clopen partitions.

\begin{lemma}[Units over an empty open form a trivial group]
  \label{lem:subsingleton_units_empty}
  \lean{AlgebraicGeometry.Scheme.subsingleton_units_of_le_bot}
  \leanok
  For a scheme \(X\) and an open \(O \subseteq X\) with \(O \subseteq \emptyset\) (that is,
  \(O = \emptyset\)), the unit group \(\Gamma(X, O)^{\times}\) is trivial (a subsingleton).
\end{lemma}
\begin{proof}
  \leanok
  Since \(O = \emptyset\), the ring \(\Gamma(X, O)\) is the zero ring, in which \(0 = 1\) is the
  only element; hence its group of units has a single element.
\end{proof}

\begin{lemma}[Sections pull back isomorphically over an open inside the image]
  \label{lem:isIso_appLE_of_le_opensRange}
  \lean{AlgebraicGeometry.Scheme.Hom.isIso_appLE_of_le_opensRange}
  \leanok
  Let \(V \subseteq Y\) be an open with \(V \subseteq \operatorname{range}(w)\). Then pullback of
  sections along \(w\) is an isomorphism of rings
  \(\Gamma(Y, V) \xrightarrow{\ \sim\ } \Gamma(Z, w^{-1}V)\).
\end{lemma}
\begin{proof}
  \leanok
  An open immersion \(w\) identifies \(Z\) with the open subscheme \(\operatorname{range}(w)\) of
  \(Y\); for an open \(V\) contained in that image the comparison map on sections is the
  restriction isomorphism of the structure sheaf between \(V\) and its homeomorphic preimage
  \(w^{-1}V\). Hence pullback of sections over \(V\) is an isomorphism of rings.
\end{proof}

\begin{definition}[Transport of unit sections across an open immersion]
  \label{def:unitsPreimageEquiv}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsPreimageEquiv}
  \uses{lem:isIso_appLE_of_le_opensRange}
  \leanok
  For an open \(V \subseteq Y\) with \(V \subseteq \operatorname{range}(w)\), the isomorphism of
  unit groups
  \[
    \Gamma(Y, V)^{\times} \xrightarrow{\ \sim\ } \Gamma(Z, w^{-1}V)^{\times}
  \]
  induced by pullback of sections along \(w\).
\end{definition}
\begin{proof}
  \leanok
  Pullback of sections along \(w\) is an isomorphism of rings over \(V\)
  (Lemma~\ref{lem:isIso_appLE_of_le_opensRange}); an isomorphism of rings restricts to an
  isomorphism of their groups of units.
\end{proof}

\section{Decomposition of the \v Cech Picard group along a clopen partition}

A \emph{clopen partition} of a scheme \(Y\) is a family of open immersions
\(w_i \colon Z_i \to Y\), \(i \in \iota\), whose ranges are pairwise disjoint
(\(\operatorname{range}(w_i) \cap \operatorname{range}(w_j) = \emptyset\) for \(i \ne j\)) and
cover \(Y\); each range is then open with open complement. This section proves that the \v Cech
Picard group of \(Y\) decomposes along such a partition: separation along an arbitrary clopen
partition, and gluing along a finite one. Throughout, \(\Pic(Y)\) is the definitional \v Cech
Picard group recalled in Section~\ref{sec:etaleSeparatedness}, with pullback
\(w^{*} \colon \Pic(Y) \to \Pic(Z)\) along a morphism \(w \colon Z \to Y\).

\begin{theorem}[Separation of \v Cech Picard classes along a clopen partition]
  \label{thm:cechPic_clopen_separation}
  \lean{AlgebraicGeometry.Scheme.CechPic.eq_of_map_eq_of_clopen}
  \uses{def:unitsPreimageEquiv, lem:subsingleton_units_empty, cor:cechPic_mk_injective}
  \leanok
  Let \((w_i)_{i \in \iota}\) be a clopen partition of \(Y\). Two \v Cech Picard classes
  \(L, L' \in \Pic(Y)\) with \(w_i^{*} L = w_i^{*} L'\) for every \(i\) are equal.
\end{theorem}
\begin{proof}
  \leanok
  \uses{lem:units_separation, lem:units_gluing}
  Choose for each point \(y \in Y\) an index \(p(y)\) with \(y \in \operatorname{range}(w_{p(y)})\).
  Represent \(L = [\mathcal U_1, a_1]\) and \(L' = [\mathcal U_2, a_2]\) and pass to the common
  adapted pointed cover \(\mathcal V(y) := \mathcal U_1(y) \cap \mathcal U_2(y) \cap
  \operatorname{range}(w_{p(y)})\), so that \(\mathcal V(y) \subseteq \operatorname{range}(w_{p(y)})\)
  for every \(y\); it suffices to show the ratio cocycle \(\gamma\) representing \(L/L'\) on
  \(\mathcal V\) is a coboundary.

  \emph{Triviality on each piece.} Fix \(i\). Since \(w_i^{*}L = w_i^{*}L'\), the pullback classes
  \(w_i^{*}[\mathcal V, a_1|_{\mathcal V}]\) and \(w_i^{*}[\mathcal V, a_2|_{\mathcal V}]\) are
  represented on the pulled-back pointed cover \(\mathcal V^{(i)} := w_i^{-1}\mathcal V\) by the
  pulled-back cocycles, and they agree in \(\Pic(Z_i)\); by refinement injectivity
  (Corollary~\ref{cor:cechPic_mk_injective}) already the pulled-back ratio cocycle
  \(w_i^{\sharp}\gamma\) is a coboundary on \(\mathcal V^{(i)}\): there are units
  \(\alpha^{(i)}_z \in \struct{Z_i}(\mathcal V^{(i)}(z))^{\times}\) with
  \(\alpha^{(i)}_z \cdot (w_i^{\sharp}\gamma)_{zz'} = \alpha^{(i)}_{z'}\) on the overlaps.

  \emph{Gluing the piece coboundaries.} For each \(y \in Y\), let \(z_0\) be the unique point of
  \(Z_{p(y)}\) over \(y\) (an open immersion is injective on points), and set
  \(\beta_y := \Phi^{-1}\bigl(\alpha^{(p(y))}_{z_0}|_{w_{p(y)}^{-1}\mathcal V(y)}\bigr) \in
  \Gamma(Y, \mathcal V(y))^{\times}\), where \(\Phi\) is the unit transport of
  Definition~\ref{def:unitsPreimageEquiv} across \(w_{p(y)}\) (applicable since
  \(\mathcal V(y) \subseteq \operatorname{range}(w_{p(y)})\)). The choice of index is forced: if
  \(y \in \operatorname{range}(w_i)\) too, then \(y \in \operatorname{range}(w_i) \cap
  \operatorname{range}(w_{p(y)})\), which is empty unless \(i = p(y)\); and the choice of preimage
  point is forced by injectivity.

  \emph{\(\beta\) cobounds \(\gamma\).} Fix \(y, y'\). If \(p(y') = p(y)\), both members lie in the
  single piece \(Z_{p(y)}\); the coboundary relation for \(\alpha^{(p(y))}\) pulls back injectively
  through \(w_{p(y)}\) on the overlap \(\mathcal V(y) \cap \mathcal V(y') \subseteq
  \operatorname{range}(w_{p(y)})\) (pullback of unit sections is injective on opens inside the
  range, Definition~\ref{def:unitsPreimageEquiv}), yielding
  \(\beta_y \cdot \gamma_{yy'} = \beta_{y'}\) there. If \(p(y') \ne p(y)\), then
  \(\mathcal V(y) \cap \mathcal V(y') \subseteq \operatorname{range}(w_{p(y)}) \cap
  \operatorname{range}(w_{p(y')}) = \emptyset\), so the units over the overlap form a trivial group
  (Lemma~\ref{lem:subsingleton_units_empty}) and the relation holds vacuously. Assembling over the
  cover of \(\mathcal V(y) \cap \mathcal V(y')\) by these two cases and separating
  (Lemma~\ref{lem:units_separation}; gluing across pieces uses Lemma~\ref{lem:units_gluing} in the
  construction of \(\beta\)), \(\gamma = \delta\beta\) is a coboundary, so \(L/L' = 1\), i.e.
  \(L = L'\).
\end{proof}

\begin{theorem}[The one-piece extension across a clopen decomposition]
  \label{thm:cechPic_extendClass}
  \lean{AlgebraicGeometry.Scheme.CechPic.extendClass,
    AlgebraicGeometry.Scheme.CechPic.map_extendClass,
    AlgebraicGeometry.Scheme.CechPic.map_extendClass_of_le_compl}
  \uses{def:unitsPreimageEquiv, lem:subsingleton_units_empty}
  \leanok
  Let \(w \colon Z \to Y\) be an open immersion whose range is complemented by an open
  \(\Omega' \subseteq Y\): \(\operatorname{range}(w) \cap \Omega' = \emptyset\) and
  \(\operatorname{range}(w) \cup \Omega' = Y\). For every \(L_0 \in \Pic(Z)\) there is a class
  \(\widetilde L \in \Pic(Y)\) with
  \[
    w^{*}\widetilde L = L_0, \qquad v^{*}\widetilde L = 1 \text{ for every } v \colon W \to Y
    \text{ with image contained in } \Omega'.
  \]
\end{theorem}
\begin{proof}
  \leanok
  Represent \(L_0 = [\mathcal U_0, \gamma_0]\) by a unit cocycle on a pointed cover of \(Z\). Build
  the \emph{extension cover} \(\mathcal E\) of \(Y\): at a point \(y \in \operatorname{range}(w)\)
  take the \(w\)-image of the member of \(\mathcal U_0\) at the unique preimage of \(y\); at
  \(y \notin \operatorname{range}(w)\) take \(\Omega'\) (a legitimate pointed cover, since
  \(\operatorname{range}(w) \cup \Omega' = Y\)). Define its pair values: on range--range overlaps
  the transported cocycle value \(\Phi^{-1}\bigl((\gamma_0)_{\cdot\cdot}\bigr)\) of
  Definition~\ref{def:unitsPreimageEquiv} across \(w\), and \(1\) whenever either argument lies off
  the range. These satisfy the cocycle identity: on triple overlaps of range members it is the
  transported cocycle identity of \(\gamma_0\); every other triple overlap meets a range member and
  a non-range member, hence lies in \(\operatorname{range}(w) \cap \Omega' = \emptyset\) and carries
  only the trivial unit (Lemma~\ref{lem:subsingleton_units_empty}), so the identity degenerates.
  This produces \(\widetilde L := [\mathcal E, \text{extension cocycle}] \in \Pic(Y)\).

  \emph{Restriction on the piece.} The given cover \(\mathcal U_0\) refines the pullback
  \(w^{-1}\mathcal E\) (the preimage of the image of a member is that member), and along this
  refinement the pulled-back extension cocycle restricts to \(\gamma_0\) (its range--range values
  are the transported \(\gamma_0\)). Hence \(w^{*}\widetilde L = [\mathcal U_0, \gamma_0] = L_0\).

  \emph{Restriction off the piece.} For \(v \colon W \to Y\) with image in \(\Omega'\), every point
  \(v(x)\) lies off \(\operatorname{range}(w)\) (else it would lie in
  \(\operatorname{range}(w) \cap \Omega' = \emptyset\)); so every pulled-back pair value is \(1\),
  the pulled-back cocycle is trivial, and \(v^{*}\widetilde L = 1\).
\end{proof}

\begin{theorem}[Gluing of \v Cech Picard classes along a finite clopen partition]
  \label{thm:cechPic_clopen_gluing}
  \lean{AlgebraicGeometry.Scheme.CechPic.exists_map_eq_of_clopen}
  \uses{thm:cechPic_extendClass}
  \leanok
  Let \((w_i)_{i \in \iota}\) be a \emph{finite} clopen partition of \(Y\). Every family
  \((L_i)_{i \in \iota}\) with \(L_i \in \Pic(Z_i)\) is the family of restrictions of a single
  class \(M \in \Pic(Y)\): \(w_i^{*} M = L_i\) for all \(i\).
\end{theorem}
\begin{proof}
  \leanok
  For each \(i\), set \(\Omega'_i := \bigcup_{j \ne i} \operatorname{range}(w_j)\). By pairwise
  disjointness \(\operatorname{range}(w_i) \cap \Omega'_i = \emptyset\), and since the ranges cover
  \(Y\), \(\operatorname{range}(w_i) \cup \Omega'_i = Y\). Let \(M_i \in \Pic(Y)\) be the one-piece
  extension of \(L_i\) across \((w_i, \Omega'_i)\) (Theorem~\ref{thm:cechPic_extendClass}). Put
  \(M := \prod_{i} M_i\) (finite product). For each \(i\), pullback along \(w_i\) is a homomorphism,
  so \(w_i^{*} M = \prod_j w_i^{*} M_j\). The factor \(j = i\) is \(w_i^{*} M_i = L_i\); every factor
  \(j \ne i\) is \(1\), because \(\operatorname{range}(w_i) \subseteq \Omega'_j\) means \(w_i\) has
  image in the complement of the \(j\)-th piece, so \(w_i^{*}M_j = 1\)
  (Theorem~\ref{thm:cechPic_extendClass}). Hence \(w_i^{*} M = L_i\).
\end{proof}

\section{The relative Picard group of a finite product of test algebras}

Fix a field \(k\) and a curve \(C\) over \(k\). For a finite family \((B_i)_{i \in \iota}\) of
commutative \(k\)-algebras with product \(P := \prod_i B_i\), the spectrum of \(P\) is the disjoint
union of the spectra of the factors, clopen-partitioned by the basic opens of the coordinate
idempotents; base-changing along the curve, the whiskered coordinate projections clopen-partition
the curve-product. Through the clopen decomposition of the previous section this identifies the
relative Picard group of the product test with the product of the relative Picard groups of the
factors. Write \(e_i \in P\) for the coordinate idempotent (\(1\) in slot \(i\), \(0\) elsewhere)
and \(\pi_i \colon P \to B_i\) for the projection.

\begin{lemma}[Range of a whiskered open immersion]
  \label{lem:range_whiskerLeft}
  \lean{AlgebraicGeometry.Over.range_whiskerLeft}
  \uses{thm:isPullback_whiskerLeft_snd}
  \leanok
  Let \(g \colon T' \to T\) be a morphism of test objects with \(g_{\mathrm{left}}\) an open
  immersion. Then the whiskered morphism \((C \lhd g)_{\mathrm{left}}\) is an open immersion, and
  its range is the preimage under the second projection \(\mathrm{pr} \colon (C \otimes
  T)_{\mathrm{left}} \to T_{\mathrm{left}}\) of the range of \(g_{\mathrm{left}}\):
  \[
    \operatorname{range}\bigl((C \lhd g)_{\mathrm{left}}\bigr) = \mathrm{pr}^{-1}\bigl(
    \operatorname{range}(g_{\mathrm{left}})\bigr).
  \]
\end{lemma}
\begin{proof}
  \leanok
  The whiskering square with horizontal legs \((C \lhd g)_{\mathrm{left}}\), \(g_{\mathrm{left}}\)
  and vertical legs the two second projections is a pullback of schemes
  (Theorem~\ref{thm:isPullback_whiskerLeft_snd}). Open immersions are stable under base change, so
  \((C \lhd g)_{\mathrm{left}}\), being the base change of \(g_{\mathrm{left}}\) along
  \(\mathrm{pr}\), is an open immersion; and the range of the base change of an open immersion along
  \(\mathrm{pr}\) is the \(\mathrm{pr}\)-preimage of its range.
\end{proof}

\begin{lemma}[A factor is the localization away from the coordinate idempotent]
  \label{lem:isLocalization_away_piFactor}
  \lean{AlgebraicGeometry.isLocalization_away_piFactor}
  \leanok
  For a finite product \(P = \prod_j B_j\) and an index \(i\), the projection \(\pi_i \colon P \to
  B_i\) exhibits \(B_i\) as the localization of \(P\) away from the coordinate idempotent \(e_i\).
\end{lemma}
\begin{proof}
  \leanok
  The element \(e_i\) is idempotent, \(e_i^2 = e_i\). Two elements \(x, y \in P\) have the same
  image in \(B_i\) iff they agree in slot \(i\), iff \(e_i x = e_i y\) (multiplication by \(e_i\)
  zeroes every other slot). And every \(b \in B_i\) is the image of \(\mathrm{single}_i(b) \in P\).
  By the criterion for a localization away from an idempotent, \(B_i = P[e_i^{-1}]\).
\end{proof}

\begin{lemma}[The coordinate projections clopen-partition the spectrum of a product]
  \label{lem:opensRange_eval_clopen}
  \lean{AlgebraicGeometry.isOpenImmersion_overSpecMap_evalAlgHom,
    AlgebraicGeometry.opensRange_overSpecMap_evalAlgHom_disjoint,
    AlgebraicGeometry.exists_mem_opensRange_overSpecMap_evalAlgHom}
  \uses{lem:isLocalization_away_piFactor, def:overSpecMap}
  \leanok
  The morphisms \(\Spec \pi_i \colon \Spec B_i \to \Spec P\) (for the finite family
  \((B_i)_{i \in \iota}\)) are open immersions with pairwise disjoint ranges covering \(\Spec P\):
  the range of \(\Spec \pi_i\) is the basic open \(D(e_i)\), and \(D(e_i) \cap D(e_j) = \emptyset\)
  for \(i \ne j\) while \(\bigcup_i D(e_i) = \Spec P\).
\end{lemma}
\begin{proof}
  \leanok
  By Lemma~\ref{lem:isLocalization_away_piFactor}, \(\pi_i\) realizes \(B_i\) as a localization of
  \(P\) away from \(e_i\), so \(\Spec \pi_i\) is an open immersion with range the basic open
  \(D(e_i)\) (the spectrum of a localization away from an element is that element's basic open). For
  \(i \ne j\), \(e_i e_j = 0\), whence \(D(e_i) \cap D(e_j) = D(e_i e_j) = D(0) = \emptyset\).
  Finally \(\sum_i e_i = 1\); since \(\iota\) is finite, no prime of \(P\) contains all the \(e_i\)
  (it would then contain \(1\)), so every prime lies in some \(D(e_i)\), i.e. the ranges cover.
\end{proof}

\begin{theorem}[Separation of relative Picard classes over a finite product]
  \label{thm:relPic_pi_separation}
  \lean{AlgebraicGeometry.relPic.eq_of_pi_proj_eq}
  \uses{thm:cechPic_clopen_separation, thm:cechPic_clopen_gluing, lem:range_whiskerLeft,
    lem:opensRange_eval_clopen, def:relPicAlgMap, lem:snd_left_naturality}
  \leanok
  For a finite family \((B_i)_{i \in \iota}\) with product \(P\), two relative Picard classes
  \(\zeta, \zeta' \in \mathrm{relPic}(C, P)\) with \(\pi_i^{*}\zeta = \pi_i^{*}\zeta'\) in
  \(\mathrm{relPic}(C, B_i)\) for every \(i\) are equal.
\end{theorem}
\begin{proof}
  \leanok
  Represent \(\zeta, \zeta'\) by \v Cech Picard classes \(L, L'\) on the curve-product
  \((C \otimes \Spec P)_{\mathrm{left}}\) (a relative Picard class is a class on the curve-product
  modulo those pulled back from the base along \(\mathrm{pr}\)); restriction along \(\pi_i\)
  corresponds to \v Cech pullback of the underlying class along the whiskered projection
  \((C \lhd \Spec \pi_i)_{\mathrm{left}}\). The hypotheses give, for each \(i\), a class \(N_i\) on
  \(\Spec B_i\) with \(\mathrm{pr}^{*}N_i = (C \lhd \Spec\pi_i)_{\mathrm{left}}^{*}(L/L')\) (the
  restriction of \(L/L'\) to the \(i\)-th piece is pulled back from the base). Glue the \(N_i\) to a
  single class \(M\) on \(\Spec P\) by the clopen gluing (Theorem~\ref{thm:cechPic_clopen_gluing})
  for the coordinate partition of \(\Spec P\) (Lemma~\ref{lem:opensRange_eval_clopen}), so that
  \(\Spec\pi_i^{*} M = N_i\).

  It remains to show \(\mathrm{pr}^{*} M = L/L'\) on the curve-product; then \(\zeta = \zeta'\). The
  whiskered coordinate projections \((C \lhd \Spec\pi_i)_{\mathrm{left}}\) form a clopen partition
  of \((C \otimes \Spec P)_{\mathrm{left}}\): their ranges are the \(\mathrm{pr}\)-preimages of the
  ranges of the coordinate projections (Lemma~\ref{lem:range_whiskerLeft}), which partition
  \(\Spec P\) (Lemma~\ref{lem:opensRange_eval_clopen}). By separation along this partition
  (Theorem~\ref{thm:cechPic_clopen_separation}) it suffices to check equal pullback along each
  whiskered projection. Using the base square of the projection
  (Lemma~\ref{lem:snd_left_naturality}) and functoriality of \v Cech pullback,
  \[
    (C \lhd \Spec\pi_i)_{\mathrm{left}}^{*}(\mathrm{pr}^{*} M)
      = \mathrm{pr}^{*}\bigl(\Spec\pi_i^{*} M\bigr)
      = \mathrm{pr}^{*} N_i
      = (C \lhd \Spec\pi_i)_{\mathrm{left}}^{*}(L/L'),
  \]
  as required.
\end{proof}

\begin{theorem}[Gluing of relative Picard classes over a finite product]
  \label{thm:relPic_pi_gluing}
  \lean{AlgebraicGeometry.relPic.exists_pi_lift}
  \uses{thm:cechPic_clopen_gluing, lem:range_whiskerLeft, lem:opensRange_eval_clopen,
    def:relPicAlgMap}
  \leanok
  For a finite family \((B_i)_{i \in \iota}\) with product \(P\), every family
  \((\xi_i)_{i \in \iota}\) with \(\xi_i \in \mathrm{relPic}(C, B_i)\) is the family of restrictions
  of a class \(\zeta \in \mathrm{relPic}(C, P)\): \(\pi_i^{*}\zeta = \xi_i\) for all \(i\).
\end{theorem}
\begin{proof}
  \leanok
  Represent each \(\xi_i\) by a \v Cech Picard class \(L_i\) on the curve-product
  \((C \otimes \Spec B_i)_{\mathrm{left}}\). The whiskered coordinate projections
  \((C \lhd \Spec\pi_i)_{\mathrm{left}}\) form a clopen partition of
  \((C \otimes \Spec P)_{\mathrm{left}}\), their ranges being the \(\mathrm{pr}\)-preimages
  (Lemma~\ref{lem:range_whiskerLeft}) of the coordinate ranges that partition \(\Spec P\)
  (Lemma~\ref{lem:opensRange_eval_clopen}). By the clopen gluing
  (Theorem~\ref{thm:cechPic_clopen_gluing}) there is a class \(M\) on the curve-product with
  \((C \lhd \Spec\pi_i)_{\mathrm{left}}^{*} M = L_i\) for all \(i\). Let \(\zeta\) be the relative
  Picard class of \(M\). Then \(\pi_i^{*}\zeta\) is the relative Picard class of
  \((C \lhd \Spec\pi_i)_{\mathrm{left}}^{*} M = L_i\), which is \(\xi_i\).
\end{proof}

\section{Zariski separation of the \'etale plus construction}

Throughout, \(k\) is a field and \(C\) is a curve over \(k\) (proper, geometrically irreducible,
geometrically reduced). This section proves that the affine \'etale plus \(\mathrm{PicEtAff}(C, -)\)
is a separated presheaf for the Zariski topology of affine tests: two plus classes over \(A\)
agreeing on a finite covering family of localizations agree. The argument is instance-free of
\'etale separatedness; it consumes only the product decomposition of the relative Picard group.

\begin{theorem}[Unfolding an equality of restricted plus classes]
  \label{thm:PicEtAff_exists_relPicAlgMap_eq}
  \lean{AlgebraicGeometry.PicEtAff.exists_relPicAlgMap_eq_of_mapAlg_eq}
  \uses{thm:PicEtAff_mk_eq_mk_iff, def:PicEtAff_map, def:etale_cover_baseChange,
    def:etale_cover_baseChangeInclude, def:relPicAlgMap, lem:relPicAlgMap_functor}
  \leanok
  Let \(\varphi_1 \colon A_1 \to R\) and \(\varphi_2 \colon A_2 \to R\) be homomorphisms of
  \(k\)-algebras, \(E_1\) a presented \'etale cover of \(A_1\) and \(E_2\) of \(A_2\), and
  \(\xi_1 \in \mathrm{Desc}(C, E_1)\), \(\xi_2 \in \mathrm{Desc}(C, E_2)\). If \(\varphi_1^{*}
  [E_1, \xi_1] = \varphi_2^{*}[E_2, \xi_2]\) in \(\mathrm{PicEtAff}(C, R)\), then there are a
  presented \'etale cover \(H\) of \(R\) and homomorphisms of \(k\)-algebras \(m_1 \colon B_{E_1}
  \to B_H\), \(m_2 \colon B_{E_2} \to B_H\), semilinear over \(\varphi_1, \varphi_2\)
  (\(m_1 \circ \iota_{E_1} = \iota_H \circ \varphi_1\) and \(m_2 \circ \iota_{E_2} = \iota_H \circ
  \varphi_2\)), with \(m_1^{*}\xi_1 = m_2^{*}\xi_2\) in \(\mathrm{relPic}(C, B_H)\).
\end{theorem}
\begin{proof}
  \leanok
  Regard \(R\) as an \(A_1\)- and \(A_2\)-algebra through \(\varphi_1, \varphi_2\). Then
  \(\varphi_i^{*}[E_i, \xi_i] = [(E_i)_R, \kappa_{E_i}^{*}\xi_i]\) is the restriction along the base
  extension \(A_i \to R\) of the plus class (Definition~\ref{def:PicEtAff_map}), with \((E_i)_R\)
  the base change of \(E_i\) (Definition~\ref{def:etale_cover_baseChange}) and \(\kappa_{E_i}\) its
  canonical inclusion (Definition~\ref{def:etale_cover_baseChangeInclude}). The hypothesis
  \([(E_1)_R, \kappa^{*}\xi_1] = [(E_2)_R, \kappa^{*}\xi_2]\) unfolds by the presentation criterion
  (Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff}): there are a presented \'etale cover \(H\) of \(R\) and
  homomorphisms of \(R\)-algebras \(r_i \colon B_{(E_i)_R} \to B_H\) with
  \((r_1)_{*}(\kappa^{*}\xi_1) = (r_2)_{*}(\kappa^{*}\xi_2)\). Set \(m_i := r_i \circ \kappa_{E_i}
  \colon B_{E_i} \to B_H\). Since \(\kappa_{E_i}\) and \(r_i\) both cover the base inclusions,
  \(m_i \circ \iota_{E_i} = \iota_H \circ \varphi_i\); and by functoriality of restriction
  (Lemma~\ref{lem:relPicAlgMap_functor}), \(m_i^{*}\xi_i = r_i^{*}(\kappa_{E_i}^{*}\xi_i)\), so the
  refinement equality gives \(m_1^{*}\xi_1 = m_2^{*}\xi_2\).
\end{proof}

\begin{theorem}[A finite covering family of localizations assembles into an \'etale cover]
  \label{thm:PicEtAff_exists_etaleCover_pi}
  \lean{AlgebraicGeometry.PicEtAff.exists_etaleCover_pi}
  \uses{def:etale_cover_of, lem:etale_cover_ofEquiv, def:etale_cover}
  \leanok
  Let \(A\) be a \(k\)-algebra and \((g_i)_{i \in \iota}\) a finite family with
  \(\sum_i (g_i) = (1)\), and let \(S_i\) be the localization of \(A\) away from \(g_i\). Given
  presented \'etale covers \(K_i\) of \(S_i\), the product \(\prod_i B_{K_i}\) is the carrier of a
  presented \'etale cover \(W\) of \(A\), with an isomorphism of \(A\)-algebras \(B_W \cong
  \prod_i B_{K_i}\).
\end{theorem}
\begin{proof}
  \leanok
  Each \(S_i\), a localization of \(A\) away from \(g_i\), is \'etale over \(A\); each \(B_{K_i}\)
  is \'etale over \(S_i\), hence over \(A\); so the finite product \(\prod_i B_{K_i}\) is \'etale
  over \(A\). It remains that \(\Spec(\prod_i B_{K_i}) \to \Spec A\) is surjective; then
  \(\prod_i B_{K_i}\) is a presented \'etale cover of \(A\) (Definition~\ref{def:etale_cover_of},
  Lemma~\ref{lem:etale_cover_ofEquiv}). Given a prime \(p\) of \(A\): since
  \(\sum_i (g_i) = (1)\), some \(g_i \notin p\), so \(p\) lifts to \(\Spec S_i\) (the spectrum of
  the localization away from \(g_i\) is the basic open \(D(g_i) \ni p\)); as \(K_i\) is a cover of
  \(S_i\) it is surjective on spectra (Definition~\ref{def:etale_cover}), so \(p\) lifts further to
  \(\Spec B_{K_i}\), and thence to \(\Spec(\prod_j B_{K_j})\) through the \(i\)-th coordinate. Hence
  the structure map is surjective.
\end{proof}

\begin{theorem}[Zariski separation of the \'etale plus construction]
  \label{thm:PicEtAff_eq_of_away_eq}
  \lean{AlgebraicGeometry.PicEtAff.eq_of_away_eq}
  \uses{thm:relPic_pi_separation, thm:PicEtAff_exists_relPicAlgMap_eq,
    thm:PicEtAff_exists_etaleCover_pi, lem:PicEtAff_ind, thm:PicEtAff_mk_one, def:PicEtAff_map}
  \leanok
  Let \(A\) be a \(k\)-algebra, \((g_i)_{i \in \iota}\) a finite family with \(\sum_i (g_i) = (1)\),
  and \(S_i\) the localization of \(A\) away from \(g_i\). Two plus classes \(x, y \in
  \mathrm{PicEtAff}(C, A)\) with equal restrictions along every \(A \to S_i\) are equal.
\end{theorem}
\begin{proof}
  \leanok
  Restriction is a homomorphism, so it suffices to show a class \(z\) with trivial restriction to
  every \(S_i\) is trivial. Represent \(z = [G, \zeta]\) (Lemma~\ref{lem:PicEtAff_ind}). For each
  \(i\), comparing the restriction of \([G, \zeta]\) with that of the trivial class
  \([\mathrm{self}(A), 1]\) over \(S_i\) and unfolding (Theorem~\ref{thm:PicEtAff_exists_relPicAlgMap_eq}),
  there are a presented \'etale cover \(K_i\) of \(S_i\) and a homomorphism \(m_i \colon B_G \to
  B_{K_i}\), semilinear over \(A \to S_i\), with \(m_i^{*}\zeta = 1\) in \(\mathrm{relPic}(C,
  B_{K_i})\). Assemble the product cover \(W\) of \(A\) from the \(K_i\)
  (Theorem~\ref{thm:PicEtAff_exists_etaleCover_pi}), \(B_W \cong \prod_i B_{K_i}\) over \(A\). The
  joint map \(\langle m_i \rangle \colon B_G \to \prod_i B_{K_i}\) pushes \(\zeta\) to a class whose
  \(i\)-th factor is \(\pi_i^{*}(\langle m_i\rangle^{*}\zeta) = m_i^{*}\zeta = 1\); by the product
  separation (Theorem~\ref{thm:relPic_pi_separation}) the pushed class is trivial in
  \(\mathrm{relPic}(C, \prod_i B_{K_i})\), hence in \(\mathrm{relPic}(C, B_W)\) after transport
  through the carrier isomorphism. As the joint map is an \(A\)-algebra refinement \(B_G \to B_W\),
  \([G, \zeta] = [W, 1] = 1\) (Theorem~\ref{thm:PicEtAff_mk_one}). So \(z = 1\).
\end{proof}

\section{Restriction of relative Picard classes to an \'etale cover is injective}

This section extracts the usable corollary of the (C1) \'etale-separatedness theorem for the
Layer-2 gluing arguments. Throughout \(C\) is a curve over \(k\) (proper, geometrically irreducible,
geometrically reduced) and \(R\) is a commutative \(k\)-algebra.

\begin{theorem}[The unit represented on an arbitrary cover]
  \label{thm:PicEtAff_unit_eq_mk}
  \lean{AlgebraicGeometry.PicEtAff.unit_eq_mk}
  \uses{def:PicEtAff_unit, lem:PicEtAff_tautological_mem_descentClasses, def:PicEtAff_mk,
    def:descentMap, lem:PicEtAff_mk_descentMap, def:etale_cover_fromSelf, def:relPicAlgMap}
  \leanok
  For a presented \'etale cover \(E\) of \(R\) and \(z \in \mathrm{relPic}(C, R)\), the unit
  \(\eta_R(z)\) is represented on \(E\) by the tautological descent datum of \(z\):
  \[
    \eta_R(z) = [E, \iota_E^{*}z], \qquad \iota_E^{*}z \in \mathrm{Desc}(C, E),
  \]
  where \(\iota_E \colon R \to B_E\) is the structure map.
\end{theorem}
\begin{proof}
  \leanok
  By definition (Definition~\ref{def:PicEtAff_unit}) \(\eta_R(z) = [\mathrm{self}(R), \iota^{*}z]\)
  with \(\iota^{*}z\) the tautological datum on the trivial cover
  (Lemma~\ref{lem:PicEtAff_tautological_mem_descentClasses}). Transport along the canonical map
  \(\mathrm{fromSelf} \colon B_{\mathrm{self}(R)} \to B_E\) (Definition~\ref{def:etale_cover_fromSelf})
  carries the tautological datum on \(\mathrm{self}(R)\) to the tautological datum
  \(\iota_E^{*}z\) on \(E\): both are the restriction of \(z\) along the structure map, by
  functoriality of restriction, and the composite structure map \(R \to B_{\mathrm{self}(R)} \to
  B_E\) is \(\iota_E\) (Definition~\ref{def:relPicAlgMap}). By
  Lemma~\ref{lem:PicEtAff_mk_descentMap}, transporting a representative along a refinement map does
  not change the plus class, so \([E, \iota_E^{*}z] = [E, \mathrm{fromSelf}_{*}(\iota^{*}z)] =
  [\mathrm{self}(R), \iota^{*}z] = \eta_R(z)\).
\end{proof}

\begin{theorem}[Restriction to an \'etale cover is injective --- the (C1) consumable]
  \label{thm:relPicAlgMap_injective_of_etaleCover}
  \lean{AlgebraicGeometry.relPicAlgMap_injective_of_etaleCover}
  \uses{thm:PicEtAff_unit_injective, thm:PicEtAff_unit_eq_mk, def:relPicAlgMap, def:PicEtAff_mk}
  \leanok
  For a presented \'etale cover \(E\) of \(R\), restriction of relative Picard classes along the
  structure map \(\iota_E \colon R \to B_E\) is injective: if \(x, y \in \mathrm{relPic}(C, R)\)
  satisfy \(\iota_E^{*}x = \iota_E^{*}y\) in \(\mathrm{relPic}(C, B_E)\), then \(x = y\). This is
  what licenses every gluing step of the Layer-2 functor.
\end{theorem}
\begin{proof}
  \leanok
  By the \'etale separatedness of the relative Picard functor
  (Theorem~\ref{thm:PicEtAff_unit_injective}), the unit \(\eta_R\) is injective, so it suffices to
  show \(\eta_R(x) = \eta_R(y)\). Represent both on \(E\) (Theorem~\ref{thm:PicEtAff_unit_eq_mk}):
  \(\eta_R(x) = [E, \iota_E^{*}x]\) and \(\eta_R(y) = [E, \iota_E^{*}y]\). Since \(\iota_E^{*}x =
  \iota_E^{*}y\) by hypothesis, these classes coincide, so \(\eta_R(x) = \eta_R(y)\) and hence
  \(x = y\).
\end{proof}

\section{Zariski gluing of the \'etale plus construction}

Throughout, \(C\) is a curve over \(k\) (proper, geometrically irreducible, geometrically reduced).
This section proves the gluing half of the Zariski sheaf property of \(\mathrm{PicEtAff}(C, -)\) on
affine tests. Its engine, the pair condition, is the single point where the Layer-2 functoriality
consumes the (C1) \'etale separatedness.

\begin{theorem}[The pair condition]
  \label{thm:PicEtAff_pair_condition}
  \lean{AlgebraicGeometry.PicEtAff.relPicAlgMap_tensor_eq_of_compat}
  \uses{thm:relPicAlgMap_injective_of_etaleCover, thm:PicEtAff_exists_relPicAlgMap_eq,
    thm:relPicAlgMap_congr, def:etale_cover_baseChange, def:relPicAlgMap}
  \leanok
  Let \(S_1, S_2\) be localizations of a \(k\)-algebra \(A\) away from \(g_1, g_2\), and \(T_v\) a
  localization away from \(g_1 g_2\), with \(A\)-algebra homomorphisms \(\varphi_1 \colon S_1 \to
  T_v\), \(\varphi_2 \colon S_2 \to T_v\). Let \(E_1\) be a presented \'etale cover of \(S_1\),
  \(E_2\) of \(S_2\), and \(\xi_1 \in \mathrm{Desc}(C, E_1)\), \(\xi_2 \in \mathrm{Desc}(C, E_2)\).
  If \(\varphi_1^{*}[E_1, \xi_1] = \varphi_2^{*}[E_2, \xi_2]\) in \(\mathrm{PicEtAff}(C, T_v)\), then
  the two pullbacks of the underlying classes into the \(A\)-tensor product agree:
  \[
    \mathrm{inl}^{*}\xi_1 = \mathrm{inr}^{*}\xi_2 \quad\text{in } \mathrm{relPic}(C, B_{E_1}
    \otimes_A B_{E_2}),
  \]
  where \(\mathrm{inl} \colon B_{E_1} \to B_{E_1} \otimes_A B_{E_2}\) and \(\mathrm{inr} \colon
  B_{E_2} \to B_{E_1} \otimes_A B_{E_2}\) are the two coprojections.
\end{theorem}
\begin{proof}
  \leanok
  Unfold the overlap compatibility (Theorem~\ref{thm:PicEtAff_exists_relPicAlgMap_eq}): there are a
  presented \'etale cover \(H\) of \(T_v\) and homomorphisms \(m_1 \colon B_{E_1} \to B_H\),
  \(m_2 \colon B_{E_2} \to B_H\), semilinear over \(\varphi_1, \varphi_2\), with \(m_1^{*}\xi_1 =
  m_2^{*}\xi_2\) in \(\mathrm{relPic}(C, B_H)\).

  In \(B_{E_1} \otimes_A B_{E_2}\), the element \(g_1 g_2\) is a unit: \(g_1\) is a unit in
  \(B_{E_1}\) and \(g_2\) in \(B_{E_2}\) (both localized-away), and their images multiply to
  \(g_1 g_2\). Since \(T_v\) is the localization of \(A\) away from \(g_1 g_2\), there is a unique
  homomorphism of \(A\)-algebras \(\rho \colon T_v \to B_{E_1} \otimes_A B_{E_2}\). Base-change \(H\)
  along \(\rho\) to a presented \'etale cover \(W := H_{B_{E_1} \otimes_A B_{E_2}}\)
  (Definition~\ref{def:etale_cover_baseChange}), with canonical inclusion \(\theta \colon B_H \to
  B_W\). By the (C1) consumable (Theorem~\ref{thm:relPicAlgMap_injective_of_etaleCover}), restriction
  along the structure map \(B_{E_1} \otimes_A B_{E_2} \to B_W\) is injective; it therefore suffices
  to show that the two sides become equal after transport into \(B_W\).

  Consider the two routes \(B_{E_1} \to B_W\). The first is \(\mathrm{inl}\) followed by the
  structure map into \(B_W\); the second is \(\theta \circ m_1\). Both are homomorphisms of
  \(S_1\)-algebras: for the second, \(m_1\) is \(\varphi_1\)-semilinear and \(\rho \circ \varphi_1\)
  equals the \(S_1\)-structure map \(S_1 \to B_{E_1} \otimes_A B_{E_2}\) (two homomorphisms of
  \(A\)-algebras out of the localization \(S_1\), hence equal). By refinement independence
  (Theorem~\ref{thm:relPicAlgMap_congr}, applied to the two \(S_1\)-algebra maps out of the cover
  \(E_1\) of \(S_1\) and the descent class \(\xi_1\)), the two routes transport \(\xi_1\) to the
  same class in \(\mathrm{relPic}(C, B_W)\). Symmetrically the two routes \(B_{E_2} \to B_W\)
  (namely \(\mathrm{inr}\) into \(B_W\) and \(\theta \circ m_2\)) transport \(\xi_2\) equally. Now
  \[
    (\theta \circ m_1)^{*}\xi_1 = \theta^{*}(m_1^{*}\xi_1) = \theta^{*}(m_2^{*}\xi_2)
      = (\theta \circ m_2)^{*}\xi_2 ,
  \]
  so, chaining the two refinement independences, the transports into \(B_W\) of
  \(\mathrm{inl}^{*}\xi_1\) and \(\mathrm{inr}^{*}\xi_2\) agree; by injectivity,
  \(\mathrm{inl}^{*}\xi_1 = \mathrm{inr}^{*}\xi_2\).
\end{proof}

\begin{lemma}[Restriction along an algebra isomorphism is injective]
  \label{lem:relPicAlgMap_algEquiv_injective}
  \lean{AlgebraicGeometry.relPicAlgMap_algEquiv_injective}
  \uses{def:relPicAlgMap, lem:relPicAlgMap_functor}
  \leanok
  For an isomorphism of \(k\)-algebras \(e \colon A \xrightarrow{\ \sim\ } B\), restriction of
  relative Picard classes along \(e\), \(e^{*} \colon \mathrm{relPic}(C, A) \to \mathrm{relPic}(C,
  B)\), is injective.
\end{lemma}
\begin{proof}
  \leanok
  Restriction along \(e^{-1}\) is a left inverse: \((e^{-1})^{*} \circ e^{*} = (e^{-1} \circ e)^{*}
  = (\id_A)^{*} = \id\), by functoriality (Lemma~\ref{lem:relPicAlgMap_functor}). A map with a left
  inverse is injective.
\end{proof}

\begin{lemma}[Computing a restricted plus class on a given cover]
  \label{lem:PicEtAff_mapAlg_mk_eq_mk}
  \lean{AlgebraicGeometry.PicEtAff.mapAlg_mk_eq_mk}
  \uses{thm:PicEtAff_mk_eq_mk_iff, def:PicEtAff_map, def:PicEtAff_mapAlg,
    def:etale_cover_baseChange, def:relPicAlgMap}
  \leanok
  Let \(\varphi \colon A_1 \to R\) be a homomorphism of \(k\)-algebras, \(E_1\) a presented \'etale
  cover of \(A_1\), \(F\) a presented \'etale cover of \(R\), \(\xi \in \mathrm{Desc}(C, E_1)\) and
  \(\eta \in \mathrm{Desc}(C, F)\). Suppose there is a homomorphism of \(k\)-algebras \(n \colon
  B_{E_1} \to B_F\), semilinear over \(\varphi\) (\(n \circ \iota_{E_1} = \iota_F \circ \varphi\)),
  with \(n^{*}\xi = \eta\) in \(\mathrm{relPic}(C, B_F)\). Then \(\varphi^{*}[E_1, \xi] = [F, \eta]\).
\end{lemma}
\begin{proof}
  \leanok
  Regard \(R\) as an \(A_1\)-algebra through \(\varphi\), so that \(\varphi^{*}[E_1, \xi] =
  [(E_1)_R, \kappa_{E_1}^{*}\xi]\) (Definition~\ref{def:PicEtAff_map}, with \((E_1)_R\) the base
  change, Definition~\ref{def:etale_cover_baseChange}). The semilinear map \(n\) extends uniquely to
  an \(R\)-algebra refinement \(n_R \colon B_{(E_1)_R} \to B_F\) with \(n_R \circ \kappa_{E_1} = n\).
  By the presentation criterion (Theorem~\ref{thm:PicEtAff_mk_eq_mk_iff}, with the common cover
  \(F\), the map \(n_R\) out of \((E_1)_R\) and the identity out of \(F\)), \([(E_1)_R,
  \kappa_{E_1}^{*}\xi] = [F, (n_R)_{*}(\kappa_{E_1}^{*}\xi)]\); and \((n_R)_{*}(\kappa_{E_1}^{*}\xi)
  = n^{*}\xi = \eta\) by functoriality (Definition~\ref{def:relPicAlgMap}). Hence
  \(\varphi^{*}[E_1, \xi] = [F, \eta]\).
\end{proof}

\begin{theorem}[Zariski gluing of the \'etale plus construction]
  \label{thm:PicEtAff_exists_mapAlg_eq_of_compat}
  \lean{AlgebraicGeometry.PicEtAff.exists_mapAlg_eq_of_compat}
  \uses{thm:PicEtAff_pair_condition, thm:PicEtAff_exists_etaleCover_pi, thm:relPic_pi_gluing,
    thm:relPic_pi_separation, lem:PicEtAff_mapAlg_mk_eq_mk, lem:relPicAlgMap_algEquiv_injective,
    lem:PicEtAff_ind}
  \leanok
  Let \(A\) be a \(k\)-algebra, \((g_i)_{i \in \iota}\) a finite family with \(\sum_i (g_i) = (1)\),
  \(S_i\) the localization of \(A\) away from \(g_i\), and \(T_{ij}\) the localization away from
  \(g_i g_j\). A family \((x_i)_{i \in \iota}\) with \(x_i \in \mathrm{PicEtAff}(C, S_i)\),
  compatible on the overlaps (the restrictions of \(x_i\) and \(x_j\) to \(T_{ij}\) agree for all
  \(i, j\)), is the family of restrictions of a plus class \(z \in \mathrm{PicEtAff}(C, A)\):
  restriction of \(z\) to \(S_i\) is \(x_i\). Together with Theorem~\ref{thm:PicEtAff_eq_of_away_eq}
  this is the Zariski sheaf property of \(\mathrm{PicEtAff}(C, -)\) on affine tests.
\end{theorem}
\begin{proof}
  \leanok
  Represent \(x_i = [E_i, \xi_i]\) (Lemma~\ref{lem:PicEtAff_ind}). For each \(i, j\), the overlap
  compatibility over \(T_{ij}\) yields, by the pair condition
  (Theorem~\ref{thm:PicEtAff_pair_condition}), \(\mathrm{inl}^{*}\xi_i = \mathrm{inr}^{*}\xi_j\) in
  \(\mathrm{relPic}(C, B_{E_i} \otimes_A B_{E_j})\). Lift the underlying classes to the product: by
  the product gluing (Theorem~\ref{thm:relPic_pi_gluing}) there is \(\zeta \in \mathrm{relPic}(C,
  \prod_i B_{E_i})\) with \(\pi_i^{*}\zeta = \xi_i\). Assemble the product cover \(W\) of \(A\) from
  the \(E_i\) (Theorem~\ref{thm:PicEtAff_exists_etaleCover_pi}), \(B_W \cong \prod_i B_{E_i}\) over
  \(A\); transport \(\zeta\) to \(\zeta_W \in \mathrm{relPic}(C, B_W)\).

  \emph{\(\zeta_W\) is a descent class on \(W\).} The descent condition \(\mathrm{inl}^{*}\zeta_W =
  \mathrm{inr}^{*}\zeta_W\) in \(\mathrm{relPic}(C, B_W \otimes_A B_W)\) is checked through the
  \(\pi\)-decomposition of the tensor square, \(B_W \otimes_A B_W \cong \prod_{(i, j)} B_{E_i}
  \otimes_A B_{E_j}\): by injectivity of transport along this isomorphism
  (Lemma~\ref{lem:relPicAlgMap_algEquiv_injective}) and product separation over the index set
  \(\iota \times \iota\) (Theorem~\ref{thm:relPic_pi_separation}), it suffices to compare
  components. The \((i, j)\)-component of \(\mathrm{inl}^{*}\zeta_W\) is \(\mathrm{inl}^{*}
  (\pi_i^{*}\zeta) = \mathrm{inl}^{*}\xi_i\) and of \(\mathrm{inr}^{*}\zeta_W\) is
  \(\mathrm{inr}^{*}(\pi_j^{*}\zeta) = \mathrm{inr}^{*}\xi_j\); these agree by the pair conditions.

  \emph{The glued class.} Set \(z := [W, \zeta_W]\). Its restriction to \(S_i\) is \(x_i\): the
  \(i\)-th projection \(B_W \cong \prod_j B_{E_j} \to B_{E_i}\) is a homomorphism semilinear over
  \(A \to S_i\) carrying \(\zeta_W\) onto \(\pi_i^{*}\zeta = \xi_i\), so by
  Lemma~\ref{lem:PicEtAff_mapAlg_mk_eq_mk}, \((A \to S_i)^{*}[W, \zeta_W] = [E_i, \xi_i] = x_i\).
\end{proof}

\section{The \'etale-sheafified relative Picard functor: the affine-opens limit}

The frozen group-object interface forces the relative Picard functor to exist on \emph{all} of
\(\Over(\Spec k)\), not only on affine tests. Following the resolution of the Layer-2 vehicle
question, the extension is the \emph{bespoke affine-opens limit}: a section over a test object
\(T\) is a compatible family of affine-level plus classes over the affine opens of
\(T_{\mathrm{left}}\). The index poset is \(\mathrm{Type}\)-small, which is the point of the
vehicle. Throughout, \(k\) is a field and \(C\) is a curve over \(k\).

\begin{definition}[Transport of plus classes along an algebra isomorphism]
  \label{def:PicEtAff_congr}
  \lean{AlgebraicGeometry.PicEtAff.congr}
  \uses{def:PicEtAff_map, thm:PicEtAff_map_map, thm:PicEtAff_map_id}
  \leanok
  For an isomorphism of \(k\)-algebras \(e \colon A \xrightarrow{\ \sim\ } B\), restriction of plus
  classes along \(e\) is a group isomorphism \(\mathrm{PicEtAff}(C, A) \xrightarrow{\ \sim\ }
  \mathrm{PicEtAff}(C, B)\), with inverse restriction along \(e^{-1}\).
\end{definition}
\begin{proof}
  \leanok
  Restriction along \(e\) and along \(e^{-1}\) are homomorphisms of groups
  (Definition~\ref{def:PicEtAff_map}); their two composites are restriction along
  \(e^{-1} \circ e = \id_A\) and along \(e \circ e^{-1} = \id_B\), each the identity by transitivity
  of restriction (Theorem~\ref{thm:PicEtAff_map_map}) and its normalization at the identity
  (Theorem~\ref{thm:PicEtAff_map_id}). Hence the two are mutually inverse.
\end{proof}

\begin{definition}[The affine identification of global sections]
  \label{def:overSpecGammaTop}
  \lean{AlgebraicGeometry.Over.overSpecΓTopAlgEquiv}
  \leanok
  For a \(k\)-algebra \(A\), the global sections of the affine test \(\Spec A\) over its top open
  are identified with \(A\) as a \(k\)-algebra: \(\Gamma((\Spec A)_{\mathrm{left}}, \top)
  \xrightarrow{\ \sim\ } A\), through the canonical isomorphism \(\Gamma(\Spec A, \top) \cong A\) of
  the affine scheme.
\end{definition}
\begin{proof}
  \leanok
  The canonical isomorphism of rings \(\Gamma(\Spec A, \top) \cong A\) intertwines the two
  \(k\)-algebra structures: the structure map of the sections and that of \(A\) both come from the
  \(k\)-algebra structure of \(A\) through this same isomorphism. Hence it is an isomorphism of
  \(k\)-algebras.
\end{proof}

\begin{definition}[The \'etale-sheafified relative Picard functor at a test object]
  \label{def:picEt}
  \lean{AlgebraicGeometry.picEtSubgroup, AlgebraicGeometry.picEt}
  \uses{def:PicEtAff, def:PicEtAff_map}
  \source{kleiman-picard}
  \leanok
  For a test object \(T\) of \(\Over(\Spec k)\), \(\mathrm{picEt}(C, T)\) is the group of
  \emph{compatible families}: an element assigns to each affine open \(V \subseteq T_{\mathrm{left}}\)
  a plus class \(s_V \in \mathrm{PicEtAff}(C, \Gamma(T, V))\) such that for affine opens
  \(U \subseteq V\), the value \(s_U\) is the restriction of \(s_V\) along the section-restriction
  homomorphism \(\Gamma(T, V) \to \Gamma(T, U)\) (Definition~\ref{def:PicEtAff_map}). Componentwise
  product makes \(\mathrm{picEt}(C, T)\) a commutative group, a subgroup of the product
  \(\prod_{V} \mathrm{PicEtAff}(C, \Gamma(T, V))\); evaluation at an affine open \(V\) is the
  homomorphism \(s \mapsto s_V\). On affine tests this is the plus itself (the affine comparison,
  Definition~\ref{def:picEtAffineEquiv}); on general tests it is the canonical Zariski-continuous
  extension --- the realization on all test objects of the \'etale sheafification
  \(\Pic_{(X/S)\mathrm{\acute et}}\) of the relative Picard functor.
\end{definition}
\begin{proof}
  \leanok
  The compatibility condition is closed under the componentwise group operations: the constant
  family \(1\) is compatible (restriction preserves the identity); and if \(s, t\) are compatible,
  so are \(s \cdot t\) and \(s^{-1}\), because restriction of plus classes is a homomorphism of
  groups (Definition~\ref{def:PicEtAff_map}). Hence the compatible families form a subgroup of the
  product group, which is therefore a commutative group.
\end{proof}

\begin{definition}[The affine comparison isomorphism]
  \label{def:picEtAffineEquiv}
  \lean{AlgebraicGeometry.picEtAffineEquiv}
  \uses{def:picEt, def:PicEtAff_congr, def:overSpecGammaTop, def:PicEtAff_map}
  \leanok
  On an affine test \(\Spec A\), evaluation at the top affine open \(\top\) is a group isomorphism
  \[
    \mathrm{picEt}(C, \Spec A) \xrightarrow{\ \sim\ } \mathrm{PicEtAff}(C, A),
  \]
  transported through the identification \(\Gamma(\top) \cong A\) of
  Definition~\ref{def:overSpecGammaTop}.
\end{definition}
\begin{proof}
  \leanok
  The affine-opens poset of \(\Spec A\) has a terminal element, the top open \(\top\) (all of
  \(\Spec A\), an affine open containing every affine open), so a compatible family is determined by
  its value at \(\top\). The forward map sends \(s\) to \(s_\top\) carried through \(\Gamma(\top)
  \cong A\) (Definition~\ref{def:overSpecGammaTop}, Definition~\ref{def:PicEtAff_congr}). The
  backward map sends \(x \in \mathrm{PicEtAff}(C, A)\) to the family whose value at \(V\) is \(x\)
  carried to \(\Gamma(\top)\) and restricted to \(\Gamma(V)\) (Definition~\ref{def:PicEtAff_map});
  this family is compatible because restriction is functorial (restricting from \(\top\) to \(V\)
  and then to \(U\) is restricting to \(U\)). The two are mutually inverse: forward-then-backward
  recovers a family \(s\) from its \(\top\)-value, since \(s_V\) is the restriction of \(s_\top\) by
  the compatibility of \(s\) at \(V \subseteq \top\); backward-then-forward returns \(x\), since
  restriction from \(\top\) to \(\top\) is the identity and \(\Gamma(\top) \cong A\) cancels. Both
  maps are homomorphisms of groups, so this is a group isomorphism.
\end{proof}

\section{Functoriality by the unique-pullback-value characterization}

The Layer-2 functor \(\mathrm{picEt}\) is functorial along an \emph{arbitrary} morphism
\(f \colon T' \to T\) of test objects. The value of the restricted family at an affine open
\(W \subseteq T'_{\mathrm{left}}\) --- whose \(f\)-image need not lie in any affine open of
\(T_{\mathrm{left}}\) --- is glued over a finite basic-open refinement of \(W\) subordinate to the
preimages of affine opens, using the Zariski sheaf property of the affine \'etale Picard functor.
Throughout, \(C\) is a curve over \(k\).

\begin{theorem}[Finite basic subcovers subordinate to a constraint]
  \label{thm:exists_basic_subcover}
  \lean{AlgebraicGeometry.Scheme.exists_basic_subcover}
  \leanok
  Let \(W\) be an affine open of a scheme \(X\) and \(P\) a property of opens such that every point
  of \(W\) has an open neighbourhood inside \(W\) satisfying \(P\). Then there is a finite family of
  sections \(r \in \Gamma(X, W)\) spanning the unit ideal whose basic opens \(D(r)\) each lie inside
  some open satisfying \(P\).
\end{theorem}
\begin{proof}
  \leanok
  For each \(w \in W\), choose an open \(U_0 \ni w\) with \(P(U_0)\); since the basic opens of the
  affine \(W\) form a basis of its topology, choose \(r_w \in \Gamma(X, W)\) with \(w \in D(r_w)
  \subseteq U_0\). The \(D(r_w)\) cover \(W\); as \(W\) is quasi-compact (being affine), finitely
  many \(D(r_{w_1}), \dots, D(r_{w_n})\) already cover \(W\), which means the \(r_{w_j}\) span the
  unit ideal of \(\Gamma(X, W)\). Each \(D(r_{w_j}) \subseteq U_0\) lies inside an open with \(P\).
\end{proof}

\begin{theorem}[Zariski separation of the plus over the section rings of a basic cover]
  \label{thm:picEt_eq_of_basic_eq}
  \lean{AlgebraicGeometry.picEt.eq_of_basic_eq}
  \uses{thm:PicEtAff_eq_of_away_eq}
  \leanok
  Let \(W\) be an affine open of a test object \(T\) and \((r_i)_{i \in s}\) a finite family in
  \(\Gamma(T, W)\) spanning the unit ideal. Two plus classes \(x, y \in \mathrm{PicEtAff}(C,
  \Gamma(T, W))\) whose restrictions to \(\Gamma(T, D(r_i))\) agree for every \(i\) are equal.
\end{theorem}
\begin{proof}
  \leanok
  The section ring \(\Gamma(T, D(r_i))\) of a basic open of the affine open \(W\) is the
  localization of \(\Gamma(T, W)\) away from \(r_i\), and the \(r_i\) span the unit ideal. Apply the
  Zariski separation of the plus construction (Theorem~\ref{thm:PicEtAff_eq_of_away_eq}) to this
  finite covering family of localizations of \(\Gamma(T, W)\).
\end{proof}

\begin{definition}[The pullback-value property]
  \label{def:picEt_IsPullbackValue}
  \lean{AlgebraicGeometry.picEt.IsPullbackValue}
  \uses{def:picEt, def:PicEtAff_map}
  \leanok
  Let \(f \colon T' \to T\) be a morphism of test objects, \(s \in \mathrm{picEt}(C, T)\), and
  \(W\) an affine open of \(T'_{\mathrm{left}}\). A plus class \(v \in \mathrm{PicEtAff}(C,
  \Gamma(T', W))\) has the \emph{pullback-value property} for \((f, s, W)\) if, for every affine
  open \(W_0 \subseteq W\) contained in the preimage \(f^{-1}V\) of some affine open \(V\) of
  \(T_{\mathrm{left}}\), the restriction of \(v\) to \(\Gamma(T', W_0)\) equals the pullback of
  \(s_V\) along the section-pullback homomorphism \(\Gamma(T, V) \to \Gamma(T', W_0)\) (pullback of
  sections along \(f\), a \(k\)-algebra map; Definition~\ref{def:PicEtAff_map}).
\end{definition}

\begin{theorem}[Choice independence]
  \label{thm:picEt_mapAlg_appLE_eq}
  \lean{AlgebraicGeometry.picEt.mapAlg_appLE_eq}
  \uses{thm:picEt_eq_of_basic_eq, thm:exists_basic_subcover, def:picEt}
  \leanok
  Let \(f \colon T' \to T\), \(s \in \mathrm{picEt}(C, T)\), \(W_0\) an affine open of
  \(T'_{\mathrm{left}}\), and \(V, V'\) affine opens of \(T_{\mathrm{left}}\) with \(W_0 \subseteq
  f^{-1}V\) and \(W_0 \subseteq f^{-1}V'\). Then the pullback of \(s_V\) and the pullback of
  \(s_{V'}\) to \(\Gamma(T', W_0)\) (along the two section-pullback maps) agree.
\end{theorem}
\begin{proof}
  \leanok
  Refine \(W_0\) by basic opens: for each point \(w \in W_0\), the image \(f(w) \in V \cap V'\) lies
  in an affine open \(V'' \subseteq V \cap V'\) of \(T_{\mathrm{left}}\); choose a basic open
  \(D(r) \ni w\) of \(W_0\) with \(f(D(r)) \subseteq V''\), i.e. \(D(r) \subseteq f^{-1}V''\). By
  Theorem~\ref{thm:exists_basic_subcover} a finite family of such \(r\) spans the unit ideal. On
  each \(D(r)\), the pullback of \(s_V\) restricted to \(\Gamma(T', D(r))\) factors as the pullback
  of \(s_{V''}\): using the compatibility \(s_{V''} = s_V|_{V''}\) (as \(V'' \subseteq V\)) and the
  functoriality of section pullback and restriction, it equals the pullback of \(s_{V''}\) along
  \(f\) from \(V''\) to \(D(r)\); likewise for \(s_{V'}\). Hence the two pullbacks agree on every
  \(D(r)\), so by Theorem~\ref{thm:picEt_eq_of_basic_eq} they agree on \(\Gamma(T', W_0)\).
\end{proof}

\begin{theorem}[Uniqueness of the pullback value]
  \label{thm:picEt_pullbackValue_unique}
  \lean{AlgebraicGeometry.picEt.pullbackValue_unique}
  \uses{def:picEt_IsPullbackValue, thm:picEt_eq_of_basic_eq, thm:exists_basic_subcover}
  \leanok
  For fixed \((f, s, W)\), a plus class with the pullback-value property is unique: if \(v, v'\)
  both have the property, then \(v = v'\).
\end{theorem}
\begin{proof}
  \leanok
  Refine \(W\) by basic opens \(D(r)\) each contained in the preimage of an affine open of
  \(T_{\mathrm{left}}\): every point of \(W\) maps into some affine open \(V\) of
  \(T_{\mathrm{left}}\), so has a basic-open neighbourhood in \(W\) inside \(f^{-1}V\; \)by
  Theorem~\ref{thm:exists_basic_subcover} a finite such family spans the unit ideal. On each
  \(D(r) \subseteq f^{-1}V\), both \(v\) and \(v'\) restrict to the pullback of \(s_V\) (the
  defining property, Definition~\ref{def:picEt_IsPullbackValue}), hence agree. By
  Theorem~\ref{thm:picEt_eq_of_basic_eq}, \(v = v'\).
\end{proof}

\begin{theorem}[Existence of the pullback value]
  \label{thm:picEt_exists_isPullbackValue}
  \lean{AlgebraicGeometry.picEt.exists_isPullbackValue,
    AlgebraicGeometry.picEt.existsUnique_isPullbackValue}
  \uses{def:picEt_IsPullbackValue, thm:PicEtAff_exists_mapAlg_eq_of_compat,
    thm:picEt_eq_of_basic_eq, thm:exists_basic_subcover, thm:picEt_mapAlg_appLE_eq,
    thm:picEt_pullbackValue_unique}
  \leanok
  For every \(f \colon T' \to T\), \(s \in \mathrm{picEt}(C, T)\) and affine open \(W\) of
  \(T'_{\mathrm{left}}\), there exists a unique plus class \(v \in \mathrm{PicEtAff}(C, \Gamma(T',
  W))\) with the pullback-value property for \((f, s, W)\).
\end{theorem}
\begin{proof}
  \leanok
  Choose (Theorem~\ref{thm:exists_basic_subcover}) a finite family \((r)\) in \(\Gamma(T', W)\)
  spanning the unit ideal such that each \(D(r)\) lies in the preimage \(f^{-1}V_r\) of an affine
  open \(V_r\) of \(T_{\mathrm{left}}\) (every point of \(W\) maps into some affine open). On
  \(D(r)\) take the local value to be the pullback of \(s_{V_r}\) along \(f\). On an overlap
  \(D(r) \cap D(r') = D(r r')\), the two local values agree: both restrict, through the affine
  opens \(V_r, V_{r'}\), to the same plus class by choice independence
  (Theorem~\ref{thm:picEt_mapAlg_appLE_eq}). The section rings \(\Gamma(T', D(r))\) are localizations
  of \(\Gamma(T', W)\) away from the \(r\), which span the unit ideal, and the overlaps are
  localizations away from \(r r'\); so by the Zariski gluing of the plus construction
  (Theorem~\ref{thm:PicEtAff_exists_mapAlg_eq_of_compat}) the local values glue to a plus class
  \(v \in \mathrm{PicEtAff}(C, \Gamma(T', W))\).

  This \(v\) has the pullback-value property: for an affine \(W_0 \subseteq W\) inside \(f^{-1}V\),
  refine \(W_0\) by basic opens \(D(q)\) each inside some \(D(r)\)
  (Theorem~\ref{thm:exists_basic_subcover}). On \(D(q)\), \(v\) restricts through the glued datum on
  \(D(r)\) to the pullback of \(s_{V_r}\), which by choice independence
  (Theorem~\ref{thm:picEt_mapAlg_appLE_eq}) equals the pullback of \(s_V\); by
  Theorem~\ref{thm:picEt_eq_of_basic_eq}, the restriction of \(v\) to \(\Gamma(T', W_0)\) equals the
  pullback of \(s_V\). Uniqueness is Theorem~\ref{thm:picEt_pullbackValue_unique}.
\end{proof}

\begin{definition}[Restriction of \(\mathrm{picEt}\) along an arbitrary morphism]
  \label{def:picEtMap}
  \lean{AlgebraicGeometry.picEtMapVal, AlgebraicGeometry.picEtMap}
  \uses{thm:picEt_exists_isPullbackValue, def:picEt}
  \leanok
  For a morphism \(f \colon T' \to T\) of test objects, the homomorphism of groups \(f^{*} \colon
  \mathrm{picEt}(C, T) \to \mathrm{picEt}(C, T')\) whose value at an affine open \(W\) of
  \(T'_{\mathrm{left}}\) is the unique plus class with the pullback-value property for \((f, s, W)\)
  (Theorem~\ref{thm:picEt_exists_isPullbackValue}).
\end{definition}
\begin{proof}
  \leanok
  The values form a compatible family: for affine opens \(U \subseteq W\), the restriction of the
  value at \(W\) still has the pullback-value property at \(U\) (the property is stable under
  further restriction, by functoriality of section pullback and restriction), so by uniqueness it
  equals the value at \(U\); thus \((W \mapsto v_W)\) is a section of \(\mathrm{picEt}(C, T')\). It
  is a homomorphism: the pullback-value property is preserved by the componentwise group operations
  (pullback of \(s\) is a homomorphism), so by uniqueness the value at \(s \cdot t\) is the product
  of the values and the value at \(1\) is \(1\).
\end{proof}

\begin{theorem}[The functor laws]
  \label{thm:picEtMap_functor_laws}
  \lean{AlgebraicGeometry.picEtMap_id, AlgebraicGeometry.picEtMap_comp}
  \uses{def:picEtMap, thm:picEt_exists_isPullbackValue, thm:exists_basic_subcover,
    thm:picEt_eq_of_basic_eq, def:picEt}
  \leanok
  Restriction along the identity is the identity, \((\id_T)^{*} = \id\) on \(\mathrm{picEt}(C, T)\);
  and for \(f \colon T' \to T\) and \(g \colon T'' \to T'\), restriction along the composite is the
  composite of the restrictions, \((f \circ g)^{*} = g^{*} \circ f^{*}\).
\end{theorem}
\begin{proof}
  \leanok
  \emph{Identity.} The value of \((\id_T)^{*}s\) at an affine open \(W\) is the unique class with
  the pullback-value property; \(s_W\) itself has it, since for \(W_0 \subseteq W\) inside
  \(\id^{-1}V = V\) the restriction of \(s_W\) is \(s_{W_0}\), the pullback of \(s_V\) along the
  identity (by compatibility of \(s\)). By uniqueness (Theorem~\ref{thm:picEt_exists_isPullbackValue})
  the value is \(s_W\), so \((\id_T)^{*}s = s\).

  \emph{Composite.} It suffices to show the value \((g^{*}(f^{*}s))_W\) has the pullback-value
  property for \((f \circ g, s, W)\); uniqueness then identifies it with \(((f \circ g)^{*}s)_W\).
  Fix an affine \(W \subseteq T''_{\mathrm{left}}\) and \(W_0 \subseteq W\) inside
  \((f \circ g)^{-1}V\). Refine \(W_0\) by basic opens \(D(q)\) whose \(g\)-image lies in an affine
  open \(V'' \subseteq f^{-1}V\) of \(T'_{\mathrm{left}}\)
  (Theorem~\ref{thm:exists_basic_subcover}). On \(D(q)\): the value of \(f^{*}s\) at \(V''\) is the
  pullback of \(s_V\) (the pullback-value property of \(f^{*}s\), as \(V'' \subseteq f^{-1}V\)), and
  the value of \(g^{*}(f^{*}s)\) at \(D(q)\) is the pullback of \((f^{*}s)_{V''}\) along \(g\), which
  by functoriality of section pullback equals the pullback of \(s_V\) along \(f \circ g\). By
  Theorem~\ref{thm:picEt_eq_of_basic_eq}, the value of \(g^{*}(f^{*}s)\) at \(W\) has the
  pullback-value property for \((f \circ g, s, W)\), as required.
\end{proof}

\begin{definition}[The \'etale-sheafified relative Picard functor]
  \label{def:picEtFunctor}
  \lean{AlgebraicGeometry.picEtFunctor}
  \uses{def:picEt, def:picEtMap, thm:picEtMap_functor_laws}
  \leanok
  For a curve \(C\) over \(k\) (proper, geometrically irreducible, geometrically reduced), the
  contravariant functor
  \[
    \mathrm{picEt}(C, -) \colon \bigl(\Over(\Spec k)\bigr)^{\mathrm{op}} \to \mathbf{CommGrp}
  \]
  sending a test object \(T\) to the commutative group \(\mathrm{picEt}(C, T)\)
  (Definition~\ref{def:picEt}) and a morphism \(f\) to the restriction homomorphism \(f^{*}\)
  (Definition~\ref{def:picEtMap}).
\end{definition}
\begin{proof}
  \leanok
  The object and morphism assignments are given by Definition~\ref{def:picEt} and
  Definition~\ref{def:picEtMap}; the identity and composition laws of a functor are exactly the two
  functor laws of restriction (Theorem~\ref{thm:picEtMap_functor_laws}).
\end{proof}

\begin{theorem}[Naturality of the affine comparison]
  \label{thm:picEtAffineEquiv_naturality}
  \lean{AlgebraicGeometry.picEtAffineEquiv_naturality}
  \uses{def:picEtAffineEquiv, def:picEtMap, def:PicEtAff_map, def:overSpecGammaTop,
    thm:picEt_exists_isPullbackValue}
  \leanok
  The affine comparison is natural in the test algebra: for a homomorphism of \(k\)-algebras
  \(\varphi \colon A \to B\) and \(s \in \mathrm{picEt}(C, \Spec A)\), the affine comparison of
  \((\Spec\varphi)^{*}s\) equals the restriction along \(\varphi\) of the affine comparison of
  \(s\). Under the comparison isomorphisms (Definition~\ref{def:picEtAffineEquiv}), restriction along
  \(\Spec\varphi\) corresponds to restriction of plus classes along \(\varphi\).
\end{theorem}
\begin{proof}
  \leanok
  Both sides are computed at the top affine opens. Since \(\top_B \subseteq (\Spec\varphi)^{-1}
  \top_A\), the value of \((\Spec\varphi)^{*}s\) at \(\top_B\) is, by the pullback-value property
  (Theorem~\ref{thm:picEt_exists_isPullbackValue}), the pullback of \(s_{\top_A}\) along the
  section-pullback map \(\Gamma(\Spec A, \top) \to \Gamma(\Spec B, \top)\). Under the identifications
  \(\Gamma(\top) \cong A\) and \(\Gamma(\top) \cong B\) (Definition~\ref{def:overSpecGammaTop}), that
  section-pullback map corresponds to \(\varphi\). Transporting through the comparison isomorphisms
  (Definition~\ref{def:picEtAffineEquiv}), the value corresponds to the restriction along
  \(\varphi\) (Definition~\ref{def:PicEtAff_map}) of the affine comparison of \(s\).
\end{proof}

\begin{theorem}[Uniqueness of gluings for \(\mathrm{picEt}\)]
  \label{thm:picEt_ext_of_le_cover}
  \lean{AlgebraicGeometry.picEt.ext_of_le_cover}
  \uses{def:picEt, thm:picEt_eq_of_basic_eq, thm:exists_basic_subcover}
  \leanok
  Two sections \(s, t \in \mathrm{picEt}(C, T)\) agreeing on every affine open subordinate to an
  open cover of \(T_{\mathrm{left}}\) are equal: if \((O_i)_{i}\) is a family of opens covering
  \(T_{\mathrm{left}}\) and \(s_U = t_U\) for every affine open \(U\) contained in some \(O_i\),
  then \(s = t\). This is the separation half of the sheaf property of the Layer-2 functor.
\end{theorem}
\begin{proof}
  \leanok
  Fix an affine open \(U\) of \(T_{\mathrm{left}}\). Refine \(U\) by basic opens \(D(r)\) each
  contained in some \(O_i\): every point of \(U\) lies in some \(O_i\), so has a basic-open
  neighbourhood in \(U\) inside \(O_i\); by Theorem~\ref{thm:exists_basic_subcover} a finite such
  family spans the unit ideal. On \(D(r) \subseteq O_i\), the restriction of \(s_U\) equals
  \(s_{D(r)} = t_{D(r)}\) (the hypothesis, as \(D(r)\) is an affine open inside \(O_i\)), which
  equals the restriction of \(t_U\) (compatibility of \(s, t\) at \(D(r) \subseteq U\)). By
  Theorem~\ref{thm:picEt_eq_of_basic_eq}, \(s_U = t_U\). As \(U\) was an arbitrary affine open,
  \(s = t\).
\end{proof}

\section{Rigidification along a section of the projection}
\label{sec:rigidification}

Let \(C\) be an object of \(\Over(\Spec k)\) (the curve). For a test object \(T\) in
\(\Over(\Spec k)\), a \(T\)-point \(\sigma \colon T \to C\) determines a section of the
projection \(\mathrm{pr} = \mathrm{snd} \colon C \otimes T \to T\); rigidifying a \v Cech Picard
class along that section is the cocycle recast of Kleiman's \(g\)-rigidification. These are the
inputs to the \((C2)\) comparison of the next section.

\begin{definition}[The section of the projection attached to a point]
  \label{def:sectionOfPoint}
  \lean{AlgebraicGeometry.Over.sectionOfPoint, AlgebraicGeometry.Over.sectionOfPoint_fst,
    AlgebraicGeometry.Over.sectionOfPoint_snd, AlgebraicGeometry.Over.sectionOfPoint_naturality}
  \leanok
  \source{kleiman-picard}
  For a \(T\)-point \(\sigma \colon T \to C\), the \emph{section of the projection}
  \(g_\sigma \colon T \to C \otimes T\) is the map \(\langle \sigma, \id_T \rangle\) into the
  product, characterised by
  \[
    \mathrm{fst} \circ g_\sigma = \sigma, \qquad \mathrm{snd} \circ g_\sigma = \id_T .
  \]
  It is natural in the test object: for \(h \colon T' \to T\), \(h \circ g_\sigma = g_{h \circ
  \sigma} \circ (C \lhd h)\). This is Kleiman's \(g_T\) (\emph{The Picard Scheme}, proof of
  Theorem 2.5).
\end{definition}
\begin{proof}
  \leanok
  By the universal property of the cartesian product, \(T\)-points of \(C\) and sections of the
  projection \(\mathrm{snd}\) are the same datum: \(\langle \sigma, \id_T\rangle\) is the unique
  map with the two stated composites. Naturality is checked on the two projections, using
  \(\mathrm{fst} \circ (C \lhd h) = h \circ \mathrm{fst}\) and \(\mathrm{snd} \circ (C \lhd h) =
  \mathrm{snd}\).
\end{proof}

\begin{definition}[Rigidified \v Cech Picard class]
  \label{def:isRigidified}
  \lean{AlgebraicGeometry.Over.IsRigidified}
  \uses{def:sectionOfPoint}
  \leanok
  \source{kleiman-picard}
  A \v Cech Picard class \(L\) on the product \(C \otimes T\) is \emph{rigidified} along a point
  \(\sigma \colon T \to C\) when its pullback along the section of the projection is trivial,
  \[
    g_\sigma^{*} L = 1 .
  \]
  This is the cocycle form of Kleiman's \(g\)-rigidification (\(\mathrm{df:rgd}\)): on the
  cocycle model an isomorphism class carries no datum, so ``a trivialisation \(u \colon
  \mathcal O_T \xrightarrow{\ \sim\ } g_\sigma^{*} L\) exists'' is exactly \(g_\sigma^{*} L = 1\).
\end{definition}

\begin{theorem}[Rigidity of automorphisms of a rigidified pair]
  \label{thm:unitsAppTop_sectionOfPoint_bijective}
  \lean{AlgebraicGeometry.Over.unitsAppTop_sectionOfPoint_bijective,
    AlgebraicGeometry.Over.isIso_appTop_sectionOfPoint}
  \uses{def:sectionOfPoint, thm:isIso_appLE_snd}
  \leanok
  \source{kleiman-picard}
  Let the curve \(C\) be proper, geometrically irreducible and geometrically reduced. For every
  point \(\sigma \colon \Spec A \to C\), pullback of global unit sections along the section of the
  projection,
  \[
    g_\sigma^{\sharp} \colon \Gamma(\Spec A, \top)^{\times}
      \;\longrightarrow\; \Gamma(X_A, \top)^{\times},
  \]
  is a bijection. In particular, a global unit of the curve \(X_A\) whose restriction along the
  section is \(1\) is itself \(1\). This is the cocycle form of Kleiman's automorphism rigidity: an
  automorphism of a rigidified pair is trivial.
\end{theorem}
\begin{proof}
  \leanok
  Because \(C\) is proper, geometrically irreducible and geometrically reduced, the degree-zero
  cohomology of the relative curve is the test ring itself: pullback of global sections along the
  projection \(\mathrm{pr} = \mathrm{snd} \colon X_A \to \Spec A\) is a ring isomorphism
  \(\Gamma(\Spec A, \top) \xrightarrow{\sim} \Gamma(X_A, \top)\)
  (Theorem~\ref{thm:isIso_appLE_snd}, the case \(H^0(X_A, \struct{}) = A\); this is Kleiman's
  hypothesis \(\struct S \xrightarrow{\sim} f_{*}\struct X\) holding universally in the test ring).
  The section retracts the projection, \(\mathrm{pr} \circ g_\sigma = \id\)
  (Definition~\ref{def:sectionOfPoint}), and pullback of sections is contravariant, so on global
  sections \(g_\sigma^{\sharp} \circ \mathrm{pr}^{\sharp} = (\mathrm{pr} \circ g_\sigma)^{\sharp} =
  \id\). As \(\mathrm{pr}^{\sharp}\) is an isomorphism, \(g_\sigma^{\sharp}\) is its inverse, hence
  an isomorphism, hence bijective on the unit groups. Kleiman's argument is exactly this: an
  automorphism \(v\) of a pair \((L, u)\) rigidified along \(\sigma\) satisfies
  \(g_\sigma^{\sharp} v = 1\), while \(v\) lies in \(H^0(\struct{X_A}) = H^0(\struct{\Spec A})\); the
  displayed isomorphism forces \(v = 1\).
\end{proof}

\begin{lemma}[The retraction identity]
  \label{lem:cechPicMap_sectionOfPoint_snd}
  \lean{AlgebraicGeometry.Over.cechPicMap_sectionOfPoint_snd}
  \uses{def:sectionOfPoint}
  \leanok
  \source{kleiman-picard}
  For a point \(\sigma \colon T \to C\), pullback of \v Cech Picard classes along the section
  of the projection retracts pullback along the projection: for every \(N \in \Pic(T)\),
  \[
    g_\sigma^{*}\,\mathrm{snd}^{*} N = N .
  \]
  This is \(g_T^{*} f_T^{*} = 1\) in Kleiman's notation.
\end{lemma}
\begin{proof}
  \leanok
  Pullback of \v Cech classes is contravariantly functorial, and \(\mathrm{snd} \circ
  g_\sigma = \id_T\) (Definition~\ref{def:sectionOfPoint}), so the composite pullback is the
  pullback along the identity, which is the identity.
\end{proof}

\begin{lemma}[Stability of rigidification under restriction]
  \label{lem:isRigidified_cechPicMap}
  \lean{AlgebraicGeometry.Over.isRigidified_one, AlgebraicGeometry.Over.IsRigidified.cechPicMap}
  \uses{def:isRigidified, def:sectionOfPoint}
  \leanok
  The trivial class is rigidified along every point. Moreover, for \(h \colon T' \to T\) and a
  class \(L\) on \(C \otimes T\) rigidified along \(\sigma \colon T \to C\), the pullback
  \((C \lhd h)^{*} L\) is rigidified along the restricted point \(h \circ \sigma\).
\end{lemma}
\begin{proof}
  \leanok
  The first claim is \(g_\sigma^{*} 1 = 1\). For the second, the naturality of the section in
  the test object (Definition~\ref{def:sectionOfPoint}) gives \(h \circ g_\sigma =
  g_{h \circ \sigma} \circ (C \lhd h)\), so
  \[
    g_{h \circ \sigma}^{*} (C \lhd h)^{*} L
      = \bigl((C \lhd h) \circ g_{h \circ \sigma}\bigr)^{*} L
      = (g_\sigma \circ h)^{*} L
      = h^{*} \bigl(g_\sigma^{*} L\bigr) = h^{*} 1 = 1 . \qedhere
  \]
\end{proof}

\begin{theorem}[Kleiman's identification, injectivity: rigidified representatives are unique]
  \label{thm:isRigidified_eq_of_relPicMk_eq}
  \lean{AlgebraicGeometry.Over.IsRigidified.eq_of_relPicMk_eq,
    AlgebraicGeometry.Over.IsRigidified.eq_one_of_relPicMk_eq_one}
  \uses{def:isRigidified, lem:cechPicMap_sectionOfPoint_snd, def:relPic}
  \leanok
  \source{kleiman-picard}
  Two \v Cech Picard classes on \(C \otimes T\), both rigidified along a point
  \(\sigma \colon T \to C\), which represent the same relative Picard class, are equal on the
  nose. In particular a rigidified representative of the identity relative class is \(1\).
  This is the injectivity half of Kleiman's Lemma \(\mathrm{lm{:}idn}\) (rigidified pairs are
  carried isomorphically onto \(\Pic_{X/S}(T)\)), in cocycle form.
\end{theorem}
\begin{proof}
  \leanok
  Let \(L, L'\) be the two classes. By the exact coset relation
  (Definition~\ref{def:relPic}) the ratio is pulled back from the base: \(L/L' =
  \mathrm{snd}^{*} N\) for some \(N \in \Pic(T)\). Apply \(g_\sigma^{*}\): by the retraction
  identity (Lemma~\ref{lem:cechPicMap_sectionOfPoint_snd}),
  \[
    N = g_\sigma^{*}\,\mathrm{snd}^{*} N = g_\sigma^{*}(L/L')
      = g_\sigma^{*}L \,/\, g_\sigma^{*}L' = 1/1 = 1 ,
  \]
  using both rigidifications. Hence \(L/L' = \mathrm{snd}^{*}1 = 1\), i.e.\ \(L = L'\). The
  special case takes \(L' = 1\), which is rigidified.
\end{proof}

\begin{theorem}[Kleiman's identification, surjectivity: existence of a rigidified representative]
  \label{thm:relPic_exists_isRigidified_rep}
  \lean{AlgebraicGeometry.relPic.exists_isRigidified_rep}
  \uses{def:isRigidified, def:relPic, lem:cechPicMap_sectionOfPoint_snd}
  \leanok
  \source{kleiman-picard}
  Every relative Picard class on \(C \otimes T\) has a representative rigidified along any
  given point \(\sigma \colon T \to C\). This is the surjectivity half of Kleiman's Lemma
  \(\mathrm{lm{:}idn}\), in cocycle form.
\end{theorem}
\begin{proof}
  \leanok
  Let \(M\) be any \v Cech representative of the class (the projection to the quotient is
  surjective, Definition~\ref{def:relPic}). Kleiman's identity-rigidification twist
  \[
    L := M \cdot \bigl(\mathrm{snd}^{*} g_\sigma^{*} M\bigr)^{-1}
  \]
  (\(\mathcal L := \mathcal M \otimes (f_T^{*} g_T^{*} \mathcal M)^{-1}\)) works. The twist factor is pulled
  back from the base, so \(L\) represents the same relative class. And by the retraction
  identity (Lemma~\ref{lem:cechPicMap_sectionOfPoint_snd}),
  \(g_\sigma^{*} L = g_\sigma^{*} M \cdot (g_\sigma^{*} M)^{-1} = 1\), so \(L\) is
  rigidified along \(\sigma\).
\end{proof}

\begin{theorem}[The rigidified transport keystone]
  \label{thm:isRigidified_cechPicMap_congr}
  \lean{AlgebraicGeometry.Over.IsRigidified.cechPicMap_congr}
  \uses{def:isRigidified, thm:relPicAlgMap_congr, thm:isRigidified_eq_of_relPicMk_eq,
    lem:isRigidified_cechPicMap, def:descentClasses, def:relPicMap, def:overSpecMap}
  \leanok
  \source{kleiman-picard}
  Let \(A\) be a \(k\)-algebra, \(E\) a presented \'etale cover of \(A\), \(R\) an
  \(A\)-algebra, \(\sigma \colon \Spec A \to C\) a point, and \(L\) a \v Cech Picard class on
  \(C \otimes \Spec B_E\) such that the relative class of \(L\) is a descent class on \(E\)
  and \(L\) is rigidified along the point of \(\Spec B_E\) induced by \(\sigma\). Then for
  \emph{any} two \(A\)-algebra maps \(j_1, j_2 \colon B_E \to R\), the two pullbacks of \(L\)
  agree \emph{on the nose}:
  \[
    (C \lhd \Spec j_1)^{*} L = (C \lhd \Spec j_2)^{*} L \quad\text{in } \Pic(C \otimes \Spec R).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The plus-construction keystone \(\mathrm{relPicAlgMap\_congr}\)
  (Theorem~\ref{thm:relPicAlgMap_congr}) gives the equality of the two pullbacks as
  \emph{relative} Picard classes, since the class of \(L\) is a descent class and the
  \(j_i\) are \(A\)-algebra maps. Both pullbacks are rigidified along the point of
  \(\Spec R\) induced by \(\sigma\): the \(j_i\) are \(A\)-algebra maps, so the induced point
  of \(\Spec R\) restricts, along \(\Spec j_i\), the induced point of \(\Spec B_E\), and
  rigidification is stable under restriction (Lemma~\ref{lem:isRigidified_cechPicMap}).
  Kleiman's injectivity (Theorem~\ref{thm:isRigidified_eq_of_relPicMk_eq}) upgrades the
  coset equality of two rigidified classes to an equality of \v Cech classes.
\end{proof}

\begin{theorem}[The descent equation of a rigidified representative holds on the nose]
  \label{thm:isRigidified_cechPicMap_doubleInl_eq_doubleInr}
  \lean{AlgebraicGeometry.Over.IsRigidified.cechPicMap_doubleInl_eq_doubleInr}
  \uses{thm:isRigidified_cechPicMap_congr, def:doubleInl_doubleInr}
  \leanok
  \source{kleiman-picard}
  In the situation of Theorem~\ref{thm:isRigidified_cechPicMap_congr}, the two pullbacks of
  the rigidified representative \(L\) to the double cover \(\Spec(B_E \otimes_A B_E)\), along
  the two coprojections, are \emph{equal \v Cech Picard classes} — not merely equal relative
  classes. This is Kleiman's rigidified pair \((\mathcal L', u')\) having a canonical comparison on
  the double cover, the input to the descent-datum construction in the proof of his
  comparison theorem.
\end{theorem}
\begin{proof}
  \leanok
  The two coprojections \(B_E \rightrightarrows B_E \otimes_A B_E\)
  (Definition~\ref{def:doubleInl_doubleInr}) are \(A\)-algebra maps out of the cover carrier
  into the common \(A\)-algebra \(R := B_E \otimes_A B_E\); apply the transport keystone
  (Theorem~\ref{thm:isRigidified_cechPicMap_congr}) to them.
\end{proof}

\section{The \(\sigma\)-normalized comparison cochain}
\label{sec:normalizedComparison}

We now fix a \(k\)-algebra \(A\) with a further \(A\)-algebra \(B\) (the carrier of an \'etale
cover in the intended application) and a curve point \(\sigma \colon \Spec A \to C\).
Write \(X_R := (C \otimes \Spec R)_{\mathrm{left}}\) for the curve over \(\Spec R\). Let
\(q_1, q_2 \colon \Spec(B \otimes_A B) \to \Spec B\) be the coprojections
(Definition~\ref{def:tensorInl_tensorInr}), \(u_1, u_2 \colon X_{B \otimes_A B} \to X_B\) their
whiskerings \(C \lhd q_i\), and \(f_{12}, f_{13}, f_{23}\), \(w_{ij} = C \lhd f_{ij}\) the cofaces
of Definition~\ref{def:tensorFaces}. Write \(s_B, s_q\) for the sections of the projection
(Definition~\ref{def:sectionOfPoint}) attached to the base changes of \(\sigma\) to \(B\) and
\(B \otimes_A B\), and \(p_2 \colon X_{B \otimes_A B} \to \Spec(B \otimes_A B)\) for the
projection. Throughout, \(s^{\sharp}\) denotes pullback of unit cochains as in
Section~\ref{sec:cochainPullback}.

This section packages, and constructs with \emph{no geometric hypotheses}, a cochain-level
realisation of the descent equation \(u_1^{*} L = u_2^{*} L\), normalized along \(\sigma\).

\begin{lemma}[The section squares]
  \label{lem:sectionSquares}
  \lean{AlgebraicGeometry.Over.overSpecMap_comp_point,
    AlgebraicGeometry.Over.sectionOfPoint_left_comp_whiskerLeft,
    AlgebraicGeometry.Over.sectionOfPoint_left_comp_snd,
    AlgebraicGeometry.Over.sectionSq_comp_inl, AlgebraicGeometry.Over.sectionSq_comp_inr,
    AlgebraicGeometry.Over.sectionCb_comp_face₁₂, AlgebraicGeometry.Over.sectionCb_comp_face₁₃,
    AlgebraicGeometry.Over.sectionCb_comp_face₂₃}
  \uses{def:sectionOfPoint, def:overSpecMap, def:tensorInl_tensorInr, def:tensorFaces}
  \leanok
  The section of the projection is natural across the base-change coprojections and cofaces: as
  maps of curve products,
  \[
    s_q \circ u_1 = q_1 \circ s_B, \quad s_q \circ u_2 = q_2 \circ s_B, \quad
    s_{\mathrm{cb}} \circ w_{ij} = f_{ij} \circ s_q \ (ij \in \{12,13,23\}),
  \]
  and \(s_q\) retracts the projection, \(s_q \circ p_2 = \id\).
\end{lemma}
\begin{proof}
  \leanok
  Each square is the naturality of the section (Definition~\ref{def:sectionOfPoint}) applied to
  the relevant \(A\)-algebra map: the coprojections \(q_i\) and cofaces \(f_{ij}\) are
  \(\Spec\) of \(A\)-algebra homomorphisms out of \(B\) respectively \(B \otimes_A B\)
  (Definitions~\ref{def:tensorInl_tensorInr}, \ref{def:tensorFaces}), and restricting the
  base-changed point along such a map lands at the base-changed point over the target algebra;
  whiskering with \(C\) and passing to the section turns this point-compatibility into the stated
  square. The retraction is \(\mathrm{snd} \circ g_\sigma = \id\) of
  Definition~\ref{def:sectionOfPoint}, whiskered to the curve product.
\end{proof}

\begin{lemma}[Pullback of a one-sided trivializing relation]
  \label{lem:unitsAppLE_trivializing_rel}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_trivializing_rel}
  \leanok
  Let \(\varphi \colon X \to Y\) and \(r \colon Y \to Z\). Suppose a unit \(0\)-cochain \(a\) on a
  pointed cover of \(Y\) trivializes the pullback along \(r\) of a pair-indexed unit family \(E\):
  for all \(y, y'\), on the overlap,
  \[
    a_y \cdot \bigl(r^{\sharp} E\bigr)_{y y'} = a_{y'} .
  \]
  Then for every \(x, x' \in X\) and every open \(O \subseteq \varphi^{-1}(\cdots)\) inside the
  relevant overlap pullback, the pulled-back cochain \(\varphi^{\sharp} a\) trivializes the family
  pulled back along the composite:
  \[
    \varphi^{\sharp}_O\, a_{\varphi x} \cdot \bigl((r\varphi)^{\sharp}_O E\bigr)_{x x'}
      = \varphi^{\sharp}_O\, a_{\varphi x'} .
  \]
  This is the one-sided companion of Lemma~\ref{lem:unitsAppLE_coboundary_rel}.
\end{lemma}
\begin{proof}
  \leanok
  Apply the pullback homomorphism \(\varphi^{\sharp}_O\) to the given relation at \(\varphi x,
  \varphi x'\). Being a group homomorphism on units it distributes over the product; by
  functoriality \(\varphi^{\sharp}_O(r^{\sharp} E) = (r\varphi)^{\sharp}_O E\) merges the pullback,
  while \(\varphi^{\sharp}_O a\) is left unchanged.
\end{proof}

\begin{lemma}[Compatibility of a ratio cochain]
  \label{lem:unitsAppLE_trivializing_ratio_compat}
  \lean{AlgebraicGeometry.Scheme.Hom.unitsAppLE_trivializing_ratio_compat}
  \uses{lem:unitsAppLE_coboundary_rel, lem:unitsAppLE_trivializing_rel, lem:unitsAppLE_congr_hom}
  \leanok
  Let \(\varphi_t \colon X \to Y_c\), \(\varphi_1, \varphi_2 \colon X \to Y_a\), \(r_1, r_2
  \colon Y_c \to Z\), \(s_1 \colon Y_a \to Z\). Suppose a \(0\)-cochain \(c\) on \(Y_c\) cobounds
  the comparison of a pair-indexed family \(E\) pulled back along \(r_1, r_2\)
  (\ref{lem:unitsAppLE_coboundary_rel}), and a \(0\)-cochain \(a\) on \(Y_a\) trivializes \(E\)
  pulled back along \(s_1\) (\ref{lem:unitsAppLE_trivializing_rel}). If the pulled-back composites
  agree, \(\varphi_t \circ r_1 = \varphi_1 \circ s_1\) and \(\varphi_t \circ r_2 = \varphi_2
  \circ s_1\), then the ratio cochain
  \[
    \varphi_t^{\sharp} c \cdot \frac{\varphi_2^{\sharp} a}{\varphi_1^{\sharp} a}
  \]
  on \(X\) is \v Cech-compatible: its values at \(x\) and \(x'\) agree on overlaps.
\end{lemma}
\begin{proof}
  \leanok
  Pull the coboundary relation for \(c\) back along \(\varphi_t\)
  (\ref{lem:unitsAppLE_coboundary_rel}) and the trivializing relation for \(a\) back along
  \(\varphi_1\) and \(\varphi_2\) (\ref{lem:unitsAppLE_trivializing_rel}). The hypotheses
  \(\varphi_t r_i = \varphi_i s_1\) identify the two families through
  Lemma~\ref{lem:unitsAppLE_congr_hom}; combining the pulled-back relations, the comparison of
  the ratio cochain at \(x\) and \(x'\) reduces to an identity of units, giving compatibility.
\end{proof}

\begin{definition}[The normalization cover]
  \label{def:normalizationCover}
  \lean{AlgebraicGeometry.Over.normalizationCover,
    AlgebraicGeometry.Over.normalizationCover_le_section,
    AlgebraicGeometry.Over.normalizationCover_le_inl,
    AlgebraicGeometry.Over.normalizationCover_le_inr}
  \uses{def:sectionOfPoint}
  \leanok
  For a pointed cover \(\mathcal N\) of the curve \(X_B\) and a pointed cover \(\mathcal W\) of
  the curve \(X_{B \otimes_A B}\), the \emph{normalization cover} of \(\Spec(B \otimes_A B)\) is
  \[
    \mathcal W \text{ pulled back along } s_q, \ \text{ intersected with the two coprojection
    pullbacks } q_1^{*}, q_2^{*} \text{ of } \mathcal N \text{ pulled back along } s_B .
  \]
  It is the cover on which the \(\sigma\)-normalization below is stated; it lies below \(s_q^{-1}
  \mathcal W\) and below each \(q_i^{-1}(s_B^{-1}\mathcal N)\).
\end{definition}

\begin{definition}[The \(\sigma\)-normalized comparison datum]
  \label{def:normalizedCechComparison}
  \lean{AlgebraicGeometry.NormalizedCechComparison}
  \uses{def:sectionOfPoint, def:isRigidified, def:normalizationCover}
  \leanok
  Fix a unit \v Cech cocycle \(\gamma\) on a pointed cover \(\mathcal N\) of \(X_B\), representing
  a class \(L = [\gamma]\). A \emph{\(\sigma\)-normalized comparison} of \(\gamma\) packages:
  \begin{itemize}
    \item a trivializing \(0\)-cochain \(\rho\) of the section-pullback \(s_B^{\sharp}\gamma\) on
      the cover \(s_B^{-1}\mathcal N\) of \(\Spec B\): \(\rho_b \cdot (s_B^{\sharp}\gamma)_{b b'} =
      \rho_{b'}\) on overlaps — the cochain shadow of rigidification (\ref{def:isRigidified})
      along the section over \(B\);
    \item a pointed cover \(\mathcal W\) of \(X_{B \otimes_A B}\) refining both coprojection
      pullbacks of \(\mathcal N\), and a comparison \(0\)-cochain \(\theta\) on it, with
    \item \textbf{(N1)} \(\theta_x \cdot (u_1^{\sharp}\gamma)_{x y} = (u_2^{\sharp}\gamma)_{x y}
      \cdot \theta_y\) on overlaps — \(\theta\) cobounds the two coprojection pullbacks of
      \(\gamma\), realising \(u_1^{*} L = u_2^{*} L\) at the cochain level; and
    \item \textbf{(N2)} \((s_q^{\sharp}\theta)_y \cdot (q_2^{\sharp}\rho)_y = (q_1^{\sharp}\rho)_y\)
      on the normalization cover (\ref{def:normalizationCover}) — the \(\sigma\)-restriction of
      \(\theta\) is the \(\rho\)-comparison \(q_1^{\sharp}\rho / q_2^{\sharp}\rho\).
  \end{itemize}
  The normalization is \(\rho\)-relative: rigidification makes \(s_B^{\sharp}\gamma\) trivial only
  as a class, giving the trivializing cochain \(\rho\), so ``\(\sigma\)-restriction \(=1\)'' is
  replaced by (N2). Every step is stated pointwise via unit pullback and is blind to
  disconnectedness of \(\Spec(B \otimes_A B)\).
\end{definition}

\begin{theorem}[The \(\sigma\)-defect glues to a global unit]
  \label{thm:exists_glued_sigmaDefect}
  \lean{AlgebraicGeometry.Over.sigmaDefectCochain,
    AlgebraicGeometry.Over.exists_glued_sigmaDefect}
  \uses{def:normalizationCover, lem:sectionSquares,
    lem:unitsAppLE_trivializing_ratio_compat, thm:exists_global_unit_of_compatible}
  \leanok
  Let \(\gamma\) be a unit cocycle on \(\mathcal N\), let \(\theta_0\) be a comparison cochain on
  a refinement \(\mathcal W\) satisfying (N1), and let \(\rho\) be a trivializing cochain of
  \(s_B^{\sharp}\gamma\). The \emph{\(\sigma\)-defect cochain}
  \[
    s_q^{\sharp}\theta_0 \cdot \frac{q_2^{\sharp}\rho}{q_1^{\sharp}\rho}
  \]
  on the normalization cover is \v Cech-compatible, hence glues to a global unit \(\delta \in
  \Gamma(\Spec(B \otimes_A B), \top)^{\times}\).
\end{theorem}
\begin{proof}
  \leanok
  Compatibility is the ratio-compatibility Lemma~\ref{lem:unitsAppLE_trivializing_ratio_compat}
  applied with \(\varphi_t = s_q\), \(\varphi_i = q_i\), \(r_i = u_i\), \(s_1 = s_B\): (N1) is
  the coboundary relation for \(\theta_0\), the relation for \(\rho\) is the one-sided
  trivialization, and the composite coincidences \(s_q \circ u_i = q_i \circ s_B\) are the
  section squares (\ref{lem:sectionSquares}). A compatible unit family on a pointed cover glues to
  a global unit by the sheaf axiom (\ref{thm:exists_global_unit_of_compatible}).
\end{proof}

\begin{theorem}[Existence of the \(\sigma\)-normalized comparison]
  \label{thm:exists_normalizedCechComparison}
  \lean{AlgebraicGeometry.Over.correctedComparison,
    AlgebraicGeometry.Over.exists_normalizedCechComparison}
  \uses{def:isRigidified, def:normalizedCechComparison, thm:exists_glued_sigmaDefect,
    lem:sectionSquares, cor:cechPic_mk_eq_one,
    thm:isRigidified_cechPicMap_doubleInl_eq_doubleInr}
  \leanok
  Let \(\gamma\) be a unit cocycle on a pointed cover \(\mathcal N\) of \(X_B\) whose class \(L =
  [\gamma]\) is rigidified along the section over \(B\) (\ref{def:isRigidified}) and satisfies the
  descent equation \(u_1^{*} L = u_2^{*} L\) — as holds for any rigidified representative of a
  descent class, by Theorem~\ref{thm:isRigidified_cechPicMap_doubleInl_eq_doubleInr}. Then a
  \(\sigma\)-normalized comparison of \(\gamma\) exists. No properness, geometric
  irreducibility or reducedness, or faithful flatness is required.
\end{theorem}
\begin{proof}
  \leanok
  Rigidification gives \(g_{\sigma_B}^{*} L = 1\); on cocycles (\ref{cor:cechPic_mk_eq_one}) this
  means the section-pullback \(s_B^{\sharp}\gamma\) is a coboundary, so a trivializing cochain
  \(\rho\) exists on \(s_B^{-1}\mathcal N\) itself (no refinement). The descent equation
  \(u_1^{*} L = u_2^{*} L\) means the two coprojection pullbacks of \(\gamma\) cobound on a common
  refinement \(\mathcal W\), yielding a comparison cochain \(\theta_0\) with (N1). By
  Theorem~\ref{thm:exists_glued_sigmaDefect} the \(\sigma\)-defect of \(\theta_0\) glues to a
  global unit \(\delta\) of \(\Spec(B \otimes_A B)\). Correct \(\theta_0\) by dividing out the
  projection pullback \(p_2^{\sharp}\delta\): this preserves (N1) (a global factor cancels from
  both sides of the coboundary relation), and, because \(s_q\) retracts \(p_2\)
  (\ref{lem:sectionSquares}), it makes the \(\sigma\)-restriction of the corrected cochain equal
  to \(q_1^{\sharp}\rho / q_2^{\sharp}\rho\) on the nose — that is (N2). The corrected data is the
  required datum.
\end{proof}

\section{Coherence and uniqueness of the \(\sigma\)-normalized comparison}
\label{sec:comparisonCoherence}

Fix a unit \v Cech cocycle \(\gamma\) on a pointed cover \(\mathcal N\) of \(X_B\) and a
\(\sigma\)-normalized comparison of \(\gamma\)
(Definition~\ref{def:normalizedCechComparison}), with cover \(\mathcal W\) of \(X_{B \otimes_A B}\)
and comparison cochain \(\theta\). We show that \(\theta\) satisfies the Amitsur cocycle identity on
the triple base \emph{on the nose}, is unique, and is trivial on the diagonal --- the three
inputs the per-piece descent of the next section runs on. All three are the cochain form of
Kleiman's automorphism-rigidity argument (Lemma~\ref{thm:unitsAppTop_sectionOfPoint_bijective}):
glue a defect to a global unit, kill its \(\sigma\)-restriction by the normalization, and apply
rigidity at the relevant affine test.

Write \(X_{B \otimes_A (B \otimes_A B)}\) for the curve over the triple base. Its three
tensor-slot \emph{insertions} \(v_1, v_2, v_3 \colon X_{B \otimes_A (B \otimes_A B)} \to X_B\) are
the whiskerings \(C \lhd (\Spec\ \text{of})\) of the \(A\)-algebra maps \(x \mapsto x \otimes 1
\otimes 1\), \(x \mapsto 1 \otimes x \otimes 1\), \(x \mapsto 1 \otimes 1 \otimes x\).

\begin{definition}[The Amitsur product cover and its insertions]
  \label{def:amitsurProductCover}
  \lean{AlgebraicGeometry.Over.amitsurProductCover, AlgebraicGeometry.Over.amitsurInsertion₁,
    AlgebraicGeometry.Over.amitsurInsertion₂, AlgebraicGeometry.Over.amitsurInsertion₃}
  \uses{def:amitsurCover, def:tensorInl_tensorInr, def:tensorFaces}
  \leanok
  For a pointed cover \(\mathcal W\) of the curve \(X_{B \otimes_A B}\), the \emph{Amitsur product
  cover} of \(X_{B \otimes_A (B \otimes_A B)}\) is the common refinement of the three coface
  pullbacks,
  \[
    w_{23}^{-1}\mathcal W \ \sqcap\ w_{12}^{-1}\mathcal W \ \sqcap\ w_{13}^{-1}\mathcal W ,
  \]
  the curve-product mirror of the Amitsur cover (Definition~\ref{def:amitsurCover}). The three
  insertions \(v_1, v_2, v_3\) are the pairwise-coincident values of the six coface--coprojection
  composites \(w_{ij} \circ u_k \colon X_{B \otimes_A (B \otimes_A B)} \to X_B\):
  \[
    v_1 = w_{12} \circ u_1 = w_{13} \circ u_1, \quad
    v_2 = w_{23} \circ u_1 = w_{12} \circ u_2, \quad
    v_3 = w_{23} \circ u_2 = w_{13} \circ u_2 .
  \]
\end{definition}
\begin{proof}
  \leanok
  The cover is a finite intersection of pullbacks of the pointed cover \(\mathcal W\), hence a
  pointed cover. Each of the three displayed pairs of composites coincides by the simplicial
  identities of the tensor tower relating the cofaces \(f_{ij}\) (Definition~\ref{def:tensorFaces})
  to the coprojections \(x \mapsto x \otimes 1\), \(x \mapsto 1 \otimes x\)
  (Definition~\ref{def:tensorInl_tensorInr}): whiskering to the curve preserves those equalities,
  and each \(v_i\) is the whiskered \(\Spec\) of one tensor-slot insertion.
\end{proof}

\begin{theorem}[The Amitsur defect glues to a global unit]
  \label{thm:exists_glued_productDefect}
  \lean{AlgebraicGeometry.Over.productDefectCochain,
    AlgebraicGeometry.Over.exists_glued_productDefect}
  \uses{def:amitsurProductCover, def:normalizedCechComparison, thm:exists_global_unit_of_compatible}
  \leanok
  Let \(\gamma\) be a unit cocycle on \(\mathcal N\) and \(\theta_0\) a comparison cochain on a
  refinement \(\mathcal W\) satisfying \textbf{(N1)}, i.e.\ \(\theta_0\) cobounds the two
  coprojection pullbacks of \(\gamma\). The \emph{Amitsur defect}
  \[
    \varepsilon \;=\; \frac{(w_{23}^{\sharp}\theta_0)\,(w_{12}^{\sharp}\theta_0)}
      {w_{13}^{\sharp}\theta_0}
  \]
  --- a unit \(0\)-cochain on the Amitsur product cover --- is \v Cech-compatible, hence glues to a
  global unit \(\bar\varepsilon \in \Gamma(X_{B \otimes_A (B \otimes_A B)}, \top)^{\times}\). No
  geometric hypotheses are used.
\end{theorem}
\begin{proof}
  \leanok
  Relation \textbf{(N1)} reads \(\theta_{0,x} \cdot (u_1^{\sharp}\gamma)_{xy} =
  (u_2^{\sharp}\gamma)_{xy} \cdot \theta_{0,y}\) on overlaps. Pull it back along each of the three
  cofaces \(w_{23}, w_{12}, w_{13}\); by Definition~\ref{def:amitsurProductCover} the
  coface--coprojection composites appearing are exactly the three insertions, so the pulled-back
  relations express the overlap discrepancy of each factor \(w_{ij}^{\sharp}\theta_0\) through the
  cocycle \(\gamma\) evaluated at the insertions \(v_1, v_2, v_3\). The three insertion values are
  common to the numerator and denominator of \(\varepsilon\); multiplying the three relations
  telescopically, the \(\gamma\)-terms cancel and the value of \(\varepsilon\) at \(z\) agrees with
  its value at \(z'\) on the overlap. A compatible unit family on a pointed cover glues to a global
  unit by the sheaf axiom (Theorem~\ref{thm:exists_global_unit_of_compatible}).
\end{proof}

\begin{theorem}[Coherence of the \(\sigma\)-normalized comparison]
  \label{thm:normalizedComparison_coherent}
  \lean{AlgebraicGeometry.NormalizedCechComparison.coherent}
  \uses{def:normalizedCechComparison, thm:exists_glued_productDefect, lem:sectionSquares,
    thm:unitsAppTop_sectionOfPoint_bijective, def:module_descent_cocycle}
  \leanok
  \source{kleiman-picard}
  Let the curve \(C\) be proper, geometrically irreducible and geometrically reduced. Then the
  comparison cochain \(\theta\) of a \(\sigma\)-normalized comparison of \(\gamma\) satisfies the
  Amitsur cocycle identity on the nose:
  \[
    (w_{23}^{\sharp}\theta)\,(w_{12}^{\sharp}\theta) \;=\; w_{13}^{\sharp}\theta ,
  \]
  in the face convention of the descent \(1\)-cocycle (Definition~\ref{def:module_descent_cocycle}).
  No faithful flatness is required.
\end{theorem}
\begin{proof}
  \leanok
  By \textbf{(N1)} the Amitsur defect \(\varepsilon\) of \(\theta\) glues to a global unit
  \(\bar\varepsilon\) of \(X_{B \otimes_A (B \otimes_A B)}\)
  (Theorem~\ref{thm:exists_glued_productDefect}). We claim its \(\sigma\)-restriction is \(1\).
  Pull the glued identity back along the section \(s_{\mathrm{cb}}\) over the triple base: by the
  section squares \(s_{\mathrm{cb}} \circ w_{ij} = f_{ij} \circ s_q\)
  (Lemma~\ref{lem:sectionSquares}) the three coface pullbacks of \(\theta\) become the coface
  pullbacks \(f_{ij}^{\sharp}\) of the \(\sigma\)-restriction of \(\theta\). Now \textbf{(N2)}
  rewrites the \(\sigma\)-restriction of \(\theta\) as the \(\rho\)-comparison \(q_1^{\sharp}\rho /
  q_2^{\sharp}\rho\); substituting, the three coface pullbacks become three ratios of
  \(\rho\)-terms whose endpoints match up through the simplicial coincidences \(f_{12} \circ q_2 =
  f_{23} \circ q_1\), \(f_{13} \circ q_1 = f_{12} \circ q_1\), \(f_{13} \circ q_2 = f_{23} \circ
  q_2\). These telescope to \(1\); hence the \(\sigma\)-restriction of \(\bar\varepsilon\) is \(1\).
  Finally, at the affine test \(B \otimes_A (B \otimes_A B)\), rigidity
  (Theorem~\ref{thm:unitsAppTop_sectionOfPoint_bijective}) forces a global unit with trivial
  \(\sigma\)-restriction to be \(1\), so \(\bar\varepsilon = 1\), i.e.\ \(\varepsilon = 1\), which is
  the claimed identity. This is Kleiman's descent-cocycle step: the automorphism
  \(v_{13}^{-1}v_{23}v_{12}\) of the first-projection pullback of the rigidified pair is trivial.
\end{proof}

\begin{theorem}[Uniqueness of the \(\sigma\)-normalized comparison]
  \label{thm:normalizedComparison_unique}
  \lean{AlgebraicGeometry.Over.normalizedComparison_unique}
  \uses{def:normalizedCechComparison, thm:exists_global_unit_of_compatible,
    thm:unitsAppTop_sectionOfPoint_bijective}
  \leanok
  \source{kleiman-picard}
  Let the curve \(C\) be proper, geometrically irreducible and geometrically reduced. Two comparison
  cochains \(\theta, \theta'\) on the same cover \(\mathcal W\), each satisfying \textbf{(N1)}
  against the same cocycle \(\gamma\) and \textbf{(N2)} against the same trivializing cochain
  \(\rho\), are equal.
\end{theorem}
\begin{proof}
  \leanok
  The ratio \(\theta/\theta'\) has trivial coboundary: since \(\theta\) and \(\theta'\) cobound the
  same comparison of \(\gamma\) (both satisfy \textbf{(N1)}), the overlap discrepancies of
  \(\theta\) and \(\theta'\) coincide and cancel in the ratio. Hence \(\theta/\theta'\) is \v
  Cech-compatible and glues to a global unit \(\chi\) of \(X_{B \otimes_A B}\)
  (Theorem~\ref{thm:exists_global_unit_of_compatible}). Its \(\sigma\)-restriction is \(1\): by
  \textbf{(N2)} both \(s_q^{\sharp}\theta\) and \(s_q^{\sharp}\theta'\) equal the same
  \(\rho\)-comparison \(q_1^{\sharp}\rho / q_2^{\sharp}\rho\) on the normalization cover, so their
  ratio restricts to \(1\). Rigidity (Theorem~\ref{thm:unitsAppTop_sectionOfPoint_bijective}) at the
  affine test \(B \otimes_A B\) forces \(\chi = 1\); reading this pointwise gives \(\theta =
  \theta'\).
\end{proof}

\begin{theorem}[The diagonal pullback of a witness glues to a global unit]
  \label{thm:exists_glued_diagonalSeed}
  \lean{AlgebraicGeometry.Over.exists_glued_diagonalSeed,
    AlgebraicGeometry.tensorLmul'_comp_tensorInl, AlgebraicGeometry.tensorLmul'_comp_tensorInr,
    AlgebraicGeometry.Over.whiskerLeft_lmul'_inl, AlgebraicGeometry.Over.whiskerLeft_lmul'_inr}
  \uses{def:normalizedCechComparison, def:tensorInl_tensorInr, thm:exists_global_unit_of_compatible}
  \leanok
  The multiplication \(\nabla \colon B \otimes_A B \to B\) retracts both coprojections, \(\nabla
  \circ q_1 = \id = \nabla \circ q_2\); whiskered to the curve this is \(u_1 \circ \Delta = \id =
  u_2 \circ \Delta\), where \(\Delta \colon X_B \to X_{B \otimes_A B}\) is the diagonal (the
  whiskered \(\Spec\) of \(\nabla\)). Consequently, for a comparison cochain \(\theta_0\) satisfying
  \textbf{(N1)}, the diagonal pullback \(\Delta^{\sharp}\theta_0\) is \v Cech-compatible and glues to
  a global unit \(\bar d \in \Gamma(X_B, \top)^{\times}\). No geometric hypotheses.
\end{theorem}
\begin{proof}
  \leanok
  The retractions are the identities \(\nabla(b \otimes 1) = b\) and \(\nabla(1 \otimes b) = b\);
  whiskering the resulting equalities of \(A\)-algebra maps to the curve gives \(u_1 \circ \Delta =
  \id = u_2 \circ \Delta\). Pull \textbf{(N1)} back along \(\Delta\): both insertion terms of the
  pulled relation are \(\gamma\) evaluated along \(u_1 \circ \Delta = u_2 \circ \Delta\), hence
  coincide and cancel, leaving \(\Delta^{\sharp}\theta_0\) with matching overlap values. Gluing by
  the sheaf axiom (Theorem~\ref{thm:exists_global_unit_of_compatible}) yields \(\bar d\).
\end{proof}

\begin{theorem}[Triviality of the comparison on the diagonal]
  \label{thm:normalizedComparison_diagonal_eq_one}
  \lean{AlgebraicGeometry.Over.normalizedComparison_diagonal_eq_one}
  \uses{def:normalizedCechComparison, thm:exists_glued_diagonalSeed, lem:sectionSquares,
    thm:unitsAppTop_sectionOfPoint_bijective}
  \leanok
  \source{kleiman-picard}
  Let the curve \(C\) be proper, geometrically irreducible and geometrically reduced. The pullback
  of the comparison cochain \(\theta\) of a \(\sigma\)-normalized comparison along the diagonal
  \(\Delta\) of \(X_{B \otimes_A B}\) is trivial: \(\Delta^{\sharp}\theta = 1\). This is the
  cochain source of the diagonal normalization \(\mu(u) = 1\) of the descent \(1\)-cocycle.
\end{theorem}
\begin{proof}
  \leanok
  Glue the diagonal seed of \(\theta\) to a global unit \(\bar d\) of \(X_B\)
  (Theorem~\ref{thm:exists_glued_diagonalSeed}). Its \(\sigma\)-restriction is \(1\): the section
  square relating \(s_B\), \(\Delta\), the \(\Spec\) of \(\nabla\) and \(s_q\)
  (Lemma~\ref{lem:sectionSquares}) turns it into the \(\nabla\)-pullback of the
  \(\sigma\)-restriction of \(\theta\), which \textbf{(N2)} makes the \(\nabla\)-pullback of the
  \(\rho\)-comparison \(q_1^{\sharp}\rho / q_2^{\sharp}\rho\); the two legs coincide on the diagonal
  because the multiplication retracts both coprojections
  (Theorem~\ref{thm:exists_glued_diagonalSeed}), so the comparison collapses to \(1\). Rigidity
  (Theorem~\ref{thm:unitsAppTop_sectionOfPoint_bijective}) at the affine test \(B\) forces \(\bar d
  = 1\); pointwise this is \(\Delta^{\sharp}\theta = 1\).
\end{proof}

\section{The per-piece descent datum}
\label{sec:effectivityDescentDatum}

The \(\sigma\)-normalized comparison is descended piece by piece over a \(\mathrm{cg}\)-saturated
affine cover of the base curve \(X_A\). On a piece \(V\) the cover-piece ring is \(M := S \otimes_A
B\) with \(S := \Gamma(X_A, U)\) the base-piece ring (Definition~\ref{def:pieceAlgEquiv}), and the
descent along \(S \to M\) is governed by the piece restriction of the comparison. This section
records the pure-algebra bridge: the identification of the descent-cocycle ring with the geometric
double-base ring, and the extraction of a descent \(1\)-cocycle from a comparison unit in geometric
coordinates. Throughout, \(A\) is a commutative ring, \(S\) and \(B\) are \(A\)-algebras, and \(M =
S \otimes_A B\).

\begin{definition}[The descent-cocycle ring identification]
  \label{def:pieceDescentEquiv}
  \lean{Algebra.TensorProduct.pieceDescentEquiv, Algebra.TensorProduct.pieceDescentTripleEquiv}
  \uses{def:module_descent_cocycle}
  \leanok
  The ring \(M \otimes_S M\) in which a descent \(1\)-cocycle relative to \(S \to M\)
  (Definition~\ref{def:module_descent_cocycle}) lives is the base change to \(S\) of the whole-cover
  descent-cocycle ring \(B \otimes_A B\): there is an \(S\)-algebra isomorphism
  \[
    M \otimes_S M \;\xrightarrow{\ \sim\ }\; S \otimes_A (B \otimes_A B), \qquad
    (s_1 \otimes b_1) \otimes (s_2 \otimes b_2) \;\longmapsto\; (s_2 s_1) \otimes (b_1 \otimes b_2),
  \]
  together with its triple analogue \(M \otimes_S (M \otimes_S M) \xrightarrow{\sim} S \otimes_A (B
  \otimes_A (B \otimes_A B))\).
\end{definition}
\begin{proof}
  \leanok
  The map is the composite of the cancellation of the middle base ring, \((S \otimes_A B)
  \otimes_S (S \otimes_A B) \cong S \otimes_A (S \otimes_A B) \cong (S \otimes_A S) \otimes_A B\)
  contracted along \(S \otimes_A S \to S\), with the associativity isomorphism of the iterated
  tensor product; the displayed value on pure tensors is read off from these two standard
  isomorphisms. The triple form is obtained by applying the same identification in the inner two
  factors and then cancelling and reassociating.
\end{proof}

\begin{lemma}[Compatibility with the multiplication and the cofaces]
  \label{lem:pieceDescentEquiv_faces}
  \lean{Algebra.TensorProduct.pieceDescentEquiv_lmul',
    Algebra.TensorProduct.pieceDescentTripleEquiv_descentFace₂₃,
    Algebra.TensorProduct.pieceDescentTripleEquiv_descentFace₁₂,
    Algebra.TensorProduct.pieceDescentTripleEquiv_descentFace₁₃}
  \uses{def:pieceDescentEquiv, def:module_descent_cocycle}
  \leanok
  Under the identification of Definition~\ref{def:pieceDescentEquiv}, the multiplication
  \(\mu \colon M \otimes_S M \to M\) corresponds to \(\id_S \otimes \mu\) on \(S \otimes_A (B
  \otimes_A B)\), and the three cofaces \(\partial_{23}, \partial_{12}, \partial_{13}\) of \(M
  \otimes_S M\) correspond to \(\id_S \otimes \partial_{23}, \id_S \otimes \partial_{12}, \id_S
  \otimes \partial_{13}\) on \(S \otimes_A (B \otimes_A (B \otimes_A B))\).
\end{lemma}
\begin{proof}
  \leanok
  Each is an identity between two \(S\)-algebra maps out of \(M \otimes_S M\); it therefore suffices
  to check it on pure tensors, where both sides evaluate to the same element by the computation of
  Definition~\ref{def:pieceDescentEquiv}, and to extend by bilinearity.
\end{proof}

\begin{theorem}[A coherent comparison unit is a descent \(1\)-cocycle]
  \label{thm:isDescentCocycle_comparisonDescentUnit}
  \lean{Module.comparisonDescentUnit, Module.isDescentCocycle_comparisonDescentUnit}
  \uses{def:pieceDescentEquiv, lem:pieceDescentEquiv_faces, def:module_descent_cocycle}
  \leanok
  Let \(v \in (S \otimes_A (B \otimes_A B))^{\times}\) be a \emph{comparison unit} that is
  diagonal-normalized, \((\id_S \otimes \mu)(v) = 1\), and satisfies the Amitsur identity through
  the three cofaces,
  \[
    (\id_S \otimes \partial_{23})(v) \cdot (\id_S \otimes \partial_{12})(v) = (\id_S \otimes
    \partial_{13})(v) .
  \]
  Then the unit of \(M \otimes_S M\) that corresponds to \(v\) under
  Definition~\ref{def:pieceDescentEquiv} --- the \emph{comparison descent unit} --- is a descent
  \(1\)-cocycle relative to \(S \to M\) (Definition~\ref{def:module_descent_cocycle}).
\end{theorem}
\begin{proof}
  \leanok
  Transport the two hypotheses through the identification. By
  Lemma~\ref{lem:pieceDescentEquiv_faces} the normalization \(\mu\) of the comparison descent unit
  is carried to \((\id_S \otimes \mu)(v) = 1\), which is the normalization condition; and the
  cocycle product \(\partial_{23} \cdot \partial_{12}\) of the comparison descent unit is carried,
  through the triple identification, to \((\id_S \otimes \partial_{23})(v) \cdot (\id_S \otimes
  \partial_{12})(v) = (\id_S \otimes \partial_{13})(v)\), the image of \(\partial_{13}\). As the
  triple identification is injective, the cocycle identity holds.
\end{proof}

\begin{definition}[The descended per-piece class and its cover pullback]
  \label{def:comparisonDescentClass}
  \lean{Module.comparisonDescentClass, Module.mapAlgebra_comparisonDescentClass_eq_one,
    Module.IsDescentCocycle.mapAlgebra_picClass_eq_one}
  \uses{thm:isDescentCocycle_comparisonDescentUnit, def:module_picClass, def:module_descended}
  \leanok
  Assume \(A \to B\) is faithfully flat, and let \(v\) be a coherent comparison unit as in
  Theorem~\ref{thm:isDescentCocycle_comparisonDescentUnit}. The \emph{descended per-piece class}
  \(M_V \in \operatorname{Pic}(S)\) is the Picard class (Definition~\ref{def:module_picClass}) of the
  descent \(1\)-cocycle of the comparison descent unit. Its image under \(\operatorname{Pic}(S) \to
  \operatorname{Pic}(M)\) is trivial.
\end{definition}
\begin{proof}
  \leanok
  Faithful flatness passes from \(A \to B\) to \(S \to M = S \otimes_A B\) by base change, so the
  descent \(1\)-cocycle of the comparison descent unit has a well-defined Picard class
  (Definition~\ref{def:module_picClass}). Base change to \(M\) sends the descended module to \(M\)
  itself: the descended module of a cocycle is, by construction, the submodule of \(M\) on which the
  two coactions agree (Definition~\ref{def:module_descended}), and tensoring up to \(M\) recovers
  \(M\) as a free rank-one module through the descent isomorphism. Hence the class of \(M_V\) in
  \(\operatorname{Pic}(M)\) is that of a free module, namely \(1\).
\end{proof}

\begin{definition}[The geometric descent-cocycle ring identification]
  \label{def:pieceDescentGeom}
  \lean{AlgebraicGeometry.Over.pieceDescentTensorEquiv,
    AlgebraicGeometry.Over.pieceDescentCoverEquiv}
  \uses{def:pieceAlgEquiv, def:pieceDescentEquiv}
  \leanok
  For a \(\mathrm{cg}\)-saturated affine piece \(U \subseteq X_A\), with base-piece ring \(\Gamma(X_A,
  U)\) and cover-piece ring \(\Gamma(X_B, \mathrm{cg}^{-1}U)\), the descent-cocycle ring
  \(\Gamma(X_B, \mathrm{cg}^{-1}U) \otimes_{\Gamma(X_A, U)} \Gamma(X_B, \mathrm{cg}^{-1}U)\) is
  identified, as a \(\Gamma(X_A, U)\)-algebra, with \(\Gamma(X_A, U) \otimes_A (B \otimes_A B)\), and
  hence with the section ring \(\Gamma(X_{B \otimes_A B}, \mathrm{cgq}^{-1}U)\) of the curve over the
  descent-cocycle base --- the ring on whose spectrum the piece restriction of the comparison lives.
\end{definition}
\begin{proof}
  \leanok
  Apply the piece identification \(\Gamma(X_B, \mathrm{cg}^{-1}U) \cong \Gamma(X_A, U) \otimes_A B\)
  (Definition~\ref{def:pieceAlgEquiv}) to each tensor factor, then the algebraic descent-cocycle
  ring identification (Definition~\ref{def:pieceDescentEquiv}) with \(S = \Gamma(X_A, U)\); this
  gives the first identification. For the second, apply the piece identification at the test algebra
  \(B \otimes_A B\), giving \(\Gamma(X_A, U) \otimes_A (B \otimes_A B) \cong \Gamma(X_{B \otimes_A
  B}, \mathrm{cgq}^{-1}U)\).
\end{proof}

\section{The per-piece comparison unit and its descended class}
\label{sec:effectivityComparisonUnit}

We continue with the \((C2)\) data: a commutative ring \(A\), an \(A\)-algebra \(B\), the curve
\(C\) over \(\Spec k\), and the cover inclusion \(\mathrm{cg} \colon X_B \to X_A\) (the whiskering
\(C \lhd \Spec(A \to B)\)), with \(\mathrm{cgq} \colon X_{B \otimes_A B} \to X_A\) its double, and
\(u_1, u_2 \colon X_{B \otimes_A B} \to X_B\) the coprojections. A rigidified class \(L =
[\gamma]\) on \(X_B\) is descended \emph{piece by piece} over \(\mathrm{cg}\)-saturated affine opens
\(V\) of \(X_A\). This section manufactures, on each such piece equipped with a trivialization of
\(L\), the comparison unit that the per-piece descent extraction (brick E2) consumes, and its
descended class.

\begin{definition}[A piece trivialization]
  \label{def:pieceTrivialization}
  \lean{AlgebraicGeometry.Over.PieceTrivialization, AlgebraicGeometry.Over.whiskerLeft_inl_comp_cover,
    AlgebraicGeometry.Over.whiskerLeft_inr_comp_cover, AlgebraicGeometry.Over.cgqPreimage_le_inl,
    AlgebraicGeometry.Over.cgqPreimage_le_inr}
  \uses{def:tensorInl_tensorInr, cor:cechPic_mk_eq_one}
  \leanok
  A \emph{piece trivialization} of a representing cocycle \(\gamma\) on a pointed cover \(\mathcal N\)
  of \(X_B\), over a piece \(V \subseteq X_A\), is a trivializing \(0\)-cochain \(t\) of \(\gamma\)
  on the \(\mathrm{cg}^{-1}V\)-trimmed opens: units \(t_b \in \Gamma(X_B, \mathcal N(b) \cap
  \mathrm{cg}^{-1}V)^{\times}\) with \(t_b \cdot \gamma_{b b'} = t_{b'}\) on the trimmed pairwise
  overlaps. It is the cochain witness that the class \(L = [\gamma]\) is trivial on the cover piece
  \(\mathrm{cg}^{-1}V\) (\ref{cor:cechPic_mk_eq_one}); its existence over a covering family of pieces
  is the piece-selection input consumed by the final splice. The two coprojections both lie over the
  cover inclusions, \(u_1 \circ \mathrm{cg} = \mathrm{cgq} = u_2 \circ \mathrm{cg}\) as maps to
  \(X_A\), so the double piece is bounded by each coprojection preimage of the piece,
  \(\mathrm{cgq}^{-1}V \le u_i^{-1}(\mathrm{cg}^{-1}V)\).
\end{definition}
\begin{proof}
  \leanok
  The two coprojection identities are the whiskerings of \(q_i \circ (A \to B) = (A \to B \otimes_A
  B)\) as \(A\)-algebra maps (Definition~\ref{def:tensorInl_tensorInr}); whiskering to the curve and
  passing to preimages gives \(\mathrm{cgq}^{-1}V \le u_i^{-1}(\mathrm{cg}^{-1}V)\).
\end{proof}

\begin{theorem}[The trivialization-twisted witness glues to a unit]
  \label{thm:exists_glued_unitsTrivTwist}
  \lean{AlgebraicGeometry.unitsTrivTwistCochain, AlgebraicGeometry.unitsTrivTwistCochain_compat,
    AlgebraicGeometry.exists_glued_unitsTrivTwist,
    AlgebraicGeometry.Scheme.Hom.unitsAppLE_glued_trivTwist}
  \uses{thm:exists_global_unit_of_compatible}
  \leanok
  Over abstract schemes, let \(r_1, r_2 \colon Y \to Z\), let \(\mathcal C\) be a pointed cover of
  \(Y\) and \(\mathcal N\) one of \(Z\), let \(c\) be a comparison \(0\)-cochain on \(\mathcal C\)
  and \(E\) a pair-indexed unit family on \(\mathcal N\), and let \(t\) trivialize \(E\) on the
  \(DZ\)-trimmed opens of \(\mathcal N\), for opens \(DZ \subseteq Z\), \(DY \subseteq Y\) with
  \(DY \le r_i^{-1}DZ\). Define the \emph{twisted value} at \(y\), on \(\mathcal C(y) \cap DY\),
  \[
    (c_y) \cdot \bigl(r_2^{\sharp}t\bigr)_y \cdot \bigl(r_1^{\sharp}t\bigr)_y^{-1} .
  \]
  If \(c\) cobounds the two pullbacks of \(E\) (the relation \(c_x \cdot (r_1^{\sharp}E)_{xy} =
  (r_2^{\sharp}E)_{xy} \cdot c_y\)) and \(t\) satisfies the trivializing relation, then the twisted
  values are \v Cech-compatible on the trimmed cover \(\{\mathcal C(y) \cap DY\}\) of \(DY\), hence
  glue to a global unit \(v \in \Gamma(Y, DY)^{\times}\); and for a further map \(\varphi\) into
  \(Y\) with \(\varphi \circ r_i = m_i\), the \(\varphi\)-pullback of \(v\) expands into the pulled
  witness value \(\varphi^{\sharp}c\) times the two \(m_i\)-pullbacks of \(t\).
\end{theorem}
\begin{proof}
  \leanok
  Compatibility is a telescoping identity: on a pairwise overlap the coboundary relation for \(c\)
  and the two pullbacks of the trivializing relation for \(t\) (along \(r_1\) and \(r_2\)) combine so
  that the \(E\)-terms cancel and the twisted value at \(y\) matches that at \(y'\). A compatible
  unit family on a pointed cover glues to a global unit by the sheaf axiom
  (Theorem~\ref{thm:exists_global_unit_of_compatible}). The pullback expansion is the defining
  gluing relation pulled back along \(\varphi\), with the composites \(\varphi \circ r_i = m_i\)
  merging the two pullbacks.
\end{proof}

\begin{theorem}[The per-piece comparison unit]
  \label{thm:pieceComparisonUnit}
  \lean{AlgebraicGeometry.Over.pieceComparisonUnit, AlgebraicGeometry.Over.pieceComparisonUnit_spec,
    AlgebraicGeometry.Over.pieceComparisonUnit_unique}
  \uses{thm:exists_glued_unitsTrivTwist, def:pieceTrivialization, def:normalizedCechComparison}
  \leanok
  Let \(W\) be a \(\sigma\)-normalized comparison of \(\gamma\)
  (Definition~\ref{def:normalizedCechComparison}) with comparison cochain \(\theta\), and \(T\) a
  piece trivialization of \(\gamma\) on \(V\). The \emph{per-piece comparison unit}
  \[
    v_V \;\in\; \Gamma\bigl(X_{B \otimes_A B},\, \mathrm{cgq}^{-1}V\bigr)^{\times}
  \]
  is the global unit glued from the values \(\theta_x \cdot (u_2^{\sharp}T)(x) /
  (u_1^{\sharp}T)(x)\) on the trimmed comparison cover: on each member it restricts to that twisted
  witness value. It is the unique unit of the double piece with this restriction property.
\end{theorem}
\begin{proof}
  \leanok
  Apply Theorem~\ref{thm:exists_glued_unitsTrivTwist} with \(r_1, r_2 = u_1, u_2\), comparison
  cover \(\mathcal C = W.\mathrm{cover}\), representing cover \(\mathcal N\), comparison cochain
  \(c = \theta\), pair family \(E = \gamma\), trimming opens \(DZ = \mathrm{cg}^{-1}V\), \(DY =
  \mathrm{cgq}^{-1}V\), and trivialization \(t = T\): the coboundary relation for \(\theta\) is the
  \((N1)\) witness relation of the normalized comparison, and the trivializing relation is that of
  the piece trivialization (Definition~\ref{def:pieceTrivialization}). Gluing yields \(v_V\) and its
  defining restriction property. Uniqueness is the separation half of the sheaf axiom: two units of
  \(\mathrm{cgq}^{-1}V\) with the same restrictions to a cover agree.
\end{proof}

\begin{theorem}[Naturality of the section-ring identification in the algebra]
  \label{thm:pieceRingEquiv_whiskerLeft_naturality}
  \lean{AlgebraicGeometry.Over.pieceRingEquiv_whiskerLeft_naturality,
    AlgebraicGeometry.Over.map_pieceEquiv_eq_pieceEquiv_whiskerLeft,
    AlgebraicGeometry.Over.whiskerLeft_overSpecMap_comp_cover,
    AlgebraicGeometry.Over.coverPreimage_le_whiskerLeft,
    AlgebraicGeometry.Over.restrictScalars_comp_ofId,
    AlgebraicGeometry.Over.pieceRingEquiv_pieceEquiv}
  \uses{def:pieceRingEquiv, def:pieceAlgEquiv, thm:pieceRingEquiv_naturality}
  \leanok
  The section-ring identification \(\Gamma(X_R, \mathrm{cg}_R^{-1}V) \cong \Gamma(X_A, V)
  \otimes_A R\) (Definition~\ref{def:pieceRingEquiv}, \(R\)-uniform) is natural in the base algebra:
  for an \(A\)-algebra map \(j \colon R \to R'\), the whiskered map \(W_j = (C \lhd \Spec\, j) \colon
  X_{R'} \to X_R\) lies over the cover structure maps (\(W_j \circ \mathrm{cg}_R = \mathrm{cg}_{R'}\)),
  and pulling identified sections back along \(W_j\) is \(\id_{\Gamma(X_A, V)} \otimes j\) through the
  identifications of the two pieces:
  \[
    W_j^{\sharp}\bigl(\Phi^R_V(x)\bigr) \;=\; \Phi^{R'}_V\bigl((\id \otimes j)(x)\bigr) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both sides are \(A\)-algebra homomorphisms out of \(\Gamma(X_A, V) \otimes_A R\), so it suffices to
  check them on a pure tensor \(s \otimes r\), then extend by bilinearity. There the identification
  sends \(s \otimes r\) to \(\mathrm{cg}_R^{\sharp}(s) \cdot \mathrm{pr}_R^{\sharp}(r)\)
  (Definition~\ref{def:pieceRingEquiv}). The \(\mathrm{cg}\)-factor pulls back along \(W_j\) by the
  composite \(W_j \circ \mathrm{cg}_R = \mathrm{cg}_{R'}\) (as \(A\)-algebra maps, \(j \circ (A \to R)
  = (A \to R')\)), giving \(\mathrm{cg}_{R'}^{\sharp}(s)\). The projection factor pulls back along the
  square \(W_j \circ \mathrm{pr}_R = \mathrm{pr}_{R'} \circ \Spec\, j\), and the \(\Spec\)-side factor
  is the naturality of \(\Gamma\)-of-\(\Spec\) applied to \(j\), giving \(\mathrm{pr}_{R'}^{\sharp}(j
  r)\). Their product is \(\Phi^{R'}_V(s \otimes j r) = \Phi^{R'}_V((\id \otimes j)(s \otimes r))\).
  This is the algebra-variable mirror of the open-variable restriction seam
  (Theorem~\ref{thm:pieceRingEquiv_naturality}).
\end{proof}

\begin{theorem}[Diagonal triviality of the comparison unit]
  \label{thm:pieceComparisonUnit_diagonal_eq_one}
  \lean{AlgebraicGeometry.Over.pieceComparisonUnit_diagonal_eq_one}
  \uses{thm:pieceComparisonUnit, thm:normalizedComparison_diagonal_eq_one,
    thm:exists_glued_diagonalSeed}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be proper, geometrically irreducible and geometrically reduced. The pullback of the
  per-piece comparison unit \(v_V\) along the diagonal \(\Delta = (C \lhd \Spec\, \nabla) \colon X_B
  \to X_{B \otimes_A B}\) (\(\nabla\) the multiplication of \(B \otimes_A B\)) is \(1\).
\end{theorem}
\begin{proof}
  \leanok
  Work locally on the diagonal pullback of the comparison cover. The multiplication retracts both
  coprojections, \(\Delta \circ u_1 = \id = \Delta \circ u_2\) whiskered
  (Theorem~\ref{thm:exists_glued_diagonalSeed}), so the pullback expansion of \(v_V\)
  (Theorem~\ref{thm:exists_glued_unitsTrivTwist}, with \(\varphi = \Delta\) and \(m_1 = m_2 = \id\))
  gives the diagonal witness value \(\Delta^{\sharp}\theta\) times two trivialization factors along
  the \emph{same} insertion, which cancel. The remaining witness factor \(\Delta^{\sharp}\theta = 1\)
  is the landed diagonal triviality of the \(\sigma\)-normalized comparison
  (Theorem~\ref{thm:normalizedComparison_diagonal_eq_one}). So the local value is \(1\); by sheaf
  separation the diagonal pullback of \(v_V\) is \(1\). This is the cochain form of the diagonal
  normalization in Kleiman's descent-cocycle step.
\end{proof}

\begin{theorem}[Amitsur coherence of the comparison unit]
  \label{thm:pieceComparisonUnit_coherent}
  \lean{AlgebraicGeometry.Over.pieceComparisonUnit_coherent,
    AlgebraicGeometry.Over.pieceAmitsurOpen}
  \uses{thm:pieceComparisonUnit, thm:normalizedComparison_coherent, def:amitsurProductCover}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be proper, geometrically irreducible and geometrically reduced. The three coface
  pullbacks of \(v_V\) to the triple piece \(\Gamma(X_{B \otimes_A (B \otimes_A B)},
  \mathrm{cgcb}^{-1}V)^{\times}\) satisfy the Amitsur cocycle identity on the nose:
  \[
    \bigl(w_{23}^{\sharp}v_V\bigr)\bigl(w_{12}^{\sharp}v_V\bigr) \;=\; w_{13}^{\sharp}v_V .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Work locally on the trimmed Amitsur product cover of \(X_{B \otimes_A (B \otimes_A B)}\)
  (Definition~\ref{def:amitsurProductCover}). By the pullback expansion
  (Theorem~\ref{thm:exists_glued_unitsTrivTwist}) each coface pullback \(w_{ij}^{\sharp}v_V\) is the
  coface pullback of the witness \(\theta\) times two insertion pullbacks of the trivialization; the
  three tensor-slot insertions \(v_1, v_2, v_3\) are common to numerator and denominator, so the
  trivialization factors telescope, \((T_{23}\,t_c\,t_b^{-1})(T_{12}\,t_b\,t_a^{-1}) =
  T_{23}T_{12}\,t_c\,t_a^{-1}\). The landed coherence (Theorem~\ref{thm:normalizedComparison_coherent})
  supplies \((w_{23}^{\sharp}\theta)(w_{12}^{\sharp}\theta) = w_{13}^{\sharp}\theta\), so the two
  sides agree locally; by sheaf separation the identity holds globally. This is Kleiman's
  descent-cocycle identity \(v_{13}^{-1}v_{23}v_{12} = 1\).
\end{proof}

\begin{theorem}[The transported comparison unit and its descent hypotheses]
  \label{thm:pieceComparisonTensorUnit}
  \lean{AlgebraicGeometry.Over.pieceComparisonTensorUnit,
    AlgebraicGeometry.Over.pieceComparisonTensorUnit_val,
    AlgebraicGeometry.Over.pieceComparisonTensorUnit_lmul,
    AlgebraicGeometry.Over.pieceComparisonTensorUnit_cocycle}
  \uses{thm:pieceComparisonUnit, thm:pieceRingEquiv_whiskerLeft_naturality,
    thm:pieceComparisonUnit_diagonal_eq_one, thm:pieceComparisonUnit_coherent, def:pieceAlgEquiv,
    def:pieceDescentEquiv}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced. Through the section-ring
  identification \(\Gamma(X_{B \otimes_A B}, \mathrm{cgq}^{-1}V) \cong \Gamma(X_A, V) \otimes_A (B
  \otimes_A B)\) (Definition~\ref{def:pieceAlgEquiv}), the comparison unit \(v_V\) is a unit
  \(\tilde v_V \in (\Gamma(X_A, V) \otimes_A (B \otimes_A B))^{\times}\) of the descent-cocycle ring.
  It is diagonal-normalized and Amitsur-coherent through the maps of the descent \(1\)-cocycle:
  \[
    (\id \otimes \mu)(\tilde v_V) = 1, \qquad
    (\id \otimes \partial_{23})(\tilde v_V)\,(\id \otimes \partial_{12})(\tilde v_V)
      = (\id \otimes \partial_{13})(\tilde v_V) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  The whiskered maps \(\Delta\) and \(w_{ij}\) are the whiskerings of \(\Spec\) of \(\mu\) and the
  three cofaces \(\partial_{ij}\); so by the algebra-naturality of the identification
  (Theorem~\ref{thm:pieceRingEquiv_whiskerLeft_naturality}) the map \(\id \otimes \mu\) applied to
  \(\tilde v_V\) equals the transport of the diagonal pullback \(\Delta^{\sharp}v_V = 1\)
  (Theorem~\ref{thm:pieceComparisonUnit_diagonal_eq_one}), and likewise the three \(\id \otimes
  \partial_{ij}\) applied to \(\tilde v_V\) are the transports of the three coface pullbacks of
  \(v_V\). The cocycle identity of the coface pullbacks
  (Theorem~\ref{thm:pieceComparisonUnit_coherent}) therefore transports to the stated identity of
  the three \(\id \otimes \partial_{ij}\) images (Definition~\ref{def:pieceDescentEquiv}).
\end{proof}

\begin{theorem}[The descended per-piece class and its cover pullback]
  \label{def:pieceDescentClass}
  \lean{AlgebraicGeometry.Over.pieceDescentClass,
    AlgebraicGeometry.Over.mapAlgebra_pieceDescentClass_eq_one}
  \uses{thm:pieceComparisonTensorUnit, thm:isDescentCocycle_comparisonDescentUnit,
    def:comparisonDescentClass}
  \leanok
  Assume in addition \(A \to B\) is faithfully flat. The \emph{descended per-piece class}
  \[
    M_V \;\in\; \operatorname{Pic}\bigl(\Gamma(X_A, V)\bigr)
  \]
  is the Picard class of the descent \(1\)-cocycle of the transported comparison unit \(\tilde v_V\),
  whose diagonal-normalization and coherence are those of
  Theorem~\ref{thm:pieceComparisonTensorUnit}. Its pullback to the cover-piece ring \(\Gamma(X_A, V)
  \otimes_A B \cong \Gamma(X_B, \mathrm{cg}^{-1}V)\) is trivial.
\end{theorem}
\begin{proof}
  \leanok
  Faithful flatness of \(A \to B\) passes to \(\Gamma(X_A, V) \to \Gamma(X_A, V) \otimes_A B\) by
  base change, so the coherent comparison unit \(\tilde v_V\)
  (Theorem~\ref{thm:pieceComparisonTensorUnit}) is a descent \(1\)-cocycle
  (Theorem~\ref{thm:isDescentCocycle_comparisonDescentUnit}) with a well-defined Picard class
  \(M_V\) (Definition~\ref{def:comparisonDescentClass}); the same definition records that its base
  change to the cover-piece ring is the trivial class.
\end{proof}

\begin{theorem}[The piece restriction of the descending class is trivial]
  \label{thm:cechPicMap_pieceI_eq_one}
  \lean{AlgebraicGeometry.Scheme.Hom.pullbackUnitsCocycle_isCohomologous_one,
    AlgebraicGeometry.Over.cechPicMap_pieceι_eq_one}
  \uses{def:pieceTrivialization, cor:cechPic_mk_eq_one}
  \leanok
  The class \(L = [\gamma]\) of the \((C2)\) setting, restricted to the open subscheme
  \(\mathrm{cg}^{-1}V\), is trivial: \(\iota^{*}L = 1\) for the open immersion \(\iota \colon
  \mathrm{cg}^{-1}V \hookrightarrow X_B\). Together with the cover-pullback triviality of
  \(M_V\) (Theorem~\ref{def:pieceDescentClass}), this is the recovery identity \(\mathrm{cg}^{*}M_V
  = [L|_{\mathrm{cg}^{-1}V}]\), both sides trivial by construction.
\end{theorem}
\begin{proof}
  \leanok
  Over abstract schemes, if \(f^{-1}(DZ) = \top\) and a \(0\)-cochain \(t\) trivializes the pair
  values of \(\gamma\) on the \(DZ\)-trimmed opens, then the \(f\)-pullbacks of \(t\) cobound the
  pulled cocycle \(f^{\sharp}\gamma\) against \(1\), so \(f^{\sharp}\gamma\) is cohomologous to
  \(1\). Apply this to the open immersion \(\iota\) of the piece \(\mathrm{cg}^{-1}V\), whose
  self-preimage is \(\top\), with \(t = T.\mathrm{triv}\) the piece trivialization
  (Definition~\ref{def:pieceTrivialization}): the pulled cocycle is cohomologous to \(1\), hence its
  class is trivial (\ref{cor:cechPic_mk_eq_one}).
\end{proof}

\begin{theorem}[Base-change naturality of the descent extraction]
  \label{thm:comparisonDescentClass_mapAlgebra}
  \lean{Module.comparisonDescentUnit_baseChange, Module.comparisonDescentClass_mapAlgebra}
  \uses{def:comparisonDescentClass, thm:isDescentCocycle_comparisonDescentUnit,
    thm:module_descentCocycle_baseChange, thm:module_picClass_baseChange,
    def:module_tensorSqBaseChange, def:pieceDescentEquiv}
  \leanok
  Let \(S \to S'\) be a map of \(A\)-algebras and \(v\) a coherent comparison unit over \(S\). The
  class descended over \(S'\) from the base-changed comparison \((\mathrm{algebraMap} \otimes \id)(v)\)
  is the \(\operatorname{Pic}\)-image of the class descended over \(S\):
  \[
    \mathrm{comparisonDescentClass}_{S'}\bigl((\mathrm{algebraMap} \otimes \id)(v)\bigr)
      \;=\; \operatorname{Pic.mapAlgebra}_{S \to S'}\bigl(\mathrm{comparisonDescentClass}_S(v)\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  First, the comparison descent unit of the base-changed comparison is the image of the descent unit
  of \(v\) under the tensor-square base change along \(S \to S'\), identified through the
  base-change cancellation on each tensor factor: this is an elementwise computation on pure
  tensors, using the descent-cocycle ring identification (Definition~\ref{def:pieceDescentEquiv}) and
  the tensor-square base change (Definition~\ref{def:module_tensorSqBaseChange}). Now chain the
  descent extraction (Theorem~\ref{thm:isDescentCocycle_comparisonDescentUnit}): the \(S'\)-class is
  the class of the base-changed descent cocycle further mapped by the cancellation
  (\(\operatorname{picClass}\) is invariant under the mapping and under replacing a cocycle by a
  cohomologous one), which equals the class of the base-changed cocycle
  (Theorem~\ref{thm:module_descentCocycle_baseChange}), which in turn is the
  \(\operatorname{mapAlgebra}\)-image of the \(S\)-class
  (Theorem~\ref{thm:module_picClass_baseChange}).
\end{proof}

\begin{theorem}[Restriction canonicity of the descended per-piece classes]
  \label{thm:pieceDescentClass_res}
  \lean{AlgebraicGeometry.Over.PieceTrivialization.res, AlgebraicGeometry.Over.pieceComparisonUnit_res,
    AlgebraicGeometry.Over.pieceComparisonTensorUnit_res,
    AlgebraicGeometry.Over.pieceDescentClass_res}
  \uses{def:pieceDescentClass, thm:comparisonDescentClass_mapAlgebra, thm:pieceComparisonUnit,
    thm:pieceComparisonTensorUnit, thm:pieceRingEquiv_naturality}
  \leanok
  Assume \(A \to B\) faithfully flat and \(C\) proper, geometrically irreducible and geometrically
  reduced. For affine pieces \(V' \le V\) of \(X_A\) and a piece trivialization \(T\) on \(V\): the
  trivialization restricts to one on \(V'\), the glued comparison unit of the restricted datum is the
  restriction of the glued unit, and the descended classes are natural in the piece,
  \[
    M_{V'} \;=\; \operatorname{Pic.mapAlgebra}_{\Gamma(X_A, V) \to \Gamma(X_A, V')}\,(M_V) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  The trivialization restricts by restricting each trimmed cochain value along \(\mathrm{cg}^{-1}V'
  \le \mathrm{cg}^{-1}V\), preserving the trivializing relation. Its comparison unit is the
  restriction of \(v_V\) by uniqueness of gluing (Theorem~\ref{thm:pieceComparisonUnit}): the
  restriction of \(v_V\) has the defining restriction property of the restricted datum. Through the
  section-ring identifications, this restriction is \(\mathrm{algebraMap} \otimes \id\) on the
  descent-cocycle ring, by the open-variable restriction seam
  (Theorem~\ref{thm:pieceRingEquiv_naturality}) applied to the transported unit
  (Theorem~\ref{thm:pieceComparisonTensorUnit}). Hence \(\tilde v_{V'}\) is the base change of
  \(\tilde v_V\) along \(\Gamma(X_A, V) \to \Gamma(X_A, V')\), and \(M_{V'}\) is the class of the
  base-changed unit, which by the base-change naturality of the extraction
  (Theorem~\ref{thm:comparisonDescentClass_mapAlgebra}) is
  \(\operatorname{mapAlgebra}(M_V)\). On an overlap of two pieces both descend from the same global
  \(\sigma\)-normalized comparison, so the descended classes agree through their common restriction:
  this is what the refinement-splice consumes.
\end{proof}

\section{Trivializing an invertible module away from finitely many primes}
\label{sec:effectivityInvertibleAvoid}

The pure-algebra core of the \((C2)\) piece-selection moving lemma. An invertible module over a
commutative ring becomes free after inverting a single element chosen to avoid any prescribed finite
set of primes; and, for an integral extension, an element of the extension avoiding every prime over
a base prime divides the image of a base element avoiding that prime --- the \emph{algebraic tube}.
These are the two bricks that convert triviality of a class on a basic open of the cover into a
basic open of the base.

\begin{lemma}[A cyclic invertible module is free]
  \label{lem:invertible_cyclic_free}
  \lean{Module.Invertible.bijective_toSpanSingleton_of_span_eq_top,
    Module.Invertible.free_of_span_singleton_eq_top}
  \leanok
  Let \(R\) be a commutative ring and \(N\) an invertible \(R\)-module generated by a single element
  \(m_0\), i.e.\ \(R \cdot m_0 = N\). Then the scalar map \(r \mapsto r \cdot m_0\) is an isomorphism
  \(R \xrightarrow{\sim} N\); in particular \(N\) is free of rank one.
\end{lemma}
\begin{proof}
  \leanok
  Surjectivity is the hypothesis \(R \cdot m_0 = N\). For injectivity, suppose \(r \cdot m_0 = 0\).
  Since \(m_0\) generates \(N\), \(r\) annihilates every element of \(N\), hence \(r \cdot \id_N = 0\)
  as an endomorphism, and therefore \(r\) annihilates every element of \(N^{\vee} \otimes_R N\) (the
  endomorphism acts through the right tensor factor). Invertibility of \(N\) means the contraction
  pairing \(N^{\vee} \otimes_R N \to R\) is surjective; choose \(w\) with \(\mathrm{contract}(w) = 1\).
  Then \(r = r \cdot \mathrm{contract}(w) = \mathrm{contract}(r \cdot w) = \mathrm{contract}(0) = 0\).
  So the scalar map is bijective, whence \(N \cong R\) is free.
\end{proof}

\begin{theorem}[The avoidance brick]
  \label{thm:invertible_avoid_free}
  \lean{Module.Invertible.exists_notMem_isUnit_free}
  \uses{lem:invertible_cyclic_free}
  \leanok
  Let \(R\) be a commutative ring, \(N\) an invertible \(R\)-module, and \((\mathfrak q_i)_{i \in I}\)
  a finite family of prime ideals of \(R\). Then there is an element \(f \in R\) with \(f \notin
  \mathfrak q_i\) for every \(i\) such that, for every \(R\)-algebra \(S\) in which \(f\) becomes a
  unit, the base change \(S \otimes_R N\) is a free \(S\)-module.
\end{theorem}
\begin{proof}
  \leanok
  If \(I = \varnothing\) there are no primes to avoid and the claim holds trivially; assume \(I\) is
  nonempty. Localize \(R\) at the multiplicative set \(S_0 := \bigcap_i (R \setminus \mathfrak q_i)\),
  the complement of \(\bigcup_i \mathfrak q_i\). Every maximal ideal of \(R_{S_0}\) is the
  localization of one of the \(\mathfrak q_i\): its contraction to \(R\) is a prime disjoint from
  \(S_0\), hence contained in \(\bigcup_i \mathfrak q_i\), hence --- by prime avoidance --- inside
  some \(\mathfrak q_i\), and maximality forces equality. Thus \(R_{S_0}\) is semilocal with finitely
  many maximal ideals, so its Picard group is trivial, and therefore \(S_0^{-1}N\) is a \emph{cyclic}
  \(R_{S_0}\)-module, generated by a single element \(z\).

  Fix finitely many generators \(g_1, \dots, g_n\) of \(N\) over \(R\), and write \(z = m_0 / s_0\)
  with \(m_0 \in N\), \(s_0 \in S_0\). Clearing denominators in the relations expressing each \(g_j\)
  as an \(R_{S_0}\)-multiple of \(z\) yields elements \(d_j \in S_0\) and \(r_j \in R\) with
  \(d_j \cdot g_j = r_j \cdot m_0\) in \(N\). Set \(f := \prod_j d_j\); each \(d_j \in S_0\) avoids
  every \(\mathfrak q_i\), and a prime containing a product contains a factor, so \(f\) avoids every
  \(\mathfrak q_i\).

  Now let \(S\) be an \(R\)-algebra in which \(f\) is a unit. In \(S \otimes_R N\) each \(1 \otimes
  g_j\) lies in the \(S\)-span of \(1 \otimes m_0\): from \((\prod_l d_l)\cdot g_j = \bigl(\prod_{l
  \ne j} d_l\bigr) r_j \cdot m_0\), inverting the unit \(f = \prod_l d_l\) expresses \(1 \otimes g_j\)
  as an \(S\)-multiple of \(1 \otimes m_0\). Since the \(g_j\) generate \(N\), every pure tensor
  \(1 \otimes x\) --- and hence all of \(S \otimes_R N\) --- lies in the \(S\)-span of \(1 \otimes
  m_0\). So \(S \otimes_R N\) is cyclic, and invertible because invertibility is preserved by base
  change; by Lemma~\ref{lem:invertible_cyclic_free} it is free.
\end{proof}

\begin{lemma}[The algebraic tube]
  \label{lem:algebraic_tube}
  \lean{Algebra.exists_notMem_algebraMap_eq_mul}
  \leanok
  Let \(S \to R\) be an integral extension of commutative rings, \(\mathfrak p\) a prime of \(S\),
  and \(f \in R\) an element avoiding every prime of \(R\) lying over \(\mathfrak p\) (that is,
  \(f \notin Q\) whenever \(Q\) is prime with \(Q \cap S = \mathfrak p\)). Then there are \(g \in S
  \setminus \mathfrak p\) and \(h \in R\) with \(g = f \cdot h\) in \(R\).
\end{lemma}
\begin{proof}
  \leanok
  Consider the contracted ideal \((fR) \cap S\) of \(S\). Were it contained in \(\mathfrak p\),
  going-up for the integral extension \(S \to R\) would produce a prime \(Q \supseteq fR\) of \(R\)
  with \(Q \cap S = \mathfrak p\); but then \(f \in Q\) is a prime over \(\mathfrak p\) containing
  \(f\), contradicting the hypothesis. Hence \((fR) \cap S \not\subseteq \mathfrak p\): some
  \(g \in (fR) \cap S\) lies outside \(\mathfrak p\). By construction \(g \in fR\), so \(g = f \cdot
  h\) for some \(h \in R\).
\end{proof}

\section{The moving lemma: pieces on which the class trivializes}
\label{sec:effectivityMoving}

We now select, for a \emph{module-finite} faithfully flat cover \(A \to B\), the affine pieces of the
base curve \(X_A\) on which a prescribed \v Cech Picard class of the cover curve \(X_B\) becomes
trivial after pullback to the cover piece. The route is pure commutative algebra --- no integrality
of the curve, no divisors --- through the affine-open class and the two bricks of the previous
section. Throughout, \(\mathrm{cg} \colon X_B \to X_A\) is the cover inclusion.

\begin{definition}[The affine-open \v Cech--Picard class]
  \label{def:cechPicClass_affineOpen}
  \lean{AlgebraicGeometry.Scheme.Opens.cechPicClass, AlgebraicGeometry.Scheme.Opens.ιTop,
    AlgebraicGeometry.Scheme.Opens.cechPicClass_of_le}
  \uses{def:cechPic_toPic}
  \leanok
  Let \(Z\) be a scheme and \(O \subseteq Z\) an affine open. Pullback along the open immersion \(O
  \hookrightarrow Z\) identifies the ambient sections \(\Gamma(Z, O)\) with the global sections
  \(\Gamma(O, \top)\) of the open subscheme; write \(\iota_O^{\top}\) for this ring isomorphism. The
  \emph{affine-open class} of a \v Cech Picard class \(L\) on \(Z\) is
  \[
    L\langle O\rangle \;:=\; \bigl(\iota_O^{\top}\bigr)^{-1}_{*}\,
      \mathrm{toPic}_O\bigl(\iota^{*}L\bigr) \;\in\; \operatorname{Pic}\bigl(\Gamma(Z, O)\bigr),
  \]
  the invertible \(\Gamma(Z, O)\)-module obtained by transporting, through the affine \v
  Cech--Picard dictionary \(\mathrm{toPic}\) (Definition~\ref{def:cechPic_toPic}), the restriction of
  \(L\) to \(O\). It is natural in the open: for affine opens \(O' \le O\) the class \(L\langle
  O'\rangle\) is the image of \(L\langle O\rangle\) under the restriction homomorphism
  \(\operatorname{Pic}(\Gamma(Z, O)) \to \operatorname{Pic}(\Gamma(Z, O'))\).
\end{definition}
\begin{proof}
  \leanok
  \uses{thm:cechPic_toPic_map}
  The section identification \(\iota_O^{\top}\) is an isomorphism because \(O \hookrightarrow Z\) is
  an open immersion with self-preimage \(O\), so its pullback on sections over \(O\) is invertible;
  transporting the affine class \(\mathrm{toPic}_O(\iota^{*}L)\) back along it gives a well-defined
  element of \(\operatorname{Pic}(\Gamma(Z, O))\). Naturality is the commuting square of the two open
  immersions \(O' \le O \le Z\): the restriction map of ambient sections and the two section
  identifications intertwine the \(\mathrm{toPic}\)-images by naturality of the dictionary in the
  scheme (Theorem~\ref{thm:cechPic_toPic_map}), so the class formed on \(O'\) is the restriction of
  the class formed on \(O\).
\end{proof}

\begin{theorem}[Triviality detection for the affine-open class]
  \label{thm:cechPicClass_triv}
  \lean{AlgebraicGeometry.Scheme.Opens.cechPicMap_ι_eq_one_of_cechPicClass_eq_one,
    AlgebraicGeometry.Scheme.cechPicMap_ι_eq_one_of_le,
    AlgebraicGeometry.Scheme.Opens.cechPicClass_basicOpen_eq_one_of_free}
  \uses{def:cechPicClass_affineOpen, thm:cechPic_toPic_injective}
  \leanok
  Let \(Z\) be a scheme and \(L\) a \v Cech Picard class on \(Z\).
  \begin{enumerate}
    \item If the affine-open class \(L\langle O\rangle\) is trivial for an affine open \(O\), then
      the restriction \(\iota^{*}L\) of \(L\) to \(O\) is trivial.
    \item Restriction triviality is monotone: if \(\iota_O^{*}L = 1\) and \(O' \le O\), then
      \(\iota_{O'}^{*}L = 1\).
    \item If, for an affine open \(O\) and \(f \in \Gamma(Z, O)\), the invertible module \(L\langle
      O\rangle\) becomes free over every \(\Gamma(Z, O)\)-algebra in which \(f\) is a unit, then the
      affine-open class on the basic open \(D(f)\) is trivial, \(L\langle D(f)\rangle = 1\); hence
      \(L\) restricts trivially to \(D(f)\).
  \end{enumerate}
\end{theorem}
\begin{proof}
  \leanok
  (1) The dictionary \(\mathrm{toPic}\) is injective (Theorem~\ref{thm:cechPic_toPic_injective}), so
  \(\iota^{*}L = 1\) follows from \(\mathrm{toPic}_O(\iota^{*}L) = 1\); the latter is the transport
  of \(L\langle O\rangle = 1\) through the section identification, which reflects triviality because
  it has a two-sided inverse. (2) Restriction along \(O' \le O\) factors the restriction to \(O'\)
  through the restriction to \(O\), and a group homomorphism sends \(1\) to \(1\). (3) The
  restriction homomorphism \(\Gamma(Z, O) \to \Gamma(Z, D(f))\) inverts \(f\), because \(f\) is a
  unit on its own basic open; so by hypothesis \(L\langle O\rangle\) base-changes to a free, hence
  trivial, class over \(\Gamma(Z, D(f))\), and by naturality of the affine-open class
  (Definition~\ref{def:cechPicClass_affineOpen}) this base change is \(L\langle D(f)\rangle\), which
  is therefore \(1\). Triviality of \(L\) restricted to \(D(f)\) then follows from~(1).
\end{proof}

\begin{lemma}[Module-finiteness of the cover piece over the base piece]
  \label{lem:finite_pieceCover}
  \lean{AlgebraicGeometry.Over.finite_pieceCover}
  \uses{def:pieceAlgEquiv}
  \leanok
  Let \(A \to B\) be a module-finite homomorphism of \(k\)-algebras and \(V \subseteq X_A\) an affine
  open. Then the cover-piece ring \(\Gamma(X_B, \mathrm{cg}^{-1}V)\) is a module-finite \(\Gamma(X_A,
  V)\)-algebra.
\end{lemma}
\begin{proof}
  \leanok
  By the piece identification (Definition~\ref{def:pieceAlgEquiv}) the cover-piece ring is \(\Gamma(
  X_A, V) \otimes_A B\) as a \(\Gamma(X_A, V)\)-algebra. Base change preserves module-finiteness: as
  \(B\) is module-finite over \(A\), the base change \(\Gamma(X_A, V) \otimes_A B\) is module-finite
  over \(\Gamma(X_A, V)\).
\end{proof}

\begin{theorem}[The moving lemma]
  \label{thm:moving_lemma}
  \lean{AlgebraicGeometry.Over.exists_isAffineOpen_cechPicMap_preimage_eq_one}
  \uses{thm:cechPicClass_triv, thm:invertible_avoid_free, lem:algebraic_tube, lem:finite_pieceCover,
    def:cechPicClass_affineOpen, thm:exists_isAffineOpen_cg_le, def:pieceAlgEquiv}
  \leanok
  Let \(A \to B\) be module-finite. For every \v Cech Picard class \(L\) on the cover curve \(X_B\)
  and every point \(x \in X_A\), there is an affine open \(V \ni x\) of the base curve such that \(L\)
  restricts trivially to the open subscheme \(\mathrm{cg}^{-1}V\) of \(X_B\).
\end{theorem}
\begin{proof}
  \leanok
  Choose a \(\mathrm{cg}\)-saturated affine open \(V_0 \ni x\) of \(X_A\)
  (Theorem~\ref{thm:exists_isAffineOpen_cg_le}); the cover piece \(\mathrm{cg}^{-1}V_0\) is then
  affine with ring \(N := \Gamma(X_B, \mathrm{cg}^{-1}V_0)\), and \(L\langle \mathrm{cg}^{-1}V_0
  \rangle\) (Definition~\ref{def:cechPicClass_affineOpen}) is an invertible \(N\)-module. By
  module-finiteness (Lemma~\ref{lem:finite_pieceCover}) the piece map \(\Gamma(X_A, V_0) \to N\) is
  module-finite, hence integral and quasi-finite; therefore the fibre of \(\operatorname{Spec} N \to
  \operatorname{Spec}\Gamma(X_A, V_0)\) over the germ prime \(\mathfrak p_x\) of \(x\) is a
  \emph{finite} set of primes \(\mathfrak q_1, \dots, \mathfrak q_m\) of \(N\).

  Apply the avoidance brick (Theorem~\ref{thm:invertible_avoid_free}) to the invertible module
  \(L\langle \mathrm{cg}^{-1}V_0\rangle\) and the finite family \((\mathfrak q_j)\): there is \(f \in
  N\) with \(f \notin \mathfrak q_j\) for all \(j\) such that \(L\langle \mathrm{cg}^{-1}V_0\rangle\)
  becomes free wherever \(f\) is inverted. Since \(f\) avoids every prime of \(N\) over \(\mathfrak
  p_x\), the algebraic tube (Lemma~\ref{lem:algebraic_tube}) for the integral extension \(\Gamma(X_A,
  V_0) \to N\) produces \(g \notin \mathfrak p_x\) and \(h \in N\) with \(\mathrm{cg}^{\sharp}g = f
  \cdot h\). Set \(V := D(g) \subseteq X_A\). Then \(x \in V\), because \(g \notin \mathfrak p_x\)
  means the germ of \(g\) at \(x\) is a unit, and
  \[
    \mathrm{cg}^{-1}V = D(\mathrm{cg}^{\sharp}g) = D(f \cdot h) \le D(f) .
  \]
  Freeness of \(L\langle \mathrm{cg}^{-1}V_0\rangle\) after inverting \(f\) trivializes the class on
  \(D(f)\) (Theorem~\ref{thm:cechPicClass_triv}(3)), and restriction triviality is monotone
  (Theorem~\ref{thm:cechPicClass_triv}(2)), so \(L\) restricts trivially to \(\mathrm{cg}^{-1}V \le
  D(f)\).

  \emph{Module-finiteness is necessary.} For a merely quasi-finite (for instance \'etale) non-finite
  cover the conclusion fails. There the fibre of the piece map over \(\mathfrak p_x\) can be infinite,
  and the bare restricted class need not become trivial on any \(\mathrm{cg}\)-saturated neighbourhood
  of the fibre: take \(B = A_u \times A_v\), a product of two localizations of a two-dimensional
  normal local ring \(A\) with non-trivial class group, and a class whose restrictions to the two
  factors are non-trivial classes of the two localizations; no single saturated piece trivializes it.
  The general faithfully-flat effectivity therefore genuinely needs the per-piece descent datum of
  Section~\ref{sec:effectivityComparisonUnit} rather than bare piece-triviality, and survives with
  piece-selection taken as a hypothesis (Theorem~\ref{thm:effectivity_of_pieces}).
\end{proof}

\section{From subscheme triviality to a trimmed trivializing cochain}
\label{sec:effectivityTrivialization}

The moving lemma delivers triviality of the class \emph{as a class} on the cover piece. The per-piece
descent of Section~\ref{sec:effectivityComparisonUnit} instead consumes a trivializing \emph{cochain}
of the representing cocycle, trimmed to the piece and indexed by all ambient points. This section
converts the one to the other.

\begin{theorem}[The trimmed trivializing cochain of a class trivial on an open subscheme]
  \label{thm:exists_trimmed_trivializing}
  \lean{AlgebraicGeometry.Scheme.exists_trimmed_trivializing_of_cechPicMap_ι_eq_one}
  \uses{cor:cechPic_mk_eq_one, def:unitsPreimageEquiv, lem:units_gluing}
  \leanok
  Let \(Z\) be a scheme, \(\mathcal N\) a pointed cover of \(Z\), \(\gamma\) a unit \(1\)-cocycle on
  \(\mathcal N\), and \(D \subseteq Z\) an open subscheme. If the class \([\gamma]\) restricts
  trivially to \(D\) (that is \(\iota_D^{*}[\gamma] = 1\)), then there is a family of units
  \[
    t_b \in \Gamma\bigl(Z,\, \mathcal N(b) \cap D\bigr)^{\times}, \qquad b \in Z,
  \]
  indexed by \emph{all} ambient points, satisfying the one-sided trivializing relation \(t_b \cdot
  \gamma_{b b'} = t_{b'}\) on the \(D\)-trimmed pairwise overlaps.
\end{theorem}
\begin{proof}
  \leanok
  Triviality of the restricted class means the pulled-back cocycle \(\iota_D^{\sharp}\gamma\) on the
  cover \(\iota_D^{-1}\mathcal N\) of \(D\) is cohomologous to \(1\)
  (Corollary~\ref{cor:cechPic_mk_eq_one}); as restriction to an open subscheme needs no further
  refinement, this yields a trivializing \(0\)-cochain \(\alpha\), indexed by points \(p\) of \(D\),
  with \(\alpha_p \cdot (\iota_D^{\sharp}\gamma)_{p p'} = \alpha_{p'}\). Transport each \(\alpha_p\)
  across the open immersion \(\iota_D\): on the preimage of the trimmed member \(\mathcal
  N(\iota_D p) \cap D\) the unit \(\alpha_p\) is the image of an ambient unit
  (Definition~\ref{def:unitsPreimageEquiv}, unit sections across an open immersion), giving units
  \(t'_p\) on \(\mathcal N(\iota_D p) \cap D\) that satisfy the ambient trivializing relation on
  subscheme pairs. Finally re-index from points of \(D\) to points of \(Z\): for each ambient \(b\)
  the trimmed member \(\mathcal N(b) \cap D\) is covered by the domains of the \(t'_p\), the values
  \(t'_p \cdot \gamma_{(\iota_D p)\, b}\) agree on overlaps by the cocycle identity, so they glue
  (Lemma~\ref{lem:units_gluing}) to a unit \(t_b\) on \(\mathcal N(b) \cap D\). The glued family
  satisfies \(t_b \cdot \gamma_{b b'} = t_{b'}\), again by the cocycle identity together with the
  local relations.
\end{proof}

\begin{theorem}[A piece trivialization from restriction triviality]
  \label{thm:pieceTrivialization_of_triv}
  \lean{AlgebraicGeometry.Over.pieceTrivialization_of_cechPicMap_eq_one}
  \uses{thm:exists_trimmed_trivializing, def:pieceTrivialization}
  \leanok
  Let \(\gamma\) be a representing unit cocycle on a pointed cover \(\mathcal N\) of \(X_B\) and \(V
  \subseteq X_A\) a piece. If the class \([\gamma]\) restricts trivially to the cover piece
  \(\mathrm{cg}^{-1}V\), then \(V\) carries a piece trivialization of \(\gamma\)
  (Definition~\ref{def:pieceTrivialization}).
\end{theorem}
\begin{proof}
  \leanok
  Instantiate Theorem~\ref{thm:exists_trimmed_trivializing} at the open subscheme \(D = \mathrm{cg}
  ^{-1}V\): the trimmed trivializing cochain it produces is precisely the field data of a piece
  trivialization (Definition~\ref{def:pieceTrivialization}).
\end{proof}

\section{Twisting a piece trivialization}
\label{sec:effectivityTwist}

Two piece trivializations of the same representing cocycle on the same piece differ, member by member,
by the restrictions of a single global unit of the cover piece (this is proved in the next section).
Here we record how the per-piece comparison unit responds to such a twist, and the algebraic and
geometric seams that identify the twist with a descent coboundary --- the mechanism behind both the
trivialization-independence of the descended class and the flattening of a trivialization.

\begin{theorem}[Twisting a piece trivialization by a global unit]
  \label{thm:pieceComparisonUnit_twist}
  \lean{AlgebraicGeometry.Over.PieceTrivialization.twist, AlgebraicGeometry.Over.geomCoboundary,
    AlgebraicGeometry.Over.pieceComparisonUnit_eq_of_triv_eq}
  \uses{def:pieceTrivialization, thm:pieceComparisonUnit}
  \leanok
  Let \(T\) be a piece trivialization of \(\gamma\) on \(V\) and \(e \in \Gamma(X_B, \mathrm{cg}^{-1}
  V)^{\times}\) a global unit of the cover piece. The \emph{twist} \(T \cdot e\) is the piece
  trivialization with members \(t_b \cdot e|_{\mathcal N(b) \cap \mathrm{cg}^{-1}V}\). Write the
  \emph{geometric descent coboundary} of \(e\),
  \[
    \partial e \;:=\; \frac{u_2^{\sharp} e}{u_1^{\sharp} e} \;\in\; \Gamma\bigl(X_{B \otimes_A B},\,
      \mathrm{cgq}^{-1}V\bigr)^{\times},
  \]
  the ratio of its two coprojection pullbacks to the double piece. If two piece trivializations \(T,
  T'\) differ member by member by \(e\), i.e.\ \(T' = T \cdot e\), then for any \(\sigma\)-normalized
  comparison \(W\) their per-piece comparison units (Theorem~\ref{thm:pieceComparisonUnit}) differ by
  \(\partial e\):
  \[
    v_V(T') = v_V(T) \cdot \partial e .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Multiplying every member of \(T\) by the restrictions of the single global unit \(e\) preserves the
  trivializing relation \(t_b \cdot \gamma_{b b'} = t_{b'}\): the two \(e\)-factors coincide on the
  overlap. For the comparison units, the per-piece comparison unit is characterized by its
  restriction to the trimmed comparison cover (Theorem~\ref{thm:pieceComparisonUnit}), where it
  restricts to \(\theta_x \cdot (u_2^{\sharp}T)(x) / (u_1^{\sharp}T)(x)\). Replacing \(T\) by \(T
  \cdot e\) multiplies this local value by \((u_2^{\sharp}e)/(u_1^{\sharp}e)\) at every point; by
  uniqueness of the glued unit this multiplies \(v_V(T)\) by the global unit \(\partial e\) with that
  restriction.
\end{proof}

\begin{theorem}[The coboundary seams of the identification]
  \label{thm:geomCoboundary_seams}
  \lean{Module.comparisonDescentUnit_coboundary,
    AlgebraicGeometry.Over.map_pieceEquiv_geomCoboundary}
  \uses{thm:pieceComparisonUnit_twist, def:pieceDescentEquiv,
    thm:isDescentCocycle_comparisonDescentUnit, thm:pieceRingEquiv_whiskerLeft_naturality}
  \leanok
  Fix an affine piece \(V\) and \(e \in \Gamma(X_B, \mathrm{cg}^{-1}V)^{\times}\); let \(\beta \in
  (\Gamma(X_A, V) \otimes_A B)^{\times}\) be its image under the piece identification
  (Definition~\ref{def:pieceAlgEquiv}). Then:
  \begin{enumerate}
    \item \textup{(algebra seam)} the comparison descent unit of the base-changed coboundary of
      \(\beta\) --- the ratio of the two inclusions \(\beta \mapsto \beta \otimes 1\), \(\beta
      \mapsto 1 \otimes \beta\) of \(B \to B \otimes_A B\), base changed to \(\Gamma(X_A, V)\) ---
      equals the descent coboundary of \(\beta\) relative to \(\Gamma(X_A, V) \to \Gamma(X_A, V)
      \otimes_A B\);
    \item \textup{(geometric seam)} through the piece identification, the geometric descent coboundary
      \(\partial e\) (Theorem~\ref{thm:pieceComparisonUnit_twist}) is carried to the base-changed
      coboundary of \(\beta\).
  \end{enumerate}
\end{theorem}
\begin{proof}
  \leanok
  (1) Transport both sides through the descent-cocycle ring identification
  (Definition~\ref{def:pieceDescentEquiv}) to \((\Gamma(X_A, V) \otimes_A (B \otimes_A B))^{\times}\):
  there the identification carries a left pure tensor to the base change of the first inclusion and a
  right pure tensor to that of the second (checked on pure tensors, extended by bilinearity), so the
  comparison descent unit of the inclusion ratio (Theorem~\ref{thm:isDescentCocycle_comparisonDescentUnit})
  is the descent coboundary of \(\beta\). (2) The two coprojections \(u_1, u_2\) are the whiskerings
  of the two inclusions \(B \to B \otimes_A B\), so by the algebra-naturality of the section-ring
  identification (Theorem~\ref{thm:pieceRingEquiv_whiskerLeft_naturality}) each pullback \(u_i^{\sharp}
  e\) is carried to the corresponding inclusion applied to \(\beta\), and their ratio is the
  base-changed coboundary of \(\beta\).
\end{proof}

\section{Trivialization independence and flat trivializations}
\label{sec:effectivityOverlap}

We deduce the \((B)\) deliverable of the \((C2)\) close --- the descended per-piece class is
independent of the chosen trivialization --- and its constructive upgrade: on a piece whose descended
class is trivial some trivialization is \emph{flat}, with per-piece comparison unit \(1\) on the nose.
The flat pieces produced here are what the refinement splice glues.

\begin{theorem}[Two piece trivializations differ by a glued global unit]
  \label{thm:exists_ratio_unit}
  \lean{AlgebraicGeometry.Over.exists_ratio_unit}
  \uses{def:pieceTrivialization, lem:units_gluing}
  \leanok
  Any two piece trivializations \(T, T'\) of the same cocycle \(\gamma\) on the same piece \(V\)
  differ by a single global unit of the cover piece: there is \(e \in \Gamma(X_B, \mathrm{cg}^{-1}
  V)^{\times}\) with \(T' = T \cdot e\), i.e.\ \(t'_b = t_b \cdot e|_{\mathcal N(b) \cap \mathrm{cg}
  ^{-1}V}\) for every \(b\).
\end{theorem}
\begin{proof}
  \leanok
  The member-wise ratio \(t'_b / t_b\), a unit on the trimmed member \(\mathcal N(b) \cap \mathrm{cg}
  ^{-1}V\), is \v Cech-compatible: the two trivializing relations \(t_b \cdot \gamma_{b b'} =
  t_{b'}\) and \(t'_b \cdot \gamma_{b b'} = t'_{b'}\) cancel the cocycle \(\gamma\), so \(t'_b/t_b\)
  and \(t'_{b'}/t_{b'}\) agree on the overlap. The trimmed members cover \(\mathrm{cg}^{-1}V\), so the
  ratios glue (Lemma~\ref{lem:units_gluing}) to a unit \(e\) with the stated restrictions.
\end{proof}

\begin{theorem}[Trivialization independence of the descended per-piece class]
  \label{thm:pieceDescentClass_congr}
  \lean{AlgebraicGeometry.Over.comparisonDescentUnit_twist,
    AlgebraicGeometry.Over.pieceDescentClass_congr}
  \uses{thm:exists_ratio_unit, thm:pieceComparisonUnit_twist, thm:geomCoboundary_seams,
    def:pieceDescentClass, def:module_picClass}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced, and \(A \to B\)
  faithfully flat. For a fixed \(\sigma\)-normalized comparison \(W\) and an affine piece \(V\), the
  descended per-piece class \(M_V\) (Theorem~\ref{def:pieceDescentClass}) does not depend on the
  chosen piece trivialization.
\end{theorem}
\begin{proof}
  \leanok
  Let \(T, T'\) be two piece trivializations; by Theorem~\ref{thm:exists_ratio_unit} they differ by a
  global unit \(e\), \(T' = T \cdot e\). Transported to the descent-cocycle ring, the comparison unit
  of \(T'\) is that of \(T\) multiplied by the descent coboundary of \(\beta\), the piece
  identification of \(e\): this is the twist lemma (Theorem~\ref{thm:pieceComparisonUnit_twist})
  combined with the two coboundary seams (Theorem~\ref{thm:geomCoboundary_seams}). The Picard class
  of a descent \(1\)-cocycle is unchanged when the cocycle is multiplied by a descent coboundary,
  since a coboundary alters the descent datum by an isomorphism and not the isomorphism class of the
  descended module (Definition~\ref{def:module_picClass}). Hence \(M_V(T') = M_V(T)\).
\end{proof}

\begin{theorem}[Flattening a trivialization along a trivial descended class]
  \label{thm:exists_pieceComparisonUnit_eq_one}
  \lean{AlgebraicGeometry.Over.exists_pieceComparisonUnit_eq_one}
  \uses{thm:pieceComparisonUnit_twist, thm:geomCoboundary_seams, def:pieceDescentClass,
    def:module_picClass, thm:pieceComparisonUnit}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced, \(A \to B\) faithfully
  flat, \(W\) a \(\sigma\)-normalized comparison, and \(T\) a piece trivialization on \(V\) whose
  descended class \(M_V(T)\) is trivial. Then \(V\) carries a piece trivialization whose per-piece
  comparison unit is \(1\) on the nose.
\end{theorem}
\begin{proof}
  \leanok
  Triviality of \(M_V(T)\) means the descent \(1\)-cocycle of the transported comparison unit
  cobounds: there is \(\beta \in (\Gamma(X_A, V) \otimes_A B)^{\times}\) whose descent coboundary is
  that cocycle (Definition~\ref{def:module_picClass}: the class is \(1\) exactly when the descended
  module is free). Pull \(\beta\) back through the piece identification to a global unit \(e \in
  \Gamma(X_B, \mathrm{cg}^{-1}V)^{\times}\). By the coboundary seams
  (Theorem~\ref{thm:geomCoboundary_seams}) the per-piece comparison unit of \(T\) is the geometric
  descent coboundary \(\partial e\). Twisting \(T\) by \(e^{-1}\) multiplies the comparison unit by
  \(\partial(e^{-1}) = (\partial e)^{-1}\) (Theorem~\ref{thm:pieceComparisonUnit_twist}), giving
  comparison unit \(v_V(T) \cdot (\partial e)^{-1} = 1\).
\end{proof}

\begin{theorem}[Localize and flatten]
  \label{thm:exists_flat_pieceTrivialization}
  \lean{AlgebraicGeometry.Over.exists_flat_pieceTrivialization_of_le}
  \uses{thm:exists_pieceComparisonUnit_eq_one, thm:invertible_avoid_free, thm:pieceDescentClass_res}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced, \(A \to B\) faithfully
  flat, and \(W\) a \(\sigma\)-normalized comparison. Every point \(x\) of a trivialized affine piece
  \((V_1, T_1)\) lies in a basic affine subpiece \(V \le V_1\) carrying a \emph{flat} piece
  trivialization --- one whose per-piece comparison unit is \(1\).
\end{theorem}
\begin{proof}
  \leanok
  Apply the avoidance brick (Theorem~\ref{thm:invertible_avoid_free}) to the invertible module
  \(M_{V_1}(T_1)\) and the single germ prime \(\mathfrak p_x\) of \(x\) on \(\Gamma(X_A, V_1)\): it
  yields \(f \notin \mathfrak p_x\) such that \(M_{V_1}(T_1)\) becomes free wherever \(f\) is
  inverted. Set \(V := D(f) \subseteq X_A\); then \(x \in V\) (the germ of \(f\) at \(x\) is a unit)
  and \(V \le V_1\). Restrict \(T_1\) to \(V\); by restriction canonicity of the descended classes
  (Theorem~\ref{thm:pieceDescentClass_res}) the restricted descended class is the base change of
  \(M_{V_1}(T_1)\) along \(\Gamma(X_A, V_1) \to \Gamma(X_A, V)\), which inverts \(f\) and so is free,
  hence trivial. Flattening (Theorem~\ref{thm:exists_pieceComparisonUnit_eq_one}) then produces a
  piece trivialization on \(V\) with comparison unit \(1\).
\end{proof}

\section{The refinement splice}
\label{sec:effectivitySplice}

The assembly of the descended class from a covering family of flat pieces, run in the constructive
direction of the \((C1)\) kernel lemma's final assembly.

\begin{theorem}[The refinement splice]
  \label{thm:refinement_splice}
  \lean{AlgebraicGeometry.Over.exists_cechPic_map_whiskerLeft_eq_of_flat}
  \uses{thm:exists_ratio_unit, thm:pieceComparisonUnit_twist, thm:exists_unitsAppLE_eq,
    thm:appLE_whiskerLeft_injective, thm:isAffineOpen_inf, def:pieceTrivialization,
    cor:cechPic_mk_eq_one}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced, and \(A \to B\)
  faithfully flat. Suppose every point of \(X_A\) lies in an affine piece carrying a \emph{flat}
  piece trivialization of \(\gamma\) (per-piece comparison unit \(1\)). Then the class \(L =
  [\gamma]\) descends along the cover inclusion: there is a \v Cech Picard class \(M\) on \(X_A\)
  with \(\mathrm{cg}^{*}M = L\).
\end{theorem}
\begin{proof}
  \leanok
  Fix a covering family \((V_x, T_x)\) of flat trivialized pieces. On the overlap \(V_x \cap V_y\)
  the two restricted trivializations differ by a glued unit \(c_{xy}\) of the overlap cover piece
  (Theorem~\ref{thm:exists_ratio_unit}); both restrictions are still flat, so the twist lemma
  (Theorem~\ref{thm:pieceComparisonUnit_twist}) forces the geometric descent coboundary of
  \(c_{xy}\) to be \(1\) --- the two coprojection pullbacks of \(c_{xy}\) to the double piece agree
  on the nose. Faithfully flat descent of unit sections along \(\mathrm{cg}\)
  (Theorem~\ref{thm:exists_unitsAppLE_eq}) therefore descends each \(c_{xy}\) to a unit \(m_{xy}\) of
  the affine overlap \(V_x \cap V_y\) downstairs, the overlaps being affine by separatedness of the
  curve product (Theorem~\ref{thm:isAffineOpen_inf}). The \(m_{xy}\) satisfy the \v Cech cocycle
  identity: their \(\mathrm{cg}\)-pullbacks telescope through the trivializations, and
  \(\mathrm{cg}\)-pullback is injective on sections (Theorem~\ref{thm:appLE_whiskerLeft_injective}).
  Let \(M\) be the class of the resulting unit cocycle \(m\) on the pointed cover \((V_x)\). Then
  \(\mathrm{cg}^{*}M = L\) by \(\mathrm{mk}\)-calculus over the common refinement of the
  \(\mathrm{cg}\)-pullback of \((V_x)\) and \(\mathcal N\): the trivializations \(T_x\) themselves
  cobound the two pulled cocycles (Corollary~\ref{cor:cechPic_mk_eq_one}).
\end{proof}

\section{The \((C2)\) effectivity theorem and the surjectivity close}
\label{sec:effectivityClose}

The campaign close: the effectivity theorem in both forms, and the resulting bijectivity of the unit
of the \'etale plus construction over a section-admitting field test.

\begin{theorem}[Effectivity from a covering family of trivialized pieces]
  \label{thm:effectivity_of_pieces}
  \lean{AlgebraicGeometry.Over.exists_cechPic_map_whiskerLeft_eq_of_pieces}
  \uses{thm:exists_normalizedCechComparison, thm:exists_flat_pieceTrivialization,
    thm:refinement_splice, def:isRigidified}
  \leanok
  Let \(C\) be proper, geometrically irreducible and geometrically reduced, and \(A \to B\)
  faithfully flat. Let \(\gamma\) be a representing cocycle on \(X_B\) whose class \(L = [\gamma]\) is
  rigidified along the base-changed section (Definition~\ref{def:isRigidified}) and satisfies the
  on-the-nose descent equation \(u_1^{*}L = u_2^{*}L\). If every point of \(X_A\) lies in an affine
  piece on which \(\gamma\) admits a piece trivialization, then \(L\) descends along the cover
  inclusion: \(\exists M,\ \mathrm{cg}^{*}M = L\).
\end{theorem}
\begin{proof}
  \leanok
  The descent equation together with rigidification produces a \(\sigma\)-normalized comparison \(W\)
  of \(\gamma\), with no further geometric hypotheses
  (Theorem~\ref{thm:exists_normalizedCechComparison}). At each point, localize-and-flatten
  (Theorem~\ref{thm:exists_flat_pieceTrivialization}) turns the given trivialized piece into a flat
  one through the point. The resulting covering family of flat pieces feeds the refinement splice
  (Theorem~\ref{thm:refinement_splice}), which descends \(L\).
\end{proof}

\begin{theorem}[The \((C2)\) effectivity theorem]
  \label{thm:effectivity}
  \lean{AlgebraicGeometry.Over.exists_cechPic_map_whiskerLeft_eq}
  \uses{thm:effectivity_of_pieces, thm:moving_lemma, thm:pieceTrivialization_of_triv}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be proper, geometrically irreducible and geometrically reduced, and \(A \to B\) a
  \emph{module-finite} faithfully flat cover. Every \v Cech Picard class \(L\) on the cover curve
  \(X_B\) that is rigidified along the base-changed section and satisfies the on-the-nose descent
  equation \(u_1^{*}L = u_2^{*}L\) descends along the cover inclusion: \(\exists M,\ \mathrm{cg}^{*}M
  = L\).
\end{theorem}
\begin{proof}
  \leanok
  Represent \(L = [\gamma]\). Because the cover is module-finite, the moving lemma
  (Theorem~\ref{thm:moving_lemma}) applies: every point of \(X_A\) has an affine neighbourhood on
  which \(L\) restricts trivially to the cover piece, and such a restriction triviality furnishes a
  piece trivialization (Theorem~\ref{thm:pieceTrivialization_of_triv}). The covering family of
  trivialized pieces feeds the general effectivity Theorem~\ref{thm:effectivity_of_pieces}. This is
  the cocycle recast of the descent step in Kleiman's Comparison Theorem, Part~2: the two projection
  pullbacks of the rigidified pair agree, so the automorphism \(v_{13}^{-1}v_{23}v_{12}\) of its
  first-projection pullback is trivial and the pair descends along the cover.
\end{proof}

\begin{theorem}[Surjectivity of the unit over a section-admitting field test]
  \label{thm:unit_surjective_of_section}
  \lean{AlgebraicGeometry.PicEtAff.unit_surjective_of_section}
  \uses{thm:effectivity, thm:etale_cover_field_cofinality, def:isRigidified,
    thm:PicEtAff_unit_eq_mk, def:relPicAlgMap, lem:PicEtAff_mk_descentMap, def:descentClasses,
    lem:PicEtAff_ind}
  \leanok
  \source{kleiman-picard}
  Let \(C\) be a curve over \(k\) that is proper, geometrically irreducible and geometrically
  reduced, and let \(K\) be a field extension of \(k\) admitting a \(K\)-point \(\sigma \colon
  \operatorname{Spec} K \to C\). Then the unit \(\eta_K \colon \mathrm{relPic}(C, \operatorname{Spec}
  K) \to \mathrm{PicEtAff}(C, K)\) of the \'etale plus construction is surjective.
\end{theorem}
\begin{proof}
  \leanok
  A plus class is represented on an \'etale cover \(E\) of \(\operatorname{Spec} K\)
  (Lemma~\ref{lem:PicEtAff_ind}). \'Etale covers of a field are cofinal in finite separable field
  extensions (Theorem~\ref{thm:etale_cover_field_cofinality}): refine \(E\) to a finite separable
  field extension \(L/K\), giving a module-finite --- hence faithfully flat --- cover \(F =
  \operatorname{Spec} L\) and a descent class \(y\) over \(F\) representing the same plus class
  (Lemma~\ref{lem:PicEtAff_mk_descentMap}). The rigidification layer produces a rigidified \v Cech
  representative \(L_c\) of \(y\) (Definition~\ref{def:isRigidified}) whose two double-cover pullbacks
  agree on the nose. As \(K \to L\) is module-finite faithfully flat, the effectivity theorem
  (Theorem~\ref{thm:effectivity}) descends \(L_c\) along the cover inclusion to a class \(M\) on
  \(X_K\) with \(\mathrm{cg}^{*}M = L_c\). The relative Picard class \([M]\) maps under \(\eta_K\) to
  the original plus class, by the identification of the unit with the tautological \(\mathrm{mk}\)
  (Theorem~\ref{thm:PicEtAff_unit_eq_mk}) and \(\mathrm{mk}\)-calculus for the algebra map \(K \to L\)
  (Definition~\ref{def:relPicAlgMap}, Definition~\ref{def:descentClasses}). Hence \(\eta_K\) is
  surjective. This is the surjectivity direction of Kleiman's Comparison Theorem Part~2 for a base
  admitting a section --- over a field test the \'etale-local section is an actual point.
\end{proof}

\begin{theorem}[The unit is an isomorphism over a section-admitting field test]
  \label{thm:unitEquiv_of_section}
  \lean{AlgebraicGeometry.PicEtAff.unitEquiv_of_section}
  \uses{thm:unit_surjective_of_section, thm:PicEtAff_unit_injective}
  \leanok
  \source{kleiman-picard}
  Under the hypotheses of Theorem~\ref{thm:unit_surjective_of_section}, the unit is a group
  isomorphism
  \[
    \eta_K \colon \mathrm{relPic}(C, \operatorname{Spec} K) \;\xrightarrow{\ \sim\ }\;
      \mathrm{PicEtAff}(C, K).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The unit is injective by \'etale separatedness (the \((C1)\) close,
  Theorem~\ref{thm:PicEtAff_unit_injective}) and surjective by
  Theorem~\ref{thm:unit_surjective_of_section}; a bijective group homomorphism is an isomorphism.
\end{proof}

\section{Divisor classes from local equations}

An effective Cartier divisor \(D\) on a scheme \(X\) is cut out, near each point, by a single
regular equation. Adapted to the pointed covers of the \v Cech Picard group \(\Pic(X)\) recalled
earlier in this chapter, this data --- one regular section \(f_x\) on each member
of a pointed cover, the sections agreeing up to a unit on overlaps --- is a trivialization of the
invertible sheaf \(\struct X(D)\): on the member \(\mathcal U(x)\) the sheaf is trivialized by
multiplication by \(f_x\). The transition units \(g_{xy} = f_x/f_y \in \struct
X(\mathcal U(x) \cap \mathcal U(y))^{\times}\) form a unit \v Cech \(1\)-cocycle, and its class in
\(\Pic(X)\) is \(\struct X(D)\). This section records that construction and its independence of
the chosen equations up to units; the next builds from it the class of a Weil divisor on a curve.

\begin{definition}[Local equations for an effective divisor]
  \label{def:localEquations}
  \lean{AlgebraicGeometry.Scheme.LocalEquations}
  \leanok
  A system of \emph{local equations} on \(X\), adapted to a pointed cover \(\mathcal U\), consists
  of a section \(f_x \in \struct X(\mathcal U(x))\) on each member, subject to two conditions:
  \begin{itemize}
    \item (regularity) the germ of \(f_x\) at every point \(y \in \mathcal U(x)\) is a
      nonzerodivisor in the stalk \(\struct{X,y}\);
    \item (overlap) for every pair \(x, y\) the restrictions of \(f_x\) and \(f_y\) to the overlap
      \(\mathcal U(x) \cap \mathcal U(y)\) differ by a unit factor: there is a unit \(u \in
      \struct X(\mathcal U(x) \cap \mathcal U(y))^{\times}\) with \(f_x|_{\cap} = u \cdot
      f_y|_{\cap}\).
  \end{itemize}
\end{definition}

\begin{lemma}[The transition units]
  \label{lem:localEquations_ratioUnit}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.ratioUnit,
    AlgebraicGeometry.Scheme.LocalEquations.eqn_restrict_eq,
    AlgebraicGeometry.Scheme.LocalEquations.ratioUnit_unique}
  \uses{def:localEquations}
  \leanok
  For a local-equation system and points \(x, y\) there is a \emph{unique} unit \(g_{xy} \in
  \struct X(\mathcal U(x) \cap \mathcal U(y))^{\times}\) with \(f_x|_{\cap} = g_{xy} \cdot
  f_y|_{\cap}\) on the overlap; write \(g_{xy} = f_x/f_y\) for the transition unit.
\end{lemma}
\begin{proof}
  \leanok
  Existence is the overlap condition of Definition~\ref{def:localEquations}. For uniqueness, the
  restriction of \(f_y\) to the overlap is again a nonzerodivisor: a section of a sheaf is
  determined by its germs, so it is a nonzerodivisor as soon as each of its germs is, and the germs
  of \(f_y\) are nonzerodivisors by regularity. Hence in the equation \(f_x|_{\cap} = u \cdot
  f_y|_{\cap}\) the right factor \(f_y|_{\cap}\) can be cancelled on the right, determining the unit
  \(u\) uniquely.
\end{proof}

\begin{lemma}[The cocycle identity of the transition units]
  \label{lem:localEquations_cocycle}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.ratioUnit_trans}
  \uses{lem:localEquations_ratioUnit}
  \leanok
  On the triple overlap \(\mathcal U(x) \cap \mathcal U(y) \cap \mathcal U(z)\) the transition
  units satisfy \(g_{xy} \cdot g_{yz} = g_{xz}\).
\end{lemma}
\begin{proof}
  \leanok
  Restrict everything to the triple overlap and multiply through by \(f_z\). By the defining
  equation (Lemma~\ref{lem:localEquations_ratioUnit}) applied to the pairs \((y,z)\) and \((x,y)\),
  \[
    g_{xy}\, g_{yz}\, f_z = g_{xy}\, f_y = f_x ,
  \]
  while applied to \((x,z)\) it gives \(g_{xz}\, f_z = f_x\). The restriction of \(f_z\) to the
  triple overlap is a nonzerodivisor (regularity, as in
  Lemma~\ref{lem:localEquations_ratioUnit}), so cancelling it yields \(g_{xy}\, g_{yz} = g_{xz}\).
\end{proof}

\begin{definition}[The Picard class of a local-equation system]
  \label{def:localEquations_picClass}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.unitsCocycle,
    AlgebraicGeometry.Scheme.LocalEquations.picClass}
  \uses{def:localEquations, lem:localEquations_ratioUnit, lem:localEquations_cocycle}
  \leanok
  The transition units \(g_{xy}\) of a local-equation system \(d\) form a unit \v Cech
  \(1\)-cocycle on its cover \(\mathcal U\); its class
  \[
    \mathrm{picClass}(d) = [\mathcal U,\, g] \in \Pic(X)
  \]
  is the \emph{Picard class} \(\struct X(D)\) of the effective divisor \(D\) cut out by \(d\).
\end{definition}
\begin{proof}
  \leanok
  Each \(g_{xy}\) is a unit on the double overlap \(\mathcal U(x) \cap \mathcal U(y)\), and the
  cocycle identity \(g_{xy}\, g_{yz} = g_{xz}\) holds on triple overlaps
  (Lemma~\ref{lem:localEquations_cocycle}); this is exactly the data of a unit \v Cech
  \(1\)-cocycle on \(\mathcal U\). Take its class in the colimit \(\Pic(X)\).
\end{proof}

\begin{lemma}[Independence of the class under unit rescaling]
  \label{lem:localEquations_rescale}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.rescale,
    AlgebraicGeometry.Scheme.LocalEquations.rescale_ratioUnit,
    AlgebraicGeometry.Scheme.LocalEquations.picClass_rescale}
  \uses{def:localEquations, lem:localEquations_ratioUnit, def:localEquations_picClass}
  \leanok
  Let \(d\) be a local-equation system on \(\mathcal U\) and \((v_x)_x\) a family of units
  \(v_x \in \struct X(\mathcal U(x))^{\times}\). Rescaling each equation, \(f'_x = v_x \cdot f_x\),
  is again a local-equation system on \(\mathcal U\), and it has the same Picard class:
  \(\mathrm{picClass}(d\text{ rescaled by }v) = \mathrm{picClass}(d)\). In particular \(\struct
  X(D)\) depends only on the divisor, not on the chosen equations.
\end{lemma}
\begin{proof}
  \leanok
  Each \(v_x \cdot f_x\) is regular --- at every point its germ is the product of a unit germ and a
  nonzerodivisor germ, hence a nonzerodivisor --- and its overlap ratio is the conjugated unit
  \[
    g'_{xy} = (v_x|_{\cap}) \cdot g_{xy} \cdot (v_y|_{\cap})^{-1},
  \]
  so the rescaled data is a local-equation system on the same cover \(\mathcal U\) with transition
  units \(g'\). The rings \(\struct X(U)\) are commutative, so their units form an abelian group;
  hence \(g'_{xy} = (v_x|_{\cap})(v_y|_{\cap})^{-1}\, g_{xy}\), which exhibits \(g'\) as the product
  of \(g\) with the coboundary of the \(0\)-cochain \((v_x)_x\). Cohomologous cocycles on the same
  cover have the same class in \(\Pic(X)\), so \(\mathrm{picClass}\) is unchanged.
\end{proof}

\section{Pullback of a local-equation system}

A morphism \(f \colon Y \to X\) pulls a local-equation system on \(X\) back to one on \(Y\),
provided the pulled-back equations remain regular; on Picard classes this realizes the pullback of
the associated invertible sheaf, \(f^{*}\struct X(D) = \struct Y(f^{*}D)\).

\begin{definition}[Pullback of a local-equation system]
  \label{def:localEquations_pullback}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.pullback,
    AlgebraicGeometry.Scheme.LocalEquations.pullbackEqn}
  \uses{def:localEquations, lem:localEquations_ratioUnit}
  \leanok
  Let \(f \colon Y \to X\) be a morphism of schemes and \(E\) a local-equation system on \(X\)
  (\ref{def:localEquations}), adapted to a pointed cover \(\mathcal U\). Pull the cover back
  pointwise: the pulled-back pointed cover \(f^{*}\mathcal U\) assigns to \(y \in Y\) the open
  \(f^{-1}\mathcal U(f(y))\). The \emph{pulled-back equations} are the \(f\)-pullbacks
  \(f^{*}\bigl(f_{f(y)}\bigr) \in \struct Y\bigl(f^{-1}\mathcal U(f(y))\bigr)\) of the equations of
  \(E\).

  These form a local-equation system \(f^{*}E\) on \(f^{*}\mathcal U\), \emph{under the additional
  hypothesis that the pulled-back equations are regular}: that the germ of \(f^{*}(f_{f(y)})\) at
  every point of its member is a nonzerodivisor. This regularity is not automatic --- pulling a
  nonzerodivisor back along a non-flat morphism can produce a zerodivisor, so the naive claim
  ``pull the equations back and stay a local-equation system'' is false in general, and the
  hypothesis is genuinely required. (Flatness of \(f\) would be a stronger sufficient condition,
  since flat pullback preserves nonzerodivisors; it is not assumed here.)
\end{definition}
\begin{proof}
  \leanok
  Regularity of the pulled-back equations is the added hypothesis. For the overlap condition, fix
  \(y, y'\) and restrict the defining equation
  \(f_{f(y)}|_{\cap} = g_{f(y)f(y')}\cdot f_{f(y')}|_{\cap}\) of \(E\)
  (\ref{lem:localEquations_ratioUnit}) along \(f\). Since pullback of sections is a ring
  homomorphism commuting with restriction, the two pulled-back equations differ on the overlap
  \(f^{-1}\mathcal U(f(y)) \cap f^{-1}\mathcal U(f(y'))\) by the factor
  \(f^{*}\bigl(g_{f(y)f(y')}\bigr)\), the \(f\)-pullback of the transition unit of \(E\). The
  pullback of a unit section is again a unit, so this factor is a unit and the overlap condition
  holds.
\end{proof}

\begin{lemma}[Transition data of a pullback]
  \label{lem:localEquations_pullback_ratioUnit}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.pullback_ratioUnit,
    AlgebraicGeometry.Scheme.LocalEquations.pullback_unitsCocycle}
  \uses{def:localEquations_pullback, lem:localEquations_ratioUnit, def:localEquations_picClass}
  \leanok
  The transition units of the pulled-back system \(f^{*}E\) are the \(f\)-pullbacks of those of
  \(E\): for all \(y, y'\),
  \[
    g^{f^{*}E}_{y y'} = f^{*}\bigl(g_{f(y)f(y')}\bigr).
  \]
  Consequently the unit \v Cech \(1\)-cocycle of \(f^{*}E\) is the \(f\)-pullback of the cocycle of
  \(E\).
\end{lemma}
\begin{proof}
  \leanok
  The overlap ratio arising in the construction of \(f^{*}E\) (\ref{def:localEquations_pullback})
  is \(f^{*}(g_{f(y)f(y')})\), and the transition unit of \(f^{*}E\) is the unique unit realizing
  that ratio (\ref{lem:localEquations_ratioUnit}); the two therefore agree. Assembling over all
  pairs, the cocycle of \(f^{*}E\) (\ref{def:localEquations_picClass}) is the entry-by-entry
  \(f\)-pullback of the cocycle of \(E\).
\end{proof}

\begin{theorem}[The Picard class of a pullback is the pullback of the class]
  \label{thm:localEquations_picClass_pullback}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.picClass_pullback}
  \uses{def:localEquations_pullback, def:localEquations_picClass,
    lem:localEquations_pullback_ratioUnit}
  \leanok
  For a morphism \(f \colon Y \to X\) and a local-equation system \(E\) on \(X\) with regular
  pullback, the Picard class of \(f^{*}E\) is the pullback of the class of \(E\):
  \[
    \mathrm{picClass}(f^{*}E) = f^{*}\,\mathrm{picClass}(E) \quad\text{in } \Pic(Y),
  \]
  that is, \(\struct Y(f^{*}D) = f^{*}\struct X(D)\).
\end{theorem}
\begin{proof}
  \leanok
  Both sides are represented on the pulled-back cover \(f^{*}\mathcal U\). The class of \(f^{*}E\)
  is the class of its cocycle (\ref{def:localEquations_picClass}), and that cocycle is the
  \(f\)-pullback of the cocycle of \(E\) (\ref{lem:localEquations_pullback_ratioUnit}); pullback of
  Picard classes is, by definition, induced by pulling cocycles back along \(f\). Hence the class
  of the pulled-back cocycle is the pullback \(f^{*}\) of \(\mathrm{picClass}(E)\).
\end{proof}

\section{The point divisor and the class of a Weil divisor}

We return to the curve bundle \(X\) of Chapter~\ref{chap:RiemannRoch}: integral, smooth of relative
dimension one and quasi-compact over the field \(K\), with generic point \(\eta\). To each closed
point \(x\) we attach the local equations of the effective divisor \(1 \cdot x\), whose only zero
is a simple one at \(x\); passing to Picard classes and taking products to the multiplicities sends
each Weil divisor \(D \in \Div(X)\) to its class \(\struct X(D) \in \Pic(X)\), a homomorphism
extending the point classes.

\begin{lemma}[A uniformizer isolated to a single zero]
  \label{lem:exists_pointLocalEquation}
  \lean{AlgebraicGeometry.Scheme.exists_pointLocalEquation}
  \uses{lem:uniformizer, lem:exists_stalk_of_ord_le_one, lem:germ_generic_eq_algebraMap_germ,
    thm:ordZ_support_finite, thm:closedpoint_isClosed, lem:ord_eq_one_of_mem_basicOpen,
    def:scheme_ordZ}
  \leanok
  For a closed point \(x\) of the curve there are an open neighbourhood \(V \ni x\) and a section
  \(s \in \struct X(V)\) whose germ at the generic point \(\eta\) is the chosen uniformizer \(t\) at
  \(x\), whose germ at every point \(y \in V\) is a nonzerodivisor of \(\struct{X,y}\), and is
  moreover a unit whenever \(y \neq x\). Thus \(s\) is a uniformizer at \(x\) whose only zero on
  \(V\) is the point \(x\) itself, and whose realization as a rational function is recorded to be
  \(t\).
\end{lemma}
\begin{proof}
  \leanok
  Let \(t \in K(X)\) be a uniformizer at \(x\), so \(\mathrm{ord}_x t = 1\)
  (Lemma~\ref{lem:uniformizer}); it is a nonzero rational function. Having nonnegative order at
  \(x\), it is integral there: \(t\) is the image of an element of the stalk \(\struct{X,x}\)
  (Lemma~\ref{lem:exists_stalk_of_ord_le_one}). Represent that stalk element by a section \(s_0\)
  over some open neighbourhood \(W_0 \ni x\). Its germ at the generic point is the image of its
  germ at \(x\) under \(\struct{X,x} \to K(X)\) (Lemma~\ref{lem:germ_generic_eq_algebraMap_germ}),
  so \(\mathrm{germ}_\eta(s_0) = t\).

  Now \(t\), being a nonzero rational function, has nonzero order at only finitely many closed
  points (Theorem~\ref{thm:ordZ_support_finite}); let \(\mathrm{bad}\) be the finite set of those
  points \emph{other than} \(x\). Each closed point is a closed singleton
  (Theorem~\ref{thm:closedpoint_isClosed}), so \(\mathrm{bad}\) is a finite closed set; removing it
  from \(W_0\) leaves an open set
  \[
    V := W_0 \setminus \mathrm{bad}, \qquad x \in V
  \]
  (indeed \(x \notin \mathrm{bad}\)). Restrict \(s_0\) to \(V\) and call the result \(s\); its germ
  at \(y \in V\) still maps to \(t\) under \(\struct{X,y} \to K(X)\). In particular at the generic
  point the germ is exactly \(\mathrm{germ}_\eta(s) = t\), the tracked realization.

  \emph{Regularity.} For \(y \in V\), the germ \(\mathrm{germ}_y(s)\) maps to \(t \neq 0\) in the
  function field under the localization \(\struct{X,y} \to K(X)\); since that map is injective on
  the domain stalk, \(\mathrm{germ}_y(s) \neq 0\), i.e.\ it is a nonzerodivisor.

  \emph{Unit away from \(x\).} Let \(y \in V\) with \(y \neq x\). If \(y = \eta\), then
  \(\mathrm{germ}_\eta(s) = t \neq 0\) is a unit of the field \(K(X)\). Otherwise \(y\) is a closed
  point; suppose \(\mathrm{germ}_y(s)\) were not a unit of \(\struct{X,y}\). A section invertible at
  a closed point has order of vanishing \(0\) there (Lemma~\ref{lem:ord_eq_one_of_mem_basicOpen});
  contrapositively, non-invertibility of \(s\) at \(y\) forces \(\mathrm{ord}_y t \neq 0\)
  (recall \(\mathrm{germ}_\eta(s) = t\), and \(\mathrm{ord}_y\) is the order homomorphism
  \ref{def:scheme_ordZ}). Then \(y\) is a closed point where \(t\) has nonzero order, distinct from
  \(x\), so \(y \in \mathrm{bad}\) --- contradicting \(y \in V = W_0 \setminus \mathrm{bad}\). Hence
  \(\mathrm{germ}_y(s)\) is a unit.
\end{proof}

\begin{definition}[The point divisor \(1 \cdot x\)]
  \label{def:pointDivisor}
  \lean{AlgebraicGeometry.Scheme.pointDivisor,
    AlgebraicGeometry.Scheme.germGeneric_pointDivisorEqn_self}
  \uses{def:localEquations, lem:exists_pointLocalEquation, thm:closedpoint_isClosed}
  \leanok
  For a closed point \(x\), the \emph{point divisor} \(1 \cdot x\) is the local-equation system on
  the pointed cover
  \[
    \mathcal U(y) = \begin{cases} V & y = x, \\ X \setminus \{x\} & y \neq x, \end{cases}
  \]
  with \(V\) the neighbourhood of Lemma~\ref{lem:exists_pointLocalEquation}, whose equation on the
  distinguished member \(V\) is the uniformizer-section \(s\) and whose equation on every other
  member \(X \setminus \{x\}\) is the constant \(1\). Its defining data is fully accessible: in
  particular the germ at the generic point \(\eta\) of the equation on the member at \(x\) is the
  chosen uniformizer \(t\), which is what pins the Weil divisor these equations cut out.
\end{definition}
\begin{proof}
  \leanok
  The complement \(X \setminus \{x\}\) is open because \(\{x\}\) is closed
  (Theorem~\ref{thm:closedpoint_isClosed}), and it contains every \(y \neq x\), so \(\mathcal U\) is
  a pointed cover. Regularity holds member by member: on \(V\) the germs of \(s\) are
  nonzerodivisors (Lemma~\ref{lem:exists_pointLocalEquation}), and on \(X \setminus \{x\}\) the
  germs of the constant \(1\) are units, hence nonzerodivisors. For the overlap ratios, consider a
  pair \((a, b)\). If neither or both of \(a, b\) equal \(x\), the two equations on the overlap are
  equal (both \(1\), or both restrictions of \(s\) on \(V \cap V = V\)), so the ratio is the unit
  \(1\). If exactly one of \(a, b\) equals \(x\), the overlap is contained in \(V \cap (X \setminus
  \{x\}) = V \setminus \{x\}\), where \(s\) is a unit (Lemma~\ref{lem:exists_pointLocalEquation});
  the ratio of the two equations \(s\) and \(1\) is then \(s\) or \(s^{-1}\), a unit there. Thus the
  data is a local-equation system. The equation on the member at \(x\) is the section \(s\), whose
  germ at \(\eta\) is the tracked uniformizer \(t\) (Lemma~\ref{lem:exists_pointLocalEquation}).
\end{proof}

\begin{definition}[The class of a Weil divisor]
  \label{def:divisorClass}
  \lean{AlgebraicGeometry.Scheme.divisorClass}
  \uses{def:pointDivisor, def:localEquations_picClass, def:curveDivisor}
  \leanok
  For a Weil divisor \(D \in \Div(X)\) (\ref{def:curveDivisor}), its \emph{Picard class} is the
  finite product
  \[
    \struct X(D) = \prod_{x} \struct X(x)^{D_x} \in \Pic(X),
  \]
  over the finite support of \(D\), where \(\struct X(x) := \mathrm{picClass}(1 \cdot x) \in
  \Pic(X)\) is the class of the point divisor (\ref{def:pointDivisor}, \ref{def:localEquations_picClass}).
  A negative coefficient \(D_x\) contributes the inverse class, so the exponent is an integer power
  in the abelian group \(\Pic(X)\); the assignment is defined on all of \(\Div(X)\), with no
  effective/anti-effective case split. The product is finite because \(D\) is finitely supported
  and \(\struct X(x)^0 = 1\).
\end{definition}

\begin{theorem}[Additivity of the divisor class]
  \label{thm:divisorClass_add}
  \lean{AlgebraicGeometry.Scheme.divisorClass_add}
  \uses{def:divisorClass}
  \leanok
  The class map \(D \mapsto \struct X(D)\) is a homomorphism \(\Div(X) \to \Pic(X)\): for all
  \(D, D' \in \Div(X)\),
  \[
    \struct X(D + D') = \struct X(D) \cdot \struct X(D') .
  \]
\end{theorem}
\begin{proof}
  \leanok
  The class is the finitely supported product \(D \mapsto \prod_x \struct X(x)^{D_x}\). At each
  point \(x\) the exponentiation \(n \mapsto \struct X(x)^n\) is a homomorphism \(\Z \to \Pic(X)\):
  it sends \(0\) to the identity and satisfies \(\struct X(x)^{m+n} = \struct X(x)^m \cdot \struct
  X(x)^n\). Hence, taking the product over the pointwise sum \((D + D')_x = D_x + D'_x\) in the
  abelian group \(\Pic(X)\), the summands separate and the product over \(D + D'\) factors as the
  product over \(D\) times the product over \(D'\), giving \(\struct X(D + D') = \struct X(D) \cdot
  \struct X(D')\).
\end{proof}

\begin{theorem}[Normalization at a one-point divisor]
  \label{thm:divisorClass_single}
  \lean{AlgebraicGeometry.Scheme.divisorClass_single_eq_pointDivisor}
  \uses{def:divisorClass, def:curveDivisor_single, def:pointDivisor, def:localEquations_picClass}
  \leanok
  For a closed point \(x\), the class of the one-point divisor \(1 \cdot x\)
  (\ref{def:curveDivisor_single}) is the point-divisor class:
  \[
    \struct X(1 \cdot x) = \mathrm{picClass}(1 \cdot x) = \struct X(x) .
  \]
\end{theorem}
\begin{proof}
  \leanok
  The one-point divisor \(1 \cdot x\) is supported at the single point \(x\) with coefficient \(1\)
  (\ref{def:curveDivisor_single}), so the defining product of \(\struct X(1 \cdot x)\)
  (\ref{def:divisorClass}) reduces to the single factor \(\struct X(x)^1 = \struct X(x)\).
\end{proof}

\section{Meromorphic presentations of \v Cech Picard classes}

The remainder of this chapter carries out, at the level of \v Cech cocycles, the classical
identification of the group of Weil divisors modulo principal equivalence with the Picard group
of an integral curve. The device that replaces every sheaf-theoretic gluing argument is the
\emph{generic-point embedding}: on an integral scheme every nonempty open contains the generic
point \(\eta\), and taking germs at \(\eta\) embeds the sections over such an open into the
function field \(K(X)\). A \v Cech Picard class can therefore be \emph{presented meromorphically}
--- by a pointed cover, a unit cocycle on it, and one rational function per member --- after
which every cochain comparison downstream is a literal equality of elements of the field
\(K(X)\), never a gluing of sheaf sections.

\begin{definition}[The generic-point embedding of unit sections]
  \label{def:germGenericUnits}
  \lean{AlgebraicGeometry.Scheme.germGenericUnits,
    AlgebraicGeometry.Scheme.germGenericUnits_unitsRestrict,
    AlgebraicGeometry.Scheme.germGenericUnits_injective}
  \leanok
  Let \(X\) be an integral scheme with generic point \(\eta\) and \(U\) an open with
  \(\eta \in U\). Taking the germ at \(\eta\) is a homomorphism of groups
  \[
    \mathrm{germ}_\eta \colon \Gamma(X,U)^{\times} \longrightarrow K(X)^{\times},
  \]
  the \emph{generic-point embedding} of unit sections into the units of the function field. It is
  restriction-invariant --- for \(\eta \in W \le U\) it agrees with restriction
  \(\Gamma(X,U)^{\times} \to \Gamma(X,W)^{\times}\) followed by the embedding on \(W\) --- and, on
  an integral scheme, injective.
\end{definition}
\begin{proof}
  \leanok
  The germ at \(\eta\) is a ring homomorphism \(\Gamma(X,U) \to K(X)\) carrying units to units, so
  it restricts to a group homomorphism on the unit groups. Restriction-invariance is the
  functoriality of germs along \(W \le U\). For injectivity, on an integral scheme a section over
  a nonempty open is determined by its germ at \(\eta\) (which lies in every nonempty open); hence
  two unit sections with the same germ at \(\eta\) are equal.
\end{proof}

\begin{lemma}[Pointed covers contain the generic point]
  \label{lem:pointedCover_genericPoint_mem}
  \lean{AlgebraicGeometry.Scheme.PointedCover.genericPoint_mem_opens,
    AlgebraicGeometry.Scheme.PointedCover.genericPoint_mem_inf}
  \leanok
  On an irreducible scheme \(X\), every member \(\mathcal U(x)\) of a pointed cover contains the
  generic point \(\eta\), and hence so does every pairwise overlap \(\mathcal U(x) \cap \mathcal
  U(y)\).
\end{lemma}
\begin{proof}
  \leanok
  A pointed cover assigns to each \(x\) an open \(\mathcal U(x) \ni x\), in particular nonempty;
  on an irreducible space the generic point lies in every nonempty open, so \(\eta \in \mathcal
  U(x)\). Intersecting two such memberships gives \(\eta \in \mathcal U(x) \cap \mathcal U(y)\).
\end{proof}

\begin{definition}[Meromorphic presentation]
  \label{def:meromorphicPresentation}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass}
  \uses{def:germGenericUnits, lem:pointedCover_genericPoint_mem}
  \leanok
  A \emph{meromorphic presentation} of a \v Cech Picard class on an integral scheme \(X\) consists
  of a pointed cover \(\mathcal U\), a unit \v Cech \(1\)-cocycle \(\gamma\) on \(\mathcal U\), and
  a family \((f_x)_x\) of units \(f_x \in K(X)^{\times}\), one per member, satisfying the
  \emph{ratio law}
  \[
    f_x \cdot f_y^{-1} = \mathrm{germ}_\eta(\gamma_{xy}) \qquad \text{for every pair } x, y,
  \]
  where \(\gamma_{xy} \in \Gamma(X, \mathcal U(x) \cap \mathcal U(y))^{\times}\) is the cocycle
  value. Its \emph{Picard class} is
  \[
    \mathrm{picClass}(P) = [\mathcal U, \gamma] \in \Pic(X).
  \]
\end{definition}
\begin{proof}
  \leanok
  Each overlap \(\mathcal U(x) \cap \mathcal U(y)\) contains \(\eta\)
  (\ref{lem:pointedCover_genericPoint_mem}), so the germ \(\mathrm{germ}_\eta(\gamma_{xy})\)
  (\ref{def:germGenericUnits}) is defined and the ratio law is a condition in \(K(X)^{\times}\).
  The Picard class is the class in the colimit \(\Pic(X)\) of the unit cocycle \(\gamma\) on
  \(\mathcal U\).
\end{proof}

\begin{theorem}[Existence of meromorphic presentations]
  \label{thm:exists_meromorphicPresentation}
  \lean{AlgebraicGeometry.Scheme.exists_meromorphicPresentation}
  \uses{def:meromorphicPresentation, def:germGenericUnits, lem:pointedCover_genericPoint_mem}
  \leanok
  Every \v Cech Picard class \(L \in \Pic(X)\) of an integral scheme is the class of a meromorphic
  presentation.
\end{theorem}
\begin{proof}
  \leanok
  Represent \(L\) by a unit \(1\)-cocycle \(\gamma\) on a pointed cover \(\mathcal U\). Use the
  generic point itself as base index: set
  \[
    f_x := \mathrm{germ}_\eta(\gamma_{x\eta}) \in K(X)^{\times},
  \]
  the germ at \(\eta\) of the cocycle value on the pair \((x, \eta)\), whose overlap contains
  \(\eta\) (\ref{lem:pointedCover_genericPoint_mem}). The cocycle identity for the triple
  \((x, y, \eta)\) reads \(\gamma_{xy}\, \gamma_{y\eta} = \gamma_{x\eta}\) on the triple overlap,
  which contains \(\eta\); applying the generic-point embedding, whose value is unchanged by the
  restriction to the triple overlap (\ref{def:germGenericUnits}), and rearranging gives
  \[
    \mathrm{germ}_\eta(\gamma_{xy}) = \mathrm{germ}_\eta(\gamma_{x\eta}) \cdot
      \mathrm{germ}_\eta(\gamma_{y\eta})^{-1} = f_x \cdot f_y^{-1},
  \]
  the ratio law. Thus \((\mathcal U, \gamma, f)\) is a meromorphic presentation
  (\ref{def:meromorphicPresentation}) with class \([\mathcal U, \gamma] = L\).
\end{proof}

\begin{lemma}[The presentation of a local-equation system]
  \label{lem:localEquations_presentation}
  \lean{AlgebraicGeometry.Scheme.LocalEquations.presentation,
    AlgebraicGeometry.Scheme.LocalEquations.presentation_picClass}
  \uses{def:meromorphicPresentation, def:localEquations, lem:localEquations_ratioUnit,
    def:localEquations_picClass}
  \leanok
  Let \(E\) be a local-equation system on \(X\) (\ref{def:localEquations}). The germs at \(\eta\)
  of its regular equations, \(f_x := \mathrm{germ}_\eta(E.\mathrm{eqn}_x) \in K(X)^{\times}\), form
  a meromorphic presentation whose cocycle is the transition-unit cocycle of \(E\) and whose class
  is the Picard class \(\mathrm{picClass}(E)\) of \(E\) (\ref{def:localEquations_picClass}).
\end{lemma}
\begin{proof}
  \leanok
  Each equation \(E.\mathrm{eqn}_x\) is regular, so its germ at \(\eta\) is a nonzerodivisor of the
  field \(K(X)\), that is, a nonzero element, hence a unit \(f_x \in K(X)^{\times}\). The defining
  equation \(E.\mathrm{eqn}_x = g_{xy} \cdot E.\mathrm{eqn}_y\) on the overlap
  (\ref{lem:localEquations_ratioUnit}), pushed to the generic point, gives \(f_x = \mathrm{germ}_\eta(g_{xy}) \cdot f_y\),
  i.e.\ the ratio law \(f_x \cdot f_y^{-1} = \mathrm{germ}_\eta(g_{xy})\) with the transition-unit
  cocycle \(g\) of \(E\). The presented class is \([\mathcal U, g] = \mathrm{picClass}(E)\)
  (\ref{def:localEquations_picClass}).
\end{proof}

\section{The divisor of a meromorphic presentation}

We now specialize to the curve bundle \(X\) of Chapter~\ref{chap:RiemannRoch}: integral, smooth of
relative dimension one and quasi-compact over the field \(K\), with generic point \(\eta\). The
trivializing elements of a meromorphic presentation cut out a Weil divisor, read off point by
point from their orders of vanishing.

\begin{theorem}[Unit sections have trivial order]
  \label{thm:ordZ_germGenericUnits}
  \lean{AlgebraicGeometry.Scheme.ordZ_germGenericUnits}
  \uses{def:germGenericUnits, def:scheme_ordZ, lem:ord_eq_one_of_mem_basicOpen}
  \leanok
  For an open \(U \ni \eta\), a unit section \(u \in \Gamma(X,U)^{\times}\), and a closed point
  \(x \in U\), the germ at \(\eta\) of \(u\) has trivial order at \(x\):
  \[
    \mathrm{ord}_x\bigl(\mathrm{germ}_\eta(u)\bigr) = 0.
  \]
\end{theorem}
\begin{proof}
  \leanok
  The section \(u\) is invertible at \(x\), so \(x\) lies in the basic open set where the
  underlying section is invertible. A rational function that is the germ at \(\eta\) of a section
  invertible at \(x\) has order \(0\) there (\ref{lem:ord_eq_one_of_mem_basicOpen}).
\end{proof}

\begin{theorem}[Piece-independence of the order]
  \label{thm:ordZ_elem_eq}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.ordZ_elem_eq}
  \uses{def:meromorphicPresentation, thm:ordZ_germGenericUnits, def:scheme_ordZ}
  \leanok
  Let \(P\) be a meromorphic presentation and \(x\) a closed point lying in a member
  \(\mathcal U(y)\) of its cover. Then the trivializing element \(f_y\) of that piece has the same
  order at \(x\) as the element \(f_x\) indexed by \(x\) itself:
  \[
    \mathrm{ord}_x(f_y) = \mathrm{ord}_x(f_x).
  \]
\end{theorem}
\begin{proof}
  \leanok
  By the ratio law, \(f_x \cdot f_y^{-1} = \mathrm{germ}_\eta(\gamma_{xy})\) with \(\gamma_{xy}\) a
  unit section over \(\mathcal U(x) \cap \mathcal U(y)\), an overlap containing the closed point
  \(x\) (which lies in \(\mathcal U(x)\) and, by hypothesis, in \(\mathcal U(y)\)). Its germ at
  \(\eta\) has order \(0\) at \(x\) (\ref{thm:ordZ_germGenericUnits}). Since \(\mathrm{ord}_x\) is a
  homomorphism (\ref{def:scheme_ordZ}), \(\mathrm{ord}_x(f_x) - \mathrm{ord}_x(f_y) =
  \mathrm{ord}_x(f_x \cdot f_y^{-1}) = 0\).
\end{proof}

\begin{theorem}[Finite support of the orders]
  \label{thm:ordZ_elem_support_finite}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.ordZ_elem_support_finite}
  \uses{def:meromorphicPresentation, thm:ordZ_elem_eq, thm:ordZ_support_finite}
  \leanok
  For a meromorphic presentation \(P\) on the quasi-compact curve, the set of closed points \(x\)
  at which the piece-indexed element \(f_x\) has nonzero order is finite.
\end{theorem}
\begin{proof}
  \leanok
  The curve is quasi-compact, so the members \(\mathcal U(i)\) of the cover admit a finite
  subcover indexed by a finite set \(T\). If a closed point \(x\) has \(\mathrm{ord}_x(f_x) \neq
  0\), choose \(i \in T\) with \(x \in \mathcal U(i)\); by piece-independence
  (\ref{thm:ordZ_elem_eq}), \(\mathrm{ord}_x(f_x) = \mathrm{ord}_x(f_i) \neq 0\), so \(x\) lies in
  the order support of the single rational function \(f_i\), which is finite
  (\ref{thm:ordZ_support_finite}). Hence the whole support is contained in the finite union over
  \(i \in T\) of these finite sets.
\end{proof}

\begin{definition}[The divisor of a presentation]
  \label{def:presentationDivisor}
  \lean{AlgebraicGeometry.Scheme.presentationDivisor,
    AlgebraicGeometry.Scheme.coeffAt_presentationDivisor}
  \uses{def:meromorphicPresentation, thm:ordZ_elem_eq, thm:ordZ_elem_support_finite,
    def:curveDivisor, def:scheme_ordZ}
  \leanok
  For a meromorphic presentation \(P\) on the curve, its \emph{divisor} is the Weil divisor
  \[
    \mathrm{presentationDivisor}(P) = \sum_x \mathrm{ord}_x(f_x)\, x \in \Div(X),
  \]
  whose coefficient at each closed point \(x\) is the order at \(x\) of the piece-indexed
  trivializing element \(f_x\).
\end{definition}
\begin{proof}
  \leanok
  The assignment \(x \mapsto \mathrm{ord}_x(f_x)\) has finite support
  (\ref{thm:ordZ_elem_support_finite}), so it defines an element of \(\Div(X)\)
  (\ref{def:curveDivisor}); by piece-independence (\ref{thm:ordZ_elem_eq}) the coefficient is the
  order of the local trivialization near \(x\), whichever piece is used to read it off.
\end{proof}

\section{The calculus of meromorphic presentations}

Meromorphic presentations multiply, invert, and have a unit --- pointwise on the trivializing
elements, and, on the cocycles, by restriction to the common refinement. No group laws are
claimed (the covers of \((P \cdot Q) \cdot R\) and \(P \cdot (Q \cdot R)\) differ by
associativity of intersection), and none are needed: every identification is made at the level of
the Picard class and of the divisor.

\begin{definition}[The principal presentation]
  \label{def:meromorphicPresentation_principal}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.principal}
  \uses{def:meromorphicPresentation}
  \leanok
  For \(g \in K(X)^{\times}\), the \emph{principal presentation} of \(g\) is the trivial cocycle on
  the one-member cover \(\{X\}\), trivialized by the constant \(g\) (so \(f_x = g\) for all
  \(x\)).
\end{definition}
\begin{proof}
  \leanok
  The cocycle is trivial, and the ratio law holds because \(f_x \cdot f_y^{-1} = g \cdot g^{-1} =
  1 = \mathrm{germ}_\eta(1)\).
\end{proof}

\begin{theorem}[Multiplicativity of the presented class]
  \label{thm:meromorphicPresentation_picClass_hom}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass_one,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass_mul,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass_inv,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass_principal}
  \uses{def:meromorphicPresentation, def:meromorphicPresentation_principal}
  \leanok
  Write \(1\) for the \emph{unit presentation} (the trivial cocycle on \(\{X\}\) with all elements
  \(1\)), \(P \cdot Q\) for the \emph{product} on the common refinement \(\mathcal U_P \cap
  \mathcal U_Q\) (trivializing elements multiplied pointwise, cocycles restricted and multiplied),
  and \(P^{-1}\) for the \emph{inverse} (trivializing elements and cocycle inverted). Then the
  presented class is multiplicative:
  \[
    \mathrm{picClass}(1) = 1, \quad \mathrm{picClass}(P \cdot Q) = \mathrm{picClass}(P) \cdot
      \mathrm{picClass}(Q), \quad \mathrm{picClass}(P^{-1}) = \mathrm{picClass}(P)^{-1},
  \]
  and \(\mathrm{picClass}(\mathrm{principal}\, g) = 1\).
\end{theorem}
\begin{proof}
  \leanok
  The class of a presentation is the class of its cocycle. The trivial cocycle has trivial class,
  giving \(\mathrm{picClass}(1) = 1\); the principal presentation
  (\ref{def:meromorphicPresentation_principal}) also carries the trivial cocycle, so
  \(\mathrm{picClass}(\mathrm{principal}\, g) = 1\). Inverting a cocycle inverts its class,
  giving \(\mathrm{picClass}(P^{-1}) = \mathrm{picClass}(P)^{-1}\). For the product, restricting
  each cocycle to the common refinement leaves its class unchanged, and the class of a product of
  cocycles is the product of the classes, so \(\mathrm{picClass}(P \cdot Q) = \mathrm{picClass}(P)
  \cdot \mathrm{picClass}(Q)\).
\end{proof}

\begin{theorem}[Additivity of the presentation divisor]
  \label{thm:presentationDivisor_hom}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.presentationDivisor_one,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.presentationDivisor_mul,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.presentationDivisor_inv,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.presentationDivisor_principal}
  \uses{def:presentationDivisor, def:meromorphicPresentation_principal, def:divOf}
  \leanok
  With the operations of \ref{thm:meromorphicPresentation_picClass_hom}, the divisor is additive:
  \[
    \mathrm{presentationDivisor}(1) = 0, \quad \mathrm{presentationDivisor}(P \cdot Q) =
      \mathrm{presentationDivisor}(P) + \mathrm{presentationDivisor}(Q),
  \]
  \(\mathrm{presentationDivisor}(P^{-1}) = -\mathrm{presentationDivisor}(P)\), and the divisor of
  the principal presentation of \(g\) is the principal divisor:
  \[
    \mathrm{presentationDivisor}(\mathrm{principal}\, g) = \mathrm{div}(g).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Compare coefficients at each closed point \(x\) (\ref{def:presentationDivisor}). The element of
  \(1\) at \(x\) is \(1\), of order \(0\), so \(\mathrm{presentationDivisor}(1) = 0\). The element
  of \(P \cdot Q\) at \(x\) is \(f_x \cdot f'_x\), and \(\mathrm{ord}_x\) is a homomorphism
  (\ref{def:scheme_ordZ}), giving additivity; inversion negates the order. For the principal
  presentation the element at \(x\) is \(g\), so the coefficient is \(\mathrm{ord}_x(g)\), the
  coefficient of \(\mathrm{div}(g)\) (\ref{def:divOf}).
\end{proof}

\section{The class law: equal divisors give equal classes}

The heart of the meromorphic bridge is that the \v Cech Picard class of a presentation depends
only on its divisor. Its local input is that a rational function of trivial order is the germ of a
unit section; its global mechanism is that the cohomology relating two presentations of equal
divisor can be verified entirely inside \(K(X)^{\times}\), through the injective generic-point
embedding --- on an integral scheme no gluing of sheaf sections is ever required.

\begin{lemma}[Order matching produces a unit section]
  \label{lem:exists_germGenericUnits_ordMatch}
  \lean{AlgebraicGeometry.Scheme.exists_germGenericUnits_eq_of_forall_ordZ_eq_one,
    AlgebraicGeometry.Scheme.exists_germGenericUnits_eq_mul_inv_of_forall_ordZ_eq}
  \uses{def:germGenericUnits, def:scheme_ordZ, def:divisorSections, lem:exists_section_germ_eq}
  \leanok
  Let \(V\) be a nonempty open (\(\eta \in V\)). A rational function \(q \in K(X)^{\times}\) whose
  order vanishes at every closed point of \(V\) is the germ at \(\eta\) of a unit section over
  \(V\): there is \(u \in \Gamma(X,V)^{\times}\) with \(\mathrm{germ}_\eta(u) = q\). Consequently
  two rational functions \(g, h \in K(X)^{\times}\) with equal order at every closed point of
  \(V\) differ by the germ of a unit section: \(\mathrm{germ}_\eta(u) = g \cdot h^{-1}\) for some
  \(u \in \Gamma(X,V)^{\times}\).
\end{lemma}
\begin{proof}
  \leanok
  Since \(\mathrm{ord}_x(q) = 0\) at every closed point \(x \in V\), both \(q\) and \(q^{-1}\) have
  poles bounded by the zero divisor on \(V\), so both lie in \(\mathcal O(0)(V)\)
  (\ref{def:divisorSections}). Each is therefore the germ at \(\eta\) of a section over \(V\)
  (\ref{lem:exists_section_germ_eq}); let \(s, s'\) be sections with \(\mathrm{germ}_\eta(s) = q\)
  and \(\mathrm{germ}_\eta(s') = q^{-1}\). Their product has \(\mathrm{germ}_\eta(s s') = q q^{-1}
  = 1\), and on the integral scheme a section is determined by its germ at \(\eta\), so \(s s' =
  1\); thus \(s\) is a unit section with \(\mathrm{germ}_\eta(s) = q\). The two-element form is
  this applied to \(q = g \cdot h^{-1}\), whose order at each closed point of \(V\) is
  \(\mathrm{ord}_x(g) - \mathrm{ord}_x(h) = 0\).
\end{proof}

\begin{theorem}[The class law]
  \label{thm:picClass_eq_of_presentationDivisor_eq}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass_eq_of_presentationDivisor_eq}
  \uses{def:presentationDivisor, thm:ordZ_elem_eq, lem:exists_germGenericUnits_ordMatch,
    def:meromorphicPresentation}
  \leanok
  Two meromorphic presentations with equal divisors present equal \v Cech Picard classes: if
  \(\mathrm{presentationDivisor}(P) = \mathrm{presentationDivisor}(Q)\) then \(\mathrm{picClass}(P)
  = \mathrm{picClass}(Q)\).
\end{theorem}
\begin{proof}
  \leanok
  Equal divisors mean \(\mathrm{ord}_z(f_z) = \mathrm{ord}_z(f'_z)\) at every closed point \(z\),
  comparing coefficients (\ref{def:presentationDivisor}). Fix a member indexed by \(x\) of the
  common refinement \(\mathcal W := \mathcal U_P \cap \mathcal U_Q\) and a closed point \(z \in
  \mathcal W(x)\). Piece-independence (\ref{thm:ordZ_elem_eq}) gives \(\mathrm{ord}_z(f_x) =
  \mathrm{ord}_z(f_z)\) and \(\mathrm{ord}_z(f'_x) = \mathrm{ord}_z(f'_z)\), so \(\mathrm{ord}_z(f_x)
  = \mathrm{ord}_z(f'_x)\): the elements \(f_x\) and \(f'_x\) have equal order at every closed
  point of \(\mathcal W(x)\). By order matching (\ref{lem:exists_germGenericUnits_ordMatch}) there
  is a unit section \(u_x \in \Gamma(X, \mathcal W(x))^{\times}\) with \(\mathrm{germ}_\eta(u_x) =
  f_x \cdot (f'_x)^{-1}\).

  The \(0\)-cochain \((u_x^{-1})_x\) exhibits the restricted cocycles \(\gamma|_{\mathcal W}\) and
  \(\gamma'|_{\mathcal W}\) as cohomologous. The required coboundary identity is, on each overlap
  \(\mathcal W(x) \cap \mathcal W(y)\), an equality of unit sections; applying the injective
  generic-point embedding (\ref{def:germGenericUnits}) turns it into the identity
  \[
    \mathrm{germ}_\eta(u_x)^{-1} \cdot \bigl(f_x f_y^{-1}\bigr) = \bigl(f'_x (f'_y)^{-1}\bigr) \cdot
      \mathrm{germ}_\eta(u_y)^{-1}
  \]
  in the abelian group \(K(X)^{\times}\), where \(f_x f_y^{-1}\) and \(f'_x (f'_y)^{-1}\) are the
  germs of the restricted cocycle values by the ratio law; substituting \(\mathrm{germ}_\eta(u_x) =
  f_x (f'_x)^{-1}\) makes both sides equal. Cohomologous cocycles on \(\mathcal W\) have the same
  class, and restricting a cocycle to a refinement preserves its \v Cech class, so
  \(\mathrm{picClass}(P) = [\mathcal W, \gamma|_{\mathcal W}] = [\mathcal W, \gamma'|_{\mathcal W}]
  = \mathrm{picClass}(Q)\).
\end{proof}

\section{Extraction: equal classes differ by a principal divisor}

\begin{theorem}[Extraction and the meromorphic characterization]
  \label{thm:meromorphicPresentation_extraction}
  \lean{AlgebraicGeometry.Scheme.MeromorphicPresentation.exists_divOf_of_picClass_eq,
    AlgebraicGeometry.Scheme.MeromorphicPresentation.picClass_eq_iff_exists_divOf}
  \uses{thm:picClass_eq_of_presentationDivisor_eq, thm:meromorphicPresentation_picClass_hom,
    thm:presentationDivisor_hom, def:presentationDivisor, thm:ordZ_germGenericUnits,
    def:meromorphicPresentation_principal, def:divOf}
  \leanok
  Two meromorphic presentations \(P, Q\) present the same \v Cech Picard class if and only if their
  divisors differ by a principal divisor:
  \[
    \mathrm{picClass}(P) = \mathrm{picClass}(Q) \iff \mathrm{presentationDivisor}(P) -
      \mathrm{presentationDivisor}(Q) = \mathrm{div}(g) \text{ for some } g \in K(X)^{\times}.
  \]
\end{theorem}
\begin{proof}
  \leanok
  \((\Rightarrow)\) Equal classes are, on a common refinement \(\mathcal W\), cohomologous
  cocycles: there is a \(0\)-cochain \((\alpha_x)\) of unit sections \(\alpha_x \in \Gamma(X,
  \mathcal W(x))^{\times}\) with \(\alpha_x \cdot \gamma_{xy}|_{\mathcal W} = \gamma'_{xy}|_{\mathcal
  W} \cdot \alpha_y\) on each overlap. Put
  \[
    c_x := f_x \cdot (f'_x)^{-1} \cdot \mathrm{germ}_\eta(\alpha_x) \in K(X)^{\times}.
  \]
  Applying the generic-point embedding to the coboundary identity and rearranging in the abelian
  group \(K(X)^{\times}\) shows \(c_x = c_y\) for all \(x, y\); as the members cover \(X\), the
  \(c_x\) are a single rational function \(g\). At a closed point \(z\), choosing \(x\) with \(z
  \in \mathcal W(x)\), the germ \(\mathrm{germ}_\eta(\alpha_x)\) has order \(0\) at \(z\)
  (\ref{thm:ordZ_germGenericUnits}), so
  \[
    \mathrm{ord}_z(g) = \mathrm{ord}_z(f_z) - \mathrm{ord}_z(f'_z) =
      \mathrm{presentationDivisor}(P)_z - \mathrm{presentationDivisor}(Q)_z .
  \]
  Hence \(\mathrm{div}(g) = \mathrm{presentationDivisor}(P) - \mathrm{presentationDivisor}(Q)\).

  \((\Leftarrow)\) If \(\mathrm{presentationDivisor}(P) - \mathrm{presentationDivisor}(Q) =
  \mathrm{div}(g)\), then by additivity (\ref{thm:presentationDivisor_hom}) the presentation \(Q
  \cdot \mathrm{principal}\, g\) has divisor \(\mathrm{presentationDivisor}(Q) + \mathrm{div}(g) =
  \mathrm{presentationDivisor}(P)\); the class law (\ref{thm:picClass_eq_of_presentationDivisor_eq})
  gives \(\mathrm{picClass}(Q \cdot \mathrm{principal}\, g) = \mathrm{picClass}(P)\), while
  \(\mathrm{picClass}(Q \cdot \mathrm{principal}\, g) = \mathrm{picClass}(Q)\) by multiplicativity
  and \(\mathrm{picClass}(\mathrm{principal}\, g) = 1\)
  (\ref{thm:meromorphicPresentation_picClass_hom}). Hence \(\mathrm{picClass}(P) =
  \mathrm{picClass}(Q)\).
\end{proof}

\section{The point presentation}

To feed the class map with concrete divisors we realize each one-point divisor \(1 \cdot x\) by a
meromorphic presentation whose defining data is tracked: its equation at \(x\) is a uniformizer
whose germ at \(\eta\) is recorded.

\begin{lemma}[A tracked point-uniformizer]
  \label{lem:pointUniformizerData}
  \lean{AlgebraicGeometry.Scheme.PointUniformizerData,
    AlgebraicGeometry.Scheme.nonempty_pointUniformizerData,
    AlgebraicGeometry.Scheme.pointUniformizerData}
  \uses{lem:uniformizer, lem:exists_stalk_of_ord_le_one, lem:germ_generic_eq_algebraMap_germ,
    thm:ordZ_support_finite, thm:closedpoint_isClosed, def:scheme_ordZ,
    lem:ord_eq_one_of_mem_basicOpen}
  \leanok
  For a closed point \(x\) of the curve, a \emph{tracked point-uniformizer} at \(x\) is an open
  neighbourhood \(V \ni x\) together with a section \(s \in \Gamma(X,V)\) that is regular (its
  germs are nonzerodivisors), whose germ at \(\eta\) is a chosen uniformizer \(t\) at \(x\)
  (\(\mathrm{ord}_x t = 1\)), and which is a unit at every point of \(V\) other than \(x\). Such
  data exists.
\end{lemma}
\begin{proof}
  \leanok
  Choose a uniformizer \(t \in K(X)\) at \(x\) (\ref{lem:uniformizer}), a nonzero rational function
  with \(\mathrm{ord}_x t = 1\). Having nonnegative order at \(x\), \(t\) is integral there, so it
  is the germ at \(\eta\) of a section \(s_0\) over a neighbourhood \(W_0 \ni x\)
  (\ref{lem:exists_stalk_of_ord_le_one}, \ref{lem:germ_generic_eq_algebraMap_germ}). Remove from
  \(W_0\) the finitely many closed points other than \(x\) at which \(t\) has nonzero order
  (finite by \ref{thm:ordZ_support_finite}, and a finite union of closed points is closed by
  \ref{thm:closedpoint_isClosed}); the result \(V := W_0 \setminus \mathrm{bad}\) is an open
  neighbourhood of \(x\), and the restriction \(s\) of \(s_0\) to \(V\) still has germ \(t\) at
  \(\eta\).

  \emph{Regularity.} For \(y \in V\), the germ of \(s\) maps to \(t \neq 0\) under the injective
  localization \(\struct{X,y} \to K(X)\), hence is a nonzerodivisor.

  \emph{Unit away from \(x\).} Let \(y \in V\), \(y \neq x\). If \(y = \eta\), then
  \(\mathrm{germ}_\eta(s) = t\) is a unit of the field. If \(y\) is a closed point and the germ of
  \(s\) at \(y\) were not a unit, then \(t\) would have nonzero order at \(y\) (a section invertible
  at a closed point has order \(0\) there, \ref{lem:ord_eq_one_of_mem_basicOpen}, contrapositively,
  reading order through \ref{def:scheme_ordZ}); but then \(y\) is a removed point, contradicting
  \(y \in V\). So \(s\) is a unit at \(y\).
\end{proof}

\begin{definition}[The local equations of the point divisor]
  \label{def:pointEquations}
  \lean{AlgebraicGeometry.Scheme.pointCover, AlgebraicGeometry.Scheme.pointEquations,
    AlgebraicGeometry.Scheme.germGeneric_pointEqn_self}
  \uses{lem:pointUniformizerData, def:localEquations, thm:closedpoint_isClosed}
  \leanok
  From a tracked point-uniformizer \(d\) at \(x\) (\ref{lem:pointUniformizerData}), the
  \emph{point equations} of \(1 \cdot x\) are the local-equation system on the pointed cover
  \[
    \mathcal U(z) = \begin{cases} V & z = x, \\ X \setminus \{x\} & z \neq x, \end{cases}
  \]
  whose equation on the member at \(x\) is the tracked section \(s\) and whose equation on every
  other member is the constant \(1\); the germ at \(\eta\) of the equation at \(x\) is the chosen
  uniformizer.
\end{definition}
\begin{proof}
  \leanok
  The complement \(X \setminus \{x\}\) is open (\ref{thm:closedpoint_isClosed}) and contains every
  \(z \neq x\), so \(\mathcal U\) is a pointed cover. Regularity holds member by member: on \(V\)
  the germs of \(s\) are nonzerodivisors (\ref{lem:pointUniformizerData}), and the constant \(1\)
  is a unit. For overlap ratios, a pair both at \(x\) or both away from \(x\) has equal equations,
  ratio \(1\); a mixed pair has overlap inside \(V \setminus \{x\}\), where \(s\) is a unit
  (\ref{lem:pointUniformizerData}), so the ratio of \(s\) and \(1\) is a unit. Thus the data is a
  local-equation system (\ref{def:localEquations}), and the germ at \(\eta\) of the equation at
  \(x\) is \(\mathrm{germ}_\eta(s) = t\).
\end{proof}

\begin{theorem}[The divisor of the point presentation]
  \label{thm:presentationDivisor_pointEquations}
  \lean{AlgebraicGeometry.Scheme.presentationDivisor_pointEquations}
  \uses{def:pointEquations, lem:localEquations_presentation, def:presentationDivisor,
    def:curveDivisor_single, lem:uniformizer}
  \leanok
  The divisor of the meromorphic presentation of the point equations at a closed point \(x\) is
  the one-point divisor:
  \[
    \mathrm{presentationDivisor}\bigl((\text{point equations at } x)\text{'s presentation}\bigr) =
      1 \cdot x .
  \]
\end{theorem}
\begin{proof}
  \leanok
  The presentation of the point equations (\ref{lem:localEquations_presentation}) has, at each
  closed point \(z\), trivializing element the germ at \(\eta\) of the equation at \(z\). At \(z =
  x\) this is the uniformizer \(t\), of order \(\mathrm{ord}_x t = 1\) (\ref{lem:uniformizer}), so
  the coefficient at \(x\) is \(1\); at \(z \neq x\) the equation is the constant \(1\), of order
  \(0\), so the coefficient vanishes. Hence the divisor is \(1 \cdot x\)
  (\ref{def:curveDivisor_single}, \ref{def:presentationDivisor}).
\end{proof}

\section{The \v Cech Picard class of a Weil divisor}

Assembling the realization of divisors, the class law, and extraction yields the total class map
\(D \mapsto \struct X(D)\) from Weil divisors to \v Cech Picard classes, and its kernel: the class
map descends to an isomorphism of \(\Div(X)\) modulo principal divisors onto \(\Pic(X)\).

\begin{theorem}[Realization of Weil divisors]
  \label{thm:exists_presentationDivisor_eq}
  \lean{AlgebraicGeometry.Scheme.exists_presentationDivisor_eq}
  \uses{thm:presentationDivisor_pointEquations, thm:presentationDivisor_hom,
    lem:pointUniformizerData, def:curveDivisor_single, lem:curveDivisor_single_arith}
  \leanok
  Every Weil divisor \(D \in \Div(X)\) on the curve is the divisor of a meromorphic presentation.
\end{theorem}
\begin{proof}
  \leanok
  First realize the one-point divisors \(n \cdot x\). For \(n \ge 0\), induct on \(n\): the divisor
  \(0 \cdot x = 0\) is realized by the unit presentation (\(\mathrm{presentationDivisor}(1) = 0\),
  \ref{thm:presentationDivisor_hom}), and \((n+1) \cdot x = n \cdot x + 1 \cdot x\) by the product
  of a realization of \(n \cdot x\) with the point presentation at \(x\), using additivity
  (\ref{thm:presentationDivisor_hom}), the point-divisor anchor
  (\ref{thm:presentationDivisor_pointEquations}, \ref{lem:pointUniformizerData}), and the one-point
  arithmetic (\ref{lem:curveDivisor_single_arith}). Negative multiplicities use the inverse
  presentation, whose divisor is negated (\ref{thm:presentationDivisor_hom}). A general \(D\) is a
  finite sum of one-point divisors (\ref{def:curveDivisor_single}), realized by the product of
  their presentations, again by additivity.
\end{proof}

\begin{definition}[The class map and its surjectivity]
  \label{def:curveDivisor_picClass}
  \lean{AlgebraicGeometry.Scheme.CurveDivisor.picClass,
    AlgebraicGeometry.Scheme.CurveDivisor.picClass_presentationDivisor,
    AlgebraicGeometry.Scheme.CurveDivisor.exists_picClass_eq,
    AlgebraicGeometry.Scheme.CurveDivisor.picClass_surjective}
  \uses{thm:exists_presentationDivisor_eq, thm:picClass_eq_of_presentationDivisor_eq,
    thm:exists_meromorphicPresentation, def:curveDivisor}
  \leanok
  The \emph{\v Cech Picard class} \(\struct X(D) = \mathrm{picClass}(D) \in \Pic(X)\) of a Weil
  divisor \(D\) is the class of any meromorphic presentation whose divisor is \(D\). It is
  well-defined, satisfies \(\mathrm{picClass}(\mathrm{presentationDivisor}(P)) = \mathrm{picClass}(P)\)
  for every presentation \(P\), and the map \(D \mapsto \struct X(D)\) is surjective onto
  \(\Pic(X)\).
\end{definition}
\begin{proof}
  \leanok
  A realizing presentation exists (\ref{thm:exists_presentationDivisor_eq}). If \(P, P'\) both have
  divisor \(D\), the class law (\ref{thm:picClass_eq_of_presentationDivisor_eq}) gives
  \(\mathrm{picClass}(P) = \mathrm{picClass}(P')\), so \(\mathrm{picClass}(D)\) is well-defined;
  taking \(D = \mathrm{presentationDivisor}(P)\) with the realization \(P\) itself gives
  \(\mathrm{picClass}(\mathrm{presentationDivisor}(P)) = \mathrm{picClass}(P)\). For surjectivity,
  every class \(L\) is presented by some \(P\) (\ref{thm:exists_meromorphicPresentation}), and then
  \(\struct X(\mathrm{presentationDivisor}(P)) = \mathrm{picClass}(P) = L\).
\end{proof}

\begin{theorem}[The class map is a homomorphism trivial on principal divisors]
  \label{thm:curveDivisor_picClass_hom}
  \lean{AlgebraicGeometry.Scheme.CurveDivisor.picClass_zero,
    AlgebraicGeometry.Scheme.CurveDivisor.picClass_add,
    AlgebraicGeometry.Scheme.CurveDivisor.picClass_divOf}
  \uses{def:curveDivisor_picClass, thm:presentationDivisor_hom,
    thm:meromorphicPresentation_picClass_hom, def:divOf}
  \leanok
  The class map is a group homomorphism \(\Div(X) \to \Pic(X)\), trivial on principal divisors:
  \[
    \struct X(0) = 1, \quad \struct X(D + D') = \struct X(D) \cdot \struct X(D'), \quad \struct
    X(\mathrm{div}\, g) = 1 \ (g \in K(X)^{\times}).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Realizing divisors by presentations and using
  \(\mathrm{picClass}(\mathrm{presentationDivisor}(P)) = \mathrm{picClass}(P)\)
  (\ref{def:curveDivisor_picClass}): \(\struct X(0) = \mathrm{picClass}(1) = 1\) since
  \(\mathrm{presentationDivisor}(1) = 0\) (\ref{thm:presentationDivisor_hom},
  \ref{thm:meromorphicPresentation_picClass_hom}). If \(P, P'\) realize \(D, D'\), then \(P \cdot
  P'\) realizes \(D + D'\) (\ref{thm:presentationDivisor_hom}), so \(\struct X(D + D') =
  \mathrm{picClass}(P \cdot P') = \mathrm{picClass}(P) \cdot \mathrm{picClass}(P') = \struct X(D)
  \cdot \struct X(D')\) (\ref{thm:meromorphicPresentation_picClass_hom}). Finally
  \(\mathrm{div}\, g = \mathrm{presentationDivisor}(\mathrm{principal}\, g)\)
  (\ref{thm:presentationDivisor_hom}), so \(\struct X(\mathrm{div}\, g) =
  \mathrm{picClass}(\mathrm{principal}\, g) = 1\) (\ref{thm:meromorphicPresentation_picClass_hom}).
\end{proof}

\begin{theorem}[The kernel is the principal divisors]
  \label{thm:curveDivisor_picClass_eq_iff}
  \lean{AlgebraicGeometry.Scheme.CurveDivisor.exists_divOf_of_picClass_eq,
    AlgebraicGeometry.Scheme.CurveDivisor.picClass_eq_iff}
  \uses{def:curveDivisor_picClass, thm:meromorphicPresentation_extraction,
    thm:curveDivisor_picClass_hom, def:divOf}
  \leanok
  Two Weil divisors have the same \v Cech Picard class if and only if they differ by a principal
  divisor:
  \[
    \struct X(D) = \struct X(D') \iff D - D' = \mathrm{div}(g) \text{ for some } g \in
      K(X)^{\times}.
  \]
  Together with surjectivity (\ref{def:curveDivisor_picClass}) this identifies \(\Pic(X)\) with the
  group of Weil divisors modulo principal divisors, the classical isomorphism
  \(\mathrm{CaCl}(X) = \Pic(X)\) on an integral curve.
\end{theorem}
\begin{proof}
  \leanok
  \((\Rightarrow)\) Realize \(D, D'\) by presentations \(P, P'\), so \(\mathrm{picClass}(P) =
  \struct X(D) = \struct X(D') = \mathrm{picClass}(P')\); extraction
  (\ref{thm:meromorphicPresentation_extraction}) yields \(g\) with
  \(\mathrm{presentationDivisor}(P) - \mathrm{presentationDivisor}(P') = \mathrm{div}(g)\), that is
  \(D - D' = \mathrm{div}(g)\). \((\Leftarrow)\) If \(D - D' = \mathrm{div}(g)\), then \(D = D' +
  \mathrm{div}(g)\), so \(\struct X(D) = \struct X(D') \cdot \struct X(\mathrm{div}\, g) = \struct
  X(D')\) by additivity and triviality on principal divisors
  (\ref{thm:curveDivisor_picClass_hom}). Since the class map is onto \(\Pic(X)\) with fibres the
  cosets of the subgroup of principal divisors, it descends to an isomorphism of \(\Div(X)\) modulo
  principal divisors onto \(\Pic(X)\).
\end{proof}

\begin{theorem}[Normalization at a one-point divisor]
  \label{thm:curveDivisor_picClass_single}
  \lean{AlgebraicGeometry.Scheme.CurveDivisor.picClass_single}
  \uses{def:curveDivisor_picClass, thm:presentationDivisor_pointEquations,
    lem:localEquations_presentation, def:curveDivisor_single}
  \leanok
  For a closed point \(x\), the class of the one-point divisor \(1 \cdot x\) is the class of the
  tracked point equations at \(x\):
  \[
    \struct X(1 \cdot x) = \mathrm{picClass}(\text{point equations at } x).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The presentation of the point equations at \(x\) has divisor \(1 \cdot x\)
  (\ref{thm:presentationDivisor_pointEquations}), so \(\struct X(1 \cdot x)\) is its class
  (\ref{def:curveDivisor_picClass}), which is the class of the point equations
  (\ref{lem:localEquations_presentation}, \ref{def:curveDivisor_single}).
\end{proof}

\section{The point-divisor class map and the meromorphic class map coincide}

The chapter carries two constructions of the divisor-to-class assignment \(D \mapsto \struct
X(D)\). The first, \(\mathrm{divisorClass}\) (\ref{def:divisorClass}), is the finitely supported
product of the point-divisor classes \(\struct X(x) = \mathrm{picClass}(1 \cdot x)\) read off the
point local equations (\ref{def:pointDivisor}); the second, the anchored
\(\mathrm{picClass}\) (\ref{def:curveDivisor_picClass}), is the class of any meromorphic
presentation realizing \(D\). This closing section identifies them. The bridge is that the point
local equations, whose equation at \(x\) has generic-point germ the uniformizer
(\ref{def:pointDivisor}), present the one-point divisor \(1 \cdot x\); their two classes agree, and
the agreement propagates from one-point divisors to all divisors by homomorphism extensionality.

\begin{theorem}[The divisor of the point-divisor presentation]
  \label{thm:presentationDivisor_pointDivisor}
  \lean{AlgebraicGeometry.Scheme.presentationDivisor_pointDivisor}
  \uses{def:pointDivisor, lem:localEquations_presentation, def:presentationDivisor,
    def:curveDivisor_single, lem:uniformizer}
  \leanok
  The divisor of the meromorphic presentation of the point-divisor local equations at a closed
  point \(x\) is the one-point divisor:
  \[
    \mathrm{presentationDivisor}\bigl((1 \cdot x)\text{'s presentation}\bigr) = 1 \cdot x .
  \]
\end{theorem}
\begin{proof}
  \leanok
  Compare coefficients at each closed point \(z\) (\ref{def:presentationDivisor}). The presentation
  of the point-divisor equations (\ref{lem:localEquations_presentation}) has, at \(z\), trivializing
  element the germ at \(\eta\) of the equation at \(z\). At \(z = x\) that germ is the chosen
  uniformizer \(t\) (\ref{def:pointDivisor}), of order \(\mathrm{ord}_x t = 1\)
  (\ref{lem:uniformizer}), so the coefficient at \(x\) is \(1\); at \(z \neq x\) the equation is the
  constant \(1\), of order \(0\), so the coefficient vanishes. Hence the divisor is \(1 \cdot x\)
  (\ref{def:curveDivisor_single}).
\end{proof}

\begin{theorem}[The point-divisor class is the anchored one-point class]
  \label{thm:pointDivisor_picClass_eq}
  \lean{AlgebraicGeometry.Scheme.pointDivisor_picClass_eq}
  \uses{def:pointDivisor, def:curveDivisor_single, thm:presentationDivisor_pointDivisor,
    def:curveDivisor_picClass, lem:localEquations_presentation}
  \leanok
  For a closed point \(x\), the Picard class of the point-divisor local equations at \(x\) equals
  the anchored class of the one-point divisor \(1 \cdot x\):
  \[
    \mathrm{picClass}(1 \cdot x) \;=\; \struct X(1 \cdot x).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The presentation of the point-divisor equations has divisor \(1 \cdot x\)
  (\ref{thm:presentationDivisor_pointDivisor}), so the anchored class \(\struct X(1 \cdot x)\) is
  the class of that presentation (\ref{def:curveDivisor_picClass}); and the class of the
  presentation of a local-equation system is the Picard class of the system itself
  (\ref{lem:localEquations_presentation}), which is \(\mathrm{picClass}(1 \cdot x)\)
  (\ref{def:pointDivisor}). Chaining the two equalities gives \(\mathrm{picClass}(1 \cdot x) =
  \struct X(1 \cdot x)\).
\end{proof}

\begin{theorem}[The two divisor-class maps coincide]
  \label{thm:divisorClass_eq_picClass}
  \lean{AlgebraicGeometry.Scheme.divisorClass_eq_picClass}
  \uses{def:divisorClass, def:curveDivisor_picClass, thm:divisorClass_add,
    thm:curveDivisor_picClass_hom, thm:pointDivisor_picClass_eq, def:curveDivisor_single}
  \leanok
  The point-product class map (\ref{def:divisorClass}) and the anchored meromorphic class map
  (\ref{def:curveDivisor_picClass}) agree on every Weil divisor:
  \[
    \mathrm{divisorClass}(D) \;=\; \struct X(D), \qquad D \in \Div(X).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both assignments are homomorphisms \(\Div(X) \to \Pic(X)\) from the additive group of divisors to
  the multiplicative Picard group: \(\mathrm{divisorClass}\) by additivity
  (\ref{thm:divisorClass_add}) and the anchored class map by
  Theorem~\ref{thm:curveDivisor_picClass_hom}. Since \(\Div(X)\) is freely generated by the
  one-point divisors (\ref{def:curveDivisor_single}), it suffices to check agreement on each
  \(n \cdot x\). On the point-product side the defining product (\ref{def:divisorClass}) collapses
  to the single factor \(\mathrm{divisorClass}(n \cdot x) = \mathrm{picClass}(1 \cdot x)^{n}\). On
  the anchored side, additivity (\ref{thm:curveDivisor_picClass_hom}) gives \(\struct X(n \cdot x) =
  \struct X(1 \cdot x)^{n}\). The two base classes are equal, \(\mathrm{picClass}(1 \cdot x) =
  \struct X(1 \cdot x)\) (\ref{thm:pointDivisor_picClass_eq}), so their \(n\)-th powers agree and
  \(\mathrm{divisorClass}(n \cdot x) = \struct X(n \cdot x)\). By homomorphism extensionality on the
  generators, the two maps coincide on all of \(\Div(X)\).
\end{proof}

\section{The unit of the \'etale sheafification}
\label{sec:picEtUnit}

The honest relative Picard functor maps into its \'etale-sheafified Layer-2 vehicle
\(\mathrm{picEt}\) by a natural transformation — the unit of the sheafification. On an affine
test it is the unit of the plus construction; on a general test it is assembled over the
affine opens.

\begin{definition}[Restriction of plus classes along an explicit algebra map]
  \label{def:PicEtAff_mapAlg}
  \lean{AlgebraicGeometry.PicEtAff.mapAlg, AlgebraicGeometry.PicEtAff.mapAlg_id,
    AlgebraicGeometry.PicEtAff.mapAlg_comp, AlgebraicGeometry.PicEtAff.mapAlg_unit}
  \uses{def:PicEtAff_map, thm:PicEtAff_map_id, thm:PicEtAff_map_map, thm:PicEtAff_map_unit,
    def:PicEtAff_unit, def:relPicAlgMap}
  \leanok
  For an explicit homomorphism of \(k\)-algebras \(\varphi \colon A \to A'\), restriction of
  plus classes \(\varphi^{*} \colon \mathrm{PicEtAff}(C,A) \to \mathrm{PicEtAff}(C,A')\):
  regard \(A'\) as an \(A\)-algebra through \(\varphi\) and apply the base-extension map of
  Definition~\ref{def:PicEtAff_map}. It satisfies \((\id_A)^{*} = \id\) and
  \((\psi \circ \varphi)^{*} = \psi^{*} \circ \varphi^{*}\), and it is natural on units of
  the plus construction:
  \[
    \varphi^{*}\bigl(\mathrm{unit}(x)\bigr) = \mathrm{unit}\bigl(\varphi^{*} x\bigr),
    \qquad x \in \mathrm{relPic}(C,A).
  \]
\end{definition}
\begin{proof}
  \leanok
  The scalar tower \(k \to A \to A'\) determined by \(\varphi\) makes
  Definition~\ref{def:PicEtAff_map} applicable; the two functor laws are
  Theorems~\ref{thm:PicEtAff_map_id} and~\ref{thm:PicEtAff_map_map} read through this tower,
  and naturality on units is Theorem~\ref{thm:PicEtAff_map_unit}.
\end{proof}

\begin{definition}[The affine-open test objects of a test object]
  \label{def:fromSpecAffine}
  \lean{AlgebraicGeometry.Over.fromSpecAffine, AlgebraicGeometry.Over.fromSpecAffine_naturality,
    AlgebraicGeometry.Over.fromSpecAffine_resAlgHom,
    AlgebraicGeometry.Over.overSpecMap_ΓTop_fromSpecAffine_top}
  \uses{def:overSpecMap, def:overSpecGammaTop}
  \leanok
  For a test object \(T\) and an affine open \(U \subseteq T_{\mathrm{left}}\), the spectrum
  of the section ring \(\Spec \Gamma(T, U)\) is a test object over \(T\), via the canonical
  morphism \(\Spec \Gamma(T,U) \to T\) of the affine open. This assignment is coherent:
  \begin{enumerate}
  \item (restriction) for \(U \le V\), the map of \(U\) factors through that of \(V\) along
    \(\Spec\) of the section restriction \(\Gamma(T,V) \to \Gamma(T,U)\);
  \item (naturality) for a morphism of tests \(f \colon T' \to T\) and affine opens
    \(W \le f^{-1}V\), the square formed by \(\Spec\) of the section pullback
    \(\Gamma(T,V) \to \Gamma(T',W)\) and the two affine-open test maps commutes;
  \item (top of an affine test) for \(T = \Spec A\), the affine-open test object of the top
    open, composed with \(\Spec\) of the identification \(\Gamma(\Spec A, \top) \cong A\)
    (Definition~\ref{def:overSpecGammaTop}), is the identity of \(\Spec A\).
  \end{enumerate}
\end{definition}
\begin{proof}
  \leanok
  The structure morphism to \(\Spec k\) is \(\Spec\) of the \(k\)-algebra structure of the
  section ring, so the canonical morphism of the affine open lies over \(\Spec k\); this is
  the compatibility of the affine-open inclusion with the structure morphisms. Coherences (i)
  and (ii) are both instances of the standard identity
  \(\Spec(f^{\sharp}_{V,W}) \circ \iota_W = \iota_V \circ f\) for the canonical maps of
  affine opens, applied to the identity of \(T\) and to \(f\) respectively; (iii) is the
  fact that the canonical map of the top affine open of an affine scheme is the isomorphism
  \(\Spec \Gamma(\Spec A, \top) \cong \Spec A\), inverse to \(\Spec\) of the section
  identification.
\end{proof}

\begin{definition}[The component of the unit at a test object]
  \label{def:relPicToPicEt}
  \lean{AlgebraicGeometry.relPicToPicEt, AlgebraicGeometry.relPicToPicEt_val}
  \uses{def:picEt, def:PicEtAff_unit, def:fromSpecAffine, def:relPicMap, def:PicEtAff_mapAlg}
  \leanok
  For a test object \(T\), the homomorphism
  \(\mathrm{relPic}(C,T) \to \mathrm{picEt}(C,T)\) sending a relative Picard class \(z\) to
  the family whose value at an affine open \(U \subseteq T_{\mathrm{left}}\) is the plus unit
  of the restriction of \(z\) along the affine-open test object of \(U\):
  \[
    z \;\longmapsto\;
    \Bigl( U \mapsto \mathrm{unit}\bigl(\iota_U^{*} z\bigr) \Bigr)_{U} .
  \]
\end{definition}
\begin{proof}
  \leanok
  The family is compatible under restriction of affine opens, as required by
  Definition~\ref{def:picEt}: for \(U \le V\), the restriction coherence of the affine-open
  test objects (Definition~\ref{def:fromSpecAffine}) gives \(\iota_U = \iota_V \circ
  \Spec(\mathrm{res}_{V,U})\), so functoriality of restriction (Definition~\ref{def:relPicMap})
  and naturality of the unit on explicit algebra maps (Definition~\ref{def:PicEtAff_mapAlg})
  identify \(\mathrm{res}_{V,U}^{*}\,\mathrm{unit}(\iota_V^{*}z) =
  \mathrm{unit}(\iota_U^{*}z)\). The assignment is a homomorphism because each constituent
  map is.
\end{proof}

\begin{theorem}[Affine consistency of the unit]
  \label{thm:picEtAffineEquiv_relPicToPicEt}
  \lean{AlgebraicGeometry.picEtAffineEquiv_relPicToPicEt}
  \uses{def:relPicToPicEt, def:picEtAffineEquiv, def:PicEtAff_mapAlg, def:fromSpecAffine,
    def:relPicMap, def:PicEtAff_unit}
  \leanok
  On an affine test \(\Spec A\), the component of the unit collapses through the affine
  comparison \(\mathrm{picEt}(C, \Spec A) \cong \mathrm{PicEtAff}(C, A)\)
  (Definition~\ref{def:picEtAffineEquiv}) to the unit of the plus construction:
  \[
    \mathrm{picEtAffineEquiv}\bigl(\mathrm{relPicToPicEt}(z)\bigr)
      = \mathrm{unit}(z), \qquad z \in \mathrm{relPic}(C,A).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The affine comparison evaluates the family at the top affine open and transports along the
  section identification \(\Gamma(\Spec A, \top) \cong A\). The value there is
  \(\mathrm{unit}(\iota_\top^{*} z)\); transporting along the identification and using
  naturality of the unit (Definition~\ref{def:PicEtAff_mapAlg}) yields the unit of
  \(z\) restricted along \(\Spec(\Gamma(\Spec A,\top) \cong A) \circ \iota_\top\), which is
  the identity of \(\Spec A\) by coherence (iii) of Definition~\ref{def:fromSpecAffine}; so
  the value is \(\mathrm{unit}(z)\) by functoriality (Definition~\ref{def:relPicMap}).
\end{proof}

\begin{theorem}[Naturality of the unit]
  \label{thm:picEtMap_relPicToPicEt}
  \lean{AlgebraicGeometry.picEtMap_relPicToPicEt}
  \uses{def:relPicToPicEt, def:picEtMap, def:picEt_IsPullbackValue,
    thm:picEt_pullbackValue_unique, def:fromSpecAffine, def:PicEtAff_mapAlg, def:relPicMap}
  \leanok
  Let the curve \(C\) be proper, geometrically irreducible and geometrically reduced. For a
  morphism of test objects \(f \colon T' \to T\) and \(z \in \mathrm{relPic}(C,T)\),
  \[
    f^{*}\bigl(\mathrm{relPicToPicEt}(z)\bigr)
      = \mathrm{relPicToPicEt}\bigl(f^{*} z\bigr)
    \quad\text{in } \mathrm{picEt}(C,T').
  \]
\end{theorem}
\begin{proof}
  \leanok
  The restriction map of \(\mathrm{picEt}\) is characterised value-by-value by the
  \(\exists!\)-property of Definition~\ref{def:picEt_IsPullbackValue} together with its
  uniqueness (Theorem~\ref{thm:picEt_pullbackValue_unique}); it therefore suffices to verify
  that the right-hand family has the characterising property of the pullback of the
  left-hand family. Unwinding, this is the statement that for affine opens
  \(W_0 \le W \subseteq T'_{\mathrm{left}}\) with \(W_0 \le f^{-1}V\),
  \[
    \mathrm{res}^{*}\,\mathrm{unit}\bigl(\iota_W^{*} f^{*} z\bigr)
      = (f^{\sharp}_{V,W_0})^{*}\,\mathrm{unit}\bigl(\iota_V^{*} z\bigr).
  \]
  Both sides are units of restrictions of \(z\) (naturality of the unit,
  Definition~\ref{def:PicEtAff_mapAlg}), and the two restrictions agree because the two
  composites of affine-open test maps agree: \(\iota_{W_0} \circ (\text{res}) = \iota_W\) and
  \(f \circ \iota_{W_0} = \iota_V \circ \Spec(f^{\sharp}_{V,W_0})\), the two coherences of
  Definition~\ref{def:fromSpecAffine}.
\end{proof}

\begin{definition}[The unit of the \'etale sheafification]
  \label{def:picEtUnit}
  \lean{AlgebraicGeometry.picEtUnit, AlgebraicGeometry.picEtUnit_app,
    AlgebraicGeometry.picEtAffineEquiv_picEtUnit_app}
  \uses{def:relPicToPicEt, thm:picEtMap_relPicToPicEt, def:picEtFunctor, def:relPicMap,
    thm:picEtAffineEquiv_relPicToPicEt}
  \leanok
  Let the curve \(C\) be proper, geometrically irreducible and geometrically reduced. The
  components of Definition~\ref{def:relPicToPicEt} assemble into a natural transformation
  \[
    \mathrm{relPicFunctor}(C) \;\longrightarrow\; \mathrm{picEtFunctor}(C)
  \]
  of presheaves of commutative groups on \(\Over(\Spec k)\), whose affine components collapse
  to the unit of the plus construction.
\end{definition}
\begin{proof}
  \leanok
  Naturality of the components is Theorem~\ref{thm:picEtMap_relPicToPicEt}; the affine
  collapse is Theorem~\ref{thm:picEtAffineEquiv_relPicToPicEt}.
\end{proof}

\section{The degree of a plus class}
\label{sec:degAff}

The relative degree \(\mathrm{relPicDeg}\) of Definition~\ref{def:relPicDeg} reads an honest
integer off a relative Picard class over a \emph{field}. This section descends it to the plus
construction: a plus class over \(K\) is represented on an \'etale cover, every cover is
refined by a single finite separable field extension (cofinality,
Theorem~\ref{thm:etale_cover_field_cofinality}), and the \emph{zigzag} shows the field
reading is independent of every choice.

\begin{lemma}[The relative degree is additive]
  \label{lem:relPicDeg_hom}
  \lean{AlgebraicGeometry.relPicDeg_mul, AlgebraicGeometry.relPicDeg_one}
  \uses{def:relPicDeg}
  \leanok
  For a field extension \(K\) of \(k\) and relative Picard classes
  \(x, y \in \mathrm{relPic}(C, K)\),
  \[
    \mathrm{relPicDeg}_K(x \cdot y) = \mathrm{relPicDeg}_K(x) + \mathrm{relPicDeg}_K(y),
    \qquad \mathrm{relPicDeg}_K(1) = 0 .
  \]
\end{lemma}
\begin{proof}
  \leanok
  \(\mathrm{relPicDeg}_K\) is a homomorphism from the multiplicative relative Picard group to
  \(\Z\) by construction (Definition~\ref{def:relPicDeg}); these are its two homomorphism
  laws.
\end{proof}

\begin{theorem}[The zigzag, leg (i): one degree through any two field readings]
  \label{thm:relPicDeg_relPicAlgMap_congr}
  \lean{AlgebraicGeometry.relPicDeg_relPicAlgMap_congr}
  \uses{def:relPicDeg, thm:relPicDeg_relPicAlgMap, thm:relPicAlgMap_congr,
    thm:etale_cover_field_cofinality, def:etale_cover_prod, def:etale_cover_prod_coproj,
    def:etale_cover_ofField, def:descentClasses, lem:relPicAlgMap_functor}
  \leanok
  Let \(K\) be a field extension of \(k\), \(E\) a presented \'etale cover of \(K\), and
  \(x \in \mathrm{relPic}(C, B_E)\) a descent class on \(E\). Let \(L_1, L_2\) be finite
  separable field extensions of \(K\) and \(j_1 \colon B_E \to L_1\),
  \(j_2 \colon B_E \to L_2\) two \(K\)-algebra maps. Then
  \[
    \mathrm{relPicDeg}_{L_1}\bigl(j_1^{*} x\bigr)
      = \mathrm{relPicDeg}_{L_2}\bigl(j_2^{*} x\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Refine the product of the two field covers \(\mathrm{ofField}(L_1) \times
  \mathrm{ofField}(L_2)\) (Definitions~\ref{def:etale_cover_ofField},
  \ref{def:etale_cover_prod}) to a single finite separable field extension \(M\) of \(K\)
  (cofinality, Theorem~\ref{thm:etale_cover_field_cofinality}); composing with the
  coprojections (Definition~\ref{def:etale_cover_prod_coproj}) yields \(K\)-algebra maps
  \(\theta_1 \colon L_1 \to M\) and \(\theta_2 \colon L_2 \to M\). Then
  \[
    \mathrm{relPicDeg}_{L_1}(j_1^{*} x)
      = \mathrm{relPicDeg}_{M}(\theta_1^{*} j_1^{*} x)
      = \mathrm{relPicDeg}_{M}\bigl((\theta_1 j_1)^{*} x\bigr),
  \]
  using invariance of the relative degree under base-field transitions (E-iv-alg descended,
  Theorem~\ref{thm:relPicDeg_relPicAlgMap}) and functoriality
  (Lemma~\ref{lem:relPicAlgMap_functor}); likewise for the second leg. Now \(\theta_1 j_1\)
  and \(\theta_2 j_2\) are two \(K\)-algebra maps \(B_E \to M\) out of the cover carrier, and
  \(x\) is a descent class, so the transport-independence keystone of the plus construction
  (Theorem~\ref{thm:relPicAlgMap_congr}) gives \((\theta_1 j_1)^{*} x = (\theta_2 j_2)^{*} x\).
  The two degrees over \(M\) therefore agree, hence so do the original readings.
\end{proof}

\begin{theorem}[The zigzag: well-definedness of the plus-class degree]
  \label{thm:relPicDeg_eq_of_descentMap_eq}
  \lean{AlgebraicGeometry.relPicDeg_eq_of_descentMap_eq}
  \uses{thm:relPicDeg_relPicAlgMap_congr, def:descentMap, thm:etale_cover_field_cofinality,
    lem:relPicAlgMap_functor, def:descentClasses}
  \leanok
  Let \(E_1, E_2, G\) be presented \'etale covers of \(K\), \(x_1, x_2\) descent classes on
  \(E_1, E_2\), and \(f \colon B_{E_1} \to B_G\), \(g \colon B_{E_2} \to B_G\) \(K\)-algebra
  maps with \(f_{*} x_1 = g_{*} x_2\) as descent classes on \(G\) (the identification of the
  plus-construction setoid). Then for any two field readings — finite separable field
  extensions \(L_1, L_2\) of \(K\) with \(K\)-algebra maps \(j_1 \colon B_{E_1} \to L_1\) and
  \(j_2 \colon B_{E_2} \to L_2\) —
  \[
    \mathrm{relPicDeg}_{L_1}\bigl(j_1^{*} x_1\bigr)
      = \mathrm{relPicDeg}_{L_2}\bigl(j_2^{*} x_2\bigr).
  \]
  No Galois theory appears: Galois twisting of the transport is a special case of the
  transport-independence keystone.
\end{theorem}
\begin{proof}
  \leanok
  Refine \(G\) to a single finite separable field extension \(N\) of \(K\) by cofinality
  (Theorem~\ref{thm:etale_cover_field_cofinality}), with refinement map
  \(\ell \colon B_G \to N\). By leg (i) of the zigzag
  (Theorem~\ref{thm:relPicDeg_relPicAlgMap_congr}) applied to the descent class \(x_1\) on
  \(E_1\) and the two readings \(j_1\) and \(\ell f\),
  \[
    \mathrm{relPicDeg}_{L_1}(j_1^{*} x_1) = \mathrm{relPicDeg}_{N}\bigl((\ell f)^{*} x_1\bigr)
      = \mathrm{relPicDeg}_{N}\bigl(\ell^{*} f^{*} x_1\bigr)
  \]
  (functoriality, Lemma~\ref{lem:relPicAlgMap_functor}). Cross over along the identification
  \(f^{*} x_1 = g^{*} x_2\) (the underlying relative classes of \(f_{*}x_1 = g_{*}x_2\),
  Definition~\ref{def:descentMap}) and run the same two steps backwards on the second leg:
  \(\mathrm{relPicDeg}_{N}(\ell^{*} g^{*} x_2) = \mathrm{relPicDeg}_{N}((\ell g)^{*} x_2) =
  \mathrm{relPicDeg}_{L_2}(j_2^{*} x_2)\), again by leg (i).
\end{proof}

\begin{definition}[The degree of a plus class]
  \label{def:degAff}
  \lean{AlgebraicGeometry.PicEtAff.degAff, AlgebraicGeometry.PicEtAff.degAff_mk,
    AlgebraicGeometry.PicEtAff.degAff_mk_ofField}
  \uses{def:PicEtAff, def:PicEtAff_mk, thm:relPicDeg_eq_of_descentMap_eq,
    thm:relPicDeg_relPicAlgMap_congr, thm:etale_cover_field_cofinality, def:relPicDeg,
    def:etale_cover_ofField}
  \leanok
  The \emph{degree} \(\deg^{+}_K \colon \mathrm{PicEtAff}(C, K) \to \Z\) of an
  \'etale-locally trivial relative Picard class: represent the class by a descent class
  \(x\) on a cover \(E\), refine \(E\) to a finite separable field extension \(L/K\) by
  cofinality (Theorem~\ref{thm:etale_cover_field_cofinality}), and read
  \(\mathrm{relPicDeg}_L\) of the transported class. The value is independent of the
  representative and of the refinement, and it is pinned by the \emph{master equality}: for
  every descent-class representative \((E, x)\), every finite separable field extension
  \(L/K\) and every \(K\)-algebra map \(j \colon B_E \to L\),
  \[
    \deg^{+}_K [E, x] = \mathrm{relPicDeg}_L\bigl(j^{*} x\bigr).
  \]
  In particular, on a field-cover representative \((\mathrm{ofField}(L), y)\) the degree is
  \(\mathrm{relPicDeg}_L\) of \(y\) transported through the carrier identification.
\end{definition}
\begin{proof}
  \leanok
  Existence of a field refinement of each cover is cofinality
  (Theorem~\ref{thm:etale_cover_field_cofinality}). Independence of the representative is
  exactly the zigzag (Theorem~\ref{thm:relPicDeg_eq_of_descentMap_eq}): two representatives
  of one plus class are identified after transport to a common refinement
  (Definition~\ref{def:PicEtAff_mk}), and the zigzag equates any two field readings of such
  a pair — in particular the readings through the chosen refinements. The master equality is
  leg (i) of the zigzag (Theorem~\ref{thm:relPicDeg_relPicAlgMap_congr}), comparing the
  chosen refinement map with the given \(j\); the field-cover normalization is the master
  equality at the carrier identification of \(\mathrm{ofField}(L)\)
  (Definition~\ref{def:etale_cover_ofField}).
\end{proof}

\begin{theorem}[Additivity of the plus-class degree]
  \label{thm:degAff_hom}
  \lean{AlgebraicGeometry.PicEtAff.degAff_one, AlgebraicGeometry.PicEtAff.degAff_mul,
    AlgebraicGeometry.PicEtAff.degAff_inv}
  \uses{def:degAff, def:PicEtAff_one, thm:PicEtAff_mk_mul_mk, lem:PicEtAff_ind,
    def:etale_cover_prod, def:etale_cover_prod_coproj, thm:etale_cover_field_cofinality,
    lem:relPicDeg_hom, def:etale_cover_self, lem:relPicAlgMap_functor}
  \leanok
  \(\deg^{+}_K\) is a homomorphism: \(\deg^{+}_K(1) = 0\),
  \(\deg^{+}_K(a b) = \deg^{+}_K(a) + \deg^{+}_K(b)\) and
  \(\deg^{+}_K(a^{-1}) = -\deg^{+}_K(a)\).
\end{theorem}
\begin{proof}
  \leanok
  \emph{Unit.} The trivial plus class is represented by the trivial descent class on the
  trivial cover (Definitions~\ref{def:PicEtAff_one}, \ref{def:etale_cover_self}); its field
  reading is \(\mathrm{relPicDeg}_K(1) = 0\) (Lemma~\ref{lem:relPicDeg_hom}), and the master
  equality (Definition~\ref{def:degAff}) transfers this to \(\deg^{+}\).

  \emph{Additivity.} Represent \(a = [E,x]\) and \(b = [F,y]\)
  (Lemma~\ref{lem:PicEtAff_ind}); the product is represented on the product cover
  \(E \times F\) by the product of the transported classes
  (Theorem~\ref{thm:PicEtAff_mk_mul_mk}). Refine \(E \times F\) to a single finite separable
  field \(L\) (Theorem~\ref{thm:etale_cover_field_cofinality}) with refinement map \(\ell\),
  and read all three degrees there through the master equality: the reading of \(ab\) is
  \(\mathrm{relPicDeg}_L\) of the product of the two transported classes (transport is a
  homomorphism, Lemma~\ref{lem:relPicAlgMap_functor}), which splits as the sum by
  Lemma~\ref{lem:relPicDeg_hom}; and the two summands are the readings of \(a\) and \(b\)
  through \(\ell\) composed with the coprojections
  (Definition~\ref{def:etale_cover_prod_coproj}).

  \emph{Inverses.} From \(\deg^{+}(a^{-1}) + \deg^{+}(a) = \deg^{+}(1) = 0\).
\end{proof}

\begin{theorem}[The unit normalization of the plus-class degree]
  \label{thm:degAff_unit}
  \lean{AlgebraicGeometry.PicEtAff.degAff_unit}
  \uses{def:degAff, def:PicEtAff_unit, def:etale_cover_self,
    lem:PicEtAff_tautological_mem_descentClasses, lem:relPicAlgMap_functor}
  \leanok
  On a class in the image of the unit of the plus construction, the degree is the relative
  degree over the base field itself:
  \[
    \deg^{+}_K\bigl(\mathrm{unit}(z)\bigr) = \mathrm{relPicDeg}_K(z),
    \qquad z \in \mathrm{relPic}(C,K).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The unit represents its value by the tautological descent class of \(z\) on the trivial
  cover (Definition~\ref{def:PicEtAff_unit},
  Lemma~\ref{lem:PicEtAff_tautological_mem_descentClasses}), and the trivial cover is
  refined by the field cover of \(K\) itself. The master equality
  (Definition~\ref{def:degAff}) reads \(\mathrm{relPicDeg}_K\) of \(z\) transported along the
  composite \(K \to B_{\mathrm{self}} \to K\), which is the identity
  (Lemma~\ref{lem:relPicAlgMap_functor}).
\end{proof}

\section{The degree at field points and the degree-zero Picard functor}
\label{sec:pic0}

\begin{definition}[The degree of an \'etale Picard class at a field point]
  \label{def:degAt}
  \lean{AlgebraicGeometry.degAt}
  \uses{def:degAff, def:picEtAffineEquiv, def:picEtMap}
  \leanok
  Let \(T\) be a test object, \(\lambda \in \mathrm{picEt}(C,T)\), \(K\) a field extension of
  \(k\) and \(t \colon \Spec K \to T\) a \emph{field point} of \(T\). The \emph{degree of
  \(\lambda\) at \(t\)} is the plus-class degree of the restriction:
  \[
    \deg_t(\lambda) \;:=\; \deg^{+}_K\bigl(\mathrm{picEtAffineEquiv}(t^{*}\lambda)\bigr) \in \Z ,
  \]
  the restriction along \(t\) (Definition~\ref{def:picEtMap}) collapsed to a plus class by
  the affine comparison (Definition~\ref{def:picEtAffineEquiv}).
\end{definition}

\begin{lemma}[The degree at a field point is additive]
  \label{lem:degAt_hom}
  \lean{AlgebraicGeometry.degAt_one, AlgebraicGeometry.degAt_mul, AlgebraicGeometry.degAt_inv}
  \uses{def:degAt, thm:degAff_hom}
  \leanok
  For classes \(\lambda, \mu \in \mathrm{picEt}(C,T)\) and a field point \(t\),
  \[
    \deg_t(1) = 0, \qquad
    \deg_t(\lambda\mu) = \deg_t(\lambda) + \deg_t(\mu), \qquad
    \deg_t(\lambda^{-1}) = -\deg_t(\lambda).
  \]
\end{lemma}
\begin{proof}
  \leanok
  Restriction and the affine comparison are homomorphisms, and \(\deg^{+}\) is additive
  (Theorem~\ref{thm:degAff_hom}).
\end{proof}

\begin{theorem}[Functoriality of the degree at field points]
  \label{thm:degAt_picEtMap}
  \lean{AlgebraicGeometry.degAt_picEtMap, AlgebraicGeometry.degAt_picEtFunctor_map}
  \uses{def:degAt, thm:picEtMap_functor_laws}
  \leanok
  For \(f \colon T' \to T\), \(\lambda \in \mathrm{picEt}(C,T)\) and a field point
  \(t' \colon \Spec K \to T'\),
  \[
    \deg_{t'}\bigl(f^{*}\lambda\bigr) = \deg_{f \circ t'}(\lambda).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Both sides collapse the restriction of \(\lambda\) along the same composite field point:
  \(t'^{*}(f^{*}\lambda) = (f \circ t')^{*}\lambda\) by functoriality of restriction
  (Theorem~\ref{thm:picEtMap_functor_laws}).
\end{proof}

\begin{definition}[The degree-zero subgroup]
  \label{def:pic0Subgroup}
  \lean{AlgebraicGeometry.pic0Subgroup, AlgebraicGeometry.mem_pic0Subgroup_iff}
  \uses{def:degAt, lem:degAt_hom}
  \leanok
  For a test object \(T\), the subgroup
  \[
    \mathrm{pic}^0(C,T) \;:=\;
    \bigl\{\, \lambda \in \mathrm{picEt}(C,T) \;:\; \deg_t(\lambda) = 0
      \text{ for every field point } t \text{ of } T \,\bigr\}
  \]
  of classes of degree zero at \emph{every} field point of \(T\).
\end{definition}
\begin{proof}
  \leanok
  Closure under unit, product and inverse is Lemma~\ref{lem:degAt_hom}, pointwise in the
  field point.
\end{proof}

\begin{definition}[The degree-zero relative Picard functor]
  \label{def:pic0Functor}
  \lean{AlgebraicGeometry.pic0Map, AlgebraicGeometry.pic0Map_coe,
    AlgebraicGeometry.pic0Functor, AlgebraicGeometry.pic0Functor_obj,
    AlgebraicGeometry.pic0Functor_map, AlgebraicGeometry.pic0Inclusion}
  \uses{def:pic0Subgroup, thm:degAt_picEtMap, def:picEtFunctor, thm:picEtMap_functor_laws}
  \leanok
  The degree-zero condition is stable under restriction: for \(f \colon T' \to T\), the
  restriction map of \(\mathrm{picEt}\) carries \(\mathrm{pic}^0(C,T)\) into
  \(\mathrm{pic}^0(C,T')\). The functor
  \[
    \mathrm{Pic}^0_{C/k} \colon \Over(\Spec k)^{\mathrm{op}} \longrightarrow \mathrm{CommGrp},
    \qquad T \mapsto \mathrm{pic}^0(C,T),
  \]
  with these restrictions, is the \emph{degree-zero relative Picard functor} — a subgroup
  subfunctor of \(\mathrm{picEtFunctor}(C)\), with inclusion natural transformation
  \(\mathrm{Pic}^0_{C/k} \to \mathrm{picEtFunctor}(C)\). This is the carrier of the
  representability statement: the Jacobian represents \emph{this} functor.
\end{definition}
\begin{proof}
  \leanok
  Stability: for \(\lambda\) of degree zero at every field point of \(T\) and \(t'\) a field
  point of \(T'\), functoriality (Theorem~\ref{thm:degAt_picEtMap}) gives
  \(\deg_{t'}(f^{*}\lambda) = \deg_{f \circ t'}(\lambda) = 0\). The functor laws are
  inherited from those of \(\mathrm{picEtFunctor}\)
  (Theorem~\ref{thm:picEtMap_functor_laws}) on underlying classes, and the inclusion is
  natural because the restriction of a degree-zero class \emph{is} the restriction of its
  underlying class.
\end{proof}

\section{The degree seam at field points}
\label{sec:degreeSeam}

For a \emph{cocycle-presented} plus class on an affine test — one which is the unit image of
an honest \v Cech Picard class — the degree at a field point collapses to the curve-level
class degree \(\deg_{\Pic}\) of the fibre class. This seam is where the campaign's coverage
and stratification arguments spend degree-zero-ness.

\begin{theorem}[The degree seam, unit form]
  \label{thm:degAt_of_affineEquiv_eq_unit}
  \lean{AlgebraicGeometry.degAt_of_affineEquiv_eq_unit}
  \uses{def:degAt, thm:picEtAffineEquiv_naturality, def:PicEtAff_mapAlg, thm:degAff_unit,
    def:relPicAlgMap}
  \leanok
  Let \(A\) be a \(k\)-algebra, \(\lambda \in \mathrm{picEt}(C, \Spec A)\) a class whose
  affine collapse is the plus unit of a relative Picard class \(z \in \mathrm{relPic}(C,A)\),
  and \(\varphi \colon A \to K\) a \(k\)-algebra map into a field. Then the degree of
  \(\lambda\) at the field point \(\Spec \varphi\) is the relative degree of the fibre class:
  \[
    \deg_{\Spec\varphi}(\lambda) = \mathrm{relPicDeg}_K\bigl(\varphi^{*} z\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  The affine comparison intertwines restriction along \(\Spec\varphi\) with the explicit
  transport \(\varphi^{*}\) of plus classes (Theorem~\ref{thm:picEtAffineEquiv_naturality}),
  which is natural on units (Definition~\ref{def:PicEtAff_mapAlg}); so the collapse of
  \(t^{*}\lambda\) is \(\mathrm{unit}(\varphi^{*} z)\), whose degree is
  \(\mathrm{relPicDeg}_K(\varphi^{*} z)\) by the unit normalization
  (Theorem~\ref{thm:degAff_unit}).
\end{proof}

\begin{theorem}[The degree seam: cocycle-presented classes]
  \label{thm:degAt_of_affineEquiv_eq_unit_relPicMk}
  \lean{AlgebraicGeometry.degAt_of_affineEquiv_eq_unit_relPicMk}
  \uses{thm:degAt_of_affineEquiv_eq_unit, def:relPicMap, def:relPic, def:relPicDeg}
  \leanok
  In the situation of Theorem~\ref{thm:degAt_of_affineEquiv_eq_unit}, suppose
  \(z = \pi_{\Spec A}(L)\) for an honest \v Cech Picard class \(L\) on \(C \otimes \Spec A\).
  Then the degree at the field point is the class degree of the fibre \v Cech class:
  \[
    \deg_{\Spec\varphi}(\lambda)
      = \deg_{\Pic}\Bigl( (C \lhd \Spec\varphi)^{*} L \Bigr),
  \]
  the pullback of \(L\) along the point.
\end{theorem}
\begin{proof}
  \leanok
  By Theorem~\ref{thm:degAt_of_affineEquiv_eq_unit} the degree is
  \(\mathrm{relPicDeg}_K(\varphi^{*}\pi_{\Spec A}(L))\); the restriction of a projected class
  is the projection of the pullback (Definition~\ref{def:relPicMap}), and on projected
  classes over a field the relative degree reads the class degree of the representative
  (Definition~\ref{def:relPicDeg}).
\end{proof}

\begin{theorem}[Base-field constancy of the degree]
  \label{thm:degAt_baseChange}
  \lean{AlgebraicGeometry.degAt_of_affineEquiv_eq_unit_baseChange,
    AlgebraicGeometry.degAt_eq_classDeg_of_affineEquiv_eq_unit_baseChange}
  \uses{thm:degAt_of_affineEquiv_eq_unit, lem:relPicAlgMap_functor,
    thm:relPicDeg_relPicAlgMap, def:relPicDeg, def:relPic}
  \leanok
  In the situation of Theorem~\ref{thm:degAt_of_affineEquiv_eq_unit}, suppose \(z\) is pulled
  back from the base: \(z = \iota_A^{*} w\) for a class \(w \in \mathrm{relPic}(C,k)\), with
  \(\iota_A \colon k \to A\) the structure map. Then the degree of \(\lambda\) is
  \(\mathrm{relPicDeg}_k(w)\) at \emph{every} field point of \(\Spec A\) — independent of the
  point. If moreover \(w = \pi(L_0)\) for a \v Cech class \(L_0\) on \(C \otimes \Spec k\),
  the constant is \(\deg_{\Pic}(L_0)\).
\end{theorem}
\begin{proof}
  \leanok
  At a field point \(\Spec\varphi\), Theorem~\ref{thm:degAt_of_affineEquiv_eq_unit} reads
  \(\mathrm{relPicDeg}_K(\varphi^{*}\iota_A^{*}w) =
  \mathrm{relPicDeg}_K\bigl((\varphi\iota_A)^{*}w\bigr)\) (functoriality,
  Lemma~\ref{lem:relPicAlgMap_functor}); invariance of the relative degree under base-field
  transitions (Theorem~\ref{thm:relPicDeg_relPicAlgMap}) collapses this to
  \(\mathrm{relPicDeg}_k(w)\), with no dependence on \(\varphi\). The \v Cech form reads the
  representative through Definition~\ref{def:relPicDeg}.
\end{proof}

\begin{theorem}[The fibre degree of a degree-zero twist]
  \label{thm:degAt_pic0_mul_pow}
  \lean{AlgebraicGeometry.degAt_pow, AlgebraicGeometry.degAt_pic0_mul_pow}
  \uses{lem:degAt_hom, def:pic0Subgroup}
  \leanok
  For any class \(\theta \in \mathrm{picEt}(C,T)\), \(m \in \N\), and a field point \(t\),
  \(\deg_t(\theta^m) = m \cdot \deg_t(\theta)\); and for
  \(\lambda \in \mathrm{pic}^0(C,T)\),
  \[
    \deg_t\bigl(\lambda \cdot \theta^{m}\bigr) = m \cdot \deg_t(\theta)
  \]
  on the nose — the degree-zero factor contributes nothing.
\end{theorem}
\begin{proof}
  \leanok
  The power law is additivity (Lemma~\ref{lem:degAt_hom}) by induction on \(m\); the twist
  law adds \(\deg_t(\lambda) = 0\) (Definition~\ref{def:pic0Subgroup}).
\end{proof}

\section{The \texorpdfstring{\(\theta\)}{theta}-family and the multiplication shift}
\label{sec:thetaShift}

Fix a \v Cech Picard class \(L_0\) on the base-changed curve
\(C_k := (C \otimes \Spec k)_{\mathrm{left}}\). Pulling its plus class back from the base
test along the canonical structure maps produces a family \(\theta_T\) of \'etale Picard
classes, natural in \(T\) and of constant degree \(d_1 = \deg_{\Pic}(L_0)\) at every field
point; multiplication by \(\theta_T^{m}\) then shifts the degree-zero functor onto the
degree-\(m d_1\) layer.

\begin{definition}[The canonical map to the base test]
  \label{def:toBaseTest}
  \lean{AlgebraicGeometry.toBaseTest, AlgebraicGeometry.toBaseTest_left,
    AlgebraicGeometry.toBaseTest_naturality, AlgebraicGeometry.toBaseTest_overSpec}
  \uses{def:overSpecMap}
  \leanok
  The base test \(\Spec k\) (the affine test of the \(k\)-algebra \(k\)) is terminal in
  \(\Over(\Spec k)\) up to the identification of its structure morphism with the identity:
  every test object \(T\) has a canonical morphism \(T \to \Spec k\) given by its structure
  morphism, natural in \(T\) (\(f \circ (\text{canonical}) = \text{canonical}\)); on an
  affine test \(\Spec A\) it is \(\Spec\) of the structure map \(k \to A\).
\end{definition}
\begin{proof}
  \leanok
  The structure morphism of the base test is \(\Spec\) of \(\mathrm{id}_k\), the identity;
  hence the structure morphism of \(T\) is a morphism of \(\Over(\Spec k)\) into it.
  Naturality is the defining triangle of morphisms of \(\Over(\Spec k)\); the affine case is
  the compatibility of \(\Spec\) with structure maps (Definition~\ref{def:overSpecMap}).
\end{proof}

\begin{definition}[The \(\theta\)-family]
  \label{def:thetaFamily}
  \lean{AlgebraicGeometry.thetaBase, AlgebraicGeometry.thetaFamily,
    AlgebraicGeometry.thetaFamily_natural}
  \uses{def:toBaseTest, def:picEtAffineEquiv, def:PicEtAff_unit, def:relPic, def:picEtMap,
    thm:picEtMap_functor_laws}
  \leanok
  For a \v Cech class \(L_0\) on \(C_k\), let
  \(\theta_{\mathrm{base}} \in \mathrm{picEt}(C, \Spec k)\) be the affine-comparison preimage
  of the plus unit of \(\pi(L_0)\), and for every test \(T\) set
  \[
    \theta_T \;:=\; (\text{canonical } T \to \Spec k)^{*}\,\theta_{\mathrm{base}}
      \;\in\; \mathrm{picEt}(C,T).
  \]
  The family is natural: \(f^{*}\theta_T = \theta_{T'}\) for every \(f \colon T' \to T\) —
  \(\theta\) pulls back to \(\theta\), so twisting by \(\theta_T^{m}\) is uniform in the
  test.
\end{definition}
\begin{proof}
  \leanok
  Naturality: \(f^{*}\theta_T\) is the pullback of \(\theta_{\mathrm{base}}\) along the
  composite \(f \circ (\text{canonical})\), which is the canonical map of \(T'\)
  (Definition~\ref{def:toBaseTest}); conclude by functoriality of restriction
  (Theorem~\ref{thm:picEtMap_functor_laws}).
\end{proof}

\begin{theorem}[The degree of the \(\theta\)-family at every field point]
  \label{thm:degAt_thetaFamily}
  \lean{AlgebraicGeometry.thetaFamily_overSpec_affineEquiv,
    AlgebraicGeometry.degAt_thetaFamily, AlgebraicGeometry.degAt_thetaFamily_pow}
  \uses{def:thetaFamily, thm:degAt_baseChange, thm:picEtAffineEquiv_naturality,
    def:PicEtAff_mapAlg, thm:degAt_picEtMap, thm:degAt_pic0_mul_pow, def:toBaseTest,
    def:relPicAlgMap}
  \leanok
  For every test \(T\), every field point \(t \colon \Spec K \to T\) and every \(m \in \N\),
  \[
    \deg_t(\theta_T) = \deg_{\Pic}(L_0) =: d_1,
    \qquad
    \deg_t\bigl(\theta_T^{\,m}\bigr) = m \, d_1 ,
  \]
  a base-field-invariant constant.
\end{theorem}
\begin{proof}
  \leanok
  On an affine test \(\Spec A\), the affine collapse of \(\theta_{\Spec A}\) is the plus unit
  of the base-changed class \(\iota_A^{*}\pi(L_0)\): the canonical map is \(\Spec\iota_A\)
  (Definition~\ref{def:toBaseTest}), the affine comparison intertwines restriction with the
  explicit transport (Theorem~\ref{thm:picEtAffineEquiv_naturality}), and the transport is
  natural on units (Definition~\ref{def:PicEtAff_mapAlg}). Base-field constancy
  (Theorem~\ref{thm:degAt_baseChange}) then reads \(\deg = \deg_{\Pic}(L_0)\) at every field
  point of \(\Spec A\). For a general test \(T\) and field point \(t\), naturality of the
  family (Definition~\ref{def:thetaFamily}) plus functoriality of the degree
  (Theorem~\ref{thm:degAt_picEtMap}) reduce \(\deg_t(\theta_T)\) to the degree of
  \(\theta_{\Spec K}\) at the identity point of \(\Spec K\), covered by the affine case.
  The power law is Theorem~\ref{thm:degAt_pic0_mul_pow}.
\end{proof}

\begin{definition}[The degree-\(d\) layer functor]
  \label{def:picDegLayerFunctor}
  \lean{AlgebraicGeometry.picDegLayer, AlgebraicGeometry.picDegLayerFunctor}
  \uses{def:degAt, def:picEtFunctor, thm:degAt_picEtMap, thm:picEtMap_functor_laws}
  \leanok
  For \(d \in \Z\), the \emph{degree-\(d\) layer}
  \[
    \mathrm{pic}^{d}(C,T) \;:=\;
    \bigl\{\, \lambda \in \mathrm{picEt}(C,T) \;:\; \deg_t(\lambda) = d
      \text{ for every field point } t \,\bigr\},
  \]
  a \emph{set}-valued subfunctor \(\Over(\Spec k)^{\mathrm{op}} \to \mathrm{Set}\) of the
  \'etale Picard functor. For \(d \neq 0\) the layer is a coset of the degree-zero subgroup,
  not a subgroup: it carries no group structure.
\end{definition}
\begin{proof}
  \leanok
  Stability of the degree-\(d\) condition under restriction is functoriality of the degree
  (Theorem~\ref{thm:degAt_picEtMap}); the functor laws are inherited from
  \(\mathrm{picEtFunctor}\) (Theorem~\ref{thm:picEtMap_functor_laws}).
\end{proof}

\begin{theorem}[The multiplication-by-\(\theta^m\) natural isomorphism and the shift of a representation]
  \label{thm:mulThetaPowNatIso}
  \lean{AlgebraicGeometry.mulThetaPowEquiv, AlgebraicGeometry.mulThetaPowNatIso,
    AlgebraicGeometry.representableByOfShift}
  \uses{def:picDegLayerFunctor, def:pic0Functor, thm:degAt_pic0_mul_pow,
    thm:degAt_thetaFamily, def:thetaFamily, lem:degAt_hom}
  \leanok
  For every \(m \in \N\), multiplication by \(\theta_T^{m}\) is a bijection
  \[
    \mathrm{pic}^0(C,T) \;\xrightarrow{\ \sim\ }\; \mathrm{pic}^{m d_1}(C,T),
    \qquad \lambda \mapsto \lambda \cdot \theta_T^{m},
  \]
  natural in \(T\): an isomorphism of set-valued functors from (the underlying-set functor
  of) \(\mathrm{Pic}^0_{C/k}\) onto the degree-\(m d_1\) layer functor. Consequently a
  representation of the shifted layer functor by an object \(J\) transports to a
  representation of \(\mathrm{Pic}^0_{C/k}\) (as a set-valued functor) by \(J\).
\end{theorem}
\begin{proof}
  \leanok
  Forward: \(\deg_t(\lambda\theta_T^m) = m\,\deg_t(\theta_T) = m d_1\) at every field point
  (Theorem~\ref{thm:degAt_pic0_mul_pow}, Theorem~\ref{thm:degAt_thetaFamily}). Backward,
  \(\mu \mapsto \mu \cdot (\theta_T^{m})^{-1}\) lands in degree zero by additivity
  (Lemma~\ref{lem:degAt_hom}); the two maps are mutually inverse since the ambient group is
  commutative. Naturality is naturality of the \(\theta\)-family
  (Definition~\ref{def:thetaFamily}): restriction is a homomorphism carrying
  \(\theta_T^{m}\) to \(\theta_{T'}^{m}\). Transport of a representation along a natural
  isomorphism of set-valued functors is formal.
\end{proof}

\begin{definition}[The pinned \(\Theta\)-class]
  \label{def:thetaCechClass}
  \lean{AlgebraicGeometry.baseCurveObj, AlgebraicGeometry.thetaP1,
    AlgebraicGeometry.isFinite_thetaP1, AlgebraicGeometry.isDominant_thetaP1,
    AlgebraicGeometry.thetaCechClass, AlgebraicGeometry.one_le_classDeg_thetaCechClass}
  \uses{thm:exists_finite_dominant_toP1, thm:baseChangeCurve_bundle, def:fiberTwist,
    thm:classDeg_fiberTwist_one}
  \leanok
  The base-changed curve \(C_k = (C \otimes \Spec k)_{\mathrm{left}}\) is again a curve over
  \(k\) through the second projection (Theorem~\ref{thm:baseChangeCurve_bundle}), so it
  carries a finite dominant morphism \(\pi \colon C_k \to \PP^1\)
  (Theorem~\ref{thm:exists_finite_dominant_toP1}). The \emph{pinned \(\Theta\)-class} is the
  unit fiber twist
  \[
    \Theta \;:=\; \Theta_1(\pi) = \mathrm{fiberTwist}(\pi, 1) \in \Pic(C_k),
  \]
  and it satisfies \(1 \le \deg_{\Pic}(\Theta)\). It is the canonical choice of \(L_0\) for
  the \(\theta\)-family; its degree \(d_1 := \deg_{\Pic}(\Theta) \ge 1\) is the shift
  constant.
\end{definition}
\begin{proof}
  \leanok
  Positivity is the \(\Theta\)-positivity theorem
  (Theorem~\ref{thm:classDeg_fiberTwist_one}) applied to the finite dominant \(\pi\) on the
  curve \(C_k\).
\end{proof}

\section{The Zariski sheaf property of the degree-zero functor on the slice}
\label{sec:pic0ZariskiSheaf}

The functor \(\mathrm{picEt}\) satisfies the Zariski sheaf axioms for arbitrary open covers
of arbitrary tests — separation was established as Theorem~\ref{thm:picEt_ext_of_le_cover};
here we add gluing, and the S-lemma making the degree-zero subfunctor a subsheaf.

\begin{definition}[Compatible local data on an open cover]
  \label{def:picEt_LocalData}
  \lean{AlgebraicGeometry.picEt.LocalData, AlgebraicGeometry.picEt.IsGlueValue}
  \uses{def:picEt, def:PicEtAff_mapAlg}
  \leanok
  Let \(T\) be a test object and \((O_i)_{i \in \iota}\) an open cover of
  \(T_{\mathrm{left}}\). \emph{Compatible local data} on the cover is a family assigning to
  every index \(i\) and every affine open \(W \le O_i\) a plus class
  \(v_{i,W} \in \mathrm{PicEtAff}(C, \Gamma(T,W))\), such that
  (\emph{res}) within a member, \(v_{i,W}\) restricts to \(v_{i,W'}\) for \(W' \le W \le O_i\),
  and (\emph{glue}) across members, \(v_{i,W} = v_{j,W}\) whenever \(W \le O_i\) and
  \(W \le O_j\). A plus class \(z\) at an affine open \(W\) is a \emph{glue value} of the
  data when its restriction to every affine sub-open \(W_0 \le W\) contained in some member
  \(O_i\) equals \(v_{i,W_0}\).
\end{definition}

\begin{theorem}[Uniqueness of glue values]
  \label{thm:picEt_glueValue_unique}
  \lean{AlgebraicGeometry.picEt.glueValue_unique}
  \uses{def:picEt_LocalData, thm:exists_basic_subcover, thm:picEt_eq_of_basic_eq}
  \leanok
  If the \(O_i\) cover \(T_{\mathrm{left}}\), then any two glue values of the same data at
  the same affine open agree.
\end{theorem}
\begin{proof}
  \leanok
  Choose a finite family of basic opens of \(W\) covering \(W\), each contained in some
  member (Theorem~\ref{thm:exists_basic_subcover}, with the subordination predicate
  ``contained in some \(O_i\)''). Two glue values restrict, on each such basic open, to the
  same local datum; classes agreeing on a spanning family of basic opens agree
  (Theorem~\ref{thm:picEt_eq_of_basic_eq}).
\end{proof}

\begin{theorem}[Existence of glue values]
  \label{thm:picEt_exists_isGlueValue}
  \lean{AlgebraicGeometry.picEt.exists_isGlueValue}
  \uses{def:picEt_LocalData, thm:PicEtAff_exists_mapAlg_eq_of_compat,
    thm:exists_basic_subcover, thm:picEt_eq_of_basic_eq, def:PicEtAff_mapAlg}
  \leanok
  Compatible local data on an open cover of \(T_{\mathrm{left}}\) has a glue value at every
  affine open of \(T_{\mathrm{left}}\).
\end{theorem}
\begin{proof}
  \leanok
  Fix an affine open \(W\) and choose a finite basic-open refinement \((D(r))_{r \in s}\) of
  \(W\) subordinate to the cover, with \(\sum_{r \in s}(r) = (1)\)
  (Theorem~\ref{thm:exists_basic_subcover}). The local data restricted to the \(D(r)\) is a
  compatible family in the sense of the affine Zariski gluing: on an overlap
  \(D(rr') = D(r) \cap D(r')\) the two restrictions agree by (\emph{res}) within each
  chosen member followed by (\emph{glue}) across the two members. By the affine gluing
  theorem (Theorem~\ref{thm:PicEtAff_exists_mapAlg_eq_of_compat}) there is a plus class
  \(z\) at \(W\) restricting to the data on each \(D(r)\).

  \(z\) is a glue value: given an affine sub-open \(W_0 \le W\) with \(W_0 \le O_i\), refine
  \(W_0\) by basic opens of \(W_0\) each of the form \(D(q) \subseteq D(r)\) for some
  \(r \in s\) (Theorem~\ref{thm:exists_basic_subcover} again). On each such \(D(q)\), the
  restriction of \(z\) computes through \(D(r)\) as the local datum at \(D(q)\) by
  (\emph{res}), and the local datum at \(D(q)\) read through member \(i\) agrees with that
  read through the member of \(r\) by (\emph{glue}). So the restrictions of \(z\) and of
  \(v_{i,W_0}\) to a spanning family of basic opens of \(W_0\) agree, and
  Theorem~\ref{thm:picEt_eq_of_basic_eq} concludes.
\end{proof}

\begin{theorem}[The gluing half of the Zariski sheaf property of \(\mathrm{picEt}\)]
  \label{thm:picEt_existsUnique_glue_of_le_cover}
  \lean{AlgebraicGeometry.picEt.glueValue, AlgebraicGeometry.picEt.glueValue_spec,
    AlgebraicGeometry.picEt.glueValue_eq_of, AlgebraicGeometry.picEt.glueSection,
    AlgebraicGeometry.picEt.glueSection_eq,
    AlgebraicGeometry.picEt.existsUnique_glue_of_le_cover}
  \uses{thm:picEt_glueValue_unique, thm:picEt_exists_isGlueValue, thm:picEt_ext_of_le_cover,
    def:picEt, def:PicEtAff_mapAlg}
  \leanok
  Compatible local data on an open cover of \(T_{\mathrm{left}}\) glues to a \emph{unique}
  section \(s \in \mathrm{picEt}(C,T)\) whose value at every affine open subordinate to a
  member is the local datum there.
\end{theorem}
\begin{proof}
  \leanok
  Take \(s\) to be the family of glue values (existence:
  Theorem~\ref{thm:picEt_exists_isGlueValue}; they are unique by
  Theorem~\ref{thm:picEt_glueValue_unique}). The family is compatible under restriction of
  affine opens — the restriction of the glue value at \(V\) to \(U \le V\) is itself a glue
  value at \(U\), since glue-value restrictions compose — so \(s\) is a section of
  \(\mathrm{picEt}(C,T)\) (Definition~\ref{def:picEt}). At an affine open \(W \le O_i\), the
  glue value restricted along \(W \le W\) is the local datum, so \(s\) extends the data.
  Uniqueness: two such sections agree at every affine open subordinate to a member, hence
  agree by separation (Theorem~\ref{thm:picEt_ext_of_le_cover}).
\end{proof}

\begin{theorem}[Separation of the degree-zero subfunctor]
  \label{thm:pic0Subgroup_ext_of_le_cover}
  \lean{AlgebraicGeometry.pic0Subgroup_ext_of_le_cover}
  \uses{def:pic0Subgroup, thm:picEt_ext_of_le_cover}
  \leanok
  Two degree-zero classes on \(T\) whose values agree at every affine open subordinate to an
  open cover of \(T_{\mathrm{left}}\) are equal.
\end{theorem}
\begin{proof}
  \leanok
  The underlying \(\mathrm{picEt}\) classes agree by separation
  (Theorem~\ref{thm:picEt_ext_of_le_cover}); membership in the subgroup carries no further
  data.
\end{proof}

\begin{theorem}[The S-lemma: degree-zero membership is Zariski-local]
  \label{thm:mem_pic0Subgroup_of_cover}
  \lean{AlgebraicGeometry.mem_pic0Subgroup_of_cover}
  \uses{def:pic0Subgroup, thm:degAt_picEtMap, def:picEtMap}
  \leanok
  Let \((f_i \colon T_i \to T)\) be a family of test morphisms whose left legs are open
  immersions with jointly surjective ranges, and \(\lambda \in \mathrm{picEt}(C,T)\) a class
  whose restriction \(f_i^{*}\lambda\) is degree-zero for every \(i\). Then \(\lambda\) is
  degree-zero. This is what makes the degree-zero subfunctor a \emph{subsheaf}, not merely a
  subfunctor, of the Zariski sheaf \(\mathrm{picEt}\).
\end{theorem}
\begin{proof}
  \leanok
  Let \(t \colon \Spec K \to T\) be a field point. Its underlying space is a single point,
  so its topological image lies in the range of some \(f_i\); as that left leg is an open
  immersion, \(t\) factors through it: \(t = f_i \circ t'\) for a field point \(t'\) of
  \(T_i\) (lift along an open immersion containing the image). Then
  \[
    \deg_t(\lambda) = \deg_{t'}\bigl(f_i^{*}\lambda\bigr) = 0
  \]
  by functoriality of the degree (Theorem~\ref{thm:degAt_picEtMap}) and the hypothesis. As
  \(t\) was arbitrary, \(\lambda \in \mathrm{pic}^0(C,T)\).
\end{proof}

\section{The morphism-form cover bridge}
\label{sec:coverBridge}

The sheaf statements of the previous section speak \emph{topological} covers — opens of
\(T_{\mathrm{left}}\) and data at subordinate affine opens. The big-site packaging of the
next section speaks \emph{morphism-form} covers: families \(f_i \colon T_i \to T\) of test
morphisms with open-immersion left legs carrying sections. This section is the bridge.

\begin{lemma}[The section-ring isomorphism of an open immersion of tests]
  \label{lem:appLEAlgEquiv}
  \lean{AlgebraicGeometry.Over.appLEAlgHom_congr_hom, AlgebraicGeometry.Over.bijective_appLEAlgHom,
    AlgebraicGeometry.Over.appLEAlgEquiv,
    AlgebraicGeometry.Over.appLEAlgHom_comp_appLEAlgEquiv_symm,
    AlgebraicGeometry.PicEtAff.mapAlg_injective}
  \uses{def:PicEtAff_mapAlg}
  \leanok
  Let \(f \colon T' \to T\) be a test morphism whose left leg is an open immersion, and
  \(V \subseteq T_{\mathrm{left}}\) an open contained in its range. Then pullback of sections
  \(\Gamma(T,V) \to \Gamma(T', f^{-1}V)\) is a \(k\)-algebra \emph{isomorphism}. Moreover
  transport of plus classes along any bijective \(k\)-algebra map is injective.
\end{lemma}
\begin{proof}
  \leanok
  An open immersion restricts to an isomorphism from \(f^{-1}V\) onto \(V\) when
  \(V\) lies in the range, and an isomorphism of schemes induces an isomorphism on sections;
  the algebra structures match because \(f\) lies over \(\Spec k\). For the second claim,
  transport along the inverse algebra isomorphism is a two-sided inverse up to the functor
  laws of Definition~\ref{def:PicEtAff_mapAlg}, so the transport is injective.
\end{proof}

\begin{definition}[The evaluation of a morphism-form family into local data]
  \label{def:picEt_coverValue}
  \lean{AlgebraicGeometry.picEt.coverValue, AlgebraicGeometry.picEt.mapAlg_coverValue,
    AlgebraicGeometry.picEt.coverValue_res, AlgebraicGeometry.picEt.overlapTest,
    AlgebraicGeometry.picEt.overlapInclusion, AlgebraicGeometry.picEt.coverValue_glue}
  \uses{lem:appLEAlgEquiv, def:picEt_LocalData, def:picEt, def:picEtMap,
    def:PicEtAff_mapAlg, thm:picEt_mapAlg_appLE_eq}
  \leanok
  Let \((f_i \colon T_i \to T)\) have open-immersion left legs and let
  \(x_i \in \mathrm{picEt}(C, T_i)\) be a family of sections, \emph{compatible} in the
  morphism form: for every pair \(i, j\), every test \(Z\) and every pair of morphisms
  \(g_i \colon Z \to T_i\), \(g_j \colon Z \to T_j\) with \(f_i g_i = f_j g_j\), the two
  restrictions of the family to \(Z\) agree. The \emph{cover value} of the family at an
  affine open \(W\) contained in the range of \(f_i\) is the value of \(x_i\) at the
  preimage affine open \(f_i^{-1}W\), transported back along the section-ring isomorphism
  (Lemma~\ref{lem:appLEAlgEquiv}). The cover values are compatible local data
  (Definition~\ref{def:picEt_LocalData}) on the ranges \(O_i := \mathrm{range}(f_i)\).
\end{definition}
\begin{proof}
  \leanok
  (\emph{res}) Restriction within a member commutes with the section-ring transports and
  with the internal compatibility of the section \(x_i\), by the restriction calculus of the
  vehicle (Theorem~\ref{thm:picEt_mapAlg_appLE_eq}) and injectivity of transport along the
  bijective pullback (Lemma~\ref{lem:appLEAlgEquiv}).

  (\emph{glue}) Fix a shared affine open \(W \le O_i \cap O_j\) and form the mediating test:
  the open subscheme of \(T\) at \(W\), over \(\Spec k\) through the inclusion. The
  inclusion lifts through both members (an open immersion whose range contains \(W\) admits
  a lift of the inclusion of \(W\)), producing \(g_i, g_j\) with
  \(f_i g_i = f_j g_j = (\text{inclusion of } W)\). The compatibility hypothesis identifies
  the two restricted sections on the mediating test; evaluating both at its top affine open
  and cancelling the common (bijective) evaluation map
  (Lemma~\ref{lem:appLEAlgEquiv}) identifies the two cover values.
\end{proof}

\begin{theorem}[The sheaf property of \(\mathrm{picEt}\) in morphism-cover form]
  \label{thm:picEt_existsUnique_of_cover}
  \lean{AlgebraicGeometry.picEt.ext_of_cover, AlgebraicGeometry.picEt.existsUnique_of_cover}
  \uses{def:picEt_coverValue, thm:picEt_existsUnique_glue_of_le_cover,
    thm:picEt_ext_of_le_cover, thm:picEt_glueValue_unique, lem:appLEAlgEquiv}
  \leanok
  Let \((f_i \colon T_i \to T)\) have open-immersion left legs with jointly surjective
  ranges. Then two sections of \(\mathrm{picEt}(C,T)\) agreeing after restriction to every
  member agree; and every compatible family \((x_i)\) as in
  Definition~\ref{def:picEt_coverValue} glues to a unique section \(s\) with
  \(f_i^{*} s = x_i\) for all \(i\).
\end{theorem}
\begin{proof}
  \leanok
  \emph{Separation.} At an affine open subordinate to a member the values of the two
  sections compute through the member's restriction, which agree; conclude by topological
  separation (Theorem~\ref{thm:picEt_ext_of_le_cover}) after cancelling the bijective
  transports (Lemma~\ref{lem:appLEAlgEquiv}).

  \emph{Gluing.} The cover values of the family are compatible local data on the ranges
  (Definition~\ref{def:picEt_coverValue}), which glue to a unique section \(s\)
  (Theorem~\ref{thm:picEt_existsUnique_glue_of_le_cover}). That \(f_i^{*} s = x_i\) is
  checked at every affine open \(U'\) of \(T_i\): the value of \(f_i^{*}s\) there computes
  from the value of \(s\) at the image affine open \(f_i(U')\), which is the cover value,
  i.e.\ the value of \(x_i\) at \(f_i^{-1}f_i(U') \supseteq U'\), and the internal
  compatibility of \(x_i\) restricts it to \(U'\). Uniqueness follows from separation.
\end{proof}

\begin{theorem}[The sheaf property of the degree-zero functor in morphism-cover form]
  \label{thm:pic0Subgroup_existsUnique_of_cover}
  \lean{AlgebraicGeometry.pic0Subgroup_ext_of_cover,
    AlgebraicGeometry.pic0Subgroup_existsUnique_of_cover}
  \uses{thm:picEt_existsUnique_of_cover, thm:mem_pic0Subgroup_of_cover, def:pic0Functor,
    def:pic0Subgroup}
  \leanok
  In the situation of Theorem~\ref{thm:picEt_existsUnique_of_cover}, a compatible family of
  \emph{degree-zero} classes \(x_i \in \mathrm{pic}^0(C, T_i)\) glues to a unique degree-zero
  class \(s \in \mathrm{pic}^0(C,T)\) with \(f_i^{*} s = x_i\); and two degree-zero classes
  agreeing on every member agree.
\end{theorem}
\begin{proof}
  \leanok
  Glue the underlying \(\mathrm{picEt}\) classes
  (Theorem~\ref{thm:picEt_existsUnique_of_cover}); the glued class is degree-zero by the
  S-lemma (Theorem~\ref{thm:mem_pic0Subgroup_of_cover}), since each restriction is. Both
  uniqueness claims reduce to the underlying classes.
\end{proof}

\section{The \texorpdfstring{\(\Sigma\)}{Sigma}-extension and the big-site sheaf}
\label{sec:sigmaExtension}

A presheaf on the slice \(\Over(S)\) extends to a presheaf on the ambient category by
summing over structure morphisms. For \(S = \Spec k\) and the degree-zero Picard functor
this \emph{slice trick} produces the big-site carrier consumed by the local-representability
engine, and a representation of the extension descends to one of the original functor.

\begin{definition}[The canonical slice morphism of an equality]
  \label{def:mkCongr}
  \lean{CategoryTheory.Over.mkCongr, CategoryTheory.Over.mkCongr_left,
    CategoryTheory.Over.mkCongr_rfl, CategoryTheory.Over.mkCongr_comp_mkCongr,
    CategoryTheory.Over.mkCongr_comp_homMk}
  \leanok
  Let \(\mathcal C\) be a category, \(S\) an object, and \(a = b\) two equal morphisms
  \(T \to S\). The identity of \(T\) is a morphism of slice objects
  \((T, a) \to (T, b)\) in \(\Over(S)\), the \emph{canonical morphism of the equality}. It
  satisfies: the canonical morphism of a reflexive equality is the identity; canonical
  morphisms compose to the canonical morphism of the transitive equality; and every slice
  morphism \(g \colon X \to (T, b)\) factors as the canonical morphism of its own
  compatibility equation followed by the slice morphism induced by its underlying map.
\end{definition}
\begin{proof}
  \leanok
  The identity of \(T\) satisfies \(\id_T \circ b = a\) precisely because \(a = b\); the
  three laws are immediate from composition of identities.
\end{proof}

\begin{definition}[The \(\Sigma\)-extension of a slice presheaf]
  \label{def:sigmaExtension}
  \lean{CategoryTheory.Over.sigmaExtensionMap, CategoryTheory.Over.sigmaExtension,
    CategoryTheory.Over.sigmaExtension_obj, CategoryTheory.Over.sigmaExtension_map_mk,
    CategoryTheory.Over.sigmaExtension_map_fst, CategoryTheory.Over.sigmaExtension_ext,
    CategoryTheory.Over.sigmaExtension_snd_eq}
  \uses{def:mkCongr}
  \leanok
  For a presheaf \(F\) on the slice \(\Over(S)\), the \emph{\(\Sigma\)-extension}
  \(\widetilde F\) is the presheaf on the ambient category with
  \[
    \widetilde F(T) \;:=\; \coprod_{a \colon T \to S} F(T, a) ,
  \]
  an element being a pair \(\langle a, \xi\rangle\) of a structure morphism and a fibre
  element. Restriction along \(g \colon T' \to T\) composes on the structure component and
  applies \(F\) of the induced slice morphism on the fibre:
  \(g^{*}\langle a, \xi \rangle = \langle g \circ a,\ F(g)^{*}\xi\rangle\). Two
  \(\Sigma\)-elements over equal structure morphisms are equal iff their fibres correspond
  under \(F\) of the canonical morphism of the equality (Definition~\ref{def:mkCongr}).
\end{definition}
\begin{proof}
  \leanok
  Functoriality: restriction along the identity composes with \(a\) to \(a\), and the
  induced slice morphism is the identity, so \(F\) fixes the fibre. For a composite, the two
  structure components agree by associativity, and the two fibre components correspond under
  \(F\) of the canonical morphism, since the induced slice morphisms compose accordingly —
  the transport calculus of Definition~\ref{def:mkCongr} mediates without any cast. The
  final characterisation of equality of \(\Sigma\)-elements is the elimination rule of the
  coproduct.
\end{proof}

\begin{lemma}[The amalgamation seam and the compatibility descent]
  \label{lem:sigmaExtension_seams}
  \lean{CategoryTheory.Over.sigmaExtension_map_mk_eq_iff,
    CategoryTheory.Over.sigmaExtension_map_left_mk,
    CategoryTheory.Over.map_eq_of_sigmaExtension_map_eq}
  \uses{def:sigmaExtension, def:mkCongr}
  \leanok
  Let \(F\) be a presheaf on \(\Over(S)\) and \(\widetilde F\) its \(\Sigma\)-extension.
  \begin{enumerate}
  \item (\emph{Amalgamation seam}) For \(g \colon T' \to T\), \(a \colon T \to S\),
    \(b \colon T' \to S\) with \(g \circ a = b\), and elements \(s \in F(T,a)\),
    \(y \in F(T',b)\):
    \(g^{*}\langle a, s\rangle = \langle b, y\rangle\) in \(\widetilde F(T')\) iff
    \(s\) restricts to \(y\) along the slice morphism \((T',b) \to (T,a)\) induced by \(g\).
  \item (\emph{Left-leg rule}) For a slice morphism \(g \colon Z \to (T,a)\) and
    \(x \in F(T,a)\): restriction of \(\langle a, x\rangle\) along the underlying map of
    \(g\) is \(\langle Z_{\mathrm{struct}},\, F(g)^{*}x \rangle\), the honest slice
    restriction on the fibre.
  \item (\emph{Compatibility descent}) If two \(\Sigma\)-elements
    \(\langle a, x\rangle, \langle b, y\rangle\) have equal restrictions along the
    underlying maps of a pair of slice morphisms \(g_a \colon Z \to (T,a)\),
    \(g_b \colon Z' = Z \to (T',b)\), then \(F(g_a)^{*}x = F(g_b)^{*}y\).
  \end{enumerate}
\end{lemma}
\begin{proof}
  \leanok
  (i) After substituting the equality \(g \circ a = b\), both sides live over the same
  structure morphism and the characterisation of equal \(\Sigma\)-elements
  (Definition~\ref{def:sigmaExtension}) reduces the claim to the fibres, where the canonical
  morphism of the reflexive equality acts as the identity. (ii) is (i) applied to the
  compatibility equation of \(g\), using that the induced slice morphism of the left leg
  \emph{is} \(g\) (Definition~\ref{def:mkCongr}, factorisation law). (iii) Combine (ii) on
  both sides: both restrictions are \(\Sigma\)-elements over the structure morphism of
  \(Z\), and equality of \(\Sigma\)-elements over one structure morphism gives equality of
  fibres.
\end{proof}

\begin{theorem}[The \(\Sigma\)-descent of a representation]
  \label{thm:representableBy_overSlice}
  \lean{CategoryTheory.Functor.RepresentableBy.overSlice}
  \uses{def:sigmaExtension, lem:sigmaExtension_seams}
  \leanok
  Let \(F\) be a presheaf on \(\Over(S)\) and suppose the \(\Sigma\)-extension
  \(\widetilde F\) is representable by an object \(J\) of the ambient category, with
  universal element \(\langle u_1, u_2 \rangle \in \widetilde F(J)\) (the image of
  \(\id_J\)). Then \(F\) is representable on the slice by \((J, u_1)\), with universal
  correspondence sending a slice morphism \(g \colon X \to (J,u_1)\) to the slice
  restriction \(F(g)^{*} u_2\).
\end{theorem}
\begin{proof}
  \leanok
  \emph{Injectivity.} If \(F(g)^{*}u_2 = F(g')^{*}u_2\) then, by the left-leg rule
  (Lemma~\ref{lem:sigmaExtension_seams}(ii)), the restrictions of the universal element
  along the underlying maps of \(g\) and \(g'\) are the same \(\Sigma\)-element of
  \(\widetilde F(X_{\mathrm{left}})\); by representability of \(\widetilde F\) the
  underlying maps agree, hence \(g = g'\) (slice morphisms are determined by their
  underlying maps).

  \emph{Surjectivity.} Given \(\xi \in F(X)\), the \(\Sigma\)-element
  \(\langle X_{\mathrm{struct}}, \xi\rangle\) corresponds under the representation to a map
  \(h \colon X_{\mathrm{left}} \to J\) with
  \(h^{*}\langle u_1, u_2\rangle = \langle X_{\mathrm{struct}}, \xi\rangle\). Comparing
  structure components, \(h \circ u_1 = X_{\mathrm{struct}}\), so \(h\) underlies a slice
  morphism \(g \colon X \to (J, u_1)\); comparing fibres through the amalgamation seam
  (Lemma~\ref{lem:sigmaExtension_seams}(i)) gives \(F(g)^{*}u_2 = \xi\).

  Compatibility with composition is functoriality of \(F\).
\end{proof}

\begin{definition}[The big-site carrier of the degree-zero functor]
  \label{def:pic0SigmaFunctor}
  \lean{AlgebraicGeometry.pic0TypeFunctor, AlgebraicGeometry.pic0TypeFunctor_obj,
    AlgebraicGeometry.pic0TypeFunctor_map_apply, AlgebraicGeometry.pic0SigmaFunctor}
  \uses{def:pic0Functor, def:sigmaExtension}
  \leanok
  Write \(\mathrm{pic}^0_{\mathrm{Set}}(C)\) for the set-valued functor underlying the
  degree-zero relative Picard functor (Definition~\ref{def:pic0Functor}). Its
  \(\Sigma\)-extension along the slice \(\Over(\Spec k)\),
  \[
    T \;\longmapsto\; \coprod_{a \colon T \to \Spec k} \mathrm{pic}^0\bigl(C, (T,a)\bigr),
    \qquad T \in \mathrm{Sch},
  \]
  is a presheaf of sets on the category of schemes — the big-site carrier of the slice
  trick.
\end{definition}

\begin{theorem}[The big-site Zariski sheaf certificate]
  \label{thm:pic0SigmaFunctor_isSheaf}
  \lean{AlgebraicGeometry.pic0SigmaFunctor_isSheaf, AlgebraicGeometry.pic0SigmaSheaf}
  \uses{def:pic0SigmaFunctor, thm:pic0Subgroup_existsUnique_of_cover,
    lem:sigmaExtension_seams, def:sigmaExtension}
  \leanok
  The \(\Sigma\)-extension of the degree-zero Picard functor is a sheaf for the big Zariski
  topology on schemes.
\end{theorem}
\begin{proof}
  \leanok
  The Zariski pretopology is generated by open covers and is stable under base change, so
  the sheaf condition reduces to elementwise unique amalgamation over an honest open cover
  \((\iota_i \colon U_i \to Y)\) carrying a compatible family
  \(x_i = \langle a_i, \xi_i \rangle\) of \(\Sigma\)-elements.

  \emph{Structure components.} Compatibility on pullbacks forces the \(a_i\) to agree on
  overlaps, so they glue to a unique \(a_Y \colon Y \to \Spec k\) with
  \(\iota_i \circ a_Y = a_i\) (gluing of scheme morphisms along an open cover).

  \emph{Fibre components.} The cover members induce slice morphisms
  \((U_i, a_i) \to (Y, a_Y)\) with open-immersion left legs and jointly surjective ranges.
  The fibres \(\xi_i\) are a compatible family on this slice cover: by the compatibility
  descent (Lemma~\ref{lem:sigmaExtension_seams}(iii)), the \(\Sigma\)-level compatibility of
  the \(x_i\) descends to slice-level compatibility of the \(\xi_i\). By the morphism-form
  sheaf property of the degree-zero functor
  (Theorem~\ref{thm:pic0Subgroup_existsUnique_of_cover}) the \(\xi_i\) glue to a unique
  degree-zero class \(s\) on \((Y, a_Y)\) restricting to each.

  \emph{Stitching.} The \(\Sigma\)-element \(\langle a_Y, s\rangle\) restricts to each
  \(x_i\) by the amalgamation seam (Lemma~\ref{lem:sigmaExtension_seams}(i)). Uniqueness:
  the structure component of any amalgamation is determined by gluing of morphisms, and its
  fibre by the separation half of
  Theorem~\ref{thm:pic0Subgroup_existsUnique_of_cover}, again through the seam.
\end{proof}

\begin{definition}[Local representability descends to the slice]
  \label{def:pic0RepresentableByOfCharts}
  \lean{AlgebraicGeometry.pic0RepresentableByOfCharts}
  \uses{thm:pic0SigmaFunctor_isSheaf, thm:representableBy_overSlice, def:pic0SigmaFunctor}
  \leanok
  Suppose given a family of schemes \(X_i\) with maps
  \(f_i \colon \mathrm{yoneda}(X_i) \to \widetilde{\mathrm{pic}^0}(C)\) of big-site sheaves
  which are relatively representable open immersions, jointly Zariski-locally surjective.
  Then the local-representability theorem glues the \(X_i\) into a scheme \(J\)
  representing the \(\Sigma\)-extension, and by \(\Sigma\)-descent
  (Theorem~\ref{thm:representableBy_overSlice}) the set-valued degree-zero Picard functor is
  representable on the slice by \(J\) placed over \(\Spec k\) via the structure component of
  the universal element.
\end{definition}
\begin{proof}
  \leanok
  The local-representability theorem for Zariski sheaves on schemes (mathlib's
  01JJ engine) applies to the sheaf of Theorem~\ref{thm:pic0SigmaFunctor_isSheaf} and the
  given chart family, producing a representation of the \(\Sigma\)-extension by the glued
  scheme; compose with Theorem~\ref{thm:representableBy_overSlice}.
\end{proof}

\section{The Abel element}
\label{sec:abelElement}

For a rational point \(P\) of the curve, the class of the diagonal minus the constant graph
is a degree-zero family on the test \(T = C\) — the element whose image under the universal
correspondence of the representation is the Abel map.

\begin{theorem}[The unit seam at arbitrary tests]
  \label{thm:degAt_relPicToPicEt}
  \lean{AlgebraicGeometry.degAt_relPicToPicEt}
  \uses{def:degAt, thm:picEtMap_relPicToPicEt, thm:picEtAffineEquiv_relPicToPicEt,
    thm:degAff_unit, def:relPicToPicEt, def:relPicMap}
  \leanok
  For a test object \(T\), a relative Picard class \(z \in \mathrm{relPic}(C,T)\) and a
  field point \(t \colon \Spec K \to T\), the degree at \(t\) of the unit image of \(z\) is
  the relative degree of the restriction:
  \[
    \deg_t\bigl(\mathrm{relPicToPicEt}(z)\bigr) = \mathrm{relPicDeg}_K\bigl(t^{*} z\bigr).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Naturality of the unit (Theorem~\ref{thm:picEtMap_relPicToPicEt}) collapses the
  restriction along \(t\) to the unit image of \(t^{*}z\) over \(\Spec K\); affine
  consistency (Theorem~\ref{thm:picEtAffineEquiv_relPicToPicEt}) identifies its affine
  collapse with the plus unit of \(t^{*}z\); the unit normalization of the degree
  (Theorem~\ref{thm:degAff_unit}) reads \(\mathrm{relPicDeg}_K\).
\end{proof}

\begin{definition}[The Abel \v Cech class]
  \label{def:abelCechClass}
  \lean{AlgebraicGeometry.abelCechClass, AlgebraicGeometry.abelPicEt}
  \uses{def:graphLocalEquations, def:relPicToPicEt, def:relPic}
  \leanok
  \source{kleiman-picard, abelian-varieties:page-0107}
  Let \(P \colon \mathbf{1} \to C\) be a rational point of the curve (a morphism from the
  unit test). The \emph{Abel \v Cech class} on the test \(T = C\) is
  \[
    \mathcal A_P \;:=\; \struct{C \otimes C}(\Delta) \cdot \struct{C \otimes C}(P \times C)^{-1}
      \;\in\; \Pic(C \otimes C),
  \]
  the graph class of the identity \(\id_C\) (the diagonal) times the inverse graph class of
  the constant point \(C \to \mathbf 1 \xrightarrow{P} C\) — both factors through the graph
  divisor of Definition~\ref{def:graphLocalEquations}, so one degree certificate serves
  both. The \emph{Abel class} \(\alpha_P \in \mathrm{picEt}(C, C)\) is the unit image of its
  relative class.
\end{definition}

\begin{theorem}[The functor-point formula, \v Cech level]
  \label{thm:cechPicMap_abelCechClass}
  \lean{AlgebraicGeometry.cechPicMap_abelCechClass}
  \uses{def:abelCechClass, thm:graphLocalEquations_base_change}
  \leanok
  For any test \(T\) and any point \(f \colon T \to C\), the pullback of the Abel \v Cech
  class along \(C \lhd f\) is the graph-minus-constant-graph class of \(f\):
  \[
    (C \lhd f)^{*} \mathcal A_P
      = \struct{C \otimes T}(\Gamma_f)\cdot\struct{C \otimes T}(\Gamma_{P_T})^{-1},
  \]
  where \(P_T \colon T \to \mathbf 1 \xrightarrow{P} C\) is the constant point of \(T\).
\end{theorem}
\begin{proof}
  \leanok
  Base change of the graph class (Theorem~\ref{thm:graphLocalEquations_base_change}) sends
  \(\struct{}(\Gamma_{\id_C})\) to \(\struct{}(\Gamma_{f \circ \id}) = \struct{}(\Gamma_f)\)
  and \(\struct{}(\Gamma_{P_C})\) to \(\struct{}(\Gamma_{f \circ P_C})\); and
  \(f \circ P_C = P_T\) by terminality of the unit test (both factor through
  \(\mathbf 1\)). Pullback is a homomorphism, so the product formula follows.
\end{proof}

\begin{theorem}[The degree-zero certificate of the Abel class]
  \label{thm:degAt_abelPicEt}
  \lean{AlgebraicGeometry.degAt_abelPicEt}
  \uses{thm:degAt_relPicToPicEt, thm:cechPicMap_abelCechClass, thm:classDeg_graphPicClass,
    def:relPicMap, def:relPicDeg, lem:degAt_hom}
  \leanok
  At every field point \(t \colon \Spec K \to C\), the Abel class has degree zero:
  \(\deg_t(\alpha_P) = 0\). The certificate is a proved equality at every point — no
  choice is involved.
\end{theorem}
\begin{proof}
  \leanok
  By the unit seam (Theorem~\ref{thm:degAt_relPicToPicEt}) the degree is
  \(\mathrm{relPicDeg}_K\) of the restriction of the relative Abel class along \(t\), which
  the relative degree reads as \(\deg_{\Pic}\) of the fibre \v Cech class
  (Definition~\ref{def:relPicDeg} on the projected representative,
  Definition~\ref{def:relPicMap}). By the functor-point formula
  (Theorem~\ref{thm:cechPicMap_abelCechClass}) at \(f := t\), the fibre class is
  \(\struct{}(\Gamma_t) \cdot \struct{}(\Gamma_{P_{\Spec K}})^{-1}\) — the ratio of two
  graph classes of \(K\)-points. Each has degree one by the degree-one certificate
  (Theorem~\ref{thm:classDeg_graphPicClass}), so the degree is \(1 - 1 = 0\).
\end{proof}

\begin{definition}[The Abel element]
  \label{def:abelElement}
  \lean{AlgebraicGeometry.abelElement, AlgebraicGeometry.abelElement_coe}
  \uses{def:pic0Subgroup, thm:degAt_abelPicEt, def:abelCechClass}
  \leanok
  \source{kleiman-picard, abelian-varieties:page-0107}
  The \emph{Abel element} is the Abel class as an element of the degree-zero subgroup,
  \[
    \alpha_P \in \mathrm{pic}^0(C, C),
  \]
  membership being the certificate of Theorem~\ref{thm:degAt_abelPicEt}. On points it is the
  family \(t \mapsto [\,\Gamma_t - \Gamma_P\,]\), the divisor-class form \(t \mapsto [t - P]\)
  of the Abel map with base point \(P\).
\end{definition}

\begin{theorem}[The functor-point formula of the Abel element]
  \label{thm:abelElement_map}
  \lean{AlgebraicGeometry.abelPicEt_map, AlgebraicGeometry.abelElement_map}
  \uses{def:abelElement, thm:picEtMap_relPicToPicEt, thm:cechPicMap_abelCechClass,
    def:pic0Functor, def:relPicMap}
  \leanok
  For any point \(f \colon T \to C\), the restriction of the Abel element along \(f\) is the
  unit image of the graph-minus-constant-graph class of \(f\):
  \[
    f^{*}\alpha_P = \mathrm{relPicToPicEt}\Bigl(\pi\bigl(
      \struct{C \otimes T}(\Gamma_f)\cdot\struct{C\otimes T}(\Gamma_{P_T})^{-1}\bigr)\Bigr)
    \quad\text{in } \mathrm{pic}^0(C,T).
  \]
\end{theorem}
\begin{proof}
  \leanok
  Naturality of the unit (Theorem~\ref{thm:picEtMap_relPicToPicEt}) commutes the restriction
  into the relative class, where it is the projection of the pullback of the Abel \v Cech
  class (Definition~\ref{def:relPicMap}); conclude by the \v Cech-level functor-point
  formula (Theorem~\ref{thm:cechPicMap_abelCechClass}).
\end{proof}

\begin{theorem}[The pointing law]
  \label{thm:abelElement_map_point}
  \lean{AlgebraicGeometry.abelElement_map_point}
  \uses{thm:abelElement_map, def:pic0Functor}
  \leanok
  Restriction of the Abel element along the rational point \(P\) itself is trivial:
  \[
    P^{*} \alpha_P = 1 \quad\text{in } \mathrm{pic}^0(C, \mathbf 1).
  \]
\end{theorem}
\begin{proof}
  \leanok
  By the functor-point formula (Theorem~\ref{thm:abelElement_map}) at \(f := P\), the
  restricted class is the unit image of
  \(\struct{}(\Gamma_P)\cdot\struct{}(\Gamma_{P_{\mathbf 1}})^{-1}\) on
  \(C \otimes \mathbf 1\). The constant point of the unit test is \(P\) itself
  (terminality: the canonical map \(\mathbf 1 \to \mathbf 1\) is the identity), so the two
  graph factors coincide and the \v Cech class is already \(1\); its unit image is \(1\).
\end{proof}

\label{chap:Jacobian}

Throughout this chapter \(k\) is a field and \(C\) is the challenge curve: a
scheme over \(k\), proper, smooth of relative dimension one, and geometrically
irreducible. The degree-zero relative Picard functor
\(\Pic^0_{C/k} : \Over(\Spec k)^{\op} \to \mathrm{CommGrp}\) was constructed in
\ref{def:pic0Functor}. This chapter introduces the \emph{Jacobian datum} --- a
representing object for \(\Pic^0_{C/k}\) together with the certificates its
construction provides --- and develops what follows formally from it: the
group structure and universal property of the representing object, its
uniqueness up to canonical isomorphism, separatedness (every group scheme over
a field is separated), the homogeneity supplied by translations, and, given a
proper irreducible \emph{Abel source} mapping onto it, properness and geometric
irreducibility.

\section{The representability datum}
\label{sec:jacobian_datum}

\begin{definition}[Jacobian datum]
  \label{def:jacobian_data}
  \lean{AlgebraicGeometry.JacobianData}
  \uses{def:pic0Functor}
  \leanok
  A \emph{Jacobian datum} for \(C\) consists of:
  \begin{enumerate}
    \item a scheme \(J\) over \(k\);
    \item a representation of the degree-zero relative Picard functor by
      \(J\): a family of bijections
      \(\Hom_{\Over(\Spec k)}(T, J) \cong \mathrm{pic}^0(C, T)\), natural in
      the test object \(T\);
    \item the certificate that the structure morphism of \(J\) is locally of
      finite type;
    \item the certificate that the structure morphism of \(J\) is
      quasi-compact.
  \end{enumerate}
  The two certificates come from the construction of the representing object
  and are carried as part of the datum rather than re-derived.
\end{definition}

\begin{definition}[The group structure of the representing object]
  \label{def:jacobian_data_grp}
  \lean{AlgebraicGeometry.JacobianData.grpObj}
  \uses{def:jacobian_data, def:pic0Functor}
  \leanok
  For a Jacobian datum \(d\) with representing object \(J\), the scheme \(J\)
  is a group object of \(\Over(\Spec k)\), with multiplication, unit and
  inversion induced by the commutative-group structure of
  \(\mathrm{pic}^0(C, -)\) through the representation.
\end{definition}
\begin{proof}
  \leanok
  Transport the group structure across the natural bijections of
  \ref{def:jacobian_data}: each \(\Hom(T, J)\) becomes a group, naturally in
  \(T\) --- precomposition with any \(T' \to T\) is a group homomorphism
  because the restriction maps of \(\Pic^0_{C/k}\) are. By the Yoneda lemma the
  natural transformation
  \(\Hom(-, J) \times \Hom(-, J) \to \Hom(-, J)\) given by the pointwise
  products is induced by a unique morphism \(\mu : J \otimes J \to J\), and
  similarly for the unit \(1 \to J\) and the inversion \(J \to J\); the group
  axioms hold for these morphisms because they hold pointwise on
  \(T\)-points.
\end{proof}

\begin{lemma}[The universal property, consumer form]
  \label{lem:jacobian_data_homEquiv}
  \lean{AlgebraicGeometry.JacobianData.homEquiv,
    AlgebraicGeometry.JacobianData.homEquiv_comp}
  \uses{def:jacobian_data, def:pic0Functor}
  \leanok
  Let \(d\) be a Jacobian datum with representing object \(J\). For every test
  object \(T\) there is a bijection
  \[
    \theta_T : \Hom_{\Over(\Spec k)}(T, J) \;\cong\; \mathrm{pic}^0(C, T),
  \]
  natural against restriction: for \(f : T' \to T\) and \(g : T \to J\),
  \[
    \theta_{T'}(g \circ f) \;=\; f^*\bigl(\theta_T(g)\bigr),
  \]
  where \(f^*\) is the restriction map of \(\Pic^0_{C/k}\)
  (\ref{def:pic0Functor}).
\end{lemma}
\begin{proof}
  \leanok
  This is the representation carried by the datum (\ref{def:jacobian_data}),
  with its naturality read element-wise.
\end{proof}

\begin{definition}[Uniqueness of the representing object up to canonical
    isomorphism]
  \label{def:jacobian_data_unique}
  \lean{AlgebraicGeometry.JacobianData.uniqueUpToIso,
    AlgebraicGeometry.JacobianData.homEquiv_uniqueUpToIso_hom}
  \uses{def:jacobian_data, lem:jacobian_data_homEquiv}
  \leanok
  Let \(d\), \(d'\) be two Jacobian data for the same curve, with representing
  objects \(J\), \(J'\) and universal bijections \(\theta\), \(\theta'\). There
  is a canonical isomorphism \(\sigma : J \cong J'\) in \(\Over(\Spec k)\),
  characterised by the intertwining property
  \[
    \theta'_T\bigl(\sigma \circ f\bigr) = \theta_T(f)
    \qquad \text{for every } f : T \to J .
  \]
\end{definition}
\begin{proof}
  \leanok
  Let \(u = \theta_J(\mathrm{id}_J) \in \mathrm{pic}^0(C, J)\) be the universal
  class of \(d\), and set \(\sigma = \theta'^{-1}_J(u) : J \to J'\).
  For \(f : T \to J\), naturality of \(\theta'\)
  (\ref{lem:jacobian_data_homEquiv}) gives
  \[
    \theta'_T(\sigma \circ f) = f^*\bigl(\theta'_J(\sigma)\bigr)
    = f^*(u) = f^*\bigl(\theta_J(\mathrm{id}_J)\bigr)
    = \theta_T(\mathrm{id}_J \circ f) = \theta_T(f).
  \]
  Symmetrically there is \(\sigma' = \theta^{-1}_{J'}(u') : J' \to J\), where
  \(u' = \theta'_{J'}(\mathrm{id}_{J'})\), with
  \(\theta_T(\sigma' \circ f') = \theta'_T(f')\) for every \(f' : T \to J'\).
  The two composites are identities: e.g.\
  \(\theta_J(\sigma' \circ \sigma) = \theta'_J(\sigma) = u =
  \theta_J(\mathrm{id}_J)\), and \(\theta_J\) is injective, so
  \(\sigma' \circ \sigma = \mathrm{id}_J\); likewise the other composite.
  Uniqueness of an isomorphism with the intertwining property follows from
  injectivity of \(\theta'\) at \(T = J\).
\end{proof}

\section{Group schemes are separated}
\label{sec:group_separated}

\begin{theorem}[The diagonal of a group object is a pullback of the unit]
  \label{thm:grp_diagonal_pullback}
  \lean{CategoryTheory.GrpObj.isPullback_diagonal}
  \uses{def:grp_diff}
  \leanok
  \source{kleiman-picard}
  Let \(G\) be a group object in a cartesian monoidal category, with unit
  \(e : 1 \to G\) and difference morphism
  \(\delta = \mathrm{pr}_1 \cdot \mathrm{pr}_2^{-1} : G \otimes G \to G\)
  (\ref{def:grp_diff}). Then the square
  \[
    \begin{array}{ccc}
      G & \xrightarrow{\ \Delta = \langle \mathrm{id}, \mathrm{id}\rangle\ }
        & G \otimes G \\
      \downarrow & & \downarrow \delta \\
      1 & \xrightarrow{\ e\ } & G
    \end{array}
  \]
  is a pullback: the diagonal of \(G\) is the base change of the unit along
  the difference map.
\end{theorem}
\begin{proof}
  \leanok
  \emph{Commutativity.} In the hom-group \(\Hom(G, G)\):
  \(\delta \circ \Delta = (\mathrm{pr}_1 \circ \Delta)\cdot(\mathrm{pr}_2
  \circ \Delta)^{-1} = \mathrm{id} \cdot \mathrm{id}^{-1} = 1\), the constant
  unit, which is the composite through the terminal object.

  \emph{Universality.} Let \(s_1 : T \to 1\) and \(s_2 : T \to G \otimes G\)
  satisfy \(\delta \circ s_2 = e \circ s_1\). The right-hand side is the unit
  of \(\Hom(T, G)\), and the left-hand side is
  \((\mathrm{pr}_1 \circ s_2)\cdot(\mathrm{pr}_2 \circ s_2)^{-1}\); hence
  \(\mathrm{pr}_1 \circ s_2 = \mathrm{pr}_2 \circ s_2 =: h\). The morphism
  \(h : T \to G\) satisfies \(\Delta \circ h = \langle h, h \rangle = s_2\)
  (equal components) and \(t_G \circ h = s_1\) (morphisms to the terminal
  object agree). For uniqueness, any \(m\) with \(\Delta \circ m = s_2\) has
  \(m = \mathrm{pr}_1 \circ \Delta \circ m = \mathrm{pr}_1 \circ s_2 = h\).
\end{proof}

\begin{theorem}[A group scheme with closed unit section is separated]
  \label{thm:separated_of_closed_unit}
  \lean{AlgebraicGeometry.isSeparated_of_isClosedImmersion_one}
  \uses{thm:grp_diagonal_pullback}
  \leanok
  \source{kleiman-picard}
  Let \(S\) be a scheme and \(G\) a group object of \(\Over(S)\). If the unit
  section \(e : S \to G\) is a closed immersion of schemes, then the structure
  morphism \(G \to S\) is separated. No finiteness hypothesis is required.
\end{theorem}
\begin{proof}
  \leanok
  Apply the forgetful functor \(\Over(S) \to \mathrm{Sch}\) to the pullback
  square of \ref{thm:grp_diagonal_pullback}; it preserves the square and its
  pullback property (fibre products in \(\Over(S)\) are computed on underlying
  schemes), and the monoidal product \(G \otimes G\) becomes the fibre product
  \(G \times_S G\) with \(\Delta\) the diagonal morphism of \(G\) over \(S\).
  Thus the diagonal \(\Delta_{G/S}\) is a base change of the closed immersion
  \(e\), and closed immersions are stable under base change; a morphism whose
  diagonal is a closed immersion is separated.
\end{proof}

\begin{theorem}[Group schemes over a field are separated]
  \label{thm:group_scheme_separated}
  \lean{AlgebraicGeometry.isSeparated_of_grpObj}
  \uses{thm:separated_of_closed_unit}
  \leanok
  \source{kleiman-picard}
  Every group scheme \(G\) over a field \(K\) is separated over \(K\).
\end{theorem}
\begin{proof}
  \leanok
  The unit section \(e : \Spec K \to G\) of a group scheme over a field is a
  closed immersion: its image is a \(K\)-rational point, and a section of a
  \(K\)-scheme at a rational point is a closed immersion. Apply
  \ref{thm:separated_of_closed_unit}.
\end{proof}

\begin{corollary}[The representing object of a Jacobian datum is separated]
  \label{cor:jacobianData_separated}
  \lean{AlgebraicGeometry.JacobianData.isSeparated}
  \uses{def:jacobian_data_grp, thm:group_scheme_separated}
  \leanok
  For every Jacobian datum \(d\) with representing object \(J\), the structure
  morphism of \(J\) is separated.
\end{corollary}
\begin{proof}
  \leanok
  \(J\) is a group scheme over \(k\) (\ref{def:jacobian_data_grp}); apply
  \ref{thm:group_scheme_separated}.
\end{proof}

\section{Translations}
\label{sec:translations}

Group schemes are homogeneous: right translation by a point is an
automorphism, so a point-local property holding at one rational point spreads
to every rational point. This section provides the translation isomorphisms
and the transport statements, first for a group object \(G\) in a cartesian
monoidal category \(\mathcal C\) (with the hom-group calculus of
\ref{sec:difference_map}), then on underlying schemes. For a point
\(g : 1 \to G\), the \emph{right translation} \(\rho_g : G \cong G\) is the
isomorphism \(\rho_g = \mu \circ \langle \mathrm{id}_G,\ g \circ t_G\rangle\)
(``multiply on the right by \(g\)''), with inverse the right translation by
\(g^{-1}\).

\begin{lemma}[Composition with a right translation]
  \label{lem:comp_mulRight}
  \lean{CategoryTheory.GrpObj.comp_mulRight_hom,
    CategoryTheory.GrpObj.comp_mulRight_inv}
  \leanok
  For morphisms \(f : X \to G\) and points \(g : 1 \to G\) of a group object
  \(G\),
  \[
    \rho_g \circ f = f \cdot \hat g
    \qquad\text{and}\qquad
    \rho_g^{-1} \circ f = f \cdot \hat g^{-1},
  \]
  computed in the hom-group \(\Hom(X, G)\), where
  \(\hat g = g \circ t_X\) is the constant morphism at \(g\).
\end{lemma}
\begin{proof}
  \leanok
  Unfolding \(\rho_g\): \(\rho_g \circ f = \mu \circ \langle \mathrm{id},\ g
  \circ t_G\rangle \circ f = \mu \circ \langle f,\ g \circ t_X\rangle
  = f \cdot \hat g\), using \(t_G \circ f = t_X\) (morphisms into the terminal
  object). The second identity follows from the first applied to
  \(\rho_g^{-1} = \rho_{g^{-1}}\), or directly: unfolding the inverse
  translation gives \(\mu \circ \langle f,\ \iota \circ g \circ t_X\rangle =
  f \cdot \hat g^{-1}\).
\end{proof}

\begin{definition}[The translation carrying one point to another]
  \label{def:point_translation}
  \lean{CategoryTheory.GrpObj.pointTranslation}
  \leanok
  \source{kleiman-picard}
  For points \(x, y : 1 \to G\) of a group object \(G\), the
  \emph{point translation}
  \[
    \tau_{x,y} \;=\; \rho_y \circ \rho_x^{-1} \;:\; G \cong G
  \]
  is the automorphism ``multiply on the right by \(x^{-1} y\)''.
\end{definition}

\begin{lemma}[The point translation carries \(x\) to \(y\)]
  \label{lem:point_translation_apply}
  \lean{CategoryTheory.GrpObj.comp_pointTranslation_hom}
  \uses{def:point_translation, lem:comp_mulRight}
  \leanok
  For points \(x, y : 1 \to G\),
  \(\tau_{x,y} \circ x = y\).
\end{lemma}
\begin{proof}
  \leanok
  By \ref{lem:comp_mulRight}, computed in the hom-group \(\Hom(1, G)\), where
  the constant \(\hat g\) at a point \(g\) is \(g\) itself (\(t_1 =
  \mathrm{id}\)):
  \(\rho_x^{-1} \circ x = x \cdot x^{-1} = 1\), and then
  \(\rho_y \circ (\rho_x^{-1} \circ x) = 1 \cdot y = y\).
\end{proof}

\begin{definition}[Translations of the underlying scheme]
  \label{def:point_translation_iso}
  \lean{CategoryTheory.GrpObj.pointTranslationIso,
    CategoryTheory.GrpObj.pointTranslationIso_hom,
    CategoryTheory.GrpObj.pointTranslationIso_inv}
  \uses{def:point_translation}
  \leanok
  Let \(S\) be a scheme, \(G\) a group scheme over \(S\), and \(x, y\) two
  sections \(S \to G\). The \emph{translation isomorphism}
  \(\tau_{x,y} : G \cong G\) of underlying schemes is the image of the point
  translation \ref{def:point_translation} under the forgetful functor from
  schemes over \(S\) to schemes; its inverse is the image of the inverse point
  translation.
\end{definition}

\begin{lemma}[Translations commute with the structure morphism]
  \label{lem:point_translation_iso_over}
  \lean{CategoryTheory.GrpObj.pointTranslationIso_hom_comp}
  \uses{def:point_translation_iso}
  \leanok
  In the situation of \ref{def:point_translation_iso}, composing
  \(\tau_{x,y}\) with the structure morphism \(G \to S\) gives the structure
  morphism: \(\tau_{x,y}\) is an automorphism of \(G\) over \(S\).
\end{lemma}
\begin{proof}
  \leanok
  The point translation is a morphism in the category of schemes over \(S\),
  and the forgetful functor remembers the commutation with the structure
  morphisms.
\end{proof}

\begin{lemma}[Translations act on points as prescribed]
  \label{lem:point_translation_iso_points}
  \lean{CategoryTheory.GrpObj.pointTranslationIso_hom_apply}
  \uses{def:point_translation_iso, lem:point_translation_apply}
  \leanok
  In the situation of \ref{def:point_translation_iso}, for every point
  \(s \in S\),
  \[
    \tau_{x,y}\bigl(x(s)\bigr) = y(s)
  \]
  on underlying topological spaces.
\end{lemma}
\begin{proof}
  \leanok
  The equation \(\tau_{x,y} \circ x = y\) of \ref{lem:point_translation_apply}
  holds in \(\Over(S)\), hence on underlying schemes, hence on underlying
  topological spaces; evaluate at \(s\).
\end{proof}

\begin{lemma}[Transport of the smooth locus]
  \label{lem:smooth_locus_transport}
  \lean{AlgebraicGeometry.mem_smoothLocus_iff_of_comp_eq}
  \leanok
  Let \(f : X \to S\) be a morphism locally of finite presentation and
  \(e : X \to X\) an open immersion with \(f \circ e = f\). Then for every
  \(z \in X\),
  \[
    e(z) \in \operatorname{SmoothLocus}(f)
    \iff
    z \in \operatorname{SmoothLocus}(f).
  \]
\end{lemma}
\begin{proof}
  \leanok
  Smoothness of \(f\) at a point is local on \(X\): composing with the open
  immersion \(e\), the morphism \(f\) is smooth at \(e(z)\) if and only if
  \(f \circ e\) is smooth at \(z\) (an open immersion is smooth, identifies
  local rings, and smoothness is a stalk-local property of the morphism). Now
  rewrite \(f \circ e = f\).
\end{proof}

\begin{lemma}[Transport of stalk reducedness]
  \label{lem:stalk_reduced_transport}
  \lean{AlgebraicGeometry.isReduced_stalk_iff_of_isOpenImmersion}
  \leanok
  Let \(e : X \to Y\) be an open immersion of schemes and \(z \in X\). Then
  \(\struct{X,z}\) is reduced if and only if \(\struct{Y, e(z)}\) is reduced.
\end{lemma}
\begin{proof}
  \leanok
  An open immersion induces an isomorphism on stalks, and reducedness is
  invariant under ring isomorphism.
\end{proof}

\begin{lemma}[Transport of irreducibility]
  \label{lem:irreducible_transport}
  \lean{AlgebraicGeometry.isIrreducible_preimage_iff_of_isIso}
  \leanok
  Let \(e : X \to Y\) be an isomorphism of schemes and \(t \subseteq Y\) a
  subset. Then \(e^{-1}(t)\) is irreducible if and only if \(t\) is
  irreducible.
\end{lemma}
\begin{proof}
  \leanok
  An isomorphism of schemes is a homeomorphism of underlying spaces;
  irreducibility is a topological property, preserved and reflected by
  homeomorphisms (the image of an irreducible set under a continuous map is
  irreducible, applied to \(e\) and \(e^{-1}\)).
\end{proof}

\begin{corollary}[Homogeneity of the representing object]
  \label{cor:jacobian_translation}
  \lean{AlgebraicGeometry.JacobianData.pointTranslation,
    AlgebraicGeometry.JacobianData.comp_pointTranslation_hom,
    AlgebraicGeometry.JacobianData.pointTranslationIso,
    AlgebraicGeometry.JacobianData.pointTranslationIso_hom_comp,
    AlgebraicGeometry.JacobianData.pointTranslationIso_hom_apply,
    AlgebraicGeometry.JacobianData.pointTranslationIso_mem_smoothLocus_iff,
    AlgebraicGeometry.JacobianData.isReduced_stalk_pointTranslationIso_iff,
    AlgebraicGeometry.JacobianData.isIrreducible_pointTranslationIso_preimage_iff}
  \uses{def:jacobian_data_grp, def:point_translation,
    lem:point_translation_apply, def:point_translation_iso,
    lem:point_translation_iso_over, lem:point_translation_iso_points,
    lem:smooth_locus_transport, lem:stalk_reduced_transport,
    lem:irreducible_transport}
  \leanok
  Let \(d\) be a Jacobian datum with representing object \(J\), and let
  \(x, y : \Spec k \to J\) be two \(k\)-points. With the group structure of
  \ref{def:jacobian_data_grp}, the translation \(\tau_{x,y}\) is an
  automorphism of \(J\) over \(k\) with \(\tau_{x,y} \circ x = y\); on the
  underlying scheme it commutes with the structure morphism and carries the
  point of \(x\) to the point of \(y\); and it preserves and reflects
  membership in the smooth locus of the structure morphism (when the latter is
  locally of finite presentation), reducedness of stalks, and irreducibility
  of subsets.
\end{corollary}
\begin{proof}
  \leanok
  Instantiate \ref{def:point_translation}--\ref{lem:irreducible_transport} at
  the group scheme \(J\): the translation exists and carries \(x\) to \(y\)
  (\ref{def:point_translation}, \ref{lem:point_translation_apply}); its
  underlying isomorphism commutes with the structure morphism
  (\ref{lem:point_translation_iso_over}) and acts on points as prescribed
  (\ref{lem:point_translation_iso_points}); the three transport lemmas
  (\ref{lem:smooth_locus_transport}, applicable by
  \ref{lem:point_translation_iso_over}; \ref{lem:stalk_reduced_transport};
  \ref{lem:irreducible_transport}) give the invariances.
\end{proof}

\section{The Abel source: properness and geometric irreducibility}
\label{sec:abel_source}

\begin{definition}[Abel source]
  \label{def:abel_source}
  \lean{AlgebraicGeometry.AbelSourceData}
  \uses{def:jacobian_data}
  \leanok
  \source{abelian-varieties:page-0107}
  Let \(d\) be a Jacobian datum with representing object \(J\). An
  \emph{Abel source} for \(d\) consists of:
  \begin{enumerate}
    \item a scheme \(D\) over \(k\);
    \item a certificate that \(D\) is proper over \(k\);
    \item a certificate that \(D\) is geometrically irreducible over \(k\);
    \item an \emph{Abel morphism} \(a : D \to J\) over \(k\);
    \item a certificate that \(a\) is surjective on underlying topological
      spaces.
  \end{enumerate}
  (The intended instance takes \(D\) a proper scheme of effective divisors of
  large degree on \(C\) and \(a\) the Abel map; the results of this section
  are conditional on the interface only.)
\end{definition}

\begin{theorem}[The representing object is universally closed]
  \label{thm:jacobianData_universallyClosed}
  \lean{AlgebraicGeometry.universallyClosed_of_abelSource}
  \uses{def:abel_source, def:jacobian_data}
  \leanok
  \source{abelian-varieties:page-0107}
  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
  morphism of the representing object \(J\) is universally closed.
\end{theorem}
\begin{proof}
  \leanok
  Let \(a : D \to J\) be the Abel morphism. Since \(a\) is a morphism over
  \(k\), the composite of \(a\) with the structure morphism of \(J\) is the
  structure morphism of \(D\), which is universally closed (\(D\) is proper).
  Surjectivity and closedness are stable under base change, so it suffices to
  see: if \(g \circ f\) is universally closed and \(f\) is surjective, then
  \(g\) is universally closed. Indeed, after any base change, for a closed
  subset \(Z\) of the source of the (base-changed) \(g'\),
  \(g'(Z) = (g' \circ f')\bigl(f'^{-1}(Z)\bigr)\) by surjectivity of the
  base-changed \(f'\), and the right-hand side is closed since
  \(g' \circ f' = (g \circ f)'\) is a closed map.
\end{proof}

\begin{theorem}[The representing object is proper]
  \label{thm:jacobianData_proper}
  \lean{AlgebraicGeometry.isProper_of_abelSource}
  \uses{def:abel_source, cor:jacobianData_separated,
    thm:jacobianData_universallyClosed, def:jacobian_data}
  \leanok
  \source{abelian-varieties:page-0107}
  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
  morphism of the representing object \(J\) is proper.
\end{theorem}
\begin{proof}
  \leanok
  Properness is the conjunction of separatedness, universal closedness and
  finite type. Separatedness is \ref{cor:jacobianData_separated}; universal
  closedness is \ref{thm:jacobianData_universallyClosed}; the structure morphism
  is locally of finite type by the datum's certificate
  (\ref{def:jacobian_data}), and quasi-compact because universally closed
  morphisms are quasi-compact; locally of finite type and quasi-compact is
  finite type.
\end{proof}

\begin{theorem}[The representing object is geometrically irreducible]
  \label{thm:jacobianData_geomIrreducible}
  \lean{AlgebraicGeometry.geometricallyIrreducible_of_abelSource}
  \uses{def:abel_source}
  \leanok
  Let \(d\) be a Jacobian datum admitting an Abel source. Then the structure
  morphism of the representing object \(J\) is geometrically irreducible: for
  every field extension \(K/k\), the base change \(J_K\) is irreducible.
\end{theorem}
\begin{proof}
  \leanok
  Fix a field extension \(K/k\) and a fibre product \(Z = J \times_k K\) with
  projections to \(J\) and \(\Spec K\). The base change
  \(D_K = D \times_k K\) is irreducible by the Abel source's certificate. The
  comparison morphism \(D_K \to Z\) induced by the Abel morphism \(a\) is,
  by pasting of pullback squares, a base change of \(a\) along
  \(Z \to J\) (the square with legs \(D_K \to Z \to \Spec K\) over
  \(D \to J \to \Spec k\) decomposes into two pullbacks); surjectivity is
  stable under base change, so \(D_K \to Z\) is surjective. A continuous
  surjective image of an irreducible space is irreducible, so \(Z\) is
  irreducible.
\end{proof}
